/*Table structure for table `inventorytransactiondetail` */

DROP TABLE IF EXISTS `inventorytransactiondetail`;

CREATE TABLE `inventorytransactiondetail` (
  `primary_key` bigint NOT NULL AUTO_INCREMENT,
  `routekey` bigint NOT NULL,
  `detailkey` bigint NOT NULL,
  `transactiontypecode` bigint NOT NULL,
  `itemcode` bigint NOT NULL,
  `quantity` decimal(18,0) DEFAULT '0',
  `requestedqty` bigint NOT NULL,
  `weighted` int DEFAULT '0',
  `itemprice` decimal(18,6) DEFAULT '0.000000',
  `batchdetailkey` decimal(18,0) DEFAULT NULL,
  `itemcaseprice` decimal(18,6) DEFAULT '0.000000',
  `currencycode` bigint DEFAULT '0',
  `record_flag` enum('0','1') DEFAULT '0' COMMENT 'set enum tye 0 -> cloud ,1->tablet',
  `expirydate` date DEFAULT NULL,
  `reasoncode` int DEFAULT NULL,
  PRIMARY KEY (`primary_key`),
  UNIQUE KEY `IX_InventoryTransactionDetail` (`detailkey`,`transactiontypecode`,`itemcode`),
  KEY `IX_InventoryTransactionDetail_1` (`routekey`),
  KEY `IX_InventoryTransactionDetail_2` (`detailkey`),
  KEY `IX_InventoryTransactionDetail_3` (`transactiontypecode`),
  KEY `IX_InventoryTransactionDetail_4` (`itemcode`),
  CONSTRAINT `FK_InventoryTransactionDetail_InventoryTransactionHeader` FOREIGN KEY (`detailkey`) REFERENCES `inventorytransactionheader` (`detailkey`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_InventoryTransactionDetail_ItemMaster` FOREIGN KEY (`itemcode`) REFERENCES `itemmaster` (`actualitemcode`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=12322378 DEFAULT CHARSET=latin1;

