/* Trigger structure for table `importtables` */

DELIMITER $$

/*!50003 DROP TRIGGER*//*!50032 IF EXISTS */ /*!50003 `importtablesdata` */$$

/*!50003 CREATE */ /*!50017 DEFINER = 'root'@'localhost' */ /*!50003 TRIGGER `importtablesdata` AFTER UPDATE ON `importtables` FOR EACH ROW BEGIN
	IF NEW.sman = 1 THEN
	  CALL sp_import_Salesman;	  
	END IF;
	 IF NEW.ware_house = 1 THEN
	 CALL sp_import_WareHouseStock();
	  CALL sp_import_target();
	 END IF;
 	IF NEW.item = 1 THEN
 	  CALL sp_import_ItemMaster();
 	  CALL sp_import_routeitemgroup();
 	END IF;
	/*IF NEW.customer = 1 THEN
	  CALL sp_import_customer; commented bcoz Explicit or implicit commit is not allowed in stored function or trigger.
	 END IF;*/
	IF NEW.outstanding = 1 THEN
	  CALL sp_import_CustomerInvoice;
	END IF;
	IF NEW.route = 1 THEN
	  CALL sp_import_routeitemgroup();
	  CALL sp_import_RouteMaster;
	END IF;	
	IF NEW.customerprice = 1 THEN
		 
	DELETE FROM  pricingdetail1;
	DELETE FROM pricingplanheader1;
	DELETE FROM  customerpricing1;
	DELETE FROM  customerpricingplanheader1;
	CALL sp_import_CustomerPrice;
	END IF;
	
    END */$$


DELIMITER ;

