/* Function  structure for function  `get_month_order` */

/*!50003 DROP FUNCTION IF EXISTS `get_month_order` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `get_month_order`() RETURNS varchar(100) CHARSET latin1
    DETERMINISTIC
BEGIN
		DECLARE start_value INT DEFAULT MONTH(CURRENT_DATE());
		DECLARE end_value INT DEFAULT 12;
		DECLARE str varchar(100);
		
		DROP TEMPORARY TABLE IF EXISTS tmptbl;
		CREATE TEMPORARY TABLE tmptbl(monthno int);
		
		WHILE start_value <= end_value DO
			INSERT INTO tmptbl(monthno)VALUES(start_value);
			SET start_value = start_value + 1;
			
			IF start_value = 13 and MONTH(CURRENT_DATE()) != 1 THEN
				SET start_value = 1;
				set end_value = (MONTH(CURRENT_DATE())-1);
			END IF;
			
		END WHILE; 
		
		SELECT GROUP_CONCAT(monthno) INTO str FROM tmptbl;
		RETURN str;
				
    END */$$
DELIMITER ;

