/* Function  structure for function  `update_advpayment_customer_balance` */

/*!50003 DROP FUNCTION IF EXISTS `update_advpayment_customer_balance` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `update_advpayment_customer_balance`(custid BIGINT(18),bal decimal(18,4)) RETURNS bigint
    DETERMINISTIC
BEGIN
	
	
	select enableadvancepayment into @advpay from customermaster where customercode = custid;
	if @advpay = 1 then 
		update customermaster SET balance = balance+bal WHERE customercode = custid;		
	end if;
	RETURN bal;
END */$$
DELIMITER ;

/* Function  structure for function  `update_bodocseq_route` */

