DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `update_bodocseq_route`(routeid BIGINT(28)) RETURNS bigint
    DETERMINISTIC
BEGIN
	update routemaster SET bodocseq = bodocseq+1 WHERE routecode = routeid;
