/* Procedure structure for procedure `deletetransactiondata_by_date` */

/*!50003 DROP PROCEDURE IF EXISTS  `deletetransactiondata_by_date` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `deletetransactiondata_by_date`(
    IN var_from_date DATE,
    IN var_to_date DATE
)
BEGIN
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        DROP TEMPORARY TABLE IF EXISTS temp_routekeys;
        RESIGNAL;
    END;
    START TRANSACTION;
    DROP TEMPORARY TABLE IF EXISTS temp_routekeys;
    CREATE TEMPORARY TABLE temp_routekeys (
        routekey DECIMAL(28,0) PRIMARY KEY
    );
    INSERT IGNORE INTO temp_routekeys (routekey)
    SELECT DISTINCT routekey
    FROM startendday
    WHERE routestartdate >= var_from_date
      AND routestartdate < DATE_ADD(var_to_date, INTERVAL 1 DAY)
      AND routekey IS NOT NULL;
    DELETE t
    FROM cashcheckdetail t
    INNER JOIN temp_routekeys r ON r.routekey = t.routekey;
    DELETE t
    FROM ardetail t
    INNER JOIN temp_routekeys r ON r.routekey = t.routekey;
    DELETE t
    FROM arheader t
    INNER JOIN temp_routekeys r ON r.routekey = t.routekey;
    DELETE t
    FROM customerpromotionplandetail t
    INNER JOIN temp_routekeys r ON r.routekey = t.routekey;
    DELETE t
    FROM surveyauditdetail t
    INNER JOIN temp_routekeys r ON r.routekey = t.routekey;
    DELETE t
    FROM posequipmentchangedetail t
    INNER JOIN temp_routekeys r ON r.routekey = t.routekey;
    DELETE t
    FROM customerinventorydetail t
    INNER JOIN temp_routekeys r ON r.routekey = t.routekey;
    DELETE t
    FROM orderrxddetail t
    INNER JOIN temp_routekeys r ON r.routekey = t.routekey;
    DELETE t
    FROM salesorderdetail t
    INNER JOIN temp_routekeys r ON r.routekey = t.routekey;
    DELETE t
    FROM salesorderheader t
    INNER JOIN temp_routekeys r ON r.routekey = t.routekey;
    DELETE t
    FROM invoicerxddetail t
    INNER JOIN temp_routekeys r ON r.routekey = t.routekey;
    DELETE t
    FROM promotiondetail t
    INNER JOIN temp_routekeys r ON r.routekey = t.routekey;
    DELETE t
    FROM invoicedetail t
    INNER JOIN temp_routekeys r ON r.routekey = t.routekey;
    DELETE t
    FROM invoiceheader t
    INNER JOIN temp_routekeys r ON r.routekey = t.routekey;
    DELETE t
    FROM nonservicedcustomer t
    INNER JOIN temp_routekeys r ON r.routekey = t.routekey;
    DELETE t
    FROM nosalesheader t
    INNER JOIN temp_routekeys r ON r.routekey = t.routekey;
    DELETE t
    FROM customeroperationscontrol t
    INNER JOIN temp_routekeys r ON r.routekey = t.routekey;
    DELETE t
    FROM routesequencecustomerstatus t
    INNER JOIN temp_routekeys r ON r.routekey = t.routekey;
    DELETE t
    FROM batchexpirydetail t
    INNER JOIN temp_routekeys r ON r.routekey = t.routekey;
    DELETE t
    FROM inventorysummarydetail t
    INNER JOIN temp_routekeys r ON r.routekey = t.routekey;
    DELETE t
    FROM inventorytransactiondetail t
    INNER JOIN temp_routekeys r ON r.routekey = t.routekey;
    DELETE t
    FROM inventorytransactionheader t
    INNER JOIN temp_routekeys r ON r.routekey = t.routekey;
    DELETE t
    FROM startendday t
    INNER JOIN temp_routekeys r ON r.routekey = t.routekey;
    DROP TEMPORARY TABLE IF EXISTS temp_routekeys;
    COMMIT;
END */$$
DELIMITER ;

/* Procedure structure for procedure `employees_hier` */

/*!50003 DROP PROCEDURE IF EXISTS  `employees_hier` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `employees_hier`(
in p_emp_id smallint unsigned
)
begin
declare v_done tinyint unsigned default(0);
declare v_dpth smallint unsigned default(0);
create temporary table hier(
 boss_id smallint unsigned, 
 emp_id smallint unsigned, 
 depth smallint unsigned
)engine = memory;
insert into hier select boss_id, emp_id, v_dpth from employees where emp_id = p_emp_id;
CREATE TEMPORARY TABLE emps ENGINE=MEMORY SELECT * FROM hier;
WHILE NOT v_done DO
    IF EXISTS( SELECT 1 FROM employees e INNER JOIN hier ON e.boss_id = hier.emp_id AND hier.depth = v_dpth) THEN
        INSERT INTO hier SELECT e.boss_id, e.emp_id, v_dpth + 1 
            FROM employees e INNER JOIN emps ON e.boss_id = emps.emp_id AND emps.depth = v_dpth;
        SET v_dpth = v_dpth + 1;            
        TRUNCATE TABLE emps;
        INSERT INTO emps SELECT * FROM hier WHERE depth = v_dpth;
    ELSE
        SET v_done = 1;
    END IF;
END WHILE;
SELECT 
 e.emp_id,
 e.name AS emp_name,
 p.emp_id AS boss_emp_id,
 p.name AS boss_name,
 hier.depth
FROM 
 hier
INNER JOIN employees e ON hier.emp_id = e.emp_id
LEFT OUTER JOIN employees p ON hier.boss_id = p.emp_id;
DROP TEMPORARY TABLE IF EXISTS hier;
DROP TEMPORARY TABLE IF EXISTS emps;
END */$$
DELIMITER ;

/* Procedure structure for procedure `Enhance_BAT_Productivity` */

/*!50003 DROP PROCEDURE IF EXISTS  `Enhance_BAT_Productivity` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `Enhance_BAT_Productivity`(
	    IN var_division VARCHAR(50),
	    IN var_paramFrom DATE,
	    IN var_paramTo DATE
	)
BEGIN
	DECLARE StrQuery TEXT DEFAULT "";
	DECLARE StrDivision  VARCHAR(250) DEFAULT ""; 
	DECLARE StrDate  VARCHAR(500) DEFAULT ""; 
	DECLARE var_invoice_count INT;
DECLARE var_collection_count INT;
SET var_collection_count=0;
SET var_invoice_count=0;
		DROP TABLE IF EXISTS RptProductivity1;
		
		DROP TABLE IF EXISTS RptProductivity2;
		
		DROP TABLE IF EXISTS RptProductivity3;
	
	IF var_division != '* ALL *' THEN
		SET StrDivision = CONCAT("AND RM.DivisionCode = '", var_division ,"' ");
	END IF;
		
	SET  StrDate = CONCAT("AND SED.RouteStartDate BETWEEN '",var_paramFrom,"' AND '", var_paramTo,"' ");
	SET @StrQuery = CONCAT(" CREATE TABLE RptProductivity1 
				SELECT 
				RSCS.routekey,RSCS.customercode,RSCS.routecode,RSCS.schelduledflag, RSCS.servicedflag 
			 FROM RouteSequenceCustomerStatus RSCS, StartEndDay SED 
			 WHERE RSCS.RouteKey = SED.RouteKey AND RSCS.SeqWeekDay != 5 ", StrDate ," ");
			 
	PREPARE s1 FROM @StrQuery;
 	EXECUTE s1;
 
	SET @StrQuery1 = CONCAT("CREATE TABLE RptProductivity2
				SELECT  
SED.RouteKey, SED.RouteCode, RM.DivisionCode, RM.AlternateRouteCode, RM.RouteName, SED.SalesmanCode, SM.SalesmanName1, 				
COALESCE (Total_Sheduled.TotalCust, 0) AS TotalSheduled,		 	
COALESCE (Total_Visited.TotalCust, 0) AS TotalVisited,				
" ,
var_invoice_count + var_collection_count ,"
 + COALESCE (Total_Unsheduled_Visit.TotalCust, 0) AS TotalUnsheduledVisit,
COALESCE (Total_Sheduled_Sale.TotalCust, 0) AS TotalSheduledSale, " ,
var_invoice_count + var_collection_count , "
+ COALESCE (Total_UnSheduled_Sale.TotalCust, 0) AS TotalUnSheduledSale,			 
COALESCE (Total_Sheduled_NoSale.TotalCust, 0) AS TotalSheduledNoSale,
COALESCE (Total_UnSheduled_NoSale.TotalCust, 0) AS TotalUnSheduledNoSale,
COALESCE (TotalCashSale.NoOfInv, 0) AS TotalCashSale,
COALESCE (TotalCreditSale.NoOfInv, 0) AS TotalCreditSale,		
COALESCE (Receipts.NoOfReceipts, 0) AS TotalReceipts,	
CASE WHEN COALESCE (Total_Sheduled.TotalCust, 0) > 0 THEN
COALESCE (TotalCashSale.NoOfInv, 0) + COALESCE (TotalCreditSale.NoOfInv, 0) / COALESCE (Total_Sheduled.TotalCust, 0)  * 100
ELSE
0
END AS StrikeRate,		
CASE WHEN COALESCE (Total_Visited.TotalCust, 0) + COALESCE (Total_Unsheduled_Visit.TotalCust, 0) > 0 THEN
COALESCE (TotalCashSale.NoOfInv, 0) + COALESCE (TotalCreditSale.NoOfInv, 0)  / COALESCE (Total_Visited.TotalCust, 0) + COALESCE (Total_Unsheduled_Visit.TotalCust, 0) * 100
ELSE
0
END AS Productivity	
			FROM 
				StartEndDay SED, RouteMaster RM, Salesman SM,
				(SELECT RSC.RouteKey, RSC.RouteCode, COUNT(RSC.CustomerCode) AS TotalCust FROM RptProductivity1 RSC WHERE (RSC.SchelduledFlag = 1) GROUP BY RSC.RouteKey, RSC.RouteCode) AS Total_Sheduled,
				
				(SELECT VIS.RouteKey, VIS.RouteCode, COUNT(VIS.CustomerCode) AS TotalCust FROM RptProductivity1 VIS WHERE (VIS.SchelduledFlag = 1) AND (VIS.ServicedFlag != 0) GROUP BY VIS.RouteKey, VIS.RouteCode) AS Total_Visited,
				(SELECT VISOUT.RouteKey, VISOUT.RouteCode, COUNT(VISOUT.CustomerCode) AS TotalCust FROM RptProductivity1 VISOUT WHERE (VISOUT.SchelduledFlag = 0) AND (VISOUT.ServicedFlag != 0) GROUP BY VISOUT.RouteKey, VISOUT.RouteCode) AS Total_Unsheduled_Visit,
				
				(SELECT SALE.RouteKey, SALE.RouteCode, COUNT(SALE.CustomerCode) AS TotalCust FROM RptProductivity1 SALE, InvoiceHeader IH WHERE SALE.RouteKey = IH.RouteKey AND SALE.CustomerCode = IH.CustomerCode AND (SALE.SchelduledFlag = 1) AND (SALE.ServicedFlag = 1) AND (IH.VoidFlag = 0) GROUP BY SALE.RouteKey, SALE.RouteCode) AS Total_Sheduled_Sale,	
				(SELECT SALE.RouteKey, SALE.RouteCode, COUNT(SALE.CustomerCode) AS TotalCust FROM RptProductivity1 SALE, InvoiceHeader IH WHERE SALE.RouteKey = IH.RouteKey AND SALE.CustomerCode = IH.CustomerCode AND (SALE.SchelduledFlag = 0) AND (SALE.ServicedFlag = 1) AND (IH.VoidFlag = 0) GROUP BY SALE.RouteKey, SALE.RouteCode) AS Total_UnSheduled_Sale,
				
				(SELECT NSALE.RouteKey, NSALE.RouteCode, COUNT(NSALE.CustomerCode) AS TotalCust FROM RptProductivity1 NSALE WHERE (NSALE.SchelduledFlag = 1) AND (NSALE.ServicedFlag != 1) GROUP BY NSALE.RouteKey, NSALE.RouteCode) AS Total_Sheduled_NoSale,
				(SELECT NSALE.RouteKey, NSALE.RouteCode, COUNT(NSALE.CustomerCode) AS TotalCust FROM RptProductivity1 NSALE WHERE (NSALE.SchelduledFlag = 0) AND (NSALE.ServicedFlag != 1) GROUP BY NSALE.RouteKey, NSALE.RouteCode) AS Total_UnSheduled_NoSale,
				
				(SELECT IH.RouteKey, IH.RouteCode, COUNT(DISTINCT IH.CustomerCode) NoOfInv FROM InvoiceHeader IH WHERE (IH.ImmediatePaid != 0) AND (IH.VoidFlag = 0) GROUP BY IH.RouteKey, IH.RouteCode) AS TotalCashSale,
				(SELECT IH.RouteKey, IH.RouteCode, COUNT(DISTINCT IH.CustomerCode) NoOfInv FROM InvoiceHeader IH WHERE (IH.ImmediatePaid = 0) AND (IH.VoidFlag = 0) GROUP BY IH.RouteKey, IH.RouteCode) AS TotalCreditSale,
				(SELECT AR.RouteKey, AR.RouteCode, COUNT(DISTINCT AR.CustomerCode) NoOfReceipts FROM ARHeader AR WHERE AR.VoidFlag = 0 AND AR.CustomerCode NOT IN (SELECT DISTINCT IH.CustomerCode FROM InvoiceHeader IH WHERE IH.RouteKey = AR.RouteKey AND IH.VoidFlag = 0) GROUP BY AR.RouteKey, AR.RouteCode) Receipts			
			WHERE 
				(SED.RouteCode = RM.RouteCode) AND (SED.SalesmanCode = SM.SalesmanCode) AND 
				SED.RouteKey = Total_Sheduled.RouteKey AND SED.RouteCode = Total_Sheduled.RouteCode AND 
				SED.RouteKey = Total_Visited.RouteKey AND SED.RouteCode = Total_Visited.RouteCode AND
				SED.RouteKey = Total_Unsheduled_Visit.RouteKey AND SED.RouteCode = Total_Unsheduled_Visit.RouteCode AND
				SED.RouteKey = Total_Sheduled_Sale.RouteKey AND SED.RouteCode = Total_Sheduled_Sale.RouteCode AND
				SED.RouteKey = Total_UnSheduled_Sale.RouteKey AND SED.RouteCode = Total_UnSheduled_Sale.RouteCode AND
				SED.RouteKey = Total_Sheduled_NoSale.RouteKey AND SED.RouteCode = Total_Sheduled_NoSale.RouteCode AND	
				SED.RouteKey = Total_UnSheduled_NoSale.RouteKey AND SED.RouteCode = Total_UnSheduled_NoSale.RouteCode AND	
				SED.RouteKey = TotalCashSale.RouteKey AND SED.RouteCode = TotalCashSale.RouteCode AND
				SED.RouteKey = TotalCreditSale.RouteKey AND SED.RouteCode = TotalCreditSale.RouteCode AND
				SED.RouteKey = Receipts.RouteKey AND SED.RouteCode = Receipts.RouteCode ", StrDate ,"  ", StrDivision ," ");
		PREPARE s2 FROM @StrQuery1;
		EXECUTE s2;
		
		
		SET @StrQuery3 = CONCAT(" CREATE TABLE RptProductivity3	
				SELECT 
				KPI.AlternateRouteCode RouteCode,CONCAT(KPI.RouteName,'(',CAST(KPI.RouteCode AS CHAR),')', '' ) Route, KPI.SalesmanName1 Salesman,
				SUM(KPI.TotalSheduled) PlanedCalls, 
				SUM(KPI.TotalVisited + KPI.TotalUnsheduledVisit) ActualCalls,
				SUM(KPI.TotalCashSale) TotalCashSale,
				SUM(KPI.TotalCreditSale) TotalCreditSale,
				SUM(KPI.TotalReceipts) TotalReceipts,
				SUM(KPI.TotalCashSale + KPI.TotalCreditSale + KPI.TotalReceipts) ProductiveCalls,
				CASE WHEN SUM(KPI.TotalSheduled) > 0 THEN
					ROUND(SUM(KPI.TotalCashSale + KPI.TotalCreditSale + KPI.TotalReceipts)/ SUM(KPI.TotalSheduled) * 100, 3)
				ELSE
					0
				END StrikeRate,
				
				CASE WHEN SUM(KPI.TotalVisited + KPI.TotalUnsheduledVisit) > 0 THEN
					ROUND(SUM(KPI.TotalCashSale + KPI.TotalCreditSale + KPI.TotalReceipts) / SUM(KPI.TotalVisited + KPI.TotalUnsheduledVisit) * 100, 3)
				ELSE
					0
				END Productivity	
			FROM 
				RptProductivity2 KPI
			GROUP BY 
				KPI.AlternateRouteCode, KPI.RouteName, KPI.RouteCode, KPI.SalesmanName1");
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `Enhance_BAT_SalesReport` */

/*!50003 DROP PROCEDURE IF EXISTS  `Enhance_BAT_SalesReport` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `Enhance_BAT_SalesReport`(
		IN division varchar(20),
		in FromDate datetime,
		in todate datetime
	)
BEGIN
SELECT 
		RM.AlternateRouteCode RouteCode, RM.RouteName RouteName, 
		SM.AlternateSalesmanCode SalesmanCode, SM.SalesmanName1 SalesmanName, 
		REPLACE(CM.AlternateCode,'-','') CustomerCode, CM.CustomerName Customer, CM.Region Channel, 
		IH.InvoiceNumber InvoiceNumber, IH.ActualTransactionDate InvoiceDate,
		CASE WHEN CM.InvoicePaymentTerms < 2 THEN 'CASH' WHEN CM.InvoicePaymentTerms = 2 THEN 'CREDIT' ELSE 'TC' END InvoiceType,		
		IM.AlternateCode ItemCode, IM.ItemDescription ItemDescription, 
		ID.SalesQty SalesQuantity, (ID.FreeSampleQty + ID.ManualFreeQty) FreeQuantity, 
		(ID.SalesQty + ID.FreeSampleQty + ID.ManualFreeQty) NetQuantity,
		CM.Grouping_Code GroupingCode, CM.Outlet_Quality OutletQuality
	FROM 
		InvoiceHeader IH, InvoiceDetail ID, CustomerMaster CM, RouteMaster RM, Salesman SM, ItemMaster IM
	WHERE 
		IH.RouteKey = ID.RouteKey AND IH.VisitKey = ID.VisitKey AND 
		IH.RouteCode = RM.RouteCode AND IH.CustomerCode = CM.CustomerCode AND ID.ItemCode = IM.ActualItemCode AND
		IH.SalesmanCode = SM.SalesmanCode AND ID.SalesQty + ID.FreeSampleQty + ID.ManualFreeQty > 0 AND IH.VoidFlag = 0 AND IH.ActualTransactionDate BETWEEN FromDate AND todate  AND CM.DivisionCode = division 
		
	UNION ALL
	SELECT 
		RM.AlternateRouteCode RouteCode, RM.RouteName RouteName, 
		SM.AlternateSalesmanCode SalesmanCode, SM.SalesmanName1 SalesmanName, 
		REPLACE(CM.AlternateCode,'-','') CustomerCode, CM.CustomerName Customer, CM.Region Channel, 
		IH.InvoiceNumber InvoiceNumber, IH.ActualTransactionDate InvoiceDate,
		'RETURN' InvoiceType, 
		IM.AlternateCode ItemCode, IM.ItemDescription ItemDescription, 
		(ID.ReturnQty + ID.DamagedQty + ID.ExpiryQty) * -1 SalesQuantity, ID.ReturnFreeQty * -1 FreeQuantity, 
		(ID.ReturnQty + ID.DamagedQty + ID.ExpiryQty+ID.ReturnFreeQty) * -1 NetQuantity,
		CM.Grouping_Code GroupingCode, CM.Outlet_Quality OutletQuality
	FROM 
		InvoiceHeader IH, InvoiceDetail ID, CustomerMaster CM, RouteMaster RM, Salesman SM, ItemMaster IM
	WHERE 
		IH.RouteKey = ID.RouteKey AND IH.VisitKey = ID.VisitKey AND 
		IH.RouteCode = RM.RouteCode AND IH.CustomerCode = CM.CustomerCode AND ID.ItemCode = IM.ActualItemCode AND
		IH.SalesmanCode = SM.SalesmanCode AND ID.ReturnQty + ID.DamagedQty + ID.ExpiryQty > 0 AND IH.VoidFlag = 0 AND IH.ActualTransactionDate BETWEEN FromDate AND todate  AND CM.DivisionCode = division  ORDER BY 8 ;
  END */$$
DELIMITER ;

/* Procedure structure for procedure `fill_date_dimension` */

/*!50003 DROP PROCEDURE IF EXISTS  `fill_date_dimension` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `fill_date_dimension`(IN startdate DATE,IN stopdate DATE)
BEGIN
    DECLARE currentdate DATE;
    SET currentdate = startdate;
    WHILE currentdate < stopdate DO
        INSERT INTO time_dimension VALUES (
                       
                        YEAR(currentdate),
                         
                        WEEKOFYEAR(currentdate),
                        ADDDATE(currentdate, INTERVAL 1-DAYOFWEEK(currentdate) DAY) ,
		        ADDDATE(currentdate, INTERVAL 7-DAYOFWEEK(currentdate) DAY) 
                        
                        );
        SET currentdate = ADDDATE(currentdate,INTERVAL 7 DAY);
    END WHILE;
END */$$
DELIMITER ;

/* Procedure structure for procedure `int_exp_ardetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_exp_ardetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_exp_ardetail`(
		IN routeKey BIGINT(20)
	)
BEGIN
	SET @closedroute = 0;
	
	SELECT routeclosed INTO @closedroute FROM startendday WHERE routekey = routekey LIMIT 1;
	
	SET @indicator = @closedroute + 1;
	IF @closedroute = 1 THEN
		SET @fromtime = CAST("00:01:00" AS TIME);
		SET @totime = CAST("23:59:00" AS TIME);
	ELSE
		SET @fromtime = CAST(CONCAT(HOUR(CURTIME()),":00:00") AS TIME) - INTERVAL 2 HOUR;
		SET @totime = CURTIME() - INTERVAL 15 MINUTE;
	END IF;
	
	
	
	SELECT 	
		arh.invoicenumber AS receiptno,
		ard.routekey,
		ard.invoicenumber AS invoiceno,
		CASE WHEN arh.transactiondate = ard.invoicedate THEN '0' ELSE ard.alternateinvoicenumber END AS oraclerefno, 
		ard.amountpaid,
		arh.customercode attribute1
	FROM ardetail ard
		INNER JOIN arheader arh ON arh.transactionkey = ard.transactionkey
	WHERE 	
		ard.routekey = routeKey AND 
		CAST(arh.receivedtime AS TIME) BETWEEN @fromtime AND @totime AND 
		arh.transmitindicator < @indicator
	UNION
	
	SELECT 	
		sh.invoicenumber AS receiptno,
		sh.routekey,
		sh.invoicenumber AS invoiceno,
		'0' AS oraclerefno,
		CASE WHEN sh.splittransaction = 0 THEN sh.amountpaid ELSE sh.totalinvoiceamount + sh.totalreturnamount + sh.totaldamagedamount END amountpaid, 
		
		sh.customercode attribute1
	FROM invoiceheader sh
	WHERE 	
		sh.routekey = routeKey AND 
		sh.immediatepaid != 0 AND 
		CAST(sh.receivedtime AS TIME) BETWEEN @fromtime AND @totime
	UNION
	
	SELECT 	
		sh.invoicenumber AS receiptno,
		sh.routekey,
		sh.hhcinvoicenumber AS invoiceno,
		'0' AS oraclerefno,
		(sh.totalreturnamount + sh.totaldamagedamount) * -1 AS amountpaid, 
		
		sh.customercode attribute1
	FROM invoiceheader sh
	WHERE 	
		sh.routekey = routeKey AND 
		sh.immediatepaid != 0 AND 
		sh.splittransaction = 1 AND
		CAST(sh.receivedtime AS TIME) BETWEEN @fromtime AND @totime;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `int_exp_arheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_exp_arheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_exp_arheader`(
		IN routeKey BIGINT(20)
	)
BEGIN
	SET @closedroute = 0;
	SET @s = CONCAT("SELECT routeclosed INTO @closedroute FROM startendday WHERE routekey = ", routekey," LIMIT 1");
        PREPARE stmt1 FROM @s;
        EXECUTE stmt1;	
	
	SET @indicator = @closedroute + 1;
	IF @closedroute = 1 THEN
		SET @fromtime = CAST("00:01:00" AS TIME);
		SET @totime = CAST("23:59:00" AS TIME);
	ELSE
		SET @fromtime = CAST(CONCAT(HOUR(CURTIME()),":00:00") AS TIME) - INTERVAL 2 HOUR;
		SET @totime = CURTIME() - INTERVAL 15 MINUTE;
	END IF;
		
	SELECT 	
		arh.invoicenumber AS receiptno,
		arh.routekey,		
		DATE(arh.transactiondate) AS receiptdate,
		cm.ancustomercode AS custrefno,
		cm.customercode AS custcode,
		arh.routecode,
		sm.salesmancode AS salesmancode,
		arh.totalinvoiceamount AS receiptamt,
		CASE WHEN ccd.typecode = 1 THEN "CHEQUE" ELSE "CASH" END AS MOP,
		ccd.checknumber AS chequeno,
		DATE(ccd.checkdate) AS checkdate,			
		bm.bankname AS bankname,
		CASE WHEN advancepaymentflag = 1 THEN 'ADV' ELSE 'AR' END trantype
		FROM arheader arh
		INNER JOIN customermaster cm ON cm.customercode = arh.customercode
		INNER JOIN cashcheckdetail ccd ON ccd.routekey = arh.routekey AND ccd.visitkey = arh.visitkey 
		LEFT JOIN bankmaster bm ON bm.bankcode = ccd.bankcode
		INNER JOIN salesman sm ON sm.salesmancode = arh.salesmancode
	WHERE 	
		arh.routekey = routeKey AND CAST(arh.receivedtime AS TIME) BETWEEN @fromtime AND @totime AND 
			arh.transmitindicator < @indicator
		
	UNION
	
	SELECT 	
		sh.invoicenumber AS receiptno,
		sh.routekey,		
		DATE(sh.transactiondate) AS receiptdate,
		cm.ancustomercode AS custrefno,
		cm.customercode AS custcode,
		sh.routecode,
		sm.salesmancode AS salesmancode,
		sh.totalinvoiceamount AS receiptamt,
		CASE WHEN ccd.typecode = 1 THEN "CHEQUE" ELSE "CASH" END AS MOP,
		ccd.checknumber AS chequeno,
		DATE(ccd.checkdate) AS checkdate,			
		bm.bankname AS bankname,
		'INV' trantype
	FROM invoiceheader sh
		INNER JOIN customermaster cm ON cm.customercode = sh.customercode
		INNER JOIN cashcheckdetail ccd ON ccd.routekey = sh.routekey AND ccd.visitkey = sh.visitkey 
		LEFT JOIN bankmaster bm ON bm.bankcode = ccd.bankcode
		INNER JOIN salesman sm ON sm.salesmancode = sh.salesmancode
	WHERE 	
		sh.routekey = routeKey AND sh.immediatepaid != 0 AND CAST(sh.receivedtime AS TIME) BETWEEN @fromtime AND @totime;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `int_exp_closingstocks` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_exp_closingstocks` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_exp_closingstocks`(
		IN routeKey BIGINT(20)
	)
BEGIN
	select 		ith.routecode,
			sm.salesmancode as salesmancode,
			itd.routekey,
			DATE(ith.transactiondate) as closingdate,
			ith.documentnumber, 			
			im.actualitemcode as itemcode,
			itd.quantity
		from 	inventorytransactiondetail itd
			inner join inventorytransactionheader ith on ith.detailkey = itd.detailkey  AND ith.transmitindicator =0
			inner join itemmaster im on im.actualitemcode = itd.itemcode
			INNER JOIN salesman sm ON sm.salesmancode = ith.salesmancode
		where 	itd.routekey = routeKey AND
			itd.transactiontypecode IN (6,5);
    END */$$
DELIMITER ;

/* Procedure structure for procedure `int_exp_damages` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_exp_damages` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_exp_damages`(
		IN routeKey BIGINT(20)
	)
BEGIN
	SET @invoice := 0;
	SET @linid := 0;
	
	SELECT 
		sed.routecode,
		sed.salesmancode,
		DATE(sed.routeenddate) AS enddate,
		sed.routekey,
		concat(sed.routecode,'0',sed.routekey) documentnumber, 
		im.actualitemcode AS itemcode,
		'B' AS transactiontype,	
		im.memo2 units,
		SUM(rd.quantity) quantity,
		rr.alternatecode attribute2,
		DATE(CASE WHEN rd.expirydate = '0000-00-00' THEN sed.routestartdate ELSE COALESCE(rd.expirydate, sed.routestartdate) END) as expirydate,
		@linid := CASE WHEN @invoice = sed.routekey THEN @linid+1 ELSE 1 END AS lineno,
		@invoice := sed.routekey AS docn
	FROM startendday sed 	
		INNER JOIN invoicedetail id ON sed.routekey = id.routekey
		INNER JOIN itemmaster im ON im.actualitemcode = id.itemcode
		INNER JOIN invoicerxddetail rd ON rd.transactionkey = id.transactionkey AND rd.itemcode = id.itemcode
		INNER JOIN expiryreturnreasons rr ON rr.code = rd.reasoncode
	WHERE rd.itemtransactiontype = 2 AND sed.routekey = routeKey
	GROUP BY sed.routecode, sed.salesmancode, sed.routekey, im.actualitemcode, rr.alternatecode, im.memo2, 
		COALESCE(rd.expirydate, sed.routestartdate), rr.alternatecode 
	ORDER BY 4, 12;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `int_exp_get_closedroutes` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_exp_get_closedroutes` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_exp_get_closedroutes`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN routeEndDate DATETIME	
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'route.routecode';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'cnt.*';
	END IF;
	SET @count_sql = CONCAT("SELECT COUNT(*) AS counter 
		FROM routemaster AS route 
		LEFT JOIN startendday  sed ON sed.routecode = route.routecode
		LEFT JOIN salesman ON route.salesmancode = salesman.salesmancode
		LEFT JOIN subareamaster AS subarea ON route.subareacode = subarea.subareacode
		WHERE routetmpl = 0 AND sed.routeclosed = 1 AND sed.exportedflag != '1' AND DATE(sed.routeenddate) = '",routeEndDate,"'");
	PREPARE s1 FROM @count_sql;	
	EXECUTE s1;	
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ,"
		FROM routemaster AS route 
		LEFT JOIN startendday  sed ON sed.routecode = route.routecode
		LEFT JOIN salesman ON route.salesmancode = salesman.salesmancode
		LEFT JOIN subareamaster AS subarea ON route.subareacode = subarea.subareacode
		WHERE 1=1 AND routetmpl = 0 AND sed.routeclosed = 1 AND sed.exportedflag != '1' AND DATE(sed.routeenddate) = '",routeEndDate, "' ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    
    
    PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `int_exp_get_routekey` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_exp_get_routekey` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_exp_get_routekey`()
BEGIN
	SELECT routekey from startendday 	where routeclosed = 1 
						and exportedflag != '1';
    END */$$
DELIMITER ;

/* Procedure structure for procedure `int_exp_get_routekey_rpt` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_exp_get_routekey_rpt` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_exp_get_routekey_rpt`()
BEGIN
      
SELECT routekey
FROM
(
	SELECT DISTINCT routekey FROM invoiceheader WHERE transmitindicator = 0 AND voidflag = 0
	UNION
	SELECT DISTINCT routekey FROM arheader WHERE transmitindicator = 0 AND voidflag = 0
	UNION 
	SELECT DISTINCT routekey FROM inventorytransactionheader WHERE transmitindicator = 0 AND 
		transactiontype IN (2,4) AND voidflag = 0
	UNION
	SELECT DISTINCT routekey FROM salesorderheader WHERE transmitindicator = 0 AND voidflag = 0
) trip
WHERE routekey > 0;  
END */$$
DELIMITER ;

/* Procedure structure for procedure `int_exp_loadrequest` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_exp_loadrequest` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_exp_loadrequest`(
		IN routeKey BIGINT(20)
	)
BEGIN	
	SET @sql = CONCAT("
		SELECT
			ith.routecode,
			sed.salesmancode AS salesmancode,
			DATE(ith.transactiondate) AS transferdate,
			DATE(ith.requestdate) AS requestdate,
			itd.routekey,
			ith.documentnumber, 
			im.actualitemcode AS itemcode,
			itd.quantity,
			im.memo2 units,
			im.hhcitemshortdescription attribute2,
			COALESCE((SELECT rm.alternateroutecode FROM routemaster rm WHERE rm.routecode = ith.transferlocationcode LIMIT 1), '') attribute3
		FROM 	
			inventorytransactiondetail itd
				INNER JOIN inventorytransactionheader ith ON ith.detailkey = itd.detailkey AND ith.transmitindicator =0 AND ith.isurgent =1
				INNER JOIN itemmaster im ON im.actualitemcode = itd.itemcode AND im.hhcitemshortdescription = 'F'
				INNER JOIN startendday sed ON sed.routecode = ith.routecode AND sed.routekey = ith.routekey
		WHERE 	
			itd.routekey = ", routeKey, " AND itd.transactiontypecode IN (8)  
			UNION
		SELECT
			ith.routecode,
			sed.salesmancode AS salesmancode,
			DATE(ith.transactiondate) AS transferdate,
			DATE(ith.requestdate) AS requestdate,
			itd.routekey,
			CONCAT(ith.documentnumber,'0') documentnumber, 
			im.actualitemcode AS itemcode,
			itd.quantity,
			im.memo2 units,
			im.hhcitemshortdescription attribute2,
			COALESCE((SELECT rm.alternateroutecode FROM routemaster rm WHERE rm.routecode = ith.transferlocationcode LIMIT 1), '') attribute3
		FROM 	
			inventorytransactiondetail itd
				INNER JOIN inventorytransactionheader ith ON ith.detailkey = itd.detailkey AND ith.transmitindicator =0 AND ith.isurgent =1
				INNER JOIN itemmaster im ON im.actualitemcode = itd.itemcode AND im.hhcitemshortdescription = 'NF'
				INNER JOIN startendday sed ON sed.routecode = ith.routecode AND sed.routekey = ith.routekey
		WHERE 	
			itd.routekey = ", routeKey, " AND itd.transactiontypecode IN (8)");
	
	DROP TABLE IF EXISTS int_exp_loadrequestdetail;
	
	SET @sql = CONCAT('CREATE TABLE int_exp_loadrequestdetail AS ', @sql, ' ');	
	PREPARE stmt1 FROM @sql;
	EXECUTE stmt1;
	
	SET @invoice := 0;
	SET @linid := 0;
	
	SELECT
		routecode,
		salesmancode,
		DATE(transferdate) AS transferdate,
		DATE(requestdate) AS requestdate,
		routekey,
		documentnumber, 
		itemcode,
		quantity,
		units,
		attribute2,
		attribute3,
		@linid := CASE WHEN @invoice = documentnumber THEN @linid+1 ELSE 1 END AS lineno,
		@invoice := documentnumber AS docno
	FROM 	
		int_exp_loadrequestdetail	
	ORDER BY 
		documentnumber, itemcode;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `int_exp_loadrequest_scheduler` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_exp_loadrequest_scheduler` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_exp_loadrequest_scheduler`(
	)
BEGIN	
	SET @sql = CONCAT("
		SELECT
			ith.routecode,
			sed.salesmancode AS salesmancode,
			DATE(ith.transactiondate) AS transferdate,
			DATE(ith.requestdate) AS requestdate,
			itd.routekey,
			ith.documentnumber, 
			im.actualitemcode AS itemcode,
			itd.quantity,
			im.memo2 units,
			im.hhcitemshortdescription attribute2,
			COALESCE((SELECT rm.alternateroutecode FROM routemaster rm WHERE rm.routecode = ith.transferlocationcode LIMIT 1), '') attribute3
		FROM 	
			inventorytransactiondetail itd
				INNER JOIN inventorytransactionheader ith ON ith.detailkey = itd.detailkey AND ith.transmitindicator =0
				INNER JOIN itemmaster im ON im.actualitemcode = itd.itemcode AND im.hhcitemshortdescription = 'F'
				INNER JOIN startendday sed ON sed.routecode = ith.routecode AND sed.routekey = ith.routekey
		WHERE 	
			itd.transactiontypecode IN (8)  
			
		UNION
		
		SELECT
			ith.routecode,
			sed.salesmancode AS salesmancode,
			DATE(ith.transactiondate) AS transferdate,
			DATE(ith.requestdate) AS requestdate,
			itd.routekey,
			CONCAT(ith.documentnumber,'0') documentnumber, 
			im.actualitemcode AS itemcode,
			itd.quantity,
			im.memo2 units,
			im.hhcitemshortdescription attribute2,
			COALESCE((SELECT rm.alternateroutecode FROM routemaster rm WHERE rm.routecode = ith.transferlocationcode LIMIT 1), '') attribute3
		FROM 	
			inventorytransactiondetail itd
				INNER JOIN inventorytransactionheader ith ON ith.detailkey = itd.detailkey AND ith.transmitindicator =0
				INNER JOIN itemmaster im ON im.actualitemcode = itd.itemcode AND im.hhcitemshortdescription = 'NF'
				INNER JOIN startendday sed ON sed.routecode = ith.routecode AND sed.routekey = ith.routekey
		WHERE 	
			itd.transactiontypecode IN (8)");
	
	DROP TABLE IF EXISTS int_exp_loadrequestdetail;
	
	SET @sql = CONCAT('CREATE TABLE int_exp_loadrequestdetail AS ', @sql, ' ');	
	PREPARE stmt1 FROM @sql;
	EXECUTE stmt1;
	
	SET @invoice := 0;
	SET @linid := 0;
	
	SELECT
		routecode,
		salesmancode,
		DATE(transferdate) AS transferdate,
		DATE(requestdate) AS requestdate,
		routekey,
		documentnumber, 
		itemcode,
		quantity,
		units,
		attribute2,
		attribute3,
		@linid := CASE WHEN @invoice = documentnumber THEN @linid+1 ELSE 1 END AS lineno,
		@invoice := documentnumber AS docno
	FROM 	
		int_exp_loadrequestdetail	
	ORDER BY 
		documentnumber, itemcode;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `int_exp_loadtransfers` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_exp_loadtransfers` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_exp_loadtransfers`(
		IN routeKey BIGINT(20)
	)
BEGIN
	
	SET @sql = CONCAT("
		SELECT 
			ih.routecode,
			ih.salesmancode,
			DATE(ih.transactiondate) AS transferdate,
			ih.routekey,
			ih.documentnumber, 
			im.actualitemcode AS itemcode,		
			im.alternatecode,
			CASE WHEN id.transactiontypecode = 3 THEN 'IN' WHEN id.transactiontypecode = 2 THEN 'OUT' ELSE 'B' END AS transactiontype,	
			im.memo1 units,
			FLOOR(id.quantity/ im.unitspercase) quantity,
			CASE WHEN id.transactiontypecode = 3 THEN 'IN' WHEN id.transactiontypecode = 2 THEN retres.description END AS attribute2,
			CASE WHEN id.transactiontypecode = 3 THEN CURDATE() WHEN id.transactiontypecode = 2 THEN id.expirydate END AS expirydate,
			im.unitspercase attribute3
		FROM inventorytransactionheader ih 	
			INNER JOIN inventorytransactiondetail id ON ih.detailkey = id.detailkey AND ih.voidflag = 0
			INNER JOIN itemmaster im ON im.actualitemcode = id.itemcode
			LEFT OUTER JOIN retitmreasons retres ON retres.code = id.reasoncode
		WHERE ih.transactiontype = 2 AND FLOOR(id.quantity/ im.unitspercase) AND ih.routekey = ", routeKey, " AND ih.transmitindicator = 0
		
		UNION
		
		SELECT 
			ih.routecode,
			ih.salesmancode,
			DATE(ih.transactiondate) AS transferdate,
			ih.routekey,
			ih.documentnumber, 
			im.actualitemcode AS itemcode,		
			im.alternatecode,
			CASE WHEN id.transactiontypecode = 3 THEN 'IN' WHEN id.transactiontypecode = 2 THEN 'OUT' ELSE 'B' END AS transactiontype,	
			im.memo2 units,
			(id.quantity MOD im.unitspercase) quantity,
			CASE WHEN id.transactiontypecode = 3 THEN 'IN' WHEN id.transactiontypecode = 2 THEN retres.description END AS attribute2,
			CASE WHEN id.transactiontypecode = 3 THEN CURDATE() WHEN id.transactiontypecode = 2 THEN id.expirydate END AS expirydate,
			im.unitspercase attribute3
		FROM inventorytransactionheader ih 	
			INNER JOIN inventorytransactiondetail id ON ih.detailkey = id.detailkey AND ih.voidflag = 0
			INNER JOIN itemmaster im ON im.actualitemcode = id.itemcode
			LEFT OUTER JOIN retitmreasons retres ON retres.code = id.reasoncode
		WHERE ih.transactiontype = 2 AND (id.quantity MOD im.unitspercase) AND ih.routekey = ", routeKey, " AND ih.transmitindicator = 0");
	DROP TABLE IF EXISTS int_exp_transferdetail;	
	SET @sql = CONCAT('CREATE TABLE int_exp_transferdetail AS ', @sql, ' ');	
	PREPARE stmt1 FROM @sql;
	EXECUTE stmt1;
	SET @invoice := 0;
	SET @linid := 0;
	
	SELECT 
		routecode,
		salesmancode,
		transferdate,
		routekey,
		documentnumber, 
		itemcode,
		alternatecode,
		transactiontype,	
		units,
		quantity,
		attribute2,
		CASE WHEN expirydate = '0000-00-00' THEN CURDATE() ELSE expirydate END expirydate,
		attribute3,
		@linid := CASE WHEN @invoice = documentnumber THEN @linid+1 ELSE 1 END AS lineno,
		@invoice := documentnumber AS docn
	FROM int_exp_transferdetail
	ORDER BY routekey, documentnumber, alternatecode;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `int_exp_orderdetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_exp_orderdetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_exp_orderdetail`(
		IN routeKey BIGINT(20)
	)
BEGIN
	SET @closedroute = 0;
	SET @s = CONCAT("SELECT routeclosed INTO @closedroute FROM startendday WHERE routekey = ", routekey," LIMIT 1");
        PREPARE stmt1 FROM @s;
        EXECUTE stmt1;	
	
	SET @indicator = @closedroute + 1;
	IF @closedroute = 1 THEN
		SET @fromtime = CAST("00:01:00" AS TIME);
		SET @totime = CAST("23:59:00" AS TIME);
	ELSE
		SET @fromtime = CAST(CONCAT(HOUR(CURTIME()),":00:00") AS TIME) - INTERVAL 2 HOUR;
		SET @totime = CURTIME() - INTERVAL 15 MINUTE;
	END IF;
		
	SET @sql = CONCAT("
		SELECT 0 AS SeqNo, sh.invoicenumber AS invoiceno, sd.routekey, 0 AS lineno,
			im.actualitemcode AS itemcode, FLOOR(sd.salesqty/ im.unitspercase) AS quantity, '0' AS refinvoiceno, 'O' AS linetype,
			sd.salescaseprice AS eachprice, COALESCE(pd.promotionpercent, 0) AS itemdiscount,
			'' AS expirydate, im.memo1 unit, 'ORDER' attribute2, im.unitspercase attribute3, im.hhcitemshortdescription attribute4
		FROM salesorderdetail sd
			INNER JOIN salesorderheader sh ON sh.transactionkey = sd.transactionkey 
			INNER JOIN itemmaster im ON im.actualitemcode = sd.itemcode AND im.hhcitemshortdescription = 'F' 
			LEFT JOIN promotiondetail pd ON pd.transactionkey = sh.transactionkey AND pd.promotiontypecode = 6
		WHERE sd.routekey = ", routeKey, " AND sh.voidflag = 0 AND sh.transmitindicator < ", @indicator, " AND 
			CAST(sd.receivedtime AS TIME) BETWEEN '", @fromtime,"' AND '", @totime,"' AND FLOOR(sd.salesqty/ im.unitspercase) > 0
			
			UNION
			
		SELECT 0 AS SeqNo, sh.invoicenumber AS invoiceno, sd.routekey, 0 AS lineno, 
			im.actualitemcode AS itemcode, (sd.salesqty MOD im.unitspercase) AS quantity, '0' AS refinvoiceno, 'O' AS linetype,
			sd.salesprice AS eachprice, COALESCE(pd.promotionpercent, 0) AS itemdiscount,
			'' AS expirydate, im.memo2 unit, 'ORDER' attribute2, im.unitspercase attribute3, im.hhcitemshortdescription attribute4
		FROM salesorderdetail sd
			INNER JOIN salesorderheader sh ON sh.transactionkey = sd.transactionkey
			INNER JOIN itemmaster im ON im.actualitemcode = sd.itemcode AND im.hhcitemshortdescription = 'F' 
			LEFT JOIN promotiondetail pd ON pd.transactionkey = sh.transactionkey AND pd.promotiontypecode = 6
		WHERE sd.routekey = ", routeKey, " AND sh.voidflag = 0 AND sh.transmitindicator < ", @indicator, " AND
			CAST(sd.receivedtime AS TIME) BETWEEN '", @fromtime,"' AND '", @totime,"' AND (sd.salesqty MOD im.unitspercase) > 0
		
	UNION
		SELECT 0 AS SeqNo, sh.invoicenumber AS invoiceno, sd.routekey, 0 AS lineno,
			im.actualitemcode AS itemcode, FLOOR(sd.freesampleqty/im.unitspercase) AS quantity, '0' AS refinvoiceno, 'F' AS linetype,	
			'0'  AS eachprice, 0 AS itemdiscount, '' AS expirydate, im.memo1 unit, 'FREE' attribute2, im.unitspercase attribute3, im.hhcitemshortdescription attribute4
		FROM salesorderdetail sd
			INNER JOIN salesorderheader sh ON sh.transactionkey = sd.transactionkey
			INNER JOIN itemmaster im ON im.actualitemcode = sd.itemcode AND im.hhcitemshortdescription = 'F' 
		WHERE sd.routekey = ", routeKey, " AND sh.voidflag = 0 AND sh.transmitindicator < ", @indicator, " AND 
			CAST(sd.receivedtime AS TIME) BETWEEN '", @fromtime,"' AND '", @totime,"' AND FLOOR(sd.freesampleqty/im.unitspercase) > 0 
			
			UNION
			
		SELECT 0 AS SeqNo, sh.invoicenumber AS invoiceno, sd.routekey, 0 AS lineno,
			im.actualitemcode AS itemcode, (sd.freesampleqty MOD im.unitspercase) AS quantity, '0' AS refinvoiceno, 'F' AS linetype,	
			'0'  AS eachprice, 0 AS itemdiscount, '' AS expirydate, im.memo2 unit, 'FREE' attribute2, im.unitspercase attribute3, im.hhcitemshortdescription attribute4
		FROM salesorderdetail sd
			INNER JOIN salesorderheader sh ON sh.transactionkey = sd.transactionkey
			INNER JOIN itemmaster im ON im.actualitemcode = sd.itemcode AND im.hhcitemshortdescription = 'F' 
		WHERE sd.routekey = ", routeKey, " AND sh.voidflag = 0 AND sh.transmitindicator < ", @indicator, " AND 
			CAST(sd.receivedtime AS TIME) BETWEEN '", @fromtime,"' AND '", @totime,"' AND (sd.freesampleqty MOD im.unitspercase) > 0
	
	UNION
		SELECT 0 AS SeqNo, sh.invoicenumber AS invoiceno, sd.routekey, 0 AS lineno,
			im.actualitemcode AS itemcode, FLOOR(sd.returnqty/im.unitspercase) AS quantity, '0' AS refinvoiceno, 'G' AS linetype,	
			'0'  AS eachprice, 0 AS itemdiscount, '' AS expirydate, im.memo1 unit, 'FREE' attribute2, im.unitspercase attribute3, im.hhcitemshortdescription attribute4
		FROM salesorderdetail sd
			INNER JOIN salesorderheader sh ON sh.transactionkey = sd.transactionkey
			INNER JOIN itemmaster im ON im.actualitemcode = sd.itemcode AND im.hhcitemshortdescription = 'F' 
		WHERE sd.routekey = ", routeKey, " AND sh.voidflag = 0 AND sh.transmitindicator < ", @indicator, " AND 
			CAST(sd.receivedtime AS TIME) BETWEEN '", @fromtime,"' AND '", @totime,"' AND FLOOR(sd.returnqty/im.unitspercase) > 0 
			
			UNION
			
		SELECT 0 AS SeqNo, sh.invoicenumber AS invoiceno, sd.routekey, 0 AS lineno,
			im.actualitemcode AS itemcode, (sd.returnqty MOD im.unitspercase) AS quantity, '0' AS refinvoiceno, 'G' AS linetype,	
