/* Procedure structure for procedure `int_exp_orderheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_exp_orderheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_exp_orderheader`(
		IN routekey BIGINT(20)
	)
BEGIN
	SET @closedroute = 0;
	SET @s = CONCAT("SELECT routeclosed INTO @closedroute FROM startendday WHERE routekey = ", routekey," LIMIT 1");
        PREPARE stmt1 FROM @s;
        EXECUTE stmt1;	
	
	SET @indicator = @closedroute + 1;
	IF @closedroute = 1 THEN
		SET @fromtime = CAST("00:01:00" AS TIME);
		SET @totime = CAST("23:59:00" AS TIME);
	ELSE
		SET @fromtime = CAST(CONCAT(HOUR(CURTIME()),":00:00") AS TIME) - INTERVAL 2 HOUR;
		SET @totime = CURTIME() - INTERVAL 15 MINUTE;
	END IF;
	
	SELECT 		
		sorh.invoicenumber AS orderno,
		sorh.routekey,
		DATE(sorh.transactiondate) AS transactiondate,
		REPLACE(cm.ancustomercode,cm.customercode,'') AS custrefno,
		cm.customercode AS custcode,
		sorh.routecode,	
		sm.salesmancode AS salesmancode,
		sorh.lineitemdiscount AS invoicediscount,
		
		sd.salesamount AS totalorderamt,
		COALESCE(sd.itemcount, 0) itemcount,
		'F' attribute1
	FROM salesorderheader sorh
		INNER JOIN customermaster cm ON cm.customercode = sorh.customercode
		INNER JOIN salesman sm ON sm.salesmancode = sorh.salesmancode
		INNER JOIN 
			(SELECT so.transactionkey, COUNT(so.itemcode) itemcount, 
				SUM((FLOOR(so.salesqty/ im.unitspercase)*so.salescaseprice) + ((so.salesqty MOD im.unitspercase)*so.salesprice)) salesamount
			FROM salesorderdetail so INNER JOIN itemmaster im ON im.actualitemcode = so.itemcode AND im.hhcitemshortdescription = 'F'
			GROUP BY so.transactionkey) sd ON sd.transactionkey = sorh.transactionkey
	WHERE 	
		sorh.routekey = routeKey AND COALESCE(sd.itemcount, 0) > 0 AND sorh.voidflag = 0 AND
		sorh.transmitindicator < @indicator AND
		CAST(sorh.receivedtime AS TIME) BETWEEN @fromtime AND @totime
		
	UNION
	
	SELECT 		
		CONCAT(sorh.invoicenumber,'0') AS orderno,
		sorh.routekey,
		DATE(sorh.transactiondate) AS transactiondate,
		REPLACE(cm.ancustomercode,cm.customercode,'') AS custrefno,
		cm.customercode AS custcode,
		sorh.routecode,	
		sm.salesmancode AS salesmancode,
		sorh.lineitemdiscount AS invoicediscount,
		
		sd.salesamount AS totalorderamt,
		COALESCE(sd.itemcount, 0) itemcount,
		'NF' attribute1
	FROM salesorderheader sorh
		INNER JOIN customermaster cm ON cm.customercode = sorh.customercode
		INNER JOIN salesman sm ON sm.salesmancode = sorh.salesmancode
		INNER JOIN 
			(SELECT so.transactionkey, COUNT(so.itemcode) itemcount, 
				SUM((FLOOR(so.salesqty/ im.unitspercase)*so.salescaseprice) + ((so.salesqty MOD im.unitspercase)*so.salesprice)) salesamount
			FROM salesorderdetail so INNER JOIN itemmaster im ON im.actualitemcode = so.itemcode AND im.hhcitemshortdescription = 'NF'
			GROUP BY so.transactionkey) sd ON sd.transactionkey = sorh.transactionkey
	WHERE 	
		sorh.routekey = routeKey AND COALESCE(sd.itemcount, 0) > 0 AND sorh.voidflag = 0 AND
		sorh.transmitindicator < @indicator AND
		CAST(sorh.receivedtime AS TIME) BETWEEN @fromtime AND @totime;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `int_exp_salemantarget` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_exp_salemantarget` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_exp_salemantarget`(
		IN routeKey BIGINT(20)
	)
BEGIN
		SELECT 	rg.routecode,
			sm.salesmancode as salesmancode,
			DATE(rg.fromdate) as FromDate,
			DATE(rg.todate) as ToDate,
			ig.itemgroupname as itemgrp,
			rg.quantity as targetqty,
			'0' as targetamt
		FROM 	routegoal rg
		inner join salesman sm on sm.salesmancode = rg.salesmancode
		inner join itemgroup ig on ig.itemgroupcode = rg.packagenumber;
    END */$$
DELIMITER ;

