/* Procedure structure for procedure `int_imp_StartingloadDetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_imp_StartingloadDetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_imp_StartingloadDetail`()
BEGIN
SET @temptable = "DROP TABLE IF EXISTS temp_loads";
PREPARE qry3 FROM @temptable;
EXECUTE qry3;
SET @sql = "
SELECT DISTINCT loadperiodnumber FROM startingloaddetail WHERE ddate = CURDATE()
UNION
SELECT DISTINCT loadnumber FROM inventorytransactionheader WHERE transactiontype = 1 AND loadnumber > 1 AND transactiondate = CURDATE()";
SET @temptable =  CONCAT("CREATE TEMPORARY TABLE IF NOT EXISTS temp_loads AS ", @sql);
PREPARE qry4 FROM @temptable;
EXECUTE qry4;
INSERT INTO startingloaddetail 
	(itemcode,routecode,ddate,loadperiodnumber,cases,caseprice,units,totunits,suggtotunits,rcvdtotunits,upc,loadtime,salesmancode,salesprice,
	returnprice,returncaseprice,STATUS,transactiondate,erpreferencenumber,currencycode,batchnumber,expirydate,warehouse,warehousestock,mdat)
SELECT DISTINCT
	ld.itemid, ld.routecode, ld.loaddate, ld.loadno, 0 cases, im.caseprice, ld.eachqty, ld.eachqty, 0 suggtotunits, 0 rcvdtotunits, im.unitspercase, CURTIME() loadtime, 
	ld.salesmancode, im.defaultsalesprice, im.defaultsalesprice, im.caseprice, 0 STATUS, CURDATE() transactiondate, ld.referenceno, 971 currencycode, 
	'NONE' batch, '2099-12-31 00:00:00' expirydate, 0 warehouse, 0 warehousestock, CURDATE() mdat
FROM imp_dailysalesmanload ld
	INNER JOIN itemmaster im ON im.actualitemcode = ld.itemid
WHERE ld.loaddate = CURDATE() AND ld.loadno NOT IN (SELECT temp_loads.loadperiodnumber FROM temp_loads);
UPDATE startingloaddetail SET warehouse = 1 WHERE ddate = CURDATE();
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `int_imp_updated_tables` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_imp_updated_tables` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_imp_updated_tables`(
		IN rwcnt INT,
		IN srchvalue VARCHAR(500), 		
		IN order_by VARCHAR(500),		
		IN order_type VARCHAR(10),		
		IN lmt_strt INT,				
		IN lmt_end INT, 				
		IN table_fields TEXT, 			
		IN dateVal DATETIME	
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'tablename';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'cnt.*';
	END IF;
	SET @count_sql = CONCAT("select count(distinct tablename) as counter from intimplogmaster where DATE(cdat) = '",dateVal,"'");
	PREPARE s1 FROM @count_sql;	
	EXECUTE s1;
	SET @count_sql = CONCAT("SELECT ", table_fields ," from intimplogmaster where DATE(cdat) = '",dateVal,"' ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	PREPARE s2 FROM @count_sql;	
	EXECUTE s2;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `int_imp_Warehousestock` */

