DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_imp_Warehousestock`()
BEGIN
	
	UPDATE itemmaster SET warehousestock = 0;
	
	UPDATE itemmaster im
		INNER JOIN imp_whstock wh ON wh.itemid = im.actualitemcode
	SET im.warehousestock = wh.quantity;
	DELETE FROM imp_whstock;
END */$$
DELIMITER ;

/* Procedure structure for procedure `int_reco_collectionsummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_reco_collectionsummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_reco_collectionsummary`(
)
BEGIN
SELECT ih.transactiondate PostingDate, ih.routekey TripID, ih.routecode RouteCode, sm.alternatesalesmancode SalesmanCode, 
	cm.customercode CustomerID, cm.alternatecode CustomerCode, ih.invoicenumber ReceiptNumber, 
	ih.totalinvoiceamount ReceiptAmount, 
	id.invoicenumber InvoiceNumber, id.amountpaid AmountPaid, 'AR' TranType,
	ccd.checknumber
FROM arheader ih
	INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
	INNER JOIN customermaster cm ON cm.customercode = ih.customercode
	INNER JOIN ardetail id ON id.transactionkey = ih.transactionkey AND ih.voidflag = 0
	INNER JOIN cashcheckdetail ccd ON ccd.routekey = ih.routekey and ccd.visitkey = ih.visitkey
WHERE ih.transactiondate = CURDATE()
UNION
SELECT ih.transactiondate PostingDate, ih.routekey TripID, ih.routecode RouteCode, sm.alternatesalesmancode SalesmanCode, 
	cm.customercode CustomerID, cm.alternatecode CustomerCode, ih.invoicenumber ReceiptNumber, 
	ih.totalinvoiceamount ReceiptAmount, 
	ih.invoicenumber InvoiceNumber, ih.totalinvoiceamount AmountPaid, 'SALE' TranType,
	ccd.checknumber
FROM invoiceheader ih
	INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
	INNER JOIN customermaster cm ON cm.customercode = ih.customercode
	INNER JOIN cashcheckdetail ccd ON ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey
WHERE ih.transactiondate = CURDATE() AND ih.voidflag = 0;
END */$$
DELIMITER ;

/* Procedure structure for procedure `int_reco_presentstocks` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_reco_presentstocks` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_reco_presentstocks`(
)
BEGIN
DROP TABLE IF EXISTS tmp_items;
  CREATE TABLE tmp_items AS SELECT rm.routecode, map.itemcode, im.unitspercase, im.alternatecode FROM routemaster rm INNER JOIN routeitemmapping map ON map.routeitemgrpcode = rm.routeitemgrpcode INNER JOIN itemmaster im ON im.actualitemcode = map.itemcode;
DROP TABLE IF EXISTS tmp_route;
  CREATE TABLE tmp_route AS SELECT routecode, routename, salesmancode,activestatus FROM routemaster WHERE routecode IN (SELECT DISTINCT routecode FROM startendday);
DROP TABLE IF EXISTS tmp_lasttrip;
  CREATE TABLE tmp_lasttrip AS SELECT routecode, MAX(routekey) routekey FROM startendday WHERE routeclosed = 1 GROUP BY routecode;
DROP TABLE IF EXISTS tmp_presenttrip;
  CREATE TABLE tmp_presenttrip AS SELECT routecode, MAX(routekey) routekey FROM startendday WHERE routeclosed = 0 GROUP BY routecode;
   
SELECT CURDATE() SystemDate, rm.routecode Route, sm.alternatesalesmancode Salesman, 
	im.alternatecode ItemCode, im.itemcode ItemID, 
	COALESCE(clos.ClosingQty, 0) Opening,
	COALESCE(lod.LoadQty, 0) Loaded, COALESCE(tout.OutQty, 0) TransferOut, COALESCE(tin.InQty, 0) TransferIn,
	COALESCE(sale.SalesQty, 0) Sales, COALESCE(sale.FreeQty, 0) Free, COALESCE(sale.ReturnQty, 0) GReturn, COALESCE(sale.ReturnFreeQty, 0) GReturnFree,
	COALESCE(clos.ClosingQty, 0) + COALESCE(lod.LoadQty, 0) - COALESCE(tout.OutQty, 0) + COALESCE(tin.InQty, 0) - 
		COALESCE(sale.SalesQty, 0) - COALESCE(sale.FreeQty, 0) + COALESCE(sale.ReturnQty, 0) + COALESCE(sale.ReturnFreeQty, 0) VanStock
FROM tmp_route rm 
	INNER JOIN salesman sm ON sm.salesmancode = rm.salesmancode	
	INNER JOIN tmp_items im ON im.routecode = rm.routecode
	LEFT OUTER JOIN
		(SELECT sed.routecode, id.itemcode, SUM(id.quantity) ClosingQty
		FROM tmp_lasttrip sed 
			INNER JOIN inventorytransactionheader ih ON ih.routekey = sed.routekey 
			INNER JOIN inventorytransactiondetail id ON id.detailkey = ih.detailkey AND ih.transactiontype = 3 AND id.transactiontypecode = 5
		GROUP BY sed.routecode, id.itemcode) clos ON clos.routecode = rm.routecode AND clos.itemcode = im.itemcode	
	LEFT OUTER JOIN
		(SELECT sed1.routecode, id.itemcode, SUM(id.quantity) LoadQty
		FROM tmp_presenttrip sed1 
			INNER JOIN inventorytransactionheader ih ON ih.routekey = sed1.routekey 
			INNER JOIN inventorytransactiondetail id ON id.detailkey = ih.detailkey AND ih.transactiontype = 1 AND id.transactiontypecode = 1
		GROUP BY sed1.routecode, id.itemcode) lod ON lod.routecode = rm.routecode AND lod.itemcode = im.itemcode
	LEFT OUTER JOIN
		(SELECT sed2.routecode, id.itemcode, SUM(id.quantity) OutQty
		FROM tmp_presenttrip sed2 
			INNER JOIN inventorytransactionheader ih ON ih.routekey = sed2.routekey 
			INNER JOIN inventorytransactiondetail id ON id.detailkey = ih.detailkey AND ih.transactiontype = 2 AND id.transactiontypecode = 2
		GROUP BY sed2.routecode, id.itemcode) tout ON tout.routecode = rm.routecode AND tout.itemcode = im.itemcode
	LEFT OUTER JOIN
		(SELECT sed3.routecode, id.itemcode, SUM(id.quantity) InQty
		FROM tmp_presenttrip sed3 
			INNER JOIN inventorytransactionheader ih ON ih.routekey = sed3.routekey 
			INNER JOIN inventorytransactiondetail id ON id.detailkey = ih.detailkey AND ih.transactiontype = 2 AND id.transactiontypecode = 3
		GROUP BY sed3.routecode, id.itemcode) tin ON tin.routecode = rm.routecode AND tin.itemcode = im.itemcode
	LEFT OUTER JOIN
		(SELECT sed4.routecode, id.itemcode, SUM(id.salesqty) SalesQty, SUM(id.freesampleqty) FreeQty, SUM(id.returnqty) ReturnQty, SUM(id.returnfreeqty) ReturnFreeQty
		FROM tmp_presenttrip sed4 
			INNER JOIN invoiceheader ih ON ih.routekey = sed4.routekey 
			INNER JOIN invoicedetail id ON id.transactionkey = ih.transactionkey AND ih.voidflag = 0
		GROUP BY sed4.routecode, id.itemcode) sale ON sale.routecode = rm.routecode AND sale.itemcode = im.itemcode
WHERE rm.activestatus = 1 AND
	COALESCE(clos.ClosingQty, 0) + COALESCE(lod.LoadQty, 0) + COALESCE(tout.OutQty, 0) + COALESCE(tin.InQty, 0) + 
	COALESCE(sale.SalesQty, 0) + COALESCE(sale.FreeQty, 0) + COALESCE(sale.ReturnQty, 0) + COALESCE(sale.ReturnFreeQty, 0) > 0
ORDER BY rm.routecode, im.alternatecode;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `int_reco_salessummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_reco_salessummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_reco_salessummary`(
)
BEGIN
SELECT ih.transactiondate PostingDate, ih.routekey TripID, ih.routecode RouteCode, sm.alternatesalesmancode SalesmanCode, 
                cm.customercode CustomerID, cm.alternatecode CustomerCode, ih.invoicenumber InvoiceNumber, 
                ih.totalinvoiceamount TotalInvoiceAmount, ih.totalpromoamount InvoiceDiscount,
                im.actualitemcode ItemID, im.alternatecode ItemCode, im.unitspercase Upc, 
                id.salesqty SaleQty, id.returnqty ReturnQty, id.damagedqty DamageQty,  
                id.freesampleqty FreeQty, id.returnfreeqty ReturnFreeQty,
                id.salescaseprice CasePrice, id.salesprice PcsPrice,                          
		(FLOOR(id.salesqty / im.unitspercase) * id.salescaseprice + (id.salesqty  MOD im.unitspercase) * id.salesprice) -
		(FLOOR((id.returnqty + id.damagedqty)/ im.unitspercase) * id.returncaseprice + ((id.returnqty + id.damagedqty) MOD im.unitspercase) * id.returnprice) LineTotal
FROM invoiceheader ih
                INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
                INNER JOIN customermaster cm ON cm.customercode = ih.customercode
                INNER JOIN invoicedetail id ON id.transactionkey = ih.transactionkey AND ih.voidflag = 0
                INNER JOIN itemmaster im ON im.actualitemcode = id.itemcode
WHERE ih.transactiondate = CURDATE();
END */$$
DELIMITER ;

/* Procedure structure for procedure `int_reco_stocksdifference` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_reco_stocksdifference` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_reco_stocksdifference`(
)
BEGIN
DROP TABLE IF EXISTS tmp_startendday;
  CREATE TABLE tmp_startendday AS 
	SELECT DISTINCT sed.routecode, sed.salesmancode, sed.routekey, sed.routestartdate, sed.routeenddate
	FROM startendday sed
		INNER JOIN inventorytransactionheader ith ON ith.routekey = sed.routekey
	WHERE COALESCE(sed.routeenddate, CURDATE()) = CURDATE() ;
	
DROP TABLE IF EXISTS tmp_trips;
  CREATE TABLE tmp_trips AS 
	SELECT sed.routecode, 
		COALESCE((SELECT MAX(sed1.routekey) FROM startendday sed1 WHERE sed1.routecode = sed.routecode AND sed1.routekey < sed.routekey), 0) lastvisitkey,
		sed.routekey nextvisitkey, sed.routestartdate nextvisitstartday
	FROM tmp_startendday sed
	HAVING lastvisitkey > 0 ;
	
SELECT MIN(lastvisitkey) INTO @minkey FROM tmp_trips;
SELECT MAX(nextvisitkey) INTO @maxkey FROM tmp_trips;
DROP TABLE IF EXISTS tmp_stocks;
CREATE TABLE tmp_stocks AS 
	SELECT routekey, transactiontypecode, SUM(quantity * itemprice) amount FROM inventorytransactiondetail 
	WHERE transactiontypecode IN (5,12) AND routekey BETWEEN @minkey AND @maxkey
	GROUP BY routekey, transactiontypecode;
	
SELECT routecode, nextvisitkey routekey, nextvisitstartday startdate, 	
	clos.amount PreviousClosingValue, opn.amount NewOpeningValue
FROM tmp_trips
	LEFT OUTER JOIN tmp_stocks clos ON clos.routekey = lastvisitkey AND clos.transactiontypecode = 5 
	LEFT OUTER JOIN tmp_stocks opn ON opn.routekey = nextvisitkey AND opn.transactiontypecode = 12
HAVING NewOpeningValue < PreviousClosingValue;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `int_reco_transactionsummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_reco_transactionsummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_reco_transactionsummary`(
)
BEGIN
SELECT TripID, TranDate, Route, SalesmanID, SalesmanCode, 
	SUM(TotalSalesDocs) TotalSalesDocs, SUM(TotalCashSales) TotalCashSales, sUM(TotalCreditSales) TotalCreditSales, 
	SUM(TotalArDocs) TotalArDocs, SUM(TotalReceipts) TotalArAmount
FROM
	(SELECT ih.routekey TripID, ih.transactiondate TranDate, ih.routecode Route, ih.salesmancode SalesmanID, sm.alternatesalesmancode SalesmanCode,
		COUNT(ih.invoicenumber) TotalSalesDocs, 
		SUM(CASE WHEN ih.amountpaid != 0 THEN ih.totalinvoiceamount ELSE 0 END) TotalCashSales, 
		SUM(CASE WHEN ih.amountpaid = 0 THEN ih.totalinvoiceamount ELSE 0 END) TotalCreditSales, 
		0 TotalArDocs, 0 TotalReceipts
	FROM invoiceheader ih
		INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
		INNER JOIN routemaster rm ON rm.routecode = ih.routecode
	WHERE ih.voidflag = 0 AND ih.transactiondate = CURDATE()
	GROUP BY ih.routekey, ih.transactiondate, ih.routecode, ih.salesmancode, sm.alternatesalesmancode
	
	UNION
	
	SELECT ih.routekey TripID, ih.transactiondate TranDate, ih.routecode Route, ih.salesmancode SalesmanID, sm.alternatesalesmancode SalesmanCode, 
		0 TotalSalesDocs, 0 TotalCashSales, 0 TotalCreditSales,
		COUNT(ih.invoicenumber) TotalArDocs, SUM(ih.totalinvoiceamount) TotalReceipts
	FROM arheader ih
		INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
		INNER JOIN routemaster rm ON rm.routecode = ih.routecode
	WHERE ih.voidflag = 0 AND ih.transactiondate = CURDATE()
	GROUP BY ih.routekey, ih.transactiondate, ih.routecode, ih.salesmancode, sm.alternatesalesmancode
	) Tran
GROUP BY TripID, TranDate, Route, SalesmanID, SalesmanCode;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `int_sp_clear_tables` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_sp_clear_tables` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_sp_clear_tables`()
BEGIN
	DECLARE EXIT HANDLER FOR SQLEXCEPTION
	call int_sp_error_logging('sp - int_sp_clear_tables');
	
	
	DELETE FROM intimperrorlogs;
	DELETE FROM intimplogmaster;
	DELETE FROM intexperrorlogs;
	
	
	DELETE FROM imp_employee;
	DELETE FROM imp_itemmaster;
	DELETE FROM imp_dailysalesmanload;
	DELETE FROM imp_customermaster;
	DELETE FROM imp_customerinvoice;
	DELETE FROM imp_customerspecialprice;
		
    END */$$
DELIMITER ;

