/* Procedure structure for procedure `int_sp_error_logging` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_sp_error_logging` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_sp_error_logging`(
		IN remarks TEXT
	)
BEGIN
		GET DIAGNOSTICS CONDITION 1 @sqlstate = RETURNED_SQLSTATE, 
		@errno = MYSQL_ERRNO, @text = MESSAGE_TEXT;
		SET @full_error = CONCAT("ERROR ", @errno, " (", @sqlstate, "): ", @text);
		INSERT INTO intimperrorlogs SET `date` = curdate(), 
						errorcode = @errno,
						description = @full_error,
						remarks = remarks;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `int_sp_execute_query` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_sp_execute_query` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_sp_execute_query`(
		IN sqlVal TEXT,
		IN comments TEXT
	)
BEGIN
	DECLARE sqlSt TEXT DEFAULT "";
	DECLARE EXIT HANDLER FOR SQLEXCEPTION
	call int_sp_error_logging(concat('sp - int_sp_execute_query ',substring(sqlVal,0,100),' Comments : ',sqlVal ));
	
	SET  @val = CONCAT(sqlVal,"");
	PREPARE sqlSt FROM @val;
	EXECUTE sqlSt;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `int_sp_exp_error_logging` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_sp_exp_error_logging` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_sp_exp_error_logging`(
		IN errno varchar(50),
		IN description TEXT,
		IN remarks TEXT
	)
BEGIN
	INSERT INTO intexperrorlogs SET 	`date` = curdate(), 
						errorcode = errno,
						description = description,
						remarks = remarks;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `int_sp_insert_logging` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_sp_insert_logging` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_sp_insert_logging`(
		in tblname varchar(100),
		in tblid bigint(20),
		in createdby varchar(30),
		in operationtype varchar(20),
		in description text
	)
BEGIN
	DECLARE EXIT HANDLER FOR SQLEXCEPTION
	call int_sp_error_logging('sp - int_sp_insert_logging');
	insert into intimplogmaster	(tablename,recordid,created,cdat,operationtype,description)values
					(tblname,tblid,createdby,now(),operationtype,description);
    END */$$
DELIMITER ;

/* Procedure structure for procedure `postsuggestedorderinvoice` */

/*!50003 DROP PROCEDURE IF EXISTS  `postsuggestedorderinvoice` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `postsuggestedorderinvoice`(
	IN dttoday DATETIME,
	IN introutecode BIGINT(18)
    )
BEGIN
	SELECT COALESCE(offtakeparameter, 1) * 7 INTO @offtake FROM setup;
	
	SELECT COALESCE(routetype,0) INTO @routetype FROM routemaster WHERE routecode = introutecode;
	
	
	
	IF @routetype = 1 OR @routetype = 3 THEN
		SET @SQL = CONCAT("
		INSERT INTO suggestedorderinvoice (routecode,customercode,transactiondate,itemcode,transactiontype,lastvisitshelfstock,lastvisitsales,currentvisitshelfstock,currentvisitsales,offtakeqty,currentvisitgsales,currentvisitreturns,currentvisitsecondarysales,mdat)
			SELECT coc.routecode, coc.customercode, CURDATE(), id.itemcode, 4 transactiontype, 
				COALESCE(SUM(qtyloc1each + qtyloc2each + qtyloc3each), 0) lastvisitshelfstock, 
				COALESCE(AVG(id.salesqty-id.returnqty-id.damagedqty), 0) lastvisitsales, 
				0, 0, 
				CASE WHEN AVG(id.salesqty-id.returnqty-id.damagedqty) < 0 THEN 0 ELSE 
					AVG(id.salesqty-id.returnqty-id.damagedqty) + 
						ROUND(AVG(id.salesqty-id.returnqty-id.damagedqty) * (SELECT COALESCE(offtakeparameter,0) FROM itemmaster im WHERE im.actualitemcode = id.itemcode), 0) END offtake, 0, 0, 0, CURDATE() 
			FROM customeroperationscontrol coc
				LEFT OUTER JOIN salesorderheader ih ON ih.routekey = coc.routekey AND ih.visitkey = coc.visitkey AND ih.voidflag = 0
					INNER JOIN salesorderdetail id ON id.routekey = ih.routekey AND id.visitkey = ih.visitkey
				LEFT OUTER JOIN customerinventorydetail cid ON cid.routekey = coc.routekey AND cid.visitkey = coc.visitkey
				INNER JOIN customermaster cm ON cm.customercode = coc.customercode AND cm.enablesuggestsales = 1
			WHERE DATE(coc.visitstartdate) > DATE(CURDATE() - INTERVAL ", @offtake, " DAY) AND coc.routecode = ", introutecode, " 
			GROUP BY coc.routecode, coc.customercode, id.itemcode
			HAVING offtake > 0");
	ELSE
		SET @SQL = CONCAT("
		INSERT INTO suggestedorderinvoice (routecode,customercode,transactiondate,itemcode,transactiontype,lastvisitshelfstock,lastvisitsales,currentvisitshelfstock,currentvisitsales,offtakeqty,currentvisitgsales,currentvisitreturns,currentvisitsecondarysales,mdat)
			SELECT ih.deliveryroute, ih.customercode, CURDATE(), id.itemcode, 4 transactiontype, 0 lastvisitshelfstock, 
				COALESCE(AVG(id.salesqty), 0) lastvisitsales, 
				0, 0, 
				CASE WHEN AVG(id.salesqty) < 0 THEN 0 ELSE 
					AVG(id.salesqty) + ROUND(AVG(id.salesqty) * (SELECT COALESCE(offtakeparameter,0) FROM itemmaster im WHERE im.actualitemcode = id.itemcode), 0) END offtake, 
						0, 0, 0, CURDATE() 
			FROM deliveryheader ih 
				INNER JOIN deliverydetail id ON id.deliveryno = ih.deliveryno
				INNER JOIN customermaster cm ON cm.customercode = ih.customercode AND cm.enablesuggestsales = 1
			WHERE DATE(ih.deliverydate) > DATE(CURDATE() - INTERVAL @offtake DAY) AND ih.deliveryroute = ", introutecode, " 
			GROUP BY ih.deliveryroute, ih.customercode, id.itemcode
			HAVING offtake > 0");
	END IF;
	PREPARE s1 FROM @SQL;
	EXECUTE s1;
	
	
	IF @routetype = 0 OR @routetype = 2 THEN
		SET @SQL = CONCAT("UPDATE suggestedorderinvoice ss
			INNER JOIN itemmaster im ON im.actualitemcode = ss.itemcode AND ss.routecode = ", introutecode, " AND
				(ss.offtakeqty > 0) AND (ss.offtakeqty MOD im.unitspercase > 0)
			SET ss.offtakeqty = ss.offtakeqty + (im.unitspercase - (ss.offtakeqty MOD im.unitspercase));");
		PREPARE s2 FROM @SQL;
		EXECUTE s2;
	END IF;
	
    
END */$$
DELIMITER ;

/* Procedure structure for procedure `postsuggestedsalesinvoice` */

/*!50003 DROP PROCEDURE IF EXISTS  `postsuggestedsalesinvoice` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `postsuggestedsalesinvoice`(
		IN dttoday DATETIME,
		IN introutecode BIGINT(18)
    )
BEGIN
	
	 DECLARE var_routecode BIGINT(18);
	 DECLARE var_customercode BIGINT(18);
	 DECLARE var_maxroutekey BIGINT(18);
	 DECLARE var_offtakeparameter INT;
	 DECLARE var_rowcount1 INT;
	 DECLARE var_trndate DATETIME;
	 DECLARE var_historymaxdelivery INT;
	 
	 DECLARE counter INT DEFAULT 1;
	 DECLARE no_more_rows BOOLEAN;
	 DECLARE num_rows INT DEFAULT 0;
	 
	 DECLARE crlastvisit CURSOR FOR SELECT DISTINCT customercode,routecode FROM suggestsalesinvoice;
	 DECLARE crofftake CURSOR FOR SELECT customercode ,MIN(transactiondate) AS trndate,COUNT(DISTINCT transactiondate) AS rowcount1 FROM suggestsalesinvoice GROUP BY customercode,transactiondate;
	
	 SELECT offtakeparameter INTO var_offtakeparameter FROM setup WHERE setupid=1;
	 
	 DROP TEMPORARY TABLE IF EXISTS suggestsalesinvoice;
	 
	 CREATE TEMPORARY TABLE IF NOT EXISTS suggestsalesinvoice (
		routecode BIGINT(18),
		customercode BIGINT(18),
		transactiondate DATETIME,
		itemcode BIGINT(18),
		transactiontype INT NULL,
		lastvisitshelfstock BIGINT(18) NULL,
		lastvisitsales BIGINT(18) NULL,
		currentvisitshelfstock BIGINT(18) NULL,
		currentvisitsales BIGINT(18) NULL,
		offtakeqty BIGINT(18) NULL,
		currentvisitgsales BIGINT(18) NULL,
		currentvisitreturns BIGINT(18) NULL,
		currentvisitsecondarysales BIGINT(18) NULL,
		orderedqty BIGINT(18) NULL
	 );
	 
	 DELETE FROM suggestedsalesinvoice WHERE routecode = introutecode;
	 
	 INSERT INTO suggestsalesinvoice
        SELECT ih.routecode,ih.customercode ,ih.transactiondate transactiondate
        ,idt.itemcode,4 AS transactiontype,0 AS lastvisitshelfstock,0 AS lastvisitsales
        ,0 AS currentvisitshelfstock,SUM(idt.salesqty-returnqty-damagedqty) AS currentvisitsales
        ,0 AS offtakeqty
        ,SUM(idt.salesqty) AS currentvisitgsales
        ,SUM(returnqty+damagedqty) AS currentvisitreturns,0 AS currentvisitsecondarysales
        ,0 AS orderedqty
        FROM invoicedetail idt,invoiceheader ih,startendday sed
        WHERE idt.transactionkey = ih.transactionkey AND ih.visitkey = idt.visitkey
        AND ih.routekey = sed.routekey AND idt.routekey = sed.routekey
        AND sed.routeenddate =@dttoday        
        AND sed.routecode = introutecode
        GROUP BY ih.routecode,ih.customercode,ih.transactiondate,idt.itemcode;    
		
			OPEN crlastvisit;
			SELECT FOUND_ROWS() INTO num_rows;
			main_loop: LOOP
			IF no_more_rows THEN
				CLOSE crlastvisit;
				LEAVE main_loop;
				IF counter > num_rows THEN
					CLOSE crlastvisit;
					LEAVE main_loop;
				END IF;
			END IF;
		
			FETCH crlastvisit INTO var_customercode,var_routecode;					
				SELECT MAX(coc.routekey) AS routekey INTO var_maxroutekey FROM customeroperationscontrol coc
						 WHERE coc.customercode = var_customercode AND routekey 
						 IN (SELECT routekey FROM startendday
						 WHERE routeenddate = @dttoday);
				INSERT INTO suggestsalesinvoice  SELECT var_routecode routecode,ih.customercode
				,ih.transactiondate AS transactiondate
				,idt.itemcode,2 AS transactiontype,0 AS lastvisitshelfstock,SUM(idt.salesqty-returnqty-damagedqty) AS lastvisitsales
				,0 AS currentvisitshelfstock,0 AS currentvisitsales, SUM(idt.salesqty-returnqty-damagedqty) AS offtakeqty
				,0 AS currentvisitgsales,0 AS currentvisitreturns,0 AS currentvisitsecondarysales
				,0 AS orderedqty
				 FROM invoicedetail idt,invoiceheader ih,startendday sed
				 WHERE idt.transactionkey = ih.transactionkey AND ih.visitkey = idt.visitkey
				 AND ih.routekey = sed.routekey AND idt.routekey = sed.routekey
				 AND sed.routekey = var_maxroutekey AND ih.customercode = var_customercode
				 GROUP BY ih.customercode,ih.transactiondate,idt.itemcode;			
				FETCH crlastvisit INTO var_customercode,var_routecode;		
		SET counter = counter+1;
		END LOOP main_loop;	
	   
	   INSERT INTO suggestedsalesinvoice SELECT * FROM suggestsalesinvoice;	
		OPEN crofftake;
		SELECT FOUND_ROWS() INTO num_rows;
		main_loop: LOOP
		IF no_more_rows THEN
			CLOSE crofftake;
			LEAVE main_loop;
			IF counter > num_rows THEN
				CLOSE crofftake;
				LEAVE main_loop;
			END IF;
		END IF;
		FETCH crofftake INTO var_customercode,var_trndate,var_rowcount1;		
			BEGIN
				  SELECT IFNULL(histmaxdeliveries,0) INTO var_historymaxdelivery FROM customermaster WHERE customercode=var_customercode;
				  
				  IF var_rowcount1 >var_historymaxdelivery THEN
					DELETE FROM suggestedsalesinvoice WHERE customercode = var_customercode AND transactiondate= var_trndate;
				  END IF;	
				FETCH crofftake INTO var_customercode,var_trndate,var_rowcount1;
			END;
		SET counter = counter+1;
		END LOOP main_loop;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `postsuggestedsalesinvoiceNEW` */

/*!50003 DROP PROCEDURE IF EXISTS  `postsuggestedsalesinvoiceNEW` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `postsuggestedsalesinvoiceNEW`(
	IN dttoday DATETIME,
	IN introutecode BIGINT(18)
    )
BEGIN
	SELECT COALESCE(offtakeparameter, 1) * 7 INTO @offtake FROM setup;
	
	SELECT COALESCE(routetype,0) INTO @routetype FROM routemaster WHERE routecode = introutecode;
	
	
	
	IF @routetype = 1 OR @routetype = 3 THEN
		SET @sql = CONCAT("
		INSERT INTO suggestedsalesinvoice (routecode,customercode,transactiondate,itemcode,transactiontype,lastvisitshelfstock,lastvisitsales,currentvisitshelfstock,currentvisitsales,offtakeqty,currentvisitgsales,currentvisitreturns,currentvisitsecondarysales,mdat)
			SELECT coc.routecode, coc.customercode, CURDATE(), id.itemcode, 4 transactiontype, 
				COALESCE(SUM(qtyloc1each + qtyloc2each + qtyloc3each), 0) lastvisitshelfstock, 
				COALESCE(AVG(id.salesqty-id.returnqty-id.damagedqty), 0) lastvisitsales, 
				0, 0, 
				CASE WHEN AVG(id.salesqty-id.returnqty-id.damagedqty) < 0 THEN 0 ELSE 
					AVG(id.salesqty-id.returnqty-id.damagedqty) + 
						ROUND(AVG(id.salesqty-id.returnqty-id.damagedqty) * (SELECT COALESCE(offtakeparameter,0) FROM itemmaster im WHERE im.actualitemcode = id.itemcode), 0) END offtake, 0, 0, 0, CURDATE() 
			FROM customeroperationscontrol coc
				LEFT OUTER JOIN invoiceheader ih ON ih.routekey = coc.routekey AND ih.visitkey = coc.visitkey AND ih.voidflag = 0
					INNER JOIN invoicedetail id ON id.routekey = ih.routekey AND id.visitkey = ih.visitkey
				LEFT OUTER JOIN customerinventorydetail cid ON cid.routekey = coc.routekey AND cid.visitkey = coc.visitkey
				INNER JOIN customermaster cm ON cm.customercode = coc.customercode AND cm.enablesuggestsales = 1
			WHERE DATE(coc.visitstartdate) > DATE(CURDATE() - INTERVAL ", @offtake, " DAY) AND coc.routecode = ", introutecode, " 
			GROUP BY coc.routecode, coc.customercode, id.itemcode
			HAVING offtake > 0");
	ELSE
		SET @sql = CONCAT("
		INSERT INTO suggestedsalesinvoice (routecode,customercode,transactiondate,itemcode,transactiontype,lastvisitshelfstock,lastvisitsales,currentvisitshelfstock,currentvisitsales,offtakeqty,currentvisitgsales,currentvisitreturns,currentvisitsecondarysales,mdat)
			SELECT ih.deliveryroute, ih.customercode, CURDATE(), id.itemcode, 4 transactiontype, 0 lastvisitshelfstock, 
				COALESCE(AVG(id.salesqty), 0) lastvisitsales, 
				0, 0, 
				CASE WHEN AVG(id.salesqty) < 0 THEN 0 ELSE 
					AVG(id.salesqty) + ROUND(AVG(id.salesqty) * (SELECT COALESCE(offtakeparameter,0) FROM itemmaster im WHERE im.actualitemcode = id.itemcode), 0) END offtake, 
						0, 0, 0, CURDATE() 
			FROM deliveryheader ih 
				INNER JOIN deliverydetail id ON id.deliveryno = ih.deliveryno
				INNER JOIN customermaster cm ON cm.customercode = ih.customercode AND cm.enablesuggestsales = 1
			WHERE DATE(ih.deliverydate) > DATE(CURDATE() - INTERVAL @offtake DAY) AND ih.deliveryroute = ", introutecode, " 
			GROUP BY ih.deliveryroute, ih.customercode, id.itemcode
			HAVING offtake > 0");
	END IF;
	PREPARE s1 FROM @sql;
	EXECUTE s1;
	
	
	IF @routetype = 0 OR @routetype = 2 THEN
		SET @sql = CONCAT("UPDATE suggestedsalesinvoice ss
			INNER JOIN itemmaster im ON im.actualitemcode = ss.itemcode AND ss.routecode = ", introutecode, " AND
				(ss.offtakeqty > 0) AND (ss.offtakeqty MOD im.unitspercase > 0)
			SET ss.offtakeqty = ss.offtakeqty + (im.unitspercase - (ss.offtakeqty MOD im.unitspercase));");
		PREPARE s2 FROM @sql;
		EXECUTE s2;
	END IF;
	
    
END */$$
DELIMITER ;

/* Procedure structure for procedure `post_salestrend_routebook` */

/*!50003 DROP PROCEDURE IF EXISTS  `post_salestrend_routebook` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `post_salestrend_routebook`(
	IN var_routecode BIGINT(20)
	)
BEGIN
	SELECT COALESCE(routetype,0) INTO @routetype FROM routemaster WHERE routecode = introutecode;
	
	
	DELETE FROM salestrend WHERE routecode = var_routecode;
	
	IF @routetype = 1 OR @routetype = 3 THEN
		INSERT INTO salestrend
		SELECT routecode, transactiondate, SUM(totalinvoiceamount) totalinvoiceamount, SUM(totalsalesamount) totalsalesamount,
			SUM(totalreturnamount) totalreturnamount, SUM(totaldamagedamount) totaldamagedamount
		FROM invoiceheader WHERE routecode = var_routecode 
		GROUP BY routecode, transactiondate LIMIT 5;
	ELSE
		INSERT INTO salestrend
		SELECT deliveryroute, deliverydate, SUM(totalamount) totalinvoiceamount, SUM(totalamount) totalsalesamount,
			0 totalreturnamount, 0 totaldamagedamount
		FROM deliveryheader WHERE deliveryroute = var_routecode 
		GROUP BY deliveryroute, deliverydate LIMIT 5;
	END IF;
	
	
	DELETE FROM routebook WHERE routecode = var_routecode;
	
	IF @routetype = 1 OR @routetype = 3 THEN
		INSERT INTO routebook
		SELECT ih.routecode, ih.transactiondate, ih.invoicenumber, ih.customercode, id.itemcode, id.salesqty, id.returnqty, id.damagedqty, id.freesampleqty
		FROM invoiceheader ih
			INNER JOIN invoicedetail id ON id.transactionkey = ih.transactionkey 
		WHERE ih.routecode = var_routecode AND ih.transactiondate BETWEEN CURDATE() - INTERVAL 30 DAY AND CURDATE();
	ELSE
		INSERT INTO routebook
		SELECT ih.deliveryroute, ih.deliverydate, ih.orderno, ih.customercode, id.itemcode, id.salesqty, id.returnqty, 0 damagedqty, id.focqty
		FROM deliveryheader ih
			INNER JOIN deliverydetail id ON id.deliveryno = ih.deliveryno 
		WHERE ih.deliveryroute = var_routecode AND ih.deliverydate BETWEEN CURDATE() - INTERVAL 30 DAY AND CURDATE();
	END IF;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `post_suggestedqty` */

/*!50003 DROP PROCEDURE IF EXISTS  `post_suggestedqty` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `post_suggestedqty`(
	IN var_salesmancode BIGINT(18),
	IN var_routecode BIGINT(18)
    )
BEGIN
	
	DECLARE invoice VARCHAR(100) DEFAULT CONCAT("temp_target_inv_",var_salesmancode);
	DECLARE custopsctl VARCHAR(100) DEFAULT CONCAT("temp_target_coc_",var_salesmancode);
	
	
	SELECT COALESCE(offtakeparameter, 1) * 7 INTO @offtake FROM setup;
	
	SELECT COALESCE(routetype,0) INTO @routetype FROM routemaster WHERE routecode = var_routecode;
	
	
	
	
	IF @routetype = 1 OR @routetype = 3 THEN
		SET @sql = CONCAT("
		INSERT INTO suggestedsalesinvoice (routecode,customercode,transactiondate,itemcode,transactiontype,lastvisitshelfstock,lastvisitsales,currentvisitshelfstock,currentvisitsales,offtakeqty,currentvisitgsales,currentvisitreturns,currentvisitsecondarysales,mdat)
			SELECT coc.routecode, coc.customercode, CURDATE(), id.itemcode, 4 transactiontype, 
				COALESCE(SUM(qtyloc1each + qtyloc2each + qtyloc3each), 0) lastvisitshelfstock, 
				COALESCE(AVG(id.salesqty-id.returnqty-id.damagedqty), 0) lastvisitsales, 
				0, 0, 
				CASE WHEN AVG(id.salesqty-id.returnqty-id.damagedqty) < 0 THEN 0 ELSE 
					AVG(id.salesqty-id.returnqty-id.damagedqty) + 
						ROUND(AVG(id.salesqty-id.returnqty-id.damagedqty) * (SELECT COALESCE(offtakeparameter,0) FROM itemmaster im WHERE im.actualitemcode = id.itemcode), 0) END offtake, 0, 0, 0, CURDATE() 
			FROM ", custopsctl," coc
				LEFT OUTER JOIN ", invoice," id ON id.routekey = coc.routekey AND id.visitkey = coc.visitkey 
				LEFT OUTER JOIN customerinventorydetail cid ON cid.routekey = coc.routekey AND cid.visitkey = coc.visitkey
				INNER JOIN customermaster cm ON cm.customercode = coc.customercode AND cm.enablesuggestsales = 1
			WHERE DATE(coc.visitstartdate) > DATE(CURDATE() - INTERVAL ", @offtake, " DAY) AND coc.routecode = ", var_routecode, " 
			GROUP BY coc.routecode, coc.customercode, id.itemcode
			HAVING offtake > 0");
	ELSE
		SET @sql = CONCAT("
		INSERT INTO suggestedsalesinvoice (routecode,customercode,transactiondate,itemcode,transactiontype,lastvisitshelfstock,lastvisitsales,currentvisitshelfstock,currentvisitsales,offtakeqty,currentvisitgsales,currentvisitreturns,currentvisitsecondarysales,mdat)
			SELECT ih.deliveryroute, ih.customercode, CURDATE(), id.itemcode, 4 transactiontype, 0 lastvisitshelfstock, 
				COALESCE(AVG(id.salesqty), 0) lastvisitsales, 
				0, 0, 
				CASE WHEN AVG(id.salesqty) < 0 THEN 0 ELSE 
					AVG(id.salesqty) + ROUND(AVG(id.salesqty) * (SELECT COALESCE(offtakeparameter,0) FROM itemmaster im WHERE im.actualitemcode = id.itemcode), 0) END offtake, 
						0, 0, 0, CURDATE() 
			FROM deliveryheader ih 
				INNER JOIN deliverydetail id ON id.deliveryno = ih.deliveryno
				INNER JOIN customermaster cm ON cm.customercode = ih.customercode AND cm.enablesuggestsales = 1
			WHERE DATE(ih.deliverydate) > DATE(CURDATE() - INTERVAL @offtake DAY) AND ih.deliveryroute = ", var_routecode, " 
			GROUP BY ih.deliveryroute, ih.customercode, id.itemcode
			HAVING offtake > 0");
	END IF;
	PREPARE s1 FROM @sql;
	EXECUTE s1;
	
	
	IF @routetype = 0 OR @routetype = 2 THEN
		SET @sql = CONCAT("UPDATE suggestedsalesinvoice ss
			INNER JOIN itemmaster im ON im.actualitemcode = ss.itemcode AND ss.routecode = ", var_routecode, " AND
				(ss.offtakeqty > 0) AND (ss.offtakeqty MOD im.unitspercase > 0)
			SET ss.offtakeqty = ss.offtakeqty + (im.unitspercase - (ss.offtakeqty MOD im.unitspercase));");
		PREPARE s2 FROM @sql;
		EXECUTE s2;
	END IF;
	
    
END */$$
DELIMITER ;

/* Procedure structure for procedure `post_target_achievement` */

/*!50003 DROP PROCEDURE IF EXISTS  `post_target_achievement` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `post_target_achievement`(
	)
BEGIN
	
	DECLARE salesman_code VARCHAR(50);
	DECLARE route_code VARCHAR(50);
	
	DECLARE done INT DEFAULT FALSE;
		
	DECLARE cur_one CURSOR FOR 
		(SELECT DISTINCT salesmancode, routecode 
			FROM routegoal WHERE CURDATE() BETWEEN fromdate AND todate ORDER BY 1);
	
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
	
	OPEN cur_one;
	read_loop_one: LOOP
		
		FETCH cur_one INTO salesman_code, route_code;
			
		IF done = TRUE THEN
			LEAVE read_loop_one;
		END IF;
		
		CALL `post_target_tables` (salesman_code, route_code);
		
	END LOOP read_loop_one;
	
	CLOSE cur_one;
	
		
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `post_target_salesmanachievement` */

/*!50003 DROP PROCEDURE IF EXISTS  `post_target_salesmanachievement` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `post_target_salesmanachievement`(
	IN var_salesmancode BIGINT(20)
	)
BEGIN
	
	DECLARE goal_key VARCHAR(50);
	DECLARE route_code VARCHAR(50);
	DECLARE pack_no VARCHAR(50);
	DECLARE from_date VARCHAR(50);
	DECLARE to_date VARCHAR(50);
	DECLARE goal_qty VARCHAR(50);
	DECLARE target_type VARCHAR(50);
	
	
	DECLARE invoice VARCHAR(100) DEFAULT CONCAT("temp_target_inv_",var_salesmancode);
	DECLARE inventory VARCHAR(100) DEFAULT CONCAT("temp_target_ith_",var_salesmancode);
	DECLARE custopsctl VARCHAR(100) DEFAULT CONCAT("temp_target_coc_",var_salesmancode);
	DECLARE routseqsts VARCHAR(100) DEFAULT CONCAT("temp_target_rs_",var_salesmancode);
	
	
	DECLARE done INT DEFAULT FALSE;
		
	DECLARE cur_one CURSOR FOR 
		(
		SELECT primary_key, routecode, packagenumber, fromdate, todate, quantity, targettype
		FROM routegoal
		WHERE salesmancode = var_salesmancode AND CURDATE() BETWEEN fromdate AND todate
		);
	
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
	
	OPEN cur_one;
	read_loop_one: LOOP
		
		FETCH cur_one INTO goal_key, route_code, pack_no, from_date, to_date, goal_qty, target_type;
			
		IF done = TRUE THEN
			LEAVE read_loop_one;
		END IF;
		
		SET @achievequantity = 0; SET @achieveamount = 0; SET @todayachieved = 0;
		SET @dailybalance = 0; SET @monthlybalance = 0;
		
		SELECT COALESCE(COUNT(*),1) INTO @workingdays FROM targetcalender WHERE calday <> 'Friday';
		SELECT COALESCE(COUNT(*),1) INTO @balancedays FROM targetcalender WHERE caldate>= CURDATE() AND calday <> 'Friday';		
		SELECT COALESCE(COUNT(*),1) INTO @passdays FROM targetcalender WHERE caldate<= CURDATE() AND calday <> 'Friday';
			
		IF target_type = 1 THEN		
			SET @sql1 = CONCAT("SELECT 0 qtyachieved, 
				COALESCE(SUM(id.salesqty-id.returnqty),0) amountachieved,
				COALESCE(SUM(CASE WHEN id.transactiondate = CURDATE() THEN (id.salesqty-id.returnqty) ELSE 0 END),0) todayachieved
			INTO @achievequantity, @achieveamount, @todayachieved
			FROM ", invoice," id
				INNER JOIN itemmaster im ON im.actualitemcode = id.itemcode AND im.packagecode = ", pack_no," 
				INNER JOIN startendday sed ON sed.routekey = id.routekey AND sed.routeclosed = 1
			WHERE id.transactiondate BETWEEN '", from_date,"' AND '", to_date,"'");
			
			SET @sql2 = "";
				
		ELSEIF target_type = 2 THEN		
			SET @sql1 = CONCAT("SELECT 0 qtyachieved, 
				COALESCE(SUM((FLOOR((id.salesqty-id.returnqty)/ im.unitspercase) * id.salescaseprice) + (((id.salesqty-id.returnqty) MOD im.unitspercase) * id.salesprice)),0) amountachieved,
				COALESCE(SUM(CASE WHEN id.transactiondate = CURDATE() THEN (FLOOR((id.salesqty-id.returnqty)/ im.unitspercase) * id.salescaseprice) + (((id.salesqty-id.returnqty) MOD im.unitspercase) * id.salesprice) ELSE 0 END),0) todayachieved
			INTO @achievequantity, @achieveamount, @todayachieved
			FROM ", invoice," id
				INNER JOIN itemmaster im ON im.actualitemcode = id.itemcode AND im.packagecode = ", pack_no," 
				INNER JOIN startendday sed ON sed.routekey = id.routekey AND sed.routeclosed = 1
			WHERE id.transactiondate BETWEEN '", from_date,"' AND '", to_date,"'");
		
			SET @sql2 = "";
			
		ELSEIF target_type = 3 THEN		
			
			SET @sql1 = CONCAT("SELECT 0 qtyachieved, 
				COALESCE(SUM(arh.amountpaid),0) amountachieved,
				COALESCE(SUM(CASE WHEN arh.transactiondate = CURDATE() THEN arh.amountpaid ELSE 0 END),0) todayachieved
			INTO @achievequantity, @achieveamount, @todayachieved
			FROM arheader arh 
				INNER JOIN startendday sed ON sed.routekey = arh.routekey AND sed.routeclosed = 1
			WHERE arh.voidflag = 0 AND arh.salesmancode= ", var_salesmancode," AND 
				arh.transactiondate BETWEEN '", from_date,"' AND '", to_date,"' ");
				
			SET @sql2 = CONCAT("SELECT COALESCE(SUM(CASE WHEN duedate <= CURDATE() THEN invoicebalance ELSE 0 END),0) dailybalance,
				COALESCE(SUM(invoicebalance),0) monthlybalance
			INTO @dailybalance, @monthlybalance
			FROM customerinvoice 
			WHERE salesmancode = ", var_salesmancode," AND duedate <= LAST_DAY(CURDATE()) AND voidflag = 0 AND invoicebalance != 0");
			
		ELSEIF target_type = 4 THEN		
			SET @sql1 = CONCAT("SELECT 0 qtyachieved, 
				COUNT(DISTINCT CONCAT(coc.customercode,coc.visitstartdate)) visitachieved,
				COALESCE(COUNT(DISTINCT CASE WHEN coc.visitstartdate = CURDATE() THEN CONCAT(coc.customercode,coc.visitstartdate) ELSE 0 END),0) todayachieved
			INTO @achievequantity, @achieveamount, @todayachieved
			FROM ", custopsctl," coc
				INNER JOIN ", routseqsts," rs ON rs.routekey = coc.routekey AND rs.customercode = coc.customercode AND 
					coc.visitstartdate BETWEEN '", from_date,"' AND '", to_date,"' 
				INNER JOIN startendday sed ON sed.routekey = coc.routekey AND sed.routeclosed = 1");
			
			SET @sql2 = "";
			
		ELSEIF target_type = 5 THEN		
			SET @sql1 = CONCAT("SELECT 0 qtyachieved, 
				COUNT(DISTINCT CONCAT(coc.customercode,coc.visitstartdate)) visitachieved,
				COALESCE(COUNT(DISTINCT CASE WHEN coc.visitstartdate = CURDATE() THEN CONCAT(coc.customercode,coc.visitstartdate) ELSE 0 END),0) todayachieved
			INTO @achievequantity, @achieveamount, @todayachieved
			FROM ", custopsctl," coc
				INNER JOIN ", routseqsts," rs ON rs.routekey = coc.routekey AND rs.customercode = coc.customercode AND
					coc.visitstartdate BETWEEN '", from_date,"' AND '", to_date,"' 
					INNER JOIN ", invoice," ih ON ih.routekey = coc.routekey AND ih.visitkey = coc.visitkey 
				INNER JOIN startendday sed ON sed.routekey = coc.routekey AND sed.routeclosed = 1");
			
			SET @sql2 = "";
				
		ELSEIF target_type = 6 THEN		
			SET @sql1 = CONCAT("SELECT 0 qtyachieved,
				COALESCE(SUM((FLOOR(id.quantity/ im.unitspercase) * im.caseprice) + ((id.quantity MOD im.unitspercase) * im.defaultsalesprice)),0) damageachieved,
				COALESCE(SUM(CASE WHEN id.transactiondate = CURDATE() THEN (FLOOR(id.quantity/ im.unitspercase) * im.caseprice) + ((id.quantity MOD im.unitspercase) * im.defaultsalesprice) ELSE 0 END),0) todayachieved
			INTO @achievequantity, @achieveamount, @todayachieved
			FROM ", inventory," id 				
				INNER JOIN itemmaster im ON im.actualitemcode = id.itemcode AND im.packagecode = ", pack_no," 
				INNER JOIN retitmreasons rr ON rr.code = id.reasoncode AND rr.hhcdescription <> ''
				INNER JOIN startendday sed ON sed.routekey = id.routekey AND sed.routeclosed = 1
			WHERE id.transactiondate BETWEEN '", from_date,"' AND '", to_date,"'");
				
			SET @sql2 = CONCAT("SELECT 
				COALESCE(SUM((FLOOR(id.salesqty/ im.unitspercase) * id.salescaseprice) + ((id.salesqty MOD im.unitspercase) * id.salesprice)),0) salesachieved
			INTO @sales
			FROM ", invoice," id
				INNER JOIN itemmaster im ON im.actualitemcode = id.itemcode AND im.packagecode = ", pack_no," 
				INNER JOIN startendday sed ON sed.routekey = id.routekey AND sed.routeclosed = 1
			WHERE id.transactiondate BETWEEN '", from_date,"' AND '", to_date,"'");			
			
		ELSEIF target_type = 7 THEN		
			SET @sql1 = CONCAT("SELECT 0 qtyachieved, 
				COUNT(DISTINCT id.customercode) amountachieved,
				COALESCE(COUNT(DISTINCT CASE WHEN id.transactiondate <= CURDATE() THEN id.customercode ELSE 0 END),0) todayachieved
			INTO @achievequantity, @achieveamount, @todayachieved
			FROM ", invoice," id				
				INNER JOIN startendday sed ON sed.routekey = id.routekey AND sed.routeclosed = 1
				INNER JOIN (SELECT customercode, COUNT(mslitem) mslcount
					FROM tmp_invoice 
					WHERE mslitem > 0 AND transactiondate BETWEEN '", from_date,"' AND '", to_date,"'
					GROUP BY customercode) msl ON msl.customercode = id.customercode
			WHERE id.transactiondate BETWEEN '", from_date,"' AND '", to_date,"' AND msl.mslcount > 10");
			
			SET @sql2 = "";
			
		ELSE		
			SET @achievequantity = 0;
			SET @achieveamount = 0;
			
		END IF;
		
		PREPARE s1 FROM @sql1;
		EXECUTE s1;
		
		IF @sql2 <> '' THEN
			PREPARE s2 FROM @sql2;
			EXECUTE s2;
		END IF;
		
		UPDATE routegoal SET 
			achievequantity= @achieveamount, 
			achieveamount= @achieveamount, 
			mdat= NOW(),
			quantity = CASE WHEN targettype = 3 THEN @monthlybalance WHEN targettype = 6 THEN (@sales*0.5)/100 ELSE quantity END
		WHERE salesmancode= var_salesmancode AND fromdate = from_date AND todate = to_date AND packagenumber = pack_no AND targettype = target_type;		
		IF target_type = 1 OR target_type = 2 THEN	
			UPDATE routegoal SET 
				todaysgoal= CASE WHEN (quantity-@achieveamount) < 0 THEN 0 ELSE ROUND((quantity-@achieveamount)/@balancedays,0) END,
				dailytarget= CASE WHEN quantity < 0 THEN 0 ELSE ROUND(quantity/@workingdays,0) END,
				progressivetarget= CASE WHEN quantity < 0 THEN 0 ELSE ROUND(quantity/@balancedays,0) END,
				asontarget= CASE WHEN quantity < 0 THEN 0 ELSE ROUND(quantity/@workingdays,0) END,
				mtdtarget= CASE WHEN quantity < 0 THEN 0 ELSE quantity END,			
				dailyvalue= 0,
				progressivevalue= @todayachieved,
				asonvalue= @todayachieved,
				mtdvalue= @achieveamount
			WHERE salesmancode= var_salesmancode AND fromdate = from_date AND todate = to_date AND packagenumber = pack_no AND targettype = target_type;		
		
		ELSEIF target_type = 3 THEN	
			UPDATE routegoal SET 
				todaysgoal= @dailybalance,
				dailytarget= @dailybalance,
				progressivetarget= @dailybalance,
				asontarget= @dailybalance,
				mtdtarget= @monthlybalance,
				dailyvalue= 0,
				progressivevalue= @todayachieved,
				asonvalue= @todayachieved,
				mtdvalue= @achieveamount			
			WHERE salesmancode= var_salesmancode AND fromdate = from_date AND todate = to_date AND packagenumber = pack_no AND targettype = target_type;		
		
		ELSEIF target_type = 4 OR target_type = 5 THEN	
			UPDATE routegoal SET 
				todaysgoal= CASE WHEN quantity < 0 THEN 0 ELSE ROUND(quantity/@workingdays,0) END,
				dailytarget= CASE WHEN quantity < 0 THEN 0 ELSE ROUND(quantity/@workingdays,0) END,
				progressivetarget= CASE WHEN quantity < 0 THEN 0 ELSE ROUND(quantity/@workingdays,0) END,
				asontarget= CASE WHEN quantity < 0 THEN 0 ELSE ROUND(quantity/@workingdays,0) END,
				mtdtarget= CASE WHEN quantity < 0 THEN 0 ELSE quantity END,			
				dailyvalue= 0,
				progressivevalue= @todayachieved,
				asonvalue= @todayachieved,
				mtdvalue= @achieveamount
			WHERE salesmancode= var_salesmancode AND fromdate = from_date AND todate = to_date AND packagenumber = pack_no AND targettype = target_type;			
		
		ELSEIF target_type = 6 THEN	
			UPDATE routegoal SET 
				todaysgoal= CASE WHEN (quantity-@achieveamount) < 0 THEN 0 ELSE ROUND((quantity-@achieveamount)/@balancedays,0) END,
				dailytarget= CASE WHEN quantity < 0 THEN 0 ELSE ROUND(quantity/@workingdays,0) END,
				progressivetarget= CASE WHEN quantity < 0 THEN 0 ELSE ROUND(quantity/@balancedays,0) END,
				asontarget= CASE WHEN quantity < 0 THEN 0 ELSE ROUND(quantity/@workingdays,0) END,
				mtdtarget= CASE WHEN quantity < 0 THEN 0 ELSE quantity END,			
				dailyvalue= 0,
				progressivevalue= @todayachieved,
				asonvalue= @todayachieved,
				mtdvalue= @achieveamount
			WHERE salesmancode= var_salesmancode AND fromdate = from_date AND todate = to_date AND packagenumber = pack_no AND targettype = target_type;		
		
		ELSEIF target_type = 7 THEN	
			UPDATE routegoal SET 
				todaysgoal= CASE WHEN (quantity-@achieveamount) < 0 THEN 0 ELSE ROUND((quantity-@achieveamount)/@balancedays,0) END,
				dailytarget= CASE WHEN quantity < 0 THEN 0 ELSE ROUND(quantity/@workingdays,0) END,
				progressivetarget= CASE WHEN quantity < 0 THEN 0 ELSE ROUND(quantity/@balancedays,0) END,
				asontarget= CASE WHEN quantity < 0 THEN 0 ELSE ROUND(quantity/@workingdays,0) END,
				mtdtarget= CASE WHEN quantity < 0 THEN 0 ELSE quantity END,			
				dailyvalue= 0,
				progressivevalue= @todayachieved,
				asonvalue= @todayachieved,
				mtdvalue= @achieveamount
			WHERE salesmancode= var_salesmancode AND fromdate = from_date AND todate = to_date AND packagenumber = pack_no AND targettype = target_type;	
			
		END IF;
					
		
	END LOOP read_loop_one;
	
	CLOSE cur_one;
	
		
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `post_target_tables` */

/*!50003 DROP PROCEDURE IF EXISTS  `post_target_tables` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `post_target_tables`(
	IN var_salesmancode BIGINT(20),
	IN var_routecodecode BIGINT(20)
	)
BEGIN
DECLARE invoice VARCHAR(100) DEFAULT CONCAT("temp_target_inv_",var_salesmancode);
DECLARE inventory VARCHAR(100) DEFAULT CONCAT("temp_target_ith_",var_salesmancode);
DECLARE custopsctl VARCHAR(100) DEFAULT CONCAT("temp_target_coc_",var_salesmancode);
DECLARE routseqsts VARCHAR(100) DEFAULT CONCAT("temp_target_rs_",var_salesmancode);
SELECT DATE_FORMAT(CURDATE() ,'%Y-%m-01'), LAST_DAY(CURDATE()) INTO @startdate, @enddate;
SET @temptable = CONCAT("DROP TABLE IF EXISTS ",invoice);
PREPARE qry1 FROM @temptable ;
EXECUTE qry1;
SET @tempscript =  CONCAT("CREATE TABLE IF NOT EXISTS ", invoice, " AS 
	SELECT ih.routekey, ih.visitkey, ih.transactionkey, ih.routecode, ih.invoicenumber, ih.transactiondate, ih.customercode,
		id.itemcode, id.salesqty, id.returnqty, id.damagedqty, 
		id.salesprice, id.returnprice, id.salescaseprice, id.returncaseprice,
		COALESCE(msl.itemcode, 0) mslitem
	FROM invoiceheader ih 
		INNER JOIN routemaster rm ON rm.routecode = ih.routecode 
		INNER JOIN invoicedetail id ON id.transactionkey = ih.transactionkey		
		LEFT OUTER JOIN itemmustdetail msl ON msl.itemmustcode = rm.itemmustkey AND msl.itemcode = id.itemcode
	WHERE ih.voidflag= 0 AND ih.salesmancode= ", var_salesmancode," AND 
		ih.transactiondate BETWEEN '", @startdate ,"' AND '", @enddate, "'");
PREPARE qry1 FROM @tempscript;
EXECUTE qry1;
SET @temptable = CONCAT("DROP TABLE IF EXISTS ",inventory);
PREPARE qry1 FROM @temptable ;
EXECUTE qry1;
SET @tempscript =  CONCAT("CREATE TABLE IF NOT EXISTS ", inventory, " AS 
	SELECT ith.routekey, ith.detailkey, ith.transactiondate, itd.itemcode, itd.quantity, itd.itemprice, itd.itemcaseprice, itd.reasoncode
	FROM inventorytransactionheader ith
		INNER JOIN inventorytransactiondetail itd ON itd.detailkey = ith.detailkey AND ith.voidflag = 0
	WHERE itd.transactiontypecode = 2 AND ith.salesmancode= ", var_salesmancode," AND 
		ith.transactiondate BETWEEN '", @startdate ,"' AND '", @enddate, "'");
PREPARE qry1 FROM @tempscript;
EXECUTE qry1;
SET @temptable = CONCAT("DROP TABLE IF EXISTS ",custopsctl);
PREPARE qry1 FROM @temptable ;
EXECUTE qry1;
SET @tempscript =  CONCAT("CREATE TABLE IF NOT EXISTS ", custopsctl, " AS 
	SELECT routekey, visitkey, routecode, customercode, DATE_FORMAT(visitstartdate,'%Y-%m-%d') visitstartdate, totaltransactions, reasoncode
	FROM customeroperationscontrol
	WHERE salesmancode= ", var_salesmancode," AND DATE_FORMAT(visitstartdate,'%Y-%m-%d') BETWEEN '", @startdate ,"' AND '", @enddate, "'");
PREPARE qry1 FROM @tempscript;
EXECUTE qry1;
SET @temptable = CONCAT("DROP TABLE IF EXISTS ",routseqsts);
PREPARE qry1 FROM @temptable ;
EXECUTE qry1;
SET @tempscript =  CONCAT("CREATE TABLE IF NOT EXISTS ", routseqsts, " AS 
	SELECT rs.routekey, rs.seqweeknumber, rs.seqweekday, 
		rs.customercode, rs.sequencenumber, rs.schelduledflag, rs.servicedflag
	FROM startendday sed
		INNER JOIN routesequencecustomerstatus rs ON rs.routekey = sed.routekey
	WHERE sed.salesmancode= ", var_salesmancode," AND 
		COALESCE(DATE_FORMAT(sed.routeenddate,'%Y-%m-%d'),CURDATE()) BETWEEN '", @startdate ,"' AND '", @enddate, "'");
PREPARE qry1 FROM @tempscript;
EXECUTE qry1;
SET @temptable = CONCAT("DROP TABLE IF EXISTS targetcalender");
PREPARE qry1 FROM @temptable ;
EXECUTE qry1;
SET @tempscript =  CONCAT("CREATE TABLE IF NOT EXISTS targetcalender AS 
	SELECT CURDATE() caldate,'ABCDEFGHIJKLMNOPQRSTUVWXYZ' calday");
PREPARE qry1 FROM @tempscript;
EXECUTE qry1;
DELETE FROM targetcalender;
CALL buildtargetcalender (@startdate, @enddate);
CALL `post_target_salesmanachievement` (var_salesmancode);
CALL `post_suggestedqty` (var_salesmancode, var_routecodecode);
SET @temptable = CONCAT("DROP TABLE IF EXISTS ",invoice);
PREPARE qry1 FROM @temptable ;
EXECUTE qry1;
SET @temptable = CONCAT("DROP TABLE IF EXISTS ",inventory);
PREPARE qry1 FROM @temptable ;
EXECUTE qry1;
SET @temptable = CONCAT("DROP TABLE IF EXISTS ",custopsctl);
PREPARE qry1 FROM @temptable ;
EXECUTE qry1;
SET @temptable = CONCAT("DROP TABLE IF EXISTS ",routseqsts);
PREPARE qry1 FROM @temptable ;
EXECUTE qry1;
SET @temptable = CONCAT("DROP TABLE IF EXISTS targetcalender");
PREPARE qry1 FROM @temptable ;
EXECUTE qry1;
END */$$
DELIMITER ;

/* Procedure structure for procedure `procInsertCustomerInvoice` */

/*!50003 DROP PROCEDURE IF EXISTS  `procInsertCustomerInvoice` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `procInsertCustomerInvoice`()
BEGIN
 
 DELETE FROM customerinvoice;	
	INSERT INTO CustomerInvoice(TransactionKey,TransactionType,DocumentNumber,InvoiceNumber,TransactionDate,CustomerCode,
RouteCode,
SalesmanCode,TotalInvoiceAmount,TotalSalesAmount,InvoiceBalance,PaymentType,VoidFlag,PaymentStatus,HHCInvoiceNumber,
Remarks1,Remarks2,RouteStartDate,ERPReferenceNumber,MDat,AmountPaid,duedate)
SELECT  @curRank := @curRank + 1 AS 'rank',2 AS transactiontype,@curRank  AS docnumber,
@curRank  AS invoicenumber,transaction_date,
 sfacst.customercode  ,rm.routecode,
rm.salesmancode,total_invoice_amount,total_invoice_amount,invoice_balance,2,0,0,total_invoice_amount,refernce,
'Balance from ERP',NULL,invoice_number,NOW(),
total_invoice_amount-invoice_balance,
(CASE
    WHEN sfacst.CreditTerms='DFS' THEN DATE_ADD(DATE_FORMAT(transaction_date + INTERVAL 1 MONTH,'%Y-%m-01'),INTERVAL sfacst.statementdays DAY ) 
    ELSE DATE_ADD(transaction_date,INTERVAL sfacst.statementdays DAY )
END)
 AS duedate
FROM temp_customerinvoice rec 
INNER JOIN customermaster sfacst ON sfacst.alternatecode  =rec.customer_code
AND sfacst.customercode IS NOT NULL
INNER JOIN routemaster rm ON rm.alternateroutecode=rec.route_code
INNER JOIN (SELECT @curRank := 0) r ON 1=1;
 
END */$$
DELIMITER ;

/* Procedure structure for procedure `proc_TEMP_STRIKE` */

/*!50003 DROP PROCEDURE IF EXISTS  `proc_TEMP_STRIKE` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `proc_TEMP_STRIKE`(
    IN vardivisioncode VARCHAR(500),
    IN varMonth INT,
    IN varYear INT
    )
BEGIN
 
IF vardivisioncode = '0' THEN
INSERT INTO TTS_STRIKE_YTD 
SELECT rm.divisioncode,sm.salesmancode AS salesmancode,sm.salesmanname1,  sm.arbsalesmanname1, 
0 AS Mtd_odometer,
0 AS plannedcalls, 
0 AS actualcalls, 0 AS unschedulecall,
0 AS cashsale, 0 AS creditsale , 
0 AS orders,
0 AS `returns`,
0 AS productivecalls, 
0 AS totalreceipt,
0 AS strikerate,
0 AS productiverate,
0 AS CustomerFaceTime,
0 AS OTPUsedCount,
0 AS settlementskipeddays,
0 AS CFTMin, varMonth
FROM startendday sed	
INNER JOIN routemaster rm ON sed.routecode = rm.routecode
INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
WHERE 1=1  AND MONTH (sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear  
GROUP BY sed.routecode  ;
ELSE
 
INSERT INTO TTS_STRIKE_YTD 
SELECT rm.divisioncode,sm.salesmancode AS salesmancode,sm.salesmanname1,  sm.arbsalesmanname1, 
0 AS Mtd_odometer,
0 AS plannedcalls, 
0 AS actualcalls, 0 AS unschedulecall,
0 AS cashsale, 0 AS creditsale , 
0 AS orders, 
0 AS `RETURNS`, 
0 AS productivecalls, 
0 AS totalreceipt,
0 AS strikerate,
0 AS productiverate,
0 AS CustomerFaceTime,
0 AS OTPUsedCount,
0 AS settlementskipeddays,
0 AS CFTMin, varMonth
FROM startendday sed	
INNER JOIN routemaster rm ON sed.routecode = rm.routecode
INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
INNER JOIN divisionmaster dm ON dm.divisionname=rm.divisioncode
WHERE FIND_IN_SET(dm.divisioncode, vardivisioncode) AND MONTH (sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear  
GROUP BY sed.routecode  ;
END IF;
UPDATE TTS_STRIKE_YTD t INNER JOIN (
SELECT salesmancode,SUM(CASE WHEN routeendodometer =0 THEN 0 ELSE IFNULL(routeendodometer-routestartodometer,0) END) AS mtdodometer 
FROM startendday sed1
WHERE MONTH (sed1.routestartdate) = varMonth AND YEAR(sed1.routestartdate) = varYear GROUP BY salesmancode 
) u
ON t.salesmancode=u.salesmancode
SET t.Mtd_odometer=u.mtdodometer where route_month = varMonth ;
UPDATE TTS_STRIKE_YTD t INNER JOIN (
SELECT  Salesmancode,SUM(callcount) AS plannedcalls FROM (
SELECT sed1.salesmancode,rs.routekey ,COUNT(*) AS callcount FROM routesequencecustomerstatus rs 
INNER JOIN startendday sed1 ON rs.routekey=sed1.routekey AND sed1.routecode=rs.routecode 
WHERE rs.schelduledflag = 1 AND 
MONTH (sed1.routestartdate) = varMonth AND YEAR(sed1.routestartdate) = varYear
GROUP BY rs.routekey,rs.customercode)t
GROUP BY salesmancode
) u
ON t.salesmancode=u.salesmancode
SET t.plannedcalls=u.plannedcalls WHERE route_month = varMonth;
UPDATE TTS_STRIKE_YTD t INNER JOIN (
SELECT  Salesmancode,SUM(callcount) AS ActualCalls FROM (
SELECT sed1.salesmancode,rs.routekey ,COUNT(*) AS callcount FROM routesequencecustomerstatus rs 
INNER JOIN startendday sed1 ON rs.routekey=sed1.routekey AND sed1.routecode=rs.routecode 
WHERE rs.servicedflag  = 1 AND 
MONTH (sed1.routestartdate) = varMonth AND YEAR(sed1.routestartdate) = varYear
GROUP BY rs.routekey,rs.customercode)t
GROUP BY salesmancode
) u
ON t.salesmancode=u.salesmancode
SET t.actualcalls=u.ActualCalls WHERE route_month = varMonth;
UPDATE TTS_STRIKE_YTD t INNER JOIN 
(SELECT ih.salesmancode,COUNT(*) AS cashSalescount  FROM INVOICEHEader ih 
INNER JOIN startendday sed ON sed.routekey=ih.routekey AND sed.routecode=ih.routecode 
INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
WHERE  ih.immediatepaid > 0 AND ih.voidflag = 0  AND (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear)  GROUP BY ih.salesmancode) 
 u
ON t.salesmancode=u.salesmancode
SET t.cashsale=u.cashSalescount WHERE route_month = varMonth;
UPDATE TTS_STRIKE_YTD t INNER JOIN 
(SELECT ih.salesmancode,COUNT(*) AS creditsale  FROM INVOICEHEader ih 
INNER JOIN startendday sed ON sed.routekey=ih.routekey AND sed.routecode=ih.routecode 
INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
WHERE  ih.immediatepaid =0 AND totalsalesamount>0 AND ih.voidflag = 0  AND (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear)  GROUP BY ih.salesmancode )
 u
ON t.salesmancode=u.salesmancode
SET t.creditsale=u.creditsale WHERE route_month = varMonth;
UPDATE TTS_STRIKE_YTD t INNER JOIN 
(SELECT ih.salesmancode,COUNT(*) AS grvcount  FROM INVOICEHEader ih 
INNER JOIN startendday sed ON sed.routekey=ih.routekey AND sed.routecode=ih.routecode 
INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
WHERE ih.totalinvoiceamount < 0  AND ih.totalsalesamount=0  AND ih.voidflag = 0  AND (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear)  GROUP BY ih.salesmancode )
 u
ON t.salesmancode=u.salesmancode
SET t.returns=u.grvcount WHERE route_month = varMonth;
UPDATE TTS_STRIKE_YTD t INNER JOIN 
(SELECT ih.salesmancode,COUNT(*) AS ordercount  FROM Salesorderheader ih 
INNER JOIN startendday sed ON sed.routekey=ih.routekey AND sed.routecode=ih.routecode 
INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
WHERE ih.voidflag = 0  AND (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear)  GROUP BY ih.salesmancode )
 u
ON t.salesmancode=u.salesmancode
SET t.orders=u.ordercount WHERE route_month = varMonth;
UPDATE TTS_STRIKE_YTD t INNER JOIN (
SELECT  Salesmancode,SUM(callcount) AS unschedulecall FROM (
SELECT sed1.salesmancode,rs.routekey ,COUNT(*) AS callcount FROM routesequencecustomerstatus rs 
INNER JOIN startendday sed1 ON rs.routekey=sed1.routekey AND sed1.routecode=rs.routecode 
WHERE rs.servicedflag = 1 AND  rs.schelduledflag = 0  AND 
MONTH (sed1.routestartdate) = varMonth AND YEAR(sed1.routestartdate) = varYear
GROUP BY rs.routekey,rs.customercode)t
GROUP BY salesmancode
) u
ON t.salesmancode=u.salesmancode
SET t.unschedulecall=u.unschedulecall WHERE route_month = varMonth;
UPDATE TTS_STRIKE_YTD t INNER JOIN 
(SELECT ah.salesmancode,COUNT(*) AS receipts  FROM arheader ah 
INNER JOIN startendday sed ON ah.routekey= sed.routekey AND ah.routecode= sed.routecode 
INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
WHERE  1=1   AND (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear)  GROUP BY ah.salesmancode )
 u
ON t.salesmancode=u.salesmancode
SET t.totalreceipt=u.receipts WHERE route_month = varMonth;
 
 UPDATE TTS_STRIKE_YTD t INNER JOIN (
SELECT  Salesmancode,COUNT(DISTINCT customercode,routestartdate) AS productivecalls FROM (
SELECT  coc.Salesmancode,coc.customercode,sed.routestartdate FROM invoiceheader coc
INNER JOIN startendday sed ON coc.routecode = sed.routecode AND coc.routekey = sed.routekey
WHERE  (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear)
UNION
SELECT  coc.Salesmancode,customercode,sed.routestartdate FROM salesorderheader coc
INNER JOIN startendday sed ON coc.routecode = sed.routecode AND coc.routekey = sed.routekey
WHERE  (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear)
UNION
SELECT  coc.Salesmancode,customercode,sed.routestartdate FROM arheader coc
INNER JOIN startendday sed ON coc.routecode = sed.routecode AND coc.routekey = sed.routekey
WHERE  (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear))t  GROUP BY salesmancode
) u
ON t.salesmancode=u.salesmancode
SET t.productivecalls=u.productivecalls WHERE route_month = varMonth;
UPDATE TTS_STRIKE_YTD t INNER JOIN (	 
SELECT salesmancode,(((actualcalls)/plannedcalls)*100) AS strikerate FROM  TTS_STRIKE_YTD
 ) u
ON t.salesmancode=u.salesmancode
SET t.strikerate=u.strikerate WHERE route_month = varMonth;
	 
	 
UPDATE TTS_STRIKE_YTD t INNER JOIN 	 
(SELECT coc.`salesmancode`, 
SUM(TIMESTAMPDIFF(MINUTE,
STR_TO_DATE(CONCAT(STR_TO_DATE(visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
STR_TO_DATE(CONCAT(STR_TO_DATE(visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
)) CFTMin
FROM customeroperationscontrol coc INNER JOIN startendday sed ON sed.routekey=coc.routekey
WHERE (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear) 
GROUP BY  coc.salesmancode) 
u
ON t.salesmancode=u.salesmancode
SET t.CFTMin=u.CFTMin WHERE route_month = varMonth;
	 
UPDATE TTS_STRIKE_YTD t
SET t.CustomerFaceTime=TIME_FORMAT(SEC_TO_TIME(t.CFTMin*60),'%H:%i') WHERE route_month = varMonth;
  
UPDATE TTS_STRIKE_YTD t INNER JOIN 	 
(SELECT sm.`salesmancode`, COUNT(customercode) OTPUsedCount
FROM otplogdetail otp  
INNER JOIN routemaster rm ON rm.routecode=otp.routecode
INNER JOIN salesman sm ON sm.salesmancode=rm.salesmancode
WHERE (MONTH(otpdate) = varMonth AND YEAR(otp.otpdate) = varYear) 
GROUP BY  sm.salesmancode) 
u
ON t.salesmancode=u.salesmancode
SET t.OTPUsedCount=u.OTPUsedCount WHERE route_month = varMonth;
 
 
UPDATE TTS_STRIKE_YTD t INNER JOIN (
SELECT salesmancode,DATEDIFF(RouteEndDate,routestartdate) AS settlementskipeddays FROM startendday
WHERE DATEDIFF(RouteEndDate,routestartdate)>0  AND (MONTH(routestartdate) = varMonth AND YEAR(routestartdate) = varYear) 
 ) u
ON t.salesmancode=u.salesmancode
SET t.settlementskipeddays=u.settlementskipeddays;
UPDATE TTS_STRIKE_YTD t INNER JOIN (
SELECT salesmancode,((productivecalls)/(actualcalls)*100) AS productiverate FROM  TTS_STRIKE_YTD 
)u
ON t.salesmancode=u.salesmancode
SET t.productiverate=u.productiverate WHERE route_month = varMonth;
SELECT * FROM TTS_STRIKE_YTD;
END */$$
DELIMITER ;

/* Procedure structure for procedure `proc_tts_route_cust_analysis` */

/*!50003 DROP PROCEDURE IF EXISTS  `proc_tts_route_cust_analysis` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `proc_tts_route_cust_analysis`( IN var_divcode VARCHAR(10)
    )
BEGIN
		
	DECLARE strdate DATE;	
	DECLARE div_filter TEXT;
	IF var_divcode <> 0 then
		SET div_filter = concat(" where divisioncode = (SELECT DIVISIONNAME FROM DIVISIONMASTER WHERE DIVISIONCODE = '", var_divcode,"') ");
	else
		SET div_filter = "";
	end if;
	  
	select start_date into strdate from year_month_date where year = year(curdate()) and month = month(curdate());
	
	SET @dyn_sql1 = CONCAT(" SELECT divisioncode, rt AS routecode, routetype, arbroutename region, oldroute AS cust_count_beg, oldroute + newroute tot_cust, newroute AS added_cust, 
VISIT AS actual_visit, 
ROUND(SUCC / visit * 100,2) AS strke_rate, 
INVAMT AS mtd_sale, INVCOUNT, 
ROUND(INVAMT/(oldroute + newroute),0) AS avg_nps, 
INVCOUNTLT30 inv_lt_30, CUSTCOUNTLT12 cust_lt_12_lines, 
ROUND(succ/noofdays,0) AS avg_calls, 
ROUND(NOOFLINES/INVCOUNT,0) AS avg_lines, 0 as must_have_sku_sale, 
-- NOOFITEMS/INVCUST AS avg_sku,
ROUND(AVGSKU,0) AS AVGSKU,
( SELECT start_date FROM year_month_date WHERE YEAR = YEAR(CURDATE()) AND MONTH = MONTH(CURDATE()) ) AS startdate,
DATEOFRUN
FROM(
SELECT 
(SELECT divisioncode FROM routemaster WHERE routecode = rt) divisioncode,rt, 
(select routetype from temp_routesalesman where routecode = rt) routetype,
(SELECT arbroutename FROM routemaster WHERE routecode = rt) arbroutename,
-- ( SELECT DATEDIFF(curdate(), '",strdate, "' ) + 1) AS NOOFDAYS,
IFNULL(max(CASE WHEN TYPE = 'NOOFDAYS' THEN VALUE END),0) AS NOOFDAYS,
IFNULL(SUM(CASE WHEN TYPE = 'NEWROUTE' THEN VALUE END),0) AS NEWROUTE, 
IFNULL(SUM(CASE WHEN TYPE = 'OLDROUTE' THEN VALUE END),0) AS OLDROUTE, 
IFNULL(SUM(CASE WHEN TYPE = 'SUCC' THEN VALUE END),0) AS SUCC, 
IFNULL(SUM(CASE WHEN TYPE = 'VISIT' THEN VALUE END),0) AS VISIT, 
IFNULL(SUM(CASE WHEN TYPE = 'INVAMT' THEN VALUE END),0) AS INVAMT, 
IFNULL(SUM(CASE WHEN TYPE = 'INVCOUNT' THEN VALUE END),0) AS INVCOUNT, 
IFNULL(SUM(CASE WHEN TYPE = 'INVCOUNTLT30' THEN VALUE END),0) AS INVCOUNTLT30, 
IFNULL(SUM(CASE WHEN TYPE = 'CUSTCOUNTLT12' THEN VALUE END),0) AS CUSTCOUNTLT12, 
IFNULL(SUM(CASE WHEN TYPE = 'NOOFLINES' THEN VALUE END),0) AS NOOFLINES, 
IFNULL(SUM(CASE WHEN TYPE = 'NOOFITEMS' THEN VALUE END),0) AS NOOFITEMS,
IFNULL(SUM(CASE WHEN TYPE = 'INVCUST' THEN VALUE END),0) AS INVCUST,
IFNULL(SUM(CASE WHEN TYPE = 'AVGSKU' THEN VALUE END),0) AS AVGSKU,
IFNULL(max(CASE WHEN TYPE = 'DATEOFRUN' THEN VALUE END),0) AS DATEOFRUN
FROM(
SELECT 'NEWROUTE' TYPE,ROUTECODE rt, COUNT(*) VALUE FROM CUSTOMERMASTER WHERE CDAT BETWEEN '" , strdate , "' AND CURDATE() GROUP BY ROUTECODE
UNION
SELECT 'OLDROUTE' TYPE,ROUTECODE, COUNT(*) VALUE FROM CUSTOMERMASTER WHERE CDAT < '" , strdate , "' GROUP BY ROUTECODE
UNION
SELECT 'SUCC' TYPE, ROUTECODE, COUNT(*) VALUE FROM TTS_ROUTE_ANALYSIS_VISIT_succ WHERE VISITSTARTDATE BETWEEN '" , strdate , "' AND CURDATE() GROUP BY ROUTECODE
UNION
SELECT 'VISIT' TYPE, ROUTECODE, COUNT(distinct customercode) FROM TTS_ROUTE_ANALYSIS_VISIT_total WHERE VISITSTARTDATE BETWEEN '" , strdate , "' AND CURDATE() GROUP BY ROUTECODE
UNION
SELECT 'INVAMT' TYPE, ROUTECODE, SUM(totalinvoiceamount) FROM tts_route_analysis_invoice WHERE transactiondate BETWEEN '" , strdate , "' AND CURDATE() GROUP BY ROUTECODE
UNION
SELECT 'INVCOUNT' TYPE, ROUTECODE, COUNT(*) FROM tts_route_analysis_invoice WHERE transactiondate BETWEEN '" , strdate , "' AND CURDATE() GROUP BY ROUTECODE
UNION
SELECT 'INVCOUNTLT30' TYPE, ROUTECODE, COUNT(*) FROM tts_route_analysis_invoice WHERE transactiondate BETWEEN '" , strdate , "' AND CURDATE() AND totalinvoiceamount <30 GROUP BY ROUTECODE
UNION
SELECT 'CUSTCOUNTLT12' TYPE,ROUTECODE, COUNT(DISTINCT CUSTOMERCODE) FROM(
SELECT ROUTECODE, CUSTOMERCODE,INVOICENUMBER, COUNT(DISTINCT ITEMCODE) FROM tts_route_analysis_item WHERE transactiondate BETWEEN '" , strdate , "' AND CURDATE() 
GROUP BY ROUTECODE, CUSTOMERCODE,INVOICENUMBER HAVING COUNT(DISTINCT ITEMCODE) < 12
) A GROUP BY ROUTECODE 
UNION
SELECT 'NOOFLINES' TYPE, ROUTECODE, SUM(NOOFLINES) FROM tts_route_analysis_invoice WHERE transactiondate BETWEEN '" , strdate , "' AND CURDATE() GROUP BY ROUTECODE
UNION
SELECT 'NOOFITEMS' TYPE,  ROUTECODE, COUNT(DISTINCT ITEMCODE) FROM tts_route_analysis_item WHERE transactiondate BETWEEN '" , strdate , "' AND CURDATE() GROUP BY ROUTECODE
union 
SELECT 'INVCUST' type, routecode, COUNT(DISTINCT customercode) VALUE FROM tts_route_analysis_invoice WHERE transactiondate BETWEEN '" , strdate , "' AND CURDATE() GROUP BY routecode
union
SELECT 'AVGSKU' TYPE, routecode,AVG(itemcount) VALUE FROM(
	SELECT routecode,customercode, COUNT(DISTINCT itemcode) itemcount FROM TTS_ROUTE_ANALYSIS_ITEM WHERE transactiondate BETWEEN '" , strdate , "' AND CURDATE()
	GROUP BY routecode, customercode) a
	GROUP BY routecode
UNION
select 'DATEOFRUN' type, routecode, max(dateofrun) from tts_route_analysis_invoice group by routecode
UNION
SELECT 'NOOFDAYS' TYPE, ROUTECODE, COUNT(*) FROM STARTENDDAY WHERE ROUTESTARTDATE BETWEEN '" , strdate , "' AND CURDATE() GROUP BY ROUTECODE
) A
GROUP BY rt)b ", div_filter);
		PREPARE s1 FROM @dyn_sql1;
	
		EXECUTE s1;		
		
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `proc_tts_route_cust_data` */

/*!50003 DROP PROCEDURE IF EXISTS  `proc_tts_route_cust_data` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `proc_tts_route_cust_data`()
BEGIN
	truncate table tts_route_analysis_invoice;
	INSERT INTO tts_route_analysis_invoice
	SELECT h.routekey, h.visitkey, h.routecode, h.transactiondate, invoicenumber, h.customercode, totalinvoiceamount - ITEMLINETAXAMOUNT, COUNT(d.itemcode) nooflines, CURDATE() dateofrun
	FROM invoiceheader h 
	INNER JOIN INVOICEDETAIL D ON H.routekey = D.ROUTEKEY AND H.VISITKEY = D.VISITKEY AND H.transactionkey = D.TRANSACTIONKEY
	WHERE H.transactiondate >= '2023-01-01'
	GROUP BY h.transactiondate, invoicenumber, h.customercode, totalinvoiceamount;
	
	TRUNCATE TABLE TTS_ROUTE_ANALYSIS_VISIT;
	INSERT INTO TTS_ROUTE_ANALYSIS_VISIT
	SELECT ROUTEKEY, VISITKEY, ROUTECODE, VISITSTARTDATE, CUSTOMERCODE, TOTALTRANSACTIONS FROM CUSTOMEROPERATIONSCONTROL 
	WHERE VISITSTARTDATE >= '2023-01-01';
	
	truncate table TTS_ROUTE_ANALYSIS_VISIT_total;
	insert into TTS_ROUTE_ANALYSIS_VISIT_total
	SELECT DISTINCT ROUTECODE, VISITSTARTDATE, 
	CUSTOMERCODE FROM CUSTOMEROPERATIONSCONTROL 
	WHERE VISITSTARTDATE >= '2023-11-01';
	
	TRUNCATE TABLE TTS_ROUTE_ANALYSIS_VISIT_succ;
	insert into TTS_ROUTE_ANALYSIS_VISIT_succ
	SELECT DISTINCT ROUTECODE, VISITSTARTDATE, CUSTOMERCODE, SUM(TOTALTRANSACTIONS) FROM CUSTOMEROPERATIONSCONTROL 
	WHERE VISITSTARTDATE >= '2023-11-01' AND totaltransactions > 0	 GROUP BY ROUTECODE, VISITSTARTDATE, CUSTOMERCODE;
	
	TRUNCATE TABLE TTS_ROUTE_ANALYSIS_ITEM;
	INSERT INTO TTS_ROUTE_ANALYSIS_ITEM
	SELECT H.ROUTEKEY, H.`visitkey`,H.`routecode`, H.`transactiondate`, H.`invoicenumber`, H.CUSTOMERCODE, D.ITEMCODE, CURDATE()  
	FROM INVOICEHEADER H INNER JOIN INVOICEDETAIL D ON H.ROUTEKEY = D.ROUTEKEY AND H.VISITKEY = D.VISITKEY AND H.TRANSACTIONKEY = D.`transactionkey`
	WHERE H.TRANSACTIONdate >='2023-01-01';
 END */$$
DELIMITER ;

/* Procedure structure for procedure `recallpostsuggestedsalesinvoiceafterroutefilter` */

/*!50003 DROP PROCEDURE IF EXISTS  `recallpostsuggestedsalesinvoiceafterroutefilter` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `recallpostsuggestedsalesinvoiceafterroutefilter`(
	IN introutecode BIGINT(18))
BEGIN	
	
	DECLARE route_date DATETIME;
	
	BEGIN
	
		SELECT `status` INTO @sales_status FROM controlpanel WHERE flagid = 15;
	
		DELETE FROM suggestedsalesinvoice WHERE routecode = introutecode;		
	
		IF @sales_status = 1 THEN 	
		
			SELECT MAX(routeenddate) INTO route_date FROM startendday WHERE routeclosed = 1 AND routecode = introutecode;
			
			SELECT * FROM suggestedsalesinvoice WHERE routecode = introutecode;
			
			CALL postsuggestedsalesinvoiceNEW(route_date, introutecode);
			
			DELETE FROM suggestedsalesinvoice WHERE routecode = introutecode AND offtakeqty = 0;
		END IF; 
		
		CALL update_data_posting (introutecode);
	END;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_customersequence_addcustomer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_customersequence_addcustomer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_customersequence_addcustomer`(
	    IN customer_code text,
	    IN route_code bigint,
	    IN week_no int(4),
	    IN tot_row INT,
	    in createdby varchar(30)
	)
BEGIN
	DECLARE from_start	INT;
	DECLARE customer_id int;
	
	SET from_start = 1;    
	IF from_start != tot_row THEN
	WHILE from_start <= tot_row DO
	
		SET customer_id 	= split(customer_code,'$',from_start);
			
		INSERT INTO routesequence(rp32weeknumber,routecode,customercode)
			VALUES(week_no,route_code,customer_id);
		
		
		SET  from_start = from_start + 1;
		  
	END WHILE;
ELSE
	
        INSERT INTO routesequence(rp32weeknumber,routecode,customercode)
			VALUES(week_no,route_code,customer_code);
   
        END IF;  
	
	SELECT LAST_INSERT_ID() INTO @last_id;
	SELECT @last_id AS last_id;
	
	CALL sp_add_logmaster_information('1','Route Sequence','routesequence',@last_id,createdby,'Add');
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_customerseq_arrangecustomer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_customerseq_arrangecustomer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_customerseq_arrangecustomer`(		
	    IN route_code BIGINT,
	    IN week_no INT,
	    IN input_text TEXT,	  
	    IN customer_code TEXT,
	    IN createdby VARCHAR(30)
	)
BEGIN	
	
	DECLARE my_query TEXT;
	DECLARE customer_id VARCHAR(50);
	
    
  
    
    DELETE FROM routesequence   
    
						WHERE rp32weeknumber = week_no AND routecode = route_code AND 
						customercode IN (customer_code);
	
	
		SET @c2 = '';		
		SET customer_id 	= '';
		SET my_query 		= input_text;
		SET customer_id 	= customer_code;
		
		SET @sel_qry = CONCAT("select count(*) INTO @c2 from routesequence where rp32weeknumber = ",week_no," and routecode = ",route_code," and customercode = '",customer_id,"'");
		PREPARE sel FROM @sel_qry;
		EXECUTE sel;
		
		
		IF @c2 > 0 THEN 		
			SET @qry = CONCAT("UPDATE routesequence SET	",my_query," WHERE rp32weeknumber = ",week_no," AND routecode = ",route_code," AND customercode = '",customer_id,"'");
			
			SELECT primary_key INTO @last_id FROM routesequence WHERE rp32weeknumber = week_no AND routecode = route_code AND customercode = customer_id;			
			CALL sp_add_logmaster_information('1','Route Sequence','routesequence',@last_id,createdby,'Add');
			
		ELSEIF @c2 = 0 THEN 				
			SET @qry = CONCAT("INSERT INTO routesequence SET ",my_query);
			SELECT LAST_INSERT_ID() INTO @last_id;
			CALL sp_add_logmaster_information('1','Route Sequence','routesequence',@last_id,createdby,'Add');
			
		END IF;
		
		PREPARE s1 FROM @qry;
		EXECUTE s1;
		
		
		
		  
	
	
	
	
	
	
			
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_customerseq_copysequence` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_customerseq_copysequence` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_customerseq_copysequence`(		
	    IN from_week INT,
	    IN to_week INT,
	    IN from_day INT,
	    IN to_day INT,
	    IN route_code INT,
	    IN createdby VARCHAR(30)
	)
BEGIN	
	
	DECLARE from_start	INT;	
	DECLARE customer_id INT;
	
	SET @c2 = '';
	
	
	SET @qry1 = CONCAT("select count(*) INTO @c2 from routesequence where rp32weeknumber = ",from_week," and routecode = ",route_code);
	PREPARE res1 FROM @qry1;
	EXECUTE res1;
	
	
	
	IF @c2 > 0 THEN
	
		SET from_start = 1;
		
		
		SET @qry2 = CONCAT("SELECT COUNT(*),GROUP_CONCAT(customercode) into @counter,@customercodes FROM routesequence where rp32weeknumber = ",from_week," and routecode = ",route_code);
		PREPARE res2 FROM @qry2;
		EXECUTE res2;
		
		
		WHILE from_start <= @counter DO
			
			SET customer_id = split(@customercodes,',',from_start);
			
			
			SET @qry4 = CONCAT("SELECT COUNT(*) INTO @cnt from routesequence where rp32weeknumber = ",to_week," and customercode = ",customer_id," and routecode = ",route_code);
			PREPARE res4 FROM @qry4;
			EXECUTE res4;
			
			
			
			
			SET @to_day_name = get_day_seq(to_day);
			SET @fr_day_name = get_day_seq(from_day);
			
			IF @cnt > 0 THEN
				SET @qry5 = CONCAT("UPDATE routesequence AS a ,routesequence AS b
									SET  a.",@to_day_name," = b.",@fr_day_name,",a.callrestrictiondays",to_day," = 1
									WHERE a.customercode = b.customercode AND a.routecode = b.routecode AND a.rp32weeknumber = ",to_week," and b.rp32weeknumber = ",from_week," and b.routecode = ",route_code);
				
				PREPARE res5 FROM @qry5;
				EXECUTE res5;
				
				
				SELECT primary_key INTO @last_id FROM routesequence WHERE rp32weeknumber = to_week AND customercode = customer_id AND routecode = route_code;
				
				CALL sp_add_logmaster_information('1','Route Sequence','routesequence',@last_id,createdby,'Edit');
				
			 	
			ELSEIF @cnt = 0 THEN
				SET @qry6 = CONCAT("INSERT INTO routesequence (rp32weeknumber,routecode,customercode,callrestrictiondays",to_day,",",@to_day_name,")
									(SELECT ",to_week,",a.routecode,a.customercode,a.callrestrictiondays",from_day,",",@fr_day_name," FROM routesequence AS a
									WHERE a.rp32weeknumber = ",from_week," and routecode = ",route_code,")");
				
			 	PREPARE res6 FROM @qry6;
			 	EXECUTE res6;
			 	
			 	
			 	SELECT LAST_INSERT_ID() INTO @last_id;
			 	
				CALL sp_add_logmaster_information('1','Route Sequence','routesequence',@last_id,createdby,'Add');				
			
			END IF;
			
			SET  from_start = from_start + 1;
		END WHILE;
		SELECT '1' AS result; 
	ELSE
		SELECT '0' AS result; 
	END IF;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_customerseq_copysequenceall` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_customerseq_copysequenceall` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_customerseq_copysequenceall`(		
	    IN from_week INT,
	    IN to_week INT,
	    IN from_day INT,
	    IN to_day INT,
	    IN route_code INT,
	    IN createdby VARCHAR(30)
	)
BEGIN	
	
	DECLARE from_start	INT;	
	DECLARE customer_id INT;
	
	SET @c2 = '';
	
	
	SET @qry1 = CONCAT("select count(*) INTO @c2 from routesequence where rp32weeknumber = ",from_week," and routecode = ",route_code);
	PREPARE res1 FROM @qry1;
	EXECUTE res1;
	
	
	
	IF @c2 > 0 THEN
	
		SET from_start = 1;
		
		
		SET @qry2 = CONCAT("SELECT GROUP_CONCAT(customercode) into @customercodes FROM routesequence where rp32weeknumber = ",from_week," and routecode = ",route_code);
		PREPARE res2 FROM @qry2;
		EXECUTE res2;
				
		
		SET @qry3 = CONCAT("SELECT COUNT(*) into @counter FROM routesequence where rp32weeknumber = ",from_week," and routecode = ",route_code);
		PREPARE res3 FROM @qry3;
		EXECUTE res3;
		
		
		
		WHILE from_start <= @counter DO
			
			SET customer_id = split(@customercodes,',',from_start);
			
			
			SET @qry4 = CONCAT("SELECT COUNT(*) INTO @cnt from routesequence where rp32weeknumber = ",to_week," and customercode = ",customer_id," and routecode = ",route_code);
			PREPARE res4 FROM @qry4;
			EXECUTE res4;
			
			
			
			
			if @cnt > 0 then
				SET @qry5 = CONCAT("UPDATE routesequence AS a ,routesequence AS b 									
									SET a.callrestrictiondays1 = b.callrestrictiondays1,
										a.callrestrictiondays2 = b.callrestrictiondays2,
										a.callrestrictiondays3 = b.callrestrictiondays3,
										a.callrestrictiondays4 = b.callrestrictiondays4,
										a.callrestrictiondays5 = b.callrestrictiondays5,
										a.callrestrictiondays6 = b.callrestrictiondays6,
										a.callrestrictiondays7 = b.callrestrictiondays7,
										a.monseq = b.monseq,a.tueseq = b.tueseq,a.wedseq = b.wedseq,
										a.thuseq = b.thuseq,a.friseq = b.friseq,a.satseq = b.satseq,
										a.sunseq = b.sunseq
									WHERE a.customercode = b.customercode AND a.routecode = b.routecode 
										AND a.rp32weeknumber = ",to_week," and b.rp32weeknumber = ",from_week," 
										AND a.customercode = ",customer_id," and a.routecode = ",route_code);
				PREPARE res5 FROM @qry5;
				EXECUTE res5;
				
				
				SELECT primary_key INTO @last_id FROM routesequence WHERE rp32weeknumber = to_week AND customercode = customer_id AND routecode = route_code;
				
				CALL sp_add_logmaster_information('1','Route Sequence','routesequence',@last_id,createdby,'Edit');
				
			 	
			elseIF @cnt = 0 THEN
				SET @qry6 = CONCAT("INSERT INTO routesequence (rp32weeknumber,routecode,customercode,callrestrictiondays1,
										callrestrictiondays2,callrestrictiondays3,callrestrictiondays4,callrestrictiondays5,
										callrestrictiondays6,callrestrictiondays7,monseq,tueseq,wedseq,thuseq,friseq,satseq,sunseq)
									(SELECT ",to_week,",a.routecode,a.customercode,a.callrestrictiondays1,a.callrestrictiondays2,
										a.callrestrictiondays3,a.callrestrictiondays4,a.callrestrictiondays5,a.callrestrictiondays6,
										a.callrestrictiondays7,a.monseq,a.tueseq,a.wedseq,a.thuseq,a.friseq,a.satseq,
										a.sunseq FROM routesequence AS a
									WHERE a.rp32weeknumber = ",from_week," AND a.customercode = ",customer_id," and routecode = ",route_code,")");
									
			 	PREPARE res6 FROM @qry6;
			 	EXECUTE res6;
				
				
				SELECT LAST_INSERT_ID() INTO @last_id;
			 	
				CALL sp_add_logmaster_information('1','Route Sequence','routesequence',@last_id,createdby,'Add');
				
			end if;
			
			SET  from_start = from_start + 1;
		END WHILE;
		SELECT '1' AS result; 
	ELSE
		SELECT '0' AS result; 
	END IF;
END */$$
DELIMITER ;

