/* Procedure structure for procedure `sp_add_account_settlement_addcashreceipt` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_settlement_addcashreceipt` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_settlement_addcashreceipt`(
		IN route_code 		BIGINT(18),
	    IN salesman_code 	BIGINT(18),
	    IN cash_amt 		DECIMAL(18,4),
	    IN rec_amt 			DECIMAL(18,4),
	    IN chq_amt 			DECIMAL(18,4),
	    IN total_amt 		DECIMAL(18,4),
	    IN tran_date 		TEXT,
	    IN bank_code 		BIGINT(18),
	    IN slip_no 			VARCHAR(30),
	    IN createdby 		VARCHAR(30)	
	)
BEGIN
	DECLARE ih_trankey 		TEXT;
	DECLARE cnt_ih_trankey 	INT(11);
	DECLARE ah_trankey 		TEXT;
	DECLARE cnt_ah_trankey 	INT(11);
	DECLARE from_start 		INT DEFAULT 1;
	DECLARE tran_key 		BIGINT(28);
	DECLARE cnt_record 		INT(4) DEFAULT 0;
	declare docnumber 		bigint;
	
	SET tran_date = STR_TO_DATE(tran_date,'%d-%m-%Y');
	
	
	SELECT GROUP_CONCAT(ih.transactionkey),COUNT(*) INTO ih_trankey,cnt_ih_trankey FROM invoiceheader AS ih
		LEFT JOIN cashcheckdetail AS ccd ON ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey
		WHERE ih.paymenttype IN(0,4) AND ccd.typecode IN(0,1) AND ccd.transactiontype = 1 
		AND routecode = route_code AND salesmancode = salesman_code AND transactiondate = tran_date ;
	
	SELECT GROUP_CONCAT(ah.transactionkey),COUNT(*) INTO ah_trankey,cnt_ah_trankey FROM arheader AS ah
		LEFT JOIN cashcheckdetail AS ccd ON ccd.routekey = ah.routekey AND ccd.visitkey = ah.visitkey
		WHERE 1 =1 AND ccd.typecode IN(0,1) AND ccd.transactiontype = 2 AND routecode = route_code 
		AND salesmancode = salesman_code AND transactiondate = tran_date;
		
	
	
	INSERT INTO cashierreceiptheader SET
										tobankcode 		= bank_code,
										slipno 			= slip_no,
										paymentdate		= tran_date,
										routecode 		= route_code,
										salesmancode 	= salesman_code,
											cashamount 	= cash_amt,
										receiptamount 	= rec_amt,
											checkamount = chq_amt,
												total 	= total_amt,
												`date`  = tran_date;
		SELECT LAST_INSERT_ID() INTO @lastid;
		
		SET docnumber = CONCAT(route_code,LPAD(@lastid,5,'0'));
		
		UPDATE cashierreceiptheader SET documentnumber = docnumber
									WHERE primary_key = @lastid;
		
	
	WHILE from_start <= cnt_ih_trankey DO
		SET tran_key = NULL;
		SET tran_key = split(ih_trankey,',',from_start);
		
		SET @ins1 = CONCAT("INSERT INTO cashierreceiptdetails (transactionno,transactiondate,`type`,slipno,checkno,checkdate,bankcode,invoiceamount,
											paid,balance,routecode,salesmancode,`date`,pdcbalance,checkamount,checkstatus,
											paymenttype,routekey,visitkey,transactionkey,documentnumber,customercode)
										SELECT ih.invoicenumber,ih.transactiondate,ccd.typecode,'",slip_no,"',ccd.checknumber,ccd.checkdate,",bank_code,",
											ih.totalinvoiceamount,ih.amountpaid,ih.invoicebalance,",route_code,",",salesman_code,",'",tran_date,"',0,
											ccd.amount,ccd.chequestatusindicator,ccd.paymenttype,ih.routekey,ih.visitkey,ih.transactionkey,",docnumber,",ih.customercode
											FROM invoiceheader AS ih
											LEFT JOIN cashcheckdetail AS ccd ON ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey
											WHERE ih.transactionkey = ",tran_key);
 		PREPARE s1 FROM @ins1;
 	 	EXECUTE s1;		
		
		SET from_start = from_start + 1;
	END WHILE;
	
	
	SET from_start = 1;
	
	
	WHILE from_start <= cnt_ah_trankey DO
		SET tran_key = NULL;
		SET tran_key = split(ah_trankey,',',from_start);	
		
		
		SET @ins2 = CONCAT("INSERT INTO cashierreceiptdetails 
										(transactionno,transactiondate,`type`,slipno,checkno,checkdate,bankcode,invoiceamount,paid,balance,
										 routecode,salesmancode,`date`,pdcbalance,checkamount,checkstatus,paymenttype,routekey,visitkey,
										 transactionkey,documentnumber,customercode)
										 
										 SELECT ah.invoicenumber,ah.transactiondate,ccd.typecode,'",slip_no,"',ccd.checknumber,ccd.checkdate,",bank_code,",
											ah.totalinvoiceamount,ccd.amount,ah.invoicebalance,",route_code,",",salesman_code,",'",tran_date,"',0,
											ccd.amount,paymenttype,ccd.chequestatusindicator,ah.routekey,ah.visitkey,ah.transactionkey,",docnumber,",ah.customercode
											FROM arheader AS ah
											LEFT JOIN cashcheckdetail AS ccd ON ccd.routekey = ah.routekey AND ccd.visitkey = ah.visitkey
											WHERE ah.transactionkey = ",tran_key);
 		PREPARE s1 FROM @ins2;
 		EXECUTE s1;
		
		SET from_start = from_start + 1;		
	END WHILE; 
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_settlement_addpdcgrid_1` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_settlement_addpdcgrid_1` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_settlement_addpdcgrid_1`(
		IN route_code BIGINT(18),
	    IN salesman_code BIGINT(18),
	    IN tran_date VARCHAR(50),
	    IN bank_code BIGINT(18),
	    IN erprefno VARCHAR(50),
	    IN remark VARCHAR(50),	    
	    IN bank_date TEXT,
	    IN hdntrancode TEXT,
	    IN hdncnttrancode INT(4),	    
	    IN createdby VARCHAR(30),
	    IN bankrefno VARCHAR(50)
	)
BEGIN
	
	DECLARE tran_key BIGINT(28);
	DECLARE from_start INT(11) DEFAULT 1;	
	DECLARE invoice_no BIGINT(20);
	DECLARE tbl_type VARCHAR(10);
	DECLARE tmp_str VARCHAR(500);
	
	DECLARE cnt_inv INT DEFAULT 0;
	DECLARE invnumbers TEXT;
	DECLARE from_inner_start INT(11) DEFAULT 1;	
	
	SET tran_date = STR_TO_DATE(tran_date,'%d-%m-%Y');
	
	WHILE from_start <= hdncnttrancode DO
	
		SET tmp_str 	= split(hdntrancode,'$',from_start);
		SET tran_key 	= split(tmp_str,'_',1);
		SET tbl_type 	= split(tmp_str,'_',2);
	
		IF tbl_type = 'ah' THEN
		
				SELECT 	ah.transactiondate,ah.customercode,checknumber,checkdate,bankcode,amount,ah.invoicenumber,ah.totalinvoiceamount,ah.amountpaid,ah.invoicebalance,ad.pdcbalance 
				INTO	@transactiondate,@customercode,@chequeno,@chequedate,@bankcode,@chequeamount,@invoicenumber,@totalinvoiceamount,@amountpaid,@invoicebalance,@pdcbalance 
				FROM arheader AS ah
				LEFT JOIN ardetail AS ad ON ad.transactionkey = ah.transactionkey
				LEFT JOIN cashcheckdetail AS cd ON cd.routekey = ah.routekey AND cd.visitkey = ah.visitkey
				WHERE ah.transactionkey = tran_key;
				
				UPDATE ardetail SET pdcbalance = 0 WHERE transactionkey = tran_key;
								
				UPDATE cashcheckdetail ccd	
				LEFT OUTER JOIN arheader AS ah ON ccd.routekey = ah.routekey AND ccd.visitkey = ah.visitkey
				SET ccd.checkstatus = 1 ,typecode = 0
				WHERE ah.transactionkey = tran_key;
				
				
				INSERT INTO pdcclearenceheader  SET 	transactiondate 	= CURRENT_DATE(),
														routecode 			= route_code,
														salesmancode 		= salesman_code,
														customercode 		= @customercode,
														chequeno 			= @chequeno,
														chequedate 			= @chequedate,
														bankcode 			= @bankcode,
														chequeamount		= @chequeamount,
														chequeclearedbank	= bank_code,
														erpreferencenumber	= erprefno,
														remarks 			= remark,
														bankreferenceno 	= bankrefno,
														chequeclearedon 	= STR_TO_DATE(bank_date,'%d-%m-%Y');
				SELECT LAST_INSERT_ID() INTO @last_id;
				SELECT @last_id AS last_id;
				
				
				CALL sp_add_logmaster_information('1','PDC Cheque','pdcclearenceheader',@last_id,createdby,'Add');
				
				
				INSERT INTO pdcclearencedetail SET 		transactionkey		= @last_id,
														invoicenumber 		= @invoicenumber,
														invoiceddate		= @transactiondate,
														totalinvoiceamount	= @totalinvoiceamount,
														invoicebalance 		= @invoicebalance,
														amountpaid 			= @amountpaid,
														pdcamount			= @pdcbalance;	
	
		ELSEIF tbl_type = 'ih' THEN
		
			SELECT 	ih.transactiondate,ih.customercode,checknumber,checkdate,bankcode,amount,ih.invoicenumber,ih.totalinvoiceamount,ih.amountpaid,ih.invoicebalance,ih.amountpaid 
			INTO	@transactiondate,@customercode,@chequeno,@chequedate,@bankcode,@chequeamount,@invoicenumber,@totalinvoiceamount,@amountpaid,@invoicebalance,@pdcbalance 
			FROM invoiceheader ih
			LEFT JOIN cashcheckdetail AS ccd ON ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey
			WHERE ih.transactionkey = tran_key;
			
			UPDATE ardetail SET pdcbalance = 0 WHERE transactionkey = tran_key;
			
			UPDATE cashcheckdetail ccd	
				LEFT OUTER JOIN invoiceheader AS ih ON ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey
				SET ccd.checkstatus = 1 
				WHERE ih.transactionkey = tran_key;
				
			
			INSERT INTO pdcclearenceheader  SET 	transactiondate 	= CURRENT_DATE(),
													routecode 			= route_code,
													salesmancode 		= salesman_code,
													customercode 		= @customercode,
													chequeno 			= @chequeno,
													chequedate 			= @chequedate,
													bankcode 			= @bankcode,
													chequeamount		= @chequeamount,
													chequeclearedbank	= bank_code,
													erpreferencenumber	= erprefno,
													remarks 			= remark,
													bankreferenceno 	= bankrefno,
													chequeclearedon 	= STR_TO_DATE(bank_date,'%d-%m-%Y');
			SELECT LAST_INSERT_ID() INTO @last_id;
			SELECT @last_id AS last_id;
			
			CALL sp_add_logmaster_information('1','PDC Cheque','pdcclearenceheader',@last_id,createdby,'Add');
			
			
			INSERT INTO pdcclearencedetail SET 		transactionkey		= @last_id,
													invoicenumber 		= @invoicenumber,
													invoiceddate		= @transactiondate,
													totalinvoiceamount	= @totalinvoiceamount,
													invoicebalance 		= @invoicebalance,
													amountpaid 			= @amountpaid,
													pdcamount			= @pdcbalance;
			
			
			
			SELECT transactionkey,pdcbalance INTO @tran_key,@pdcbal FROM customerinvoice WHERE invoicenumber = @invoicenumber;
			UPDATE customerinvoice SET  invoicebalance=invoicebalance-@pdcbal,amountpaid=amountpaid+@pdcbal,pdcbalance = pdcbalance-@pdcbal
			WHERE transactionkey = @tran_key;
			
			select pdcbalance into @latestpdcbal from customerinvoice WHERE transactionkey = @tran_key;
			if @latestpdcbal = 0 then 			
				update customerinvoice SET pdcindicator=0,pdcdate = ''WHERE transactionkey = @tran_key;
			end if;
			
			
			UPDATE customermaster SET balance = balance-@pdcbal WHERE customercode = @customercode;
		
		ELSEIF tbl_type = 'be' THEN
			
					SELECT  bh.customercode,bc.checknumber,DATE_FORMAT(bc.checkdate,"%d-%m-%Y") AS checkdate,bc.bankcode,bc.amount,bc.transactionkey
					INTO	@customercode,@chequeno,@chequedate,@bankcode,@chequeamount,@transactionkey
					FROM bearheader AS bh						
						LEFT JOIN bearcashcheckdetail AS bc ON bc.transactionkey = bh.transactionkey			
						WHERE bh.transactionkey = tran_key;
						
					
					UPDATE bearheader SET pdcstatus	= 2 WHERE transactionkey = tran_key;
			
					
					UPDATE beardetail SET paymentmode = 0 WHERE transactionkey = tran_key;			
					
					UPDATE bearcashcheckdetail SET checkstatus = 1 WHERE transactionkey = @transactionkey;
					
					
					
					
					INSERT INTO pdcclearenceheader  SET 	transactiondate 	= CURRENT_DATE(),
															routecode 			= route_code,
															salesmancode 		= salesman_code,
															customercode 		= @customercode,
															chequeno 			= @chequeno,
															chequedate 			= @chequedate,
															bankcode 			= @bankcode,
															chequeamount		= @chequeamount,
															chequeclearedbank	= bank_code,
															erpreferencenumber	= erprefno,
															remarks 			= remark,
															bankreferenceno 	= bankrefno,
															chequeclearedon 	= STR_TO_DATE(bank_date,'%d-%m-%Y');
					SELECT LAST_INSERT_ID() INTO @last_id;
					SELECT @last_id AS last_id;
					
					CALL sp_add_logmaster_information('1','PDC Cheque','pdcclearenceheader',@last_id,createdby,'Add');
					
					SELECT COUNT(*),GROUP_CONCAT(invoicenumber) INTO cnt_inv,invnumbers FROM beardetail WHERE transactionkey = tran_key;
					
					SET from_inner_start = 1;
					WHILE from_inner_start <= cnt_inv DO
					
						SET invoice_no = split(invnumbers,',',from_inner_start);
						
						SELECT DATE_FORMAT(bh.transactiondate,"%d-%m-%Y") AS transactiondate,bd.totalinvoiceamount,bd.amountpaid,bd.invoicebalance,bd.amountpaid AS pdcbalance
						INTO	@transactiondate,@totalinvoiceamount,@amountpaid,@invoicebalance,@pdcbalance
						FROM bearheader AS bh
						LEFT JOIN beardetail AS bd ON bd.transactionkey = bh.transactionkey
						WHERE bd.transactionkey = tran_key AND bd.invoicenumber = invoice_no;
						
						
					
							INSERT INTO pdcclearencedetail SET 		transactionkey		= @last_id,
																	invoicenumber 		= invoice_no,
																	invoiceddate		= @transactiondate,
																	totalinvoiceamount	= @totalinvoiceamount,
																	invoicebalance 		= @invoicebalance,
																	amountpaid 			= @amountpaid,
																	pdcamount			= @pdcbalance;
							
							
							SELECT transactionkey,pdcbalance INTO @tran_key,@pdcbal FROM customerinvoice WHERE invoicenumber = invoice_no;
							UPDATE customerinvoice SET  invoicebalance=invoicebalance-@pdcbal,amountpaid=amountpaid+@pdcbal,pdcbalance = pdcbalance-@pdcbal
							WHERE transactionkey = @tran_key;
							
							SELECT pdcbalance INTO @latestpdcbal FROM customerinvoice WHERE transactionkey = @tran_key;
							IF @latestpdcbal = 0 THEN 			
								UPDATE customerinvoice SET pdcindicator=0,pdcdate = ''WHERE transactionkey = @tran_key;
							END IF;
							
							
							UPDATE customermaster SET balance = balance-@pdcbal WHERE customercode = @customercode;
					
						SET from_inner_start = from_inner_start + 1;
					END WHILE;
					
			ELSEIF tbl_type = 'dc' THEN
			
					SELECT dh.customercode,dc.checknumber,DATE_FORMAT(dc.checkdate,"%d-%m-%Y") AS checkdate,dc.bankcode,dc.amount,dc.transactionkey
					INTO	@customercode,@chequeno,@chequedate,@bankcode,@chequeamount,@transactionkey
					FROM dcarheader AS dh						
						LEFT JOIN dcarcashcheckdetail AS dc ON dc.transactionkey = dh.transactionkey			
						WHERE dd.transactionkey = tran_key AND dc.invoicenumber = invoice_no;
					
					
					UPDATE dcarheader SET pdcstatus	= 2 WHERE transactionkey = tran_key;
					
					
					UPDATE dcardetail SET paymentmode = 0 WHERE transactionkey = tran_key;
					
					UPDATE bearcashcheckdetail SET checkstatus = 1 WHERE transactionkey = @transactionkey;
					
					
					
					
					
					SELECT COUNT(*),GROUP_CONCAT(invoicenumber) INTO cnt_inv,invnumbers FROM dcardetail WHERE transactionkey = tran_key;
					
					INSERT INTO pdcclearenceheader  SET 	transactiondate 	= CURRENT_DATE(),
															routecode 			= route_code,
															salesmancode 		= salesman_code,
															customercode 		= @customercode,
															chequeno 			= @chequeno,
															chequedate 			= @chequedate,
															bankcode 			= @bankcode,
															chequeamount		= @chequeamount,
															chequeclearedbank	= bank_code,
															erpreferencenumber	= erprefno,
															remarks 			= remark,
															bankreferenceno 	= bankrefno,
															chequeclearedon 	= STR_TO_DATE(bank_date,'%d-%m-%Y');
					SELECT LAST_INSERT_ID() INTO @last_id;
					SELECT @last_id AS last_id;
					
					CALL sp_add_logmaster_information('1','PDC Cheque','pdcclearenceheader',@last_id,createdby,'Add');
					
					
					
					SELECT dh.customercode,dc.checknumber,DATE_FORMAT(dc.checkdate,"%d-%m-%Y") AS checkdate,dc.bankcode,
					dc.amount,dd.invoicenumber,dd.totalinvoiceamount,dd.amountpaid,dd.invoicebalance,
					dd.amountpaid AS pdcbalance,dc.transactionkey
					INTO	@transactiondate,@customercode,@chequeno,@chequedate,@bankcode,@chequeamount,
					@invoicenumber,@totalinvoiceamount,@amountpaid,@invoicebalance,@pdcbalance,@transactionkey
					FROM dcarheader AS dh
						LEFT JOIN dcardetail AS dd ON dd.transactionkey = dh.transactionkey
						LEFT JOIN dcarcashcheckdetail AS dc ON dc.transactionkey = dh.transactionkey			
						WHERE dd.transactionkey = tran_key AND dc.invoicenumber = invoice_no;
						
					SET from_inner_start = 1;
					WHILE from_inner_start <= cnt_inv DO
					
						SET invoice_no = split(invnumbers,',',from_inner_start);
						
						SELECT DATE_FORMAT(dh.transactiondate,"%d-%m-%Y") AS transactiondate,dd.totalinvoiceamount,dd.amountpaid,dd.invoicebalance,dd.amountpaid AS pdcbalance
						INTO	@transactiondate,@totalinvoiceamount,@amountpaid,@invoicebalance,@pdcbalance
						FROM dcarheader AS dh
						LEFT JOIN dcardetail AS dd ON dd.transactionkey = dh.transactionkey
						WHERE dd.transactionkey = tran_key AND dd.invoicenumber = invoice_no;
						
						
					
							INSERT INTO pdcclearencedetail SET 		transactionkey		= @last_id,
																	invoicenumber 		= invoice_no,
																	invoiceddate		= @transactiondate,
																	totalinvoiceamount	= @totalinvoiceamount,
																	invoicebalance 		= @invoicebalance,
																	amountpaid 			= @amountpaid,
																	pdcamount			= @pdcbalance;
							
							
							SELECT transactionkey,pdcbalance INTO @tran_key,@pdcbal FROM customerinvoice WHERE invoicenumber = invoice_no;
							UPDATE customerinvoice SET  invoicebalance=invoicebalance-@pdcbal,amountpaid=amountpaid+@pdcbal,pdcbalance = pdcbalance-@pdcbal
							WHERE transactionkey = @tran_key;
							
							SELECT pdcbalance INTO @latestpdcbal FROM customerinvoice WHERE transactionkey = @tran_key;
							IF @latestpdcbal = 0 THEN 			
								UPDATE customerinvoice SET pdcindicator=0,pdcdate = ''WHERE transactionkey = @tran_key;
							END IF;
							
							
							UPDATE customermaster SET balance = balance-@pdcbal WHERE customercode = @customercode;
					
						SET from_inner_start = from_inner_start + 1;
					END WHILE;
			
			END IF;
		SET from_start = from_start + 1;
	END WHILE;	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_settlement_addpdcgrid_2` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_settlement_addpdcgrid_2` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_settlement_addpdcgrid_2`(
		IN route_code BIGINT(18),
	    IN salesman_code BIGINT(18),
	    IN tran_date VARCHAR(50),
	    IN bank_code BIGINT(18),
	    IN erprefno VARCHAR(50),
	    IN remark VARCHAR(50),	    
	    IN bank_date TEXT,
	    IN hdntrancode TEXT,
	    IN hdncnttrancode INT(4),	    
	    IN createdby VARCHAR(30),
	    IN bankrefno VARCHAR(50)
	)
BEGIN
	
	DECLARE tran_key BIGINT(28);
	DECLARE from_start INT(11) DEFAULT 1;	
	DECLARE invoice_no BIGINT(20);
	DECLARE tbl_type VARCHAR(10);
	DECLARE tmp_str VARCHAR(500);
	
	DECLARE cnt_inv INT DEFAULT 0;
	DECLARE invnumbers TEXT;
	DECLARE from_inner_start INT(11) DEFAULT 1;	
	
	SET tran_date = STR_TO_DATE(tran_date,'%d-%m-%Y');
	
	WHILE from_start <= hdncnttrancode DO
		
		SET tmp_str 	= split(hdntrancode,'$',from_start);
		SET tran_key 	= split(tmp_str,'_',1);
		SET tbl_type 	= split(tmp_str,'_',2);
		SET invoice_no 	= split(tmp_str,'_',3);
		
			IF tbl_type = 'crd' THEN 
						
				SELECT 	ci.transactiondate,ci.customercode,checkno,checkdate,bankcode,checkamount,ci.invoicenumber,ci.totalinvoiceamount,ci.amountpaid,ci.invoicebalance,ci.pdcbalance
				INTO	@transactiondate,@customercode,@chequeno,@chequedate,@bankcode,@chequeamount,@invoicenumber,@totalinvoiceamount,@amountpaid,@invoicebalance,@pdcbalance 
				FROM customerinvoice AS ci
				LEFT JOIN cashierreceiptdetails AS crd ON crd.transactionno = ci.invoicenumber
				WHERE ci.invoicenumber = invoice_no GROUP BY ci.invoicenumber;
						
				
				INSERT INTO pdcclearenceheader  SET 	transactiondate 	= tran_date,
														routecode 			= route_code,
														salesmancode 		= salesman_code,
														customercode 		= @customercode,
														chequeno 			= @chequeno,
														chequedate 			= @chequedate,
														bankcode 			= @bankcode,
														chequeamount		= @chequeamount,
														chequeclearedbank	= bank_code,
														erpreferencenumber	= erprefno,
														remarks 			= remark,
														bankreferenceno 	= bankrefno,
														chequeclearedon 	= STR_TO_DATE(bank_date,'%d-%m-%Y');
				SELECT LAST_INSERT_ID() INTO @last_id;
				SELECT @last_id AS last_id;
				
				UPDATE cashierreceiptdetails SET `type` = 0 WHERE transactionno = invoice_no;
				
				
				CALL sp_add_logmaster_information('1','PDC Cheque','pdcclearenceheader',@last_id,createdby,'Add');
				
				
				INSERT INTO pdcclearencedetail SET 		transactionkey		= @last_id,
														invoicenumber 		= @invoicenumber,
														invoiceddate		= @transactiondate,
														totalinvoiceamount	= @totalinvoiceamount,
														invoicebalance 		= @invoicebalance,
														amountpaid 			= @amountpaid,
														pdcamount			= @pdcbalance;
				SET from_start = from_start + 1;
				
				
				UPDATE customerinvoice 
					SET amountpaid = amountpaid+@pdcbalance,pdcbalance = pdcbalance-@pdcbalance,
						invoicebalance = invoicebalance-@pdcbalance
				WHERE transactionkey = tran_key;
				
				SELECT pdcbalance INTO @latestpdcbal FROM customerinvoice WHERE transactionkey = tran_key;
				IF @latestpdcbal = 0 THEN 			
					UPDATE customerinvoice SET pdcindicator=0,pdcdate = ''WHERE transactionkey = tran_key;
				END IF;
				
				
				
				UPDATE customermaster SET balance = balance-@pdcbalance WHERE customercode = @customercode;			
			
			ELSEIF tbl_type = 'be' THEN
			
					SELECT  bh.customercode,bc.checknumber,bc.checkdate AS checkdate,bc.bankcode,bc.amount,bc.transactionkey
					INTO	@customercode,@chequeno,@chequedate,@bankcode,@chequeamount,@transactionkey
					FROM bearheader AS bh
						LEFT JOIN bearcashcheckdetail AS bc ON bc.transactionkey = bh.transactionkey			
						WHERE bh.transactionkey = tran_key;
						
					
					UPDATE bearheader SET pdcstatus	= 2 WHERE transactionkey = tran_key;
			
					
					UPDATE beardetail SET paymentmode = 0 WHERE transactionkey = tran_key;			
					
					UPDATE bearcashcheckdetail SET checkstatus = 1 WHERE transactionkey = @transactionkey;
					
					
					
					
					INSERT INTO pdcclearenceheader  SET 	transactiondate 	= tran_date,
															routecode 			= route_code,
															salesmancode 		= salesman_code,
															customercode 		= @customercode,
															chequeno 			= @chequeno,
															chequedate 			= @chequedate,
															bankcode 			= @bankcode,
															chequeamount		= @chequeamount,
															chequeclearedbank	= bank_code,
															erpreferencenumber	= erprefno,
															remarks 			= remark,
															bankreferenceno 	= bankrefno,
															chequeclearedon 	= STR_TO_DATE(bank_date,'%d-%m-%Y');
					SELECT LAST_INSERT_ID() INTO @last_id;
					SELECT @last_id AS last_id;
					
					CALL sp_add_logmaster_information('1','PDC Cheque','pdcclearenceheader',@last_id,createdby,'Add');
					SELECT COUNT(*),GROUP_CONCAT(invoicenumber) INTO cnt_inv,invnumbers FROM beardetail WHERE transactionkey = tran_key;
					
					SET from_inner_start = 1;
					WHILE from_inner_start <= cnt_inv DO
					
						SET invoice_no = '';
						SET invoice_no = split(invnumbers,',',from_inner_start);
						
						SELECT bh.transactiondate AS transactiondate,bd.totalinvoiceamount,bd.amountpaid,bd.invoicebalance,bd.amountpaid AS pdcbalance
						INTO	@transactiondate,@totalinvoiceamount,@amountpaid,@invoicebalance,@pdcbalance
						FROM bearheader AS bh
						LEFT JOIN beardetail AS bd ON bd.transactionkey = bh.transactionkey
						WHERE bd.transactionkey = tran_key AND bd.invoicenumber = invoice_no;
						
						
							INSERT INTO pdcclearencedetail SET 		transactionkey		= @last_id,
																	invoicenumber 		= invoice_no,
																	invoiceddate		= @transactiondate,
																	totalinvoiceamount	= @totalinvoiceamount,
																	invoicebalance 		= @invoicebalance,
																	amountpaid 			= @amountpaid,
																	pdcamount			= @pdcbalance;
							
							SELECT transactionkey,pdcbalance INTO @tran_key,@pdcbal FROM customerinvoice WHERE invoicenumber = invoice_no;
							UPDATE customerinvoice SET  invoicebalance=invoicebalance-@pdcbal,amountpaid=amountpaid+@pdcbal,pdcbalance = pdcbalance-@pdcbal
							WHERE transactionkey = @tran_key;
							
							SELECT pdcbalance INTO @latestpdcbal FROM customerinvoice WHERE transactionkey = @tran_key;
							IF @latestpdcbal = 0 THEN 			
								UPDATE customerinvoice SET pdcindicator=0,pdcdate = ''WHERE transactionkey = @tran_key;
							END IF;
							
							
							UPDATE customermaster SET balance = balance-@pdcbal WHERE customercode = @customercode;
					
						SET from_inner_start = from_inner_start + 1;
					END WHILE;
					
			ELSEIF tbl_type = 'dc' THEN
			
					SELECT dh.customercode,dc.checknumber,dc.checkdate AS checkdate,dc.bankcode,dc.amount,dc.transactionkey
					INTO	@customercode,@chequeno,@chequedate,@bankcode,@chequeamount,@transactionkey
					FROM dcarheader AS dh
						LEFT JOIN dcarcashcheckdetail AS dc ON dc.transactionkey = dh.transactionkey			
						WHERE dd.transactionkey = tran_key;
					
					
					UPDATE dcarheader SET pdcstatus	= 2 WHERE transactionkey = tran_key;
					
					
					UPDATE dcardetail SET paymentmode = 0 WHERE transactionkey = tran_key;
					
					UPDATE bearcashcheckdetail SET checkstatus = 1 WHERE transactionkey = @transactionkey;
					
					
					
					
					
					SELECT COUNT(*),GROUP_CONCAT(invoicenumber) INTO cnt_inv,invnumbers FROM dcardetail WHERE transactionkey = tran_key;
					
					INSERT INTO pdcclearenceheader  SET 	transactiondate 	= tran_date,
															routecode 			= route_code,
															salesmancode 		= salesman_code,
															customercode 		= @customercode,
															chequeno 			= @chequeno,
															chequedate 			= @chequedate,
															bankcode 			= @bankcode,
															chequeamount		= @chequeamount,
															chequeclearedbank	= bank_code,
															erpreferencenumber	= erprefno,
															remarks 			= remark,
															bankreferenceno 	= bankrefno,
															chequeclearedon 	= STR_TO_DATE(bank_date,'%d-%m-%Y');
					SELECT LAST_INSERT_ID() INTO @last_id;
					SELECT @last_id AS last_id;
					
					CALL sp_add_logmaster_information('1','PDC Cheque','pdcclearenceheader',@last_id,createdby,'Add');
											
					SET from_inner_start = 1;
					WHILE from_inner_start <= cnt_inv DO
						
						SET invoice_no = '';
						SET invoice_no = split(invnumbers,',',from_inner_start);
						
						SELECT dh.transactiondate AS transactiondate,dd.totalinvoiceamount,dd.amountpaid,dd.invoicebalance,dd.amountpaid AS pdcbalance
						INTO	@transactiondate,@totalinvoiceamount,@amountpaid,@invoicebalance,@pdcbalance
						FROM dcarheader AS dh
						LEFT JOIN dcardetail AS dd ON dd.transactionkey = dh.transactionkey
						WHERE dd.transactionkey = tran_key AND dd.invoicenumber = invoice_no;
						
						
					
							INSERT INTO pdcclearencedetail SET 		transactionkey		= @last_id,
																	invoicenumber 		= invoice_no,
																	invoiceddate		= @transactiondate,
																	totalinvoiceamount	= @totalinvoiceamount,
																	invoicebalance 		= @invoicebalance,
																	amountpaid 			= @amountpaid,
																	pdcamount			= @pdcbalance;
							
							
							SELECT transactionkey,pdcbalance INTO @tran_key,@pdcbal FROM customerinvoice WHERE invoicenumber = invoice_no;
							UPDATE customerinvoice SET  invoicebalance=invoicebalance-@pdcbal,amountpaid=amountpaid+@pdcbal,pdcbalance = pdcbalance-@pdcbal
							WHERE transactionkey = @tran_key;
							
							SELECT pdcbalance INTO @latestpdcbal FROM customerinvoice WHERE transactionkey = @tran_key;
							IF @latestpdcbal = 0 THEN 			
								UPDATE customerinvoice SET pdcindicator=0,pdcdate = ''WHERE transactionkey = @tran_key;
							END IF;
							
							
							UPDATE customermaster SET balance = balance-@pdcbal WHERE customercode = @customercode;
					
						SET from_inner_start = from_inner_start + 1;
					END WHILE;
			
			END IF;
		
	
		SET from_start = from_start + 1;
		
	END WHILE;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_settlement_bounce_pdccheque` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_settlement_bounce_pdccheque` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_settlement_bounce_pdccheque`(
		IN var_invoicecode 			TEXT,
		IN var_cntinvoicecode 		INT
    )
BEGIN
		DECLARE table_type 	VARCHAR(10);
		DECLARE tran_key 	BIGINT(18);
		DECLARE invoice_no 	BIGINT(18);
		DECLARE invoicestr  TEXT;
		
		DECLARE pdc_balance DECIMAL(18,4);
		DECLARE from_start INT(4) DEFAULT 1;
		
		WHILE from_start <= var_cntinvoicecode DO
			
			SET tran_key	= '';
			SET table_type 	= '';
			SET invoice_no 	= '';
			
			SET invoicestr  = split(var_invoicecode,'$',from_start);
			SET tran_key 	= split(invoicestr,'_',1);
			SET table_type 	= split(invoicestr,'_',2);
			SET invoice_no 	= split(invoicestr,'_',3);
			
			IF table_type = 'be' THEN
			
				SELECT amount INTO pdc_balance FROM bearcashcheckdetail WHERE transactionkey = tran_key;
				
				UPDATE bearcashcheckdetail SET checkstatus = 2 WHERE transactionkey = tran_key;
				
				
				UPDATE 	customerinvoice AS ci,
					(SELECT amountpaid,invoicenumber,transactionkey FROM beardetail WHERE transactionkey = tran_key) AS a
					SET pdcbalance		= (pdcbalance-a.amountpaid),
						pdcdate			= '0000-00-00'	
					WHERE a.invoicenumber = ci.invoicenumber AND a.transactionkey = tran_key;
				
				UPDATE 	customerinvoice
					SET pdcindicator 	= 0
					WHERE pdcbalance = 0 AND invoicenumber IN (SELECT invoicenumber FROM beardetail WHERE transactionkey = tran_key);
					
				SELECT invoice_no AS last_id;
				
			ELSEIF	table_type = 'dc' THEN
			
				SELECT amount INTO pdc_balance FROM dcarcashcheckdetail WHERE transactionkey = tran_key;
				
				UPDATE dcarcashcheckdetail SET checkstatus = 2 WHERE transactionkey = tran_key;
				
				
					
				UPDATE 	customerinvoice AS ci,
					(SELECT amountpaid,invoicenumber,transactionkey FROM dcardetail WHERE transactionkey = 6) AS a
					SET pdcbalance		= (pdcbalance-a.amountpaid),
						pdcdate			= '0000-00-00'	
					WHERE a.invoicenumber = ci.invoicenumber AND a.transactionkey = tran_key;	
					
				UPDATE 	customerinvoice
					SET pdcindicator 	= 0
					WHERE pdcbalance = 0 AND invoicenumber IN (SELECT invoicenumber FROM beardetail WHERE transactionkey = tran_key);
					
				SELECT invoice_no AS last_id;	
		
			ELSEIF	table_type = 'ah' THEN
		
				UPDATE cashcheckdetail ccd	
				LEFT OUTER JOIN arheader AS ah ON ccd.routekey = ah.routekey AND ccd.visitkey = ah.visitkey
				SET ccd.checkstatus = 2 
				WHERE ah.transactionkey = tran_key;
				
				SELECT tran_key AS last_id;
				
			ELSEIF	table_type = 'ih' THEN
		
				UPDATE cashcheckdetail ccd	
				LEFT OUTER JOIN invoiceheader AS ih ON ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey
				SET ccd.checkstatus = 2 
				WHERE ih.transactionkey = tran_key;
				
				SELECT tran_key AS last_id;
		
			END IF;
			
			SET from_start = from_start + 1;
			
		END WHILE;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_tax` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_tax` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_tax`(
	    IN description VARCHAR(50),
	    IN arbdescription VARCHAR(50),
	    IN tax_type INT,
	    IN tax_percentage DECIMAL(18,4),
	    IN tax_base INT,
	    IN created_by VARCHAR(50)
	  
	)
BEGIN
	
	INSERT INTO tbltaxmaster  SET 					taxdescription 				= description,
									arbtaxdescription 			= arbdescription,									
									taxtype 				= tax_type,									
									taxpercentage 				= tax_percentage,
									taxbase 				= tax_base,
									created 				= created_by,
									cdat 					= CURRENT_DATE(),
									mdat 					= CURRENT_DATE();
									
	SELECT LAST_INSERT_ID() INTO @last_id;
	SELECT @last_id AS last_id;
	CALL sp_add_logmaster_information('1','Tax','tbltaxmaster',@last_id,created_by,'Add');
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_transaction_addgccollection` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_transaction_addgccollection` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_transaction_addgccollection`(
		IN var_routeid 			BIGINT(18),
		IN var_salesmancode 	BIGINT(18),
		IN var_customercode 	BIGINT(18),
		IN var_trantype 		INT,
		IN var_amount			DECIMAL(19,4),
		IN var_totalinvoceamt 	DECIMAL(19,4),
		IN var_invono 			TEXT,
		IN var_cntinvo 			INT,
		IN var_paymode 			INT,
		IN var_checknum			DECIMAL(18,0),
		IN var_checkdate 		VARCHAR(50),
		IN var_bankcode 		BIGINT(18),
		IN var_trandate 		VARCHAR(50),
		IN var_created 			VARCHAR(30),
		IN var_erprefnum 		VARCHAR(30),
		IN var_hdninvoamt 		TEXT,
		IN var_isfifo 			INT(1)
    )
BEGIN
		DECLARE docid BIGINT(28);
		DECLARE curre_code BIGINT(18);
		DECLARE from_start INT DEFAULT 1;
		DECLARE invoice_no BIGINT(18);
		DECLARE var_invbal DECIMAL(18,4);
		DECLARE new_amtpaid DECIMAL(18,4);
		DECLARE totinvamt DECIMAL(18,4);
		DECLARE amtpaid DECIMAL(18,4);
		DECLARE invbal DECIMAL(18,4);
		DECLARE var_pdc_cash INT(1);
		
		SELECT getpdctocashstatus() INTO var_pdc_cash;
		
		
		CALL sp_edit_customer_balance_zero();
		SELECT get_default_currencycode_routecode(var_routeid) INTO curre_code;
		
		SET docid = CONCAT(var_routeid,"",get_acbodocseq_route(var_routeid));
				
		IF var_cntinvo > 1 THEN
			SELECT REPLACE(var_invono,'$',',') INTO @tran_ids;
		ELSE
			SELECT REPLACE(var_invono,'$','') INTO @tran_ids;
		END IF;	
		
		SET @q = CONCAT("SELECT SUM(totalinvoiceamount),SUM(amountpaid),SUM(invoicebalance)
				INTO @totalinvoiceamount,@amountpaid,@invoicebalance
				FROM customerinvoice WHERE transactionkey IN (",@tran_ids,")");
		PREPARE s1 FROM @q;
		EXECUTE s1;	
		
		INSERT INTO bearheader SET					
					routecode			= var_routeid,
					documentnumber 		= docid,
					salesmancode 		= var_salesmancode,
					customercode		= var_customercode,				
					`trantype`			= var_trantype,
					amountpaid			= var_amount,
					totalinvoiceamount  = @totalinvoiceamount,
					invoicebalance 		= (@totalinvoiceamount-(@amountpaid+var_amount)),
					transactiondate 	= STR_TO_DATE(var_trandate,'%d-%m-%Y'),
					transactiontime 	= CURRENT_TIME(),
					erpreferencenumber  = var_erprefnum,
					created 			= var_created,
					modified 			= var_created,
					cdat 				= CURRENT_DATE(),
					mdat 				= CURRENT_DATE(),
					currencycode 		= curre_code,
					pdcstatus 			= var_paymode;
					
		SELECT LAST_INSERT_ID() INTO @last_id;
		SELECT @last_id AS last_id;
		SELECT update_acbodocseq_route(var_routeid);
		
		
		SET var_amount = ABS(var_amount);
		
		
		CALL sp_add_logmaster_information('1','GC Collection','bearheader',@last_id,var_created,'Add');
		
		
		IF var_paymode = 0 OR var_pdc_cash = 1 THEN 			
			INSERT INTO bearcashcheckdetail SET
					transactionkey		= @last_id,
					typecode 			= 0,
					amount 				= var_amount,
					currencycode 		= curre_code;
		ELSEIF var_paymode = 1 AND var_pdc_cash = 0	THEN
			INSERT INTO bearcashcheckdetail SET
					transactionkey		= @last_id,
					typecode 			= var_paymode,
					checknumber 		= var_checknum,
					checkdate           = STR_TO_DATE(var_checkdate,'%d-%m-%Y'),
					bankcode 			= var_bankcode,
					amount 				= var_amount,
					currencycode 		= curre_code;
		ELSE
			INSERT INTO bearcashcheckdetail SET
					transactionkey		= @last_id,
					typecode 			= var_paymode,
					checknumber 		= var_checknum,
					checkdate           = STR_TO_DATE(var_checkdate,'%d-%m-%Y'),
					bankcode 			= var_bankcode,
					amount 				= var_amount,
					currencycode 		= curre_code;
		END IF;
		SET  @tmp = 0;
		WHILE from_start <= var_cntinvo DO
			IF var_amount IS NOT NULL OR var_isfifo = 0 THEN
				SET @trankey = split(@tran_ids,',',from_start);
					 
				SELECT invoicenumber,totalinvoiceamount,amountpaid,invoicebalance 
					INTO invoice_no ,totinvamt,amtpaid,invbal
					FROM customerinvoice WHERE transactionkey = @trankey;
					
				
				
				IF var_isfifo = 1 AND SIGN(invbal) = -1 THEN
					SET @invoamt = ABS(invbal);
				ELSEIF var_isfifo = 1 AND from_start > 1 THEN
					SET @invoamt = var_amount;
				ELSE
					SET @invoamt = split(var_hdninvoamt,'$',from_start);
				END IF;
					
				SET new_amtpaid = '';
				SET var_invbal	= 0.0000;
				IF 	ABS(@invoamt) >= ABS(invbal) THEN
					SET new_amtpaid = invbal;
				ELSE
					SET new_amtpaid = @invoamt;
					SET var_invbal  = (invbal-@invoamt);
				END IF;
				
				
				INSERT INTO beardetail SET
							transactionkey		= @last_id,
							customercode 		= var_customercode,
							invoicenumber   	= invoice_no,
							totalinvoiceamount  = totinvamt,
							amountpaid 			= new_amtpaid,
							invoicebalance 		= var_invbal,
							paymentmode 		= var_paymode,
							invoicedate     	= STR_TO_DATE(var_trandate,'%d-%m-%Y'),
							currencycode 		= curre_code;
				
								
				IF var_paymode = 0 OR var_pdc_cash = 1 THEN 
					
					UPDATE customerinvoice SET
							amountpaid 				= (amtpaid+new_amtpaid),
							invoicebalance			= invoicebalance-new_amtpaid
							WHERE invoicenumber 	= invoice_no;				
				ELSE
					UPDATE customerinvoice SET
							pdcindicator 			= 1,
							pdcbalance 				= pdcbalance+new_amtpaid,
							pdcdate 				= STR_TO_DATE(var_checkdate,'%d-%m-%Y')
							WHERE invoicenumber 	= invoice_no;
				END IF;				
				
				
				IF var_paymode = 0 OR var_pdc_cash = 1 THEN
					
					SELECT headofficecode INTO @headofficecode FROM customermaster WHERE `type` = 2 AND customercode = var_customercode;
					IF var_customercode != @headofficecode THEN 
						UPDATE customermaster SET balance = balance-new_amtpaid WHERE customercode = @headofficecode;
					END IF;
					UPDATE customermaster SET balance = balance-new_amtpaid WHERE customercode = var_customercode;
				END IF;
				
				SET  var_amount = (var_amount-new_amtpaid);
				
				IF var_amount = 0 AND var_isfifo = 1 THEN
					SET var_cntinvo	= 0;
				END IF;
			END IF;
			SET from_start = from_start + 1;
		END WHILE;
		
		IF var_amount > 0 THEN
			SELECT update_advpayment_customer_balance(var_customercode,var_amount);
		END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_transaction_addhocollection` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_transaction_addhocollection` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_transaction_addhocollection`(
		IN var_routeid 			BIGINT(18),
		IN var_salesmancode 	BIGINT(18),
		IN var_customercode 	BIGINT(18),
		IN var_trantype 		INT,
