				END IF;
				
				
				IF var_paymode = 0  OR var_pdc_cash = 1 THEN
					UPDATE customermaster SET balance = balance-new_amtpaid WHERE customercode IN (@custcode,var_customercode);					
				END IF;
				
				
				INSERT INTO beardetail SET
							transactionkey		= @last_id,
							customercode 		= @custcode,
							invoicenumber   	= invoice_no,
							totalinvoiceamount  = totinvamt,
							amountpaid 			= new_amtpaid,
							invoicebalance 		= var_invbal,
							paymentmode 		= var_paymode,
							invoicedate     	= STR_TO_DATE(var_trandate,'%d-%m-%Y'),
							currencycode 		= curre_code;
				
							
				IF var_paymode = 0  OR var_pdc_cash = 1 THEN 
					
					UPDATE customerinvoice SET
							amountpaid 				= (amtpaid+new_amtpaid),
							invoicebalance			= invoicebalance-new_amtpaid
							WHERE invoicenumber 	= invoice_no;				
				ELSE
					UPDATE customerinvoice SET
							pdcindicator 			= 1,
							pdcbalance 				= pdcbalance+new_amtpaid,
							pdcdate 				= STR_TO_DATE(var_checkdate,'%d-%m-%Y')
							WHERE invoicenumber 	= invoice_no;
				END IF;
				
				SET  var_amount = (var_amount-new_amtpaid);
				IF var_amount = 0 AND var_isfifo = 1 THEN
					SET var_cntinvo	= 0;
				END IF;
			END IF;
			SET from_start = from_start + 1;
		END WHILE;
		IF var_amount > 0 THEN
			SELECT update_advpayment_customer_balance(var_customercode,var_amount);			
		END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_transaction_addopeningbal` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_transaction_addopeningbal` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_transaction_addopeningbal`(
		IN var_routeid 		BIGINT(18),
		IN var_salesmancode BIGINT(18),
		IN var_customercode BIGINT(18),
		IN var_trantype 	INT,
		IN var_amount		DECIMAL(19,4),
		IN var_remark1		VARCHAR(50),
		IN var_remark2		VARCHAR(50),
		IN var_trandate 	VARCHAR(50),
		IN var_erprefno 	VARCHAR(30),
		IN var_created 		VARCHAR(30)
    )
BEGIN
		DECLARE docid BIGINT(28);
		DECLARE bal DECIMAL(18,4);
		
		SET docid = CONCAT(var_routeid,"",get_acbodocseq_route(var_routeid));
		SELECT get_paymentcode_currencycode(var_customercode) INTO @pay;
		SELECT get_default_currencycode_routecode(var_routeid) INTO @curr_code;
		
		
		CALL sp_edit_customer_balance_zero();
	
		INSERT INTO customerinvoice SET
					documentnumber 		= docid,
					invoicenumber  		= docid,					
					routecode			= var_routeid,
					salesmancode 		= var_salesmancode,
					customercode		= var_customercode,
					transactiontype		= var_trantype,
					paymenttype 		= @pay,
					transactiontime 	= TIME(CURRENT_DATE()),
					totalinvoiceamount  = var_amount,
					invoicebalance		= var_amount,
					amountpaid			= 0,
					transactiondate 	= STR_TO_DATE(var_trandate,'%d-%m-%Y'),
					remarks1			= var_remark1,
					remarks2			= var_remark2,
					erpreferencenumber 	= var_erprefno,
					currencycode 		= @curr_code,
					mdat 				= CURRENT_DATE();
		SELECT LAST_INSERT_ID() INTO @last_id;
		SELECT @last_id AS last_id;
		SELECT update_acbodocseq_route(var_routeid);
		
		
		
		UPDATE customermaster SET balance = balance + var_amount WHERE customercode = var_customercode;
		
		
		SELECT headofficecode INTO @headofficecode FROM customermaster WHERE `type` = 2 AND customercode = var_customercode;
		IF var_customercode != @headofficecode THEN 
			UPDATE customermaster SET balance = balance + var_amount WHERE customercode = @headofficecode;
		END IF;
		
		
		CALL sp_add_logmaster_information('1','Opening Balance','customerinvoice',@last_id,var_created,'Add');
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_transaction_monthclose` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_transaction_monthclose` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_transaction_monthclose`(
		
		in mmonth int,
		IN yyear INT
    )
BEGIN
	
	
	
	set @q1 = concat("select count(*) into @tot_customer_rec from monthlysummarizationpercustomer
		where bmonth = ",mmonth," and byear = ",yyear);
	prepare s1 from @q1;
	execute s1;
	
	
	SET @q2 = CONCAT("select count(*) into @tot_route_rec from monthlysummarizationperroute
		where bmonth = ",mmonth," and byear = ",yyear);
	PREPARE s1 FROM @q2;
	EXECUTE s1;
	
	
	SET @go = 0;
	
	IF @tot_customer_rec = 0 THEN 
		set @go = 1;
	elseif	@tot_route_rec = 0 then
		SET @go = 1;
	end if;
	if @go = 0 then 
		SELECT 'Failed' AS msg;	
	else
	
		insert into monthlysummarizationpercustomer 
		(	 customercode,
			 bmonth,
			 byear,
			 itemcode,
			 valueexpiryreturn,
			 valuebuyback,
			 valueonhand,
			 valuesales,
			 valueorder,
			 valuecontainerin,
			 valuecontainerout,
			 valuereturnsales,
			 valuefreegood,
			 valuebybackfree,
			 valuereplacement,
			 valuegiveaway,
			 quantityexpiryreturn,
			 quantitybuyback,
			 quantityonhand,
			 quantitysales,
			 quantityorder,
			 quantitycontainerin,
			 quantitycontainerout,
			 quantityreturnsales,
			 quantityfreegood,
			 quantitybybackfree,
			 quantityreplacement,
			 quantitygiveaway,
			 upc,
			 salesprice,
			 returnprice,
			 salescaseprice,
			 returncaseprice,
			 quantitymanualfree,
			 qunatitylimitedfree,
			 valuemanualfree,
			 valuelimitedfree,
			 valuedamage,
			 quantitydamage,
			 valuerentrebate,
			 quantityrentrebate
	   )
	   (
		SELECT
		  ih.customercode AS customercode,
		  mmonth    AS bmonth,
		  yyear     AS byear,
		  id.itemcode     AS itemcode,
		  SUM(id.expiryqty*id.returnprice) AS valueexpiryreturn,
		  SUM(id.returnqty*id.goodreturnprice) AS valuebuyback,
		  SUM((cid.shelfstockcase* im.caseprice)+(cid.shelfstockeach * im.defaultsalesprice)) AS valueonhand,
		  SUM(id.salesqty*id.salesprice) AS valuesales,
		  SUM(sod.salesqty*sod.salesprice) AS valueorder,
		  0               AS valuecontainerin,
		  0               AS valuecontainerout,
		  0               AS valuereturnsales,
		  SUM(id.freesampleqty*id.salesprice) AS valuefreegood,
		  SUM(id.returnfreeqty*id.goodreturnprice) AS valuebybackfree,
		  0 			  AS valuereplacement,
		  SUM(id.fixedrentqty*id.salesprice) AS valuegiveaway,
		  SUM(id.expiryqty) AS quantityexpiryreturn,
		  SUM(id.returnqty) AS quantitybuyback,
		  SUM((cid.shelfstockcase* im.unitspercase)+(cid.shelfstockeach)) AS quantityonhand,
		  SUM(id.salesqty) AS quantitysales,
		  SUM(sod.salesqty) AS quantityorder,
		  0 AS quantitycontainerin,
		  0 AS quantitycontainerout,
		  0 AS quantityreturnsales,
		  SUM(id.freesampleqty) AS quantityfreegood,
		  SUM(id.returnfreeqty) AS quantitybybackfree,
		  0 AS quantityreplacement,
		  SUM(id.fixedrentqty) AS quantitygiveaway,
		  im.unitspercase AS upc,
		  id.salesprice AS salesprice,
		  id.returnprice AS returnprice,
		  id.salescaseprice AS salescaseprice,
		  id.returncaseprice AS returncaseprice,
		  SUM(id.manualfreeqty) AS quantitymanualfree,
		  SUM(id.limitedfreeqty) AS qunatitylimitedfree,
		  SUM(id.manualfreeqty*id.salesprice) AS valuemanualfree,
		  SUM(id.limitedfreeqty*id.salesprice) AS valuelimitedfree,
		  SUM(id.damagedqty*id.returnprice) AS valuedamage,
		  SUM(id.damagedqty) AS quantitydamage,
		  SUM(id.rebaterentqty*id.salesprice) AS valuerentrebate,
		  SUM(id.rebaterentqty) AS quantityrentrebate
		  
		FROM invoiceheader AS ih
		  LEFT JOIN invoicedetail AS id
			ON id.transactionkey = ih.transactionkey
		  LEFT JOIN customerinventorydetail AS cid
			ON cid.routekey = ih.routekey
			  AND cid.visitkey = ih.visitkey
			  AND cid.itemcode = id.itemcode
		  LEFT JOIN salesorderdetail AS sod
			ON sod.routekey = ih.routekey
			  AND sod.visitkey = ih.visitkey
			  AND sod.itemcode = id.itemcode
		  LEFT JOIN itemmaster AS im
			ON im.actualitemcode = id.itemcode
		WHERE MONTH(ih.transactiondate) = mmonth AND YEAR(ih.transactiondate) = yyear
		GROUP BY ih.customercode,id.itemcode);
	
	
		INSERT INTO monthlysummarizationperroute
            (routecode,
             bmonth,
             byear,
             itemcode,
             valuebegininventory,
             valueload,
             valueloadadjust,
             valuetransfer,
             valuesales,
             valuebuybacks,
             valuereturnscredited,
             valuereturnsunloaded,
             valuetruckspoilage,
             valuefreshreturntostock,
             valuefreegood,
             valuebuybackfree,
             valuereplacement,
             valuegiveaway,
             valueendinginventory,
             quantitybegininventory,
             quantityload,
             quantityloadadjust,
             quantitytransfer,
             quantitysales,
             quantitybuybacks,
             quantityreturnscredited,
             quantityreturnsunloaded,
             quantitytruckspoilage,
             quantityfreshreturntostock,
             quantityfreegood,
             quantitybuybackfree,
             quantityreplacement,
             quantitygiveaway,
             quantityendinginventory,
             upc,
             salesprice,
             returnprice,
             salescaseprice,
             returncaseprice,
             quantityrentrebate,
             quantitydamage,
             valuerentrebate,
             valuedamage)
		SELECT
		  sed.routecode      AS routecode,
		  mmonth       AS bmonth,
		  yyear        AS byear,
		  im.actualitemcode  AS itemcode,
		  SUM(isd.beginstockqty * isd.stdsalesprice) AS valuebegininventory,
		  SUM(isd.loadqty * isd.stdsalesprice) AS valueload,
		  0                  AS valueloadadjust,
		  SUM((isd.loadaddqty-isd.loadcutqty)* isd.stdsalesprice) AS valuetransfer,
		  SUM(id.salesqty * id.salesprice) AS valuesales,
		  SUM(id.returnqty * id.goodreturnprice) AS valuebuybacks,
		  0                  AS valuereturnscredited,
		  SUM(isd.expunloadqty * isd.stdreturnprice) AS valuereturnsunloaded,
		  SUM(isd.truckdamagedunloadqty * isd.stdsalesprice) AS valuetruckspoilage,
		  SUM(isd.unloadqty * isd.stdsalesprice) AS valuefreshreturntostock,
		  SUM(id.freesampleqty*id.salesprice) AS valuefreegood,
		  SUM(id.returnfreeqty*id.goodreturnprice) AS valuebybackfree,
		  0                  AS valuereplacement,
		  SUM(id.fixedrentqty*id.salesprice) AS valuegiveaway,
		  SUM(isd.endstockqty*isd.stdsalesprice) AS valueendinginventory,
		  SUM(isd.beginstockqty) AS quantitybegininventory,
		  SUM(isd.loadqty)   AS quantityload,
		  0                  AS quantityloadadjust,
		  SUM(isd.loadaddqty-isd.loadcutqty) AS quantitytransfer,
		  SUM(id.salesqty)   AS quantitysales,
		  SUM(id.returnqty)  AS quantitybuyback,
		  0                  AS quantityreturnscredited,
		  SUM(isd.expunloadqty) AS quantityreturnsunloaded,
		  SUM(isd.truckdamagedunloadqty) AS quantitytruckspoilage,
		  SUM(isd.unloadqty) AS quantityfreshreturntostock,
		  SUM(id.freesampleqty) AS quantityfreegood,
		  SUM(id.returnfreeqty) AS quantitybuybackfree,
		  0                  AS quantityreplacement,
		  SUM(id.fixedrentqty) AS quantitygiveaway,
		  SUM(isd.endstockqty) AS quantityendinginventory,
		  im.unitspercase    AS upc,
		  id.salesprice      AS salesprice,
		  id.returnprice     AS returnprice,
		  id.salescaseprice  AS salescaseprice,
		  id.returncaseprice AS returncaseprice,
		  SUM(id.rebaterentqty) AS quantityrentrebate,
		  SUM(id.damagedqty) AS quantitydamage,
		  SUM(id.rebaterentqty*id.salesprice) AS valuerentrebate,
		  SUM(id.damagedqty*id.returnprice) AS valuedamage
		FROM invoicedetail AS id
		  LEFT JOIN invoiceheader AS ih
			ON ih.transactionkey = id.transactionkey
		  LEFT JOIN startendday AS sed
			ON sed.routekey = id.routekey
		  LEFT JOIN itemmaster AS im
			ON im.actualitemcode = id.itemcode
		  LEFT JOIN inventorysummarydetail AS isd
			ON isd.routekey = id.routekey
		WHERE MONTH(ih.transactiondate) = mmonth
			AND YEAR(ih.transactiondate) = yyear
		GROUP BY sed.routecode,id.itemcode;
		
		select 'Success' as msg;
		
	end if;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_adcollection_adcollectionadd` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_adcollection_adcollectionadd` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_adcollection_adcollectionadd`(
in var_customercode int,
in var_route_code int,
in var_salesman_code int,
in var_comment text,
in var_payment_mode int,
in var_textamount int,
in var_checkno int,
IN var_chk_date varchar(50),
in var_bank_no int,
IN var_total_amount int
)
BEGIN
DECLARE new_document_no VARCHAR(255);
DECLARE new_invoice_no VARCHAR(255);
declare new_visit_key int;
DECLARE new_route_key INT;
declare new_transaction_key int;
	
	 call sp_add_adcollection_genereate_document_no(var_route_code,@new_document_no,@new_invoice_no);
	
	 set new_invoice_no  =  @new_invoice_no;
	 SET new_document_no =  @new_document_no;
	 
		
	 CALL sp_add_adcollection_genereate_route_key(var_route_code,var_customercode,var_salesman_code,@visit_key,@route_key);
	SET new_visit_key  =  @visit_key;
	SET new_route_key  =  @route_key;
	
	call sp_add_adcollection_arheader(var_customercode,
					var_route_code,
					var_salesman_code,
					var_comment,
					var_textamount,
					new_route_key,
					new_visit_key,
					new_document_no,
					new_invoice_no,
					'',
					@var_transaction_key);
	set new_transaction_key = @var_transaction_key;
	
	
	 call sp_add_adcollection_cashcollection(
	 new_route_key,
	 new_visit_key,
	 var_payment_mode,var_checkno,var_textamount,var_chk_date,
	var_bank_no,new_transaction_key);
	
	
	
	 
	 
	 update customermaster set balance = balance +  var_textamount
	  where customercode =var_customercode;
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_adcollection_arheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_adcollection_arheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_adcollection_arheader`(
IN var_customercode INT,
IN var_route_code INT,
IN var_salesman_code INT,
IN var_comment TEXT,
IN var_textamount INT,
in in_route_key_code int,
in new_visit_key int,
in new_document_no varchar(50),
in new_invoice_no varchar(50),
IN customer_invoice_arr text,
OUt var_transaction_key int
)
BEGIN
declare new_transaction_key int;
	INSERT INTO arheader(
	routekey,visitkey,documentnumber,transactiondate,transactiontime,
	customercode,routecode,salesmancode,voidflag,invoicenumber,invoicebalance,
	amountpaid,totalinvoiceamount,advancepaymentflag,comments,currencycode) 
	VALUES(in_route_key_code,new_visit_key, new_document_no,DATE(CURRENT_DATE()),TIME(CURRENT_DATE()),
	var_customercode,var_route_code,var_salesman_code,0, new_invoice_no ,
	0 , var_textamount,var_textamount ,1,var_comment,get_default_currencycode_routecode(var_route_code)); 
	
	
	SELECT LAST_INSERT_ID() INTO new_transaction_key;
	set var_transaction_key = new_transaction_key;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_adcollection_cashcollection` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_adcollection_cashcollection` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_adcollection_cashcollection`(
in in_route_key_code int,
in in_visitkey int,
in var_payment_mode int,
in var_checkno int,
in var_textamount int,
in var_chk_date varchar(50),
IN var_bank_no int,
in new_transaction_key int
)
BEGIN
	INSERT INTO cashcheckdetail
	(	routekey,visitkey,typecode,checknumber,amount,checkdate,bankcode,currencycode,
		hhctransactionkey,transactiontype)
	
	values(	in_route_key_code,in_visitkey,var_payment_mode,var_checkno,var_textamount,
		STR_TO_DATE(var_chk_date,'%d-%m-%Y'),
		var_bank_no,get_default_currencycode(),new_transaction_key,2);
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_adcollection_genereate_document_no` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_adcollection_genereate_document_no` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_adcollection_genereate_document_no`(
in var_route_code int,
OUT  new_document_no varchar(50),
OUT  new_invoice_no varchar(50)
)
BEGIN
declare new_invoice_no1 int;
declare new_document_no1 int;
	UPDATE routemaster SET  boarseq = IFNULL(boarseq,0) + 1, bodocseq = IFNULL(bodocseq,0) + 1
	WHERE  routecode =var_route_code;
	
	SELECT  IFNULL(boarseq,0) AS  invoice_seq, IFNULL(bodocseq,0) AS document_seq
	INTO new_invoice_no1,new_document_no1
	FROM routemaster WHERE routecode =var_route_code;
	
	
	set new_document_no = CONCAT(var_route_code,"000000",new_document_no1 );
	set new_invoice_no  =  CONCAT(var_route_code,"700000",new_invoice_no1 );
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_adcollection_genereate_route_key` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_adcollection_genereate_route_key` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_adcollection_genereate_route_key`(
IN var_route_code int,
IN var_customercode int,
in var_salesman_code int,
OUT var_visit_key int,
Out var_route_key int
)
BEGIN
declare in_route_key_code1 int;
declare in_visit_key1 int;
	SELECT routekey INTO in_route_key_code1 FROM startendday 
	WHERE startendday.routecode=var_route_code
		AND startendday.routeclosed = 0
	ORDER BY routekey DESC  LIMIT 1	;
	
	set var_route_key = in_route_key_code1;
	
	SELECT IFNULL(MAX(customeroperationscontrol.visitkey),0) INTO in_visit_key1 FROM customeroperationscontrol
	WHERE  customeroperationscontrol.routekey =in_route_key_code1 ;
	
	SET in_visit_key1 =in_visit_key1 + 1;
	set var_visit_key  =  in_visit_key1;
	
	INSERT INTO customeroperationscontrol (visitkey,routekey,customercode,salesmancode,routecode,visitstartdate,
	visitstarttime,visitenddate,visitendtime,totaltransactions,voidflag)
	value(in_visit_key1,in_route_key_code1,var_customercode,var_salesman_code,var_route_code,date(CURRENT_DATE()),time(CURRENT_DATE()),
	DATE(CURRENT_DATE()),TIME(CURRENT_DATE()),1,0);
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_admin_index_index` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_admin_index_index` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_admin_index_index`(
	   Var_SetupID  INT,
	   Var_ConversionRate  DECIMAL(18,6),
           Var_CurrencySymbol  VARCHAR(10),
           Var_ArbCurrencySymbol VARCHAR(10),
           Var_JourneyPlanFlag INT,
           Var_RouteSequencePlanFlag INT,
           Var_WeekStartDay INT,
           Var_importfilepath VARCHAR(1000),
           Var_AllowControlonPrepareFilesFlag INT,
           Var_AllowNormalGCCollectionHHCFlag INT,
           Var_AllowPrepareFilesAfterUpload INT,
           Var_DefaultsOnPrepareFilesFlag INT,
           Var_ResendDatatoERPAllowed INT,
           Var_AllowCashInvoiceOnCreditCust INT,
           Var_CallRestrictionDaysFlag INT,
           Var_AllowMoreThanOneSalesman INT,
           Var_TransferInventoryFlag INT,
           Var_ENABLELOADREQUESTTOLOADOUT INT,
           Var_RestrictPrepareFile INT,
           Var_MultiDayPostingDate INT,
           Var_PreviousDayUploadFlag INT,
           var_tabletsyncmode INT,
           var_synctimeinterval INT,
           IN createdby VARCHAR(30)
    )
BEGIN
	INSERT INTO setup (     setupid,
				conversionrate,
				currencysymbol,
				arbcurrencysymbol,				
				journeyplanflag,
				routesequenceplanflag,
				weekstartday,
				importfilepath,
				allowcontrolonpreparefilesflag,
				allownormalgccollectionhhcflag,
				allowpreparefilesafterupload,
				defaultsonpreparefilesflag,
				resenddatatoerpallowed,
				allowcashinvoiceoncreditcust,
				callrestrictiondaysflag,
				allowmorethanonesalesman,
				transferinventoryflag,
				enableloadrequesttoloadout,
				restrictpreparefile,
				multidaypostingdate,
				previousdayuploadflag,
				tabletsyncmode,
				synctimeinterval,
				modifieddate)
			VALUES( Var_SetupID,
				Var_ConversionRate,
				Var_CurrencySymbol,
				Var_ArbCurrencySymbol,				
				Var_JourneyPlanFlag,
				Var_RouteSequencePlanFlag,
				Var_WeekStartDay,
				Var_importfilepath,
				Var_AllowControlonPrepareFilesFlag,
				Var_AllowNormalGCCollectionHHCFlag,
				Var_AllowPrepareFilesAfterUpload,
				Var_DefaultsOnPrepareFilesFlag,
				Var_ResendDatatoERPAllowed,
				Var_AllowCashInvoiceOnCreditCust,
				Var_CallRestrictionDaysFlag,
				Var_AllowMoreThanOneSalesman,
				Var_TransferInventoryFlag,
				Var_ENABLELOADREQUESTTOLOADOUT,
				Var_RestrictPrepareFile,
				Var_MultiDayPostingDate,
				Var_PreviousDayUploadFlag,
				var_tabletsyncmode,
				var_synctimeinterval,
				CURRENT_DATE());
				
	SELECT LAST_INSERT_ID() INTO @last_id;
	SELECT @last_id AS last_id;
	
	
	CALL sp_add_logmaster_information('1','Basic Setup','setup',@last_id,createdby,'Add');
	
	SELECT allowmorethanonesalesman FROM setup;
	
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_admin_security_adddevice` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_admin_security_adddevice` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_admin_security_adddevice`(
		IN deviceid VARCHAR(50),
		IN remark VARCHAR(50),
		IN createdBy VARCHAR(50)
	)
BEGIN
	SELECT COUNT(*) INTO @cmpt FROM tbl_device ;
	IF @cmpt < '500' THEN /*243 before added 6 license 203 before --- sujee added 5 more 25/10/2021 based on email request*/
			/*  ADDED 10 More License by Jyothish  on 02-01-2022, 208+10 = Total 218 License 
Added 25 more as per requested 31/01/2022			
			*/ 
				
			SELECT COUNT(*) INTO @cnt FROM tbl_device WHERE device_id = deviceid;
			
			IF @cnt = 0 THEN 
					INSERT INTO tbl_device (company_id, device_id, remarks) VALUES ('1', deviceid, remark);
				
					SELECT LAST_INSERT_ID() INTO @lastid;
				
					SELECT @lastid AS lastid;
				
					
					CALL sp_add_logmaster_information('1','Device Table','tbl_device',@lastid,createdBy,'Add');
				
			ELSE
					SELECT 0 AS lastid;		
					
			END IF;
			
		ELSE
		
			SELECT -1 AS lastid;		
	  END IF;	
	   		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_admin_security_adduser` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_admin_security_adduser` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_admin_security_adduser`(
	    IN var_code VARCHAR(50),
	    IN var_username VARCHAR(50),
	    IN var_password VARCHAR(30),
	    IN var_usertypeid BIGINT,
	    IN var_accesstypeid BIGINT,
	    in var_selectionids text,
	    IN createdby VARCHAR(30)
	)
BEGIN
	DECLARE var_userID INT;
	select count(*) into @cnt from usermaster where username = `var_username`;
	
	if @cnt = 0 then 
		INSERT INTO usermaster(`username`,`password`,`usertypeid`,`accesstypeid`)
		VALUES(var_username,var_password,var_usertypeid,var_accesstypeid);
		
		select LAST_INSERT_ID() into @lastid;
		select @lastid as lastid;
		
		CALL sp_add_logmaster_information('1','User Master','usermaster',@lastid,createdby,'Add');
		
		Set var_userID = (Select userid FROM usermaster where username = var_username and `password` = var_password);
		
		CALL sp_add_admin_usertype_userdetail(var_username, var_usertypeid, var_userID); 
		
		call sp_add_admin_security_adduseraccesscode(var_username,var_accesstypeid,var_selectionids);
		
	else
		SELECT 0 AS lastid;		
	end if;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_admin_security_adduseraccesscode` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_admin_security_adduseraccesscode` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_admin_security_adduseraccesscode`(		
	in user_name varchar(50),
	IN intaccesstype int(4),
    IN intselectcode text
    )
begin
		if intaccesstype = 1 then 
		
			DELETE FROM useraccesscodes WHERE username = user_name AND cmpycode > 0;
			set @ins_qry = concat("insert into useraccesscodes(username,cmpycode,countrycode,depotcode,areacode,subareacode,regionmstcode)
				select '",user_name,"', co.cmpycode,cm.countrycode,dm.depotcode,am.areacode ,sam.subareacode,rm.regionmstcode 
				from company co 
				left outer join country cm on cm.cmpycode = co.cmpycode 
				left outer join regionmaster rm on rm.countrycode  =cm.countrycode   
				left outer join depotmaster dm on dm.regionmstcode = rm.regionmstcode
				left outer join areamaster am on am.depotcode = dm.depotcode
				left outer join subareamaster sam on sam.areacode = am.areacode 
				where co.cmpycode in (",intselectcode,")");
			
			prepare s1 from @ins_qry;
			execute s1;
		elseif	intaccesstype = 2 then 
		
			DELETE FROM useraccesscodes WHERE username = user_name AND countrycode > 0;
			SET @ins_qry = CONCAT("insert into useraccesscodes(username,countrycode,depotcode,areacode,subareacode,regionmstcode)
				select '",user_name,"', cm.countrycode,dm.depotcode,am.areacode,sam.subareacode,rm.regionmstcode 
				from country cmpycode
				left outer join regionmaster rm on rm.countrycode  =cm.countrycode  
				left outer join depotmaster dm on dm.regionmstcode = rm.regionmstcode
				left outer join areamaster am on am.depotcode = dm.depotcode
				left outer join subareamaster sam on sam.areacode = am.areacode 
				where cm.countrycode IN (",intselectcode,")");
			
			PREPARE s1 FROM @ins_qry;
			EXECUTE s1;
		 elseif intaccesstype = 3 THEN 
		 
			DELETE FROM useraccesscodes WHERE username = user_name AND regionmstcode > 0;
			SET @ins_qry = CONCAT("insert into useraccesscodes(username,depotcode,areacode,subareacode,regionmstcode)
				select '",user_name,"',dm.depotcode,am.areacode ,sam.subareacode,rm.regionmstcode  
				from regionmaster rm  
				left outer join depotmaster dm on dm.regionmstcode = rm.regionmstcode 
				left outer join areamaster am on am.depotcode = dm.depotcode
				left outer join subareamaster sam on sam.areacode = am.areacode	
				where rm.regionmstcode IN (",intselectcode,")");
			
			PREPARE s1 FROM @ins_qry;
			EXECUTE s1;
		elseif intaccesstype = 4 THEN 
		
			DELETE FROM useraccesscodes WHERE username = user_name AND depotcode > 0;
			SET @ins_qry = CONCAT("insert into useraccesscodes(username,depotcode,areacode,subareacode)
				select '",user_name,"' ,dm.depotcode,am.areacode,sam.subareacode 
				from  depotmaster dm 
				left outer join areamaster am on am.depotcode = dm.depotcode 
				left outer join subareamaster sam on sam.areacode = am.areacode 
				where  dm.depotcode IN (",intselectcode,")");
			
			PREPARE s1 FROM @ins_qry;
			EXECUTE s1;
		elseif intaccesstype = 5  THEN 
		
			DELETE FROM useraccesscodes WHERE username = user_name AND areacode > 0;
			SET @ins_qry = CONCAT("insert into useraccesscodes(username,areacode,subareacode)
				select '",user_name,"',am.areacode,sam.subareacode
				from  areamaster am  
				left outer join subareamaster sam on sam.areacode = am.areacode 
				where am.areacode IN (",intselectcode,")");
			
			PREPARE s1 FROM @ins_qry;
			EXECUTE s1;
		elseif intaccesstype = 6  THEN 
		
			DELETE FROM useraccesscodes WHERE username = user_name AND subareacode > 0;
			SET @ins_qry = CONCAT("insert into useraccesscodes(username,subareacode)
				select '",user_name,"' , sam.subareacode  from subareamaster sam 
				where  sam.subareacode IN (",intselectcode,")");
			
			PREPARE s1 FROM @ins_qry;
			EXECUTE s1;
		end	if;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_admin_security_addusertype` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_admin_security_addusertype` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_admin_security_addusertype`(
	    IN `code` VARCHAR(50),
	    IN `name` VARCHAR(50),
	    IN adminid VARCHAR(30),
	    in `status` varchar(1),
	    IN createdby VARCHAR(30)
	)
BEGIN	
	INSERT INTO user_type(id,user_type,is_admin,`status`)
	VALUES(`code`,`name`,adminid,`status`);
	
	INSERT INTO usertype(usertypeid, usertypename)
	VALUES(`code`,`name`);
	
	CALL sp_add_logmaster_information('1','User Type','user_type',`code`,createdby,'Add');
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_admin_usertype_userdetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_admin_usertype_userdetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_admin_usertype_userdetail`(
IN var_username varchar(50),
IN var_usertypeid BIGINT,
IN var_userid BIGINT
)
BEGIN
	
	DECLARE intReadData INT;
	DECLARE intUpdateData INT;
	DECLARE intInsertData INT;
	DECLARE intDeleteData INT;
	DECLARE intAllPermissions INT;
	DECLARE intModuleID INT;
	DECLARE intFormID INT;
	DECLARE no_more_rows INT DEFAULT 0;
	DECLARE lst_usertypedetail CURSOR FOR 
		SELECT readdata, updatedata, insertdata, deletedata, allpermissions, moduleid,formid 
		FROM usertypedetail WHERE usertypeid = var_usertypeid;
	DECLARE CONTINUE HANDLER FOR NOT FOUND
	    SET no_more_rows = 1;
	
	
	DELETE FROM userdetail WHERE userid = var_userid; 
	
	OPEN lst_usertypedetail;
	the_loop: LOOP
	
	FETCH lst_usertypedetail INTO
	intReadData,intUpdateData,intInsertData,intDeleteData,intAllPermissions, intModuleID, intFormID;
	IF no_more_rows = 1 THEN
	   LEAVE the_loop;
	END IF;
	
		
	INSERT INTO userdetail(username, readdata, insertdata, updatedata, deletedata, allpermissions, moduleid, formid, userid)
	VALUES(var_username,intReadData,intInsertData,intUpdateData,intDeleteData,intAllPermissions, intModuleID, intFormID,var_userid);
	END LOOP the_loop;
	
	CLOSE lst_usertypedetail;
    END */$$
DELIMITER ;

