/* Procedure structure for procedure `sp_add_arcollection_arcollectionadd` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_arcollection_arcollectionadd` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_arcollection_arcollectionadd`(
in var_customercode int,
in var_route_code int,
in var_salesman_code int,
in var_comment text,
in var_payment_mode int,
in var_textamount int,
in var_checkno int,
IN var_chk_date varchar(50),
in var_bank_no int,
IN var_total_amount int,
in customer_invoice_arr text,
in amount_arra text,
in data_text2 text,
in chkfirstout int
)
BEGIN
DECLARE new_document_no VARCHAR(255);
DECLARE new_invoice_no VARCHAR(255);
declare new_visit_key int;
DECLARE new_route_key INT;
declare new_transaction_key int;
	
	 call sp_add_arcollection_genereate_document_no(var_route_code,@new_document_no,@new_invoice_no);
	
	 set new_invoice_no  =  @new_invoice_no;
	 SET new_document_no =  @new_document_no;
	 
		
	 CALL sp_add_arcollection_genereate_route_key(var_route_code,var_customercode,var_salesman_code,@visit_key,@route_key);
	SET new_visit_key  =  @visit_key;
	SET new_route_key  =  @route_key;
	
	call sp_add_arcollection_arheader(var_customercode,
					var_route_code,
					var_salesman_code,
					var_comment,
					var_textamount,
					new_route_key,
					new_visit_key,
					new_document_no,
					new_invoice_no,
					customer_invoice_arr,
					@var_transaction_key);
	set new_transaction_key = @var_transaction_key;
	
	
	
	
	
	
	
	
	 select new_visit_key,new_route_key,new_invoice_no,new_document_no,new_transaction_key;
	
	
	
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_arcollection_ardetail_custompayment` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_arcollection_ardetail_custompayment` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_arcollection_ardetail_custompayment`(
IN var_customer_code INT,
IN var_salesman_code INT,
IN var_route_code INT,
IN var_amount DECIMAL(19,4),
IN var_routekey INT,
IN var_visitkey INT,
IN var_transactionkey INT,
IN payment_type INT,
IN customer_invoice_arr TEXT,
IN amount_arra TEXT,
in record_count int
)
BEGIN
	 
	
	
	  DECLARE in_transaction_key INT;
	  DECLARE in_invoicebalance DECIMAL(19,4);
	  DECLARE new_invoicebalance DECIMAL(19,4);
	  DECLARE new_pdcbalance DECIMAL(19,4);
	  DECLARE in_invoicenumber VARCHAR(50);
	  
	  
	  DECLARE no_more_rows BOOLEAN;
	  DECLARE loop_cntr INT DEFAULT 0;
	  DECLARE num_rows INT DEFAULT 0;
	  
	  
	  DECLARE friends_cur CURSOR FOR
	    SELECT
		customerinvoice.transactionkey
	      , customerinvoice.invoicebalance,
	        invoicenumber
	    FROM customerinvoice
	    WHERE transactionkey IN (var_transactionkey);
	  
	  DECLARE CONTINUE HANDLER FOR NOT FOUND
	    SET no_more_rows = TRUE;
	  
	  
	  OPEN friends_cur;
	  SELECT FOUND_ROWS() INTO num_rows;
	  the_loop: LOOP
	    FETCH  friends_cur
	    INTO   in_transaction_key,
	           in_invoicebalance,
		   in_invoicenumber;
	 
	    
	      
	      
	    IF no_more_rows THEN
		CLOSE friends_cur;
		LEAVE the_loop;
	    END IF;
	    
	    
	 
		INSERT INTO ardetail 
		(routekey,visitkey,transactionkey,invoicenumber,invoicedate,totalinvoiceamount, 
		amountpaid, invoicebalance,arcollectiontype,chequestatusindicator, sapchequestatusindicator, 
		currencycode,pdcbalance,alternateinvoicenumber
		)
		VALUES
		(var_routekey, var_visitkey,var_transactionkey,in_invoicenumber,DATE(CURRENT_DATE()),in_invoicebalance, 
		in_invoicebalance, 0,'0','0','0', 
		get_default_currencycode(),new_pdcbalance,'');	
		
		
		UPDATE customerinvoice SET amountpaid=amountpaid +in_invoicebalance,
		invoicebalance = invoicebalance - in_invoicebalance,
		pdcbalance = amountpaid + in_invoicebalance
		WHERE transactionkey =in_transaction_key	;
			
			
	   
	    SET loop_cntr = loop_cntr + 1;
	  END LOOP the_loop;
	  
	 
	 
			
			
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_arcollection_ardetail_firstinfirstout` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_arcollection_ardetail_firstinfirstout` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_arcollection_ardetail_firstinfirstout`(
in var_customer_code int,
in var_salesman_code int,
in var_route_code int,
in var_amount decimal(19,4),
in var_routekey int,
in var_visitkey int,
in var_transactionkey int,
in payment_type int
)
BEGIN
	 
	  
	  DECLARE in_transaction_key INT;
	  DECLARE in_invoicebalance DECIMAL(19,4);
	  DECLARE new_invoicebalance DECIMAL(19,4);
	  DECLARE new_pdcbalance DECIMAL(19,4);
	  DECLARE in_invoicenumber VARCHAR(50);
	  DECLARE var_amount1 DECIMAL(19,4);
	  DECLARE invoice_balance_1 DECIMAL(19,4);
	  
	  DECLARE no_more_rows BOOLEAN;
	  DECLARE loop_cntr INT DEFAULT 0;
	  DECLARE num_rows INT DEFAULT 0;
	  
	  
	  DECLARE friends_cur CURSOR FOR
	    SELECT
		customerinvoice.transactionkey
	      , customerinvoice.invoicebalance,
	      invoicenumber
	    FROM customerinvoice
	    WHERE 1=1;
	  
	  DECLARE CONTINUE HANDLER FOR NOT FOUND
	    SET no_more_rows = TRUE;
	  
	  
	  
	  OPEN friends_cur;
	  SELECT FOUND_ROWS() INTO num_rows;
	  the_loop: LOOP
	    FETCH  friends_cur
	    INTO   in_transaction_key,
	           in_invoicebalance,
		   in_invoicenumber;
	  SET invoice_balance_1 = in_invoicebalance;
	    
	      
	      
	    IF no_more_rows THEN
		CLOSE friends_cur;
		LEAVE the_loop;
	    END IF;
	    
	    
	    IF(var_amount > 0) THEN 
	    
		SET new_pdcbalance = 0;
		
		IF payment_type = 1 THEN
			SET new_pdcbalance = in_invoicebalance;
		END IF;
		
		IF (var_amount > in_invoicebalance) THEN
		 
			INSERT INTO ardetail 
			(routekey,visitkey,transactionkey,invoicenumber,invoicedate,totalinvoiceamount, 
			amountpaid, invoicebalance,arcollectiontype,chequestatusindicator, sapchequestatusindicator, 
			currencycode,pdcbalance,alternateinvoicenumber
			)
			VALUES
			(var_routekey, var_visitkey,var_transactionkey,in_invoicenumber,DATE(CURRENT_DATE()),in_invoicebalance, 
			in_invoicebalance, 0,'0','0','0', 
			get_default_currencycode(),new_pdcbalance,'');	
			
			
			UPDATE customerinvoice SET amountpaid=amountpaid +in_invoicebalance,
			invoicebalance = invoicebalance - in_invoicebalance,
			pdcbalance = amountpaid + in_invoicebalance
			WHERE transactionkey =in_transaction_key	;
			
			
		ELSE
		
		SET new_invoicebalance = in_invoicebalance - var_amount;
			
			INSERT INTO ardetail 
			(routekey,visitkey,transactionkey,invoicenumber,invoicedate,totalinvoiceamount, 
			amountpaid, invoicebalance,arcollectiontype,chequestatusindicator, sapchequestatusindicator, 
			currencycode,pdcbalance,alternateinvoicenumber
			)
			VALUES
			(var_routekey, var_visitkey,var_transactionkey,in_invoicenumber,DATE(CURRENT_DATE()),in_invoicebalance, 
			var_amount, new_invoicebalance,'0','0','0', 
			get_default_currencycode(),new_pdcbalance,'');	
			
			UPDATE customerinvoice SET amountpaid = amountpaid + var_amount,
			invoicebalance = invoicebalance - new_invoicebalance,
			pdcbalance=amountpaid + var_amount
			WHERE transactionkey =in_transaction_key;
		
		END IF;
			
		
		SET  var_amount = var_amount - in_invoicebalance;
		
		
	    ELSE
	    
		CLOSE friends_cur;
		LEAVE the_loop;
	    END IF;
	    
	    SET loop_cntr = loop_cntr + 1;
	  END LOOP the_loop;
	  
	 
	 
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_arcollection_arheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_arcollection_arheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_arcollection_arheader`(
IN var_customercode INT,
IN var_route_code INT,
IN var_salesman_code INT,
IN var_comment TEXT,
IN var_textamount INT,
in in_route_key_code int,
in new_visit_key int,
in new_document_no varchar(50),
in new_invoice_no varchar(50),
IN customer_invoice_arr text,
OUt var_transaction_key int
)
BEGIN
DECLARE in_totalinvoiceamount decimal(19,4);
DECLARE in_invoicebalance DECIMAL(19,4);
DECLARE new_transaction_key int;
	SELECT SUM(totalinvoiceamount),SUM(invoicebalance) 
	into in_totalinvoiceamount,in_invoicebalance 
	FROM customerinvoice where 1= 1 and FIND_IN_SET(transactionkey,customer_invoice_arr);
	
	
	
	INSERT INTO arheader 
	(	routekey,visitkey,documentnumber,transactiondate,transactiontime,customercode, 
		routecode,salesmancode,voidflag,splittransaction,transmitindicator,totalinvoiceamount,amountpaid, 
		invoicebalance,invoicenumber,hhcdocumentnumber,hhcinvoicenumber,voidreasoncode,chequecollection, 
		currencycode,hhctransactionkey,`data`,comments,advancepaymentflag,excesspayment,comments2
	)
	VALUES
	(in_route_key_code,new_visit_key,new_document_no,CURRENT_DATE(),TIME(CURRENT_DATE()),var_customercode,var_route_code, 
	var_salesman_code,'0','','',in_totalinvoiceamount,var_textamount,in_invoicebalance, 
	new_invoice_no,'','','','',get_default_currencycode(), 
	'','',var_comment,'','','') ;
	
	SELECT LAST_INSERT_ID() INTO new_transaction_key;
	
	set var_transaction_key = new_transaction_key;
END */$$
DELIMITER ;

