/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_arcollection_cashcollection` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_arcollection_cashcollection`(
in in_route_key_code int,
in in_visitkey int,
in var_payment_mode int,
