	(	routekey,visitkey,typecode,checknumber,amount,checkdate,bankcode,checkstatus, 
		branchcode,drawercode,chequestatusindicator,sapchequestatusindicator,currencycode,
		hhctransactionkey,transactiontype)
	
	values(	in_route_key_code,in_visitkey,var_payment_mode,var_checkno,var_textamount,
		STR_TO_DATE(var_chk_date,'%d-%m-%Y'),
		var_bank_no,0,0,0,0,0,0,get_default_currencycode(),new_transaction_key,2);
