/* Procedure structure for procedure `sp_add_arcollection_genereate_document_no` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_arcollection_genereate_document_no` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_arcollection_genereate_document_no`(
in var_route_code int,
OUT  new_document_no varchar(50),
OUT  new_invoice_no varchar(50)
)
BEGIN
declare new_invoice_no1 int;
declare new_document_no1 int;
	UPDATE routemaster SET  boarseq = IFNULL(boarseq,0) + 1, bodocseq = IFNULL(bodocseq,0) + 1
	WHERE  routecode =var_route_code;
	
	SELECT  IFNULL(boarseq,0) AS  invoice_seq, IFNULL(bodocseq,0) AS document_seq
	INTO new_invoice_no1,new_document_no1
	FROM routemaster WHERE routecode =var_route_code;
	
	
	set new_document_no = CONCAT(var_route_code,"000000",new_document_no1 );
	set new_invoice_no  =  CONCAT(var_route_code,"700000",new_invoice_no1 );
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_arcollection_genereate_route_key` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_arcollection_genereate_route_key` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_arcollection_genereate_route_key`(
IN var_route_code int,
IN var_customercode int,
in var_salesman_code int,
OUT var_visit_key int,
Out var_route_key int
)
BEGIN
declare in_route_key_code1 int;
declare in_visit_key1 int;
	SELECT routekey INTO in_route_key_code1 FROM startendday 
	WHERE startendday.routecode=var_route_code
		AND startendday.routeclosed = 0
	ORDER BY routekey DESC  LIMIT 1	;
	
	set var_route_key = in_route_key_code1;
	
	SELECT IFNULL(MAX(customeroperationscontrol.visitkey),0) INTO in_visit_key1 FROM customeroperationscontrol
	WHERE  customeroperationscontrol.routekey =in_route_key_code1 ;
	
	SET in_visit_key1 =in_visit_key1 + 1;
	set var_visit_key  =  in_visit_key1;
	
	INSERT INTO customeroperationscontrol (visitkey,routekey,customercode,salesmancode,routecode,visitstartdate,
	visitstarttime,visitenddate,visitendtime,totaltransactions,voidflag)
	value(in_visit_key1,in_route_key_code1,var_customercode,var_salesman_code,var_route_code,date(CURRENT_DATE()),time(CURRENT_DATE()),
	DATE(CURRENT_DATE()),TIME(CURRENT_DATE()),1,0);
	
    END */$$
DELIMITER ;

