/* Procedure structure for procedure `sp_add_basic_index_addinventoryloc` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_basic_index_addinventoryloc` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_basic_index_addinventoryloc`(
	    IN var_description VARCHAR(20),
	    IN var_arbdescription VARCHAR(20),
	    in var_altcode varchar(50)	    ,
	    in cratedby varchar(30)
	)
BEGIN
	
	INSERT INTO inventorylocation(description,arbdescription,hhcdescription,alternatecode,created,cdat)
	VALUES(var_description,var_arbdescription,'',var_altcode,cratedby,CURRENT_DATE());
		
	SELECT LAST_INSERT_ID() INTO @last_id;
	SELECT @last_id AS last_id;
	
	CALL sp_add_logmaster_information('1','Inventory Location','inventorylocation',@last_id,createdby,'Add');	
	
END */$$
DELIMITER ;

