/* Procedure structure for procedure `sp_add_inventory_index_additem` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_inventory_index_additem` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_inventory_index_additem`(
		    IN var_actualitemcode         BIGINT,
                    IN var_anitemcode             VARCHAR(50),
                    IN var_itemgroupcode          DECIMAL(18,0),
                    IN var_alternatecode          VARCHAR(50),
                    IN var_itemshortdescription   VARCHAR(50),
                    IN var_warehousestock         DECIMAL(18,0),
                    IN var_itemdescription        VARCHAR(50),
                    IN var_itemgrpcode            VARCHAR(10),
                    IN var_unitspercase           INT(11),
                    IN var_dataentry              INT(11),
                    IN var_liter                  FLOAT,
                    IN var_literperunit            FLOAT,
                    IN var_caseprice               DECIMAL(18,4),
                    IN var_defaultsalesprice       DECIMAL(18,4),
                    IN var_defaultgoodreturncaseprice  DECIMAL(18,4),
                    IN var_defaultgoodreturnprice  DECIMAL(18,4),
                    IN var_returncaseprice  	   DECIMAL(18,4),
                    IN var_defaultreturnprice      DECIMAL(18,4),
                    IN var_caseuom              	INT(11),
                    IN var_activeitem              	INT(11),
                    IN var_captureshelfstock      	INT(11),
                    IN var_tcallowed                INT(11),
                    IN var_allowvoicepricechange 	INT(11),
                    IN var_arbitemdescription       VARCHAR(50),
                    IN var_arbitemshortdescription  VARCHAR(50),
                    IN var_costcaseprice       		decimal(18,4),
                    IN var_defaultcostprice  		DECIMAL(18,4),
                    IN var_barcode1 VARCHAR(20),
					IN var_barcode2 VARCHAR(20),
                    IN var_barcode3 VARCHAR(20),
					IN var_barcode4 VARCHAR(20),
					IN var_barcode5 VARCHAR(20),
					IN var_barcode6 VARCHAR(20),
					IN var_barcode7 VARCHAR(20),
					IN var_barcode8 VARCHAR(20),
					IN var_barcode9 VARCHAR(20),
					IN var_barcode10 VARCHAR(20),
                    IN var_created                    CHAR(20),
                    IN var_modified                   CHAR(20),
                    IN var_itemtaxkey1				INT(11),
                    IN var_itemtaxkey2				INT(11),
                    IN var_itemtaxkey3				INT(11)
    )
BEGIN
		INSERT INTO itemmaster
			(actualitemcode
			,anitemcode,
			itemgroupcode,
			alternatecode,
			itemshortdescription,
			warehousestock,
			itemdescription,
			itemgrpcode,
			unitspercase,
			dataentry ,
			liter ,
			literperunit,
			caseprice,
			defaultsalesprice,
			defaultgoodreturncaseprice,
			defaultgoodreturnprice,
			returncaseprice,
			defaultreturnprice,
			caseuom,
			activeitem,
			captureshelfstock,
			tcallowed,
			allowinvoicepricechange,
			arbitemdescription,
			arbitemshortdescription,
			costcaseprice,
			defaultcostprice,
			barcode1,
			barcode2,
			barcode3,
			barcode4,
			barcode5,
			barcode6,
			barcode7,
			barcode8,
			barcode9,
			barcode10,
			created,
			modified,
			cdat,
			mdat,
			itemtaxkey1,
			itemtaxkey2,
			itemtaxkey3  )
		VALUES
		(var_actualitemcode,var_anitemcode,
		var_itemgroupcode,
		var_alternatecode,
		var_itemshortdescription,
		var_warehousestock,
		var_itemdescription,
		var_itemgrpcode,
		var_unitspercase,
		var_dataentry ,
		var_liter ,
		var_literperunit,
		var_caseprice,
		var_defaultsalesprice,
		var_defaultgoodreturncaseprice,
		var_defaultgoodreturnprice,
		var_returncaseprice,
		var_defaultreturnprice,
		var_caseuom,
		var_activeitem,
		var_captureshelfstock,
		var_tcallowed,
		var_allowvoicepricechange,
		var_arbitemdescription,
		var_arbitemshortdescription,
		var_costcaseprice,
		var_defaultcostprice,
		var_barcode1,
		var_barcode2,
		var_barcode3,
		var_barcode4,
		var_barcode5,
		var_barcode6,
		var_barcode7,
		var_barcode8,
		var_barcode9,
		var_barcode10,		
		var_created,
		var_modified,
		CURRENT_DATE(),
		CURRENT_DATE(),
		var_itemtaxkey1,
		var_itemtaxkey2,
		var_itemtaxkey3 );
		
		SELECT LAST_INSERT_ID() INTO @last_id;
		SELECT @last_id AS result;
		
		CALL sp_add_logmaster_information('1','Items','itemmaster',@last_id,var_created,'Add');
		
		
		
		
		
		select `status` into @st from controlpanel where flagid = 61;
		if @st = 1 then
			INSERT INTO routeitemmapping SET itemcode			= @last_id,
											 routeitemgrpcode	= 1;
		end if;
    END */$$
DELIMITER ;

