/* Procedure structure for procedure `sp_add_inventory_routestartday_addroute` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_inventory_routestartday_addroute` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_inventory_routestartday_addroute`(
IN var_route_code INT,
IN var_date VARCHAR(30)
)
BEGIN
	DECLARE var_salesmancode INT;
	DECLARE in_last_insert_id INT;
	
	SELECT salesmancode INTO var_salesmancode FROM routemaster  WHERE routemaster.routecode = var_route_code;
	
	SELECT rm.subareacode,sam.supervisorcode,sam.areacode,am.areamanagercode,am.depotcode,dm.branchmanagercode,
		   dm.cmpycode,co.nationalsalesmanagercode,rm.amountdecimaldigits
	into   @subareacode,@supervisorcode,@areacode,@areamanagercode,@depotcode,@branchmanagercode,
		   @cmpycode,@nationalsalesmanagercode,@amountdecimaldigits
	FROM routemaster rm,subareamaster sam,areamaster am,depotmaster dm,company co
	
	WHERE sam.subareacode = rm.subareacode AND am.areacode = sam.areacode AND dm.depotcode = am.depotcode
		  AND co.cmpycode = dm.cmpycode AND rm.routecode = var_route_code;
    
	
	INSERT INTO startendday set 	salesmancode = var_salesmancode,
									routecode = var_route_code,
									routestartdate = STR_TO_DATE(var_date,'%d-%m-%Y'),
									routestarttime = TIME(CURRENT_DATE()),
									areacode = @areacode,
									areamanagercode = @areamanagercode,
									branchmanagercode = @branchmanagercode,
									cmpycode = @cmpycode,
									currencycode = @amountdecimaldigits,
									depotcode=@depotcode,
									nationalsalesmanagercode=@nationalsalesmanagercode,
									subareacode=@subareacode,
									supervisorcode=@supervisorcode;
	SELECT LAST_INSERT_ID() INTO in_last_insert_id;
	
	DELETE FROM batchmaster WHERE routekey = in_last_insert_id;
	
  END */$$
DELIMITER ;

