/* Procedure structure for procedure `sp_add_inventory_target_additionalbarcode` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_inventory_target_additionalbarcode` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_inventory_target_additionalbarcode`(
		IN var_itemcode bigint(20),
		IN var_barcode3 varchar(20),
		IN var_barcode4 varchar(20),
		IN var_barcode5 varchar(20),
		IN var_barcode6 varchar(20),
		IN var_barcode7 varchar(20),
		IN var_barcode8 varchar(20),
		IN var_barcode9 varchar(20),
		IN var_barcode10 varchar(20),
		in var_created VARCHAR(50)
	)
BEGIN
		declare cnt int;
		
		select count(itemcode) into cnt from itembarcodes where itemcode = var_itemcode;
		
		if cnt = 0 then 
	
			INSERT INTO itembarcodes SET 
							    itemcode 	= var_itemcode,
								barcode3 	= var_barcode3,
								barcode4 	= var_barcode4,
								barcode5 	= var_barcode5,
								barcode6 	= var_barcode6,
								barcode7 	= var_barcode7,
								barcode8 	= var_barcode8,
								barcode9 	= var_barcode9,
								barcode10 	= var_barcode10,
								created 	= var_created,
								modified 	= var_created,
									cdat 	= CURRENT_DATE(),
									mdat 	= CURRENT_DATE(); 
		
			SELECT LAST_INSERT_ID() INTO @last_id;
			SELECT @last_id AS last_id;
			
			CALL sp_add_logmaster_information('1','Additional Bar Code','itembarcodes',@last_id,var_created,'Add');
		else
			select '0' as last_id;
		end if;
		
		CALL sp_combo_itemmaster();
	
END */$$
DELIMITER ;

