		EXECUTE s1;
		
		
		if @rtcode != ''  then 
			SET @edit = CONCAT("UPDATE routemaster SET routefeature = NULL, routeflag = NULL WHERE routecode IN (",@rtcode,")");
			PREPARE s2 FROM @edit;
			EXECUTE s2;
		end if;
		
		WHILE from_start <= var_counter DO
			SET @cust_code = '';
			SET @cust_code = split(var_customerid,',',from_start);
			SET @updte = CONCAT("UPDATE routemaster SET routefeature = '",var_feature,"', routeflag = '",var_fillby,"' WHERE routecode = @cust_code");
			SET from_start = from_start + 1;
			PREPARE s3 FROM @updte;
			EXECUTE s3;
		END WHILE;		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_loadstock_inventorytransactionheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_loadstock_inventorytransactionheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_loadstock_inventorytransactionheader`(			
			IN var_routecode BIGINT,
			IN var_salesmancode BIGINT,
			IN var_date VARCHAR(30),
			IN var_urgent INT(4),
			IN var_deopt_route DECIMAL(18,0)
			
		)
BEGIN
	
		DECLARE doc_num BIGINT;
		DECLARE route_key BIGINT;		
		SELECT COALESCE(MAX(documentnumber),0)+1 INTO doc_num FROM inventorytransactionheader WHERE DATA = 1;
		SELECT COALESCE(MAX(routekey),0) INTO route_key FROM startendday WHERE routecode = var_routecode;
		SET @dyn = CONCAT("INSERT INTO inventorytransactionheader SET 
			inventorykey = ",route_key,",			
			routekey = ",route_key,",
			transactiontype = '4',
			routecode = ",var_routecode,",
			salesmancode = ",var_salesmancode,",
			transactiondate = CURDATE(),
			transactiontime = CURTIME(),
			documentnumber = ",doc_num,",
			odometerreading = '0',
			transferlocationcode = ",var_deopt_route,",
			referencenumber = ",doc_num,",
			requestdate = STR_TO_DATE('",var_date,"','%Y-%m-%d'),
			deliverydate = STR_TO_DATE('",var_date,"','%Y-%m-%d'),
			securitycode = '0',
			transmitindicator = '0',
			voidflag = '0',
			hhcdocumentnumber = '0',
			loadnumber = '0',
			refdocumentnumber = '0',
			currencycode = get_default_currencycode_routecode(",var_routecode,"),
			actualtransactiondate = CURDATE(),
			inventorynumber = ",doc_num,",
			DATA = '1',
			record_flag='1',
			isurgent=",var_urgent,",
			receivedtime = CURTIME()");
		
		PREPARE s1 FROM @dyn;
		EXECUTE s1;
		SELECT LAST_INSERT_ID() AS result;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_logmaster_information` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_logmaster_information` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_logmaster_information`(
					
					in counter int,
					in form_name varchar(100),
					in tblname varchar(100),
					in tblid 	text,
					in createdby varchar(30),
					in operationtype varchar(20)
				)
BEGIN
		DECLARE record_id INT;
		declare from_start int default 1;		
		
		if operationtype = 'delete' then		
			set operationtype = 'Delete';
		end if;
		
		
		while from_start <= counter do
		
		SET record_id = split(tblid,',',from_start);
		
			insert into logmaster(formname,tablename,recordid,created,cdat,operation_type)values
				(form_name,tblname,record_id,createdby,CURRENT_DATE(),operationtype);				
				
			
			
			SET  from_start = from_start + 1;
		end while;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_merchandize_addvisual` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_merchandize_addvisual` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_merchandize_addvisual`(
	    IN visualdescription VARCHAR(50),
	    IN arbvisualdescription VARCHAR(50),	    
	    IN remarks TEXT,
	    IN createdby VARCHAR(50),
	    IN tempcode INT
	    
	    
	)
BEGIN
	
	
	INSERT INTO visualheader(visualdescription,arbvisualdescription,remarks)
	VALUES(visualdescription,arbvisualdescription,remarks);
			
	SELECT LAST_INSERT_ID() INTO @last_id;
	SELECT @last_id AS last_id;
	
	IF (tempcode!='') THEN
	
	INSERT INTO visualdetail(visualcode, imagename, imagepath, imagedescription)
	SELECT @last_id, imagename, imagepath, imagedescription
	FROM visualdetail_temp WHERE visualcode = tempcode;
	
	SET @del = CONCAT("DELETE FROM visualdetail_temp WHERE visualcode = ",tempcode);
	PREPARE s1 FROM @del;
	EXECUTE s1;
	
	END IF;
	
	
	
	 
	
	
	
	CALL sp_add_logmaster_information('1','Visual Header','visualheader',@last_id,createdby,'Add');
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_merchandize_index_addcustomerimages` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_merchandize_index_addcustomerimages` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_merchandize_index_addcustomerimages`(
			IN var_imagename VARCHAR(100),
			IN var_customercode BIGINT(20),
			IN var_imageno INT(11),
			IN var_imagepath VARCHAR(500),
			IN var_routecode BIGINT(20),
			IN var_routekey INT(11),
			IN var_transactiondate DATETIME,
			IN var_transactiontime DATETIME,
			IN var_visitkey INT(11)
    )
BEGIN
DECLARE cnt INT DEFAULT 0;
SELECT COUNT(*) INTO cnt FROM customerimages WHERE  imagename=var_imagename AND routekey=var_routekey AND customercode=var_customercode;
 
 
 IF cnt = 0 THEN	
 
		INSERT INTO customerimages SET 
						imagename = var_imagename,
						customercode = var_customercode,
						imageno = var_imageno,
						imagepath = var_imagepath,
						routecode = var_routecode,
						routekey = var_routekey,
						transactiondate = var_transactiondate,
						transactiontime = var_transactiontime,
						visitkey = var_visitkey;
					
		SELECT LAST_INSERT_ID() INTO @last_id;
		SELECT @last_id AS last_id;
		
		END IF;
		
		CALL sp_add_logmaster_information('1','Customer Images','customerimages',@last_id,'','Add');
			
    END */$$
DELIMITER ;

