/* Procedure structure for procedure `sp_add_organization_route_addroute` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_organization_route_addroute` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_organization_route_addroute`(
	IN var_routename VARCHAR(30),
	IN var_arbroutename VARCHAR(30),
	IN var_subareacode DECIMAL(18,0),
	IN var_salesmancode DECIMAL(10,0),
	IN var_created VARCHAR(20),
	IN var_cdat DATETIME,
	IN var_modified VARCHAR(20),
	IN var_mdat DATETIME,
	IN var_password1 INT(4),
	IN var_password2 INT(4),
	IN var_password3 INT(4),
	IN var_password4 INT(4),
	IN var_password5 INT(4),
	IN var_passwordarray01 INT(4),
	IN var_passwordarray02 INT(4),
	IN var_passwordarray03 INT(4),
	IN var_passwordarray04 INT(4),
	IN var_passwordarray05 INT(4),
	IN var_passwordarray06 INT(4),
	IN var_passwordarray07 INT(4),
	IN var_passwordarray08 INT(4),
	IN var_passwordarray09 INT(4),
	IN var_passwordarray10 INT(4),
	IN var_passwordarray11 INT(4),
	IN var_passwordarray12 INT(4),
	IN var_passwordarray13 INT(4),
	IN var_passwordarray14 INT(4),
	IN var_passwordarray15 INT(4),
	IN var_passwordarray16 INT(4),
	IN var_depotrouteflag INT(4),
	IN var_presalesorder SMALLINT(6),
	IN var_alternateroutecode VARCHAR(30),
	IN var_routecatcode BIGINT,
	IN var_ddlvan VARCHAR(30),
	IN var_regioncode BIGINT,
	IN var_activestatus INT(4),
	IN var_cmpycode BIGINT,
	IN var_allowroutestartdayflag INT(4),
	IN var_code INT(20),
	IN device_id VARCHAR(30),
	IN var_itummustkey BIGINT,
	IN var_enablefss int(4)
    )
BEGIN
	DECLARE rowcnt INT DEFAULT 0;
	
	SELECT COUNT(*) INTO rowcnt FROM routemaster 
		WHERE alternateroutecode = var_alternateroutecode OR
		routename = var_routename;
		
	IF rowcnt = 0 THEN
		INSERT INTO routemaster
			(routecode,
			alternateroutecode,
			routename,
			arbroutename,
			subareacode,
			salesmancode,			
			password1,
			password2,
			password3,
			password4,
			password5,
			passwordarray01,
			passwordarray02,
			passwordarray03,
			passwordarray04,
			passwordarray05,
			passwordarray06,
			passwordarray07,
			passwordarray08,
			passwordarray09,
			passwordarray10,
			passwordarray11,
			passwordarray12,
			passwordarray13,
			passwordarray14,
			passwordarray15,
			passwordarray16,
			depotrouteflag,
			presalesorder,
			routecatcode,
			regionmstcode,
			activestatus,
			allowroutestartdayflag,
			cmpycode,
			vehiclenumber,
			created,
			device_assigned_id,
			itemmustkey,
			cdat,
			enablefss)
			VALUES
			(var_code,var_alternateroutecode,
			var_routename,
			var_arbroutename,
			var_subareacode,
			var_salesmancode,		
			var_password1,
			var_password2,
			var_password3,
			var_password4,
			var_password5,
			var_passwordarray01,
			var_passwordarray02,
			var_passwordarray03,
			var_passwordarray04,
			var_passwordarray05,
			var_passwordarray06,
			var_passwordarray07,
			var_passwordarray08,
			var_passwordarray09,
			var_passwordarray10,
			var_passwordarray11,
			var_passwordarray12,
			var_passwordarray13,
			var_passwordarray14,
			var_passwordarray15,
			var_passwordarray16,
			var_depotrouteflag,
			var_presalesorder,
			var_routecatcode,
			var_regioncode,
			var_activestatus,
			var_allowroutestartdayflag,
			var_cmpycode,
			var_ddlvan,
			var_created,
			device_id,
			var_itummustkey,
			CURRENT_DATE(),
			var_enablefss);
			
			SELECT LAST_INSERT_ID() INTO @last_id;
			SET @last_id = var_code;
			SELECT @last_id AS result;
			
			CALL sp_add_logmaster_information('1','Route Master','routemaster',@last_id,var_created,'Add');
			
			
		ELSE
			SELECT 'duplicate' AS result;
		END IF;
    END */$$
DELIMITER ;

