/* Procedure structure for procedure `sp_add_promotions_advancepricing_pricingkeyitemgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_promotions_advancepricing_pricingkeyitemgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_promotions_advancepricing_pricingkeyitemgrid`(IN price_key INT,IN input_text TEXT, IN tot_row INT,in var_created varchar(30))
BEGIN
    
    DECLARE from_start INT;
    DECLARE plan_id VARCHAR(10);
    DECLARE last_id INT;
    DECLARE rowcnt INT DEFAULT 0;
    
    SET from_start = 1;
    
    WHILE from_start <= tot_row DO
    
	SET last_id = '';
    
	SET plan_id = split(input_text,',',from_start);
	SELECT COUNT(*) INTO rowcnt FROM customerpricing1 WHERE (customerpricingkey = plan_id AND pricingplankey = price_key);
	
	IF rowcnt = 0 THEN
	INSERT INTO customerpricing1 
		(customerpricingkey,description,arbdescription,active)
			SELECT customerpricingkey,description,arbdescription,active 
					FROM pricingplanheader1 
					WHERE customerpricingkey = plan_id;
	
	SELECT LAST_INSERT_ID() INTO last_id;
	
	UPDATE customerpricing1 SET 
				startdate 		= CURRENT_DATE(),
				enddate			= CURRENT_DATE(),
				created 		= var_created,
				cdat 			= CURRENT_DATE(),
				modified 		= var_created,
				mdat 			= CURRENT_DATE(),
				pricingplankey	= price_key
			WHERE	primary_key = last_id;
    
	END IF;
	
	SET  from_start = from_start + 1;
	
    END WHILE;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_promotions_advancepricing_pricingplanitemgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_promotions_advancepricing_pricingplanitemgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_promotions_advancepricing_pricingplanitemgrid`(
                    IN p_itemcode 			BIGINT,
                    IN p_unitspercase     	DECIMAL(19,4),
					IN p_stdsalesunitprice  DECIMAL(19,4),
					IN p_stdreturnunitprice	DECIMAL(19,4),
                    IN p_stdsalescaseprice  DECIMAL(19,4),
					IN p_stdreturncaseprice	DECIMAL(19,4),
                    IN p_salesprice			DECIMAL(19,4),
                    IN p_salescaseprice     DECIMAL(19,4),
					IN p_returnprice     	DECIMAL(19,4),
                    IN p_returncaseprice	DECIMAL(19,4),
                    IN p_customerpricingkey	BIGINT,
                    IN p_createdby 			VARCHAR(50)
			)
BEGIN
	DECLARE rowcnt INT DEFAULT 0;
	
	SELECT COUNT(*) INTO rowcnt FROM pricingdetail1 WHERE ( customerpricingkey = p_customerpricingkey AND itemcode = p_itemcode);
	
	IF rowcnt > 0 THEN
		SELECT 'duplicate' AS 'result';
	ELSE
		INSERT INTO pricingdetail1  SET 
						itemcode = p_itemcode,
						unitspercase = p_unitspercase,
						stdsalesunitprice = p_stdsalesunitprice,
						stdreturnunitprice = p_stdreturnunitprice,
						stdsalescaseprice = p_stdsalescaseprice,
						stdreturncaseprice = p_stdreturncaseprice,
						salesprice =p_salesprice,
						salescaseprice = p_salescaseprice,
						returnprice = p_returnprice,
						returncaseprice = p_returncaseprice,
						customerpricingkey = p_customerpricingkey,
						created = p_createdby,
						cdat = CURRENT_DATE(),
						modified = p_createdby,
						mdat = CURRENT_DATE();
		SELECT "added" AS 'result';
	END IF;
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_promotions_advance_addpromotionkey` */

