/* Procedure structure for procedure `sp_add_promotions_discount_adddistributionkeygrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_promotions_discount_adddistributionkeygrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_promotions_discount_adddistributionkeygrid`(
                    IN p_item BIGINT,
                    IN p_value     BIGINT,
                    IN p_description VARCHAR(50),
				    IN p_arbdescription VARCHAR(50),
				    IN p_active VARCHAR(50),
				    IN p_distributionkey BIGINT,
				    IN createdby VARCHAR(30)
                    
    )
BEGIN
	DECLARE rowcnt INT DEFAULT 0;
	DECLARE insid INT DEFAULT 0;
	
	if p_distributionkey = 0 or p_distributionkey = '' then 
		
		INSERT INTO `distributionkeyheader` (`description`,`arbdescription`,`active`) 
		VALUES (p_description,p_arbdescription,p_active);
		
		SELECT LAST_INSERT_ID() INTO p_distributionkey;		
		
		CALL sp_add_logmaster_information('1','Distribution Key','distributionkeyheader',p_distributionkey,createdby,'Add');
	
	end if;
	SELECT COUNT(*) INTO rowcnt FROM distributionkeydetails WHERE (distributionkey = p_distributionkey AND item = p_item);
	
	IF rowcnt > 0 THEN
		SELECT 'duplicate' AS 'result';
	ELSE
		INSERT INTO distributionkeydetails
		(distributionkey,item,`value`,created,cdat,modified,mdat  )
		VALUES(p_distributionkey,p_item,p_value,createdby,CURRENT_DATE(),createdby,CURRENT_DATE());
		SELECT "added" AS 'result';
	END IF;
	select p_distributionkey as lastid;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_promotions_discount_discountkeyitemgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_promotions_discount_discountkeyitemgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_promotions_discount_discountkeyitemgrid`(
                    IN p_actualitemcode BIGINT,
                    IN p_mindiscount     BIGINT,
					IN p_maxdiscount     BIGINT,
                    IN p_description VARCHAR(50),
				    IN p_arbdescription VARCHAR(50),
				    IN p_startdate VARCHAR(50),
				    IN p_enddate VARCHAR(50),
				    IN p_active VARCHAR(50),
				    IN p_discountkey BIGINT,
				    IN createdby VARCHAR(30)
    )
BEGIN
	DECLARE rowcnt INT DEFAULT 0;
	DECLARE insid INT DEFAULT 0;
	DECLARE from_start INT DEFAULT 1;
	DECLARE inner_start INT DEFAULT 1;
	
	
	IF p_discountkey = 0 OR p_discountkey IS NULL THEN
		INSERT INTO `discountkeyheader`(
			`description`,
			`arbdescription`,
			`startdate`,
			`enddate`,
			`active`
		) VALUES (
			p_description,
			p_arbdescription,
			p_startdate,
			p_enddate,
			p_active
		);	
		
		SELECT LAST_INSERT_ID() INTO p_discountkey;
		CALL sp_add_logmaster_information('1','Discount Key','discountkeyheader',p_discountkey,createdby,'Add');
	END IF;
	
	SELECT COUNT(*) INTO rowcnt FROM discountkeydetail WHERE ( discountkey = p_discountkey AND actualitemcode = 0);
	
	IF rowcnt = 0 THEN
	
		SELECT COUNT(*) INTO rowcnt FROM discountkeydetail WHERE ( discountkey = p_discountkey AND actualitemcode = p_actualitemcode);
		
		IF rowcnt > 0 THEN
			SELECT 'duplicate' AS 'result';			
		ELSE
			
			IF p_actualitemcode = 0 THEN
				DELETE FROM discountkeydetail WHERE discountkey = p_discountkey;
				
				SELECT COUNT(actualitemcode) INTO @main_cnt FROM itemmaster WHERE activeitem = '1';
				
				SELECT CEILING(@main_cnt/500) INTO @total_loop;
				
				SET @start_limit = 0;
				
				WHILE from_start <= @total_loop DO
				
 					
					SET @qry 	= CONCAT("SELECT COUNT(actualitemcode), CAST( GROUP_CONCAT( actualitemcode ) AS CHAR(2048) ) INTO @inner_cnt,@grpitmcd  FROM ( SELECT actualitemcode FROM itemmaster WHERE activeitem = 1 ORDER BY actualitemcode LIMIT ",@start_limit,",500 ) a");
					
					PREPARE s1 FROM @qry;
					EXECUTE s1;
					
					SET @start_limit = @start_limit+500;
					
					
					
					SET inner_start = 0;
					WHILE inner_start <= @inner_cnt DO
				
						SET @itemcode = split(@grpitmcd,',',inner_start);
						
						INSERT INTO discountkeydetail(
							discountkey,
							actualitemcode,
							mindiscount,
							maxdiscount,
							mdat
						)VALUES(
							p_discountkey,
							@itemcode,
							p_mindiscount,
							p_maxdiscount,
							CURRENT_DATE()
						);
						
						SET inner_start = inner_start + 1;
					
					END WHILE;
					
					SET from_start = from_start + 1;
				
				END WHILE;
				
				SELECT "added" AS 'result';
			ELSE
				INSERT INTO discountkeydetail(
					discountkey,
					actualitemcode,
					mindiscount,
					maxdiscount,
					mdat
				)VALUES(
					p_discountkey,
					p_actualitemcode,
					p_mindiscount,
					p_maxdiscount,
					CURRENT_DATE()
				);
				SELECT "added" AS 'result';
			END IF;
			
		END IF;
	ELSE
		SELECT 'duplicate' AS 'result';	
	END IF;
	
	SELECT p_discountkey AS lastid;
    END */$$
DELIMITER ;

