	VALUES
	(in_routekey,in_visitkey,in_transactionkey,in_customer,CURRENT_DATE(),in_amount_due,in_output,1);
 
   
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_transaction_processload_addprocessload` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_transaction_processload_addprocessload` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_transaction_processload_addprocessload`(
IN in_processload_id INT,
IN in_route_code INT,
IN in_decimal_point INT,
IN in_route_key INT,
IN in_salesman_code INT
)
BEGIN
DECLARE in_last_insert_id INT;
DECLARE in_bache_key INT;
	UPDATE routemaster SET  bodocseq = IFNULL(bodocseq,0) + 1
	WHERE  routecode =in_route_code;
	
	
	INSERT INTO inventorytransactionheader 
		(inventorykey,routekey,transactiontype,routecode,salesmancode,transactiondate, 
		transactiontime,documentnumber,voidflag,loadnumber,refdocumentnumber,
		currencycode,actualtransactiondate,inventorynumber)
	SELECT 
		in_route_key,in_route_key,1,in_route_code,in_salesman_code,DATE(CURRENT_DATE()),
		TIME(CURRENT_DATE()),get_number_type_base(in_route_code,2),0,
		in_processload_id,0,get_default_currencycode(),CURRENT_DATE(),0 ;
	SELECT LAST_INSERT_ID() INTO in_last_insert_id;
	
	SELECT IFNULL(MAX(batchdetailkey),0) INTO  in_bache_key  FROM batchexpirydetail
	WHERE routekey = in_route_key;
	
	SET in_bache_key = in_bache_key + 1;	
	
	INSERT INTO inventorytransactiondetail 
	(routekey,detailkey,transactiontypecode,itemcode,quantity,weighted,itemprice,batchdetailkey,
	itemcaseprice,	currencycode
	)
	SELECT in_route_key,in_last_insert_id,1,itemcode,
	((SUM(cases) * upc) + SUM(units)),0,
	sld.salesprice,
	in_bache_key,
	sld.caseprice,get_default_currencycode()
	
	FROM startingloaddetail sld
	WHERE routecode = in_route_code AND loadperiodnumber = in_processload_id
	AND ddate=DATE(CURRENT_DATE())
	GROUP BY itemcode,routecode,loadperiodnumber;
	
	UPDATE startingloaddetail SET `status` = 1
	WHERE routecode = in_route_code AND loadperiodnumber = in_processload_id;
		
	
	INSERT INTO `batchexpirydetail` 
	( batchdetailkey,batchnumber,itemcode,expirydate,quantity,transactiontypecode,routekey,visitkey)
 
	SELECT in_bache_key,batchnumber,itemcode,expirydate,((cases * upc) + (units)) AS qty , 1 ,in_route_key,0
	FROM startingloaddetail sld
	WHERE routecode = in_route_code AND loadperiodnumber = in_processload_id
	AND ddate=DATE(CURRENT_DATE());
	
	
	INSERT INTO batchmaster (quantity,batchdetailkey,batchnumber,itemcode,damagequantity,expirydate,routekey )
	SELECT 0,in_bache_key,batchnumber,itemcode,0,expirydate,in_route_key
	FROM startingloaddetail 
	JOIN itemmaster ON actualitemcode = itemcode
	WHERE routecode = in_route_code AND loadperiodnumber = in_processload_id
	AND ddate=DATE(CURRENT_DATE()) AND  NOT EXISTS 
	(
		SELECT itemcode,batchnumber FROM batchmaster WHERE startingloaddetail.itemcode = batchmaster.itemcode
								AND batchmaster.batchnumber = startingloaddetail.batchnumber
								AND batchmaster.routekey = in_route_key
	);
	
	
	UPDATE batchmaster ,startingloaddetail
	SET 
	batchmaster.quantity =batchmaster.quantity +((startingloaddetail.cases * startingloaddetail.upc) + (startingloaddetail.units))
	WHERE 
	batchmaster.itemcode = startingloaddetail.itemcode AND
	batchmaster.batchnumber = startingloaddetail.batchnumber AND
	startingloaddetail.routecode = in_route_code
	AND startingloaddetail.loadperiodnumber = in_processload_id
	AND batchmaster.routekey = in_route_key
	AND ddate = DATE(CURRENT_DATE());
	
	SELECT in_route_key,1,itemcode,((cases * upc) + (units)) ,startingloaddetail.salesprice ,startingloaddetail.caseprice
	FROM startingloaddetail 
	WHERE routecode = in_route_code AND loadperiodnumber = in_processload_id
	AND ddate=DATE(CURRENT_DATE())	
	GROUP BY itemcode,routecode,loadperiodnumber;
	
	
	
	
	UPDATE inventorysummarydetail
		SET loadqty = loadqty + (SELECT SUM(((s.cases * s.upc) + (s.units))) FROM startingloaddetail AS s 
				WHERE inventorysummarydetail.itemcode = s.itemcode
				AND  s.routecode = in_route_code AND s.loadperiodnumber = in_processload_id
				AND inventorysummarydetail.routekey = in_route_key
				 AND s.ddate=DATE(CURRENT_DATE())
				)
	WHERE EXISTS ( SELECT itemcode FROM startingloaddetail  AS s 
			WHERE inventorysummarydetail.itemcode = s.itemcode
				AND  s.routecode = in_route_code AND s.loadperiodnumber = in_processload_id 
				AND s.ddate=DATE(CURRENT_DATE())
			) AND inventorysummarydetail.routekey = in_route_key;
	INSERT INTO inventorysummarydetail
	(inventorykey,routekey,itemcode,loadqty,stdsalesprice,stdsalescaseprice,stdreturnprice,stdreturncaseprice,mdat,currencycode)
		(SELECT in_route_key,in_route_key,itemcode,SUM(((s.cases * s.upc) + (s.units))) AS qty ,
		i.defaultsalesprice,i.caseprice,i.defaultreturnprice,i.returncaseprice ,CURRENT_DATE(), get_default_currencycode_routecode(in_route_code)
		FROM startingloaddetail AS s 
		JOIN itemmaster AS i ON i.actualitemcode = s.itemcode
		WHERE s.routecode = in_route_code AND s.loadperiodnumber = in_processload_id 
		AND s.ddate = DATE(CURRENT_DATE())
		AND s.itemcode NOT IN( SELECT DISTINCT(s1.itemcode) FROM startingloaddetail  AS s1 
			JOIN inventorysummarydetail ON
			inventorysummarydetail.itemcode = s1.itemcode
			WHERE s1.routecode = in_route_code AND s1.loadperiodnumber = in_processload_id AND inventorysummarydetail.routekey = in_route_key
			AND s1.ddate = DATE(CURRENT_DATE()))
		GROUP BY s.itemcode
		);
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ajax_getitemsbydivision` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ajax_getitemsbydivision` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ajax_getitemsbydivision`(
    IN divisioncode VARCHAR(25)
)
BEGIN
    DECLARE st INT DEFAULT 0;
    -- Get flag value
    SELECT status INTO st FROM controlpanel WHERE flagname = 'Use Alternate Code';
    -- If divisioncode is NULL or empty, show all items
    IF divisioncode = 'ALL' THEN
        IF st = 1 THEN  
            SELECT actualitemcode AS id,
                   CONCAT(alternatecode, ' -- ', itemshortdescription) AS val
            FROM itemmaster
            WHERE activeitem = '1';
        ELSE
            SELECT actualitemcode AS id,
                   CONCAT(actualitemcode, ' -- ', itemshortdescription) AS val
            FROM itemmaster
            WHERE activeitem = '1';
        END IF;
    ELSE  -- Otherwise, filter by division
        IF st = 1 THEN  
            SELECT actualitemcode AS id,
                   CONCAT(alternatecode, ' -- ', itemshortdescription) AS val
            FROM itemmaster
            WHERE activeitem = '1'
              AND division = divisioncode;
        ELSE
            SELECT actualitemcode AS id,
                   CONCAT(actualitemcode, ' -- ', itemshortdescription) AS val
            FROM itemmaster
            WHERE activeitem = '1'
              AND division = divisioncode;
        END IF;
    END IF;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_APPROVE_loadstock_inventorytransactionheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_APPROVE_loadstock_inventorytransactionheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_APPROVE_loadstock_inventorytransactionheader`(			
			IN var_detailkey BIGINT,
			IN var_urgent INT(4),
			IN var_warehouse DECIMAL(18,0),
			IN var_date VARCHAR(30),
			IN var_user varchar(30)
		)
BEGIN
	
		UPDATE 	inventorytransactionheader SET isurgent = var_urgent, transferlocationcode = var_warehouse,
		requestdate = var_date,
		deliverydate = var_date,
		EG_LR_APPROVED = 1,
		EG_LR_APPROVED_DATE = now(),
		EG_LR_APPOVED_BY = var_user
		WHERE detailkey = var_detailkey;		
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_bulk_import_customermaster` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_bulk_import_customermaster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_bulk_import_customermaster`()
BEGIN									
	
 									
INSERT INTO CustomerMaster 
(
ANCustomerCode, TYPE, HeadOfficeCode, RouteCode, CustomerName, 									
ARBCustomerName, CustomerAddress1, ARBCustomerAddress1, CustomerAddress2, CustomerAddress3,ContactName, 									
ArbContactName, InvoicePaymentTerms,   CreditLimitDays, CreditLimit,ActiveCustomer, Memo1, Memo2, 									
AlternateCode,EnablePromoTrxn,EnableBuyBackFree,ForceStockCapture,EnableDraftCopy,enablereturnstrxn,									
enabledelayprint,enablesigcapture,enablearcollection,enabledamagedreturns,enablebatchselection,									
printsequence,invoicepriceprint,enablepromoeditinvs,enablepromoeditords,MDAT,pricingkey,enablesalestrxn,DivisionCode,									
graceperiod,Territory	,Class	,Region	,Transaction_Anals3	,GPSSaveCount	,Grouping_Code	,Outlet_Quality	,StatementDays	,
Analysis2,alternateroutecode,ALTERNATEPRICINGKEY,
chaincode,enableinvoicecomment,CreditTerms,itemmapkey,enforcemsl,taxregistrationnumber,applytax,customertaxidoptions, nrp_flag, enableadvancepayment,fixedlatitude,fixedlongitude,ccid,channel
)
SELECT customercode,1,headofficecode,(SELECT IFNULL( (SELECT RouteCode FROM routemaster WHERE alternateroutecode = routecode LIMIT 1) ,
(SELECT RouteCode FROM RouteMaster LIMIT 1))),REPLACE(CONVERT(customername USING ASCII), '?', ''),'',REPLACE(CONVERT(customeraddress1 USING ASCII), '?', ''),									
'',REPLACE(CONVERT(customeraddress2 USING ASCII), '?', ''),REPLACE(CONVERT(customeraddress3 USING ASCII), '?', ''),contactname,'',
CASE WHEN invoicepaymentterms='CASH' THEN 1 ELSE 2 END ,credit_days,CASE WHEN (invoicepaymentterms != 'CASH' AND creditlimit=0) THEN 1 ELSE creditlimit END  creditlimit ,
CASE WHEN active='A' THEN 1 ELSE 0 END ,memo1,
memo2,customercode, 2,0,0,0,4,1,2,1,3,0,2,1,3,1,NOW(),NULL,1,division_code,graceperiod,									
territory,class,	region,	 transaction_anals3,1,grouping_code,	outlet_quality,
0,					
orderlocation,routecode,pricingkey,'0',1 ,creditterms,(SELECT  customeritemgrpcode FROM customeritemgrp WHERE description=division_code),1,tax_reg_no,
CASE WHEN  vat_Flag='Y' THEN 2 ELSE 0 END,2, nrp_flag,1, SUBSTRING_INDEX(geocordinates, ',', 1), SUBSTRING_INDEX(geocordinates, ',', -1), ccid,grouping_code
FROM temp_customermaster WHERE customercode NOT IN (SELECT AlternateCode FROM customermaster);								
								
 		
		
UPDATE customermaster cm INNER JOIN Temp_CustomerMaster t ON t.customercode=cm.alternatecode 									
SET 									
cm.Grouping_Code	=  t.CreditTerms,
cm.channel = t.grouping_code,								
cm.Outlet_Quality	= t.outlet_quality,								
cm.StatementDays	= 0,	
cm.CreditLimitDays	= t.credit_days,								
cm.Analysis2	= t.orderlocation,								
cm.alternateroutecode	= t.routecode,								
cm.routecode= (SELECT IFNULL( (SELECT RouteCode FROM routemaster WHERE alternateroutecode = t.routecode LIMIT 1) ,(SELECT RouteCode FROM RouteMaster LIMIT 1))),									
cm.ALTERNATEPRICINGKEY	= t.pricingkey,								
cm.DivisionCode 	= t.division_code,								
cm.Territory	= t.territory,								
cm.Class	= t.class,								
cm.Region	= t.region,								
cm.Transaction_Anals3	= t.transaction_anals3,								
cm.CustomerName	= REPLACE(CONVERT(t.customername USING ASCII), '?', ''),								
cm.ARBCustomerName	= '',								
cm.CustomerAddress1	= REPLACE(CONVERT(t.customeraddress1 USING ASCII), '?', ''),								
cm.ARBCustomerAddress1	= '',								
cm.CustomerAddress2	= REPLACE(CONVERT(t.customeraddress2 USING ASCII), '?', ''),								
cm.CustomerAddress3	= REPLACE(CONVERT(t.customeraddress3 USING ASCII), '?', ''),								
cm.ContactName	= t.contactname,								
cm.ArbContactName	= '',								
cm.InvoicePaymentTerms	= CASE WHEN t.invoicepaymentterms='CASH' THEN 1 ELSE 2 END ,								
cm.itemmapkey	= (SELECT  customeritemgrpcode FROM customeritemgrp  WHERE  description=t.division_code),
cm.CreditLimit	= t.creditlimit,									
cm.ActiveCustomer 	= CASE WHEN t.active='A' THEN 1 ELSE 0 END ,								
cm.Memo1	= t.memo1,								
cm.Memo2	= t.memo2,								
cm.mdat=NOW()			,
cm.CreditTerms = 		t.creditterms ,
cm.taxregistrationnumber = 		t.tax_reg_no,
cm.applytax = 		CASE WHEN  vat_Flag='Y' THEN 2 ELSE 0 END,
cm.customertaxidoptions=2,
cm.nrp_flag = t.nrp_flag,
cm.enableadvancepayment = 1,
cm.fixedlatitude = CASE
        WHEN IFNULL(cm.fixedlatitude,0) = 0 THEN SUBSTRING_INDEX(t.geocordinates, ',', 1)
        ELSE cm.fixedlatitude
    END,
    cm.fixedlongitude = CASE
        WHEN IFNULL(cm.fixedlongitude,0) = 0 THEN SUBSTRING_INDEX(t.geocordinates, ',', -1)
        ELSE cm.fixedlongitude
    END,
   cm.ccid = t.ccid
WHERE cm.alternatecode=t.customercode;		
		
 						
	
SELECT ROW_COUNT() AS output;
INSERT INTO channelmaster (alternatecode,channelname,arbchannelname,created,cdat,modified,mdat) 
SELECT grouping_code,grouping_code,grouping_code,'admin',NOW(),'admin',NOW() FROM (SELECT DISTINCT grouping_code FROM temp_customermaster 
WHERE grouping_code NOT IN ( SELECT alternatecode FROM channelmaster))ch;
 
INSERT INTO categorymaster (alternatecode,categoryname,arbcategoryname,created,cdat,modified,mdat) 
SELECT v_Class,v_Class,v_Class,'admin',NOW(),'admin',NOW() FROM 
(SELECT DISTINCT class AS v_Class FROM temp_customermaster WHERE class NOT IN
 ( SELECT alternatecode FROM categorymaster))cat;
 
	
								
 									
 END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_bulk_import_customer_outstanding` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_bulk_import_customer_outstanding` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_bulk_import_customer_outstanding`()
BEGIN
 
DELETE FROM customerinvoice;	
INSERT INTO CustomerInvoice(TransactionKey,TransactionType,DocumentNumber,InvoiceNumber,TransactionDate,CustomerCode,
 RouteCode,
SalesmanCode,TotalInvoiceAmount,TotalSalesAmount,InvoiceBalance,PaymentType,VoidFlag,PaymentStatus,HHCInvoiceNumber,
Remarks1,Remarks2,RouteStartDate,ERPReferenceNumber,MDat,AmountPaid,duedate)
SELECT  @curRank := @curRank + 1 AS 'rank',2 AS transactiontype,@curRank  AS docnumber,
@curRank  AS invoicenumber,transaction_date,
 sfacst.customercode  ,rm.routecode,
rm.salesmancode,total_invoice_amount,total_invoice_amount,invoice_balance,2,0,0,total_invoice_amount,refernce,
'Balance from ERP',NULL,REPLACE(CONVERT(invoice_number USING ASCII), '?', ''),NOW(),
total_invoice_amount-invoice_balance,
(CASE
    WHEN sfacst.CreditTerms='DFS' THEN DATE_ADD(DATE_FORMAT(transaction_date + INTERVAL 1 MONTH,'%Y-%m-01'),INTERVAL sfacst.statementdays DAY ) 
    ELSE DATE_ADD(transaction_date,INTERVAL sfacst.statementdays DAY )
END)
 AS duedate
FROM temp_customerinvoice rec 
INNER JOIN customermaster sfacst ON sfacst.alternatecode  =rec.customer_code
AND sfacst.customercode IS NOT NULL
INNER JOIN routemaster rm ON rm.routecode=rec.route_code
INNER JOIN (SELECT @curRank := 0) r ON 1=1;
 
 UPDATE CUSTOMERMASTER CM Left outer  JOIN (SELECT customercode,SUM(invoicebalance) AS invoicebalance FROM customerinvoice GROUP BY customercode ) ci ON ci.customercode=cm.customercode  
SET balance=ifnull(ci.invoicebalance,0);
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_bulk_import_divisionmaster` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_bulk_import_divisionmaster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_bulk_import_divisionmaster`()
BEGIN
INSERT INTO DivisionMaster
SELECT id,NAME,NAME,'admin', NOW(),'admin',NOW(),NRP_FLAG FROM temp_divisionmaster WHERE id NOT IN (SELECT divisioncode FROM DivisionMaster) ;
INSERT INTO company (cmpycode,NAME,parentcompany,address,telephone,activestatus,mdat,cdat,alternatecmpycode,entity)
SELECT id,NAME,1,'','12345678',1,NOW(),NOW(),id,LEDGER_NAME FROM temp_divisionmaster WHERE id NOT IN (SELECT cmpycode FROM company) ;
update company inner join temp_divisionmaster on id=cmpycode
 set alternatecmpycode=id,entity = LEDGER_NAME;
UPDATE DivisionMaster dv INNER JOIN temp_divisionmaster t ON t.id=dv.DivisionCode 									
SET dv.divisionname=t.name,
    MDat=NOW(), dv.NRP_FLAG = t.nrp_flag;
UPDATE ITEMMASTER SET DIV_NRP_FLAG = (SELECT nrp_flag FROM divisionmaster WHERE divisionmaster.divisionname = itemmaster.DIVISION);    
SELECT ROW_COUNT() AS output;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_bulk_import_item` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_bulk_import_item` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_bulk_import_item`()
BEGIN
 
 
 
 
  
 
 INSERT INTO companygroup SELECT DISTINCT '' ,division_code,1,division_code,division_code,'ADMIN',NOW(),NULL,NULL,1  FROM temp_itemmaster 
 WHERE division_code NOT IN (SELECT Alternatecode FROM companygroup);
 
 UPDATE companygroup  INNER JOIN temp_itemmaster ON alternatecode=division_code
 SET companygroup.description=division_code,arbdescription=division_code,modified='admin',mdat=NOW()  ;
 
 
 
 
 INSERT INTO MAJORCATEGORY SELECT '' ,(SELECT DISTINCT companygroupcode FROM companygroup WHERE alternatecode=division_code)  ,brand_code,brand_code,brand_code,'ADMIN',NOW(),NULL,NULL,1
FROM temp_itemmaster 
 WHERE brand_code NOT IN (SELECT alternatecode FROM MAJORCATEGORY) GROUP BY brand_code ;
 
 
UPDATE MAJORCATEGORY INNER JOIN temp_itemmaster   ON alternatecode=brand_code
 SET MAJORCATEGORY.description=brand_code,arbdescription=brand_code,modified='admin',mdat=NOW() 
 WHERE alternatecode=brand_code ;
 
 
 
 
 INSERT INTO subMAJORCATEGORY SELECT '' ,category_code,(SELECT DISTINCT majorcategorycode FROM majorcategory WHERE alternatecode=brand_code) , category_code,category_code,'ADMIN',NOW(),NULL,NULL,1  FROM temp_itemmaster  WHERE
 category_code  NOT IN (SELECT alternatecode FROM subMAJORCATEGORY) GROUP BY category_code;
  
 UPDATE SUBMAJORCATEGORY INNER JOIN temp_itemmaster   ON alternatecode=category_code
 SET SUBMAJORCATEGORY.description=category_code,arbdescription=category_code,modified='admin',mdat=NOW() WHERE alternatecode=category_code  ;
 
 
 INSERT INTO Itemgroup SELECT '' ,(SELECT DISTINCT submajorcategorycode FROM submajorcategory   WHERE alternatecode= category_code LIMIT 1),sub_category_code , sub_category_code,sub_category_code,'ADMIN',NOW(),NULL,NULL,sub_category_code,1 FROM temp_itemmaster WHERE 
 sub_category_code  NOT IN (SELECT alternateitemgroupcode FROM Itemgroup) GROUP BY sub_category_code;
 
 UPDATE itemgroup INNER JOIN temp_itemmaster   ON alternateitemgroupcode=sub_category_code
 SET Itemgroupname=sub_category_code,arbitemgroup=sub_category_code,modified='admin',mdat=NOW() 
 WHERE alternateitemgroupcode=sub_category_code;
 
 
 
 
 
INSERT INTO itemmaster 
	(actualitemcode, 	itemgroupcode, 	itemtype, 	itemshortdescription, 	itemdescription, 	unitspercase, 	defaultsalesprice, 	defaultreturnprice, 	defaultretailprice, 	pricingkey, 	arbitemshortdescription, 	arbitemdescription, 	hhcitemshortdescription, 	hhcitemdescription, 	activeitem, 	caseprice, 	returncaseprice, 	retailcaseprice, 	alternatecode, 	created, 	cdat, 	modified, 	mdat, 	liter, 	dataentry, 	leadtime, 	viewflag, 	case1, 	case2, 	memo1, 	memo2, 	tcallowed, 	itemgroupingcode, 	printsequenceroute, 	printsequencecust, 	upccasecode, 	captureshelfstock, 	filmbagbarcode, 	boxtraybarcode, 	cartonbarcode, 	highper, 	lowper, 	literperunit, 	commissionallowedflag, 	alternateitemgroupcode, 	fastmovingitemflag, 	codedateformat, 	 	itemtaxkey3, 	defpricetaxkey1, 	defpricetaxkey2, 	defpricetaxkey3, 	packagecode, 	anitemcode, 	averagesales, 	enablemeatpiecescapture, 	itemcompany, 	caseuom, 	warehousestock, 	itemgrpcode, 	parentitemcode, 	shelflife, 	defaultgoodreturnprice, 	defaultgoodreturncaseprice, 	maxpricechange, 	minpricechange, 	allowbatchentry, 	costcaseprice, 	defaultcostprice, 	allowinvoicepricechange, 	reportitemcode, 	offtakeparameter, 	barcode1, 	barcode2, 	barcode3, 	barcode4, 	barcode5, 	barcode6, 	barcode7, 	barcode8, 	barcode9, 	barcode10, 	division, 	majorcategorycode, 	majorcategorydesciption, 	submajorcategorycode, 	submajorcategorydesciption, 	companygroupcode, 	companygroupname, 	itemgroupname, 	itemexpirychk, 	shelflifecapture,Sales_Account,cos_cost_account,cos_stock_account,nominal_category,itemtaxkey2,enabletax, nrp_flag,div_nrp_flag	)
	
SELECT '',(SELECT itemgroupcode FROM ItemGroup WHERE alternateitemgroupcode = sub_category_code), 1,REPLACE(CONVERT(temp_itemmaster.description USING ASCII), '?', ''),REPLACE(CONVERT(long_description USING ASCII), '?', ''),upc,sellingprcbyunit,retunprcbyunit,sellingprcbyunit,NULL,'','','','',CASE WHEN active="A" THEN 1 ELSE 0 END,sellingprcbyct,retunprcbyct,sellingprcbyct,itemcode,'admin',NOW(),'null',NULL,0,0,0,0,0,0,'','','0','null','0','1',uom,'null','0','0','NULL','NULL','NULL','NULL','NULL',itemcode,'0','0','0','0','0','0','0',itemcode,'NULL','0','1','1','NULL','NULL','0','0',retunprcbyunit,retunprcbyct,'0','0','0','0','0','0',itemcode,'0',barcode,'barcode2','barcode3','barcode4','barcode5','barcode6','barcode7','barcode8','barcode9','barcode10',division_code,(SELECT IFNULL(MAX(majorcategorycode),0)+1 FROM MAJORCATEGORY), brand_code,(SELECT IFNULL(MAX(submajorcategorycode),0)+1 FROM SUBMAJORCATEGORY),category_code,(SELECT IFNULL(MAX(companygroupcode),0)+1 FROM companygroup),division_code,sub_category_code,'0','0','','','','',
(SELECT taxcode FROM tbltaxmaster WHERE taxdescription=VAT_CODE ),
case when vat_flag='Y' then 1 else 0 end, nrp_flag,	
(select nrp_flag from divisionmaster WHERE divisionmaster.divisionname = temp_itemmaster.division_code )	
FROM temp_itemmaster WHERE itemcode NOT IN (SELECT Alternatecode FROM ItemMaster );
	
 
UPDATE itemmaster INNER JOIN temp_itemmaster ON Alternatecode=itemcode
SET itemshortdescription =	REPLACE(CONVERT(temp_itemmaster.description USING ASCII), '?', '')	,
itemdescription =	REPLACE(CONVERT(long_description USING ASCII), '?', '')	,
unitspercase =	upc	,
defaultsalesprice =	sellingprcbyunit	,
defaultreturnprice =	retunprcbyunit	,
defaultretailprice =	sellingprcbyunit	,
activeitem =	CASE WHEN active="A" THEN 1 ELSE 0 END	,
caseprice =	sellingprcbyct	,
returncaseprice =	retunprcbyct	,
retailcaseprice =	sellingprcbyct	,
modified =	'admin'	,
mdat =	NOW()	,
memo1 =	''	,
memo2 =	''	,
alternateitemgroupcode =	itemcode	,
anitemcode =	itemcode	,
defaultgoodreturnprice =	retunprcbyunit	,
defaultgoodreturncaseprice =	retunprcbyct	,
reportitemcode =	itemcode	,
barcode1 =	barcode	,
division =	division_code	,
majorcategorydesciption =	brand_code	,
submajorcategorydesciption =	category_code	,
companygroupname =	division_code	,
companygroupcode = (SELECT companygroupcode FROM companygroup WHERE alternatecode=division_code),
itemgroupname =	sub_category_code	,
Sales_Account=	''	,
cos_cost_account=	''	,
cos_stock_account=	''	,
nominal_category=	'',
itemgroupcode=(SELECT itemgroupcode FROM itemgroup WHERE alternateitemgroupcode=sub_category_code),
majorcategorycode=(SELECT majorcategorycode FROM majorcategory WHERE alternatecode=brand_code),
submajorcategorycode=(SELECT submajorcategorycode FROM submajorcategory WHERE alternatecode=category_code),
upccasecode=uom	,
itemtaxkey2=(SELECT taxcode FROM tbltaxmaster WHERE taxdescription=VAT_CODE ),
enabletax=CASE WHEN vat_flag='Y' THEN 1 ELSE 0 END,
ITEMMASTER.`NRP_FLAG` = temp_itemmaster.`nrp_flag`,
itemmaster.div_nrp_flag = (select nrp_flag from divisionmaster WHERE divisionmaster.divisionname = itemmaster.DIVISION );
																																					
																																							 																																							
INSERT INTO customeritemgrp 
(customeritemgrpcode,description,created,cdat,modified,mdat,transferstatus)
SELECT DISTINCT '',division_code,'admin',NOW(),'admin',NOW(),1 
FROM temp_itemmaster WHERE division_code 
NOT IN (SELECT description FROM customeritemgrp);  		
											
TRUNCATE TABLE  customeritemmapping;
INSERT INTO customeritemmapping SELECT customeritemgrpcode,im.actualitemcode,1 FROM   itemmaster im INNER JOIN temp_itemmaster t ON im.Alternatecode=t.itemcode INNER JOIN customeritemgrp ci ON ci.description=t.division_code
WHERE im.actualitemcode  NOT IN ( SELECT itemcode FROM customeritemmapping);
 
INSERT INTO routeitemgrp(routeitemgrpcode,itemgroupcode,description,created,cdat,modified,mdat,transferstatus) 
SELECT cm.code ,0,description,'admin',NOW(),'admin',NOW(),1  FROM companydata cm WHERE cm.code NOT IN (SELECT routeitemgrpcode FROM routeitemgrp);
	
   
TRUNCATE TABLE  routeitemmapping;	
/*	
INSERT INTO routeitemmapping(routeitemgrpcode,itemcode) 
SELECT distinct cm.code ,im.actualitemcode  FROM itemmaster im 
INNER JOIN companydata cm ON im.companygroupname=cm.description 
INNER JOIN temp_itemmaster t ON  im.Alternatecode=t.itemcode ;	
*/ 
/*SELECT DISTINCT 19 ,im.actualitemcode  FROM itemmaster im 
INNER JOIN companydata cm ON im.companygroupname=cm.description 
INNER JOIN temp_itemmaster t ON  im.Alternatecode=t.itemcode WHERE cm.code IN(1,18);
*/
INSERT INTO routeitemmapping(routeitemgrpcode,itemcode) 
	SELECT DISTINCT cm.code ,im.actualitemcode 
	FROM temp_itemmaster t
	INNER JOIN companydata cm ON cm.description  = t.division_code
	INNER JOIN itemmaster im ON im.alternatecode = t.itemcode;
INSERT INTO routeitemmapping(routeitemgrpcode,itemcode) 
	SELECT DISTINCT 19 ,im.actualitemcode  
	FROM itemmaster im 
	INNER JOIN temp_itemmaster t ON  im.Alternatecode=t.itemcode 
	INNER JOIN companydata cm ON t.division_code=cm.description 
	WHERE cm.code IN(1,18);
	
	
 
 -- INSERT INTO tbltaxmaster
  
 
SELECT ROW_COUNT() AS output; 
END */$$
DELIMITER ;

