/* Procedure structure for procedure `sp_bulk_import_merch` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_bulk_import_merch` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_bulk_import_merch`()
BEGIN									
	
insert into tts_merch_cust_master (cust_erp_code, cust_erp_cc_no, cust_name, cust_address1, cust_address2, cust_contact_name, cust_grp_code, cust_sts)
select distinct customercode , customercode , customername , customeraddress1 , customeraddress2 , contactname,1,1  
from temp_customermaster tc 
on duplicate key 
update cust_sts = case when Active = 'Y' then 1 else 0 end;	
		
delete from TTS_MERCH_CUST_ROUTE_MAP;
insert into TTS_MERCH_CUST_ROUTE_MAP(CUST_ERP_CODE, CUST_ROUTE_CODE)
select distinct CUSTOMERCODE, ROUTECODE from temp_customermaster ;
insert into tts_merch_div_master (div_name)
select distinct division_code  from temp_itemmaster
on DUPLICATE key 
update DIV_STS = 1;
insert into tts_merch_agency_master (agency_code, AGENCY_NAME)
select distinct agencycode , brand_code from temp_itemmaster
on DUPLICATE key 
update AGENCY_STS = 1;
insert into tts_merch_cate_master (CATE_NAME)
select distinct categorycode from temp_itemmaster 
on DUPLICATE key 
update CATE_STS = 1;
insert into tts_merch_subcate_master(subcate_name)
select distinct sub_category_code from temp_itemmaster 
on duplicate key 
update subcate_sts = 1;
insert into tts_merch_item_master (item_erp_code, item_grp_code , item_type, item_desc, 
item_short_desc , item_desc_arb , item_short_desc_arb ,
item_barcode1, item_div_code, item_div_name, 
item_agency_code, item_agency_name, item_cate_code, item_cate_name, item_sub_cate_code, item_sub_cate_name, item_sts)
select itemcode,1,1, description,description,description,description, barcode ,  
(select div_code from tts_merch_div_master tmdm where tmdm.div_name = i.division_code), division_code , 
(select agency_code from tts_merch_agency_master tmam where tmam.agency_name = i.brand_code), brand_code, 
(select cate_code from tts_merch_cate_master tmcm where tmcm.cate_name = i.categorycode), categorycode,
(select subcate_code from tts_merch_subcate_master tmsm where tmsm.subcate_name = i.sub_category_code), sub_category_code, 
case when active = 'A' then 1 else 0 end 
from temp_itemmaster i						
on duplicate key 
update item_sts = case when active = 'A' then 1 else 0 end ;
SELECT ROW_COUNT() AS output;
	
								
 									
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_bulk_import_pricing_key` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_bulk_import_pricing_key` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_bulk_import_pricing_key`()
BEGIN 
 
 
 
UPDATE customerpricingplanheader1 cp inner join (Select distinct pricing_key,price_list_status,pricingkey_generated from temp_pricingkey) t on cp.alternatecode=t.pricing_key  and pricingplankey= t.pricingkey_generated 
SET cp.description=t.pricing_key,cp.activeindicator=CASE WHEN t.price_list_status='A' THEN 1 ELSE 0 END
  ;
INSERT INTO customerpricingplanheader1
(pricingplankey,description,arbdescription,alternatecode,activeindicator)
SELECT  distinct pricingkey_generated,pricing_key,pricing_key,pricing_key,CASE WHEN price_list_status='A' THEN 1 ELSE 0 END from  temp_pricingkey 
where pricing_key not in ( select IFNULL(alternatecode,'') FROM customerpricingplanheader1 ) ;
 
 
 
 
 
 
UPDATE customerpricing1 inner join temp_pricingkey on alternatecode=pricing_key
SET customerpricing1.Description=pricing_key,
customerpricing1.enddate =  end_date,
active =CASE WHEN price_list_status='A' THEN 1 ELSE 0 END;
INSERT INTO customerpricing1
(CustomerPricingKey,PricingPlanKey,Sequencecode,Description,ARBDescription,active,startdate,enddate,alternatecode)
SELECT    distinct pricingkey_generated,pricingkey_generated,'',pricing_key,'',CASE WHEN price_list_status='A' THEN 1 ELSE 0 END ,start_date,end_date,pricing_key from temp_pricingkey 
where pricing_key not in (select IFNULL(alternatecode,'') from customerpricing1) ;
 
 
 
 UPDATE pricingplanheader1 inner join temp_pricingkey on  
 customerpricingkey=pricingkey_generated
SET pricingplanheader1.Description=pricing_key,active=CASE WHEN price_list_status='A' THEN 1 ELSE 0 END ;
 
INSERT INTO pricingplanheader1(CustomerPricingKey,Description,ARBDescription,TYPE,active)
SELECT  distinct pricingkey_generated,pricing_key,'','1',CASE WHEN price_list_status='A' THEN 1 ELSE 0 END
from temp_pricingkey where pricingkey_generated not in (select customerpricingkey from pricingplanheader1) ;
 
 delete from pricingdetail1;
 
 
INSERT INTO pricingdetail1(CustomerPricingKey,ItemCode,SalesPrice,ReturnPrice,RetailPrice, SalesCasePrice,ReturnCasePrice,created,cdat,modified,mdat)
 SELECT  
	pricingkey_generated ,
	(SELECT actualitemcode FROM itemmaster WHERE alternatecode=item_code),
	special_piece_price,
	special_return_price,
	'',
	special_case_price,
	special_return_case_price,
	"admin",
	NOW(),
	"admin",NOW() 
 from temp_pricingkey A 
 WHERE 
	(END_DATE >= CURDATE() or end_date = '0000-00-00')
	AND START_DATE = (SELECT MAX(START_DATE) FROM temp_pricingkey B WHERE A.PRICING_KEY = B.`pricing_key` AND A.ITEM_CODE = B.ITEM_CODE);
	--  where item_code not in (SELECT actualitemcode  FROM itemmaster );
 
 -- ARUN ADDED line number 61, 62, 63 to remove dulicate in Plan - Item Price
 
 UPDATE customermaster cm inner join pricingplanheader1 pp on ALTERNATEPRICINGKEY=pp.description
set cm.pricingkey=pp.customerpricingkey;
 
SELECT ROW_COUNT() AS output; 
END */$$
DELIMITER ;

