BEGIN
INSERT INTO productgroupdetail (groupnumber,itemcode,itemqty,promopcprice,promocaseprice,mdat,alternatecode,modified,divison) 
SELECT epgh.groupnumber,eim.actualitemcode,itemqty,promopcprice,promocaseprice,pkd.mdat,pkd.alternatecode,pkd.modified,pkd.divison
