/* Procedure structure for procedure `sp_bulk_import_salesmanstock` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_bulk_import_salesmanstock` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_bulk_import_salesmanstock`()
BEGIN
 
INSERT INTO startingloaddetail (ddate,routecode,salesmancode,loadperiodnumber,itemcode,caseprice,cases,
				units,upc,salesprice,batchnumber,expirydate,`status`,
				returnprice,returncaseprice,transactiondate,
				totunits,suggtotunits,rcvdtotunits,currencycode,
				warehouse,warehousestock,loadtime,erpreferencenumber)
				(
				SELECT 	date_received,routecode,
				(SELECT salesmancode FROM routemaster WHERE routecode=ts.routecode LIMIT 1),
				( SELECT  IFNULL(MAX(loadperiodnumber),0)+1 FROM startingloaddetail  WHERE ddate=date_received AND routecode=ts.routecode  ),
				IM.ACTUALITEMCODE,
				IM.CASEPRICE,
				-- CASE WHEN issued_qty BETWEEN 0.9 AND 1 THEN 1 ELSE FLOOR(issued_qty) END AS cases,	
				FLOOR(issued_qty) AS cases,			
				-- CAST( (CASE WHEN issued_qty BETWEEN 0.9 AND 1 THEN 1 ELSE FLOOR(issued_qty) END) *IM.UNITSPERCASE AS UNSIGNED) MOD IM.UNITSPERCASE  AS units,
				cast(issued_qty*IM.UNITSPERCASE AS UNSIGNED) MOD IM.UNITSPERCASE  AS units,				
				unitspercase,
				defaultsalesprice,'',
				NULL,
				0,
				defaultreturnprice,
				returncaseprice,
				date_received,
				CAST(issued_qty*IM.UNITSPERCASE AS UNSIGNED),0,0,1,
				subinventory_code,0,CURRENT_TIME(),
				erp_transfer_number
				FROM ITEMMASTER IM INNER JOIN temp_salesmanstock ts ON ALTERNATECODE=item_code 
				WHERE  ts.routecode NOT IN (SELECT routecode FROM startingloaddetail sld INNER JOIN itemmaster im ON im.actualitemcode=sld.itemcode WHERE ddate=	
		ts.date_received AND routecode=ts.routecode AND  im.alternatecode=ts.item_code AND erpreferencenumber =ts.erp_transfer_number) );
		
		 
			 
				  
				 
	
 
 
SELECT ROW_COUNT() AS output; 
END */$$
DELIMITER ;

