DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_checkusername_account_salesman_addsalesman`(in sid bigint,IN salesman_username varchar(50))
BEGIN
	
	if sid > 0 then 
