/* Procedure structure for procedure `sp_check_ordertransaction_salesorderadd_promotionqualified` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_check_ordertransaction_salesorderadd_promotionqualified` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_check_ordertransaction_salesorderadd_promotionqualified`(
IN in_routekey INT,
IN in_visitkey INT,
IN in_qualification_group_no INT
)
BEGIN
	
	
	
	IF in_qualification_group_no = 1 THEN
	
		SELECT IFNULL(FORMAT(SUM( IF(sales_amount = '0.0000', ((salesqty / itemmaster.unitspercase) *
			salesorderdetail_temp.salescaseprice
			+ ((salesqty % itemmaster.unitspercase) * salesorderdetail_temp.salesprice)) ,sales_amount)),4),0) AS SalesAmount,
			IFNULL(SUM(IFNULL(salesorderdetail_temp.salesqty,0)),0) AS SalesQty
		FROM salesorderdetail_temp  ,itemmaster 
		WHERE itemmaster.actualitemcode = salesorderdetail_temp.itemcode 
		AND salesorderdetail_temp.routekey = in_routekey 
		AND salesorderdetail_temp.visitkey = in_visitkey
		
		;
	
	ELSE
		SELECT IFNULL(FORMAT(SUM( IF(sales_amount = '0.0000', ((salesqty / itemmaster.unitspercase) *
			salesorderdetail_temp.salescaseprice
			+ ((salesqty % itemmaster.unitspercase) * salesorderdetail_temp.salesprice)) ,sales_amount)),4),0) AS SalesAmount,
			IFNULL(SUM(IFNULL(salesorderdetail_temp.salesqty,0)),0) AS SalesQty
		FROM salesorderdetail_temp , productgroupdetail ,itemmaster 
		WHERE   salesorderdetail_temp.itemcode = productgroupdetail.itemcode
		AND  itemmaster.actualitemcode = productgroupdetail.itemcode 
		AND salesorderdetail_temp.routekey = in_routekey 
		AND salesorderdetail_temp.visitkey = in_visitkey
		AND productgroupdetail.groupnumber =in_qualification_group_no	
		;	
		
	END IF;
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_check_ordertransaction_salesorderadd_promotionqualified_fixed` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_check_ordertransaction_salesorderadd_promotionqualified_fixed` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_check_ordertransaction_salesorderadd_promotionqualified_fixed`(
	IN in_assignmentno INT,
	IN in_customercode INT,
	IN in_routekey INT,
	IN in_visitkey INT,
	IN in_planno INT
)
BEGIN
DECLARE where_cluase TEXT DEFAULT "";
DECLARE flag BOOLEAN DEFAULT FALSE;
	SET where_cluase = "salesqty >= productgroupdetail.itemqty";
	
	SET @del1 = CONCAT("SELECT COUNT(*) into @cnt
				FROM promokeydetail
				INNER JOIN productgroupdetail
				ON  promokeydetail.qualificationgroup = productgroupdetail.groupnumber
				WHERE promokeydetail.assignmentnumber = ",in_assignmentno,"
				AND promokeydetail.promotionkey = (SELECT promotionkey 
									FROM customermaster 
									WHERE customercode = ",in_customercode,")
				AND promokeydetail.plannumber = ",in_planno," AND productgroupdetail.itemqty !=0
				AND productgroupdetail.itemcode NOT IN(SELECT salesorderdetail_temp.itemcode 
									FROM salesorderdetail_temp 
									WHERE salesorderdetail_temp.routekey = ",in_routekey,"
									AND salesorderdetail_temp.visitkey  = ",in_visitkey ,"
									AND ",where_cluase," )");
	PREPARE s1 FROM @del1;
	EXECUTE s1;
	
	IF @cnt = 0 THEN
		SET flag = TRUE;
	END IF;
IF flag = TRUE THEN 
	SELECT IFNULL((salesorderdetail_temp.salesqty),0) AS SalesQty,
		(((CAST((salesqty / itemmaster.unitspercase) AS UNSIGNED) * (salesorderdetail_temp.salescaseprice)) + (CAST((salesqty % itemmaster.unitspercase) AS UNSIGNED) * salesorderdetail_temp.salesprice))) AS SalesAmount,
		productgroupdetail.itemcode,itemqty,onetimeuse
	FROM promokeydetail
	INNER JOIN promoplandetail
	    ON promoplandetail.plannumber=promokeydetail.plannumber
	INNER JOIN productgroupdetail
	    ON  promokeydetail.qualificationgroup = productgroupdetail.groupnumber
	INNER JOIN salesorderdetail_temp
	    ON productgroupdetail.itemcode = salesorderdetail_temp.itemcode AND salesorderdetail_temp.routekey = in_routekey AND salesorderdetail_temp.visitkey  = in_visitkey
	INNER JOIN itemmaster
	    ON itemmaster.actualitemcode = productgroupdetail.itemcode
	WHERE promokeydetail.assignmentnumber = in_assignmentno
	AND promokeydetail.promotionkey = (SELECT promotionkey
					    FROM customermaster
					    WHERE customercode = in_customercode)
	AND promokeydetail.plannumber = in_planno;
END IF;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_check_returns` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_check_returns` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_check_returns`(
	 IN var_routekey BIGINT(20)
	)
BEGIN
	
	DECLARE cu_visitkey BIGINT(20);
	DECLARE cu_transactionkey BIGINT(20);
	DECLARE cu_itemcode BIGINT(20);
	DECLARE cu_freeqty BIGINT(20);
	DECLARE cu_missedqty BIGINT(20);
		
	DECLARE done INT DEFAULT FALSE;
		
	DECLARE cur_one CURSOR FOR 
		(SELECT id.visitkey, id.transactionkey, id.itemcode, id.manualfreeqty ID_FreeQty, SUM(CASE WHEN rx.itemtransactiontype = 3 THEN rx.quantity ELSE 0 END) RX_FreeQty
			FROM invoicedetail id
				LEFT OUTER JOIN invoicerxddetail rx ON rx.transactionkey = id.transactionkey AND rx.itemcode = id.itemcode
				JOIN startendday sed ON sed.routekey = id.routekey AND sed.routekey = var_routekey
			GROUP BY id.visitkey, id.transactionkey, id.itemcode, id.manualfreeqty
			HAVING ID_FreeQty > 0 AND ID_FreeQty <> RX_FreeQty);
		
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
	
	OPEN cur_one;
	read_loop_one: LOOP
		
		FETCH cur_one INTO cu_visitkey, cu_transactionkey, cu_itemcode, cu_freeqty, cu_missedqty;
			
			IF done = TRUE THEN
				LEAVE read_loop_one;
			END IF;
						
			INSERT INTO invoicerxddetail (routekey,visitkey,transactionkey,itemtransactiontype,itemcode,itemtranstypeseq,reasoncode,quantity,catchweightqty,weighted,
				instructioncode,currencycode) 
			VALUES (var_routekey, cu_visitkey, cu_transactionkey, 3, cu_itemcode, 0, 7, cu_freeqty, 0, 0, 0, 2)
			ON DUPLICATE KEY UPDATE 
				quantity = cu_freeqty;
			
	END LOOP read_loop_one;
	
	CLOSE cur_one;
	
					
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_check_transaction_customer_creditlimit` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_check_transaction_customer_creditlimit` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_check_transaction_customer_creditlimit`(
In in_customer_bal float(10,2),
in in_customer_code int
)
BEGIN
	
	SELECT 
		(  CASE WHEN balance > 0 THEN IF((creditlimit - balance) >= in_customer_bal,1,0)
		   ELSE  IF(creditlimit >= in_customer_bal,1,0) END) AS status_creditlimit
	FROM customermaster 
	WHERE customercode = in_customer_code
	AND invoicepaymentterms IN(2,3,4);
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_check_transaction_invoiceadd_promotionqualified` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_check_transaction_invoiceadd_promotionqualified` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_check_transaction_invoiceadd_promotionqualified`(
IN in_routekey INT,
IN in_visitkey INT,
in in_qualification_group_no int
)
BEGIN
	
	if in_qualification_group_no = 1 then
	
	SELECT IFNULL(FORMAT(SUM( IF(sales_amount = '0.0000', ((salesqty / itemmaster.unitspercase) *
			invoicedetail_temp.salescaseprice
		+ ((salesqty % itemmaster.unitspercase) * invoicedetail_temp.salesprice)) ,sales_amount)),4),0) AS SalesAmount,
		IFNULL(SUM(IFNULL(invoicedetail_temp.salesqty,0)),0) AS SalesQty,
		IFNULL(FORMAT(SUM( IF(return_amount = '0.0000', ((returnqty / itemmaster.unitspercase) *
			invoicedetail_temp.goodreturncaseprice
		+ ((returnqty % itemmaster.unitspercase) * invoicedetail_temp.goodreturnprice)) ,return_amount)),4),0) AS ReturnAmount,
		IFNULL(SUM(IFNULL(invoicedetail_temp.returnqty,0)),0) AS ReturnQty
	FROM invoicedetail_temp ,itemmaster 
	WHERE  itemmaster.actualitemcode = invoicedetail_temp.itemcode 
	AND invoicedetail_temp.routekey = in_routekey 
	AND invoicedetail_temp.visitkey = in_visitkey
	
	;
	
	else
	
	
	SELECT IFNULL(FORMAT(SUM( IF(sales_amount = '0.0000', ((salesqty / itemmaster.unitspercase) *
			invoicedetail_temp.salescaseprice
		+ ((salesqty % itemmaster.unitspercase) * invoicedetail_temp.salesprice)) ,sales_amount)),4),0) AS SalesAmount,
		IFNULL(SUM(IFNULL(invoicedetail_temp.salesqty,0)),0) AS SalesQty,
		
		IFNULL(FORMAT(SUM( IF(return_amount = '0.0000', ((returnqty / itemmaster.unitspercase) *
			invoicedetail_temp.goodreturncaseprice
		+ ((returnqty % itemmaster.unitspercase) * invoicedetail_temp.goodreturnprice)) ,return_amount)),4),0) AS ReturnAmount,
		IFNULL(SUM(IFNULL(invoicedetail_temp.returnqty,0)),0) AS ReturnQty
	FROM invoicedetail_temp , productgroupdetail ,itemmaster 
	
	WHERE   invoicedetail_temp.itemcode = productgroupdetail.itemcode
	and  itemmaster.actualitemcode = productgroupdetail.itemcode 
	AND invoicedetail_temp.routekey = in_routekey 
	AND invoicedetail_temp.visitkey = in_visitkey
	AND productgroupdetail.groupnumber =in_qualification_group_no	
	;	
	
	end if;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_check_transaction_invoiceadd_promotionqualified_fixed` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_check_transaction_invoiceadd_promotionqualified_fixed` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_check_transaction_invoiceadd_promotionqualified_fixed`(
in in_assignmentno INT,
in in_customercode INT,
IN in_routekey INT,
IN in_visitkey INT,
IN in_planno INT,
in in_transaction_type int
)
BEGIN
declare where_cluase text DEFAULT "";
DECLARE flag boolean default false;
IF in_transaction_type = 3 then 
	
	SET where_cluase = "salesqty >= productgroupdetail.itemqty";
	SET @del1 = CONCAT("SELECT COUNT(*) into @salescnt
				FROM promokeydetail
				INNER JOIN productgroupdetail
				ON  promokeydetail.qualificationgroup = productgroupdetail.groupnumber
				WHERE promokeydetail.assignmentnumber = ",in_assignmentno,"
				AND promokeydetail.promotionkey = (SELECT promotionkey 
									FROM customermaster 
									WHERE customercode = ",in_customercode,")
				AND promokeydetail.plannumber = ",in_planno," AND productgroupdetail.itemqty !=0
				AND productgroupdetail.itemcode NOT IN(SELECT invoicedetail_temp.itemcode 
									FROM invoicedetail_temp 
									WHERE invoicedetail_temp.routekey = ",in_routekey,"
									AND invoicedetail_temp.visitkey  = ",in_visitkey ,"
									AND ",where_cluase," )");
	PREPARE s1 FROM @del1;
	EXECUTE s1;
					
	SET where_cluase = "returnqty >= productgroupdetail.itemqty";
	SET @del1 = CONCAT("SELECT COUNT(*) into @reutrncnt
				FROM promokeydetail
				INNER JOIN productgroupdetail
				ON  promokeydetail.qualificationgroup = productgroupdetail.groupnumber
				WHERE promokeydetail.assignmentnumber = ",in_assignmentno,"
				AND promokeydetail.promotionkey = (SELECT promotionkey 
									FROM customermaster 
									WHERE customercode = ",in_customercode,")
				AND promokeydetail.plannumber = ",in_planno," AND productgroupdetail.itemqty !=0
				AND productgroupdetail.itemcode NOT IN(SELECT invoicedetail_temp.itemcode 
									FROM invoicedetail_temp 
									WHERE invoicedetail_temp.routekey = ",in_routekey,"
									AND invoicedetail_temp.visitkey  = ",in_visitkey ,"
									AND ",where_cluase," )");
	PREPARE s1 FROM @del1;
	EXECUTE s1;
	
	if @salescnt = 0 or @reutrncnt = 0 then
		set flag = true;
	end if;
else
	IF in_transaction_type = 1 THEN
		SET where_cluase = "salesqty >= productgroupdetail.itemqty";
	ELSEIF in_transaction_type = 2 THEN 
		SET where_cluase = "returnqty >= productgroupdetail.itemqty";
	END IF;
	SET @del1 = CONCAT("SELECT COUNT(*) into @cnt
				FROM promokeydetail
				INNER JOIN productgroupdetail
				ON  promokeydetail.qualificationgroup = productgroupdetail.groupnumber
				WHERE promokeydetail.assignmentnumber = ",in_assignmentno,"
				AND promokeydetail.promotionkey = (SELECT promotionkey 
									FROM customermaster 
									WHERE customercode = ",in_customercode,")
				AND promokeydetail.plannumber = ",in_planno," AND productgroupdetail.itemqty !=0
				AND productgroupdetail.itemcode NOT IN(SELECT invoicedetail_temp.itemcode 
									FROM invoicedetail_temp 
									WHERE invoicedetail_temp.routekey = ",in_routekey,"
									AND invoicedetail_temp.visitkey  = ",in_visitkey ,"
									AND ",where_cluase," )");
	PREPARE s1 FROM @del1;
	EXECUTE s1;
	
	IF @cnt = 0 THEN
		SET flag = TRUE;
	END IF;
end if;
if flag = TRUE then 
	select ifnull((invoicedetail_temp.salesqty),0) As SalesQty,
		(((CAST((salesqty / itemmaster.unitspercase) AS Unsigned) * (invoicedetail_temp.salescaseprice)) + (CAST((salesqty % itemmaster.unitspercase) AS UNSIGNED) * invoicedetail_temp.salesprice))) As SalesAmount,
		IFNULL((invoicedetail_temp.returnqty),0) AS ReturnQty,
		(((CAST((returnqty / itemmaster.unitspercase) AS UNSIGNED) * (invoicedetail_temp.goodreturncaseprice)) + (CAST((returnqty % itemmaster.unitspercase) AS UNSIGNED) * invoicedetail_temp.goodreturnprice))) AS ReturnAmount,
		productgroupdetail.itemcode,itemqty,onetimeuse
	from promokeydetail
	inner join promoplandetail
	    on promoplandetail.plannumber=promokeydetail.plannumber
	inner join productgroupdetail
	    on  promokeydetail.qualificationgroup = productgroupdetail.groupnumber
	inner join invoicedetail_temp
	    on productgroupdetail.itemcode = invoicedetail_temp.itemcode and invoicedetail_temp.routekey = in_routekey and invoicedetail_temp.visitkey  = in_visitkey
	inner join itemmaster
	    on itemmaster.actualitemcode = productgroupdetail.itemcode
	where promokeydetail.assignmentnumber = in_assignmentno
	and promokeydetail.promotionkey = (select promotionkey
					    from customermaster
					    where customercode = in_customercode)
	and promokeydetail.plannumber = in_planno;
end if;
END */$$
DELIMITER ;

