/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_combo_account_customermaster_routecode`( IN routeid BIGINT(18))
BEGIN
		
	SELECT `status` INTO @st FROM controlpanel WHERE flagname = 'Use Alternate Code';
	
	IF @st = 1 THEN 
		SELECT customercode AS id, CONCAT(alternatecode,' -- ',customername) AS val FROM customermaster WHERE activecustomer = 1 AND templateindicator = 0 AND routecode = routeid AND invoicepaymentterms IN(2,3,4) AND `type` IN (1,2);
	ELSE
		SELECT customercode AS id, CONCAT(customercode,' -- ',customername) AS val FROM customermaster WHERE activecustomer = 1 AND templateindicator = 0 AND routecode = routeid  AND invoicepaymentterms IN(2,3,4) AND `type` IN (1,2);
	END IF;
	
	
END */$$
