/* Procedure structure for procedure `sp_combo_customermaster_depotcode` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_combo_customermaster_depotcode` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_combo_customermaster_depotcode`(in depotid bigint)
BEGIN
		
	SELECT `status` INTO @st FROM controlpanel WHERE flagname = 'Use Alternate Code';
	
	IF @st = 1 THEN 	
		SELECT cm.customercode as id , CONCAT(alternatecode,' -- ',customername) as val FROM routemaster rm,subareamaster sam,areamaster am,
			depotmaster dm,customermaster cm
			WHERE sam.subareacode = rm.subareacode AND am.areacode = sam.areacode AND dm.depotcode = am.depotcode
			AND rm.routecode = cm.routecode AND dm.depotcode = depotid AND activecustomer = 1 AND templateindicator = 0;
	ELSE
		SELECT cm.customercode AS id , CONCAT(cm.customercode,' -- ',customername) AS val FROM routemaster rm,subareamaster sam,areamaster am,
			depotmaster dm,customermaster cm
			WHERE sam.subareacode = rm.subareacode AND am.areacode = sam.areacode AND dm.depotcode = am.depotcode
			AND rm.routecode = cm.routecode AND dm.depotcode = depotid AND activecustomer = 1 AND templateindicator = 0;
	END IF;
END */$$
DELIMITER ;

