/* Procedure structure for procedure `sp_combo_customer_routewise_collection` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_combo_customer_routewise_collection` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_combo_customer_routewise_collection`(
in var_route_code int
)
BEGIN
	
	SELECT `status` INTO @st FROM controlpanel WHERE flagname = 'Use Alternate Code';
	
	IF @st = 1 THEN 
		SELECT customercode AS id, CONCAT(alternatecode,' -- ',customername) AS val FROM customermaster WHERE activecustomer = 1 AND templateindicator = 0 and customermaster.routecode =var_route_code 
		and customermaster.type != 3 and customermaster.invoicepaymentterms in(2,3,4); 
	ELSE
		SELECT customercode AS id, CONCAT(customercode,' -- ',customername) AS val FROM customermaster WHERE activecustomer = 1 AND templateindicator = 0 AND customermaster.routecode =var_route_code
		AND customermaster.type != 3 AND customermaster.invoicepaymentterms IN(2,3,4);  
	END IF;
    
END */$$
DELIMITER ;

