BEGIN
	
	select `status` into @st from controlpanel where flagname = 'Use Alternate Code';
	
	if @st = 1 then 
		SELECT actualitemcode AS id, CONCAT(alternatecode,' -- ',itemshortdescription) AS val FROM itemmaster WHERE activeitem = '1' and itemgroupcode = groupcode;
	else
		SELECT actualitemcode AS id, CONCAT(actualitemcode,' -- ',itemshortdescription) AS val FROM itemmaster WHERE activeitem = '1' AND itemgroupcode = groupcode;
	end if;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_combo_itemmaster_itemmustlist` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_combo_itemmaster_itemmustlist` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_combo_itemmaster_itemmustlist`( 
in agency varchar(18),
in brand varchar(18),
in category varchar(18),
in subcateg varchar(18)
)
BEGIN
	
	declare where_agency text;
	declare where_brand text;
	declare where_catgry text;
	declare where_subcat text;  
	SET where_agency ="";
	SET where_brand  ="";
	SET where_catgry ="";
	SET where_subcat ="";
	
	IF agency > 0 THEN 
		SET where_agency = CONCAT(' AND companygroupcode IN (',agency,')'); 
	END IF;
	IF brand > 0 THEN 
		SET where_brand = CONCAT(' AND majorcategorycode IN (',brand,')'); 
	END IF;
	IF category > 0 THEN 
		SET where_catgry = CONCAT(' AND submajorcategorycode IN ( ',category,')'); 
	END IF;
	IF subcateg > 0 THEN 
		SET where_subcat = CONCAT(' AND itemgroupcode IN (',subcateg,')'); 
	END IF;
	select `status` into @st from controlpanel where flagname = 'Use Alternate Code';
	if @st = 1 then 
		SET @q1 = CONCAT(" SELECT actualitemcode AS id, CONCAT(alternatecode,' -- ',itemshortdescription) AS val FROM itemmaster WHERE activeitem = '1' ",where_agency," ",where_brand," ",where_catgry," ",where_subcat," ");
	else
		SET @q1 = CONCAT( "SELECT actualitemcode AS id, CONCAT(actualitemcode,' -- ',itemshortdescription) AS val FROM itemmaster WHERE aactiveitem = '1' ",where_agency," ",where_brand," ",where_catgry," ",where_subcat," ");
	end if;
	PREPARE s1 FROM @q1;  
    EXECUTE s1; 
	
	IF agency > 0 and brand  <=0 and category <=0 THEN 
		SET @agq1 = CONCAT("SELECT DISTINCT majorcategorycode AS id, CONCAT(majorcategorycode,' -- ',majorcategorydesciption) AS val FROM itemmaster  WHERE  companygroupcode IN (",agency,")");
		PREPARE ags1 FROM @agq1;  
		EXECUTE ags1;
		 
		SET @agq2 = CONCAT("SELECT DISTINCT submajorcategorycode AS id, CONCAT(submajorcategorycode,' -- ',smc.submajorcategorydesciption) AS val FROM itemmaster smc WHERE smc.companygroupcode IN  (",agency,")");
		PREPARE ags2 FROM @agq2;  
		EXECUTE ags2;
		 
		SET @agq3 = CONCAT("SELECT DISTINCT itemgroupcode AS id, CONCAT(itemgroupcode,' -- ',itemgroupname) AS val FROM itemmaster ig
								 WHERE ig.companygroupcode IN (",agency,")");
		PREPARE ags3 FROM @agq3;  
		EXECUTE ags3; 
	END IF;
	IF brand > 0  and category <=0 THEN 
		SET @bq1 = CONCAT("SELECT DISTINCT submajorcategorycode AS id, CONCAT(submajorcategorycode,' -- ',submajorcategorydesciption)  AS val FROM itemmaster smc
						 WHERE smc.majorcategorycode IN (",brand,")");
		PREPARE bs1 FROM @bq1;  
		EXECUTE bs1; 
		SET @bq2 = CONCAT("SELECT DISTINCT itemgroupcode AS id, CONCAT(itemgroupcode,' -- ',itemgroupname) AS val FROM itemmaster ig 
								 WHERE ig.majorcategorycode IN (",brand,")");
		PREPARE bs2 FROM @bq2;  
		EXECUTE bs2; 
	END IF;
	IF category > 0 THEN 
		SET @cq1 = CONCAT("SELECT DISTINCT itemgroupcode AS id, CONCAT(itemgroupcode,' -- ',itemgroupname) AS val FROM itemmaster ig
						 WHERE ig.submajorcategorycode IN (",category,")");
		PREPARE cs1 FROM @cq1;  
		EXECUTE cs1; 
	END IF;
	
END */$$
DELIMITER ;

