/* Procedure structure for procedure `sp_combo_poscustomer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_combo_poscustomer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_combo_poscustomer`(IN flag INT)
BEGIN
	
	
	IF flag = 0 THEN 
		SELECT `status` INTO @st FROM controlpanel WHERE flagname = 'Use Alternate Code';		
		IF @st = 1 THEN 			
			SELECT customercode AS id, CONCAT(alternatecode,' -- ',customername) AS val FROM customermaster
				WHERE customercode NOT IN(SELECT customercode FROM customerposlimit customercode)
				AND activecustomer = 1 AND templateindicator = 0;
		ELSE
			SELECT customercode AS id, CONCAT(customercode,' -- ',customername) AS val FROM customermaster
				WHERE customercode NOT IN(SELECT customercode FROM customerposlimit customercode)
				AND activecustomer = 1 AND templateindicator = 0;
		END IF;		
	ELSE 
			CALL sp_combo_customermaster();
	END IF;
END */$$
DELIMITER ;

