/* Procedure structure for procedure `sp_combo_reason` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_combo_reason` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_combo_reason`(IN in_type VARCHAR(50))
BEGIN
	IF in_type = 'return' THEN
		SELECT retitmreasons.code,retitmreasons.description FROM retitmreasons;
	ELSEIF in_type = 'bad' THEN
		SELECT expiryreturnreasons.code,expiryreturnreasons.description FROM expiryreturnreasons;
	ELSEIF in_type = 'goodreturn' THEN	
		SELECT reason_code AS `code` ,reason_desc AS description  FROM freegoodreasons;
	ELSE
		SELECT nonservreasons.code,nonservreasons.description FROM nonservreasons;
	END IF;
END */$$
DELIMITER ;

