/* Procedure structure for procedure `sp_cron_average_sales_quantity` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_cron_average_sales_quantity` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_cron_average_sales_quantity`(IN var_routecode BIGINT(28))
BEGIN
    SELECT defaultrequestdays INTO @defaultrequestdays FROM routemaster WHERE routecode = var_routecode;
    
    IF @defaultrequestdays > 0 THEN
    
		DELETE FROM averagesalesqty WHERE routecode = var_routecode;
	
	
		INSERT INTO averagesalesqty(itemcode,routecode,itemqty)
		SELECT id.itemcode,red.routecode,FORMAT(AVG(id.salesqty),0) AS avgqty
		FROM invoicedetail AS id
		JOIN startendday AS red ON red.routekey = id.routekey 
		JOIN routemaster AS rm ON rm.routecode = red.routecode
		WHERE red.routestartdate >= (CURDATE() - INTERVAL rm.defaultrequestdays DAY)
		AND rm.loadreqrolluporders = 1 AND rm.routecode = var_routecode
		GROUP BY itemcode,routecode HAVING routecode > 0 
		ON DUPLICATE KEY UPDATE itemqty =  VALUES(itemqty);
				
	END IF;	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_customer_mapping_key_update` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_customer_mapping_key_update` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_customer_mapping_key_update`(
			IN var_catid        BIGINT,
			IN var_routecode 	BIGINT,
			IN var_customerid   TEXT,
			IN var_counter      INT
    )
BEGIN
		DECLARE from_start INT;	
		SET from_start = 1;
		
						
		SELECT GROUP_CONCAT(a.customercode) INTO @cstids FROM customermaster AS a 
		            INNER JOIN routesequence AS rs ON rs.customercode=a.customercode
				WHERE rs.routecode = var_routecode  and  a.itemmapkey = var_catid;
		IF @cstids != ''  THEN 
			SET @dlt = CONCAT("UPDATE customermaster SET itemmapkey = 0 WHERE customercode IN (",@cstids,")");
			PREPARE s1 FROM @dlt;
			EXECUTE s1;
		END IF;
		WHILE from_start <= var_counter DO
			SET @cust_code = '';
			SET @cust_code = split(var_customerid,',',from_start);
			UPDATE customermaster SET itemmapkey = var_catid WHERE customercode =  @cust_code;
			SET from_start = from_start + 1;
		END WHILE;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_customer_planogram_key_update` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_customer_planogram_key_update` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_customer_planogram_key_update`(
			IN var_catid        BIGINT,
			IN var_routecode 	BIGINT,
			IN var_customerid   TEXT,
			IN var_counter      INT
    )
BEGIN
		DECLARE from_start INT;	
		SET from_start = 1;
		
				
		SELECT GROUP_CONCAT(a.customercode) INTO @cstids FROM customermaster AS a WHERE a.visualcode = var_catid AND routecode = var_routecode;
		IF @cstids != ''  THEN 
			SET @dlt = CONCAT("UPDATE customermaster SET visualcode = 0 WHERE customercode IN (",@cstids,")");
			PREPARE s1 FROM @dlt;
			EXECUTE s1;
		END IF;
		
		WHILE from_start <= var_counter DO
			SET @cust_code = '';
			SET @cust_code = split(var_customerid,',',from_start);
			UPDATE customermaster SET visualcode = var_catid WHERE customercode =  @cust_code;
			SET from_start = from_start + 1;
		END WHILE;
		
    END */$$
DELIMITER ;

