								FROM customermaster where customercode in (",@filter_id,")
							)");
				
		PREPARE s2 FROM @ins;
		EXECUTE s2;
		
		
		SET @del = CONCAT("DELETE FROM customermaster WHERE customercode IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		
		CALL sp_add_logmaster_information(@counter,'Customers','customermaster',@filter_id,deletedby,'delete');		
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
		
	ELSE 
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;		
	END IF;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_account_customer_customercluster` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_account_customer_customercluster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_account_customer_customercluster`(
    IN var_mapping_ids TEXT
)
BEGIN
    DECLARE deleted_ids TEXT DEFAULT '';

    SELECT GROUP_CONCAT(id ORDER BY id)
    INTO deleted_ids
    FROM customerclustermapping
    WHERE FIND_IN_SET(CAST(id AS CHAR), var_mapping_ids) > 0;

    DELETE FROM customerclustermapping
    WHERE divisioncode IN
    (
        SELECT divisioncode
        FROM
        (
            SELECT DISTINCT divisioncode
            FROM customerclustermapping
            WHERE FIND_IN_SET(
                CAST(id AS CHAR),
                var_mapping_ids
            ) > 0
        ) AS selected_divisions
    );

    SELECT COALESCE(deleted_ids, '') AS deleted_id;
END */$$
DELIMITER ;

