/* Procedure structure for procedure `sp_delete_account_notes_creditnotecustomer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_account_notes_creditnotecustomer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_account_notes_creditnotecustomer`( 
				IN ids TEXT,
				IN deletedby VARCHAR(25)
				)
BEGIN
	DECLARE from_start INT(11) DEFAULT 1;
	DECLARE inv_from_start INT(11) DEFAULT 1;
	DECLARE cst_from_start INT(11) DEFAULT 1;
	DECLARE var_trankey BIGINT(18);	
	DECLARE lstart INT(11) DEFAULT 0;	
	DECLARE var_pdc_cash INT(1);
	
	SELECT getpdctocashstatus() INTO var_pdc_cash;
	
	
	
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(transactionkey) into @counter,@filter_id FROM dcarheader 
			where pdcstatus <> 2  AND transactionkey in(",ids,")");
			
	PREPARE s1 FROM @chk;
	EXECUTE s1;
	
	
	IF @filter_id != '' THEN		
		WHILE from_start <= @counter DO
			SET var_trankey = split(@filter_id,',',from_start);			
			
			
			SET @chk1 = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(customercode) into @cst_cnt,@cstcode FROM dcardetail 
			where transactionkey = ",var_trankey);	
			PREPARE s2 FROM @chk1;
			EXECUTE s2;
			SET cst_from_start = 1;
			SET lstart 		   = 0;
			
			WHILE cst_from_start <= @cst_cnt DO
				SET @cstno = split(@cstcode,',',cst_from_start);
				SET @q = CONCAT("SELECT amountpaid,customercode,paymentmode INTO @totalinvamot,@var_customercode,@paymentmode FROM dcardetail WHERE transactionkey = ",var_trankey," AND customercode = ",@cstno," LIMIT ",lstart,",1");
				PREPARE s FROM @q;
				EXECUTE s;
				
				IF @paymentmode = 0 OR var_pdc_cash = 1 THEN 
					UPDATE customermaster SET balance = balance+@totalinvamot WHERE customercode = @var_customercode;
					
					SELECT headofficecode INTO @headofficecode FROM customermaster WHERE `type` = 2 AND customercode = @var_customercode;
					IF @var_customercode != @headofficecode THEN 
						UPDATE customermaster SET balance = balance+@totalinvamot WHERE customercode = @headofficecode;
					END IF;
				END IF;
				SET cst_from_start = cst_from_start + 1;
				SET lstart 		= lstart + 1;
			END WHILE;
			
			
			
			SET @chk1 = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(invoicenumber) into @inv_cnt,@inv_filter_id FROM dcardetail 
			where transactionkey = ",var_trankey);
			PREPARE s2 FROM @chk1;
			EXECUTE s2;
			
			SET inv_from_start = 1;			
			
			WHILE inv_from_start <= @inv_cnt DO
				SET @invono = split(@inv_filter_id,',',inv_from_start);
				
				
				
				SELECT amountpaid,paymentmode INTO @amountpaid,@paymentmode FROM dcardetail WHERE transactionkey = var_trankey AND invoicenumber = @invono;
				
				
				IF @paymentmode = 0 OR var_pdc_cash = 1 THEN
					UPDATE customerinvoice SET amountpaid = amountpaid-@amountpaid,cnamountpaid = cnamountpaid-@amountpaid,invoicebalance = invoicebalance+@amountpaid
						WHERE invoicenumber = @invono;
				ELSE
						SELECT pdcbalance INTO @pdcbalance  FROM customerinvoice WHERE invoicenumber = @invono;
						
						IF (@pdcbalance-@amountpaid) = 0 THEN
							UPDATE customerinvoice SET pdcindicator = 0, pdcbalance = pdcbalance-@amountpaid,pdcdate = '0000-00-00'
								WHERE invoicenumber = @invono;
						ELSE
							UPDATE customerinvoice SET pdcbalance = pdcbalance-@amountpaid
								WHERE invoicenumber = @invono;
						END IF;
				END IF;
				SET inv_from_start = inv_from_start + 1;				
			END WHILE;
			
			SET from_start = from_start + 1;
			
		END WHILE;
		
		
		SET @del = CONCAT("DELETE FROM dcarheader WHERE transactionkey IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		
		SET @del = CONCAT("DELETE FROM dcardetail WHERE transactionkey IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		
		SET @del = CONCAT("DELETE FROM dcarcashcheckdetail WHERE transactionkey IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		
		CALL sp_add_logmaster_information(@counter,'Credit Note(Customer)','dcarheader',@filter_id,deletedby,'Delete');
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
		
	ELSE 
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;		
	END IF;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_account_notes_creditnoteroute` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_account_notes_creditnoteroute` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_account_notes_creditnoteroute`( 
				IN ids TEXT,
				IN deletedby VARCHAR(25)
				)
BEGIN
	
	DECLARE from_start INT(11) DEFAULT 1;
	DECLARE var_trankey BIGINT(18);
	DECLARE var_routecode BIGINT(18);
	DECLARE totalinvamot DECIMAL(18,4);
	
	
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(transactionkey) into @counter,@filter_id FROM dcarheader 
			where transactionkey in(",ids,")");
	
	PREPARE s1 FROM @chk;
	EXECUTE s1;
	
	
	IF @filter_id != '' THEN
		
		WHILE from_start <= @counter DO
			SET var_trankey = split(@filter_id,',',from_start);
			SELECT amountpaid,routecode INTO totalinvamot,var_routecode FROM dcarheader WHERE transactionkey = var_trankey;
			UPDATE routemaster SET routebalance = routebalance+totalinvamot WHERE routecode = var_routecode;
			SET from_start = from_start + 1;
		END WHILE;
		
		
		SET @del = CONCAT("DELETE FROM dcarheader WHERE transactionkey IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		
		CALL sp_add_logmaster_information(@counter,'Credit Note (Route)','dcarheader',@filter_id,deletedby,'Delete');
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
		
	ELSE 
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;		
	END IF;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_account_note_debitnotecustomer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_account_note_debitnotecustomer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_account_note_debitnotecustomer`( 
				IN ids TEXT,
				IN deletedby VARCHAR(25)
				)
BEGIN
	
	DECLARE from_start INT(11) DEFAULT 1;
	DECLARE inv_from_start INT(11) DEFAULT 1;
	DECLARE var_trankey BIGINT(18);
	DECLARE var_customercode BIGINT(18);
	DECLARE totalinvamot DECIMAL(18,4);
	
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(transactionkey) into @counter,@filter_id FROM dcarheader 
			where transactionkey in(",ids,")");
	
	PREPARE s1 FROM @chk;
	EXECUTE s1;
	
	
	IF @filter_id != '' THEN
	
		WHILE from_start <= @counter DO
			SET var_trankey = split(@filter_id,',',from_start);
			SELECT amountpaid,customercode INTO totalinvamot,var_customercode FROM dcarheader WHERE transactionkey = var_trankey;
			UPDATE customermaster SET balance = balance-totalinvamot WHERE customercode = var_customercode;
			
			
			SELECT headofficecode INTO @headofficecode FROM customermaster WHERE `type` = 2 AND customercode = var_customercode;
			IF var_customercode != @headofficecode THEN 
				UPDATE customermaster SET balance = balance-totalinvamot WHERE customercode = @headofficecode;
			END IF;
			
			
			SET @chk1 = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(invoicenumber) into @inv_cnt,@inv_filter_id FROM dcardetail 
			where transactionkey = ",var_trankey);	
			PREPARE s2 FROM @chk1;
			EXECUTE s2;
			SET inv_from_start = 1;
			
			WHILE inv_from_start <= @inv_cnt DO
				SET @invono = split(@inv_filter_id,',',inv_from_start);
				SELECT amountpaid,invoicebalance INTO @amountpaid,@invoicebalance FROM dcardetail WHERE transactionkey = var_trankey AND invoicenumber = @invono;
				UPDATE customerinvoice SET dnamountpaid = dnamountpaid-@amountpaid,invoicebalance = invoicebalance-@amountpaid WHERE invoicenumber = @invono;
				SET inv_from_start = inv_from_start + 1;
			END WHILE;
			
			SET from_start = from_start + 1;			
		END WHILE;
		
		
		SET @del = CONCAT("DELETE FROM dcarheader WHERE transactionkey IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		
		SET @del = CONCAT("DELETE FROM dcardetail WHERE transactionkey IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		
		SET @del = CONCAT("DELETE FROM dcarcashcheckdetail WHERE transactionkey IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		
		CALL sp_add_logmaster_information(@counter,'Debit Note (Customer)','dcarheader',@filter_id,deletedby,'Delete');
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
		
		
		
	ELSE 
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;		
	END IF;
		
    END */$$
DELIMITER ;

