/* Procedure structure for procedure `sp_delete_basic_index_bankmaster` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_basic_index_bankmaster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_basic_index_bankmaster`( 
				IN ids TEXT,
				IN deletedby VARCHAR(25)				
				)
BEGIN
	
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(bankcode) into @counter,@filter_id FROM bankmaster 
		WHERE 
			(
				bankcode NOT IN (SELECT bankcode from cashcheckdetail where bankcode IN (",ids,"))			
			)	
		AND bankcode IN (",ids,")");	
	PREPARE s1 FROM @chk;
	EXECUTE s1;
		
	if @counter > 0 then
		
		
		SET @ins = CONCAT("insert into bankmaster_history (bankcode,bankname,arbbankname,bankbalance,created,cdat,
					modified,mdat,activestatus,alternatecode,`type`,acnumber,deleted,ddat)
					(
						select bankcode,bankname,arbbankname,bankbalance,created,cdat,
								modified,mdat,activestatus,alternatecode,`type`,acnumber,'",deletedby,"',CURRENT_DATE()
							from bankmaster where bankcode in (",@filter_id,")
					)");
		PREPARE s2 FROM @ins;
		EXECUTE s2;	
	
		SET @del = CONCAT("DELETE FROM bankmaster WHERE bankcode IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		
		CALL sp_add_logmaster_information(@counter,'Bank Master','bankmaster',@filter_id,deletedby,'delete');
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
		
	ELSE 
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;
	end if;
		
END */$$
DELIMITER ;

