DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_basic_index_cluster`(
    IN var_ids TEXT,
    IN var_modified VARCHAR(100)
)
BEGIN
    DECLARE deleted_ids TEXT DEFAULT '';

    SELECT GROUP_CONCAT(clustercode ORDER BY clustercode)
    INTO deleted_ids
    FROM clustermaster
    WHERE FIND_IN_SET(clustercode, var_ids) > 0;

    DELETE FROM clustermaster
    WHERE FIND_IN_SET(clustercode, var_ids) > 0;

    SELECT IFNULL(deleted_ids, '') AS deleted_id;
END */$$
