DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_basic_index_company`( 
				IN ids text,
				in deletedby varchar(25)				
				)
BEGIN
	
	
	
	set @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(cmpycode) into @counter,@filter_id FROM company 
			where 	( 
						cmpycode NOT IN(SELECT parentcompany FROM regionmanager WHERE parentcompany in(",ids,"))
						AND cmpycode NOT IN(SELECT cmpycode FROM depotmaster WHERE cmpycode in(",ids,"))
						AND cmpycode NOT IN(SELECT cmpycode FROM routemaster WHERE cmpycode in(",ids,"))
						AND cmpycode NOT IN(SELECT cmpycode FROM country WHERE cmpycode in(",ids,"))
						AND cmpycode NOT IN(SELECT parentcompany FROM regionmanager WHERE parentcompany in(",ids,"))
						AND cmpycode NOT IN(SELECT parentcompany FROM branchmanager WHERE parentcompany in(",ids,"))						
						AND cmpycode NOT IN(SELECT parentcompany FROM supervisor WHERE parentcompany in(",ids,"))
						AND cmpycode NOT IN(SELECT parentcompany FROM salesman WHERE parentcompany in(",ids,"))						
						AND cmpycode NOT IN(SELECT parentcompany FROM nationalsalesmanager WHERE parentcompany in(",ids,")) 
					)
				AND cmpycode in(",ids,")");
	
	prepare s1 from @chk;
	execute s1;
	
	
	if @filter_id != '' then
		
		set @ins = concat("INSERT INTO company_history(cmpycode,`name`,address,telephone,fax,nationalsalesmanagercode,contactname,
					city,country,arbcompanyname,alternatecmpycode,created,cdat,
					modified,mdat,zipcode,countrycode,countryname,arbcountryname,
					distributorcode1,distributorcode2,activestatus,parentcompany,deleted,ddat) 
				(
					SELECT cmpycode,`name`,address,telephone,fax,nationalsalesmanagercode,contactname,
						city,country,arbcompanyname,alternatecmpycode,created,cdat,
						modified,mdat,zipcode,countrycode,countryname,arbcountryname,
						distributorcode1,distributorcode2,activestatus,parentcompany,'",deletedby,"',CURRENT_DATE()
					FROM company where cmpycode in (",@filter_id,")
				)");
				
		PREPARE s2 FROM @ins;
		EXECUTE s2;
		
		
		SET @del = concat("DELETE FROM company WHERE cmpycode IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		
		call sp_add_logmaster_information(@counter,'Company','company',@filter_id,deletedby,'delete');		
		
		select 'Success' as result,@filter_id as deleted_id;
		
	else 
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;		
	end if;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_basic_index_currency` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_basic_index_currency` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_basic_index_currency`(
				IN ids TEXT,
				IN deletedby VARCHAR(25)
				)
BEGIN
	
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(currencycode) into @counter,@filter_id FROM currencymaster WHERE currencycode IN (",ids,")");
	PREPARE s1 FROM @chk;
	EXECUTE s1;
	IF @counter > 0 THEN
		SET @del = CONCAT("DELETE FROM currencymaster WHERE currencycode IN (",@filter_id,")");
		PREPARE s1 FROM @del;
		EXECUTE s1;
		
		CALL sp_add_logmaster_information(@counter,'Currency','currencymaster',@filter_id,deletedby,'delete');
		SELECT 'Success' AS result,@filter_id AS deleted_id;
	ELSE 
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;
	END IF;
END */$$
DELIMITER ;

