/* Procedure structure for procedure `sp_delete_datamanagement_deletedata_allcustomer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_datamanagement_deletedata_allcustomer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_datamanagement_deletedata_allcustomer`(				
				IN deletedby VARCHAR(25)
				)
BEGIN
	DECLARE record_id       BIGINT(18);
	DECLARE record_info     VARCHAR(100);
	DECLARE from_start 		INT(4) DEFAULT 1;
	DECLARE cust_counter 	BIGINT(18);
	DECLARE cust_code 		LONGTEXT;
	DECLARE cust_name 		LONGTEXT;
	
SET FOREIGN_KEY_CHECKS = 0;	
	
	SELECT IFNULL(COUNT(*),0),GROUP_CONCAT(customercode),GROUP_CONCAT(customername) 
		INTO cust_counter,cust_code,cust_name
		FROM customermaster WHERE (customercode NOT IN(SELECT customercode FROM routesequence)								
								AND customercode NOT IN(SELECT customercode FROM customerinvoice))
							ORDER BY customercode ASC;
	
	
	IF cust_counter > 0 THEN
		
		
		SET @del = CONCAT("DELETE FROM customermaster WHERE customercode IN (",cust_code,")");
		PREPARE s1 FROM @del;
		EXECUTE s1;
		WHILE from_start <= cust_counter DO
			SET record_id 	= split(cust_code,',',from_start);
			SET record_info = split(cust_name,',',from_start);
			
			
			 INSERT INTO logmaster(formname,tablename,recordid,created,cdat,operation_type,record_detail)VALUES
			 	('Customer Master','customermaster',record_id,deletedby,CURRENT_DATE(),'Delete',record_info);
			
			SET from_start = from_start + 1;
			
		END WHILE;
				
		SELECT 'Success' AS result,cust_code AS deleted_id;
		
	ELSE 
		SELECT 'Not Found' AS result,cust_code AS deleted_id;		
	END IF;
	
SET FOREIGN_KEY_CHECKS = 1;
END */$$
DELIMITER ;

