DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_datamanagement_deletedata_allroute`(				
				IN deletedby VARCHAR(25)
				)
BEGIN
	DECLARE record_id       BIGINT(18);
	DECLARE record_info     VARCHAR(100);
	DECLARE from_start 		INT(4) DEFAULT 1;
	DECLARE route_counter 	BIGINT(18);
	DECLARE route_code 		LONGTEXT;
	DECLARE route_name 		LONGTEXT;
	
SET FOREIGN_KEY_CHECKS = 0;			
	
	SELECT IFNULL(COUNT(*),0),GROUP_CONCAT(routecode),GROUP_CONCAT(routename) 
		INTO route_counter,route_code,route_name
		FROM routemaster WHERE (routecode NOT IN(SELECT routecode FROM customermaster)
								AND routecode NOT IN(SELECT routecode FROM routesequence)
								AND routecode NOT IN(SELECT routecode FROM customerinvoice)
								AND routecode NOT IN(SELECT routecode FROM routesequencecustomerstatus))
							ORDER BY routecode ASC;
	
	
	IF route_counter > 0 THEN
		
		
		SET @del = CONCAT("DELETE FROM routemaster WHERE routecode IN (",route_code,")");
		PREPARE s1 FROM @del;
		EXECUTE s1;
		WHILE from_start <= route_counter DO
			SET record_id 	= split(route_code,',',from_start);
			SET record_info = split(route_name,',',from_start);
			
			
			 INSERT INTO logmaster(formname,tablename,recordid,created,cdat,operation_type,record_detail)VALUES
			 	('Route Master','routemaster',record_id,deletedby,CURRENT_DATE(),'Delete',record_info);
			
			SET from_start = from_start + 1;
			
		END WHILE;
				
		SELECT 'Success' AS result,route_code AS deleted_id;
		
	ELSE 
		SELECT 'Not Found' AS result,route_code AS deleted_id;		
	END IF;
SET FOREIGN_KEY_CHECKS = 1;		
END */$$
