/* Procedure structure for procedure `sp_delete_deletetransaction_tourid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_deletetransaction_tourid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_deletetransaction_tourid`(	
		IN var_rotuecode BIGINT(20),
		IN var_routekey BIGINT(28)
	)
BEGIN
	DECLARE counter INT DEFAULT 1;
	DECLARE num_rows INT DEFAULT 0;
	DECLARE no_more_rows BOOLEAN;
	DECLARE introutekey,intvisitkey,inttransactionkey,intinvoicenumber,intonacctreasoncode INT;
	DECLARE dtinvoicedate DATETIME;
	DECLARE dbltotalinvoiceamount,dblamountpaid,dblinvoicebalance DECIMAL(18,4);
	
	DECLARE crpayment CURSOR FOR 
		SELECT routekey,visitkey,transactionkey,invoicenumber,invoicedate,totalinvoiceamount,onacctreasoncode,amountpaid,invoicebalance 
		FROM ardetail 
		WHERE routekey = var_routekey ORDER BY transactionkey;	
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET no_more_rows = TRUE;
	
	SET FOREIGN_KEY_CHECKS = 0;		
		
	IF (var_routekey > 0) THEN
			
		
		DELETE FROM nonservicedcustomer WHERE routekey =  var_routekey;
		DELETE FROM nosalesheader WHERE routekey = var_routekey;
		
		
		DELETE FROM surveyauditdetail WHERE routekey = var_routekey;		
		
		
		DELETE FROM posequipmentchangedetail WHERE routekey = var_routekey;
		
		DELETE FROM batchexpirydetail WHERE routekey =  var_routekey;
		
		
		DELETE FROM inventorytransactiondetail WHERE routekey =  var_routekey;
		DELETE FROM inventorysummarydetail WHERE routekey =  var_routekey;
		DELETE FROM inventorytransactionheader WHERE routekey =  var_routekey;
				
		
		DELETE FROM customerinventorydetail WHERE routekey = var_routekey;
		
		
		DELETE FROM promotiondetail WHERE routekey =  var_routekey;
		DELETE FROM customerpromotionplandetail WHERE routekey =  var_routekey;
		
		
		DELETE FROM invoicerxddetail WHERE routekey =  var_routekey;
		DELETE FROM invoicesigcapturedata WHERE routekey =  var_routekey;
		DELETE FROM invoicedetail WHERE routekey =  var_routekey;
		
		DELETE FROM orderrxddetail WHERE routekey =  var_routekey;		
		DELETE FROM ordersigcapturedata WHERE routekey =  var_routekey;
		DELETE FROM salesorderdetail WHERE routekey =  var_routekey;
		DELETE FROM salesorderheader WHERE routekey =  var_routekey;		
			
		
		
		DELETE FROM customerinvoice WHERE invoicenumber IN (SELECT invoicenumber FROM invoiceheader WHERE routekey =  var_routekey);		
		
		
		UPDATE customerinvoice,(SELECT arh.routecode,arh.customercode,ardt.invoicenumber,ardt.invoicedate,ardt.totalinvoiceamount,ardt.onacctreasoncode,ardt.amountpaid FROM ardetail ardt,arheader arh  WHERE ardt.transactionkey = arh.transactionkey AND arh.routekey = ardt.routekey AND arh.routekey = var_routekey ) AS artable2
		SET customerinvoice.amountpaid = customerinvoice.amountpaid - IFNULL(artable2.amountpaid,0) ,customerinvoice.invoicebalance = customerinvoice.invoicebalance + IFNULL(artable2.amountpaid, 0) ,mdat = CURRENT_DATE() 			
		WHERE customerinvoice.invoicenumber = artable2.invoicenumber  AND customerinvoice.transactiondate = artable2.invoicedate  AND customerinvoice.customercode = artable2.customercode;
			
		
		UPDATE invoiceheader,(SELECT arh.routecode,arh.customercode,ardt.invoicenumber,ardt.invoicedate,ardt.totalinvoiceamount,ardt.onacctreasoncode,ardt.amountpaid FROM ardetail ardt,arheader arh  WHERE ardt.transactionkey = arh.transactionkey AND arh.routekey = ardt.routekey AND arh.routekey = var_routekey ) AS artable2
		SET invoiceheader.amountpaid = invoiceheader.amountpaid - IFNULL(artable2.amountpaid, 0), invoiceheader.invoicebalance = invoiceheader.invoicebalance + IFNULL(artable2.amountpaid, 0)			
		WHERE invoiceheader.invoicenumber =  artable2.invoicenumber  AND invoiceheader.transactiondate = artable2.invoicedate AND invoiceheader.customercode = artable2.customercode;
		
		OPEN crpayment;		
		SELECT FOUND_ROWS() INTO num_rows;
		main_loop: LOOP			
			IF no_more_rows THEN			
				CLOSE crpayment;
				LEAVE main_loop;
				IF counter > num_rows THEN
					CLOSE crpayment;
					LEAVE main_loop;
				END IF;
			END IF;
			
			FETCH crpayment INTO introutekey,intvisitkey,inttransactionkey,intinvoicenumber,dtinvoicedate,dbltotalinvoiceamount,intonacctreasoncode,dblamountpaid,dblinvoicebalance;			
			
			IF EXISTS (SELECT totalinvoiceamount,amountpaid,dnamountpaid,cnamountpaid,invoicebalance FROM customerinvoice 
				 WHERE invoicenumber = intinvoicenumber AND transactiondate = dtinvoicedate AND paymentstatus = 1 AND dnamountpaid = 0 AND cnamountpaid = 0) THEN
					
					IF(EXISTS(SELECT invoicenumber FROM ardetail WHERE invoicenumber = intinvoicenumber AND invoicedate = dtinvoicedate)) THEN						
						UPDATE customerinvoice SET amountpaid = amountpaid+dblamountpaid, mdat = CURRENT_DATE() 
						WHERE invoicenumber = intinvoicenumber AND transactiondate = dtinvoicedate;							
					END IF;
					
			END IF;
			
			SET counter = counter+1;
		END LOOP main_loop;	
    
		
		DELETE FROM cashcheckdetail WHERE routekey =  var_routekey;
    
		
		DELETE FROM ardetail WHERE routekey =  var_routekey;
		DELETE FROM arheader WHERE routekey =  var_routekey;
		
		
		DELETE FROM invoiceheader WHERE routekey =  var_routekey; 
		
		
		DELETE FROM customeroperationscontrol WHERE routekey =  var_routekey;		
		
		DELETE FROM routesequencecustomerstatus WHERE routekey = var_routekey;
		
		DELETE FROM enddaydetail WHERE routekey =  var_routekey;	
		
		
		DELETE FROM t_access_override_log WHERE routekey =  var_routekey;
		
		
		DELETE FROM startendday WHERE routekey =  var_routekey;		
		
		
		
		
		
		
		
		
		
		
	
		
		
		
		
	
		
		
	
		
		
			
	END IF;
	
	
	
	SET FOREIGN_KEY_CHECKS = 1;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_device` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_device` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_device`(
				IN ids TEXT,
				IN deletedby VARCHAR(25),
				IN loginid BIGINT(18)
				)
BEGIN
	
	
		SET @del = CONCAT("DELETE FROM tbl_device WHERE `primary_key` IN (",ids,")");
		PREPARE s1 FROM @del;
		EXECUTE s1;
		
		
		CALL sp_add_logmaster_information(@counter,'Device Table','tbl_device',ids,deletedby,'Delete');
		SELECT 'Success' AS result,@filter_id AS deleted_id;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_hhctransaction_invoice_advpayment` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_hhctransaction_invoice_advpayment` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_hhctransaction_invoice_advpayment`( 
				IN ids TEXT,
				IN deleteby VARCHAR(30)
				)
BEGIN
		
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(transactionkey) into @counter,@filter_id FROM arheader
						WHERE transactionkey IN (",ids,")");	
	PREPARE s1 FROM @chk;
	EXECUTE s1;
	
	IF @counter > 0 THEN 
		SET @del = CONCAT("UPDATE customermaster 
				SET balance = balance - (SELECT SUM(cashcheckdetail.amount) 
								FROM arheader,cashcheckdetail
								WHERE cashcheckdetail.routekey = arheader.routekey
									AND cashcheckdetail.visitkey = arheader.visitkey
									AND arheader.customercode = customermaster.customercode
									AND arheader.transactionkey IN(",@filter_id,"))
				WHERE EXISTS (SELECT cashcheckdetail.amount 
						FROM arheader,cashcheckdetail
						WHERE cashcheckdetail.routekey = arheader.routekey
							AND cashcheckdetail.visitkey = arheader.visitkey
							AND arheader.customercode = customermaster.customercode
							AND arheader.transactionkey IN(",@filter_id,"))");
		PREPARE s1 FROM @del;
		EXECUTE s1;
		
		SET @del = CONCAT("DELETE cashcheckdetail 
				   FROM cashcheckdetail 
				   INNER JOIN arheader 
				   ON cashcheckdetail.routekey = arheader.routekey
				      AND cashcheckdetail.visitkey = arheader.visitkey
				   WHERE arheader.transactionkey IN(",@filter_id,")");
		
		PREPARE s1 FROM @del;
		EXECUTE s1;
	
	
		SET @del = CONCAT("DELETE FROM arheader WHERE transactionkey IN (",@filter_id,")");
		PREPARE s1 FROM @del;
		EXECUTE s1;
		
		SET @del = CONCAT("DELETE FROM ardetail WHERE transactionkey IN (",@filter_id,")");
		PREPARE s1 FROM @del;
		EXECUTE s1;	
		
		
		CALL sp_add_logmaster_information(@counter,'Advance Payment','arheader',@filter_id,deletedby,'Delete');
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
	ELSE
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;
	END IF;	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_hhctransaction_invoice_arcollection` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_hhctransaction_invoice_arcollection` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_hhctransaction_invoice_arcollection`( 
				IN ids TEXT,
				IN deleteby VARCHAR(30)
				)
BEGIN
		
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(transactionkey) into @counter,@filter_id FROM arheader
						WHERE transactionkey IN (",ids,")");	
	PREPARE s1 FROM @chk;
	EXECUTE s1;
	
	IF @counter > 0 THEN	
		
		SET @del = CONCAT("UPDATE customermaster 
				SET balance = balance + (SELECT SUM(cashcheckdetail.amount) 
								FROM arheader,cashcheckdetail
								WHERE cashcheckdetail.routekey = arheader.routekey
									AND cashcheckdetail.visitkey = arheader.visitkey
									AND arheader.customercode = customermaster.customercode
									AND arheader.transactionkey IN(",@filter_id,"))
				WHERE EXISTS (SELECT cashcheckdetail.amount 
						FROM arheader,cashcheckdetail
						WHERE cashcheckdetail.routekey = arheader.routekey
							AND cashcheckdetail.visitkey = arheader.visitkey
							AND arheader.customercode = customermaster.customercode
							AND arheader.transactionkey IN(",@filter_id,"))");
		PREPARE s1 FROM @del;
		EXECUTE s1;
		
		SET @del = CONCAT("UPDATE customerinvoice,(SELECT amountpaid,invoicenumber FROM ardetail WHERE transactionkey IN(",@filter_id,")) AS a
				   SET customerinvoice.amountpaid = customerinvoice.amountpaid - a.amountpaid,
					customerinvoice.invoicebalance = customerinvoice.invoicebalance + a.amountpaid
				   WHERE customerinvoice.invoicenumber = a.invoicenumber");
		PREPARE s1 FROM @del;
		EXECUTE s1;
		
		SET @del = CONCAT("DELETE cashcheckdetail 
				   FROM cashcheckdetail 
				   INNER JOIN arheader 
				   ON cashcheckdetail.routekey = arheader.routekey
				      AND cashcheckdetail.visitkey = arheader.visitkey
				   WHERE arheader.transactionkey IN(",@filter_id,")");
		
		PREPARE s1 FROM @del;
		EXECUTE s1;
		
		SET @del = CONCAT("DELETE FROM arheader WHERE transactionkey IN (",@filter_id,")");
		PREPARE s1 FROM @del;
		EXECUTE s1;
		
		SET @del = CONCAT("DELETE FROM ardetail WHERE transactionkey IN (",@filter_id,")");
		PREPARE s1 FROM @del;
		EXECUTE s1;
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
	ELSE
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;
	END IF;
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_hhctransaction_invoice_invoice` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_hhctransaction_invoice_invoice` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_hhctransaction_invoice_invoice`( 
				IN ids TEXT,
				IN deleteby VARCHAR(30)
				)
BEGIN
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(ih.transactionkey) into @counter,@filter_id 
				FROM invoiceheader ih
				LEFT JOIN ardetail ad ON ad.invoicenumber = ih.invoicenumber
				WHERE ih.transactionkey IN(",ids,") AND ad.invoicenumber IS NULL ");
	PREPARE s1 FROM @chk;
	EXECUTE s1;
				
	SET @chk = CONCAT("SELECT GROUP_CONCAT(ih.transactionkey) INTO @nodeleteids FROM invoiceheader ih
				LEFT JOIN ardetail ad ON ad.invoicenumber = ih.invoicenumber
				WHERE ih.transactionkey IN(",ids,") AND ad.invoicenumber IS NOT NULL ");
	PREPARE s1 FROM @chk;
	EXECUTE s1;	
	
	IF @counter > 0 THEN
		SET @del = CONCAT("UPDATE inventorysummarydetail,(SELECT salesqty,returnqty,damagedqty,freesampleqty,expiryqty,returnfreeqty,fixedrentqty,itemcode,routekey FROM invoicedetail WHERE transactionkey IN(",@filter_id,")) AS inv
				SET inventorysummarydetail.saleqty = inventorysummarydetail.saleqty - inv.salesqty,
					inventorysummarydetail.returnqty = inventorysummarydetail.returnqty - inv.returnqty,
					inventorysummarydetail.damageqty = inventorysummarydetail.damageqty - inv.damagedqty,
					inventorysummarydetail.freesampleqty = inventorysummarydetail.freesampleqty - inv.freesampleqty,
					inventorysummarydetail.expiryqty = inventorysummarydetail.expiryqty - inv.expiryqty,
					inventorysummarydetail.returnfreeqty = inventorysummarydetail.returnfreeqty - inv.returnfreeqty,
					inventorysummarydetail.rentqty = inventorysummarydetail.rentqty - inv.fixedrentqty
				WHERE inventorysummarydetail.itemcode = inv.itemcode
					AND inventorysummarydetail.routekey = inv.routekey");
		PREPARE s1 FROM @del;
		EXECUTE s1;
		
		SET @del = CONCAT("UPDATE customermaster,(SELECT totalinvoiceamount,customercode FROM invoiceheader WHERE transactionkey IN(",@filter_id,")) AS invheader
				SET customermaster.balance = customermaster.balance + invheader.totalinvoiceamount
				WHERE customermaster.customercode = invheader.customercode");
		
		PREPARE s1 FROM @del;
		EXECUTE s1;
		
		SET @del = CONCAT("DELETE FROM promotiondetail WHERE transactionkey IN (",@filter_id,")");
		PREPARE s1 FROM @del;
		EXECUTE s1;
		
		SET @del = CONCAT("DELETE batchexpirydetail
				   FROM batchexpirydetail
				   INNER JOIN invoicedetail
					ON batchexpirydetail.batchdetailkey = invoicedetail.batchdetailkey
				   WHERE invoicedetail.transactionkey IN(",@filter_id,")");
		PREPARE s1 FROM @del;
		EXECUTE s1;
		
		SET @del = CONCAT("DELETE customerinvoice
				   FROM customerinvoice
				   INNER JOIN invoiceheader
					ON customerinvoice.invoicenumber = invoiceheader.invoicenumber
				   WHERE invoiceheader.transactionkey IN(",@filter_id,")");
		PREPARE s1 FROM @del;
		EXECUTE s1;
		
		SET @del = CONCAT("DELETE FROM sigcapturedata WHERE transactionkey IN (",@filter_id,")");
		PREPARE s1 FROM @del;
		EXECUTE s1;
		
		SET @del = CONCAT("DELETE FROM invoiceheader WHERE transactionkey IN (",@filter_id,")");
		PREPARE s1 FROM @del;
		EXECUTE s1;
		
		SET @del = CONCAT("DELETE FROM invoicedetail WHERE transactionkey IN (",@filter_id,")");
		PREPARE s1 FROM @del;
		EXECUTE s1;		
		
		SELECT 'Success' AS result,@filter_id AS deleted_id,@nodeleteids AS dontdelete;
	ELSE
		SELECT 'Not Found' AS result,@filter_id AS deleted_id,@nodeleteids AS dontdelete;
	END IF;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_hhctransaction_invoice_salesorder` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_hhctransaction_invoice_salesorder` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_hhctransaction_invoice_salesorder`( 
				IN ids TEXT,
				IN deleteby VARCHAR(30)
				)
BEGIN
	
	DECLARE route_key BIGINT(18);
	DECLARE visit_key BIGINT(18);
	DECLARE tran_key BIGINT(18);
	DECLARE from_start INT(4) DEFAULT 1;
	
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(transactionkey) into @counter,@filter_id FROM salesorderheader
						WHERE transactionkey IN (",ids,")");	
	PREPARE s1 FROM @chk;
	EXECUTE s1;
	
	IF @counter > 0 THEN	
	
		WHILE from_start <= @counter DO
			
			SET tran_key = split(@filter_id,',',from_start);
			
			SELECT routekey,visitkey INTO route_key,visit_key FROM salesorderheader
				WHERE transactionkey = tran_key;
				
			SELECT route_key,visit_key;	
				
			DELETE FROM sigcapturedata WHERE routekey = route_key AND visitkey = visit_key AND transactionkey = tran_key;
			
			SET from_start = from_start + 1;
			
		END WHILE;
		
		SET @del = CONCAT("DELETE FROM salesorderheader WHERE transactionkey IN (",@filter_id,")");
		PREPARE s1 FROM @del;
		EXECUTE s1;
		
		SET @del = CONCAT("DELETE FROM salesorderdetail WHERE transactionkey IN (",@filter_id,")");
		PREPARE s1 FROM @del;
		EXECUTE s1;
		
		SET @del = CONCAT("DELETE FROM promotiondetail WHERE transactionkey IN (",@filter_id,")");
		PREPARE s1 FROM @del;
		EXECUTE s1;
		
	
		SELECT 'Success' AS result,@filter_id AS deleted_id;
	ELSE
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;
	END IF;
	
END */$$
DELIMITER ;

