/* Procedure structure for procedure `sp_delete_inventory_routestartday_deleteroute` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_inventory_routestartday_deleteroute` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_inventory_routestartday_deleteroute`(
in in_routekey int
)
BEGIN
declare allow_delete varchar(25);
set allow_delete = "NO";
	if(select ifnull(count(*),0) from inventorytransactionheader where inventorytransactionheader.routekey = in_routekey) > 0 then 
	
		IF(SELECT IFNULL(COUNT(*),0) FROM invoiceheader_temp WHERE invoiceheader_temp.routekey = in_routekey) > 0 THEN 
		
			IF(SELECT IFNULL(COUNT(*),0) FROM salesorderheader_temp WHERE salesorderheader_temp.routekey = in_routekey) > 0 THEN 
		
				IF(SELECT IFNULL(COUNT(*),0) FROM arheader WHERE arheader.routekey = in_routekey) > 0 THEN 
					SET allow_delete = "NO";
				end if;
			END IF;
		END IF;
	
	else
	
		SET allow_delete = "YES";
	 
	end if;
	
	SELECT allow_delete AS allow_delete_op;
	
	if allow_delete = "YES" then
        
	 delete from startendday where startendday.routekey = in_routekey;
	
	
	end if;
	
    END */$$
DELIMITER ;

