/* Procedure structure for procedure `sp_delete_inventory_transaction_dailysalesmangrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_inventory_transaction_dailysalesmangrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_inventory_transaction_dailysalesmangrid`(in id int)
BEGIN
	SELECT itemcode,batchnumber,get_depotcode_routecode(routecode),expirydate,((cases*upc)+units)
		INTO @itemcode,@batchno,@depotcode,@expirydate,@quantity
		FROM startingloaddetail
		WHERE loaddetailcode = id;
		
	UPDATE depotstock
		SET quantity 	= quantity + @quantity
		WHERE 	itemcode = @itemcode AND batchno = @batchno
				AND depotcode = @depotcode AND expirydate  = @expirydate; 
				  
    
		delete from startingloaddetail where loaddetailcode = id;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_inventory_transaction_dailysalesmanload` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_inventory_transaction_dailysalesmanload` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_inventory_transaction_dailysalesmanload`( 
				IN ids TEXT,
				IN deletedby VARCHAR(25),
				IN trandate VARCHAR(30)
				)
BEGIN
	
	DECLARE var_trandate DATE;
	
	SELECT STR_TO_DATE(trandate,'%d-%m-%Y') INTO var_trandate;
		 
	SET @qry = CONCAT("SELECT GROUP_CONCAT(routecode),GROUP_CONCAT(loadperiodnumber) INTO @rtcd,@loadno FROM startingloaddetail  WHERE loaddetailcode IN (",ids,") AND DATE(ddate) = '",var_trandate,"'");
	PREPARE qry FROM @qry;
	EXECUTE qry;
	
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(loaddetailcode) into @counter,@filter_id FROM startingloaddetail 
		WHERE routecode IN (",@rtcd,") AND loadperiodnumber IN (",@loadno,") AND DATE(ddate) = '",var_trandate,"'");
	PREPARE s1 FROM @chk;
	EXECUTE s1;
	
	IF @counter > 0 THEN
		
		SET @up = CONCAT("UPDATE depotstock as ds,(select itemcode,batchnumber,get_depotcode_routecode(routecode),expirydate,((cases*upc)+units) as totquantity
						from startingloaddetail WHERE loaddetailcode IN (",@filter_id,")) AS tbl
						set ds.quantity 	= ds.quantity + totquantity
						
						where ds.itemcode = tbl.itemcode and ds.batchno = tbl.batchnumber 
							and ds.expirydate = tbl.expirydate");
	
		PREPARE s2 FROM @up;
		EXECUTE s2;
		
		
		SET @del = CONCAT("DELETE FROM startingloaddetail  WHERE loaddetailcode IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		
		CALL sp_add_logmaster_information(@counter,'Daily Salesman Load','startingloaddetail ',@filter_id,deletedby,'Delete');
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
		
	ELSE 
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;
	END IF;
		
END */$$
DELIMITER ;

