DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_inventory_transaction_deliveryheader`( 
				IN ids TEXT
				)
BEGIN
		SET @del = CONCAT("DELETE FROM deliveryheader WHERE deliveryno IN (",ids,")");
		PREPARE s1 FROM @del;
