/* Procedure structure for procedure `sp_delete_inventory_transaction_depotdamageexpiry` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_inventory_transaction_depotdamageexpiry` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_inventory_transaction_depotdamageexpiry`(
			IN ids TEXT,
			IN deletedby VARCHAR(25)
		)
BEGIN
	
	SET @qry = CONCAT("SELECT GROUP_CONCAT(headerid),GROUP_CONCAT(headerid) INTO @counter,@filter_id FROM depotdamageexpiryheader WHERE headerid IN (",ids,") ");
	PREPARE qry FROM @qry;
	EXECUTE qry;
	
	IF @counter > 0 THEN
		
		set @up = concat("UPDATE depotstock as ds,(select actualitemcode,batchno,expirydate 
							from depotdamageexpirydetail WHERE headerid IN (",@filter_id,")) AS tbl
							set ds.quantity 	= ds.quantity + (ds.damagedqty + ds.expiryqty),
								ds.damagedqty 	= 0, ds.expiryqty 	= 0
							where ds.itemcode = tbl.actualitemcode and ds.batchno = tbl.batchno 
								and ds.expirydate = tbl.expirydate");
		
		PREPARE s2 FROM @up;
		EXECUTE s2;
		
		
		SET @del = CONCAT("DELETE FROM depotdamageexpiryheader WHERE headerid IN (",@filter_id,")");
		PREPARE s3 FROM @del;
 		EXECUTE s3;
		
		
		SET @del = CONCAT("DELETE FROM depotdamageexpirydetail WHERE headerid IN (",@filter_id,")");
		PREPARE s4 FROM @del;
 		EXECUTE s4;
				
		
		CALL sp_add_logmaster_information(@counter,'Depot Damage/Expiry','depotdamageexpiryheader ',@filter_id,deletedby,'Delete');
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
		
	ELSE 
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;
	END IF;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_inventory_transaction_depotdamageexpirygrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_inventory_transaction_depotdamageexpirygrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_inventory_transaction_depotdamageexpirygrid`(
			IN var_detailid BIGINT,
			IN var_headerid BIGINT			
		)
BEGIN
	
		SELECT actualitemcode,batchno,depotcode,expirydate,reasoncode
			INTO   @actualitemcode,@batchno,@depotcode,@expirydate,@reasoncode
		FROM depotdamageexpirydetail AS ded,depotdamageexpiryheader AS deh	
		WHERE detailid	= var_detailid AND ded.headerid = deh.headerid;	
		
	update depotstock
		set quantity 	= quantity + (damagedqty + expiryqty),
			damagedqty 	= 0,
			expiryqty 	= 0
		WHERE 	itemcode = @actualitemcode AND batchno = @batchno
				  AND depotcode = @depotcode AND expirydate  = @expirydate; 
	
	DELETE FROM depotdamageexpirydetail	WHERE detailid	= var_detailid AND headerid = var_headerid;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_inventory_transaction_depotinventory` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_inventory_transaction_depotinventory` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_inventory_transaction_depotinventory`(
			IN ids TEXT,
			IN deletedby VARCHAR(25)
		)
BEGIN
	
	SET @qry = CONCAT("SELECT GROUP_CONCAT(depotinvtranskey),GROUP_CONCAT(depotinvtranskey) INTO @counter,@filter_id FROM depotinventoryheader WHERE depotinvtranskey IN (",ids,") AND isposted <> 1 ");
	PREPARE qry FROM @qry;
	EXECUTE qry;
	
	IF @counter > 0 THEN
		
		SET @del = CONCAT("DELETE FROM depotinventoryheader WHERE depotinvtranskey IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		
		SET @del = CONCAT("DELETE FROM depotinventorydetails WHERE depotinvtranskey IN (",@filter_id,")");
		PREPARE s4 FROM @del;
		EXECUTE s4;
		
		
		SET @del = CONCAT("DELETE ds FROM depotstock ds
								INNER JOIN depotinventorydetails did ON did.itemcode = ds.itemcode 
									AND did.expirydate = ds.expirydate AND did.batchno = ds.batchno
									AND did.depotinvtranskey IN (",@filter_id,")");		
		PREPARE s5 FROM @del;
		EXECUTE s5;
		
		
		CALL sp_add_logmaster_information(@counter,'Depot Inventory','depotinventoryheader ',@filter_id,deletedby,'Delete');
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
		
	ELSE 
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;
	END IF;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_inventory_transaction_depotinventorygrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_inventory_transaction_depotinventorygrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_inventory_transaction_depotinventorygrid`(
			IN var_primary_id 	BIGINT,
			IN var_trankey 		BIGINT			
		)
BEGIN
	
	delete from depotinventorydetails 	WHERE primary_key = var_primary_id;
	
	DELETE FROM depotstock WHERE depotinvtranskey	= var_trankey 
		AND itemcode = (SELECT itemcode FROM depotinventorydetails WHERE primary_key = var_primary_id);
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_inventory_transaction_grn` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_inventory_transaction_grn` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_inventory_transaction_grn`(
			IN ids TEXT,
			IN deletedby VARCHAR(25)
		)
BEGIN
	
	SET @qry = CONCAT("SELECT GROUP_CONCAT(grheaderid),GROUP_CONCAT(grheaderid) INTO @counter,@filter_id FROM tblgrheader WHERE grheaderid IN (",ids,")");
	PREPARE qry FROM @qry;
	EXECUTE qry;
	
	IF @counter > 0 THEN
		
		SET @del = CONCAT("DELETE FROM tblgrheader WHERE grheaderid IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		
		SET @del = CONCAT("DELETE FROM tblgrdetail WHERE grheaderid IN (",@filter_id,")");
		PREPARE s4 FROM @del;
		EXECUTE s4;
		
		
		SET @del = CONCAT("DELETE tbldepotstock FROM tbldepotstock,tblgrdetail
						WHERE tbldepotstock.batchno = tblgrdetail.batchno 
							AND tbldepotstock.expirydate = tblgrdetail.expirydate 
							AND tbldepotstock.itemcode = tblgrdetail.itemcode 
							AND tblgrdetail.grheaderid IN (",@filter_id,")");
		PREPARE s5 FROM @del;
		EXECUTE s5;
		
		
		CALL sp_add_logmaster_information(@counter,'GRN','tblgrheader ',@filter_id,deletedby,'Delete');
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
		
	ELSE 
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;
	END IF;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_inventory_transaction_grngrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_inventory_transaction_grngrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_inventory_transaction_grngrid`(
			IN var_itemcode BIGINT,
			IN var_trankey BIGINT
		)
BEGIN
	
	DECLARE var_batchno VARCHAR(50);
	DECLARE var_expirydate DATE;
	
	SELECT batchno,expirydate INTO var_batchno,var_expirydate FROM tblgrdetail
		WHERE grheaderid = var_trankey AND itemcode = var_itemcode;
		
	delete from tblgrdetail 	where grheaderid	= var_trankey AND itemcode = var_itemcode;
	
	DELETE FROM tbldepotstock WHERE grheaderid = var_trankey AND itemcode = var_itemcode
	and batchno = var_batchno and expirydate  = var_expirydate;
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_inventory_transaction_routeitemgroup` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_inventory_transaction_routeitemgroup` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_inventory_transaction_routeitemgroup`( 
				IN ids TEXT,
				IN deletedby VARCHAR(25)
				)
BEGIN
	
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(routeitemgrpcode) into @counter,@filter_id FROM routeitemgrp 
						WHERE routeitemgrpcode NOT IN ( SELECT routeitemgrpcode FROM routemaster WHERE routeitemgrpcode IN (",ids,"))
						AND routeitemgrpcode IN (",ids,") AND LOWER(description) <> LOWER('default')");	
	PREPARE s1 FROM @chk;
	EXECUTE s1;
	
	IF @counter > 0 THEN	
		SET @del = CONCAT("DELETE FROM routeitemgrp WHERE routeitemgrpcode IN (",@filter_id,")");
		PREPARE s1 FROM @del;
		EXECUTE s1;
		
		
		SET @del_child = CONCAT("DELETE FROM routeitemmapping WHERE routeitemgrpcode IN (",@filter_id,")");
		PREPARE s2 FROM @del_child;
		EXECUTE s2;
		
		
		CALL sp_add_logmaster_information(@counter,'Route Item Group','routeitemgrp',@filter_id,deletedby,'delete');
		SELECT 'Success' AS result,@filter_id AS deleted_id;
	ELSE 
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;
	END IF;
		
END */$$
DELIMITER ;

