/* Procedure structure for procedure `sp_delete_promotion_customer_assignmentgrp` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_promotion_customer_assignmentgrp` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_promotion_customer_assignmentgrp`( 
				IN ids TEXT,
				IN deletedby VARCHAR(25)
				)
BEGIN
	
	
	
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(groupnumber) into @counter,@filter_id FROM productgroupheader 
					WHERE (
							groupnumber NOT IN ( select assignmentgroup from promoplandetail WHERE assignmentgroup IN (",ids,"))
						  )	
						  AND groupnumber IN (",ids,") AND grouptype = 2");
	PREPARE s1 FROM @chk;
	EXECUTE s1;
	
	IF @counter > 0 THEN
	
		
		SET @ins = CONCAT("INSERT into productgroupheader_history (groupnumber,groupdescription,arbgroupdescription,
								grouptype,deleted,ddat)
							(
								select groupnumber,groupdescription,arbgroupdescription,grouptype,
								'",deletedby,"',CURRENT_DATE()
								from productgroupheader where groupnumber in (",@filter_id,")
							)");
		PREPARE s2 FROM @ins;
		EXECUTE s2;	
	
		SET @del = CONCAT("DELETE FROM productgroupheader WHERE groupnumber IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		SET @del2 = CONCAT("DELETE FROM productgroupdetail WHERE groupnumber IN (",@filter_id,")");
		PREPARE s4 FROM @del2;
		EXECUTE s4;
		
		
		CALL sp_add_logmaster_information(@counter,'Assignment Group','productgroupheader',@filter_id,deletedby,'delete');
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
		
	ELSE 
		
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;
		
	END IF;
		
END */$$
DELIMITER ;

