								purchasemanagerlandlinenumber = purchasemngr_tel_no,
								purchasemanagermobilenumber = purchasemngr_mob_no,
								warehousemanagername = warehousemngr_name,
								warehousemanagermobilenumber = warehousemngr_mob_no,
								warehousemanagerlandlinenumber = warehousemngr_tel_no,
								warehousemanageremail = warehousemngr_email
							WHERE customercode = cust_code;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_account_customer_setting1` */

