	    IN description VARCHAR(50),
	    IN arbdescription VARCHAR(100),	    
	    IN reasoncd BIGINT,
	    in modifiedby	varchar(25),
	    IN altcode VARCHAR(50)
	    
	)
BEGIN
	
	UPDATE expiryreturnreasons SET  description = description,
