/* Procedure structure for procedure `sp_edit_inventory_pos_addcustomerposlimit` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_inventory_pos_addcustomerposlimit` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_inventory_pos_addcustomerposlimit`(
					in var_customercode bigint,
					IN var_poslimit INT(11),
					IN modified_by VARCHAR(30),
					in primarykey BIGINT
					)
BEGIN
    
    SELECT count(*) Into @cnt FROM customerposinventory where customercode = var_customercode;
    
	set @remain = (var_poslimit-@cnt);
    
    
	update customerposlimit set customercode 	= var_customercode,
								poslimit 		= var_poslimit,
								posbalance 		= @remain,
								modified 		= modified_by,
								mdat 			= CURRENT_DATE()
					where primary_key = primarykey;
	
	CALL sp_add_logmaster_information('1','Customer POS Limit','customerposlimit',primarykey,modified_by,'Edit');	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_inventory_pos_addcustomerposlimitgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_inventory_pos_addcustomerposlimitgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_inventory_pos_addcustomerposlimitgrid`(
			IN var_quantity   		DECIMAL(18,0),
			IN var_serialnumber     VARCHAR(20),
			in primarykey 			BIGINT,
			IN var_modified			VARCHAR(50)
		)
BEGIN
	
	select var_quantity,var_serialnumber,primarykey;
	select inventorytype into @inv_type from posmaster 
		where itemcode = (select itemcode from customerposinventory 
								where table_pk = primarykey
						 );
	
	if @inv_type = 0 then 
		update customerposinventory SET quantity = var_quantity,modified = var_modified,mdat = CURRENT_DATE()
				where	table_pk = primarykey;
	else
		UPDATE customerposinventory SET serialnumber = var_serialnumber,modified = var_modified,mdat = CURRENT_DATE()
				WHERE table_pk = primarykey;
	end if;	
		
END */$$
DELIMITER ;

