/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_organization_index_addsubarea` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_organization_index_addsubarea`(
		IN id BIGINT,
	    IN sub_area_name VARCHAR(50),
	    IN arb_sub_area_name VARCHAR(50),
	    in area_code bigint,
	    IN supervisor_code BIGINT,
	    in alt_code VARCHAR(30),	    
	    IN active_status INT,
	    IN modified_by VARCHAR(50)   
	)
BEGIN
	
	UPDATE subareamaster SET 	subareaname = sub_area_name,
								arbsubareaname = arb_sub_area_name,
								areacode = area_code,
								supervisorcode = supervisor_code,
								alternatesubareacode = alt_code,
								activestatus = active_status,
								modified = modified_by,
								mdat = CURRENT_DATE()
							WHERE	
								subareacode = id;	
		
		CALL sp_add_logmaster_information('1','Sub Area Master','subareamaster',id,modified_by,'Edit');
END */$$
DELIMITER ;

