DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_organization_route_addroute`(
	IN var_routename VARCHAR(30),
	IN var_arbroutename VARCHAR(30),
	IN var_subareacode DECIMAL(18,0),
	IN var_salesmancode DECIMAL(10,0),
	IN var_modified VARCHAR(20),
	IN var_mdat DATETIME,
	IN var_password1 INT(4),
	IN var_password2 INT(4),
	IN var_password3 INT(4),
	IN var_password4 INT(4),
	IN var_password5 INT(4),
	IN var_passwordarray01 INT(4),
	IN var_passwordarray02 INT(4),
	IN var_passwordarray03 INT(4),
	IN var_passwordarray04 INT(4),
	IN var_passwordarray05 INT(4),
	IN var_passwordarray06 INT(4),
	IN var_passwordarray07 INT(4),
	IN var_passwordarray08 INT(4),
	IN var_passwordarray09 INT(4),
	IN var_passwordarray10 INT(4),
	IN var_passwordarray11 INT(4),
	IN var_passwordarray12 INT(4),
	IN var_passwordarray13 INT(4),
	IN var_passwordarray14 INT(4),
	IN var_passwordarray15 INT(4),
	IN var_passwordarray16 INT(4),
	IN var_depotrouteflag INT(4),
	IN var_presalesorder SMALLINT(6),
	IN var_alternateroutecode VARCHAR(30),
	IN var_routecatcode BIGINT,
	IN var_vehiclenumber BIGINT,
	IN var_regioncode BIGINT,
	IN var_activestatus INT(4),
	IN var_cmpycode BIGINT,
	IN var_allowroutestartdayflag INT(4),
	IN var_routecode BIGINT,
	IN device_id VARCHAR(30),
	IN var_itemmustkey BIGINT,
	IN var_enablefss int(4)
    )
BEGIN
	DECLARE rowcnt INT DEFAULT 0;
	
	
		
		
	
	
		UPDATE routemaster SET 
			alternateroutecode = var_alternateroutecode,
			routename = var_routename,
			arbroutename = var_arbroutename,
			subareacode = var_subareacode,
			salesmancode = var_salesmancode,
			modified = var_modified,
			password1 = var_password1,
			password2 = var_password2,
			password3 = var_password3,
			password4 = var_password4,
			password5 = var_password5,
			passwordarray01 = var_passwordarray01,
			passwordarray02 = var_passwordarray02,
			passwordarray03 = var_passwordarray03,
			passwordarray04 = var_passwordarray04,
			passwordarray05 = var_passwordarray05,
			passwordarray06 = var_passwordarray06,
			passwordarray07 = var_passwordarray07,
			passwordarray08 = var_passwordarray08,
			passwordarray09 = var_passwordarray09,
			passwordarray10 = var_passwordarray10,
			passwordarray11 = var_passwordarray11,
			passwordarray12 = var_passwordarray12,
			passwordarray13 = var_passwordarray13,
			passwordarray14 = var_passwordarray14,
			passwordarray15 = var_passwordarray15,
			passwordarray16 = var_passwordarray16,
			depotrouteflag = var_depotrouteflag,
			presalesorder = var_presalesorder,
			vehiclenumber = var_vehiclenumber,
			regionmstcode = var_regioncode,
			activestatus = var_activestatus,
			routecatcode = var_routecatcode,
			cmpycode 	= var_cmpycode,
			allowroutestartdayflag = var_allowroutestartdayflag,
			device_assigned_id = device_id,
			itemmustkey = var_itemmustkey,
			mdat = CURRENT_DATE(),
			enablefss = var_enablefss
			WHERE routecode = var_routecode;
		
			
		
		
		
		CALL sp_add_logmaster_information('1','Route Master','routemaster',var_routecode,var_modified,'Edit');
    END */$$
DELIMITER ;

