/* Procedure structure for procedure `sp_edit_promotions_advancepricing_addpricingkey` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_promotions_advancepricing_addpricingkey` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_promotions_advancepricing_addpricingkey`(
			IN var_description VARCHAR(50),
			IN var_arbdescription VARCHAR(50),
			IN var_active SMALLINT(6),
			IN modified_by VARCHAR(30),
			IN var_pricingplankey BIGINT
		)
BEGIN
	
	UPDATE customerpricingplanheader1 SET
				description 	= var_description,
				arbdescription 	= var_arbdescription,
				activeindicator	= var_active
			WHERE pricingplankey = var_pricingplankey;
				
	SELECT var_pricingplankey AS last_id;
	
	
	CALL sp_add_logmaster_information('1','Pricing Key','customerpricingplanheader1',var_pricingplankey,modified_by,'Edit');
	
END */$$
DELIMITER ;

