DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_promotions_advance_addpromotionkey`(		
	    IN txt_description VARCHAR(255),
	    IN ddl_type BIGINT,
	    IN txt_arbdescription VARCHAR(255),
	    IN ddl_activeindicator INT,
	    in modified_by varchar(30),
	    IN txt_promotionkey BIGINT
	)
BEGIN
	
	UPDATE promokeyheader  SET 
								description 	= txt_description,
								`type` 			= ddl_type,
								arbdescription 	= txt_arbdescription,
								activeindicator = ddl_activeindicator,
								modified = modified_by,
								mdat 			= CURRENT_DATE()
	WHERE promotionkey = txt_promotionkey;
	
	
	CALL sp_add_logmaster_information('1','Promotion Key','promokeyheader',txt_promotionkey,modified_by,'Edit');
	
	
END */$$
