	)
BEGIN
	DECLARE range_high BIGINT;
	DECLARE range_low BIGINT;
	DECLARE counter INT;
	declare final_range_val bigint;
	
	SELECT MAX(rangehigh),MAX(rangelow),COUNT(*) INTO range_high,range_low,counter 
		FROM promotionassignmentadvanced 
		WHERE plannumber = p_plannumber and range_id != p_range_id;
	
	if range_high > range_low then
		set final_range_val = range_high;
	else
		set final_range_val = range_low;
	end if;
	
	
	IF p_rangelow < final_range_val OR counter = 0 THEN	
		UPDATE promotionassignmentadvanced SET   rangelow = p_rangelow,
					rangehigh 			= p_rangehigh,
					repeatingrange 		= p_repeatingrange,
					promotionamount		= p_promotionamount,
					mdat 				= CURRENT_DATE() 
		WHERE range_id = p_range_id;
	ELSE
		SELECT '0' AS result,final_range_val; 
	end if;
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_promotions_customer_addauthorizegroup` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_promotions_customer_addauthorizegroup` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_promotions_customer_addauthorizegroup`(
                    IN var_groupnumber     	BIGINT,
                    IN var_groupdescription     VARCHAR(50),
                    IN var_arbgroupdescription	VARCHAR(50),
                    in var_modified varchar(30)
    )
BEGIN
		DECLARE grptype VARCHAR(250);
		
		UPDATE productgroupheader SET 
			groupdescription = var_groupdescription,
			arbgroupdescription = var_arbgroupdescription,
			mdat 		= CURRENT_DATE()
			WHERE groupnumber = var_groupnumber;
		
		select grouptype into @var_grouptype  from productgroupheader WHERE groupnumber = var_groupnumber;
		 
		IF @var_grouptype = 1 THEN 
			SET grptype = 'Qualification Group';
		ELSEIF @var_grouptype = 2 THEN 
			SET grptype = 'Assignment Group';
		ELSE
			SET grptype = 'Customer Authorize Group';
		END IF;
			
		
		CALL sp_add_logmaster_information('1',grptype,'productgroupheader',var_groupnumber,var_modified,'Edit');
			
    END */$$
DELIMITER ;

