/* Procedure structure for procedure `sp_edit_transaction_invoiceadd_detail1` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_transaction_invoiceadd_detail1` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_transaction_invoiceadd_detail1`(
IN var_invoicenumber DECIMAL(28,0),
IN var_documentnumber DECIMAL(28,0),
IN var_routecode DECIMAL(18,0),
IN var_customercode DECIMAL(18,0),
IN var_comment varchar(200),
IN in_output BLOB,
IN in_invoice_transaction_key int
)
BEGIN
DECLARE var_salesmancode INT;
DECLARE in_route_key_code INT;
	
	SELECT salesmancode INTO var_salesmancode FROM routemaster  WHERE routemaster.routecode = var_routecode;
	SELECT routekey INTO in_route_key_code FROM startendday 
	WHERE startendday.routecode=var_routecode
		AND startendday.routeclosed = 0
	ORDER BY routekey DESC  LIMIT 1	;
	update invoiceheader_temp set 
	routekey  =in_route_key_code ,
	routecode = var_routecode,
	salesmancode = var_salesmancode,
	customercode = var_customercode,
	comments = var_comment
	where transactionkey = in_invoice_transaction_key;
	
	select transactionkey as invoice_transaction_key ,
	       routekey,
	       visitkey 
	 FROM invoiceheader_temp 
	where transactionkey = in_invoice_transaction_key;
	
	CALL sp_add_transaction_invoiceadd_signaturedata(in_invoice_transaction_key,in_route_key_code,in_invoice_transaction_key,var_customercode,0,in_output);
    
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_EG_dailyrouteactivity` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_EG_dailyrouteactivity` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_EG_dailyrouteactivity`(
    IN divcode VARCHAR(25),
    IN fromdate DATE,
    IN todate DATE
)
BEGIN
    SELECT 
        DATE(s.routestartdate) AS routestartdate,
        IFNULL(DATE_FORMAT(cv.logstartdate, '%d %b %Y'), '') AS trandate,
        cv.routekey,
        IFNULL(cc.visitkey, 0) AS visitkey,
        cm.alternatecode AS customercode,
        cm.customername,
        cm.arbcustomername,
        cm.customeraddress1,
        cm.customeraddress2,
        cm.customeraddress3,
        rm.routecode,
        rm.routename,
        IFNULL(rm.arbroutename, '') AS arbroutename,
        rm.divisioncode,
        sm.salesmancode,
        sm.salesmanname1,
        IFNULL(sm.arbsalesmanname1, '') AS arbsalesmanname1,
	-- Customer visit log duration
        cv.logstarttime AS custvisitstarttime,
        cv.logendtime AS custvisitendtime,
       -- TIMEDIFF(CONCAT(cv.logenddate, ' ', cv.logendtime), CONCAT(cv.logstartdate, ' ', cv.logstarttime)) AS custvisitdur,
       TIME_FORMAT(
	    TIMEDIFF(
		CONCAT(cv.logenddate, ' ', cv.logendtime),
		CONCAT(cv.logstartdate, ' ', cv.logstarttime)
	    ),
	    '%H:%i:%s'
	) AS custvisitdur,
        
      -- CONCAT(cc.visitstartdate, ' ', cc.visitstarttime) AS activitystart,       
     --  CONCAT(cc.visitenddate, ' ', cc.visitendtime) AS activityend,
        -- IFNULL(DATE_FORMAT(cc.visitstartdate, '%d %b %Y'), '') AS visitstartdate,
        IFNULL(cc.visitstarttime, '00:00:00') AS activitystarttime,
      --   IFNULL(DATE_FORMAT(cc.visitenddate, '%d %b %Y'), '') AS visitenddate,
        IFNULL(cc.visitendtime, '00:00:00') AS activityendtime,
        -- Activity duration
        IFNULL(TIME_FORMAT(TIMEDIFF(CONCAT(DATE_FORMAT(cc.visitenddate, '%Y-%m-%d'),' ',TIME_FORMAT(cc.visitendtime,'%H:%i:%s')), CONCAT(DATE_FORMAT(cc.visitstartdate, '%Y-%m-%d'),' ',TIME_FORMAT(cc.visitstarttime,'%H:%i:%s'))), '%H:%i:%s'), '00:00:00') AS activitydur,
   --     IFNULL(TIMESTAMPDIFF(HOUR, CONCAT(cc.visitstartdate,' ',cc.visitstarttime), CONCAT(cc.visitenddate,' ',cc.visitendtime)), 0) AS timeinhour,
     --   IFNULL(TIMESTAMPDIFF(MINUTE, CONCAT(cc.visitstartdate,' ',cc.visitstarttime), CONCAT(cc.visitenddate,' ',cc.visitendtime)) % 60, 0) AS timeinmin,
        -- Flags
        CASE WHEN cc.visitkey IS NOT NULL THEN 'VISITED' ELSE '' END AS visited,
        -- Transaction type
        CASE WHEN cc.reasoncode <> 0 THEN
        nr.description
        ELSE 
                CASE
            WHEN i.documentnumber IS NOT NULL THEN 'SALE'
            WHEN a.documentnumber IS NOT NULL THEN 'RECEIPT'
            WHEN s2.documentnumber IS NOT NULL THEN 'ORDER'
            ELSE 'NON SERVICED'
        END 
        END
AS trantype,
        -- Transaction references
        COALESCE(i.documentnumber, a.documentnumber, s2.documentnumber, 0) AS documentno,
        CASE 
            WHEN i.documentnumber IS NOT NULL THEN i.totalinvoiceamount
            WHEN s2.documentnumber IS NOT NULL THEN s2.totalinvoiceamount
            ELSE 0
        END AS tranamount,
        CASE 
            WHEN i.documentnumber IS NOT NULL THEN i.amountpaid
            ELSE 0
        END AS salePaid,
        CASE 
            WHEN a.documentnumber IS NOT NULL THEN a.amountpaid
            ELSE 0
        END AS receiptPaid
        
        
        FROM customervisitlog cv  RIGHT JOIN customeroperationscontrol cc 
        ON cv.routekey = cc.routekey AND cv.logkey = cc.log_id
         INNER JOIN  startendday s
        ON s.routekey = cv.routekey 
       LEFT JOIN   `nonservreasons` nr  ON  cc.reasoncode = nr.code
    LEFT JOIN invoiceheader i 
        ON i.routekey = cc.routekey 
       AND i.visitkey = cc.visitkey 
    LEFT JOIN salesorderheader s2 
        ON s2.routekey = cc.routekey 
       AND s2.visitkey = cc.visitkey 
    LEFT JOIN arheader a 
        ON a.routekey = cc.routekey 
       AND a.visitkey = cc.visitkey
    INNER JOIN routemaster rm 
        ON rm.routecode = cv.routecode
    INNER JOIN customermaster cm 
        ON cm.customercode = cv.customercode
    INNER JOIN salesman sm 
        ON sm.salesmancode = cv.salesmancode
    WHERE s.routestartdate BETWEEN fromdate AND todate
      AND (divcode = '' OR rm.divisioncode = divcode)
    ORDER BY s.routekey, cc.visitkey;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_eg_strikeratereport` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_eg_strikeratereport` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_eg_strikeratereport`(
    IN in_divisioncode VARCHAR(50),
    IN in_startdate DATE,
    IN in_enddate DATE
)
BEGIN
    SELECT 
        sm.salesmanname1,
        sm.arbsalesmanname1,
        sm.alternatesalesmancode AS salesmancode,
        rm.routename,
        rm.arbroutename,
        rm.alternateroutecode AS routecode,
        -- Planned calls
        COUNT(DISTINCT CASE WHEN rs.schelduledflag = 1 THEN rs.customercode END) AS plannedcalls,
        -- Actual calls
        COUNT(DISTINCT CASE WHEN rs.servicedflag = 1 THEN rs.customercode END) AS actualcalls,
        -- Unscheduled calls
        COUNT(DISTINCT CASE WHEN rs.servicedflag = 1 AND rs.schelduledflag = 0 THEN rs.customercode END) AS unschedulecall,
        -- Cash sales
        COUNT(DISTINCT CASE WHEN ih.immediatepaid <> 0 AND ih.voidflag = 0 THEN ih.invoicenumber  END) AS cashsale,
        -- Credit sales
        COUNT(DISTINCT CASE WHEN ih.immediatepaid = 0 AND ih.voidflag = 0 THEN  ih.invoicenumber END) AS creditsale,
        -- Productive calls
        COUNT(DISTINCT CASE WHEN coc.totaltransactions > 0 THEN coc.customercode END) AS productivecalls,
        -- Total receipts
        COUNT(DISTINCT ah.transactionkey) AS totalreceipt,
        -- Strike rate %
        ROUND(
            COUNT(DISTINCT CASE WHEN rs.servicedflag = 1 THEN rs.customercode END) /
            NULLIF(COUNT(DISTINCT CASE WHEN rs.schelduledflag = 1 THEN rs.customercode END), 0) * 100, 2
        ) AS strikerate,
        -- Productive rate %
        ROUND(
            COUNT(DISTINCT CASE WHEN coc.totaltransactions > 0 THEN coc.customercode END) /
            NULLIF(COUNT(DISTINCT CASE WHEN rs.schelduledflag = 1 THEN rs.customercode END), 0) * 100, 2
        ) AS productiverate,
        -- Customer Face Time
         COALESCE(MAX(cvl_agg.total_minutes), 0) AS CustomerFaceMinutes,
        -- format as HH:MM (zero padded)
        CONCAT(
            LPAD(FLOOR(COALESCE(MAX(cvl_agg.total_minutes),0) / 60), 2, '0'),
            ':',
            LPAD(MOD(COALESCE(MAX(cvl_agg.total_minutes),0), 60), 2, '0')
        ) AS CustomerFaceTime_HHMM
        
        
    FROM startendday sed
    INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
    INNER JOIN routemaster rm ON sed.routecode = rm.routecode
    LEFT JOIN routesequencecustomerstatus rs 
           ON rs.routecode = sed.routecode 
          AND rs.routekey  = sed.routekey
    LEFT JOIN invoiceheader ih on  ih.routekey  = sed.routekey 
    LEFT JOIN arheader ah on ah.routekey  = sed.routekey
    LEFT JOIN customeroperationscontrol coc on coc.routekey  = sed.routekey
    LEFT JOIN customervisitlog cvl    on cvl.routekey  = sed.routekey
          
          LEFT JOIN (
    SELECT 
        routekey,
        routecode,
        COALESCE(SUM(
            TIMESTAMPDIFF(
                MINUTE,
                CONCAT(logstartdate, ' ', logstarttime),
                CONCAT(logenddate,   ' ', CASE WHEN logendtime = '00:00:00' THEN logstarttime ELSE logendtime END)
            )
        ), 0) AS total_minutes
    FROM customervisitlog
    WHERE logstartdate BETWEEN in_startdate AND in_enddate
      AND logstartdate IS NOT NULL
      AND logenddate IS NOT NULL
    GROUP BY routekey, routecode
) cvl_agg
  ON cvl_agg.routekey = sed.routekey
    WHERE sed.routecode in (
    -- 1818
     select routecode from routemaster where divisioncode = in_divisioncode
    )
      AND sed.routestartdate BETWEEN in_startdate AND in_enddate
    GROUP BY sed.salesmancode, sed.routecode
    ORDER BY sed.routecode ASC;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_export_loadrequest` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_export_loadrequest` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_export_loadrequest`(
in var_requestdate date    
    )
BEGIN
	 
       SELECT rm.division as ORG_CODE,rm.warehouse as TO_SUBINV_CODE,im.alternatecode as ITEMCODE,im.upccasecode as UOM_CODE,id.quantity as QUANTITY,ih.documentnumber as HHTReference,DATE_FORMAT(ih.requestdate,'%Y-%m-%d') as DateRequired  FROM inventorytransactionheader ih 
INNER JOIN inventorytransactiondetail id ON ih.detailkey=id.detailkey AND id.transactiontypecode=8
INNER JOIN routemaster rm ON rm.routecode=ih.routecode
INNER JOIN itemmaster im ON im.actualitemcode=id.itemcode
 WHERE ih.transactiontype=4  and ih.requestdate=var_requestdate;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_geocordinates_check` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_geocordinates_check` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_geocordinates_check`()
BEGIN
  TRUNCATE TABLE locationsfaoracle;
  INSERT INTO locationsfaoracle
    (customercode, alternatecode,divisioncode, sfalat, sfalong, oraclelat, oraclelong, distancevariance,created)
  SELECT
    base.customercode,
    base.alternatecode,
    base.divisoncode,
    CASE
      WHEN base.sfa_lat_raw BETWEEN -90 AND 90
      THEN base.sfa_lat_raw ELSE NULL END AS sfalat,
    CASE
      WHEN base.sfa_lng_raw  > -180 AND base.sfa_lng_raw <= 180
      THEN base.sfa_lng_raw  ELSE NULL END AS sfalong,
    
    CASE
      WHEN tmp.orc_lat_raw BETWEEN -90 AND 90
      THEN tmp.orc_lat_raw ELSE NULL END AS oraclelat,
    CASE
      WHEN tmp.orc_lng_raw  > -180 AND tmp.orc_lng_raw <= 180
      THEN tmp.orc_lng_raw  ELSE NULL END AS oraclelong,
    CASE
      WHEN base.sfa_lat_raw BETWEEN -90 AND 90
       AND base.sfa_lng_raw  > -180 AND base.sfa_lng_raw <= 180
       AND tmp.orc_lat_raw   BETWEEN -90 AND 90
       AND tmp.orc_lng_raw   > -180 AND tmp.orc_lng_raw  <= 180
      THEN ST_Distance_Sphere(
             POINT(tmp.orc_lng_raw,  tmp.orc_lat_raw),   -- POINT(lng,lat)
             POINT(base.sfa_lng_raw, base.sfa_lat_raw)
           )
      ELSE NULL
    END AS distancevariance, now()
  FROM
 
    (
      SELECT
        cm.customercode,
        cm.alternatecode,
        cm.DivisionCode AS divisoncode,
        CAST(NULLIF(TRIM(cm.fixedlatitude),  '') AS DECIMAL(10,6)) AS sfa_lat_raw,
        CAST(NULLIF(TRIM(cm.fixedlongitude), '') AS DECIMAL(11,6)) AS sfa_lng_raw
      FROM customermaster cm
    ) base
    LEFT JOIN
    (
      SELECT
        tc.customercode,
        CAST(NULLIF(TRIM(SUBSTRING_INDEX(tc.geocordinates, ',',  1)), '') AS DECIMAL(10,6)) AS orc_lat_raw,
        CAST(NULLIF(TRIM(SUBSTRING_INDEX(tc.geocordinates, ',', -1)), '') AS DECIMAL(11,6)) AS orc_lng_raw
      FROM TEMP_CUSTOMERMASTER tc
      -- WHERE tc.geocordinates REGEXP '^-?[0-9]+(\\.[0-9]+)?,\\s*-?[0-9]+(\\.[0-9]+)?$'
    ) tmp
      ON base.alternatecode = tmp.customercode;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_getcomboboxdata` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_getcomboboxdata` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_getcomboboxdata`(
		in table_name varchar(500),
		in table_fields text,
		in table_where text
	)
BEGIN
		set @qry = concat('SELECT ',table_fields,' FROM ',table_name,' WHERE 1 = 1 ',table_where);
		PREPARE s1 FROM @qry;
		
		EXECUTE s1;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_getcombobox_account_customerseq_arrangecustomer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_getcombobox_account_customerseq_arrangecustomer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_getcombobox_account_customerseq_arrangecustomer`(in route_code int(4),IN week_no INT(4))
BEGIN
		
		CALL sp_combo_routemaster();
		
		
		
		SELECT cust.customername,cust.arbcustomername,cust.alternatecode, rs.* FROM routesequence AS rs
			RIGHT JOIN customermaster AS cust ON cust.customercode = rs.customercode
			WHERE rp32weeknumber = week_no AND rs.routecode = route_code
			ORDER BY rs.customercode;
		
		
		SELECT weekstartday FROM setup;	
		
		
  END */$$
DELIMITER ;

