/* Procedure structure for procedure `sp_get_account_customer_addcustomer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_customer_addcustomer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_customer_addcustomer`(IN id BIGINT)
BEGIN
	
	CALL sp_combo_pricingkey();
		
	
	CALL sp_combo_routemaster();
	
	
	CALL sp_combo_promotionkey();
	
	
	SELECT categoryid AS id, CONCAT(categoryid,' --- ',categoryname) AS val FROM categorymaster;
		
	SELECT * FROM customermaster WHERE customercode = id;
		
	
	SELECT surveykey AS id, CONCAT(surveykey,' --- ',surveydescription) AS val FROM customersurveykey;
	
		
	
	SELECT discountkey AS id, CONCAT(discountkey,' --- ',description) AS val FROM discountkeyheader;
	
	
	SELECT distributionkey AS id, CONCAT(distributionkey,' --- ',description) AS val FROM distributionkeyheader;
	
	
	SELECT groupnumber AS id, CONCAT(groupnumber,' --- ',groupdescription) AS val FROM productgroupheader WHERE grouptype = 3;
	
	
	CALL sp_combo_headoffice();
	
	
	SELECT groupcode AS id, CONCAT(groupcode,' --- ',groupname) AS val FROM groupmaster;
	
	
	SELECT customercode AS id, CONCAT(customercode,' --- ',templatename) AS val FROM customermaster WHERE templateindicator = 1;
	
	SELECT `status` FROM controlpanel WHERE flagid IN (3,57,74,79,81,82);
	
	SELECT taxcode AS id, CONCAT(taxcode,' --- ',taxdescription) AS val FROM taxmaster;
	
	CALL sp_combo_itemmust();
	
	CALL sp_combo_channel();
	
	SELECT `visualcode` AS id,`visualdescription` AS val FROM `visualheader`;
	SELECT distributioncode AS id, CONCAT(distributioncode,' --- ',distributiondescription) AS val FROM distributioncheckheader;
	SELECT pricesurveykey AS id, CONCAT(pricesurveykey,' --- ',pricesurveydescription) AS val FROM pricesurveykeyheader;
	
	SELECT advertisecode AS id, CONCAT(advertisecode,' --- ',advertisedescription) AS val FROM advertiseheader;
	
	
	SELECT loyaltykeyid AS id,CONCAT(loyaltykeyid,' --- ',description) AS val FROM loyaltykeyheader;
	
	CALL sp_combo_customermappingkey();
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_account_customer_addcustomercluster` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_customer_addcustomercluster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_customer_addcustomercluster`(
    IN var_mapping_id INT,
    IN var_posted_division VARCHAR(255)
)
BEGIN
    DECLARE selected_division VARCHAR(255) DEFAULT '';

    IF var_mapping_id > 0 THEN
        SELECT COALESCE(MAX(divisioncode), '')
        INTO selected_division
        FROM customerclustermapping
        WHERE id = var_mapping_id;
    ELSE
        SET selected_division = COALESCE(var_posted_division, '');
    END IF;

    /* Result set 1: Division dropdown. */
    SELECT DISTINCT TRIM(NAME) AS `name`
    FROM company
    WHERE activestatus = 1 AND NAME IS NOT NULL
      AND TRIM(NAME) <> ''
    ORDER BY NAME ASC;

    /* Result set 2: selected Division. */
    SELECT selected_division AS divisioncode;

    /* Result set 3: every Channel with saved/default CFT. */
    SELECT
        channel.channelname,
        COALESCE(mapping.cft, 0) AS cft
    FROM channelmaster AS CHANNEL
    LEFT JOIN customerclustermapping AS mapping
        ON mapping.`channel` = channel.channelname
       AND mapping.divisioncode = selected_division
    WHERE activestatus = 1 AND channel.channelname IS NOT NULL
      AND TRIM(channel.channelname) <> ''
    ORDER BY channel.channelname ASC;
END */$$
DELIMITER ;

