/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_customer_addcustomertmpl`(IN id BIGINT)
BEGIN
	
	CALL sp_combo_pricingkey();
		
	
	SELECT routecode AS id, CONCAT(routecode,' -- ',routename) AS val FROM routemaster;
	
	
	CALL sp_combo_promotionkey();
	
	
	SELECT categoryid AS id, CONCAT(categoryid,' -- ',categoryname) AS val FROM categorymaster;
		
	SELECT * FROM customermaster WHERE customercode = id and templateindicator = 1;	
		
	
	SELECT surveykey AS id, CONCAT(surveykey,' -- ',surveydescription) AS val FROM customersurveykey;
	
	
