/* Procedure structure for procedure `sp_get_account_customer_customer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_customer_customer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_customer_customer`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT 		)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'customercode';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	SET order_type= 'ASC';
	
	IF table_fields = '' THEN
		SET table_fields = 'customer.*';
	END IF;
    
	SET @cnt_sql = CONCAT("SELECT COUNT(*) AS counter 
		FROM  usermaster as um 
			INNER JOIN (SELECT DISTINCT cmpycode,username FROM useraccesscodes) as uac ON uac.username= um.username
			INNER JOIN routemaster as route ON route.cmpycode = uac.cmpycode
			INNER JOIN customermaster as customer on customer.routecode = route.routecode
	WHERE 1=1 AND templateindicator = 0   ",table_where);
	
	PREPARE s1 FROM @cnt_sql;
	EXECUTE s1;
    
	SET @dyn_sql = CONCAT("SELECT ", table_fields ,"
		FROM  usermaster as um 
			INNER JOIN (SELECT DISTINCT cmpycode,username FROM useraccesscodes) as uac ON uac.username= um.username
			INNER JOIN routemaster as route ON route.cmpycode = uac.cmpycode
			INNER JOIN customermaster as customer on customer.routecode = route.routecode
		WHERE 1=1 AND templateindicator = 0 ",table_where,  " ORDER BY ",order_by," ", 
