/* Procedure structure for procedure `sp_get_account_customer_customercluster` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_customer_customercluster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_customer_customercluster`(
    IN rwcnt INT,
    IN srchvalue VARCHAR(500),
    IN order_by VARCHAR(500),
    IN order_type VARCHAR(10),
    IN lmt_strt INT,
    IN lmt_end INT,
    IN table_fields TEXT,
    IN table_where TEXT
)
BEGIN
    IF lmt_strt IS NULL OR lmt_strt < 0 THEN
        SET lmt_strt = 0;
    END IF;

    IF lmt_end IS NULL OR lmt_end <= 0 THEN
        SET lmt_end = 10;
    END IF;

    IF order_by IS NULL OR TRIM(order_by) = '' THEN
        SET order_by = 'map.divisioncode';
    END IF;

    IF order_type IS NULL
       OR UPPER(order_type) NOT IN ('ASC', 'DESC') THEN
        SET order_type = 'ASC';
    END IF;

    IF table_fields IS NULL OR TRIM(table_fields) = '' THEN
        SET table_fields = 'map.*';
    END IF;

    IF table_where IS NULL THEN
        SET table_where = '';
    END IF;

    SET @customer_cluster_base =
        '(SELECT
            MIN(ccm.id) AS mapping_id,
            ccm.divisioncode,
            COUNT(DISTINCT ccm.`channel`) AS channel_count,
            GROUP_CONCAT(
                CONCAT(ccm.`channel`, '' : '', COALESCE(ccm.cft, 0))
                ORDER BY ccm.`channel`
                SEPARATOR '', ''
            ) AS channel_cft
          FROM customerclustermapping AS ccm
          GROUP BY ccm.divisioncode) AS map';

    SET @customer_cluster_count = CONCAT(
        'SELECT COUNT(*) AS counter FROM ',
        @customer_cluster_base,
        ' WHERE 1 = 1 ',
        table_where
    );

    PREPARE cluster_count_stmt FROM @customer_cluster_count;
    EXECUTE cluster_count_stmt;
    DEALLOCATE PREPARE cluster_count_stmt;

    SET @customer_cluster_data = CONCAT(
        'SELECT ', table_fields,
        ' FROM ', @customer_cluster_base,
        ' WHERE 1 = 1 ', table_where,
        ' ORDER BY ', order_by, ' ', order_type,
        ' LIMIT ', lmt_strt, ', ', lmt_end
    );

    PREPARE cluster_data_stmt FROM @customer_cluster_data;
    EXECUTE cluster_data_stmt;
    DEALLOCATE PREPARE cluster_data_stmt;
END */$$
DELIMITER ;

