/* Procedure structure for procedure `sp_get_account_customer_itemmust_enforcemsl` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_customer_itemmust_enforcemsl` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_customer_itemmust_enforcemsl`(
	IN srchvalue VARCHAR(500), 	
	IN order_by VARCHAR(500),	
	IN order_type VARCHAR(10),	
	IN lmt_strt INT,			
	IN lmt_end INT, 			
	IN table_fields TEXT, 			
	IN table_where TEXT,
	IN txt_search TEXT
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'customercode';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	SET @dyn_sql1 = CONCAT("SELECT COUNT(customercode) AS counter FROM customermaster cm
LEFT JOIN itemmustheader imh ON imh.itemmustcode = cm.itemmustkey WHERE activecustomer = 1 ",table_where," ",txt_search);
	PREPARE s1 FROM @dyn_sql1;
	EXECUTE s1;
	
	SET @dyn_sql2 = CONCAT("SELECT ",table_fields," FROM customermaster cm
LEFT JOIN itemmustheader imh ON imh.itemmustcode = cm.itemmustkey WHERE activecustomer = 1 ", table_where, " ",txt_search,"  ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end);
	PREPARE s2 FROM @dyn_sql2;
	EXECUTE s2;
SELECT @dyn_sql2;	
END */$$
DELIMITER ;

