/* Procedure structure for procedure `sp_get_account_index_journeyplan` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_index_journeyplan` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_index_journeyplan`()
BEGIN	
	
	SELECT `status` INTO @st FROM controlpanel WHERE flagname = 'Use Alternate Code';
	
	call sp_combo_depotmaster();
	
	IF @st = 1 THEN 
		SELECT customercode AS id, CONCAT(alternatecode,' -- ',customername) AS val FROM customermaster WHERE `type` in(2,3,4) and activecustomer = 1 AND templateindicator = 0; 
	ELSE
		SELECT customercode AS id, CONCAT(customercode,' -- ',customername) AS val FROM customermaster WHERE `type` IN(2,3,4) and activecustomer = 1 AND templateindicator = 0; 
	END IF;
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_account_index_journeyplandetailgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_index_journeyplandetailgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_index_journeyplandetailgrid`(
	IN rwcnt INT,
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	SET order_by = 'rm.routecode';
	SET order_type= 'ASC';
	
	IF table_fields = '' THEN
		SET table_fields = 'dm.*';
	END IF;
	
	
	SET @dyn_cnt = CONCAT("SELECT count(rm.routecode) AS counter FROM routemaster rm,subareamaster sam,areamaster am,depotmaster dm,salesman sm
							WHERE sam.subareacode = rm.subareacode AND rm.salesmancode = sm.salesmancode AND am.areacode = sam.areacode AND dm.depotcode = am.depotcode
							",table_where, " GROUP BY rm.routecode ");
	
	PREPARE s1 FROM @dyn_cnt;
	EXECUTE s1;
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM routemaster rm,subareamaster sam,areamaster am,depotmaster dm,salesman sm
							WHERE sam.subareacode = rm.subareacode AND rm.salesmancode = sm.salesmancode AND am.areacode = sam.areacode AND dm.depotcode = am.depotcode
							",table_where,  " GROUP BY rm.routecode ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	PREPARE s2 FROM @dyn_sql;
	EXECUTE s2;
	select @dyn_sql,@dyn_cnt;
	 
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_account_index_journeyplandetailgridbycustomer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_index_journeyplandetailgridbycustomer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_index_journeyplandetailgridbycustomer`(
	IN rwcnt INT,
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT,
	in depot_code bigint(18),
	IN customer_code BIGINT(18),
	in decimalplaces int
)
BEGIN
	declare route_code text;
	
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	SET order_by = 'routecode';
	SET order_type= 'ASC';
	
	IF table_fields = '' THEN
		SET table_fields = 'dm.*';
	END IF;
	
	SELECT GROUP_CONCAT(rm.routecode) INTO route_code
			FROM routemaster rm,subareamaster sam,areamaster am,depotmaster dm
			WHERE sam.subareacode = rm.subareacode
				AND am.areacode = sam.areacode
				AND dm.depotcode = am.depotcode
				AND dm.depotcode = depot_code;
		
	
	SET @q1 = CONCAT("SELECT COUNT(*),GROUP_CONCAT(routecode) INTO @counter,@routecode FROM journeyplancreditlimit WHERE customercode = ",customer_code," AND routecode IN (",route_code,")");
 	PREPARE s1 FROM @q1;
 	EXECUTE s1;
	
	set @qry 	= '';
	SET @whr 	= '';
	SET @count2 = 0;
	SET @cnt 	= '';
	
	if @counter > 0 then	 
		set @qry = CONCAT("UNION ( SELECT jp.routecode,rm.routename,sm.salesmanname1,FORMAT(jp.creditlimit,",decimalplaces,") AS creditlimit_xyz,jp.routecode AS edit_del_primary_id
			FROM journeyplancreditlimit jp,routemaster rm,salesman sm WHERE jp.routecode = rm.routecode 
			AND rm.salesmancode = sm.salesmancode AND jp.customercode = ",customer_code," AND jp.routecode IN(",@routecode,"))");
		SET @cnt = concat("UNION ( SELECT COUNT(jp.routecode) AS counter
			FROM journeyplancreditlimit jp,routemaster rm,salesman sm WHERE jp.routecode = rm.routecode 
			AND rm.salesmancode = sm.salesmancode AND jp.customercode = ",customer_code," AND jp.routecode IN(",@routecode,"))");
		set @whr = CONCAT(" AND rm.routecode NOT IN(",@routecode,")");
		
		
	END IF;
	
	
	SET @dyn_cnt = CONCAT("SELECT COUNT(rm.routecode) AS counter
										   FROM routemaster rm,
											 subareamaster sam,
											 areamaster am,
											 depotmaster dm,
											 salesman sm
										   WHERE sam.subareacode = rm.subareacode
											   AND rm.salesmancode = sm.salesmancode
											   AND am.areacode = sam.areacode
											   AND dm.depotcode = am.depotcode
											   AND dm.depotcode = ",depot_code,"
											   ",@whr,"
							",@cnt,"
										   ");
	
 	PREPARE s1 FROM @dyn_cnt;
 	EXECUTE s1;	
	
	
	
	SET @dyn_sql = CONCAT("SELECT ",table_fields,"
										   FROM routemaster rm,
											 subareamaster sam,
											 areamaster am,
											 depotmaster dm,
											 salesman sm
										   WHERE sam.subareacode = rm.subareacode
											   AND rm.salesmancode = sm.salesmancode
											   AND am.areacode = sam.areacode
											   AND dm.depotcode = am.depotcode
											   AND dm.depotcode = ",depot_code,"
											   ",@whr,"
										   GROUP BY rm.routecode
							",@qry,"			   
								ORDER BY routecode ASC LIMIT ",lmt_strt,", ",lmt_end,"");
  	PREPARE s2 FROM @dyn_sql;
  	EXECUTE s2;
 	SELECT @q1,@counter,@dyn_sql,@dyn_cnt;
	 
END */$$
DELIMITER ;

