/* Procedure structure for procedure `sp_get_account_notes_addcreditnotecustomer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_notes_addcreditnotecustomer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_notes_addcreditnotecustomer`(
	IN id 			BIGINT(20)
    )
BEGIN
		DECLARE paytype INT(4);
		
		CALL sp_combo_routemaster_actran();
		CALL sp_combo_bankmaster();
				
		IF id > 0 THEN 
			SELECT *  FROM dcarheader WHERE transactionkey = id;
		ELSE
			CALL sp_get_table_last_id('dcarheader');
		END IF;
		
		IF id > 0 THEN 
			SELECT typecode INTO paytype FROM dcarcashcheckdetail WHERE transactionkey = id;
			
			IF paytype > 0 THEN
				SELECT typecode,checknumber,DATE_FORMAT(checkdate,'%d-%m-%Y') AS checkdate,SUM(amount) AS amount,bm.bankname 
					FROM dcarcashcheckdetail AS bcd,bankmaster AS bm 
				WHERE bm.bankcode = bcd.bankcode AND transactionkey = id
					GROUP BY transactionkey;
			ELSE
				SELECT typecode,SUM(amount) AS amount FROM dcarcashcheckdetail
					WHERE transactionkey = id
					GROUP BY transactionkey;
			END IF;
		END IF;
		
    END */$$
DELIMITER ;

