		SET @cnt_sql = CONCAT("SELECT COUNT(*) AS counter FROM dcarheader AS dcah
			  LEFT JOIN routemaster AS rm ON rm.routecode = dcah.routecode
			  LEFT JOIN customermaster AS cm ON cm.customercode = dcah.customercode
			WHERE 1=1 AND dcah.customercode !='0' AND dcah.transactiontype = 4 ",table_where);
		PREPARE s1 FROM @cnt_sql;
