/* Procedure structure for procedure `sp_get_account_salesman_addsalesman` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_salesman_addsalesman` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_salesman_addsalesman`(IN id INT)
BEGIN
	IF id > 0 THEN
		
		SELECT * FROM salesman WHERE salesmancode = id;
	ELSE
		CALL sp_get_table_last_id('salesman');
	END IF;
		
	SELECT cmpycode AS id, CONCAT(cmpycode,' --- ',`name`) AS val FROM company;
		
	
	SELECT messagekey AS id, CONCAT(messagekey,' --- ',`messagedescription`) AS val FROM salesmanmessages;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_account_salesman_addsalesmanmsg` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_salesman_addsalesmanmsg` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_salesman_addsalesmanmsg`(IN id BIGINT)
BEGIN
	
	IF id > 0  THEN
		SELECT * FROM salesmanmessages WHERE  `messagekey` = id;
	ELSE
		CALL sp_get_table_last_id('salesmanmessages');
	END IF;
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_account_salesman_salesman` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_salesman_salesman` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_salesman_salesman`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT 		)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'salesmancode';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	SET order_type= 'ASC';
	
	IF table_fields = '' THEN
		SET table_fields = 'salesman.*';
	END IF;
    
	SET @cnt_sql = CONCAT("SELECT COUNT(*) AS counter 
		FROM  usermaster as um 
			INNER JOIN (SELECT DISTINCT cmpycode,username FROM useraccesscodes) as uac ON uac.username= um.username
			INNER JOIN routemaster as route ON route.cmpycode = uac.cmpycode
			LEFT JOIN salesman AS salesman  ON salesman.salesmancode = route.salesmancode	WHERE 1=1  ",table_where);
	
	PREPARE s1 FROM @cnt_sql;
	EXECUTE s1;
	SET @dyn_sql = CONCAT("SELECT ", table_fields ,"
		FROM  usermaster as um 
			INNER JOIN (SELECT DISTINCT cmpycode,username FROM useraccesscodes) as uac ON uac.username= um.username
			INNER JOIN routemaster as route ON route.cmpycode = uac.cmpycode
			LEFT JOIN salesman AS salesman  ON salesman.salesmancode = route.salesmancode	WHERE 1=1  ",table_where,  " ORDER BY ",order_by," ", 
	order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	
	PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;
    
END */$$
DELIMITER ;

