/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_salesman_salesmanmsg`(
				IN rwcnt INT,
				IN srchvalue VARCHAR(500),
				IN order_by VARCHAR(500),
				IN order_type VARCHAR(10),
				IN lmt_strt INT,
