/* Procedure structure for procedure `sp_get_account_settlement_addcashreceipt` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_settlement_addcashreceipt` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_settlement_addcashreceipt`(
				in primarykey bigint
			)
BEGIN
    
		CALL sp_combo_routemaster();
		CALL sp_combo_bankmaster();
		if primarykey > 0 then
			select routecode,salesmancode,date_format(`date`,'%d-%m-%Y') as transactiondate,tobankcode,slipno 
				from cashierreceiptheader WHERE documentnumber = primarykey;
		end if;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_account_settlement_addcashreceiptgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_settlement_addcashreceiptgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_settlement_addcashreceiptgrid`(
	
	IN rwcnt INT,
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT, 			
	IN table_where TEXT ,
	IN extra_where TEXT,
	IN decimalplaces INT,
	IN where_cond TEXT,
	in is_view int
    )
BEGIN
		
		IF lmt_strt = '' THEN
			SET lmt_strt=0;
		END IF;
		IF lmt_end = '' THEN
			SET lmt_end=10;
		END IF;
		
		SET order_by = 'edit_del_primary_id';
		SET order_type= 'ASC';
		
		IF table_fields = '' THEN
			SET table_fields = 'ci.*';
		END IF;
		
		SET @cnt_rec = CONCAT("SELECT COUNT(*) INTO @cnt FROM cashierreceiptheader WHERE ",where_cond,"");
		PREPARE rec1 FROM @cnt_rec;
		EXECUTE rec1;
		
		
		IF @cnt > 0 and is_view = 0 THEN 
			SELECT 'Exist' AS counter;
		ELSE
		
			SET @cnt_sql = CONCAT("SELECT COUNT(ah.invoicenumber) AS counter FROM arheader ah
									LEFT JOIN ardetail as ad on ad.transactionkey = ah.transactionkey
									LEFT JOIN cashcheckdetail AS ccd ON ccd.routekey = ah.routekey AND ccd.visitkey = ah.visitkey
									WHERE 1 =1 AND ccd.typecode in(0,1) AND ccd.transactiontype = 2 ",table_where," 
							UNION (
									SELECT COUNT(ih.invoicenumber) AS counter FROM invoiceheader ih
											LEFT JOIN cashcheckdetail AS ccd ON ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey									
									  WHERE 1 =1 AND ih.paymenttype IN(0,4) AND ccd.typecode IN(0,1) AND ccd.transactiontype = 1 ",extra_where,"
									)");
		 	PREPARE s1 FROM @cnt_sql;
		 	EXECUTE s1;
			
			SET @dyn_sql = CONCAT("SELECT ", table_fields ,"  FROM arheader ah
									LEFT JOIN ardetail as ad on ad.transactionkey = ah.transactionkey
									LEFT JOIN cashcheckdetail AS ccd ON ccd.routekey = ah.routekey AND ccd.visitkey = ah.visitkey
									LEFT JOIN bankmaster AS bm ON bm.bankcode = ccd.bankcode
								  WHERE 1 =1 AND ccd.typecode in(0,1) AND ccd.transactiontype = 2 ",table_where,"
								UNION (
									SELECT    ih.invoicenumber AS invoicenumber,DATE_FORMAT(ih.transactiondate,'%d-%m-%Y') AS transactiondate,IF(ih.paymenttype,'Cheque','Cash') as paymenttype,
											  ccd.checknumber AS checknumber,DATE_FORMAT(ccd.checkdate,'%d-%m-%Y') AS checkdate,bm.bankname AS bankname,
											  FORMAT(ih.totalinvoiceamount,",decimalplaces,") AS totalinvoiceamount,FORMAT(ih.amountpaid,",decimalplaces,") AS amountpaid,
											  FORMAT(ih.invoicebalance,",decimalplaces,") AS invoicebalance,2 AS sett_tran_type,
											  ih.transactionkey  AS edit_del_primary_id 
										FROM invoiceheader ih
											LEFT JOIN cashcheckdetail AS ccd ON ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey
											LEFT JOIN bankmaster AS bm ON bm.bankcode = ccd.bankcode
										WHERE 1 =1 AND ih.paymenttype IN(0,4) AND ccd.typecode IN(0,1) AND ccd.transactiontype = 1 ",extra_where,"
									) ORDER BY ",order_by," ",order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
		 	PREPARE s2 FROM @dyn_sql;
		 	EXECUTE s2;
	
			
			
			SET @sum1 = CONCAT(" SELECT	IFNULL(SUM(ah.amountpaid),0) AS sum_amtpaid,
									1 AS tpcd,1 AS tbltype 
									FROM arheader AS ah 
									JOIN cashcheckdetail AS ccd ON ccd.routekey = ah.routekey AND ccd.visitkey = ah.visitkey
									WHERE 1 = 1  AND ccd.typecode in(0,1) AND ccd.transactiontype = 2 ",table_where,"
								UNION
								 SELECT	IFNULL(SUM(ih.amountpaid),0) AS sum_amtpaid,
									1 AS tpcd,2 AS tbltype 
									FROM invoiceheader AS ih
									JOIN cashcheckdetail AS ccd ON ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey
									WHERE 1 = 1  AND ih.paymenttype IN(0) AND ccd.typecode = 0 AND ccd.transactiontype = 1 ",extra_where,"
								UNION 
								 SELECT	IFNULL(SUM(ih.amountpaid),0) AS sum_amtpaid,
									2 AS tpcd,2 AS tbltype 
									FROM invoiceheader AS ih
									JOIN cashcheckdetail AS ccd ON ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey
									WHERE 1 = 1  AND ih.paymenttype IN(4) AND ccd.typecode = 1 AND ccd.transactiontype = 1 ",extra_where);
			
			PREPARE x1 FROM @sum1;
			EXECUTE x1;		
			select @sum1;
		END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_account_settlement_addcashreceiptpopupgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_settlement_addcashreceiptpopupgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_settlement_addcashreceiptpopupgrid`(
				IN rwcnt INT,
				IN order_by VARCHAR(500),
				IN order_type VARCHAR(10),
				IN lmt_strt INT,
				IN lmt_end INT,
				IN table_fields TEXT,
				IN table_where TEXT
    )
BEGIN
		
		IF lmt_strt = '' THEN
			SET lmt_strt=0;
		END IF;
		
		IF lmt_end = '' THEN
			SET lmt_end=10;
		END IF;
		
		IF order_by = 'amountpaid' THEN
			SET order_by = 'ccd.amount';		
		ELSEIF order_by = 'totalinvoiceamount' THEN
			SET order_by = 'ah.totalinvoiceamount';	
		ELSEIF order_by = 'invoicebalance' THEN
			SET order_by = 'ah.invoicebalance';
		ELSE
			SET order_by = 'edit_del_primary_id';
		END IF;
		
		IF order_type = '' THEN
			SET order_type= 'ASC';
		END IF;
		
		IF table_fields = '' THEN
			SET table_fields = 'ah.*';
		END IF;		
					
		SET @dyn_cnt = CONCAT("SELECT COUNT(cnt) AS counter FROM (
									SELECT 1 cnt FROM arheader ah
									LEFT JOIN ardetail AS ad ON ad.transactionkey = ah.transactionkey
									LEFT JOIN cashcheckdetail AS ccd ON ccd.routekey = ah.routekey AND ccd.visitkey = ah.visitkey
									LEFT JOIN invoiceheader AS ih ON ih.invoicenumber = ad.invoicenumber
									WHERE 1 =1 AND ccd.transactiontype = 2 ",table_where,") 
								AS tbl1");
	 
	 	PREPARE s1 FROM @dyn_cnt;
	 	EXECUTE s1;
		
		SET @dyn_sql = CONCAT("SELECT ", table_fields ,"  FROM arheader ah
									LEFT JOIN ardetail as ad on ad.transactionkey = ah.transactionkey
									LEFT JOIN cashcheckdetail AS ccd ON ccd.routekey = ah.routekey AND ccd.visitkey = ah.visitkey
									LEFT JOIN invoiceheader AS ih ON ih.invoicenumber = ad.invoicenumber
									WHERE 1 =1 AND ccd.transactiontype = 2 ",table_where,"
									ORDER BY ",order_by," ",order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	  	PREPARE s2 FROM @dyn_sql;
	 	EXECUTE s2;
		
	 	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_account_settlement_addpdcdetailgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_settlement_addpdcdetailgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_settlement_addpdcdetailgrid`(
	IN rwcnt INT,
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT,
	IN table_where TEXT ,
	IN extra_where VARCHAR(10)
)
BEGIN
	IF lmt_strt = '' THEN
			SET lmt_strt=0;
		END IF;
		IF lmt_end = '' THEN
			SET lmt_end=10;
		END IF;
		IF order_by = '' THEN
			SET order_by = 'edit_del_primary_id';
		END IF;
		IF order_type = '' THEN
			SET order_type= 'DESC';
		END IF;
		IF table_fields = '' THEN
			SET table_fields = 'ci.*';
		END IF;
	
		IF extra_where = 'ah' THEN
		
			SET @dyn_cnt = CONCAT("SELECT COUNT(cnt) AS counter FROM (
									SELECT 1 cnt FROM arheader ah
									LEFT JOIN ardetail AS ad ON ad.transactionkey = ah.transactionkey
									LEFT JOIN cashcheckdetail AS ccd ON ccd.routekey = ah.routekey AND ccd.visitkey = ah.visitkey
									LEFT JOIN customerinvoice AS ci ON ci.invoicenumber = ad.invoicenumber
									WHERE 1 =1 AND ccd.typecode IN(1) AND ccd.transactiontype = 2 ",table_where," 
									) AS tbl1");
				
	
			SET @dyn_sql = CONCAT("SELECT ", table_fields ,"  FROM arheader ah
		                            LEFT JOIN ardetail as ad on ad.transactionkey = ah.transactionkey
									LEFT JOIN cashcheckdetail AS ccd ON ccd.routekey = ah.routekey AND ccd.visitkey = ah.visitkey
									LEFT JOIN customerinvoice AS ci ON ci.invoicenumber = ad.invoicenumber
									WHERE 1 =1 AND ccd.typecode in(1) AND ccd.transactiontype = 2 ",table_where," 
									ORDER BY ",order_by," ",order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
				
									
		ELSEIF extra_where = 'ih' THEN
			
			SET @dyn_cnt = CONCAT("SELECT COUNT(cnt) AS counter FROM (
									SELECT 1 cnt FROM  invoiceheader ih
									LEFT JOIN cashcheckdetail AS ccd ON ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey
									LEFT JOIN customerinvoice AS ci ON ci.invoicenumber = ih.invoicenumber
									WHERE 1 =1 AND ih.paymenttype IN(4) AND ccd.typecode IN(1) AND ccd.transactiontype = 1 ",table_where," 
									) AS tbl1");
				
			SET @dyn_sql = CONCAT("SELECT ", table_fields ,"  FROM invoiceheader ih
									LEFT JOIN cashcheckdetail AS ccd ON ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey
									LEFT JOIN customerinvoice AS ci ON ci.invoicenumber = ih.invoicenumber
									WHERE 1 =1 AND ih.paymenttype IN(4) AND ccd.typecode IN(1) AND ccd.transactiontype = 1 ",table_where," 
									ORDER BY ",order_by," ",order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
				
		ELSEIF extra_where = 'be' THEN
			
			SET @dyn_cnt = CONCAT("SELECT COUNT(cnt) AS counter FROM (
									SELECT 1 cnt FROM bearheader AS bh
									LEFT JOIN beardetail AS bd ON bd.transactionkey = bh.transactionkey
									LEFT JOIN bearcashcheckdetail AS bc ON bc.transactionkey = bh.transactionkey
									LEFT JOIN customerinvoice AS ci ON ci.invoicenumber = bd.invoicenumber
									WHERE bd.paymentmode = 1 ",table_where," 
									) AS tbl1");
				
			SET @dyn_sql = CONCAT("SELECT ", table_fields ,"  FROM bearheader AS bh
									LEFT JOIN beardetail AS bd ON bd.transactionkey = bh.transactionkey
									LEFT JOIN bearcashcheckdetail AS bc ON bc.transactionkey = bh.transactionkey
									LEFT JOIN customerinvoice AS ci ON ci.invoicenumber = bd.invoicenumber
									WHERE bd.paymentmode = 1 ",table_where," 
									ORDER BY ",order_by," ",order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
				
									
		ELSEIF extra_where = 'dc' THEN
		
			SET @dyn_cnt = CONCAT("SELECT COUNT(cnt) AS counter FROM (
									SELECT 1 cnt FROM dcarheader AS dh
									LEFT JOIN dcardetail AS dd ON dd.transactionkey = dh.transactionkey 
									LEFT JOIN dcarcashcheckdetail AS dc ON dc.transactionkey = dh.transactionkey
									LEFT JOIN customerinvoice AS ci ON ci.invoicenumber = dd.invoicenumber
									WHERE dd.paymentmode = 1 ",table_where," 
									) AS tbl1");
				
									
			SET @dyn_sql = CONCAT("SELECT ", table_fields ,"  FROM dcarheader AS dh
									LEFT JOIN dcardetail AS dd ON dd.transactionkey = dh.transactionkey 
									LEFT JOIN dcarcashcheckdetail AS dc ON dc.transactionkey = dh.transactionkey
									LEFT JOIN customerinvoice AS ci ON ci.invoicenumber = dd.invoicenumber
									WHERE dd.paymentmode = 1 ",table_where," 
									ORDER BY ",order_by," ",order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
				
									
		ELSEIF extra_where = 'crd' THEN
		
			SET @dyn_cnt = CONCAT("SELECT COUNT(cnt) AS counter FROM (
									SELECT 1 cnt FROM cashierreceiptheader AS crh
								  LEFT JOIN cashierreceiptdetails AS crd ON crd.documentnumber = crh.documentnumber
								  WHERE 1=1  ",table_where," 
								  ) AS tbl1");
				
								  
			SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM cashierreceiptheader AS crh
								  LEFT JOIN cashierreceiptdetails AS crd ON crd.documentnumber = crh.documentnumber
								  WHERE 1=1  ",table_where," 
								  ORDER BY ",order_by," ",order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
				
								  
		END IF;
		
	
		PREPARE s1 FROM @dyn_cnt;
		EXECUTE s1;	
	
 		PREPARE s2 FROM @dyn_sql;
   	 	EXECUTE s2;
   	 	SELECT @dyn_sql;
	
  END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_account_settlement_addpdcgrid_1` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_settlement_addpdcgrid_1` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_settlement_addpdcgrid_1`(
	IN rwcnt INT,
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT, 			
	IN table_where TEXT ,
	IN extra_where TEXT,
	IN decimalplaces INT,
	IN where_cond TEXT
)
BEGIN
	IF lmt_strt = '' THEN
			SET lmt_strt=0;
		END IF;
		IF lmt_end = '' THEN
			SET lmt_end=10;
		END IF;
		IF order_by = '' THEN
			SET order_by = 'edit_del_primary_id';
		END IF;
		IF order_type = '' THEN
			SET order_type= 'DESC';
		END IF;
		IF table_fields = '' THEN
			SET table_fields = 'ci.*';
		END IF;
	
		SET @cond1 = split(extra_where,'$$',1);
		SET @cond2 = split(extra_where,'$$',2);
		SET @cond3 = split(extra_where,'$$',3);
		
		SET @cnt_sql = CONCAT("SELECT COUNT(ah.invoicenumber) AS counter FROM arheader ah
									LEFT JOIN cashcheckdetail AS ccd ON ccd.routekey = ah.routekey AND ccd.visitkey = ah.visitkey
									WHERE 1 =1 AND ccd.typecode in(1) AND ccd.transactiontype = 2 ",table_where," 
							UNION (
									SELECT COUNT(ih.invoicenumber) AS counter FROM invoiceheader ih
											LEFT JOIN cashcheckdetail AS ccd ON ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey									
									  WHERE 1 =1 AND ih.paymenttype IN(4) AND ccd.typecode IN(0,1) AND ccd.transactiontype = 1 ",@cond1,"
									)
							UNION
									(
										SELECT COUNT(*) FROM bearheader AS bh
											LEFT JOIN beardetail AS bd ON bd.transactionkey = bh.transactionkey
											LEFT JOIN bearcashcheckdetail AS bcd ON bcd.transactionkey = bh.transactionkey  
											WHERE bd.paymentmode = 1 ",@cond2,"
									)
								  UNION
									(
										SELECT COUNT(*) FROM dcarheader AS dh
											  LEFT JOIN dcardetail AS dd ON dd.transactionkey = dh.transactionkey
											  LEFT JOIN dcarcashcheckdetail AS dcd ON dcd.transactionkey = dh.transactionkey  
											  WHERE dd.paymentmode = 1 ",@cond3,"
									)							
									   ");
		
		PREPARE s1 FROM @cnt_sql;
 		EXECUTE s1;
		
		SET @dyn_sql = CONCAT("SELECT ", table_fields ,"  FROM arheader ah
									LEFT JOIN cashcheckdetail AS ccd ON ccd.routekey = ah.routekey AND ccd.visitkey = ah.visitkey
									LEFT JOIN bankmaster AS bm ON bm.bankcode = ccd.bankcode
								  WHERE 1 =1 AND ccd.typecode in(1) AND ccd.transactiontype = 2 ",table_where,"
								UNION (
									SELECT ih.invoicenumber,ih.customercode,ccd.checknumber,DATE_FORMAT(ccd.checkdate,'%d-%m-%Y') AS checkdate,
										get_deciaml_palces(ccd.amount,",decimalplaces,") AS checkamount,bm.bankname,										
										1 AS sett_tran_type,CONCAT(ih.transactionkey,'_ih_',ih.invoicenumber) AS edit_del_primary_id
										FROM invoiceheader ih
											LEFT JOIN cashcheckdetail AS ccd ON ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey
											LEFT JOIN bankmaster AS bm ON bm.bankcode = ccd.bankcode
										WHERE 1 =1 AND ih.paymenttype IN(4) AND ccd.typecode IN(1) AND ccd.transactiontype = 1 ",@cond1,"
									)
								UNION
								  (
									SELECT bh.documentnumber,bh.customercode,bcd.checknumber,DATE_FORMAT(bcd.checkdate,'%d-%m-%Y') AS checkdate,
											get_deciaml_palces(bcd.amount,",decimalplaces,") AS checkamount,bm.bankname,											
											1 AS sett_tran_type,CONCAT(bh.transactionkey,'_be_',bh.documentnumber) AS edit_del_primary_id
									FROM bearheader AS bh
									  LEFT JOIN beardetail AS bd ON bd.transactionkey = bh.transactionkey 
									  LEFT JOIN bearcashcheckdetail AS bcd ON bcd.transactionkey = bh.transactionkey
									  LEFT JOIN bankmaster AS bm ON bm.bankcode = bcd.bankcode
									WHERE bd.paymentmode = 1 ",@cond2,"
								  )
								  UNION
								  (
									SELECT dh.documentnumber,dh.customercode,dcd.checknumber,DATE_FORMAT(dcd.checkdate,'%d-%m-%Y') AS checkdate,
									get_deciaml_palces(dcd.amount,",decimalplaces,") AS checkamount,bm.bankname,									
									1 AS sett_tran_type,CONCAT(dh.transactionkey,'_dc_',dh.documentnumber) AS edit_del_primary_id
									FROM dcarheader AS dh
									  LEFT JOIN dcardetail AS dd ON dd.transactionkey = dh.transactionkey 
									  LEFT JOIN dcarcashcheckdetail AS dcd ON dcd.transactionkey = dh.transactionkey
									  LEFT JOIN bankmaster AS bm ON bm.bankcode = dcd.bankcode
									WHERE dd.paymentmode = 1 ",@cond3,"
								  )
									ORDER BY ",order_by," ",order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
		
 	 	PREPARE s2 FROM @dyn_sql;
 	  	EXECUTE s2;
  END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_account_settlement_addpdcgrid_2` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_settlement_addpdcgrid_2` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_settlement_addpdcgrid_2`(
	IN rwcnt INT,
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT,
	IN table_where TEXT,
	IN extra_cond TEXT,
	IN decimalplaces INT,
	IN where_cond TEXT
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	SET order_by = 'edit_del_primary_id';
	SET order_type= 'ASC';
	
	IF table_fields = '' THEN
		SET table_fields = 'crh.*';
	END IF;
	
	SET @cond1 = split(extra_cond,'$$',1);
	SET @cond2 = split(extra_cond,'$$',2);
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM cashierreceiptheader AS crh
							  LEFT JOIN cashierreceiptdetails AS crd ON crd.documentnumber = crh.documentnumber
							  LEFT JOIN bankmaster AS bm ON bm.bankcode = crd.bankcode
							  WHERE 1=1  ",table_where,"
							  UNION
							  (
								SELECT bh.documentnumber,bh.customercode,bcd.checknumber,DATE_FORMAT(bcd.checkdate,'%d-%m-%Y') AS checkdate,
										FORMAT(bcd.amount,",decimalplaces,") AS checkamount,bm.bankname,											
										1 AS sett_tran_type,CONCAT(bh.transactionkey,'_be_',bh.documentnumber) AS edit_del_primary_id
								FROM bearheader AS bh
								  LEFT JOIN beardetail AS bd ON bd.transactionkey = bh.transactionkey 
								  LEFT JOIN bearcashcheckdetail AS bcd ON bcd.transactionkey = bh.transactionkey
								  LEFT JOIN bankmaster AS bm ON bm.bankcode = bcd.bankcode
								WHERE bd.paymentmode = 1 ",@cond1,"
							  )
							  UNION
							  (
								SELECT dh.documentnumber,dh.customercode,dcd.checknumber,DATE_FORMAT(dcd.checkdate,'%d-%m-%Y') AS checkdate,
								FORMAT(dcd.amount,",decimalplaces,") AS checkamount,bm.bankname,									
								1 AS sett_tran_type,CONCAT(dh.transactionkey,'_dc_',dh.documentnumber) AS edit_del_primary_id
								FROM dcarheader AS dh
								  LEFT JOIN dcardetail AS dd ON dd.transactionkey = dh.transactionkey 
								  LEFT JOIN dcarcashcheckdetail AS dcd ON dcd.transactionkey = dh.transactionkey
								  LEFT JOIN bankmaster AS bm ON bm.bankcode = dcd.bankcode
								WHERE dd.paymentmode = 1 ",@cond2,"
							  )
						   ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	PREPARE s2 FROM @dyn_sql;
	EXECUTE s2;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_account_settlement_addpdcgrid_3` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_settlement_addpdcgrid_3` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_settlement_addpdcgrid_3`(
	IN rwcnt INT,
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT,
	IN table_where TEXT,
	IN extra_cond TEXT,
	in decimalplaces int,
	in where_cond text
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	SET order_by = 'edit_del_primary_id';
	SET order_type= 'ASC';
	
	IF table_fields = '' THEN
		SET table_fields = 'crh.*';
	END IF;
	
	set @cond1 = split(extra_cond,'$$',1);
	set @cond2 = split(extra_cond,'$$',2);
		
	SET @dyn_cnt = CONCAT("SELECT COUNT(*) AS counter FROM cashierreceiptheader AS crh
							LEFT JOIN cashierreceiptdetails AS crd ON crd.documentnumber = crh.documentnumber
							WHERE 1=1  ",table_where,"
							  UNION
								(
									SELECT COUNT(*) FROM bearheader AS bh
										LEFT JOIN beardetail AS bd ON bd.transactionkey = bh.transactionkey
										LEFT JOIN bearcashcheckdetail AS bc ON bc.transactionkey = bh.transactionkey  
										WHERE bd.paymentmode = 1 ",@cond1,"
								)
							  UNION
								(
									SELECT COUNT(*) FROM dcarheader AS dh
										  LEFT JOIN dcardetail AS dd ON dd.transactionkey = dh.transactionkey
										  LEFT JOIN dcarcashcheckdetail AS dc ON dc.transactionkey = dh.transactionkey  
										  WHERE dd.paymentmode = 1 ",@cond2,"
								)
						  ");
	
	PREPARE s1 FROM @dyn_cnt;
	EXECUTE s1;
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM cashierreceiptheader AS crh
							  LEFT JOIN cashierreceiptdetails AS crd ON crd.documentnumber = crh.documentnumber
							  LEFT JOIN bankmaster AS bm ON bm.bankcode = crd.bankcode
							  WHERE 1=1  ",table_where,"
							  UNION
							  (
								SELECT bd.invoicenumber,DATE_FORMAT(bh.transactiondate,'%d-%m-%Y') AS transactiondate,
								  bc.checknumber,DATE_FORMAT(bc.checkdate,'%d-%m-%Y') AS checkdate,bm.bankname,
								  get_deciaml_palces(bd.totalinvoiceamount,",decimalplaces,") AS totalinvoiceamount,get_deciaml_palces(bd.amountpaid,",decimalplaces,") AS amountpaid,
								  get_deciaml_palces(bd.invoicebalance,",decimalplaces,") AS invoicebalance,get_deciaml_palces(bc.amount,",decimalplaces,") AS pdcbalance,
								  bh.transactionkey AS edit_del_primary_id
								FROM bearheader AS bh
								  LEFT JOIN beardetail AS bd ON bd.transactionkey = bh.transactionkey
								  LEFT JOIN bearcashcheckdetail AS bc ON bc.transactionkey = bh.transactionkey
								  LEFT JOIN bankmaster AS bm ON bm.bankcode = bc.bankcode
								WHERE bd.paymentmode = 1 ",@cond1,"
							  )
							  UNION
							  (
								SELECT dd.invoicenumber,DATE_FORMAT(dh.transactiondate,'%d-%m-%Y') AS transactiondate,
								  dc.checknumber,DATE_FORMAT(dc.checkdate,'%d-%m-%Y') AS checkdate,bm.bankname,
								  get_deciaml_palces(dd.totalinvoiceamount,",decimalplaces,") AS totalinvoiceamount,get_deciaml_palces(dd.amountpaid,",decimalplaces,") AS amountpaid,
								  get_deciaml_palces(dd.invoicebalance,",decimalplaces,") AS invoicebalance,get_deciaml_palces(dc.amount,",decimalplaces,") AS pdcbalance,
								  dh.transactionkey AS edit_del_primary_id
								FROM dcarheader AS dh
								  LEFT JOIN dcardetail AS dd ON dd.transactionkey = dh.transactionkey 
								  LEFT JOIN dcarcashcheckdetail AS dc ON dc.transactionkey = dh.transactionkey
								  LEFT JOIN bankmaster AS bm ON bm.bankcode = dc.bankcode 
								WHERE dd.paymentmode = 1 ",@cond2,"
							  )
						   ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	PREPARE s2 FROM @dyn_sql;
	EXECUTE s2;
	
END */$$
DELIMITER ;

