/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_tax_addtax`(IN id INT)
BEGIN
	IF id > 0 THEN
		-- For Gettin data in Salesman Table
		SELECT * FROM tbltaxmaster WHERE taxcode = id;
