/* Procedure structure for procedure `sp_get_account_transaction_addgccollectiongrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_transaction_addgccollectiongrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_transaction_addgccollectiongrid`(
	IN rwcnt INT,
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	SET order_by = 'transactiondate , invoicenumber';
	SET order_type= 'ASC';
	
	IF table_fields = '' THEN
		SET table_fields = 't1.*';
	END IF;
	
	
	SET @dyn_cnt = CONCAT("SELECT COUNT(*) AS counter FROM customerinvoice AS t1 
	WHERE 1=1  ",table_where);
	
	PREPARE s1 FROM @dyn_cnt;
	EXECUTE s1;
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM customerinvoice AS t1	
