BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	SET order_by = 'id';
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 't1.*';
	END IF;
	-- SET extrawhere = '';
	IF TABLE_NAME = 'company' THEN
		SET @extrawhere = CONCAT(" and cmpycode IN (SELECT DISTINCT cmpycode AS companycode FROM `useraccesscodes` WHERE username='", username ,"')");
		SET table_where=CONCAT(table_where,@extrawhere);
		
		ELSEIF TABLE_NAME = 'regionmaster' THEN
		SET @extrawhere = CONCAT(" and regionmstcode IN (SELECT DISTINCT regionmstcode  FROM `useraccesscodes` WHERE username='", username ,"')");
		SET table_where=CONCAT(table_where,@extrawhere);
		
		ELSEIF TABLE_NAME = 'depotmaster' THEN
		SET @extrawhere = CONCAT(" and depotcode IN (SELECT DISTINCT depotcode  FROM `useraccesscodes` WHERE username='", username ,"')");
		SET table_where=CONCAT(table_where,@extrawhere);
		
		ELSEIF TABLE_NAME = 'areamaster' THEN
		SET @extrawhere = CONCAT(" and areacode IN (SELECT DISTINCT areacode  FROM `useraccesscodes` WHERE username='", username ,"')");
		SET table_where=CONCAT(table_where,@extrawhere);
		
		ELSEIF TABLE_NAME = 'subareamaster' OR TABLE_NAME = 'routemaster' THEN
		SET @extrawhere = CONCAT(" and subareacode IN (SELECT DISTINCT subareacode  FROM `useraccesscodes` WHERE username='", username ,"')");
		SET table_where=CONCAT(table_where,@extrawhere);
		
		ELSEIF TABLE_NAME = 'divisionmaster' THEN
		SET @extrawhere = CONCAT(" ");
		SET table_where=CONCAT(table_where,@extrawhere);
		
		
		
	END IF;
	
	SET @dyn_cnt = CONCAT("SELECT COUNT(*) AS counter FROM ",table_name," AS t1 
	WHERE 1=1  ",table_where);
	
	PREPARE s1 FROM @dyn_cnt;
	EXECUTE s1;
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM ",table_name," AS t1	
	WHERE 1=1  ",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	PREPARE s2 FROM @dyn_sql;
	EXECUTE s2;
	-- select @dyn_sql;	 
END */$$
DELIMITER ;

