/* Procedure structure for procedure `sp_get_arcollection_arcollectionadd_settings` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_arcollection_arcollectionadd_settings` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_arcollection_arcollectionadd_settings`(
in in_route_code int
)
BEGIN
declare new_invoice_no int;
declare new_document_no int;
declare new_salesmancode int;
DECLARE new_invoice_no1 varchar(100);
DECLARE new_document_no1 varchar(100);
	SELECT  IFNULL(boarseq,0) AS  invoice_seq, IFNULL(bodocseq,0) AS document_seq,salesmancode
	INTO new_invoice_no,new_document_no,new_salesmancode
	FROM routemaster WHERE routecode =in_route_code;
		
	
	SET new_document_no1 = CONCAT(in_route_code,"000000",new_document_no+1 );
	SET new_invoice_no1  =  CONCAT(in_route_code,"700000",new_invoice_no+1 );
	
	
	select new_document_no1,new_invoice_no1,new_salesmancode;
END */$$
DELIMITER ;

