/* Procedure structure for procedure `sp_get_basic_index_addcurrency` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_basic_index_addcurrency` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_basic_index_addcurrency`(IN id BIGINT)
BEGIN
	CALL sp_combo_currency_filter('0');
	
	if id > 0 then
		SELECT currencycode,currencyname,arbcurrencyname,alternatecode,
		DATE_FORMAT(startdate,'%d-%m-%Y') as startdate,DATE_FORMAT(enddate,'%d-%m-%Y')as enddate,
		currencysymbol,arbcurrencysymbol,DATE_FORMAT(cdat,'%d-%m-%Y') AS cdat,defaultcurrency,decimalplaces
			FROM currencymaster WHERE  `currencycode` = id;				
		select '1';
	else
		CALL sp_get_table_last_id('currencymaster');
		
		select count(defaultcurrency) as defaultcurrency from currencymaster where defaultcurrency = 1;
	end if;
	
	SELECT currencycode,currencyname,currencysymbol FROM currencymaster WHERE defaultcurrency = 1;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_basic_index_addcurrencydetailgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_basic_index_addcurrencydetailgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_basic_index_addcurrencydetailgrid`(
	IN rwcnt INT,
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT,
	IN extra_field TEXT 
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	IF order_by = '' THEN
		SET order_by = 't2.code';
	END IF;
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	IF table_fields = '' THEN
		SET table_fields = 't2.*';
	END IF;
	
	set table_fields = concat(table_fields,'',extra_field);
	
	SET @dyn_cnt = CONCAT("SELECT COUNT(*) AS counter FROM currencymaster AS t1
	LEFT JOIN currencydetail AS t2 ON t2.currencydetailcode = t1.currencycode
	WHERE 1=1  ",table_where);
	
	PREPARE s1 FROM @dyn_cnt;
	EXECUTE s1;
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM currencymaster AS t1
	LEFT JOIN currencydetail AS t2 ON t2.currencydetailcode = t1.currencycode
	WHERE 1=1  ",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	PREPARE s2 FROM @dyn_sql;
	EXECUTE s2;
	
	 
END */$$
DELIMITER ;

