/* Procedure structure for procedure `sp_get_basic_index_cluster` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_basic_index_cluster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_basic_index_cluster`(
    IN rwcnt INT,
    IN srchvalue VARCHAR(500),
    IN order_by VARCHAR(500),
    IN order_type VARCHAR(10),
    IN lmt_strt INT,
    IN lmt_end INT,
    IN table_fields TEXT,
    IN table_where TEXT
)
BEGIN
    IF lmt_strt IS NULL OR lmt_strt < 0 THEN
        SET lmt_strt = 0;
    END IF;

    IF lmt_end IS NULL OR lmt_end <= 0 THEN
        SET lmt_end = 10;
    END IF;

    IF order_by IS NULL OR TRIM(order_by) = '' THEN
        SET order_by = 'cluster.clustercode';
    END IF;

    IF order_type IS NULL
       OR UPPER(order_type) NOT IN ('ASC', 'DESC') THEN
        SET order_type = 'DESC';
    END IF;

    IF table_fields IS NULL OR TRIM(table_fields) = '' THEN
        SET table_fields = 'cluster.*';
    END IF;

    IF table_where IS NULL THEN
        SET table_where = '';
    END IF;

    SET @cnt_sql = CONCAT(
        'SELECT COUNT(*) AS counter
         FROM clustermaster AS cluster
         WHERE 1 = 1 ',
        table_where
    );

    PREPARE s1 FROM @cnt_sql;
    EXECUTE s1;
    DEALLOCATE PREPARE s1;

    SET @dyn_sql = CONCAT(
        'SELECT ',
        table_fields,
        '
         FROM clustermaster AS cluster
         WHERE 1 = 1 ',
        table_where,
        ' ORDER BY ',
        order_by,
        ' ',
        order_type,
        ' LIMIT ',
        lmt_strt,
        ', ',
        lmt_end
    );

    PREPARE s2 FROM @dyn_sql;
    EXECUTE s2;
    DEALLOCATE PREPARE s2;
END */$$
DELIMITER ;

