/* Procedure structure for procedure `sp_get_changed_password` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_changed_password` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_changed_password`()
BEGIN
	SELECT DISTINCT password3 INTO @oldpassword FROM routemaster LIMIT 1;	
	
	SET @date = CURDATE() + INTERVAL 1 DAY;
	
	SET @day = DAY(@date);
	SET @month = MONTH(@date);
	SET @year = YEAR(@date);
	
	SELECT CASE WHEN LENGTH(@day) = 1 THEN CONCAT(@day,@day) ELSE @day END INTO @day;
	SELECT CASE WHEN LENGTH(@month) = 1 THEN CONCAT("0",@month) ELSE @month END INTO @month;
	
	SET @temppwd1 = CONCAT(@day,@month,RIGHT(@year,2));
	SET @temppwd2 = REVERSE(@temppwd1);
	SET @newpassword = LEFT((@temppwd1+@temppwd2)*(@day+@month),6);
		
	UPDATE routemaster SET password3 = @newpassword, password4 = @oldpassword;
	
	INSERT INTO passwordchagehistory VALUES (CURDATE(), 'password3', @oldpassword, @newpassword, '', NOW());
	
	SELECT 'Cashier Password' AS passtype, @newpassword AS newpassword, @oldpassword oldpassword;
END */$$
DELIMITER ;

