/* Procedure structure for procedure `sp_get_creditnote` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_creditnote` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_creditnote`(IN var_transactiondate DATE)
BEGIN
     
    
    
    
   
     
	   TRUNCATE TABLE TEMPCREDITNOTEORACLE;
    
    
      						
INSERT INTO TEMPCREDITNOTEORACLE
    SELECT
        cm.DivisionCode AS DIVISON,cm.alternatecode AS CUSTOMER_CODE, sh.transactiondate  AS TRX_DATE,sh.transactiondate  AS GL_DATE,
        
        ((SELECT SUM(promoamount) FROM invoicedetail id WHERE id .transactionkey=sh.transactionkey )-TotalPromoAmount)*-1 AS CREDIT_AMOUNT,
        SH.InvoiceNumber AS REF_INV_NUMBER,SH.Comments AS COMMENTS
      FROM
        InvoiceHeader sh
        INNER JOIN
          customermaster cm
          ON
            cm.customercode=sh.customercode
        
      WHERE
         sh.transactiondate=var_transactiondate AND (TotalPromoAmount-(SELECT SUM(promoamount) FROM invoicedetail id where id .transactionkey=sh.transactionkey ))>0
      ;
      
       
      
       
SELECT * FROM tempcreditnoteoracle;  
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_customercode` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_customercode` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_customercode`(		
	   IN route_code bigint(18)
	)
BEGIN
		declare in_flag_id int;
		declare rcode bigint(18);
		declare gen_customercode bigint(18);
		DECLARE in_depo_code BIGINT(18);
		declare in_route_depo_len bigint(18);
		SELECT flagid INTO in_flag_id  FROM controlpanel  WHERE flagid IN ('7','8','9','76') AND `status`=1;
  
		IF in_flag_id = 7 THEN 
	
				SELECT MAX(customercode) INTO rcode FROM customermaster
				WHERE routecode =route_code  AND SUBSTRING(customercode,1,LENGTH(route_code)) LIKE route_code
				GROUP BY routecode ;	
	
			IF rcode IS NULL   THEN			
				SET rcode =1;
				SET gen_customercode = CONCAT(route_code,'0000',rcode);
			 ELSE			
				SET rcode = rcode + 1 ;
				SET gen_customercode = rcode;
			END IF;
		ELSEIF in_flag_id = 8 THEN    
				SELECT depotmaster.depotcode INTO in_depo_code  FROM depotmaster 
				LEFT JOIN routemaster ON routemaster.regionmstcode = depotmaster.regionmstcode
				WHERE   routemaster.routecode = (route_code);
		
				SET in_route_depo_len = LENGTH(in_depo_code)+LENGTH(route_code);
				SELECT MAX(customercode) INTO rcode FROM customermaster
				WHERE routecode =route_code  AND SUBSTRING(customercode,1,in_route_depo_len) LIKE in_depo_code
				GROUP BY routecode ;
				IF rcode IS NULL   THEN
					SET rcode =1;
					SET gen_customercode = CONCAT(in_depo_code,'0000',rcode);
				 ELSE
					SET rcode = rcode + 1 ;
					SET gen_customercode = rcode;
				END IF;
		ELSEIF in_flag_id = 9 THEN    
				SELECT depotmaster.depotcode INTO in_depo_code  FROM depotmaster 
				LEFT JOIN routemaster ON routemaster.regionmstcode = depotmaster.regionmstcode
				WHERE   routemaster.routecode = (route_code);
		
				SELECT MAX(customercode) INTO rcode FROM customermaster
				WHERE routecode =route_code  AND SUBSTRING(customercode,1,LENGTH(in_depo_code)) LIKE in_depo_code
				GROUP BY routecode ;
				
				IF rcode IS NULL   THEN
						SET rcode =1;
						SET gen_customercode = CONCAT(route_code,in_depo_code,'0000',rcode);
				ELSE
						SET rcode = rcode + 1 ;
						SET gen_customercode = rcode;
				END IF;
		ELSE
			SELECT MAX(customercode) INTO rcode FROM customermaster;
			IF rcode IS NULL   THEN				
				SET rcode =1;
				SET gen_customercode = CONCAT('0000',rcode);
			ELSE			
				SET rcode = rcode + 1;
				SET gen_customercode = rcode;
			END IF;	
		END IF;
		
		select gen_customercode as custcode;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_customer_from_discountkey` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_customer_from_discountkey` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_customer_from_discountkey`(
					IN fillby 	INT,
					IN val 		VARCHAR(25),
					IN catid 	VARCHAR(25),
					IN discountkey VARCHAR(25)
					)
BEGIN
	DECLARE where_cond 	TEXT;
	DECLARE where_cat 	TEXT;
	DECLARE joining 	TEXT;
	
	IF fillby = 1 THEN		
		SET where_cond 	=  ' AND route.regionmstcode =';
		SET joining 	=  'LEFT JOIN routemaster AS route ON route.routecode = cust.routecode';
	ELSEIF	fillby = 2 THEN
		SET where_cond 	=  ' AND depot.depotcode =';
		SET joining 	=  'LEFT JOIN routemaster AS route ON route.routecode = cust.routecode
							LEFT JOIN regionmaster AS reg ON reg.regionmstcode = route.regionmstcode
							LEFT JOIN depotmaster AS depot ON depot.regionmstcode = reg.regionmstcode'; 
	ELSEIF	fillby = 3 THEN
		SET where_cond 	=  ' AND armst.areacode =';
		SET joining		=  'LEFT JOIN routemaster AS route ON route.routecode = cust.routecode
							LEFT JOIN subareamaster AS sub ON sub.subareacode = route.subareacode
							LEFT JOIN areamaster AS armst ON armst.areacode = sub.areacode';
	ELSEIF	fillby = 4 THEN
		SET where_cond 	=  ' AND cust.routecode =';
		SET joining		=  '';
	END IF;
	
	IF val = 0 THEN
		SET where_cond 	=	'';
		SET val 		= 	'';
	END IF;
	
	
	IF catid > 0 THEN
		SET where_cat 	= CONCAT(' AND customercategory = ',catid);
	ELSE
		SET where_cat 	= '';
		SET catid 		= '';
	END IF;
	
	SELECT `status` INTO @st FROM controlpanel WHERE flagname = 'Use Alternate Code';
	
	IF @st = 1 THEN	
		
		SET @q1 = CONCAT( "SELECT cust.customercode AS id, CONCAT(cust.alternatecode,' -- ',cust.customername) AS val FROM customermaster as cust
							",joining," WHERE 1=1 ",where_cond," ",val," ",where_cat," and activecustomer = 1 AND templateindicator = 0"); 
	
		
		SET @q2 = CONCAT( 	"SELECT cust.customercode AS id, CONCAT(cust.alternatecode,' -- ',cust.customername) AS val FROM customermaster  as cust
							",joining," WHERE 1=1 ",where_cond," ",val," ",where_cat," and activecustomer = 1 AND cust.discountkey = ",discountkey," AND templateindicator = 0");
	
	else
			
		SET @q1 = CONCAT( "SELECT cust.customercode AS id, CONCAT(cust.customercode,' -- ',cust.customername) AS val FROM customermaster as cust
							",joining," WHERE 1=1 ",where_cond," ",val," ",where_cat," and activecustomer = 1 AND templateindicator = 0"); 
	
		
		SET @q2 = CONCAT( 	"SELECT cust.customercode AS id, CONCAT(cust.customercode,' -- ',cust.customername) AS val FROM customermaster  as cust
							",joining," WHERE 1=1 ",where_cond," ",val," ",where_cat," and activecustomer = 1 AND cust.discountkey = ",discountkey," AND templateindicator = 0");
	end if;
	
	PREPARE s1 FROM @q1;
	EXECUTE s1;
	
	
	PREPARE s2 FROM @q2;
	EXECUTE s2;
	
	
	
	SET @q3 = CONCAT( 	"SELECT cust.customercode FROM customermaster as cust
						",joining," WHERE 1=1 ",where_cond," ",val," ",where_cat," and activecustomer = 1 AND cust.discountkey = ",discountkey," AND templateindicator = 0");
	PREPARE s3 FROM @q3;
	EXECUTE s3;
	
	
END */$$
DELIMITER ;

