/* Procedure structure for procedure `sp_get_customer_from_mapkey` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_customer_from_mapkey` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_customer_from_mapkey`(
					IN catid BIGINT,
					IN routeid BIGINT
					)
BEGIN
	
	SELECT `status` INTO @st FROM controlpanel WHERE flagname = 'Use Alternate Code';
	
	IF routeid > 0 THEN 
	
		IF @st = 1 THEN  
			
			SET @s = CONCAT("SELECT cust.customercode AS id, CONCAT(alternatecode,' -- ',customername) AS val FROM customermaster cust 
					INNER JOIN routesequence AS rs ON rs.customercode=cust.customercode
				WHERE rs.routecode = ",routeid," AND activecustomer = 1 AND templateindicator = 0 ORDER BY cust.alternatecode ASC"); 
			  PREPARE stmt1 FROM @s;
			  EXECUTE stmt1;
			
			SELECT cust.customercode AS id, CONCAT(alternatecode,' -- ',customername) AS val FROM customermaster cust 
			INNER JOIN routesequence AS rs ON rs.customercode=cust.customercode
		WHERE rs.routecode = routeid AND itemmapkey = catid AND activecustomer = 1 AND templateindicator = 0 ORDER BY cust.alternatecode ASC; 
		
		ELSE
		
			
			SELECT cust.customercode AS id, CONCAT(customercode,' -- ',customername) AS val FROM customermaster cust 
					INNER JOIN routesequence AS rs ON rs.customercode=cust.customercode
				WHERE rs.routecode = routeid AND activecustomer = 1 AND templateindicator = 0 ORDER BY cust.customercode ASC; 
			
			
			SELECT cust.customercode AS id, CONCAT(customercode,' -- ',customername) AS val FROM customermaster cust 
					INNER JOIN routesequence AS rs ON rs.customercode=cust.customercode
				WHERE rs.routecode = routeid AND itemmapkey = catid AND activecustomer = 1 AND templateindicator = 0 ORDER BY cust.customercode ASC;
		END IF;
			
		
		SELECT cust.customercode FROM customermaster cust 
			INNER JOIN routesequence AS rs ON rs.customercode=cust.customercode
		WHERE rs.routecode = routeid AND itemmapkey = catid AND activecustomer = 1 AND templateindicator = 0; 
	ELSE
	
		IF @st = 1 THEN	
			
			SELECT customercode AS id, CONCAT(alternatecode,' -- ',customername) AS val FROM customermaster 
				WHERE activecustomer = 1 AND templateindicator = 0; 
			
			
			SELECT customercode AS id, CONCAT(alternatecode,' -- ',customername) AS val FROM customermaster 
				WHERE itemmapkey = catid AND activecustomer = 1 AND templateindicator = 0;
		ELSE
			
			SELECT customercode AS id, CONCAT(customercode,' -- ',customername) AS val FROM customermaster 
				WHERE activecustomer = 1 AND templateindicator = 0; 
			
			
			SELECT customercode AS id, CONCAT(customercode,' -- ',customername) AS val FROM customermaster 
				WHERE itemmapkey = catid AND activecustomer = 1 AND templateindicator = 0;
		END IF;
			
		
		SELECT customercode FROM customermaster 
			WHERE itemmapkey = catid AND activecustomer = 1 AND templateindicator = 0; 	
	
	END IF;
	
END */$$
DELIMITER ;

