							",joining," WHERE 9=9 ",where_cond," ",val," ",where_cat," ",cust_cat," and activecustomer = 1 ",where_outlet," ",outletprod," AND templateindicator = 0");
	else	
			
		SET @q1 = CONCAT( "SELECT cust.customercode AS id, CONCAT(cust.customercode,' -- ',cust.customername) AS val FROM customermaster as cust
							",joining," WHERE 9=9 ",where_cond," ",val," ",where_cat," ",cust_cat," and activecustomer = 1 AND templateindicator = 0"); 
	
		
		SET @q2 = CONCAT( 	"SELECT cust.customercode AS id, CONCAT(cust.customercode,' -- ',cust.customername) AS val FROM customermaster  as cust
							",joining," WHERE 9=9 ",where_cond," ",val," ",where_cat," ",cust_cat," and activecustomer = 1 ",where_outlet," ",outletprod," AND templateindicator = 0");	
	end if;
	
	PREPARE s1 FROM @q1;
	EXECUTE s1;
	
	
