/* Procedure structure for procedure `sp_get_datamanagement_index_viewlogdata` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_datamanagement_index_viewlogdata` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_datamanagement_index_viewlogdata`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT 		)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'code';
	END IF;
	
	IF order_by = 'createdat' THEN
		SET order_by = 'cdat';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = '*';
	END IF;
    
    
	SET @dyn_cnt = CONCAT("SELECT COUNT(*) AS counter 
	FROM logmaster
	WHERE 1=1  ",table_where);
	
	PREPARE s1 FROM @dyn_cnt;
	EXECUTE s1;	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ,"
	FROM logmaster
	WHERE 1=1 ",table_where,  " ORDER BY ",order_by," ", 
	order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
        	
    PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_dave` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_dave` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_dave`()
BEGIN
  DECLARE done INT DEFAULT FALSE;
  DECLARE var_main_itemcode DECIMAL(18,0);
  DECLARE var_reqquantity DECIMAL(18,0);
  DECLARE var_batchno VARCHAR(20);
  DECLARE var_depotcode DECIMAL(18,0);
  DECLARE var_depotinventorykey BIGINT(20);
  DECLARE var_expirydate DATETIME;
  DECLARE var_itemcode DECIMAL(18,0);
  DECLARE var_quantity DECIMAL(18,0);
  
  DECLARE counter INT DEFAULT 1;
  DECLARE no_more_rows BOOLEAN;
  DECLARE num_rows INT DEFAULT 0;
  DECLARE from_start INT DEFAULT 0;  
  
  DECLARE cur1 CURSOR FOR SELECT itemcode,quantity FROM inventorytransactiondetail WHERE itemcode = 613 LIMIT 1;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET no_more_rows = TRUE;
  
  DROP TEMPORARY TABLE IF EXISTS tmp_quantityinfo; 
  CREATE TEMPORARY TABLE tmp_quantityinfo SELECT * FROM depotstock WHERE 1 = 2;
  
  OPEN cur1;
		SELECT FOUND_ROWS() INTO num_rows;
		main_loop: LOOP	
		IF no_more_rows THEN
			CLOSE cur1;
			LEAVE main_loop;
			IF counter > num_rows THEN
				CLOSE cur1;
				LEAVE main_loop;
			END IF;
		END IF;		
  
		FETCH cur1 INTO var_main_itemcode,var_reqquantity;
	
		SELECT COUNT(*) INTO @cnt FROM depotstock WHERE itemcode = var_main_itemcode;
		
			WHILE from_start < @cnt DO
			
				 IF var_reqquantity > 0 THEN
					SET @q = CONCAT("SELECT depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate
						into @var_depotinventorykey,@var_itemcode,@var_quantity,@var_depotcode,@var_batchno,@var_expirydate
					FROM depotstock
					WHERE itemcode = ",var_main_itemcode," ORDER BY expirydate
					limit ",from_start,",1");
 					
					PREPARE s1 FROM @q;
					EXECUTE s1;
						
					IF @var_quantity < var_reqquantity THEN
						SET @q1 = CONCAT("insert into tmp_quantityinfo (depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate)
							values(",@var_depotinventorykey,",",@var_itemcode,",",@var_quantity,",",@var_depotcode,",'",@var_batchno,"','",@var_expirydate,"')");
						SET var_reqquantity = var_reqquantity - @var_quantity;
						PREPARE s2 FROM @q1;
						EXECUTE s2;
						
					ELSEIF @var_quantity > var_reqquantity THEN					
						SET @q1 = CONCAT("insert into tmp_quantityinfo (depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate)
 							values(",@var_depotinventorykey,",",@var_itemcode,",",var_reqquantity,",",@var_depotcode,",'",@var_batchno,"','",@var_expirydate,"')");
						SET var_reqquantity = var_reqquantity - var_reqquantity;
						
						PREPARE s2 FROM @q1;
						EXECUTE s2;
						
					END IF;
					
				END IF;
				SET from_start 	= from_start  + 1;
				IF var_reqquantity = 0 THEN
					SET from_start = @cnt;
				END IF;
		
			END WHILE;
		FETCH cur1 INTO var_main_itemcode,var_reqquantity;
		SET counter = counter+1;
		END LOOP main_loop;
	
END */$$
DELIMITER ;

