/* Procedure structure for procedure `sp_get_distinct_company_entity` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_distinct_company_entity` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_distinct_company_entity`(
    IN rwcnt INT,
    IN srchvalue VARCHAR(500),
    IN order_by VARCHAR(500),
    IN order_type VARCHAR(10),
    IN lmt_strt INT,
    IN lmt_end INT,
    IN table_fields TEXT,
    IN table_where TEXT
)
BEGIN
    /* Pagination defaults */
    IF lmt_strt IS NULL OR lmt_strt < 0 THEN
        SET lmt_strt = 0;
    END IF;

    IF lmt_end IS NULL OR lmt_end <= 0 THEN
        SET lmt_end = 10;
    END IF;

    /* Search default */
    IF srchvalue IS NULL THEN
        SET srchvalue = '';
    END IF;

    SET srchvalue = TRIM(srchvalue);

    /* Only entity sorting is required */
    IF order_by IS NULL
       OR TRIM(order_by) = ''
       OR LOWER(order_by) = 'slno' THEN
        SET order_by = 'entity';
    END IF;

    /* Validate sorting direction */
    IF order_type IS NULL
       OR UPPER(order_type) NOT IN ('ASC', 'DESC') THEN
        SET order_type = 'ASC';
    END IF;

    SET order_type = UPPER(order_type);

    /*
     * First result set:
     * Total distinct records for pagination.
     */
    SELECT COUNT(DISTINCT TRIM(cmpny.entity)) AS counter
    FROM company AS cmpny
    WHERE cmpny.entity IS NOT NULL
      AND TRIM(cmpny.entity) <> ''
      AND (
            srchvalue = ''
            OR TRIM(cmpny.entity) LIKE CONCAT(
                '%',
                srchvalue,
                '%'
            )
          );

    /*
     * Serial number begins from the current page offset.
     */
    SET @serial_number = lmt_strt;

    /*
     * Second result set:
     * Distinct entity data with serial number.
     */
    IF order_type = 'DESC' THEN

        SELECT
            (@serial_number := @serial_number + 1) AS slno,
            entity
        FROM
        (
            SELECT DISTINCT
                TRIM(cmpny.entity) AS entity
            FROM company AS cmpny
            WHERE cmpny.entity IS NOT NULL
              AND TRIM(cmpny.entity) <> ''
              AND (
                    srchvalue = ''
                    OR TRIM(cmpny.entity) LIKE CONCAT(
                        '%',
                        srchvalue,
                        '%'
                    )
                  )
            ORDER BY entity DESC
            LIMIT lmt_strt, lmt_end
        ) AS entity_records;

    ELSE

        SELECT
            (@serial_number := @serial_number + 1) AS slno,
            entity
        FROM
        (
            SELECT DISTINCT
                TRIM(cmpny.entity) AS entity
            FROM company AS cmpny
            WHERE cmpny.entity IS NOT NULL
              AND TRIM(cmpny.entity) <> ''
              AND (
                    srchvalue = ''
                    OR TRIM(cmpny.entity) LIKE CONCAT(
                        '%',
                        srchvalue,
                        '%'
                    )
                  )
            ORDER BY entity ASC
            LIMIT lmt_strt, lmt_end
        ) AS entity_records;

    END IF;
END */$$
DELIMITER ;

