/* Procedure structure for procedure `sp_get_hhctransaction_stock_beginstock` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_hhctransaction_stock_beginstock` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_hhctransaction_stock_beginstock`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500),
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT,
	IN table_where TEXT,
	in detail_where text
    )
BEGIN
		IF lmt_strt = '' THEN
			SET lmt_strt=0;
		END IF;
		IF lmt_end = '' THEN
			SET lmt_end=10;
		END IF;
		IF order_by = '' THEN
			SET order_by = 'ith.detailkey';
		END IF;
		IF order_type = '' THEN
			SET order_type= 'DESC';
		END IF;
		IF table_fields = '' THEN
			SET table_fields = 'ith.*';
		END IF;
		
		CALL sp_combo_routemaster();
		
		SET @cnt_sql = CONCAT("SELECT COUNT(DISTINCT(ith.detailkey)) AS counter FROM inventorytransactionheader AS ith
								LEFT JOIN inventorytransactiondetail AS itd ON itd.detailkey = ith.detailkey
								LEFT JOIN routemaster AS rm ON rm.routecode = ith.routecode
								LEFT JOIN salesman AS sm ON sm.salesmancode = ith.salesmancode
								WHERE 1=1  ",table_where," ",detail_where," ");
		PREPARE s1 FROM @cnt_sql;
		EXECUTE s1;
		
		SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM inventorytransactionheader AS ith
								LEFT JOIN inventorytransactiondetail AS itd ON itd.detailkey = ith.detailkey
								LEFT JOIN routemaster AS rm ON rm.routecode = ith.routecode
								LEFT JOIN salesman AS sm ON sm.salesmancode = ith.salesmancode
		WHERE 1=1  ",table_where," ", detail_where ," GROUP BY ith.detailkey ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
		PREPARE s2 FROM @dyn_sql;
		EXECUTE s2;
		
		
		
		
		
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_hhctransaction_stock_viewbeginstock` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_hhctransaction_stock_viewbeginstock` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_hhctransaction_stock_viewbeginstock`(
	IN detail_key BIGINT(28)
    )
BEGIN
		SELECT
			 ith.transactiontype,
			 DATE_FORMAT(ith.transactiondate,'%d-%m-%Y') AS transactiondate,
			 DATE_FORMAT(sd.routestartdate,'%d-%m-%Y') AS routestartdate,
			 ith.transactiontime,
			 ith.documentnumber,
			 IF(ith.voidflag = 0, 'Valid','Not Valid') AS voidflag,
			 IF(routeclosed = 1, 'Closed','Live') AS accperiod,			 
			 ith.routecode AS routecode,
			 ith.transferlocationcode  AS depotroute,
			 sm.salesmanname1 AS salesmanname1,
			 loadnumber,
			 detailkey           AS edit_del_primary_id,
			 DATE_FORMAT(ith.requestdate,'%d-%m-%Y') AS requestdate,
			DATE_FORMAT(ith.deliverydate,'%d-%m-%Y') AS deliverydate,
			isurgent,
			rm.routename AS routename,
			transmitindicator,
			receivedtime		
			FROM inventorytransactionheader AS ith
			LEFT JOIN salesman AS sm ON sm.salesmancode = ith.salesmancode
			LEFT JOIN startendday AS sd ON sd.routekey = ith.routekey
			LEFT JOIN routemaster AS rm ON rm.routecode = ith.routecode
			WHERE ith.detailkey = detail_key;
		
		CALL sp_combo_routemaster();
		CALL sp_combo_routemaster_loadrequest();
		
		
    END */$$
DELIMITER ;

