/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_hhctransaction_stock_viewbeginstockgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_hhctransaction_stock_viewbeginstockgrid`(
	IN rwcnt INT,
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
