	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'itd.itemcode';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'desc';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'itd.*';
	END IF;
	
	
	SET @dyn_cnt = CONCAT("SELECT COUNT(*) AS counter FROM inventorytransactiondetail AS itd 
	LEFT  JOIN inventorysummarydetail isd ON isd.routekey = itd.routekey AND isd.itemcode = itd.itemcode
					LEFT JOIN itemmaster AS im ON im.actualitemcode = itd.itemcode
					WHERE 1=1  ",table_where);
	
	PREPARE s1 FROM @dyn_cnt;
	EXECUTE s1;
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM  inventorytransactiondetail AS itd 
	LEFT  JOIN inventorysummarydetail isd ON isd.routekey = itd.routekey AND isd.itemcode = itd.itemcode
					LEFT JOIN itemmaster AS im ON im.actualitemcode = itd.itemcode
					WHERE 1=1  ",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	PREPARE s2 FROM @dyn_sql;
	EXECUTE s2;
	select @dyn_sql;
	 
END */$$
