/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_hhctransaction_summary_viewinventorysummary`(
		IN var_routekey BIGINT(18)
	)
BEGIN
	SELECT sed.routekey,sed.routecode, rm.routename, sm.salesmanname1, DATE_FORMAT(sed.routestartdate,"%d-%m-%Y") as routestartdate,DATE_FORMAT(sed.routeenddate,"%d-%m-%Y") as routeenddate, 
	IF(sed.routeclosed = 0,'No','Yes') AS routeclosed
	FROM startendday sed
	LEFT JOIN routemaster rm ON rm.routecode = sed.routecode
	left join salesman as sm on sm.salesmancode = sed.salesmancode
	WHERE sed.routekey = var_routekey;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_hhctransaction_summary_viewinventorysummarygrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_hhctransaction_summary_viewinventorysummarygrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_hhctransaction_summary_viewinventorysummarygrid`(
	IN rwcnt INT,	
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT,
	IN table_where TEXT 		)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	SET order_by = 'sed.routekey, im.alternatecode';
	
	SET order_type= 'ASC';
	
	IF table_fields = '' THEN
		SET table_fields = 'sed.*';
	END IF;
	SET @cnt_sql = CONCAT("SELECT COUNT(*) AS counter FROM startendday sed,routemaster rm,salesman sm,
							inventorysummarydetail isd,itemmaster im, itemgroup ig,submajorcategory smc,
							majorcategory mc
							WHERE sed.routekey = isd.routekey AND sed.routecode = rm.routecode AND
                            sed.salesmancode = sm.salesmancode AND im.actualitemcode = isd.itemcode AND
                            ig.itemgroupcode = im.itemgroupcode AND smc.submajorcategorycode = ig.submajorcategorycode AND
                            mc.majorcategorycode = smc.majorcategorycode ",table_where);
	
	PREPARE s1 FROM @cnt_sql;
	EXECUTE s1;
	
	SET @dyn_sql = CONCAT("
		SELECT ", table_fields ," 
		FROM startendday sed, routemaster rm, salesman sm, inventorysummarydetail isd,itemmaster im, itemgroup ig,submajorcategory smc, majorcategory mc
		WHERE sed.routekey = isd.routekey AND sed.routecode = rm.routecode AND sed.salesmancode = sm.salesmancode AND im.actualitemcode = isd.itemcode AND
				ig.itemgroupcode = im.itemgroupcode AND smc.submajorcategorycode = ig.submajorcategorycode AND mc.majorcategorycode = smc.majorcategorycode ",
		table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
		
 	PREPARE s2 FROM @dyn_sql;	
 	EXECUTE s2;
 	
 	SELECT @dyn_sql;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_hhctransaction_transaction_checkprocessload` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_hhctransaction_transaction_checkprocessload` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_hhctransaction_transaction_checkprocessload`(IN routeid bigINT)
BEGIN
	SELECT routekey INTO @in_route_key_code FROM startendday 
	WHERE startendday.routecode=routeid
		AND startendday.routeclosed = 0
	ORDER BY routekey DESC  LIMIT 1	;
	
	
	select count(*) as counter from inventorytransactionheader where routecode = routeid 
	 and routekey = @in_route_key_code;
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_hhc_index_invoiceitem` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_hhc_index_invoiceitem` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_hhc_index_invoiceitem`(
	IN rwcnt INT,
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT 
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	IF order_by = '' THEN
		SET order_by = 'actualitemcode';
	END IF;
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	IF table_fields = '' THEN
		SET table_fields = 'im.*';
	END IF;
	IF rwcnt = 1 THEN
		SET @dyn_sql = CONCAT("SELECT COUNT(*) AS counter 
		FROM itemmaster AS im 
		WHERE 1=1  ",table_where);
	ELSE
		SET @dyn_sql = CONCAT("SELECT ", table_fields ,"
		FROM itemmaster AS im 
		 WHERE 1=1  ",table_where,  " ORDER BY ",order_by," ", 
		order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	END IF;
	PREPARE s1 FROM @dyn_sql;
	
	EXECUTE s1;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_inventory_dailysalesmanload_qtyinfo_ordertoload` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_dailysalesmanload_qtyinfo_ordertoload` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_dailysalesmanload_qtyinfo_ordertoload`(
in table_name varchar(50),
IN tran_date DATE,
IN var_routecode BIGINT
)
BEGIN
  
	DECLARE var_main_itemcode,var_reqquantity,last_itemcode DECIMAL(18,0);
	DECLARE counter INT DEFAULT 1;
	DECLARE no_more_rows BOOLEAN;
	DECLARE from_start,inner_start,limit_start,num_rows,main_cnt INT DEFAULT 0;
  
  
  DECLARE cur1 CURSOR FOR SELECT itemcode,sum(salesqty) FROM salesorderdetail AS sod
		LEFT JOIN salesorderheader AS soh ON soh.transactionkey = sod.transactionkey
		WHERE DATE(soh.orderdeliverydate) = tran_date and routecode = var_routecode
		GROUP BY itemcode ORDER BY itemcode;  
  
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET no_more_rows = TRUE;  
  DROP TEMPORARY TABLE IF EXISTS tmp_quantityinfo; 
  
  set @qtmp = concat("CREATE TEMPORARY TABLE tmp_quantityinfo (SELECT * FROM ",table_name," WHERE 1 = 2)");
  prepare s1 from @qtmp;
  EXECUTE s1;
  OPEN cur1;
		SELECT FOUND_ROWS() INTO num_rows;
		main_loop: LOOP	
		IF no_more_rows THEN
			CLOSE cur1;
			LEAVE main_loop;
			IF counter > num_rows THEN
				CLOSE cur1;
				LEAVE main_loop;
			END IF;
		END IF;		
  
		FETCH cur1 INTO var_main_itemcode,var_reqquantity;
		SELECT COUNT(itemcode) INTO main_cnt FROM salesorderdetail AS sod
			LEFT JOIN salesorderheader AS soh ON soh.transactionkey = sod.transactionkey
			WHERE DATE(soh.orderdeliverydate) = tran_date AND routecode = var_routecode
			GROUP BY itemcode ORDER BY itemcode;
			SET from_start 	= 0;
			WHILE from_start < main_cnt DO
				SET inner_start = 0;
				SET limit_start	= 0;
 				 IF var_reqquantity > 0 THEN
					IF table_name = 'depotstock' THEN
						SET @qtmp = CONCAT("SELECT COUNT(*) INTO @innercnt FROM ",table_name," WHERE quantity > 0 AND itemcode = ",var_main_itemcode);
					ELSEIF table_name = 'tbldepotstock' THEN
						SET @qtmp = CONCAT("SELECT COUNT(*) INTO @innercnt FROM ",table_name," WHERE avlquantity > 0 AND itemcode = ",var_main_itemcode);
					END IF;
					PREPARE s1 FROM @qtmp;
					EXECUTE s1;
					
					IF last_itemcode <> var_main_itemcode THEN
						WHILE inner_start < @innercnt DO
							IF table_name = 'depotstock' THEN
								SET @q = CONCAT("SELECT depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate
									into @var_depotinventorykey,@var_itemcode,@var_quantity,@var_depotcode,@var_batchno,@var_expirydate
								FROM depotstock
								WHERE itemcode = ",var_main_itemcode," AND quantity > 0 ORDER BY expirydate
								limit ",limit_start,",1");
								PREPARE s1 FROM @q;
								EXECUTE s1;
							 ELSEIF table_name = 'tbldepotstock' THEN
								SET @q = CONCAT("SELECT depotinventorykey,itemcode,avlquantity,depotcode,batchno,expirydate
									into @var_depotinventorykey,@var_itemcode,@var_quantity,@var_depotcode,@var_batchno,@var_expirydate
								FROM tbldepotstock
								WHERE itemcode = ",var_main_itemcode," AND avlquantity > 0 ORDER BY expirydate
								limit ",limit_start,",1");
								PREPARE s1 FROM @q;
								EXECUTE s1;
							 END IF;
							IF @var_quantity < var_reqquantity  AND @var_quantity > 0 THEN
								SET @q1 = CONCAT("insert into tmp_quantityinfo (depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate)
									values(",@var_depotinventorykey,",",@var_itemcode,",",@var_quantity,",",@var_depotcode,",'",@var_batchno,"','",@var_expirydate,"')");
								SET var_reqquantity = var_reqquantity - @var_quantity;
								
								PREPARE s2 FROM @q1;
								EXECUTE s2;
								
							ELSEIF @var_quantity > var_reqquantity  AND @var_quantity > 0 THEN					
								SET @q1 = CONCAT("insert into tmp_quantityinfo (depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate)
									values(",@var_depotinventorykey,",",@var_itemcode,",",var_reqquantity,",",@var_depotcode,",'",@var_batchno,"','",@var_expirydate,"')");
								SET var_reqquantity = 0;
								
								PREPARE s2 FROM @q1;
								EXECUTE s2;
								
							END IF;
							SET inner_start 	= inner_start  + 1;
							SET limit_start 	= limit_start  + 1;
							
							IF var_reqquantity 	= 0 THEN
								SET inner_start = @innercnt;
							END IF;
						END WHILE;
					END IF;
					SET last_itemcode = var_main_itemcode;
	 			END IF;
				
				SET from_start 		= from_start  + 1;
				IF var_reqquantity 	= 0 THEN
					SET from_start 	= main_cnt;
				END IF;
			END WHILE;		
		SET counter = counter+1;
		END LOOP main_loop;	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_inventory_dailysalesmanload_qtyinfo_previousday` */

