	DECLARE var_main_itemcode,var_reqquantity,last_itemcode DECIMAL(18,0);
	DECLARE counter INT DEFAULT 1;
	DECLARE no_more_rows BOOLEAN;
	DECLARE from_start,inner_start,limit_start,num_rows,main_cnt INT DEFAULT 0;
  
  
  DECLARE cur1 CURSOR FOR SELECT itemcode,SUM((cases*upc)+units) AS quantity  FROM startingloaddetail AS sld
		WHERE DATE(ddate) = exp_date AND routecode = var_routecode AND loadperiodnumber = var_load
		GROUP BY itemcode ORDER BY itemcode;  
  
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET no_more_rows = TRUE;  
  DROP TEMPORARY TABLE IF EXISTS tmp_quantityinfo; 
  
  SET @qtmp = CONCAT("CREATE TEMPORARY TABLE tmp_quantityinfo (SELECT * FROM ",table_name," WHERE 1 = 2)");
