/* Procedure structure for procedure `sp_get_inventory_index_companygroup` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_index_companygroup` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_index_companygroup`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT 		)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'companygroupcode';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'grp.*';
	END IF;
    
	SET @cnt_sql = CONCAT("SELECT COUNT(*) AS counter 
	FROM companygroup AS grp 
	LEFT JOIN company as cmp ON cmp.cmpycode = grp.parentcompany
	WHERE 1=1  ",table_where);
	
	
	PREPARE s1 FROM @cnt_sql;
	EXECUTE s1;
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ,"
	FROM companygroup AS grp 
	LEFT JOIN company as cmp ON cmp.cmpycode = grp.parentcompany
	WHERE 1=1  ",table_where,  " ORDER BY ",order_by," ",order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	PREPARE s2 FROM @dyn_sql;
	EXECUTE s2;
    
    
    
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_inventory_index_itemgrp` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_index_itemgrp` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_index_itemgrp`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500),
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT,
	IN table_where TEXT 	)
BEGIN
		IF lmt_strt = '' THEN
			SET lmt_strt=0;
		END IF;
		IF lmt_end = '' THEN
			SET lmt_end=10;
		END IF;
		IF order_by = '' THEN
			SET order_by = 'item.itemgroupcode';
		END IF;
		IF order_type = '' THEN
			SET order_type= 'DESC';
		END IF;
		SET order_type= 'ASC';
		
		IF table_fields = '' THEN
			SET table_fields = 'cnt.*';
		END IF;
		
		SET @cnt_sql = CONCAT("SELECT COUNT(*) AS counter
			FROM itemgroup AS item LEFT JOIN submajorcategory AS sub ON
			sub.submajorcategorycode = item.submajorcategorycode
			WHERE 1=1  ",table_where);
			
			PREPARE s1 FROM @cnt_sql;
			EXECUTE s1;
		
		SET @dyn_sql = CONCAT("SELECT ", table_fields ,"
			 FROM itemgroup AS item LEFT JOIN submajorcategory AS sub ON
			 sub.submajorcategorycode = item.submajorcategorycode
			 WHERE 1=1  ",table_where,  " ORDER BY ",order_by," ",
			order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
			
			PREPARE s2 FROM @dyn_sql;
			EXECUTE s2;		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_inventory_index_items` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_index_items` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_index_items`(
	          IN rwcnt INT,
	IN srchvalue VARCHAR(500),
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT,
	IN table_where TEXT
    )
BEGIN
		IF lmt_strt = '' THEN
			SET lmt_strt=0;
		END IF;
		IF lmt_end = '' THEN
			SET lmt_end=10;
		END IF;
		IF order_by = '' THEN
			SET order_by = 'item.actualitemcode';
		END IF;
		IF order_type = '' THEN
			SET order_type= 'DESC';
		END IF;
		IF table_fields = '' THEN
			SET table_fields = 'cnt.*';
		END IF;
		
		
		SET @cnt_sql = CONCAT("SELECT COUNT(*) AS counter
			FROM  usermaster as um 
				INNER JOIN (SELECT DISTINCT cmpycode,username FROM useraccesscodes) as uac ON uac.username= um.username
				INNER JOIN (SELECT DISTINCT parentcompany,companygroupcode FROM  companygroup ) as cg  ON cg.parentcompany = uac.cmpycode
				INNER JOIN (SELECT DISTINCT companygroupcode,majorcategorycode FROM majorcategory) as mc ON mc.companygroupcode = cg.companygroupcode
				INNER JOIN  (SELECT DISTINCT submajorcategorycode,majorcategorycode FROM submajorcategory) as smc ON smc.majorcategorycode = mc.majorcategorycode
				INNER JOIN (SELECT DISTINCT itemgroupcode,submajorcategorycode,itemgroupname FROM itemgroup) AS igrp ON igrp.submajorcategorycode = smc.submajorcategorycode
				INNER JOIN  itemmaster AS item ON item.itemgroupcode = igrp.itemgroupcode
				LEFT JOIN itemsequence AS iseq ON iseq.actualitemcode = item.actualitemcode			
			WHERE 1=1  ",table_where);
		PREPARE s1 FROM @cnt_sql;
		EXECUTE s1;
		
		SET @dyn_sql = CONCAT("SELECT ", table_fields ,"
			FROM  usermaster as um 
				INNER JOIN (SELECT DISTINCT cmpycode,username FROM useraccesscodes) as uac ON uac.username= um.username
				INNER JOIN (SELECT DISTINCT parentcompany,companygroupcode FROM  companygroup ) as cg  ON cg.parentcompany = uac.cmpycode
				INNER JOIN (SELECT DISTINCT companygroupcode,majorcategorycode FROM majorcategory) as mc ON mc.companygroupcode = cg.companygroupcode
				INNER JOIN  (SELECT DISTINCT submajorcategorycode,majorcategorycode FROM submajorcategory) as smc ON smc.majorcategorycode = mc.majorcategorycode
				INNER JOIN (SELECT DISTINCT itemgroupcode,submajorcategorycode,itemgroupname FROM itemgroup) AS igrp ON igrp.submajorcategorycode = smc.submajorcategorycode
				INNER JOIN  itemmaster AS item ON item.itemgroupcode = igrp.itemgroupcode
				LEFT JOIN itemsequence AS iseq ON iseq.actualitemcode = item.actualitemcode
			WHERE 1=1  ",table_where,  " ORDER BY ",order_by," ",
			order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
		PREPARE s2 FROM @dyn_sql;
		EXECUTE s2;
    END */$$
DELIMITER ;

