DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_index_itemset1`(
		IN itemcode INT
    )
BEGIN
	CALL sp_combo_itempackage();
	CALL sp_combo_itemtaxkey();
	
	IF itemcode > 0 THEN 
