/* Procedure structure for procedure `sp_get_inventory_routestartday` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_routestartday` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_routestartday`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT ,	
	IN tran_key BIGINT )
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'routekey';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'startendday.*';
	END IF;
	  
	SELECT routekey INTO @routekey FROM invoiceheader WHERE transactionkey =  tran_key;
	
	SET @dyn_cnt = CONCAT("SELECT COUNT(routekey) AS counter FROM startendday AS startendday
	LEFT JOIN salesman ON salesman.salesmancode = startendday.salesmancode
	LEFT JOIN routemaster ON routemaster.routecode=startendday.routecode
	WHERE 1=1  ",table_where);
        PREPARE s1 FROM @dyn_cnt;
	EXECUTE s1;	
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM startendday AS startendday
	LEFT JOIN salesman ON salesman.salesmancode = startendday.salesmancode
	LEFT JOIN routemaster ON routemaster.routecode=startendday.routecode
	WHERE 1=1  ",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;	
	
	
  
  END */$$
DELIMITER ;

