/* Procedure structure for procedure `sp_get_inventory_transaction_batchinfo` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_transaction_batchinfo` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_transaction_batchinfo`(
	IN var_depotinventorykey BIGINT
    )
BEGIN
	DECLARE var_flagid INT;
	
	SELECT flagid INTO var_flagid FROM controlpanel WHERE `flagid` IN (14,64) AND `status` = 1;
	
	IF var_flagid  = 14 THEN 
		SELECT 	IFNULL(FLOOR(ds.quantity/im.unitspercase),0) AS cases, 
				IFNULL((ds.quantity%im.unitspercase),0) AS pieces,
				DATE_FORMAT(expirydate,'%d-%m-%Y') AS expirydate,batchno
			FROM depotstock ds,itemmaster im
			WHERE ds.itemcode = im.actualitemcode AND depotinventorykey = var_depotinventorykey;
	ELSEIF var_flagid  = 64 THEN 
		SELECT 	IFNULL(FLOOR(ds.avlquantity/im.unitspercase),0) AS cases, 
				IFNULL((ds.avlquantity%im.unitspercase),0) AS pieces,
				DATE_FORMAT(expirydate,'%d-%m-%Y') AS expirydate,batchno
			FROM tbldepotstock ds,itemmaster im
			WHERE ds.itemcode = im.actualitemcode AND depotinventorykey = var_depotinventorykey;	
	END IF;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_inventory_transaction_batchinfo_depotexp` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_transaction_batchinfo_depotexp` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_transaction_batchinfo_depotexp`(
	IN var_depotinventorykey BIGINT
    )
BEGIN
	
	SELECT 	IFNULL(FLOOR(ds.quantity/im.unitspercase),0) AS cases, 
			IFNULL((ds.quantity%im.unitspercase),0) AS pieces,
			DATE_FORMAT(expirydate,'%d-%m-%Y') AS expirydate,batchno
		FROM depotstock ds,itemmaster im
		WHERE ds.itemcode = im.actualitemcode AND depotinventorykey = var_depotinventorykey;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_inventory_transaction_customeritemgroup` */

