DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_transaction_customeritemgroup`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500),
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT,
	IN table_where TEXT
    )
BEGIN
		IF lmt_strt = '' THEN
			SET lmt_strt=0;
		END IF;
		IF lmt_end = '' THEN
			SET lmt_end=10;
		END IF;
		IF order_by = '' THEN
			SET order_by = 'customeritemgrpcode';
		END IF;
		IF order_type = '' THEN
			SET order_type= 'DESC';
		END IF;
		SET order_type= 'ASC';
		
		IF table_fields = '' THEN
			SET table_fields = 'customer.*';
		END IF;
		
		SET @cnt_sql = CONCAT("SELECT COUNT(*) AS counter
