/* Procedure structure for procedure `sp_get_inventory_transaction_dailysalesmanload` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_transaction_dailysalesmanload` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_transaction_dailysalesmanload`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT 		)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'loaddetailcode';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'loaddetail.*';
	END IF;
	
	if table_where = '' then
		set table_where = ' AND ddate  = DATE(CURRENT_DATE()) ';
	end if;
    
	SET @cnt_sql = CONCAT("SELECT COUNT(cnt) AS counter FROM 
		(
			SELECT 1 AS cnt 
			FROM startingloaddetail AS loaddetail 
			LEFT JOIN salesman	ON loaddetail.salesmancode = salesman.salesmancode
			LEFT JOIN routemaster as rm on rm.routecode = loaddetail.routecode
			WHERE 1=1  ",table_where,  " GROUP BY loadperiodnumber,loaddetail.ddate,loaddetail.routecode
		) AS tbl");
	
	
	PREPARE s1 FROM @cnt_sql;
	EXECUTE s1;
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ,"
	FROM startingloaddetail AS loaddetail 
	LEFT JOIN salesman	ON loaddetail.salesmancode = salesman.salesmancode
	LEFT JOIN routemaster as rm on rm.routecode = loaddetail.routecode
	WHERE 1=1  ",table_where,  " GROUP BY loadperiodnumber,loaddetail.ddate,loaddetail.routecode ORDER BY ",order_by," ", 
	order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	PREPARE s2 FROM @dyn_sql;
	EXECUTE s2;    
    
    
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_inventory_transaction_dailysalesmanloadgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_transaction_dailysalesmanloadgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_transaction_dailysalesmanloadgrid`(
	IN rwcnt INT,	
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT,
	IN var_ddate VARCHAR(25),
	IN var_load INT(4),
	IN var_key INT(4),
	IN var_routecode BIGINT,
	IN rtstatus INT
	)
BEGIN
	
	DECLARE extra_where TEXT;
	DECLARE to_date DATE;
	DECLARE from_date DATE;	
	
	SELECT STR_TO_DATE(var_ddate,'%d-%m-%Y') INTO to_date;
	SET extra_where = CONCAT("DATE(ddate) = '",to_date,"'");
	
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'sld.itemcode';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'sld.*';
	END IF;
	
	
	
	IF var_key = 0 AND rtstatus = 1 THEN
		SELECT DATE_SUB(to_date,INTERVAL 1 DAY) INTO from_date;
		
		SELECT `status` INTO @prevload FROM controlpanel WHERE flagid = 54;
		IF @prevload = 11 THEN 
			INSERT INTO startingloaddetail (ddate,routecode,salesmancode,loadperiodnumber,itemcode,caseprice,cases,
				units,upc,salesprice,batchnumber,expirydate,`status`,returnprice,returncaseprice,transactiondate,
				totunits,suggtotunits,rcvdtotunits,currencycode,warehouse,warehousestock,loadtime)
				(
				SELECT 	to_date,routecode,salesmancode,var_load,itemcode,caseprice,SUM(cases) AS cases,
				SUM(units) AS units,upc,salesprice,batchnumber,expirydate,`status`,returnprice,returncaseprice,transactiondate,
				totunits,suggtotunits,rcvdtotunits,currencycode,warehouse,warehousestock,CURRENT_TIME()
				
				
				FROM startingloaddetail
				WHERE ddate = from_date AND routecode = var_routecode
				GROUP BY ddate,routecode,batchnumber,expirydate,itemcode
				
				ORDER BY ddate,loadperiodnumber
			);
		END IF;
		
	END IF;
    
	SET @count_sql = CONCAT("SELECT COUNT(*) AS counter 
		FROM startingloaddetail AS sld
		LEFT JOIN itemmaster AS im ON im.actualitemcode = sld.itemcode
		WHERE ( sld.cases > 0 OR sld.units > 0 ) AND loadperiodnumber = ",var_load," AND ",extra_where , " " ,table_where);
	
    PREPARE s1 FROM @count_sql;
    
	 EXECUTE s1;	
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ,"
		FROM startingloaddetail AS sld
		LEFT JOIN itemmaster AS im ON im.actualitemcode = sld.itemcode
		WHERE ( sld.cases > 0 OR sld.units > 0 ) AND loadperiodnumber = ",var_load," AND ",extra_where , " " ,table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    
    PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;
	
	 sELECT @dyn_sql;
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_inventory_transaction_dailysalesmanload_batchinfo` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_transaction_dailysalesmanload_batchinfo` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_transaction_dailysalesmanload_batchinfo`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT,
	IN table_name VARCHAR(100)
	)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	SET order_by = 'ds.expirydate';
	SET order_type= 'ASC';
	
	IF table_fields = '' THEN
		SET table_fields = 'ds.*';
	END IF;
	
	SET @cnt_sql = CONCAT("SELECT count(*) as counter FROM ",table_name," AS ds WHERE 1=1  ",table_where);		
	PREPARE s1 FROM @cnt_sql;
	EXECUTE s1;
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM ",table_name," AS ds , itemmaster AS im
	WHERE actualitemcode = itemcode  ",table_where,  " ORDER BY ",order_by," ", 
	order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	PREPARE s2 FROM @dyn_sql;
	EXECUTE s2;
    
   
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_inventory_transaction_dailysalesmanload_load_request` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_transaction_dailysalesmanload_load_request` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_transaction_dailysalesmanload_load_request`(
	IN var_routecode BIGINT,
	IN var_itemcode BIGINT,	
	IN var_ddate VARCHAR(25),
	IN var_load INT(4)
	)
BEGIN
	DECLARE to_date DATE;
	DECLARE tran_type INT;
	DECLARE var_salesmancode BIGINT;
	DECLARE var_routekey BIGINT;
	DECLARE var_detailkey BIGINT;
	DECLARE var_tran BIGINT;
	
	
	CALL sp_get_inventory_transaction_dailysalesmanload_quantity(var_routecode,var_itemcode);
	
	
	SELECT flagid INTO tran_type FROM controlpanel WHERE flagid IN (72,60,47,34,54,15) AND `status` = 1;
	SELECT salesmancode INTO var_salesmancode FROM routemaster WHERE routecode = var_routecode;
	SELECT STR_TO_DATE(var_ddate,'%d-%m-%Y') INTO to_date;	
	
	SELECT detailkey INTO var_detailkey FROM inventorytransactionheader 
		WHERE routecode = var_routecode AND transactiontype = 4 AND requestdate = to_date;
	
	SELECT transactionkey INTO var_tran FROM salesorderheader 
		WHERE routecode = var_routecode AND orderdeliverydate = to_date AND deliverystatus = '0';
	
	IF tran_type = 47 THEN 
		SELECT 	SUM(IFNULL(FLOOR(itd.quantity/im.unitspercase),0)) AS cases,
				SUM(IFNULL((itd.quantity%im.unitspercase),0)) AS pieces
		FROM inventorytransactiondetail AS itd
		LEFT JOIN itemmaster AS im ON im.actualitemcode = itd.itemcode  
		WHERE itd.detailkey = var_detailkey AND itd.transactiontypecode = 8
		GROUP BY itd.itemcode;
	
	ELSEIF tran_type = 34 THEN 
		SELECT 	SUM(IFNULL(FLOOR(sod.salesqty/im.unitspercase),0)) AS cases,
				sum(IFNULL((sod.salesqty%im.unitspercase),0)) AS pieces
		FROM salesorderdetail AS sod
		LEFT JOIN itemmaster AS im ON im.actualitemcode = sod.itemcode  
		WHERE sod.transactionkey = var_tran	 
		GROUP BY sod.itemcode;
    END IF;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_inventory_transaction_dailysalesmanload_ordertoload` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_transaction_dailysalesmanload_ordertoload` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_transaction_dailysalesmanload_ordertoload`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT,
	IN table_where TEXT,
	IN table_name VARCHAR(100),
	IN var_routecode BIGINT,
	in var_groupby text,
	IN expdate VARCHAR(50)
	)
BEGIN
 	
 	DECLARE exp_date DATE;
 	DECLARE joining TEXT;
 	
	SELECT DATE(STR_TO_DATE(expdate,'%d-%m-%Y')) INTO exp_date;
 	
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'soh.transactionkey';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'itd.*';
	END IF;
	
	IF table_fields = '' THEN
		CALL sp_get_inventory_dailysalesmanload_qtyinfo_ordertoload(table_name,exp_date,var_routecode);
		SET joining = CONCAT("LEFT JOIN tmp_quantityinfo AS ds ON ds.depotcode = get_depotcode_routecode(soh.routecode)
		AND ds.itemcode = sod.itemcode");
	ELSE
		SET joining = '';
	END IF;
		
    
	SET @cnt_sql = CONCAT(" SELECT COUNT(cnt) AS counter FROM( SELECT 1 as cnt
		FROM salesorderdetail AS sod
		LEFT JOIN salesorderheader AS soh ON soh.transactionkey = sod.transactionkey
		LEFT JOIN itemmaster AS im ON im.actualitemcode = sod.itemcode
		",joining,"	
	  	WHERE DATE(soh.orderdeliverydate) = ",exp_date,"
	  	",table_where,  " ",var_groupby," ) AS tbl1");
	
	
	PREPARE s1 FROM @cnt_sql;
	EXECUTE s1;
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ,"
		FROM salesorderdetail AS sod
		LEFT JOIN salesorderheader AS soh ON soh.transactionkey = sod.transactionkey
		LEFT JOIN itemmaster AS im ON im.actualitemcode = sod.itemcode
		",joining,"	
	  	WHERE DATE(soh.orderdeliverydate) = ",exp_date,"
	  	",table_where,  "  ",var_groupby,"
	  	ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	
	PREPARE s2 FROM @dyn_sql;
	EXECUTE s2;    
    SELECT @dyn_sql;
        
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_inventory_transaction_dailysalesmanload_previousday` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_transaction_dailysalesmanload_previousday` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_transaction_dailysalesmanload_previousday`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT,
	IN table_where TEXT,
	in table_name varchar(100),
	in var_routecode bigint,
	in var_groupby text,
	in expdate varchar(50),
	in var_loadno int(4)
	)
BEGIN
 	declare exp_date date;
 	declare joining text;
 	
	select DATE(DATE_SUB(STR_TO_DATE(expdate,'%d-%m-%Y'),INTERVAL 1 DAY)) INTO exp_date;
	
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'sld.loaddetailcode';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'sld.*';
	END IF;
	
	if table_name != '' then
		CALL sp_get_inventory_dailysalesmanload_qtyinfo_previousday(table_name,exp_date,var_routecode,var_loadno);
		set joining = concat("LEFT JOIN tmp_quantityinfo AS ds ON ds.depotcode = get_depotcode_routecode(sld.routecode)
		AND ds.itemcode = sld.itemcode AND ds.batchno = sld.batchnumber AND ds.expirydate = sld.expirydate");
	else
		set joining = '';
	end if;
		
    
	SET @cnt_sql = CONCAT(" SELECT COUNT(cnt) AS counter FROM( SELECT 1 as cnt
	FROM startingloaddetail AS sld
	LEFT JOIN itemmaster AS im ON im.actualitemcode = sld.itemcode 
	",joining,"	
	WHERE 1=1  AND DATE(ddate) = '",exp_date,"' ",table_where,  " ",var_groupby," ) AS tbl1");
	
	
	PREPARE s1 FROM @cnt_sql;
	EXECUTE s1;
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ,"
	FROM startingloaddetail AS sld
	LEFT JOIN itemmaster AS im ON im.actualitemcode = sld.itemcode
	",joining,"	
	WHERE 1=1  AND DATE(ddate) = '",exp_date,"' ",table_where,  " ",var_groupby,"
	ORDER BY ",order_by," ", 
	order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	
	PREPARE s2 FROM @dyn_sql;
	EXECUTE s2;    
	SELECT @dyn_sql;
    
    
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_inventory_transaction_dailysalesmanload_quantity` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_transaction_dailysalesmanload_quantity` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_transaction_dailysalesmanload_quantity`(
	IN route_code BIGINT,
	IN item_code BIGINT
    )
BEGIN
		DECLARE depot_code BIGINT;
		DECLARE flag_id BIGINT;
		
		CALL sp_get_iteminfo_itemcode(item_code);
		
		SELECT flagid INTO flag_id FROM controlpanel WHERE flagid IN (14,64) AND `status` = 1;
		
		SELECT DISTINCT dm.depotcode INTO depot_code FROM routemaster rm,subareamaster sam,areamaster am,depotmaster dm,regionmaster rgm,company co
			WHERE sam.subareacode = rm.subareacode AND am.areacode = sam.areacode
				AND dm.depotcode = am.depotcode AND rgm.regionmstcode = dm.regionmstcode
				AND co.cmpycode = dm.cmpycode AND rm.routecode = route_code;
		
		IF depot_code > 0 AND flag_id =  14 THEN
			SELECT IFNULL(SUM(FLOOR(ds.quantity/im.unitspercase)),0) AS cases, IFNULL(SUM(ds.quantity%im.unitspercase),0) AS pieces
				FROM depotstock ds,itemmaster im
				WHERE im.actualitemcode = ds.itemcode AND depotcode = depot_code AND itemcode = item_code;
			
			SELECT depot_code;
		ELSEIF depot_code > 0 AND flag_id =  64 THEN
			SELECT IFNULL(SUM(FLOOR(ds.avlquantity/im.unitspercase)),0) AS cases, IFNULL(SUM(ds.avlquantity%im.unitspercase),0) AS pieces
				FROM tbldepotstock ds,itemmaster im
				WHERE im.actualitemcode = ds.itemcode AND depotcode = depot_code AND itemcode = item_code;
			
			SELECT depot_code;
		END IF;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_inventory_transaction_dailysalesmanload_requesttoload` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_transaction_dailysalesmanload_requesttoload` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_transaction_dailysalesmanload_requesttoload`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT,
	IN table_where TEXT,
	IN table_name VARCHAR(100),
	IN var_routecode BIGINT,
	in var_groupby text,
	IN expdate VARCHAR(50)
	)
BEGIN
 	
 	DECLARE exp_date DATE;
 	DECLARE joining TEXT;
 	
	SELECT DATE(STR_TO_DATE(expdate,'%d-%m-%Y')) INTO exp_date;
	
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'ith.detailkey';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'itd.*';
	END IF;
	
	IF table_name <> '' THEN		
		CALL sp_get_inventory_dailysalesmanload_qtyinfo_requesttoload(table_name,exp_date,var_routecode);
				
		SET joining = CONCAT("LEFT JOIN tmp_quantityinfo AS ds ON ds.depotcode = get_depotcode_routecode(ith.routecode)
		AND ds.itemcode = itd.itemcode");
	ELSE
		SET joining = '';
	END IF;
    
	SET @cnt_sql = CONCAT(" SELECT COUNT(cnt) AS counter FROM( SELECT 1 as cnt
		FROM inventorytransactiondetail AS itd
		LEFT JOIN inventorytransactionheader AS ith ON ith.detailkey = itd.detailkey
		LEFT JOIN itemmaster AS im ON im.actualitemcode = itd.itemcode
		",joining,"	
	  	WHERE itd.transactiontypecode=8 AND DATE(ith.transactiondate) = ",exp_date,"
	  	",table_where,  " ",var_groupby," ) AS tbl1");
	
	
	PREPARE s1 FROM @cnt_sql;
	EXECUTE s1;
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ,"
		FROM inventorytransactiondetail AS itd
		LEFT JOIN inventorytransactionheader AS ith ON ith.detailkey = itd.detailkey
		LEFT JOIN itemmaster AS im ON im.actualitemcode = itd.itemcode
		",joining,"	
	  	WHERE itd.transactiontypecode=8 AND DATE(ith.transactiondate) = ",exp_date,"
			",table_where,  "  ",var_groupby,"
			ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	
	PREPARE s2 FROM @dyn_sql;
	EXECUTE s2;    
    SELECT table_name,joining,@dyn_sql;
        
END */$$
DELIMITER ;

