/* Procedure structure for procedure `sp_get_inventory_transaction_deliveryloadgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_transaction_deliveryloadgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_transaction_deliveryloadgrid`(
	IN rwcnt INT,	
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 
	IN var_loadno INT(4)
	
	)
BEGIN
	
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'sld.itemcode';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'sld.*';
	END IF;
    
	SET @count_sql = CONCAT("SELECT COUNT(*) AS counter 
		FROM deliverydetail AS sld
		LEFT JOIN itemmaster AS im ON im.actualitemcode = sld.itemcode
		WHERE deliveryno = ",var_loadno,"");
	
    PREPARE s1 FROM @count_sql;	
	EXECUTE s1;	
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ,"
		FROM deliverydetail AS sld
		LEFT JOIN itemmaster AS im ON im.actualitemcode = sld.itemcode
		WHERE deliveryno = ",var_loadno," ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    
    PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;
	
END */$$
DELIMITER ;

