/* Procedure structure for procedure `sp_get_inventory_transaction_getrouteinfo` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_transaction_getrouteinfo` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_transaction_getrouteinfo`(
	IN route_id INT,
	IN var_ddate VARCHAR(20),
	IN tran_method INT
	)
BEGIN
	DECLARE prev_date DATE;
	DECLARE loadno INT;
    
	SELECT routemaster.salesmancode, salesmanname1, vehiclenumber, IFNULL(MAX(loadperiodnumber),0) AS loadperiodnumber
	FROM routemaster 
		LEFT JOIN salesman ON salesman.salesmancode = routemaster.salesmancode
		LEFT JOIN startingloaddetail AS sld ON sld.routecode = routemaster.routecode AND DATE(ddate) = DATE(STR_TO_DATE(var_ddate,"%d-%m-%Y"))
	WHERE routemaster.routecode = route_id  
	GROUP BY sld.routecode,sld.ddate;
    
	CALL sp_get_items_routeitemgroupcode(route_id);
	SELECT get_depotcode_routecode(route_id) AS depot_code; 
    
	SELECT (IFNULL(MAX(loadperiodnumber),0)+1) INTO loadno
	FROM startingloaddetail 
	WHERE routecode = route_id AND DATE(ddate) = DATE(STR_TO_DATE(var_ddate,"%d-%m-%Y"));
    
	IF tran_method = 4 THEN
		SELECT DATE_SUB(DATE(STR_TO_DATE(var_ddate,"%d-%m-%Y")),INTERVAL 1 DAY) INTO prev_date;
		
		SELECT IFNULL(COUNT(*),0) AS counter 
		FROM startingloaddetail 
		WHERE DATE(ddate) = prev_date AND routecode = route_id AND loadperiodnumber = loadno;
		
	ELSEIF tran_method = 3 THEN		
		SELECT IFNULL(COUNT(*),0) AS counter 
		FROM salesorderheader 
		WHERE DATE(orderdeliverydate) = STR_TO_DATE(var_ddate,"%d-%m-%Y") AND routecode = route_id;
			
	ELSEIF tran_method = 2 THEN
		SELECT IFNULL(COUNT(*),0) AS counter 
		FROM inventorytransactionheader
		WHERE transactiontype = 4 AND DATE(requestdate) = STR_TO_DATE(var_ddate,"%d-%m-%Y");
		
	ELSEIF tran_method = 5 THEN
		SELECT IFNULL(COUNT(*),0) AS counter FROM suggestedsalesinvoice 
		WHERE DATE(transactiondate) = STR_TO_DATE(var_ddate,"%d-%m-%Y");
		
	END IF;	
	CALL sp_combo_customermaster_sequence(route_id);
    END */$$
DELIMITER ;

