DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_transaction_headerdeliveryload`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT 		)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'deliveryno';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'loaddetail.*';
	END IF;
	
	IF table_where = '' THEN
		SET table_where = ' AND ddate  = DATE(CURRENT_DATE()) ';
	END IF;
    
	SET @cnt_sql = CONCAT("SELECT COUNT(cnt) AS counter FROM 
		(
			SELECT 1 AS cnt 
			FROM deliveryheader AS loaddetail 
			LEFT JOIN salesman	ON loaddetail.drivercode = salesman.salesmancode
			LEFT JOIN routemaster as rm on rm.routecode = loaddetail.deliveryroute
			LEFT JOIN customermaster as cm on cm.customercode = loaddetail.customercode
			WHERE 1=1  ",table_where,  " 
		) AS tbl");
	
	
	PREPARE s1 FROM @cnt_sql;
	EXECUTE s1;
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ,"
	FROM deliveryheader AS loaddetail 
	LEFT JOIN salesman	ON loaddetail.drivercode = salesman.salesmancode
	LEFT JOIN routemaster as rm on rm.routecode = loaddetail.deliveryroute
	LEFT JOIN customermaster as cm on cm.customercode = loaddetail.customercode
	WHERE 1=1  ",table_where,  " ORDER BY ",order_by," ", 
	order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	PREPARE s2 FROM @dyn_sql;
	EXECUTE s2;    
    
    
END */$$
