/* Procedure structure for procedure `sp_get_links_route_activenonactiveitem` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_links_route_activenonactiveitem` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_links_route_activenonactiveitem`( IN itemgrpcode BIGINT(18))
BEGIN
	
	SELECT `status` INTO @st FROM controlpanel WHERE flagname = 'Use Alternate Code';	
	
	
	if itemgrpcode > 0 then
		IF @st = 1 THEN	
			SELECT actualitemcode AS id, CONCAT(alternatecode,' -- ',itemshortdescription) AS val FROM itemmaster WHERE itemgroupcode = itemgrpcode;	
			SELECT actualitemcode AS id, CONCAT(alternatecode,' -- ',itemshortdescription) AS val FROM itemmaster WHERE itemgroupcode = itemgrpcode anD activeitem = '0';	
		else
			SELECT actualitemcode AS id, CONCAT(actualitemcode,' -- ',itemshortdescription) AS val FROM itemmaster WHERE itemgroupcode = itemgrpcode;	
			SELECT actualitemcode AS id, CONCAT(actualitemcode,' -- ',itemshortdescription) AS val FROM itemmaster WHERE itemgroupcode = itemgrpcode AND activeitem = '0';
		end if;
		
		SELECT actualitemcode FROM itemmaster WHERE itemgroupcode = itemgrpcode AND activeitem = '0';
	else
		IF @st = 1 THEN	
			SELECT actualitemcode AS id, CONCAT(alternatecode,' -- ',itemshortdescription) AS val FROM itemmaster;
			SELECT actualitemcode AS id, CONCAT(alternatecode,' -- ',itemshortdescription) AS val FROM itemmaster WHERE activeitem = '0';
		else
			SELECT actualitemcode AS id, CONCAT(actualitemcode,' -- ',itemshortdescription) AS val FROM itemmaster;
			SELECT actualitemcode AS id, CONCAT(actualitemcode,' -- ',itemshortdescription) AS val FROM itemmaster WHERE activeitem = '0';
		end if;
		SELECT actualitemcode FROM itemmaster WHERE activeitem = '0';
	end if;
	
END */$$
DELIMITER ;

