/* Procedure structure for procedure `sp_get_loadrequest` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_loadrequest` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_loadrequest`(
in var_requestdate date    
    )
BEGIN
	 
       SELECT rm.division as ORG_CODE,rm.warehouse as TO_SUBINV_CODE,im.alternatecode as ITEMCODE,im.upccasecode as UOM_CODE,id.quantity/im.unitspercase as QUANTITY,ih.documentnumber as HHTReference,DATE_FORMAT(ih.requestdate,'%Y-%m-%d') as DateRequired  FROM inventorytransactionheader ih 
INNER JOIN inventorytransactiondetail id ON ih.detailkey=id.detailkey AND id.transactiontypecode=8
INNER JOIN routemaster rm ON rm.routecode=ih.routecode
INNER JOIN itemmaster im ON im.actualitemcode=id.itemcode
 WHERE ih.transactiontype=4  and ih.requestdate=var_requestdate and ih.EG_LR_APPROVED = 1;
    END */$$
DELIMITER ;

