/* Procedure structure for procedure `sp_get_merchandize_index_addsurvey` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_merchandize_index_addsurvey` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_merchandize_index_addsurvey`(IN id BIGINT)
BEGIN
	
	if id > 0 then
	
		select * from customersurveydefinition where surveydefkey = id;
	
	else
	
		-- call sp_get_table_last_id('customersurveydefinition'); -- commented by Aswin because Auto Increment Key is not working.
		SELECT MAX(surveydefkey) + 1 as Auto_increment from customersurveydefinition;
	
	end if;
	
	call sp_combo_survey_looktype();	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_merchandize_index_addsurveykey` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_merchandize_index_addsurveykey` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_merchandize_index_addsurveykey`(IN id BIGINT)
BEGIN
	
	if id > 0 then
	
		select * from customersurveykey where surveykey = id;
	
	else
	
		-- call sp_get_table_last_id('customersurveykey'); -- commented by Aswin because Auto Increment is not working
		select max(surveykey) + 1 as Auto_increment from customersurveykey;
	
	end if;
	
	select count(*) as counter from customersurveyplan;
	
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_merchandize_index_addsurveyplan` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_merchandize_index_addsurveyplan` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_merchandize_index_addsurveyplan`(IN id BIGINT)
BEGIN
	
	
	CALL sp_combo_surveydefinition();	
	
	if id > 0 then
	
		select * from customersurveyplan where surveyplankey = id;
		SELECT def.surveydefkey AS id,concat(def.surveydefkey, ' -- ',surveyprompt)  AS val FROM customersurveydefassign AS que 
			LEFT JOIN customersurveydefinition AS def ON def.surveydefkey = que.surveydefkey
			where surveyplankey = id;
	
	else
	
		-- call sp_get_table_last_id('customersurveyplan'); -- commented by Aswin because Auto Increment is not working.
		select max(surveyplankey) + 1 as Auto_increment from customersurveyplan;
	
	end if;
	
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_merchandize_index_customerimages` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_merchandize_index_customerimages` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_merchandize_index_customerimages`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500),
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT,
	IN table_where TEXT,
	in var_routecode bigint(28)
    )
BEGIN
		IF lmt_strt = '' THEN
			SET lmt_strt=0;
		END IF;
		IF lmt_end = '' THEN
			SET lmt_end=10;
		END IF;
		IF order_by = '' THEN
			SET order_by = 'customercode';
		END IF;
		IF order_type = '' THEN
			SET order_type= 'DESC';
		END IF;
		IF table_fields = '' THEN
			SET table_fields = 'ci.*';
		END IF;
		
		if var_routecode = '' then
			set var_routecode = 0;
		end if;
				
		SET @cnt_sql = CONCAT("SELECT COUNT(DISTINCT ci.customercode) AS counter from customeroperationscontrol AS ci
		INNER JOIN customerimages AS cim ON cim.customercode = ci.customercode
		LEFT JOIN customermaster AS c ON c.customercode = ci.customercode
		WHERE ci.customercode IN(SELECT DISTINCT customercode FROM routesequence WHERE routecode IN(",var_routecode,"))
		",table_where);
	 	PREPARE s1 FROM @cnt_sql;
	 	EXECUTE s1;
	 	
		
		SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM customeroperationscontrol AS ci
		INNER JOIN customerimages AS cim ON cim.customercode = ci.customercode
		LEFT JOIN customermaster AS c ON c.customercode = ci.customercode
		WHERE ci.customercode IN(SELECT DISTINCT customercode FROM routesequence WHERE routecode IN(",var_routecode,"))
		",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	 	PREPARE s2 FROM @dyn_sql;
	 	 EXECUTE s2;
	 	
		CALL sp_combo_routemaster();
		
		 select @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_merchandize_index_customerimagesdatabyid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_merchandize_index_customerimagesdatabyid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_merchandize_index_customerimagesdatabyid`(
	IN var_customercode INT,
	IN var_ddate text
    )
BEGIN
	SET @cnt_sql = CONCAT("SELECT DISTINCT imagename FROM customerimages WHERE customercode =", var_customercode," AND ",var_ddate); 
	PREPARE s1 FROM @cnt_sql;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
        EXECUTE s1; 
       
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_merchandize_index_lookupindexgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_merchandize_index_lookupindexgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_merchandize_index_lookupindexgrid`(
	IN rwcnt INT,
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	IF order_by = '' THEN
		SET order_by = 'primary_key';
	END IF;
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	IF table_fields = '' THEN
		SET table_fields = 'look.*';
	END IF;
	
	SET @dyn_cnt = CONCAT("SELECT COUNT(*) AS counter FROM lookupindexdetail AS look 
	WHERE 1=1 ",table_where);
	
	PREPARE s1 FROM @dyn_cnt;
	
	EXECUTE s1;
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM lookupindexdetail AS look 
	WHERE 1=1 ",table_where,  " ORDER BY ",order_by," ", 
	order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	PREPARE s2 FROM @dyn_sql;
	
	EXECUTE s2;
	
END */$$
DELIMITER ;

