/* Procedure structure for procedure `sp_get_ordertransaction_salesorderadd_invoicesummery` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_ordertransaction_salesorderadd_invoicesummery` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_ordertransaction_salesorderadd_invoicesummery`(
IN in_route_key INT,
IN in_transaction_key INT
)
BEGIN
	declare var_discount 	  decimal(18,4);
	DECLARE var_totaldiscount DECIMAL(18,4);
	
		SELECT primary_key AS edit_del_primary_id,
		im.actualitemcode,
		im.itemshortdescription,
		
		FLOOR((salesqty/im.unitspercase)) AS case_order_qty,
		(salesqty%im.unitspercase) AS pcs_order_qty,
		IFNULL(FLOOR((manualfreeqty/im.unitspercase)),0) AS case_free_qty,
		IFNULL((manualfreeqty%im.unitspercase),0) AS pcs_free_qty,
		FLOOR((returnqty/im.unitspercase)) AS case_return_qty,
		(returnqty%im.unitspercase) AS pcs_return_qty,
		FLOOR((damagedqty/im.unitspercase)) AS case_damage_qty,
		(damagedqty%im.unitspercase) AS pcs_damage_qty,
		promoamount AS discount,
		FLOOR((freesampleqty/im.unitspercase)) AS case_promo_free_qty,
		(freesampleqty%im.unitspercase) AS pcs_promo_free_qty
	
		
	FROM salesorderdetail_temp AS id 
	LEFT JOIN itemmaster AS im ON im.actualitemcode = id.itemcode
	WHERE 1=1 
	
	AND routekey =in_route_key
	AND transactionkey=in_transaction_key;
	
	SELECT FORMAT(IFNULL(SUM(promotiondetail_temp.promotionamount),0),2) AS totaldiscount FROM promotiondetail_temp 
	WHERE transactionkey=in_transaction_key AND routekey =in_route_key and
	itemtransactiontype = 4 ;
	
    
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_ordertransaction_salesorderadd_promotion_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_ordertransaction_salesorderadd_promotion_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_ordertransaction_salesorderadd_promotion_detail`(
IN in_plannumber INT
)
BEGIN
SELECT key1.plannumber,key1.assignmentnumber,key1.assignmentgroup, 
	key1.promotiontypecode,key1.qualificationgroup,
	key1.rangebasis,
	promotionassignmentadvanced.rangelow,  promotionassignmentadvanced.rangehigh,
	promotionassignmentadvanced.promotionamount ,  promoplandetail.plandescription,
	DATE_FORMAT(key1.startdate,"%d-%m-%Y")AS startdate, DATE_FORMAT(key1.enddate,'%d-%m-%Y') AS enddate
FROM promokeydetail AS key1  
LEFT JOIN promoplandetail ON  promoplandetail.plannumber = key1.plannumber
LEFT JOIN promotionassignmentadvanced ON  promotionassignmentadvanced.plannumber =key1.plannumber
AND promotionassignmentadvanced.assignmentnumber = key1.assignmentnumber
WHERE key1.plannumber=in_plannumber;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_ordertransaction_salesorderadd_promotion_plan` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_ordertransaction_salesorderadd_promotion_plan` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_ordertransaction_salesorderadd_promotion_plan`(
	IN in_customer_code BIGINT,
	IN in_visitkey INT,
	IN in_routekey INT    
    )
BEGIN
DECLARE in_pricingkey BIGINT;
	SELECT promotionkey INTO in_pricingkey  FROM customermaster WHERE customercode = in_customer_code;	
	
	SELECT 	promoplandetail.plannumber, promoplandetail.plandescription,promokeydetail.primary_key
	,promoplandetail.assignmentnumber,promokeydetail.rangebasis,promokeydetail.promotionkey,
	promokeydetail.promotiontypecode,promokeydetail.qualificationgroup,promokeydetail.assignmentgroup,
	
	(SELECT IF(COUNT(*) > 0, 1, 0)  FROM salesorderdetail_temp , productgroupdetail 
	WHERE   salesorderdetail_temp.itemcode = productgroupdetail.itemcode 
	AND salesorderdetail_temp.routekey = in_routekey AND salesorderdetail_temp.visitkey = in_visitkey
	AND 
		IF(promokeydetail.qualificationgroup = 1 , '1=1 group by salesorderdetail_temp.itemcode' ,productgroupdetail.groupnumber = promokeydetail.qualificationgroup)
			 ) AS qualified_promotion
	
	FROM promokeydetail
	LEFT JOIN promoplandetail ON promoplandetail.plannumber = promokeydetail.plannumber
	WHERE 	promokeydetail.promotionkey =in_pricingkey;
	
	
	
	SELECT (
		(SELECT IF(COUNT(*) > 0, 1, 0)  FROM salesorderdetail_temp , productgroupdetail 
		WHERE   salesorderdetail_temp.itemcode = productgroupdetail.itemcode 
		AND salesorderdetail_temp.routekey = in_routekey AND salesorderdetail_temp.visitkey = in_visitkey
		AND 
		IF(promokeydetail.qualificationgroup = 1 , '1=1 group by salesorderdetail_temp.itemcode' ,productgroupdetail.groupnumber = promokeydetail.qualificationgroup)
		)) AS qualified_promotion
	
	FROM promokeydetail
	LEFT JOIN promoplandetail ON promoplandetail.plannumber = promokeydetail.plannumber
	WHERE 
	 	promokeydetail.promotionkey =in_pricingkey
		GROUP BY qualified_promotion;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_ordertransaction_salesorderadd_promotion_review` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_ordertransaction_salesorderadd_promotion_review` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_ordertransaction_salesorderadd_promotion_review`(
IN in_visitkey INT,
IN in_routekey INT,
IN in_transaction_key INT,
IN in_customer_code INT
)
BEGIN
DECLARE total_amount DECIMAL(18,4);
DECLARE in_qualification_group VARCHAR(255);
		
		
		SELECT  REPLACE(FORMAT(SUM((((FLOOR(salesqty/im.unitspercase)*id.salescaseprice)+
		((salesqty%im.unitspercase)*id.salesprice))-((FLOOR(returnqty/im.unitspercase)* id.goodreturncaseprice)+
		((returnqty%im.unitspercase)*id.goodreturnprice))-((FLOOR(damagedqty/im.unitspercase)*im.returncaseprice)+
		((damagedqty%im.unitspercase)*id.returnprice)))),2),",","") AS SalesAmount
		INTO total_amount
		
		
		FROM salesorderdetail_temp AS id
		INNER JOIN itemmaster  AS im ON im.actualitemcode  = id.itemcode
							   
		WHERE 	 id.routekey =in_routekey
		AND id.visitkey  =in_visitkey;
		
    
		
		
		
		SELECT promotiontypecode,total_amount,promotionamount,
		(total_amount - promotionamount) AS new_invoice_amount ,promotiondetail_temp.promotionplannumber
		
		 FROM promotiondetail_temp  
		WHERE promotiondetail_temp.routekey =in_routekey
			AND promotiondetail_temp.visitkey=in_visitkey  
			AND promotiondetail_temp.transactionkey =in_transaction_key
			AND promotiondetail_temp.itemtransactiontype = 4
		GROUP BY promotiontypecode,promotiondetail_temp.promotionplannumber;
		
		SELECT promotiondetail_temp.*,promoplandetail.plandescription ,
		IF(promotiondetail_temp.promotiontypecode = 1 OR promotiondetail_temp.promotiontypecode = 2 OR promotiondetail_temp.promotiontypecode  = 0 ,get_item_description(promotiondetail_temp.itemcode),"") AS item_desc,
		get_item_code(promotiondetail_temp.itemcode) AS new_item_code
		FROM promotiondetail_temp  ,promoplandetail
		WHERE promoplandetail.plannumber =  promotiondetail_temp.promotionplannumber
		AND promotiondetail_temp.routekey =in_routekey
			AND promotiondetail_temp.visitkey=in_visitkey  
			AND promotiondetail_temp.transactionkey =in_transaction_key
			AND promotiondetail_temp.itemtransactiontype = 4			
		ORDER BY promotiontypecode;
		
		
		
		
		SET @del1 = CONCAT("
				SELECT 
					salesorderdetail_temp.salesqty AS case_sales_qty,
					itemmaster.unitspercase AS pcs_sales_qty,
					salesorderdetail_temp.itemcode,	itemmaster.itemshortdescription	,
					itemmaster.actualitemcode as itemcode,
					get_item_code(itemmaster.actualitemcode) AS new_item_code,
					4 as itemtransactiontype ,promotiondetail_temp.promotionplannumber,promokeydetail.rangebasis
				FROM promokeydetail 
				INNER JOIN promotiondetail_temp 
				ON promotiondetail_temp.promotionplannumber=promokeydetail.plannumber 
				AND promotiondetail_temp.promotiontypecode = 7
				AND promotiondetail_temp.visitkey= ",in_visitkey,"
				AND promotiondetail_temp.routekey = ",in_routekey," 
				LEFT JOIN salesorderdetail_temp ON FIND_IN_SET(salesorderdetail_temp.itemcode,promotiondetail_temp.itemcode)
				 AND salesorderdetail_temp.routekey = ",in_routekey,"
				  AND salesorderdetail_temp.visitkey  = ",in_visitkey,"
				  
				 --  AND FIND_IN_SET(salesorderdetail_temp.itemcode,promotiondetail_temp.itemcode)
				 JOIN itemmaster 
				ON itemmaster.actualitemcode IN (promotiondetail_temp.itemcode)
				 WHERE promokeydetail.promotionkey = (SELECT promotionkey 
									FROM customermaster
									 WHERE customercode = ",in_customer_code,")
				AND itemtransactiontype= 4
				AND promotiondetail_temp.promotiontypecode = 7");
	   
	   PREPARE s1 FROM @del1;
	   EXECUTE s1;
	   
	   
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_ordertransaction_salesorderadd_salesorderdetailgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_ordertransaction_salesorderadd_salesorderdetailgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_ordertransaction_salesorderadd_salesorderdetailgrid`(
	IN rwcnt INT,	
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT,
	IN tran_key BIGINT 
	
	)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'primary_key';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'ih.*';
	END IF;
	
	SELECT routekey INTO @routekey FROM salesorderheader_temp WHERE transactionkey =  tran_key;
	    
	SET @dyn_cnt = CONCAT("SELECT COUNT(primary_key) AS counter FROM salesorderdetail_temp AS id 
	LEFT JOIN itemmaster AS im ON im.actualitemcode = id.itemcode
	WHERE 1=1 AND routekey = @routekey AND transactionkey = ",tran_key," ",table_where);
    PREPARE s1 FROM @dyn_cnt;
	EXECUTE s1;	
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM salesorderdetail_temp AS id 
	LEFT JOIN itemmaster AS im ON im.actualitemcode = id.itemcode
	WHERE 1=1 AND routekey = @routekey AND transactionkey = ",tran_key," ",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	
		
    PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;	
	
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_ordertransaction_salesorderadd_settings` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_ordertransaction_salesorderadd_settings` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_ordertransaction_salesorderadd_settings`(
IN in_customer_code INT
)
BEGIN
	SELECT IFNULL(enablesigcapture,0) AS 'Enable_Signature_Capture' , 
		IFNULL(enablereturnstrxn,0) AS 'Enable_Good_Returns', 
		IFNULL(enablepromotrxn,0) AS 'Enable_Free', 
		IFNULL(enablerental,0) AS 'Enable_Rental', 
		IFNULL(enablesalestrxn,0) AS 'Enable_Sales', 
		IFNULL(enabledamagedreturns,0) AS 'Enable_Damage_Returns', 
		IFNULL(enableinvoicecomment,0) AS 'Enable_invoice_comment', 
		IFNULL(enablebuybackfree,0) AS 'Enable_Buy_Back_Free', 
		IFNULL(enablepromoeditinvs,0) AS 'Enable_Sales_Promotion',
		IFNULL(enablepromoeditords,0) AS 'Enable_Order_Promotion',
		IFNULL(enforcepromotion,0) AS  'enforcepromotion',
		invoicepaymentterms AS 'invoice_paynent_terms',
		creditlimit AS 'customer_credit_limit',
		enablepriceeditinvs AS 'Enable_Edit_Price_Invs',
		CASE invoicepaymentterms 
			WHEN 0 THEN 'CASH Only'
		        WHEN 1 THEN 'CASH or CHEQUE' 
		        WHEN 2 THEN 'CHARGE Only (GC)' 
		        WHEN 3 THEN 'TC (CASH or CHEQUE)' 
		        WHEN 4 THEN 'TC (CASH Only)' 
		 ELSE 'CASH Only' END AS invoice_paynent_terms_text,
		  creditlimitdays AS customer_credit_day,
		   CONCAT(customeraddress1," ", customeraddress2) AS customer_address,
		    allowcashoncreditexceed AS 'Allow_Cash_If_Credit_Exceeds'
	FROM customermaster
		WHERE customercode =in_customer_code;
    
END */$$
DELIMITER ;

