/* Procedure structure for procedure `sp_get_organization_index_addvan` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_organization_index_addvan` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_organization_index_addvan`(
		IN id BIGINT
	    
	)
BEGIN
	IF id > 0 THEN 	
		SELECT * FROM vanmaster WHERE vancode = id;
	ELSE
