/* Procedure structure for procedure `sp_get_organization_index_area` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_organization_index_area` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_organization_index_area`(
	IN rwcnt INT,			
	IN srchvalue VARCHAR(500), 	
	IN order_by VARCHAR(500),	
	IN order_type VARCHAR(10),	
	IN lmt_strt INT,		
	IN lmt_end INT, 			
	IN table_fields TEXT, 			
	IN table_where TEXT 
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'area.areacode';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	SET order_type= 'ASC';
    
	SET @dyn_cnt = CONCAT("SELECT COUNT(area.areacode) AS counter FROM areamaster AS area	
	LEFT JOIN areamanager AS am ON area.areamanagercode  = am.areamanagercode
	LEFT JOIN depotmaster AS depot ON area.DepotCode = depot.DepotCode 
	WHERE 1=1 ",table_where);
	
	PREPARE s1 FROM @dyn_cnt;
	EXECUTE s1;	
    
	SET @dyn_sql = CONCAT("SELECT ",table_fields," FROM areamaster AS area
	LEFT JOIN areamanager AS am ON area.areamanagercode  = am.areamanagercode
	LEFT JOIN depotmaster AS depot ON area.DepotCode = depot.DepotCode 
	 WHERE 1=1 ", table_where,
	" ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end);
    
    
    
	PREPARE s2 FROM @dyn_sql;
	EXECUTE s2;	
END */$$
DELIMITER ;

