/* Procedure structure for procedure `sp_get_organization_route_addroute` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_organization_route_addroute` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_organization_route_addroute`(IN id BIGINT)
BEGIN
	
	SELECT * FROM routemaster WHERE  `routecode` = id;
		
	
	CALL sp_combo_regionmaster();
		
	
	CALL sp_combo_subareamaster();
	
	
	CALL sp_get_salesman('ROUTE',id);
	
	
	CALL sp_combo_company();
	
	CALL sp_combo_vanmaster();
	
	CALL sp_combo_routecategory();
	
	CALL sp_combo_routeitemgrp();
	
	
	SELECT routecode AS id,templatename AS val FROM routemaster WHERE routetmpl	= 1;
	
	
	CALL sp_combo_currency();
	
	CALL sp_combo_customermaster();
	
	CALL sp_combo_itemmust();
	
	SELECT `status` FROM controlpanel WHERE flagid IN (3,57,74,79);
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_organization_route_addroutetmpl` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_organization_route_addroutetmpl` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_organization_route_addroutetmpl`(IN id BIGINT)
BEGIN
	IF id > 0 THEN
		
		SELECT * FROM routemaster WHERE  routecode = id AND routetmpl	= 1;
	ELSE
		SELECT 1;	
	END IF;
	
	SELECT routecode AS id,routecode AS val FROM routemaster WHERE routetmpl	= 1;
	
	
	CALL sp_combo_routeitemgrp();
	
	
	CALL sp_combo_currency();
	
	
	CALL sp_combo_routecategory();
	
	CALL sp_combo_itemmust();
	
	SELECT `status` FROM controlpanel WHERE flagid IN (3,57,74,79);
	
END */$$
DELIMITER ;

