/* Procedure structure for procedure `sp_get_organization_route_route` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_organization_route_route` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_organization_route_route`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT 		)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'route.routecode';
	END IF;
	
	SET order_type = ' ASC ';
	
	
	
	
	
	IF table_fields = '' THEN
		SET table_fields = 'cnt.*';
	END IF;
    
	SET @count_sql = CONCAT("SELECT COUNT(*) AS counter 
		FROM  usermaster as um 
		INNER JOIN (SELECT DISTINCT cmpycode, username FROM useraccesscodes) as uac ON uac.username= um.username
		INNER JOIN routemaster as route ON route.cmpycode = uac.cmpycode
		LEFT JOIN salesman ON route.salesmancode = salesman.salesmancode
		LEFT JOIN subareamaster AS subarea ON route.subareacode = subarea.subareacode
		WHERE 1=1 AND routetmpl = 0 ",table_where);
    PREPARE s1 FROM @count_sql;	
	EXECUTE s1;	
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ,"
		FROM  usermaster as um 
		INNER JOIN (SELECT DISTINCT cmpycode, username FROM useraccesscodes) as uac ON uac.username= um.username
		INNER JOIN routemaster as route ON route.cmpycode = uac.cmpycode
		LEFT JOIN salesman ON route.salesmancode = salesman.salesmancode
		LEFT JOIN subareamaster AS subarea ON route.subareacode = subarea.subareacode
		WHERE 1=1 AND routetmpl = 0 ",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    
    --  select @dyn_sql;
    PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;	
END */$$
DELIMITER ;

