/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_promotions_advance_addpromotionkey` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_promotions_advance_addpromotionkey`(IN id BIGINT)
BEGIN
	SELECT
		`promotionkey`,
		`description`,
		`arbdescription`,
		`activeindicator`,
		`type`
	FROM 
		promokeyheader
	WHERE promotionkey= id;
END */$$
