/* Procedure structure for procedure `sp_get_promotions_advance_addpromotionplan` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_promotions_advance_addpromotionplan` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_promotions_advance_addpromotionplan`(IN id BIGINT)
BEGIN
	if id > 0 then 
		SELECT
		
			pd.plannumber AS plannumber, 
			pd.qualificationgroup AS qualificationgroup, 
			pd.assignmentgroup AS assignmentgroup, 
			pd.rangebasis AS rangebasis, 
			pd.amountbasis AS amountbasis, 
			pd.exclusionoption AS exclusionoption, 
			pd.assignmentnumber AS assignmentnumber, 
			pd.plandescription AS plandescription, 
			pd.arbplandescription AS arbplandescription, 
			pd.promotiontypecode AS promotiontypecode, 
			pd.iscase AS iscase,
			pd.onetimeuse AS onetimeuse,
			pd.enforcepromotion AS enforcepromotion,
			ph.activeindicator AS activeindicator,
			repeatrange
		FROM 
			promoplandetail pd
		LEFT JOIN
			promoplanheader ph ON pd.plannumber = ph.plannumber
		
		WHERE pd.plannumber = id;
		
	else
		
		-- Aswin commented due to builtin auto increment key not working		
		-- call sp_get_table_last_id('promoplandetail');
		SELECT MAX(plannumber) + 1 as Auto_increment FROM promoplandetail;
			
	end if;
	
	call sp_combo_assignmentgroup();
	call sp_combo_qualificationgroup();
END */$$
DELIMITER ;

