/* Procedure structure for procedure `sp_get_promotions_discount_adddiscountkey` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_promotions_discount_adddiscountkey` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_promotions_discount_adddiscountkey`(in id bigint)
BEGIN
	
	CALL sp_combo_itemmaster;
	IF id > 0  THEN
		SELECT discountkey,description,arbdescription,DATE_FORMAT(startdate,"%d/%m/%Y") AS startdate,DATE_FORMAT(enddate,"%d/%m/%Y") AS enddate, active FROM discountkeyheader WHERE  `discountkey` = id;
	else
		call sp_get_table_last_id('discountkeyheader');
	END IF;
	
END */$$
