	PREPARE s1 FROM @dyn_cnt;
	EXECUTE s1;
		
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM loyaltyplanheader AS p WHERE 1=1   ",table_where,  " ORDER BY ",order_by," ", 
		order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	
	PREPARE s2 FROM @dyn_sql;
	EXECUTE s2;
	
END */$$
DELIMITER ;

