/* Procedure structure for procedure `sp_get_receipts` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_receipts` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_receipts`(
IN  var_transactiondate DATE)
BEGIN
DECLARE var_invoicenumber BIGINT;
  
TRUNCATE TABLE TEMPRECEIPTSORACLE1; -- TEMPRECEIPTSORACLE;
INSERT INTO TEMPRECEIPTSORACLE1 -- TEMPRECEIPTSORACLE
SELECT cm.divisioncode AS DIVISON,
	cm.alternatecode AS 	CUSTOMER_NUMBER	,
	ad.alternateinvoicenumber AS INVOICE_NUMBER,
	ad.TotalInvoiceAmount AS 	INVOICE_AMOUNT,
	ad.amountpaid AS 	RECEIPT_AMOUNT,
	CASE WHEN chequecollection=1 THEN 'CHEQUE' ELSE 'CASH' END AS 	PAYMENT_MODE	,
	ah.invoicenumber AS RECEIPT_NUMBER	,
	ccd.checknumber AS CHECK_NUMBER,
	CASE WHEN chequecollection=1 THEN var_transactiondate ELSE DATE_FORMAT(ah.transactiondate,'%Y-%m-%d') END AS 	RECEIPT_DATE,
	ah.comments AS COMMENTS ,
	RM.ARBROUTENAME,
	ccd.checkdate,IFNULL(BM.BANKNAME,''),
	CASE WHEN ad.deductionamount = 0 THEN '' ELSE ad.deductionamount END AS deductionamount
FROM 
	Arheader ah 
	INNER JOIN ardetail ad ON ah.transactionkey=ad.transactionkey AND ah.routekey=ad.routekey AND ah.visitkey=ad.visitkey
	INNER JOIN customermaster cm ON cm.customercode=ah.customercode
	INNER JOIN Routemaster rm ON rm.routecode=ah.routecode
	INNER JOIN view_cash_chk_detl ccd ON ccd.routekey=ah.routekey AND ccd.visitkey=ah.visitkey AND  ccd.hhctransactionkey=ah.hhctransactionkey AND ccd.routekey=ah.routekey
	LEFT OUTER JOIN BANKMASTER BM ON BM.BANKCODE=CCD.BANKCODE
WHERE ah.invoicenumber IN( SELECT invoicenumber FROM Arheader ah INNER JOIN cashcheckdetail ccd ON ccd.routekey=ah.routekey AND ccd.visitkey=ah.visitkey AND  ccd.hhctransactionkey=ah.hhctransactionkey
				AND ccd.routekey=ah.routekey WHERE 
				 CASE WHEN chequecollection=1 THEN ccd.checkdate=var_transactiondate ELSE 
				transactiondate=var_transactiondate 
				 END
			);
	
 
 INSERT INTO TEMPRECEIPTSORACLE1 -- TEMPRECEIPTSORACLE    
     SELECT 
	cm.divisioncode AS DIVISON,
	cm.alternatecode AS 	CUSTOMER_NUMBER	,
	ah.invoicenumber AS INVOICE_NUMBER,
	ah.TotalInvoiceAmount AS 	INVOICE_AMOUNT,
	ah.immediatepaid AS 	RECEIPT_AMOUNT,
	CASE WHEN ccd.checknumber>0 THEN 'CHEQUE' ELSE 'CASH' END AS 	PAYMENT_MODE	,
	ah.invoicenumber AS RECEIPT_NUMBER	,
	ccd.checknumber AS CHECK_NUMBER,
	CASE WHEN ccd.checknumber>0 THEN var_transactiondate ELSE DATE_FORMAT(ah.transactiondate,'%Y-%m-%d') END AS 	RECEIPT_DATE,
	ah.comments AS COMMENTS ,
	RM.ARBROUTENAME,ccd.checkdate,
	IFNULL(BM.BANKNAME,'')	, 
	'' 
FROM 
	InvoiceHeader ah 
	INNER JOIN customermaster cm ON cm.customercode=ah.customercode
	INNER JOIN Routemaster rm ON rm.routecode=ah.routecode
	INNER JOIN (SELECT DISTINCT * FROM  cashcheckdetail) ccd ON ccd.routekey=ah.routekey AND ccd.visitkey=ah.visitkey AND  ccd.hhctransactionkey=ah.hhctransactionkey AND ah.immediatepaid>0
	LEFT OUTER JOIN BANKMASTER BM ON BM.BANKCODE=CCD.BANKCODE
WHERE ah.invoicenumber IN (SELECT invoicenumber FROM invoiceheader ah 
				INNER JOIN cashcheckdetail ccd ON ccd.routekey=ah.routekey AND ccd.visitkey=ah.visitkey AND  ccd.hhctransactionkey=ah.hhctransactionkey AND ah.immediatepaid>0  WHERE
				CASE WHEN ccd.checknumber>0 THEN ccd.checkdate=var_transactiondate ELSE     
				transactiondate=var_transactiondate 
				END
				) 
	AND ah.dexflag=0;
	 
     
INSERT INTO TEMPRECEIPTSORACLE1 -- TEMPRECEIPTSORACLE 
(DIVISON,CUSTOMER_NUMBER,INVOICE_NUMBER,INVOICE_AMOUNT,RECEIPT_AMOUNT,PAYMENT_MODE,RECEIPT_NUMBER,CHECK_NUMBER,RECEIPT_DATE,COMMENTS ,BANKNAME,CHECK_DATE,HHT_BANK_NAME, DEDUCTION)
	SELECT cm.divisioncode,
	cm.alternatecode AS 	CUSTOMER_NUMBER	,
	'' AS INVOICE_NUMBER,
	0 AS 	INVOICE_AMOUNT,
	ah.amountpaid AS 	RECEIPT_AMOUNT,
	CASE WHEN chequecollection=1 THEN 'CHEQUE' ELSE 'CASH' END AS 	PAYMENT_MODE	,
	ah.invoicenumber AS RECEIPT_NUMBER	,
	ccd.checknumber AS CHECK_NUMBER,
	CASE WHEN chequecollection=1 THEN var_transactiondate ELSE DATE_FORMAT(ah.transactiondate,'%Y-%m-%d') END AS RECEIPT_DATE,
	ah.comments AS COMMENTS,
	RM.ARBROUTENAME,
	ccd.checkdate,
	IFNULL(BM.BANKNAME,''), 
	''
FROM 
	Arheader ah 
	INNER JOIN customermaster cm ON cm.customercode=ah.customercode
	INNER JOIN Routemaster rm ON rm.routecode=ah.routecode
	INNER JOIN view_cash_chk_detl ccd ON  ccd.hhctransactionkey=ah.hhctransactionkey AND ccd.routekey=ah.routekey AND ccd.visitkey=ah.visitkey
	LEFT OUTER JOIN BANKMASTER BM ON BM.BANKCODE=CCD.BANKCODE
WHERE    
	ah.advancepaymentflag=1 
	AND ah.invoicenumber IN( SELECT invoicenumber FROM Arheader ah INNER JOIN cashcheckdetail ccd ON ccd.routekey=ah.routekey 
				AND ccd.visitkey=ah.visitkey AND  ccd.hhctransactionkey=ah.hhctransactionkey
				AND ccd.routekey=ah.routekey 
				WHERE 
				CASE WHEN chequecollection=1 THEN ccd.checkdate=var_transactiondate ELSE   
				transactiondate=var_transactiondate 
				END
				);
    
 SELECT DIVISON,CUSTOMER_NUMBER,INVOICE_NUMBER,INVOICE_AMOUNT,RECEIPT_AMOUNT,PAYMENT_MODE,RECEIPT_NUMBER,CHECK_NUMBER,
	RECEIPT_DATE,COMMENTS,BANKNAME,
	CASE WHEN CHECK_DATE = '0000-00-00 00:00:00' THEN RECEIPT_DATE ELSE CHECK_DATE END CHECK_DATE,
	HHT_BANK_NAME,CASE WHEN DEDUCTION =0 THEN '' ELSE DEDUCTION END AS DEDUCTION
 FROM  TEMPRECEIPTSORACLE1; -- TEMPRECEIPTSORACLE;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_receipts_12may2019` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_receipts_12may2019` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_receipts_12may2019`(
IN  var_transactiondate DATE)
BEGIN
DECLARE var_invoicenumber BIGINT;
DECLARE done INT DEFAULT FALSE;
 DECLARE cur1 CURSOR FOR SELECT invoicenumber FROM Arheader WHERE transactiondate=var_transactiondate UNION SELECT invoicenumber FROM invoiceheader WHERE transactiondate=var_transactiondate ;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
  OPEN cur1;
  
  DELETE FROM TEMPRECEIPTSORACLE;
  read_loop: LOOP
    FETCH cur1 INTO var_invoicenumber;
    
    IF done THEN
      LEAVE read_loop;
    END IF;
 INSERT INTO TEMPRECEIPTSORACLE
SELECT cm.divisioncode AS DIVISON,cm.alternatecode AS 	CUSTOMER_NUMBER	,ad.alternateinvoicenumber AS INVOICE_NUMBER,ad.TotalInvoiceAmount AS 	INVOICE_AMOUNT,ad.amountpaid AS 	RECEIPT_AMOUNT,CASE WHEN chequecollection=1 THEN 'CHEQUE' ELSE 'CASH' END AS 	PAYMENT_MODE	,ah.invoicenumber AS RECEIPT_NUMBER	,ccd.checknumber AS CHECK_NUMBER,DATE_FORMAT(ah.transactiondate,'%Y-%m-%d')  AS 	RECEIPT_DATE,ah.comments AS COMMENTS ,RM.ARBROUTENAME
FROM Arheader ah INNER JOIN ardetail ad ON ah.transactionkey=ad.transactionkey
INNER JOIN customermaster cm ON cm.customercode=ah.customercode
INNER JOIN Routemaster rm ON rm.routecode=ah.routecode
INNER JOIN cashcheckdetail ccd ON ccd.routekey=ah.routekey AND ccd.visitkey=ah.visitkey AND  ccd.hhctransactionkey=ah.hhctransactionkey
AND ccd.routekey=ah.routekey
     WHERE ah.invoicenumber=var_invoicenumber;
 
 INSERT INTO TEMPRECEIPTSORACLE    
     SELECT cm.divisioncode AS DIVISON,cm.alternatecode AS 	CUSTOMER_NUMBER	,ah.invoicenumber AS INVOICE_NUMBER,ah.TotalInvoiceAmount AS 	INVOICE_AMOUNT,ah.immediatepaid AS 	RECEIPT_AMOUNT,CASE WHEN ccd.checknumber>0 THEN 'CHEQUE' ELSE 'CASH' END AS 	PAYMENT_MODE	,ah.invoicenumber AS RECEIPT_NUMBER	,ccd.checknumber AS CHECK_NUMBER,DATE_FORMAT(ah.transactiondate,'%Y-%m-%d')  AS 	RECEIPT_DATE,ah.comments AS COMMENTS ,RM.ARBROUTENAME
FROM InvoiceHeader ah 
INNER JOIN customermaster cm ON cm.customercode=ah.customercode
INNER JOIN Routemaster rm ON rm.routecode=ah.routecode
INNER JOIN cashcheckdetail ccd ON ccd.routekey=ah.routekey AND ccd.visitkey=ah.visitkey AND  ccd.hhctransactionkey=ah.hhctransactionkey AND ah.immediatepaid>0
     WHERE ah.invoicenumber=var_invoicenumber;
     
     INSERT INTO TEMPRECEIPTSORACLE (DIVISON,CUSTOMER_NUMBER,INVOICE_NUMBER,INVOICE_AMOUNT,RECEIPT_AMOUNT,PAYMENT_MODE,RECEIPT_NUMBER,CHECK_NUMBER,RECEIPT_DATE,COMMENTS ,BANKNAME)
SELECT cm.divisioncode,cm.alternatecode AS 	CUSTOMER_NUMBER	,'' AS INVOICE_NUMBER,0 AS 	INVOICE_AMOUNT,ah.amountpaid AS 	RECEIPT_AMOUNT,CASE WHEN chequecollection=1 THEN 'CHEQUE' ELSE 'CASH' END AS 	PAYMENT_MODE	,ah.invoicenumber AS RECEIPT_NUMBER	,ccd.checknumber AS CHECK_NUMBER,ah.transactiondate  AS 	RECEIPT_DATE,ah.comments AS COMMENTS,''
FROM Arheader ah 
INNER JOIN customermaster cm ON cm.customercode=ah.customercode
INNER JOIN Routemaster rm ON rm.routecode=ah.routecode
INNER JOIN cashcheckdetail ccd ON  ccd.hhctransactionkey=ah.hhctransactionkey AND ccd.routekey=ah.routekey AND ccd.visitkey=ah.visitkey
     WHERE ah.advancepaymentflag=1 AND  ah.invoicenumber=var_invoicenumber;
     
  END LOOP;
  CLOSE cur1;
 SELECT * FROM  TEMPRECEIPTSORACLE;
    END */$$
DELIMITER ;

