/* Procedure structure for procedure `sp_get_route_customer_from_routecode` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_route_customer_from_routecode` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_route_customer_from_routecode`(
	IN trankey	BIGINT(28),
	IN trantype INT(4)
    )
BEGIN
		DECLARE routeid BIGINT(18);
		DECLARE salesmanid BIGINT(18);
		DECLARE custcode BIGINT(18);
		
		IF trantype = 1 THEN 
			SELECT routecode,salesmancode,customercode INTO routeid,salesmanid,custcode FROM arheader WHERE transactionkey = trankey;
		ELSE
			SELECT routecode,salesmancode,customercode INTO routeid,salesmanid,custcode FROM customerinvoice WHERE transactionkey = trankey;
		END IF;
				
		SELECT routecode,routename FROM routemaster WHERE routecode 	= routeid;
		SELECT salesmancode,salesmanname1 FROM salesman WHERE salesmancode 	= salesmanid;
		
		CALL sp_combo_customermaster();
		CALL sp_combo_bankmaster();
		select custcode;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_route_customer_from_routecode_crheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_route_customer_from_routecode_crheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_route_customer_from_routecode_crheader`(
	IN trankey	BIGINT(28),
	in trantype int(4)
    )
BEGIN
		declare routeid bigint(18);
		DECLARE salesmanid BIGINT(18);
		DECLARE custcode BIGINT(18) DEFAULT 0;
		
		IF trantype = 1 THEN 
			select routecode,salesmancode into routeid,salesmanid from cashierreceiptheader where documentnumber = trankey;		
		ELSEIF trantype = 2 THEN 
			SELECT routecode,salesmancode,customercode INTO routeid,salesmanid,custcode FROM customerinvoice WHERE transactionkey = trankey;
		else
			select 1;
		END IF;
				
		select routecode,routename from routemaster where routecode = routeid;
		SELECT salesmancode,salesmanname1 FROM salesman WHERE salesmancode 	= salesmanid;
		
		CALL sp_combo_customermaster();
		call sp_combo_bankmaster();
		SELECT ifnull(custcode,0) as custcode;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_route_enddate_time` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_route_enddate_time` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_route_enddate_time`(
		IN routeid BIGINT	    
	)
BEGIN
	
	SELECT CONCAT(DATE_FORMAT(routeenddate,"%d-%m-%Y"),' ',routeendtime) AS routeenddate 
		FROM startendday WHERE routeclosed = 1 AND routecode = routeid ORDER BY MAX(routeenddate) DESC LIMIT 1;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_route_for_mandatory` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_route_for_mandatory` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_route_for_mandatory`(
					IN fillby 		VARCHAR(20),
					IN feature 			VARCHAR(20)
					)
BEGIN
	DECLARE where_cond 	TEXT;
	DECLARE joining 	TEXT;
	DECLARE where_route TEXT;
	
	
	
	
	SET @q1 = CONCAT( "SELECT route.routecode AS id, CONCAT(route.routecode,' -- ',route.routename) AS val FROM routemaster as route
						 WHERE 1=1  AND routetmpl = 0 AND route.activestatus = 1"); 
	
	PREPARE s1 FROM @q1;
	EXECUTE s1;
	
	
	
	SET @q2 = CONCAT( 	"SELECT route.routecode AS id, CONCAT(route.routecode,' -- ',route.routename) AS val FROM routemaster as route
						 WHERE 1=1 AND routefeature ='",feature,"' AND  routeflag = '",fillby,"' AND routetmpl = 0  AND route.activestatus = 1");
	PREPARE s2 FROM @q2;
	EXECUTE s2;
	select @q2;
	
	
	SET @q3 = CONCAT( 	"SELECT route.routecode AS routecode FROM routemaster as route
						 WHERE 9=9 AND routefeature ='",feature,"' AND  routeflag = '",fillby,"' AND routetmpl = 0  AND route.activestatus = 1");
	PREPARE s3 FROM @q3;
	EXECUTE s3;
	 select @q3;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_route_from_criteria` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_route_from_criteria` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_route_from_criteria`(
					IN fillby 		INT,
					IN val 			VARCHAR(20),				
					IN routeitmgrp 	VARCHAR(20)
					)
BEGIN
	DECLARE where_cond 	TEXT;
	DECLARE joining 	TEXT;
	DECLARE where_route TEXT;
	
	IF fillby = 1 THEN
		SET where_cond 	=  ' AND route.regionmstcode =';
		SET joining 	=  '';
	ELSEIF	fillby = 2 THEN
		SET where_cond 	=  'AND depot.depotcode =';
		SET joining 	=  'LEFT JOIN regionmaster AS reg ON reg.regionmstcode = route.regionmstcode
							LEFT JOIN depotmaster AS depot ON depot.regionmstcode = reg.regionmstcode'; 
	ELSEIF	fillby = 3 THEN
		SET where_cond 	=  'AND armst.areacode =';
		SET joining		=  'LEFT JOIN subareamaster AS sub ON sub.subareacode = route.subareacode
							LEFT JOIN areamaster AS armst ON armst.areacode = sub.areacode';
	END IF;
	
	IF val = '0' THEN
		SET where_cond 	=	'';
		SET val 		= 	'';
	END IF;
	
	IF routeitmgrp !='0' THEN
		SET where_route = concat(' AND route.routeitemgrpcode = ',routeitmgrp);
	ELSE
		SET where_route = ' AND 1=1 ';
		SET routeitmgrp = '';
	END IF;
	
	
	
	
	SET @q1 = CONCAT( "SELECT route.routecode AS id, CONCAT(route.routecode,' -- ',route.routename) AS val FROM routemaster as route
						",joining," WHERE 9=9 ",where_cond," ",val," AND routetmpl = 0 AND route.activestatus = 1"); 
	
	PREPARE s1 FROM @q1;
	EXECUTE s1;
	
	
	
	SET @q2 = CONCAT( 	"SELECT route.routecode AS id, CONCAT(route.routecode,' -- ',route.routename) AS val FROM routemaster as route
						",joining," WHERE 9=9 ",where_cond," ",val," AND routetmpl = 0 ",where_route," AND route.activestatus = 1");
	PREPARE s2 FROM @q2;
	EXECUTE s2;
	
	
	
	SET @q3 = CONCAT( 	"SELECT route.routecode AS routecode FROM routemaster as route
						",joining," WHERE 9=9 ",where_cond," ",val," AND routetmpl = 0 ",where_route," AND route.activestatus = 1");
	PREPARE s3 FROM @q3;
	EXECUTE s3;
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_route_status_startendday` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_route_status_startendday` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_route_status_startendday`(IN routeid BIGINT,IN routedate VARCHAR(50))
BEGIN
	SELECT COUNT(*) AS cnt FROM startendday 
		WHERE routeclosed = 0 AND DATE(routestartdate) = STR_TO_DATE(routedate,'%d-%m-%Y') AND routecode = routeid;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_salesInvoice` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_salesInvoice` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_salesInvoice`(
IN var_transactiondate DATE)
BEGIN
DECLARE var_invoicenumber BIGINT;
DECLARE done INT DEFAULT FALSE;
 DECLARE cur1 CURSOR FOR SELECT invoicenumber FROM InvoiceHeader WHERE IFNULL(posted,0)=0 AND transactiondate=var_transactiondate;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
  OPEN cur1;
  
  DELETE FROM TEMPSALESINVOICEORACLE;
  read_loop: LOOP
    FETCH cur1 INTO var_invoicenumber;
    
    IF done THEN
      LEAVE read_loop;
    END IF;
    
 
INSERT INTO TEMPSALESINVOICEORACLE
SELECT  cm.divisioncode  AS DIVISON,cm.alternatecode AS CUSTOMER_NUMBER,sh.invoicenumber AS INVOICE_NUMBER,sh.invoicenumber AS INVOICE_NUMBER,sm.salesmanname1 AS SALES_PERSON_NAME, sh.transactiondate AS INVOICE_DATE,'VAN_SALE' AS ORDER_TYPE,'INVOICE' AS ORDER_CATEGORY_CODE,IFNULL(alternatepricingkey,'') AS PRICE_LIST,'OMR' AS CURRENCY_CODE,
cm.memo1 AS WAREHOUSE_CODE,totalpromoamount - (SELECT SUM(promoamount)-SUM(returnpromoamount) FROM invoicedetail WHERE transactionkey=sh.transactionkey)  AS HEADER_DISCOUNT,@row_number:=@row_number+1 AS LINE_NO,im.alternatecode AS INVOICED_ITEM,
 CASE WHEN sd.salesqty>=im.unitspercase THEN sd.salesqty / im.unitspercase ELSE sd.salesqty END AS INVOICED_QTY,
 CASE WHEN sd.salesqty>=im.unitspercase THEN im.upccasecode ELSE 'EACH' END AS ITEM_UOM,
 CASE WHEN sd.salesqty>=im.unitspercase THEN sd.salescaseprice ELSE sd.salesprice END AS UNIT_SELLING_PRICE,
  CASE WHEN sd.salesqty>=im.unitspercase THEN sd.promoamount/(sd.salesqty / im.unitspercase) ELSE sd.promoamount/(sd.salesqty) END  AS LINE_LEVEL_DISCOUNT
 ,rm.warehouse AS SUBINVENTORY_CODE, '' AS BATCH_EXPIRY_DATE, '' AS RETURN_REASON_CODE,sh.comments AS COMMENTS ,IFNULL(sd.salesitemgsttax,0) AS TAX_AMOUNT,
IFNULL(tt.taxdescription,'') AS TAX_CODE
 FROM InvoiceHeader sh INNER JOIN InvoiceDetail sd ON sh.transactionkey=sd.transactionkey
INNER JOIN itemmaster im ON im.actualitemcode=sd.itemcode
INNER JOIN customermaster cm ON cm.customercode=sh.customercode
INNER JOIN RouteMaster rm ON rm.routecode=sh.routecode
INNER JOIN salesman sm ON sm.salesmancode=sh.salesmancode
LEFT OUTER JOIN customerpricingplanheader1 cp ON cp.alternatecode=cm.alternatepricingkey
LEFT OUTER JOIN tbltaxmaster tt ON tt.taxcode =im.itemtaxkey2
INNER JOIN (SELECT @row_number:=0) AS t
WHERE sd.salesqty>0 AND
IFNULL(posted,0)=0 AND sh.invoicenumber=var_invoicenumber AND sh.dexflag=0;
 
 
INSERT INTO TEMPSALESINVOICEORACLE
SELECT  cm.divisioncode  AS DIVISON,cm.alternatecode AS CUSTOMER_NUMBER,sh.invoicenumber AS INVOICE_NUMBER,sh.invoicenumber AS INVOICE_NUMBER,sm.salesmanname1 AS SALES_PERSON_NAME, sh.transactiondate AS INVOICE_DATE,'VAN_SALE' AS ORDER_TYPE,'INVOICE' AS ORDER_CATEGORY_CODE,IFNULL(alternatepricingkey,'') AS PRICE_LIST,'OMR' AS CURRENCY_CODE,cm.memo1 AS WAREHOUSE_CODE,totalpromoamount - (SELECT SUM(promoamount)-SUM(returnpromoamount)  FROM invoicedetail WHERE transactionkey=sh.transactionkey) AS HEADER_DISCOUNT,@row_number:=@row_number+1 AS LINE_NO,im.alternatecode AS INVOICED_ITEM,
 CASE WHEN (COALESCE(sd.manualfreeqty,0)+COALESCE(sd.freesampleqty,0))>=im.unitspercase THEN (COALESCE(sd.manualfreeqty,0)+COALESCE(sd.freesampleqty,0)) / im.unitspercase ELSE (COALESCE(sd.manualfreeqty,0)+COALESCE(sd.freesampleqty,0)) END AS INVOICED_QTY, 
 CASE WHEN (COALESCE(sd.manualfreeqty,0)+COALESCE(sd.freesampleqty,0))>=im.unitspercase THEN im.upccasecode ELSE 'EACH' END AS ITEM_UOM,
 
 0 AS UNIT_SELLING_PRICE,    CASE WHEN (COALESCE(sd.manualfreeqty,0)+COALESCE(sd.freesampleqty,0))>=im.unitspercase THEN sd.promoamount/((COALESCE(sd.manualfreeqty,0)+COALESCE(sd.freesampleqty,0)) / im.unitspercase) ELSE sd.promoamount/((COALESCE(sd.manualfreeqty,0)+COALESCE(sd.freesampleqty,0))) END AS LINE_LEVEL_DISCOUNT,rm.warehouse AS SUBINVENTORY_CODE, '' AS BATCH_EXPIRY_DATE, '' AS RETURN_REASON_CODE,sh.comments AS COMMENTS,0 AS TAX_AMOUNT,
IFNULL(tt.taxdescription,'') AS TAX_CODE  FROM InvoiceHeader sh INNER JOIN InvoiceDetail sd ON 
sh.transactionkey=sd.transactionkey
INNER JOIN itemmaster im ON im.actualitemcode=sd.itemcode
INNER JOIN customermaster cm ON cm.customercode=sh.customercode
INNER JOIN RouteMaster rm ON rm.routecode=sh.routecode
INNER JOIN salesman sm ON sm.salesmancode=sh.salesmancode
LEFT OUTER JOIN customerpricingplanheader1 cp ON cp.alternatecode=cm.alternatepricingkey
LEFT OUTER JOIN tbltaxmaster tt ON tt.taxcode =im.itemtaxkey2
INNER JOIN (SELECT @row_number:=0) AS t
WHERE (sd.manualfreeqty+ sd.freesampleqty) >0   AND IFNULL(posted,0)=0 AND sh.invoicenumber=var_invoicenumber AND sh.dexflag=0;
 
 
INSERT INTO TEMPSALESINVOICEORACLE
SELECT  cm.divisioncode  AS DIVISON,cm.alternatecode AS CUSTOMER_NUMBER,sh.invoicenumber AS ORDER_NUMBER,sh.invoicenumber AS INVOICE_NUMBER,sm.salesmanname1 AS SALES_PERSON_NAME, sh.transactiondate AS ORDERED_DATE,CASE WHEN rm.routetype=2 THEN 'PRE_SALE' ELSE 'VAN_SALE' END  AS ORDER_TYPE,'RETURN' AS ORDER_CATEGORY_CODE,IFNULL(alternatepricingkey,'') AS PRICE_LIST,'OMR' AS CURRENCY_CODE,
CASE WHEN (im.alternatecode LIKE '125%' OR im.alternatecode LIKE '316%') AND rm.routecode IN(1218, 1219, 1227, 1239, 1229) THEN 'G19' 
WHEN (im.alternatecode LIKE '116%' OR im.alternatecode LIKE '312%') AND rm.routecode IN(1107,1111,1199,1142,1110,1118,1143,1109,1127,1138,1112,1108,1141,1119,1101,1129,1139) THEN 'A01' WHEN (im.alternatecode LIKE '117%') AND rm.routecode IN(1107,1111,1199,1142,1110,1118,1143,1109,1127,1138,1112,1108,1141,1119,1101,1129,1139) THEN 'A01' 
ELSE cm.memo1 END  AS WAREHOUSE_CODE,
 
totalpromoamount - (SELECT SUM(promoamount)-SUM(returnpromoamount) FROM invoicedetail WHERE transactionkey=sh.transactionkey) AS HEADER_DISCOUNT,@row_number:=@row_number+1 AS LINE_NO,im.alternatecode AS ORDERED_ITEM,
 CASE WHEN sd.returnqty>=im.unitspercase THEN sd.returnqty / im.unitspercase ELSE sd.returnqty END  AS ORDERED_QTY,
 CASE WHEN (COALESCE(sd.returnqty,0))>=im.unitspercase THEN im.upccasecode ELSE 'EACH' END AS ITEM_UOM,
  CASE WHEN sd.returnqty>=im.unitspercase THEN sd.salescaseprice ELSE sd.salesprice END  AS UNIT_SELLING_PRICE,   CASE WHEN sd.returnqty>=im.unitspercase THEN sd.returnpromoamount/(sd.returnqty / im.unitspercase) ELSE sd.returnpromoamount/(sd.returnqty) END AS LINE_LEVEL_DISCOUNT,rm.warehouse AS SUBINVENTORY_CODE, bed.expirydate AS BATCH_EXPIRY_DATE, gr.alternatecode AS RETURN_REASON_CODE,sh.comments AS COMMENTS,IFNULL(sd.returnitemgsttax,0) AS TAX_AMOUNT,
IFNULL(tt.taxdescription,'') AS TAX_CODE  FROM InvoiceHeader sh INNER JOIN InvoiceDetail sd ON 
sh.transactionkey=sd.transactionkey
INNER JOIN itemmaster im ON im.actualitemcode=sd.itemcode
INNER JOIN customermaster cm ON cm.customercode=sh.customercode
INNER JOIN RouteMaster rm ON rm.routecode=sh.routecode
INNER JOIN salesman sm ON sm.salesmancode=sh.salesmancode
LEFT OUTER JOIN customerpricingplanheader1 cp ON cp.alternatecode=cm.alternatepricingkey
LEFT OUTER JOIN invoicerxddetail bed ON bed.routekey=sd.routekey AND bed.visitkey=sd.visitkey
AND bed.itemcode=sd.itemcode
LEFT OUTER JOIN  retitmreasons gr ON gr.code=bed.reasoncode 
LEFT OUTER JOIN tbltaxmaster tt ON tt.taxcode =im.itemtaxkey2
INNER JOIN (SELECT @row_number:=0) AS t
WHERE (sd.returnqty)>0 AND bed.itemtransactiontype=1 AND IFNULL(posted,0)=0 AND sh.invoicenumber=var_invoicenumber AND sh.dexflag=0;
 
INSERT INTO TEMPSALESINVOICEORACLE
SELECT  cm.divisioncode  AS DIVISON,cm.alternatecode AS CUSTOMER_NUMBER,sh.invoicenumber AS ORDER_NUMBER,sh.invoicenumber AS INVOICE_NUMBER,sm.salesmanname1 AS SALES_PERSON_NAME, sh.transactiondate AS ORDERED_DATE,CASE WHEN rm.routetype=2 THEN 'PRE_SALE' ELSE 'VAN_SALE' END  AS  ORDER_TYPE,'RETURN' AS ORDER_CATEGORY_CODE,IFNULL(alternatepricingkey,'') AS PRICE_LIST,'OMR' AS CURRENCY_CODE,
CASE WHEN (im.alternatecode LIKE '125%' OR im.alternatecode LIKE '316%') AND rm.routecode IN(1218, 1219, 1227, 1239, 1229) THEN 'G19' 
WHEN (im.alternatecode LIKE '116%' OR im.alternatecode LIKE '312%') AND rm.routecode IN(1107,1111,1199,1142,1110,1118,1143,1109,1127,1138,1112,1108,1141,1119,1101,1129,1139) THEN 'A01' WHEN (im.alternatecode LIKE '117%') AND rm.routecode IN(1107,1111,1199,1142,1110,1118,1143,1109,1127,1138,1112,1108,1141,1119,1101,1129,1139) THEN 'A01' 
ELSE cm.memo1 END  AS WAREHOUSE_CODE,
totalpromoamount - (SELECT SUM(promoamount)-SUM(returnpromoamount) FROM invoicedetail WHERE transactionkey=sh.transactionkey) AS HEADER_DISCOUNT,
@row_number:=@row_number+1 AS LINE_NO,im.alternatecode AS ORDERED_ITEM,
CASE WHEN sd.damagedqty>=im.unitspercase THEN sd.damagedqty / im.unitspercase ELSE sd.damagedqty END AS ORDERED_QTY,
CASE WHEN (COALESCE(sd.damagedqty,0))>=im.unitspercase THEN im.upccasecode ELSE 'EACH' END AS ITEM_UOM,
CASE WHEN sd.damagedqty>=im.unitspercase THEN sd.salescaseprice ELSE sd.salesprice END AS UNIT_SELLING_PRICE, 
 CASE WHEN sd.damagedqty>=im.unitspercase THEN sd.returnpromoamount/(sd.damagedqty / im.unitspercase) ELSE sd.returnpromoamount/(sd.damagedqty) END  AS LINE_LEVEL_DISCOUNT,
 -- end of arun chnged
 rm.warehouse AS SUBINVENTORY_CODE, bed.expirydate AS BATCH_EXPIRY_DATE, gr.alternatecode AS RETURN_REASON_CODE,sh.comments AS COMMENTS,IFNULL(sd.damageditemgsttax,0) AS TAX_AMOUNT,
IFNULL(tt.taxdescription,'') AS TAX_CODE FROM InvoiceHeader sh INNER JOIN InvoiceDetail sd ON 
sh.transactionkey=sd.transactionkey
INNER JOIN itemmaster im ON im.actualitemcode=sd.itemcode
INNER JOIN customermaster cm ON cm.customercode=sh.customercode
INNER JOIN RouteMaster rm ON rm.routecode=sh.routecode
INNER JOIN salesman sm ON sm.salesmancode=sh.salesmancode
LEFT OUTER JOIN customerpricingplanheader1 cp ON cp.alternatecode=cm.alternatepricingkey
LEFT OUTER JOIN invoicerxddetail bed ON bed.routekey=sd.routekey AND bed.visitkey=sd.visitkey
AND bed.itemcode=sd.itemcode
LEFT OUTER JOIN  expiryreturnreasons gr ON gr.code=bed.reasoncode 
LEFT OUTER JOIN tbltaxmaster tt ON tt.taxcode =im.itemtaxkey2
INNER JOIN (SELECT @row_number:=0) AS t
WHERE (sd.damagedqty  )>0   AND IFNULL(posted,0)=0 AND sh.invoicenumber=var_invoicenumber AND sh.dexflag=0;
 
INSERT INTO TEMPSALESINVOICEORACLE
SELECT  cm.divisioncode  AS DIVISON,cm.alternatecode AS CUSTOMER_NUMBER,sh.invoicenumber AS INVOICE_NUMBER,sh.invoicenumber AS INVOICE_NUMBER,sm.salesmanname1 AS SALES_PERSON_NAME, 
sh.transactiondate AS INVOICE_DATE,'VAN_SALE' AS ORDER_TYPE,'INVOICE' AS ORDER_CATEGORY_CODE,IFNULL(alternatepricingkey,'') AS PRICE_LIST,'OMR' AS CURRENCY_CODE,
CASE WHEN (im.alternatecode LIKE '125%' OR im.alternatecode LIKE '316%') AND rm.routecode IN(1218, 1219, 1227, 1239, 1229) THEN 'G19' ELSE cm.memo1 END  AS WAREHOUSE_CODE,
totalpromoamount - (SELECT SUM(promoamount)-SUM(returnpromoamount) FROM invoicedetail WHERE transactionkey=sh.transactionkey) AS HEADER_DISCOUNT,
@row_number:=@row_number+1 AS LINE_NO,im.alternatecode AS INVOICED_ITEM,
CASE WHEN (COALESCE(sd.returnfreeqty,0))>=im.unitspercase THEN (COALESCE(sd.returnfreeqty,0)) / im.unitspercase ELSE (COALESCE(sd.returnfreeqty,0)) END AS INVOICED_QTY,
CASE WHEN (COALESCE(sd.returnfreeqty,0))>=im.unitspercase THEN im.upccasecode ELSE 'EACH' END AS ITEM_UOM,
0 AS UNIT_SELLING_PRICE, 
 CASE WHEN sd.returnfreeqty>=im.unitspercase THEN sd.returnpromoamount/(sd.returnfreeqty / im.unitspercase) ELSE sd.returnpromoamount/(sd.returnfreeqty) END  AS LINE_LEVEL_DISCOUNT,rm.warehouse AS SUBINVENTORY_CODE, '' AS BATCH_EXPIRY_DATE, 'C3' AS RETURN_REASON_CODE,sh.comments AS COMMENTS ,0 AS TAX_AMOUNT,IFNULL(tt.taxdescription,'') AS TAX_CODE FROM InvoiceHeader sh INNER JOIN InvoiceDetail sd ON 
sh.transactionkey=sd.transactionkey
INNER JOIN itemmaster im ON im.actualitemcode=sd.itemcode
INNER JOIN customermaster cm ON cm.customercode=sh.customercode
INNER JOIN RouteMaster rm ON rm.routecode=sh.routecode
INNER JOIN salesman sm ON sm.salesmancode=sh.salesmancode
LEFT OUTER JOIN customerpricingplanheader1 cp ON cp.alternatecode=cm.alternatepricingkey
LEFT OUTER JOIN tbltaxmaster tt ON tt.taxcode =im.itemtaxkey2
INNER JOIN (SELECT @row_number:=0) AS t
WHERE (sd.returnfreeqty)>0   AND IFNULL(posted,0)=0 AND sh.invoicenumber=var_invoicenumber AND sh.dexflag=0;
  END LOOP;
  CLOSE cur1;
  
  SET @row_number:=0;
SET @inv_no:='';
  
SELECT DIVISON, 
	CUSTOMER_NUMBER, 
	ORDER_NUMBER, 
	INVOICE_NUMBER, 
	SALES_PERSON_NAME, 
	ORDERED_DATE, 
	ORDER_TYPE, 
	ORDER_CATEGORY_CODE, 
	PRICE_LIST, 
	CURRENCY_CODE, 
	WAREHOUSE_CODE, 
	HEADER_DISCOUNT, 
	@row_number:=CASE WHEN @inv_no=INVOICE_NUMBER THEN @row_number+1 ELSE 1 END AS  LINE_NO, 
	ORDERED_ITEM, 
	ORDERED_QTY, 
	ITEM_UOM, 
	UNIT_SELLING_PRICE, 
	LINE_LEVEL_DISCOUNT, 
	SUBINVENTORY_CODE, 
	BATCH_EXPIRY_DATE, 
	RETURN_REASON_CODE, 
	COMMENTS,TAXAMOUNT,TAXCODE, @inv_no:=INVOICE_NUMBER AS INVOICE_NUMBER FROM  TEMPSALESINVOICEORACLE;
    END */$$
DELIMITER ;

