BEGIN
DECLARE var_invoicenumber BIGINT;
DECLARE done INT DEFAULT FALSE;
 DECLARE cur1 CURSOR FOR SELECT invoicenumber FROM InvoiceHeader WHERE IFNULL(posted,0)=0 AND transactiondate=var_transactiondate;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
  OPEN cur1;
  
  DELETE FROM TEMPSALESINVOICEORACLE;
  read_loop: LOOP
    FETCH cur1 INTO var_invoicenumber;
    
    IF done THEN
      LEAVE read_loop;
    END IF;
