SELECT  cm.divisioncode  AS DIVISON,cm.alternatecode AS CUSTOMER_NUMBER,sh.invoicenumber AS INVOICE_NUMBER,sh.invoicenumber AS INVOICE_NUMBER,sm.salesmanname1 AS SALES_PERSON_NAME, sh.transactiondate AS INVOICE_DATE,'VAN_SALE' AS ORDER_TYPE,'INVOICE' AS ORDER_CATEGORY_CODE,IFNULL(alternatepricingkey,'') AS PRICE_LIST,'OMR' AS CURRENCY_CODE,cm.memo1 AS WAREHOUSE_CODE,0 AS HEADER_DISCOUNT,@row_number:=@row_number+1 AS LINE_NO,im.alternatecode AS INVOICED_ITEM,sd.salesqty DIV im.unitspercase AS INVOICED_QTY,'CASE' AS ITEM_UOM,im.caseprice AS UNIT_SELLING_PRICE, sd.promoamount/(sd.salesqty/im.unitspercase) AS LINE_LEVEL_DISCOUNT,rm.warehouse AS SUBINVENTORY_CODE, '' AS BATCH_EXPIRY_DATE, '' AS RETURN_REASON_CODE,sh.comments AS COMMENTS  FROM InvoiceHeader sh INNER JOIN InvoiceDetail sd ON 
sh.transactionkey=sd.transactionkey
INNER JOIN itemmaster im ON im.actualitemcode=sd.itemcode
INNER JOIN customermaster cm ON cm.customercode=sh.customercode
