/* Procedure structure for procedure `sp_get_salesman_from_routecode` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_salesman_from_routecode` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_salesman_from_routecode`(
					IN routeid BIGINT
					)
BEGIN
	
			SELECT sm.salesmancode,sm.salesmanname1 FROM routemaster AS rm
			LEFT JOIN salesman AS sm ON sm.salesmancode = rm.salesmancode
			WHERE rm.routecode = routeid;
END */$$
