/* Procedure structure for procedure `sp_get_salesorder` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_salesorder` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_salesorder`(
IN var_transactiondate DATE)
BEGIN
DECLARE var_invoicenumber BIGINT;
DECLARE done INT DEFAULT FALSE;
DECLARE cur1 CURSOR FOR SELECT invoicenumber FROM Salesorderheader WHERE mdat=var_transactiondate;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
  OPEN cur1;
  
  DELETE FROM tempsalesorderoracle;
  read_loop: LOOP
    FETCH cur1 INTO var_invoicenumber;
    
    IF done THEN
      LEAVE read_loop;
    END IF;
    
   
INSERT INTO tempsalesorderoracle (
DIVISON,               
CUSTOMER_NUMBER,   
ORDER_NUMBER,               
INVOICE_NUMBER,               
SALES_PERSON_NAME, 
ORDERED_DATE,               
ORDER_TYPE,    
ORDER_CATEGORY_CODE,               
PRICE_LIST,        
CURRENCY_CODE,               
WAREHOUSE_CODE,      
HEADER_DISCOUNT,               
LINE_NO,           
ORDERED_ITEM,               
ORDERED_QTY,               
ITEM_UOM,               
UNIT_SELLING_PRICE,               
LINE_LEVEL_DISCOUNT,               
SUBINVENTORY_CODE, 
BATCH_EXPIRY_DATE,               
RETURN_REASON_CODE,
COMMENTS)
SELECT  
cm.divisioncode  AS DIVISON,
cm.alternatecode AS CUSTOMER_NUMBER,
sh.invoicenumber AS ORDER_NUMBER,
invoicenumber AS INVOICE_NUMBER,
sm.salesmanname1 AS SALES_PERSON_NAME, 
DATE_FORMAT(sh.transactiondate,'%Y-%m-%d') AS ORDERED_DATE,
'PRE_SALE' AS ORDER_TYPE,
'ORDER' AS ORDER_CATEGORY_CODE,
IFNULL(alternatepricingkey,NULL) AS PRICE_LIST,
'OMR' AS CURRENCY_CODE,
CASE WHEN (im.alternatecode LIKE '116%' OR im.alternatecode LIKE '312%') AND rm.routecode IN(1107,1111,1199,1142,1110,1118,1143,1109,1127,1138,1112,1108,1141,1119,1101,1129,1139) THEN 'A01' 
	WHEN (im.alternatecode LIKE '117%') AND rm.routecode IN(1107,1111,1199,1142,1110,1118,1143,1109,1127,1138,1112,1108,1141,1119,1101,1129,1139) THEN 'A01' 
	when sh.routecode in (1207,1208,1218,1219,1229,1239,1240,1272,1274,1276,1278,1280,1281) and substr(im.alternatecode, 1,3) in (144, 145,128) then 'G19'
	ELSE cm.memo1 END  AS WAREHOUSE_CODE,
0 AS HEADER_DISCOUNT,
@row_number:=@row_number+1 AS LINE_NO,
im.alternatecode AS ORDERED_ITEM,
sd.salesqty DIV im.unitspercase AS ORDERED_QTY,
im.upccasecode AS ITEM_UOM,
sd.salescaseprice AS UNIT_SELLING_PRICE, 
sd.promoamount/im.unitspercase AS LINE_LEVEL_DISCOUNT,
rm.warehouse AS SUBINVENTORY_CODE, 
DATE_FORMAT(CASE WHEN orderdeliverydate = 0 THEN DATE_ADD(transactiondate, INTERVAL 1 DAY) ELSE IFNULL(orderdeliverydate,NULL) END, '%Y-%m-%d') AS BATCH_EXPIRY_DATE,
'' AS RETURN_REASON_CODE,
sh.comments AS COMMENTS  
FROM salesorderheader sh INNER JOIN salesorderdetail sd ON 
sh.transactionkey=sd.transactionkey
INNER JOIN itemmaster im ON im.actualitemcode=sd.itemcode
INNER JOIN customermaster cm ON cm.customercode=sh.customercode
INNER JOIN RouteMaster rm ON rm.routecode=sh.routecode
INNER JOIN salesman sm ON sm.salesmancode=sh.salesmancode
LEFT OUTER JOIN customerpricingplanheader1 cp ON cp.alternatecode=cm.alternatepricingkey
INNER JOIN (SELECT @row_number:=0) AS t
WHERE (sd.salesqty DIV im.unitspercase )>0   AND sh.invoicenumber=var_invoicenumber 
ORDER BY im.printsequencecust;
INSERT INTO tempsalesorderoracle (
DIVISON,               
CUSTOMER_NUMBER,   
ORDER_NUMBER,               
INVOICE_NUMBER,               
SALES_PERSON_NAME, 
ORDERED_DATE,               
ORDER_TYPE,    
ORDER_CATEGORY_CODE,               
PRICE_LIST,        
CURRENCY_CODE,               
WAREHOUSE_CODE,      
HEADER_DISCOUNT,               
LINE_NO,           
ORDERED_ITEM,               
ORDERED_QTY,               
ITEM_UOM,               
UNIT_SELLING_PRICE,               
LINE_LEVEL_DISCOUNT,               
SUBINVENTORY_CODE, 
BATCH_EXPIRY_DATE,               
RETURN_REASON_CODE,COMMENTS)
SELECT  
cm.divisioncode  AS DIVISON,
cm.alternatecode AS CUSTOMER_NUMBER,
sh.invoicenumber AS ORDER_NUMBER,
invoicenumber AS INVOICE_NUMBER,
sm.salesmanname1 AS SALES_PERSON_NAME, 
DATE_FORMAT(sh.transactiondate,'%Y-%m-%d') AS ORDERED_DATE,
'PRE_SALE' AS ORDER_TYPE,
'ORDER' AS ORDER_CATEGORY_CODE,
IFNULL(alternatepricingkey,NULL) AS PRICE_LIST,'OMR' AS CURRENCY_CODE,
CASE WHEN (im.alternatecode LIKE '116%' OR im.alternatecode LIKE '312%') AND rm.routecode IN(1107,1111,1199,1142,1110,1118,1143,1109,1127,1138,1112,1108,1141,1119,1101,1129,1139) THEN 'A01' 
	WHEN (im.alternatecode LIKE '117%') AND rm.routecode IN(1107,1111,1199,1142,1110,1118,1143,1109,1127,1138,1112,1108,1141,1119,1101,1129,1139) THEN 'A01' 
	WHEN (im.alternatecode LIKE '117%') AND rm.routecode IN(1107,1111,1199,1142,1110,1118,1143,1109,1127,1138,1112,1108,1141,1119,1101,1129,1139) THEN 'A01' 
	when sh.routecode in (1207,1208,1218,1219,1229,1239,1240,1272,1274,1276,1278,1280,1281) and substr(im.alternatecode, 1,3) in (144, 145,128) then 'G19'
	ELSE cm.memo1 END  AS WAREHOUSE_CODE,
0 AS HEADER_DISCOUNT,
@row_number:=@row_number+1 AS LINE_NO,
im.alternatecode AS ORDERED_ITEM,
sd.salesqty MOD im.unitspercase AS ORDERED_QTY,'EACH' AS ITEM_UOM,
sd.salesprice AS UNIT_SELLING_PRICE, 
sd.promoamount/im.unitspercase AS LINE_LEVEL_DISCOUNT,
rm.warehouse AS SUBINVENTORY_CODE, 
DATE_FORMAT(CASE WHEN sh.orderdeliverydate = 0 THEN DATE_ADD(sh.transactiondate, INTERVAL 1 DAY) ELSE IFNULL(sh.orderdeliverydate,NULL) END, '%Y-%m-%d') AS BATCH_EXPIRY_DATE,
'' AS RETURN_REASON_CODE,
sh.comments AS COMMENTS  
FROM salesorderheader sh INNER JOIN salesorderdetail sd ON 
sh.transactionkey=sd.transactionkey
INNER JOIN itemmaster im ON im.actualitemcode=sd.itemcode
INNER JOIN customermaster cm ON cm.customercode=sh.customercode
INNER JOIN RouteMaster rm ON rm.routecode=sh.routecode
INNER JOIN salesman sm ON sm.salesmancode=sh.salesmancode
LEFT OUTER JOIN customerpricingplanheader1 cp ON cp.alternatecode=cm.alternatepricingkey
INNER JOIN (SELECT @row_number:=0) AS t
WHERE (sd.salesqty MOD im.unitspercase )>0   AND sh.invoicenumber=var_invoicenumber ORDER BY im.printsequencecust;
INSERT INTO tempsalesorderoracle(
DIVISON,               
