CASE WHEN (im.alternatecode LIKE '125%' OR im.alternatecode LIKE '316%') AND rm.routecode IN(1218, 1219, 1227, 1239, 1229) THEN 'G19' ELSE cm.memo1 END  AS WAREHOUSE_CODE,0 AS HEADER_DISCOUNT,@row_number:=@row_number+1 AS LINE_NO,im.alternatecode AS ORDERED_ITEM,((COALESCE(sd.manualfreeqty,0)+COALESCE(sd.freesampleqty,0)) DIV im.unitspercase ) AS ORDERED_QTY,im.upccasecode AS ITEM_UOM,0 AS UNIT_SELLING_PRICE, 0 AS LINE_LEVEL_DISCOUNT,rm.warehouse AS SUBINVENTORY_CODE, DATE_FORMAT(IFNULL(sh.orderdeliverydate,NULL),'%Y-%m-%d') AS BATCH_EXPIRY_DATE, '' AS RETURN_REASON_CODE,sh.comments AS COMMENTS FROM salesorderheader sh INNER JOIN salesorderdetail sd ON 
sh.transactionkey=sd.transactionkey
INNER JOIN itemmaster im ON im.actualitemcode=sd.itemcode
INNER JOIN customermaster cm ON cm.customercode=sh.customercode
INNER JOIN RouteMaster rm ON rm.routecode=sh.routecode
INNER JOIN salesman sm ON sm.salesmancode=sh.salesmancode
LEFT OUTER JOIN customerpricingplanheader1 cp ON cp.alternatecode=cm.alternatepricingkey
INNER JOIN (SELECT @row_number:=0) AS t
WHERE ((sd.manualfreeqty+ sd.freesampleqty) DIV im.unitspercase)>0  AND sh.invoicenumber=var_invoicenumber ORDER BY im.printsequencecust;
