INSERT INTO tempsalesorderoracle (DIVISON, 	CUSTOMER_NUMBER, 	ORDER_NUMBER, 	INVOICE_NUMBER, 	SALES_PERSON_NAME, 	ORDERED_DATE, 	ORDER_TYPE, 	ORDER_CATEGORY_CODE, 	PRICE_LIST, 	CURRENCY_CODE, 	WAREHOUSE_CODE, 	HEADER_DISCOUNT, 	LINE_NO, 	ORDERED_ITEM, 	ORDERED_QTY, 	ITEM_UOM, 	UNIT_SELLING_PRICE, 	LINE_LEVEL_DISCOUNT, 	SUBINVENTORY_CODE, 	BATCH_EXPIRY_DATE, 	RETURN_REASON_CODE,COMMENTS)
SELECT   cm.divisioncode  AS DIVISON,cm.alternatecode AS CUSTOMER_NUMBER,sh.invoicenumber AS ORDER_NUMBER,invoicenumber AS INVOICE_NUMBER,sm.salesmanname1 AS SALES_PERSON_NAME, DATE_FORMAT(sh.transactiondate,'%Y-%m-%d') AS ORDERED_DATE,'PRE_SALE' AS ORDER_TYPE,'RETURN' AS ORDER_CATEGORY_CODE,IFNULL(alternatepricingkey,'') AS PRICE_LIST,'OMR' AS CURRENCY_CODE,
CASE WHEN (im.alternatecode LIKE '125%' OR im.alternatecode LIKE '316%') AND rm.routecode IN(1218, 1219, 1227, 1239, 1229) THEN 'G19' ELSE cm.memo1 END  AS WAREHOUSE_CODE,0 AS HEADER_DISCOUNT,@row_number:=@row_number+1 AS LINE_NO,im.alternatecode AS ORDERED_ITEM,sd.returnqty DIV im.unitspercase AS ORDERED_QTY,im.upccasecode AS ITEM_UOM,sd.salescaseprice AS UNIT_SELLING_PRICE,sd.promoamount/im.unitspercase AS LINE_LEVEL_DISCOUNT,rm.warehouse AS SUBINVENTORY_CODE,DATE_FORMAT(IFNULL(sh.orderdeliverydate,NULL),'%Y-%m-%d')  AS BATCH_EXPIRY_DATE,IFNULL(gr.description,'') AS RETURN_REASON_CODE ,sh.comments AS COMMENTS  FROM salesorderheader sh INNER JOIN salesorderdetail sd ON 
