INNER JOIN customermaster cm ON cm.customercode=sh.customercode
INNER JOIN RouteMaster rm ON rm.routecode=sh.routecode
INNER JOIN salesman sm ON sm.salesmancode=sh.salesmancode
LEFT OUTER JOIN customerpricingplanheader1 cp ON cp.alternatecode=cm.alternatepricingkey
LEFT OUTER JOIN orderrxddetail bed ON bed.routekey=sd.routekey AND bed.visitkey=sd.visitkey
AND bed.itemcode=sd.itemcode
LEFT OUTER JOIN  retitmreasons gr ON gr.code=bed.reasoncode 
INNER JOIN (SELECT @row_number:=0) AS t
WHERE (sd.returnqty DIV im.unitspercase)>0   AND sh.invoicenumber=var_invoicenumber ORDER BY im.printsequencecust;
INSERT INTO tempsalesorderoracle (DIVISON, 	CUSTOMER_NUMBER, 	ORDER_NUMBER, 	INVOICE_NUMBER, 	SALES_PERSON_NAME, 	ORDERED_DATE, 	ORDER_TYPE, 	ORDER_CATEGORY_CODE, 	PRICE_LIST, 	CURRENCY_CODE, 	WAREHOUSE_CODE, 	HEADER_DISCOUNT, 	LINE_NO, 	ORDERED_ITEM, 	ORDERED_QTY, 	ITEM_UOM, 	UNIT_SELLING_PRICE, 	LINE_LEVEL_DISCOUNT, 	SUBINVENTORY_CODE, 	BATCH_EXPIRY_DATE, 	RETURN_REASON_CODE,COMMENTS)
