CASE WHEN (im.alternatecode LIKE '125%' OR im.alternatecode LIKE '316%') AND rm.routecode IN(1218, 1219, 1227, 1239, 1229) THEN 'G19' ELSE cm.memo1 END  AS WAREHOUSE_CODE,0 AS HEADER_DISCOUNT,@row_number:=@row_number+1 AS LINE_NO,im.alternatecode AS ORDERED_ITEM,sd.returnqty MOD im.unitspercase AS ORDERED_QTY,'EACH' AS ITEM_UOM,sd.salesprice AS UNIT_SELLING_PRICE,sd.promoamount/im.unitspercase AS LINE_LEVEL_DISCOUNT,rm.warehouse AS SUBINVENTORY_CODE,DATE_FORMAT(IFNULL(sh.orderdeliverydate,NULL),'%Y-%m-%d')  AS BATCH_EXPIRY_DATE,IFNULL(gr.description,'') AS RETURN_REASON_CODE ,sh.comments AS COMMENTS  FROM salesorderheader sh INNER JOIN salesorderdetail sd ON 
sh.transactionkey=sd.transactionkey
INNER JOIN itemmaster im ON im.actualitemcode=sd.itemcode
INNER JOIN customermaster cm ON cm.customercode=sh.customercode
INNER JOIN RouteMaster rm ON rm.routecode=sh.routecode
INNER JOIN salesman sm ON sm.salesmancode=sh.salesmancode
LEFT OUTER JOIN customerpricingplanheader1 cp ON cp.alternatecode=cm.alternatepricingkey
LEFT OUTER JOIN orderrxddetail bed ON bed.routekey=sd.routekey AND bed.visitkey=sd.visitkey
AND bed.itemcode=sd.itemcode
LEFT OUTER JOIN  retitmreasons gr ON gr.code=bed.reasoncode 
INNER JOIN (SELECT @row_number:=0) AS t
WHERE (sd.returnqty MOD im.unitspercase)>0   AND sh.invoicenumber=var_invoicenumber ORDER BY im.printsequencecust;
     
  END LOOP;
  CLOSE cur1;
  
SET @row_number:=0;
SET @inv_no:='';
SELECT  	DIVISON, 	CUSTOMER_NUMBER, 	ORDER_NUMBER, 	INVOICE_NUMBER, 	SALES_PERSON_NAME, 	ORDERED_DATE, 	ORDER_TYPE, 	ORDER_CATEGORY_CODE, 	PRICE_LIST, 	CURRENCY_CODE, 	WAREHOUSE_CODE, 	HEADER_DISCOUNT, 	@row_number:=CASE WHEN @inv_no=INVOICE_NUMBER THEN @row_number+1 ELSE 1 END AS  LINE_NO, 	ORDERED_ITEM, 	ORDERED_QTY, 	ITEM_UOM, 	UNIT_SELLING_PRICE, 	LINE_LEVEL_DISCOUNT, 	SUBINVENTORY_CODE, 	BATCH_EXPIRY_DATE, 	RETURN_REASON_CODE, 	COMMENTS,@inv_no:=INVOICE_NUMBER AS INVOICE_NUMBER FROM  tempsalesorderoracle;
    END */$$
