/* Procedure structure for procedure `sp_get_transaction_index_invoice` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_invoice` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_invoice`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT 		)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'transactionkey';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'ih.*';
	END IF;
	
	if table_where = '' then
		set table_where = concat(' AND transactiondate =  ',date(CURRENT_DATE()));
	end if;
    
	SET @dyn_cnt = CONCAT("SELECT COUNT(transactionkey) AS counter FROM invoiceheader as ih 
	LEFT JOIN routemaster as rm on rm.routecode = ih.routecode
	LEFT JOIN salesman as sm on sm.salesmancode = ih.salesmancode	
	LEFT JOIN customermaster as cm on cm.customercode = ih.customercode	
	WHERE 1=1  ",table_where);
    PREPARE s1 FROM @dyn_cnt;	
	EXECUTE s1;	
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM invoiceheader as ih 
	LEFT JOIN routemaster as rm on rm.routecode = ih.routecode
	LEFT JOIN salesman as sm on sm.salesmancode = ih.salesmancode	
	LEFT JOIN customermaster as cm on cm.customercode = ih.customercode	
	WHERE 1=1  ",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_index_invoicedetailgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_invoicedetailgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_invoicedetailgrid`(
	IN rwcnt INT,	
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT,
	IN tran_key BIGINT 
	
	)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'primary_key';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'ih.*';
	END IF;
	  
	SELECT routekey INTO @routekey FROM invoiceheader WHERE transactionkey =  tran_key;
	
	SET @dyn_cnt = CONCAT("SELECT COUNT(primary_key) AS counter FROM invoicedetail AS id 
	LEFT JOIN itemmaster AS im ON im.actualitemcode = id.itemcode
	WHERE 1=1
	--  AND ( salesqty > 0 OR returnqty > 0 OR damagedqty > 0 OR manualfreeqty > 0 )
	 AND routekey = @routekey AND transactionkey = ",tran_key," ",table_where);
	
    PREPARE s1 FROM @dyn_cnt;
	EXECUTE s1;	
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM invoicedetail AS id 
	LEFT JOIN itemmaster AS im ON im.actualitemcode = id.itemcode
	WHERE 1=1 
	-- AND ( salesqty > 0 OR returnqty > 0 OR damagedqty > 0 OR manualfreeqty > 0 ) 
	AND routekey = @routekey AND transactionkey = ",tran_key," ",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;	
	
	SET @dyn_tc = CONCAT("SELECT 
         IFNULL(SUM((((salesqty/im.unitspercase)*id.salescaseprice)+((salesqty%im.unitspercase)*id.salesprice))-(((returnqty/im.unitspercase)*id.returncaseprice)+((returnqty%im.unitspercase)*id.returnprice))-promoamount),0)	 as tc_amount
	 FROM invoicedetail AS id 
	LEFT JOIN itemmaster AS im ON im.actualitemcode = id.itemcode
	WHERE 1=1 and im.tcallowed = '1' 
	-- AND ( salesqty > 0 OR returnqty > 0 OR damagedqty > 0 OR manualfreeqty > 0 )
	 AND routekey = @routekey AND transactionkey = ",tran_key," ",table_where);
	
    PREPARE s3 FROM @dyn_tc;
	EXECUTE s3;	
    
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_index_invoicedetailgrid_print` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_invoicedetailgrid_print` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_invoicedetailgrid_print`(	
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT,
	IN tran_key BIGINT 
	
	)
BEGIN	
	SET order_by = '1 ';
		
	SET order_type= 'ASC';	
	
	IF table_fields = '' THEN
		SET table_fields = 'ih.*';
	END IF;	
		
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM invoicedetail AS id 
	LEFT JOIN itemmaster AS im ON im.actualitemcode = id.itemcode
	LEFT JOIN `tbltaxmaster` tm on tm.taxcode=im.itemtaxkey2 
	WHERE 1=1 
	AND transactionkey = ",tran_key," ",table_where,  " ORDER BY ",order_by," ", order_type,"");
	PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;	
	
	SET @dyn_cnt = CONCAT("SELECT COALESCE(sum(salesqty),0) as salescount, COALESCE(sum(returnqty),0) as returncount, 
	COALESCE(sum(damagedqty),0) as damagecount, COALESCE(sum(freesampleqty),0) as promocount, 
	COALESCE(sum(manualfreeqty),0) as freecount 
	FROM invoicedetail AS id
	WHERE transactionkey = ",tran_key," ");
	
	PREPARE s5 FROM @dyn_cnt;
	EXECUTE s5;
    
END */$$
DELIMITER ;

