/* Procedure structure for procedure `sp_get_transaction_index_salesorderheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_salesorderheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_salesorderheader`(
	IN id INT
    )
BEGIN
	
	CALL sp_combo_routemaster();
	
	SELECT payment_mode(cm.invoicepaymentterms) AS paymentterm,ih.routecode,ih.salesmancode,ih.*,rm.routename,
		cm.customeraddress1,cm.customeraddress2,cm.customeraddress3,cm.customername,sm.salesmanname1 AS salesmanname ,signaturedata,
		DATE_FORMAT(ed.routestartdate,'%d-%m-%Y') AS routestartdate
		FROM salesorderheader AS ih
		LEFT JOIN salesman AS sm ON sm.salesmancode = ih.salesmancode
		 LEFT JOIN routemaster AS rm ON rm.routecode = ih.routecode
		LEFT JOIN customermaster AS cm ON cm.customercode = ih.customercode	
		
		LEFT JOIN sigcapturedata AS sn ON sn.routekey = ih.routekey AND sn.visitkey = ih.visitkey
		LEFT JOIN startendday AS ed ON ed.routekey = ih.routekey    
	WHERE ih.transactionkey = id;
	
	 SELECT SUM(promoamount) AS promoamount  FROM salesorderdetail WHERE transactionkey = id;
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_invoiceadd_available_qty` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_invoiceadd_available_qty` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_invoiceadd_available_qty`(
in in_itemcode int ,
IN in_customercode INT 
)
BEGIN
	select 
		quantity,
		FLOOR((quantity/get_name_type_base(itemcode,5))) AS case_qty,
		(quantity%get_name_type_base(itemcode,5)) AS pcs_qty,	
		get_name_type_base(itemcode,5) as upc,
		batchdetailkey,
		batchnumber,
		DATE_FORMAT(expirydate,'%d-%m-%Y') as expirydate,
		expirydate as expirydate1,
		damagequantity,
		get_item_code(itemcode)	 as new_item_code,
		get_item_description(itemcode) as item_name,
		itemcode
	from  batchmaster where batchmaster.itemcode =  in_itemcode 
	and quantity > 0
	order by batchmaster.expirydate asc;
	
	SELECT  ifnull(enablebatchselection,0) as enablebatchselection FROM customermaster where customercode = in_customercode; 
END */$$
DELIMITER ;

