/* Procedure structure for procedure `sp_get_transaction_invoiceadd_invoicesummery` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_invoiceadd_invoicesummery` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_invoiceadd_invoicesummery`(
IN in_route_key INT,
IN in_transaction_key INT
)
BEGIN
SELECT primary_key AS edit_del_primary_id,
		im.actualitemcode,
		im.itemshortdescription,
		FLOOR((salesqty/im.unitspercase)) AS case_sales_qty,
		(salesqty%im.unitspercase) AS pcs_sales_qty,
		FLOOR((manualfreeqty/im.unitspercase)) AS case_free_qty,
		(manualfreeqty%im.unitspercase) AS pcs_free_qty,
		FLOOR((returnqty/im.unitspercase)) AS case_return_qty,
		(returnqty%im.unitspercase) AS pcs_return_qty,
		FLOOR((returnfreeqty/im.unitspercase)) AS case_buyback_qty,
		(returnfreeqty%im.unitspercase) AS pcs_buyback_qty,
		FLOOR((damagedqty/im.unitspercase)) AS case_damage_qty,
		(damagedqty%im.unitspercase) AS pcs_damage_qty,
		FLOOR((expiryqty/im.unitspercase)) AS case_expiry_qty,
		(expiryqty%im.unitspercase) AS pcs_expiry_qty,
		FLOOR((fixedrentqty/im.unitspercase)) AS case_rental_qty,
		(fixedrentqty%im.unitspercase) AS pcs_rental_qty,
		promoamount AS discount,
		FLOOR((freesampleqty/im.unitspercase)) AS case_promo_free_qty,
		(freesampleqty%im.unitspercase) AS pcs_promo_free_qty
	
		
	FROM invoicedetail_temp AS id 
	LEFT JOIN itemmaster AS im ON im.actualitemcode = id.itemcode
	WHERE 1=1 
	
	AND routekey =in_route_key
	AND transactionkey=in_transaction_key;
	
	
	
	
	
	
	SELECT FORMAT(IFNULL(SUM(promotiondetail_temp.promotionamount),0),2) INTO @totalsalesdiscount
		FROM promotiondetail_temp 
		WHERE transactionkey=in_transaction_key AND routekey =in_route_key 
		
		AND promotiondetail_temp.itemtransactiontype = 1;
	
	SELECT FORMAT(IFNULL(SUM(promotiondetail_temp.promotionamount),0),2) INTO @totalreturndiscount
		FROM promotiondetail_temp 
		WHERE transactionkey=in_transaction_key AND routekey =in_route_key 
		
		AND promotiondetail_temp.itemtransactiontype = 2;
	
	SELECT (@totalsalesdiscount - @totalreturndiscount) AS totaldiscount;
	
	SET @dyn_tc = CONCAT("SELECT 
         IFNULL(SUM((((salesqty/im.unitspercase)*id.salescaseprice)+((salesqty%im.unitspercase)*id.salesprice))-(((returnqty/im.unitspercase)*id.goodreturncaseprice)+((returnqty%im.unitspercase)*id.goodreturnprice))-promoamount+returnpromoamount),0) as non_tc_amount
	 FROM invoicedetail_temp AS id 
	LEFT JOIN itemmaster AS im ON im.actualitemcode = id.itemcode
	WHERE 1=1 and im.tcallowed != '1'	
	 AND routekey = ",in_route_key," AND transactionkey = ",in_transaction_key);
	
    PREPARE s3 FROM @dyn_tc;
	EXECUTE s3;	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_invoiceadd_itemprice` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_invoiceadd_itemprice` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_invoiceadd_itemprice`(
IN item_code INT,
IN customer_code INT  ,
in dec_places int,
in in_routekey int
)
BEGIN
SELECT 
itemmaster.unitspercase,
	get_deciaml_palces(IF(pd.salescaseprice IS NULL,itemmaster.caseprice,pd.salescaseprice),dec_places) AS sales_case_price ,	
	get_deciaml_palces(IF(pd.salesprice IS NULL,itemmaster.defaultsalesprice,pd.salesprice),dec_places) AS sales_pcs_price ,
	get_deciaml_palces(itemmaster.defaultgoodreturncaseprice,dec_places) AS defaultgoodreturncase_price,
	get_deciaml_palces(itemmaster.defaultgoodreturnprice,dec_places) AS defaultgoodreturn_pcs_price,
	get_deciaml_palces(IF( pd.returncaseprice IS NULL,itemmaster.returncaseprice,pd.returncaseprice),dec_places) AS return_case_price,
	get_deciaml_palces(IF( pd.returnprice IS NULL,itemmaster.defaultreturnprice,pd.returnprice),dec_places) AS return_pcs_price,
	
	
	get_deciaml_palces(itemmaster.costcaseprice,dec_places) as costcaseprice    ,
	get_deciaml_palces(itemmaster.defaultcostprice,dec_places) as defaultcostprice,
	
	((ifnull(inventorysummarydetail.loadqty,0) + ifnull(inventorysummarydetail.loadaddqty,0) - ifnull(inventorysummarydetail.loadcutqty,0) -   ifnull(inventorysummarydetail.saleqty,0) + ifnull(inventorysummarydetail.returnqty,0) +ifnull(inventorysummarydetail.returnfreeqty,0) - ifnull(inventorysummarydetail.freesampleqty,0))/itemmaster.unitspercase) as case_val,
	((IFNULL(inventorysummarydetail.loadqty,0) + IFNULL(inventorysummarydetail.loadaddqty,0) - IFNULL(inventorysummarydetail.loadcutqty,0) -   IFNULL(inventorysummarydetail.saleqty,0) + IFNULL(inventorysummarydetail.returnqty,0) +IFNULL(inventorysummarydetail.returnfreeqty,0) - IFNULL(inventorysummarydetail.freesampleqty,0))%itemmaster.unitspercase) AS pieses_val,
	(IFNULL(inventorysummarydetail.loadqty,0) + IFNULL(inventorysummarydetail.loadaddqty,0) - IFNULL(inventorysummarydetail.loadcutqty,0) -   IFNULL(inventorysummarydetail.saleqty,0) + IFNULL(inventorysummarydetail.returnqty,0) +IFNULL(inventorysummarydetail.returnfreeqty,0) - IFNULL(inventorysummarydetail.freesampleqty,0)) AS availableqty
	FROM itemmaster 
	left join  inventorysummarydetail
	on itemmaster.actualitemcode = inventorysummarydetail.itemcode and inventorysummarydetail.routekey = in_routekey
	LEFT JOIN pricingdetail1 pd ON pd.itemcode = actualitemcode AND 
		pd.customerpricingkey =(SELECT IFNULL(customerpricing1.customerpricingkey,0) FROM customerpricing1 
	JOIN customermaster ON customerpricing1.pricingplankey = customermaster.pricingkey AND customercode = customer_code)
	WHERE itemmaster.actualitemcode=item_code ;
	
	SELECT allowbatchentry FROM itemmaster WHERE actualitemcode = item_code;
    
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_invoiceadd_payamountbyuser` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_invoiceadd_payamountbyuser` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_invoiceadd_payamountbyuser`(
 IN in_transaction_key INT,
 IN in_routekey INT,
 IN decimal_palace INT
)
BEGIN
	SELECT IFNULL(SUM(get_deciaml_palces(sales_amount,decimal_palace)),0) AS mini_amount FROM invoicedetail_temp 
		LEFT JOIN itemmaster ON itemmaster.actualitemcode = invoicedetail_temp.itemcode
		WHERE 
		itemmaster.tcallowed=0 AND 
		transactionkey=in_transaction_key AND 
		routekey =in_routekey;
    
    
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_invoiceadd_promotionplan` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_invoiceadd_promotionplan` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_invoiceadd_promotionplan`(
	IN in_customer_code BIGINT,
	in in_visitkey int,
	in in_routekey int
	
)
BEGIN
	declare in_pricingkey bigint;
	select promotionkey into in_pricingkey  from customermaster where customercode = in_customer_code;	
	
	SELECT 	promoplandetail.plannumber, promoplandetail.plandescription,promokeydetail.primary_key
	,promoplandetail.assignmentnumber,promokeydetail.rangebasis,promokeydetail.promotionkey,
	promokeydetail.promotiontypecode,promokeydetail.qualificationgroup,promokeydetail.assignmentgroup,
	
	(SELECT if(COUNT(*) > 0, 1, 0)  FROM invoicedetail_temp , productgroupdetail 
	WHERE   invoicedetail_temp.itemcode = productgroupdetail.itemcode 
	AND invoicedetail_temp.routekey = in_routekey AND invoicedetail_temp.visitkey = in_visitkey
	AND 
		if(promokeydetail.qualificationgroup = 1 , '1=1 group by invoicedetail_temp.itemcode' ,productgroupdetail.groupnumber = promokeydetail.qualificationgroup)
			 ) AS qualified_promotion
	
	FROM promokeydetail
	LEFT JOIN promoplandetail ON promoplandetail.plannumber = promokeydetail.plannumber
	WHERE 	promokeydetail.promotionkey =in_pricingkey;
	
	
	
	SELECT (
		(SELECT IF(COUNT(*) > 0, 1, 0)  FROM invoicedetail_temp , productgroupdetail 
		WHERE   invoicedetail_temp.itemcode = productgroupdetail.itemcode 
		AND invoicedetail_temp.routekey = in_routekey AND invoicedetail_temp.visitkey = in_visitkey
		AND 
		IF(promokeydetail.qualificationgroup = 1 , '1=1 group by invoicedetail_temp.itemcode' ,productgroupdetail.groupnumber = promokeydetail.qualificationgroup)
		)) AS qualified_promotion
	
	FROM promokeydetail
	LEFT JOIN promoplandetail ON promoplandetail.plannumber = promokeydetail.plannumber
	WHERE 
	 	promokeydetail.promotionkey =in_pricingkey
		GROUP BY qualified_promotion;
		
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_invoiceadd_promotion_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_invoiceadd_promotion_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_invoiceadd_promotion_detail`(
in in_plannumber int
)
BEGIN
SELECT key1.plannumber,key1.assignmentnumber,key1.assignmentgroup, 
	key1.promotiontypecode,key1.qualificationgroup,
	key1.rangebasis,
	promotionassignmentadvanced.rangelow,  promotionassignmentadvanced.rangehigh,
	promotionassignmentadvanced.promotionamount ,  promoplandetail.plandescription,
	DATE_FORMAT(key1.startdate,"%d-%m-%Y")as startdate, DATE_FORMAT(key1.enddate,'%d-%m-%Y') as enddate
FROM promokeydetail AS key1  
LEFT JOIN promoplandetail ON  promoplandetail.plannumber = key1.plannumber
LEFT JOIN promotionassignmentadvanced ON  promotionassignmentadvanced.plannumber =key1.plannumber
AND promotionassignmentadvanced.assignmentnumber = key1.assignmentnumber
WHERE key1.plannumber=in_plannumber;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_invoiceadd_promotion_review` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_invoiceadd_promotion_review` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_invoiceadd_promotion_review`(
IN in_visitkey INT,
IN in_routekey INT,
IN in_transaction_key INT,
IN in_customer_code INT
)
BEGIN
DECLARE total_amount DECIMAL(18,4);
DECLARE in_qualification_group VARCHAR(255);
DECLARE in_qualification_group1 VARCHAR(255);
		
		
			SELECT  REPLACE(FORMAT(SUM((((FLOOR(salesqty/im.unitspercase)*id.salescaseprice)+
			((salesqty%im.unitspercase)*id.salesprice))-
			((FLOOR(returnqty/im.unitspercase)*id.goodreturncaseprice)+
			((returnqty%im.unitspercase)*id.goodreturnprice))-((FLOOR(damagedqty/im.unitspercase)*im.returncaseprice)+
			((damagedqty%im.unitspercase)*id.returnprice)))),2),",","") AS SalesAmount
			
			
			INTO total_amount
			FROM invoicedetail_temp AS id
			INNER JOIN itemmaster  AS im ON im.actualitemcode  = id.itemcode
								   
			WHERE 	 id.routekey =in_routekey
			AND id.visitkey  =in_visitkey;
    
		
		
		
		SELECT promotiontypecode,total_amount,promotionamount,
		(total_amount - promotionamount) AS new_invoice_amount ,promotiondetail_temp.promotionplannumber
		
		 FROM promotiondetail_temp  
		WHERE promotiondetail_temp.routekey =in_routekey
			AND promotiondetail_temp.visitkey=in_visitkey  
			AND promotiondetail_temp.transactionkey =in_transaction_key
			AND promotiondetail_temp.itemtransactiontype IN(1,2)
		GROUP BY promotiontypecode,promotiondetail_temp.promotionplannumber;
		
		SELECT promotiondetail_temp.*,promoplandetail.plandescription ,
		IF(promotiondetail_temp.promotiontypecode = 1 OR promotiondetail_temp.promotiontypecode = 2 OR promotiondetail_temp.promotiontypecode  = 0 ,get_item_description(promotiondetail_temp.itemcode),"") AS item_desc,
		get_item_code(promotiondetail_temp.itemcode) AS new_item_code,
		promotiondetail_temp.promotionper
		FROM promotiondetail_temp  ,promoplandetail
		WHERE promoplandetail.plannumber =  promotiondetail_temp.promotionplannumber
		AND promotiondetail_temp.routekey =in_routekey
			AND promotiondetail_temp.visitkey=in_visitkey  
			AND promotiondetail_temp.transactionkey =in_transaction_key
			AND promotiondetail_temp.itemtransactiontype IN(1,2)			
		ORDER BY promotiontypecode,promotiondetail_temp.itemtransactiontype;
		
	
		
		DROP TEMPORARY TABLE IF EXISTS temp_promotion_review;
		CREATE TEMPORARY TABLE temp_promotion_review (
			case_sales_qty INT , 
			pcs_sales_qty INT, 
			itemcode INT , 
			itemshortdescription VARCHAR(250), 
			itemcode1 INT , 
			new_item_code VARCHAR(250) , 
			itemtransactiontype INT,
			plan_no INT,
			rangebasis INT
		);
		
		
		
	   
	   SET @del1 = CONCAT("INSERT INTO temp_promotion_review 
				SELECT 
					invoicedetail_temp.salesqty AS case_sales_qty,
					itemmaster.unitspercase AS pcs_sales_qty,
					invoicedetail_temp.itemcode,	itemmaster.itemshortdescription	,
					itemmaster.actualitemcode as itemcode,
					get_item_code(itemmaster.actualitemcode) AS new_item_code,
					1 as itemtransactiontype ,promotiondetail_temp.promotionplannumber,
					promokeydetail.rangebasis
				FROM promokeydetail 
				INNER JOIN promotiondetail_temp 
				ON promotiondetail_temp.promotionplannumber=promokeydetail.plannumber 
				AND promotiondetail_temp.promotiontypecode = 7
				AND promotiondetail_temp.visitkey= ",in_visitkey,"
				AND promotiondetail_temp.routekey = ",in_routekey," 
				LEFT JOIN invoicedetail_temp ON FIND_IN_SET(invoicedetail_temp.itemcode,promotiondetail_temp.itemcode)
				 AND invoicedetail_temp.routekey = ",in_routekey,"
				  AND invoicedetail_temp.visitkey  = ",in_visitkey,"
				
				 --  AND FIND_IN_SET(invoicedetail_temp.itemcode,promotiondetail_temp.itemcode)
				JOIN itemmaster 
				ON itemmaster.actualitemcode IN (promotiondetail_temp.itemcode)
				 WHERE promokeydetail.promotionkey = (SELECT promotionkey 
									FROM customermaster
									 WHERE customercode = ",in_customer_code,")
				AND itemtransactiontype=1
				AND promotiondetail_temp.promotiontypecode = 7");
	   
	   PREPARE s1 FROM @del1;
	   EXECUTE s1;
	   
	   SET @del1 = CONCAT("INSERT INTO temp_promotion_review 
				SELECT 
					invoicedetail_temp.returnqty AS case_sales_qty,
					itemmaster.unitspercase AS pcs_sales_qty,
					invoicedetail_temp.itemcode,	itemmaster.itemshortdescription	,
					itemmaster.actualitemcode as itemcode,
					get_item_code(itemmaster.actualitemcode) AS new_item_code,
					2 as itemtransactiontype,promotiondetail_temp.promotionplannumber,
					promokeydetail.rangebasis
				FROM promokeydetail 
				INNER JOIN promotiondetail_temp 
				ON promotiondetail_temp.promotionplannumber=promokeydetail.plannumber 
				AND promotiondetail_temp.promotiontypecode = 7
				AND promotiondetail_temp.visitkey= ",in_visitkey,"
				AND promotiondetail_temp.routekey = ",in_routekey," 
				LEFT JOIN invoicedetail_temp ON FIND_IN_SET(invoicedetail_temp.itemcode,promotiondetail_temp.itemcode)
				 AND invoicedetail_temp.routekey = ",in_routekey,"
				  AND invoicedetail_temp.visitkey  = ",in_visitkey,"
				  
				  -- AND FIND_IN_SET(invoicedetail_temp.itemcode,promotiondetail_temp.itemcode)	
				 JOIN itemmaster 
				ON itemmaster.actualitemcode IN (promotiondetail_temp.itemcode)
				 WHERE promokeydetail.promotionkey = (SELECT promotionkey 
									FROM customermaster
									 WHERE customercode = ",in_customer_code,")
				AND itemtransactiontype=2
				AND promotiondetail_temp.promotiontypecode = 7");
	  
	   PREPARE s2 FROM @del1;
	   EXECUTE s2;
	   
	   SELECT * FROM temp_promotion_review;
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_invoiceadd_returnavailable_qty` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_invoiceadd_returnavailable_qty` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_invoiceadd_returnavailable_qty`(
IN in_itemcode INT ,
IN in_customercode INT,
IN in_transactiontypecode INT,
IN in_visitkey BIGINT,
IN in_routekey INT
)
BEGIN
	DECLARE trans_typecode TEXT DEFAULT "";
	IF in_transactiontypecode = 15 THEN
		SET trans_typecode = 'bt.quantity - bt.rentalquantity - bt.freequantity + bt.returnquantity + bt.buybackquantity - bt.promoquantity';
	ELSEIF in_transactiontypecode = 16 THEN
		SET trans_typecode = 'bt.quantity - bt.salesquantity - bt.rentalquantity + bt.returnquantity + bt.buybackquantity - bt.promoquantity';
	ELSEIF in_transactiontypecode = 17 THEN
		SET trans_typecode = 'bt.quantity - bt.salesquantity - bt.rentalquantity - bt.freequantity + bt.returnquantity + bt.buybackquantity';
	ELSEIF in_transactiontypecode = 18 THEN
		SET trans_typecode = 'bt.quantity - bt.salesquantity - bt.rentalquantity - bt.freequantity + bt.buybackquantity - bt.promoquantity';
	ELSEIF in_transactiontypecode = 19 THEN
		SET trans_typecode = 'bt.quantity - bt.salesquantity - bt.rentalquantity - bt.freequantity + bt.returnquantity - bt.promoquantity';
	ELSEIF in_transactiontypecode = 20 THEN
		SET trans_typecode = 'bt.quantity - bt.salesquantity - bt.rentalquantity - bt.freequantity + bt.returnquantity + bt.buybackquantity - bt.promoquantity';
	ELSEIF in_transactiontypecode = 21 THEN
		SET trans_typecode = 'bt.quantity - bt.salesquantity - bt.rentalquantity - bt.freequantity + bt.returnquantity + bt.buybackquantity - bt.promoquantity';
	ELSEIF in_transactiontypecode = 22 THEN
		SET trans_typecode = 'bt.quantity - bt.salesquantity - bt.freequantity + bt.returnquantity + bt.buybackquantity - bt.promoquantity';
	END IF;
	
	
	
	
	SET @dyn_sql = CONCAT("SELECT
		bt.quantity,
		FLOOR((bt.quantity/get_name_type_base(bt.itemcode,5))) AS case_qty,
		(bt.quantity%get_name_type_base(bt.itemcode,5)) AS pcs_qty,
		get_name_type_base(bt.itemcode,5) AS upc,
		bt.batchdetailkey,
		bt.batchnumber,
		DATE_FORMAT(bt.expirydate,'%d-%m-%Y') AS expirydate,
		bt.expirydate AS expirydate1,
		bt.damagequantity,
		get_item_code(bt.itemcode)	 AS new_item_code,
		get_item_description(bt.itemcode) AS item_name,
		bt.itemcode,
		bet.quantity as batch_qnt,",
		trans_typecode," as available_qnt
		-- (bt.quantity - bt.salesquantity - bt.rentalquantity - bt.freequantity + bt.returnquantity + bt.buybackquantity - bt.promoquantity) as available_qnt
	FROM  batchmaster_temp AS bt
	LEFT JOIN batchexpirydetail_temp AS bet
		ON bet.batchnumber = bt.batchnumber
			AND bet.itemcode = bt.itemcode
			AND bt.visitkey = bet.visitkey
			AND bet.transactiontypecode = ",in_transactiontypecode,"
	WHERE bt.itemcode = ", in_itemcode ,"
	AND bt.visitkey = ",in_visitkey," 
	AND bt.routekey = ",in_routekey," 
	ORDER BY bt.expirydate ASC");
	
	 
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
		
	SELECT  IFNULL(enablebatchselection,0) AS enablebatchselection ,
		get_name_type_base(in_itemcode,5) AS unit,
		in_itemcode AS itemcode,
		get_item_code(in_itemcode) AS new_item_code,
		get_item_description(in_itemcode) AS item_name 
	FROM customermaster 
	WHERE customercode = in_customercode; 
	
	SELECT allowbatchentry FROM itemmaster WHERE actualitemcode = in_itemcode;
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_invoiceadd_settings` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_invoiceadd_settings` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_invoiceadd_settings`(
IN in_customer_code INT,
IN dec_places INT
)
BEGIN  
	SELECT IFNULL(enablesigcapture,0) AS 'Enable_Signature_Capture' , 
		IFNULL(enablereturnstrxn,0) AS 'Enable_Good_Returns', 
		IFNULL(enablepromotrxn,0) AS 'Enable_Free', 
		IFNULL(enablerental,0) AS 'Enable_Rental', 
		IFNULL(enablesalestrxn,0) AS 'Enable_Sales', 
		IFNULL(enabledamagedreturns,0) AS 'Enable_Damage_Returns', 
		IFNULL(enableinvoicecomment,0) AS 'Enable_invoice_comment', 
		IFNULL(enablebuybackfree,0) AS 'Enable_Buy_Back_Free', 
		IFNULL(enablepromoeditinvs,0) AS 'Enable_Sales_Promotion',
		IFNULL(enforcepromotion,0) AS  'enforcepromotion',
		invoicepaymentterms AS 'invoice_paynent_terms',
		get_deciaml_palces(creditlimit,dec_places) AS 'customer_credit_limit',
		enablepriceeditinvs AS 'Enable_Edit_Price_Invs',
		IFNULL(enablepromoeditords,0) AS 'Enable_Order_Promotion',
		CASE invoicepaymentterms 
			WHEN 0 THEN 'CASH Only'
		        WHEN 1 THEN 'CASH or CHEQUE' 
		        WHEN 2 THEN 'CHARGE Only (GC)' 
		        WHEN 3 THEN 'TC (CASH or CHEQUE)' 
		        WHEN 4 THEN 'TC (CASH Only)' 
		 ELSE 'CASH Only' END AS invoice_paynent_terms_text,
		  creditlimitdays AS customer_credit_day,
		   CONCAT(customeraddress1," ", customeraddress2) AS customer_address,
		   allowcashoncreditexceed AS 'Allow_Cash_If_Credit_Exceeds'
	FROM customermaster
		WHERE customercode =in_customer_code;
    
END */$$
DELIMITER ;

