/* Procedure structure for procedure `sp_get_transaction_invoice_batchdetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_invoice_batchdetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_invoice_batchdetail`(
	IN rwcnt INT,	
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT	
	)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'id.transactionkey';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'ih.*';
	END IF;
	
	SET @dyn_cnt = CONCAT("SELECT COUNT(*) AS counter FROM invoicedetail AS id
	JOIN batchexpirydetail AS bd ON bd.batchdetailkey = id.batchdetailkey AND id.itemcode=bd.itemcode
	JOIN itemmaster AS im ON im.actualitemcode = bd.itemcode
	WHERE 1=1 ",table_where);
	
    PREPARE s1 FROM @dyn_cnt;
	EXECUTE s1;	
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM invoicedetail AS id
	JOIN batchexpirydetail AS bd ON bd.batchdetailkey = id.batchdetailkey AND id.itemcode=bd.itemcode
	JOIN itemmaster AS im ON im.actualitemcode = bd.itemcode
	WHERE 1=1  ",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	
    PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;
	    
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_processload` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_processload` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_processload`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT ,	
	IN tran_key BIGINT )
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'ith.routecode';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'ith.*';
	END IF;
	  
	SELECT routekey INTO @routekey FROM invoiceheader WHERE transactionkey =  tran_key;
	
	SET @dyn_cnt = CONCAT("SELECT COUNT(ith.detailkey) AS counter FROM inventorytransactionheader AS ith
			LEFT JOIN inventorytransactiondetail AS itd ON itd.detailkey = ith.detailkey
			LEFT JOIN itemmaster AS im ON im.actualitemcode = itd.itemcode			
	WHERE 1=1  ",table_where ," GROUP BY loadnumber,ith.routecode" );
        PREPARE s1 FROM @dyn_cnt;
	EXECUTE s1;	
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM inventorytransactionheader AS ith
			LEFT JOIN inventorytransactiondetail AS itd ON itd.detailkey = ith.detailkey
			LEFT JOIN itemmaster AS im ON im.actualitemcode = itd.itemcode			
	WHERE 1=1  ",table_where,  " GROUP BY loadnumber,ith.routecode ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	
         PREPARE s2 FROM @dyn_sql;	
	 EXECUTE s2;	
	
	SELECT @dyn_sql;
  
  END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_processload_loaditemdetail_grid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_processload_loaditemdetail_grid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_processload_loaditemdetail_grid`(
IN rwcnt INT,	
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT
	
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'actualitemcode';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'im.*';
	END IF;
	  
	
	
	SET @dyn_cnt = CONCAT("select count(*) AS counter from ( SELECT COUNT(actualitemcode) AS counter1 FROM itemmaster AS im 
	INNER JOIN startingloaddetail sld ON im.actualitemcode = sld.itemcode
	WHERE 1=1   ",table_where,") as a");
	
	
      PREPARE s1 FROM @dyn_cnt;
	 EXECUTE s1;	
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM itemmaster AS im 
	INNER JOIN startingloaddetail sld ON im.actualitemcode = sld.itemcode
	WHERE 1=1   ",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	
	
     PREPARE s2 FROM @dyn_sql;	
	 EXECUTE s2;	
	select @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_salesorderadd_itemprice` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_salesorderadd_itemprice` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_salesorderadd_itemprice`(
IN item_code INT,
IN customer_code INT  ,
IN dec_places INT
)
BEGIN
SELECT 
	itemmaster.unitspercase,
	get_deciaml_palces(IF(pd.salescaseprice IS NULL,itemmaster.caseprice,pd.salescaseprice),dec_places) AS sales_case_price ,	
	get_deciaml_palces(IF(pd.salesprice IS NULL,itemmaster.defaultsalesprice,pd.salesprice),dec_places) AS sales_pcs_price ,
	get_deciaml_palces(itemmaster.defaultgoodreturncaseprice,dec_places) AS defaultgoodreturncase_price,
	get_deciaml_palces(itemmaster.defaultgoodreturnprice,dec_places) AS defaultgoodreturn_pcs_price,
	get_deciaml_palces(IF( pd.returncaseprice IS NULL,itemmaster.returncaseprice,pd.returncaseprice),dec_places) AS return_case_price,
	get_deciaml_palces(IF( pd.returnprice IS NULL,itemmaster.defaultreturnprice,pd.returnprice),dec_places) AS return_pcs_price,
	
	
	get_deciaml_palces(itemmaster.costcaseprice,dec_places) AS costcaseprice    ,
	get_deciaml_palces(itemmaster.defaultcostprice,dec_places) AS defaultcostprice
		
	
	
	FROM itemmaster 
	LEFT JOIN pricingdetail1 pd ON pd.itemcode = actualitemcode AND 
		pd.customerpricingkey =(SELECT IFNULL(customerpricing1.customerpricingkey,0) FROM customerpricing1 
	JOIN customermaster ON customerpricing1.pricingplankey = customermaster.pricingkey AND customercode = customer_code)
	WHERE itemmaster.actualitemcode=item_code ;
	
	
    
END */$$
DELIMITER ;

