/* Procedure structure for procedure `sp_get_year` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_year` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_year`(
IN form VARCHAR(50)
)
BEGIN
	IF form = 'ACCOUNT' THEN
		SELECT DISTINCT(YEAR(transactiondate)) AS cur_year FROM customerinvoice ORDER BY 1 DESC;
		
	ELSEIF form = 'DATA' THEN
		SELECT DISTINCT(YEAR(routestartdate)) AS cur_year FROM startendday ORDER BY 1 DESC;	
	END IF;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_hhctransaction_cloudtran_addprocessload` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_hhctransaction_cloudtran_addprocessload` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_hhctransaction_cloudtran_addprocessload`()
BEGIN
	SELECT routecode AS id, CONCAT(routecode,' -- ',routename) AS val FROM routemaster 
	WHERE 
		activestatus = '1' 
		AND routetmpl = 0 
		AND   
		routecode IN (
				SELECT startendday.routecode FROM startendday WHERE
					-
					startendday.routeclosed =0
					AND startendday.triptype = 1
					GROUP BY startendday.routecode
			     );
    
    
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_import_customer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_import_customer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_customer`()
    MODIFIES SQL DATA
BEGIN
START TRANSACTION ;
 
CREATE TEMPORARY TABLE IF NOT EXISTS TempNewCustomer AS 
SELECT * FROM rp_customer WHERE customercode NOT IN (SELECT alternatecode FROM customermaster);
INSERT INTO CustomerMaster (ANCustomerCode, TYPE, HeadOfficeCode, RouteCode, CustomerName, 
ARBCustomerName, CustomerAddress1, ARBCustomerAddress1, CustomerAddress2, CustomerAddress3,ContactName, 
ArbContactName, InvoicePaymentTerms,   CreditLimitDays, CreditLimit,ActiveCustomer, Memo1, Memo2, 
AlternateCode,EnablePromoTrxn,EnableBuyBackFree,ForceStockCapture,EnableDraftCopy,enablereturnstrxn,
enabledelayprint,enablesigcapture,enablearcollection,enabledamagedreturns,enablebatchselection,
printsequence,invoicepriceprint,enablepromoeditinvs,enablepromoeditords,MDAT,pricingkey,enablesalestrxn,DivisionCode,
graceperiod,Territory	,Class	,Region	,Cust_Disc_Code	,Transaction_Anals3	,Alpha	,Transaction_Anals2	,
Control	,GPSSaveCount	,Grouping_Code	,Outlet_Quality	,StatementDays	,Analysis2,alternateroutecode,ALTERNATEPRICINGKEY,chaincode,enableinvoicecomment	)
SELECT CustomerCode,1,HeadOfficeCode,NULL,CustomerName,CustomerName,CustomerAddress1,
CustomerAddress1,CustomerAddress2,CustomerAddress3,ContactName,ContactName,InvoicePaymentTerms, 
Credit_Days,creditlimit  ,Active,Memo1,
Memo2,CustomerCode, 2,0,0,0,4,1,2,1,3,0,2,1,3,1,NOW(),NOW(),1,Division_Code,GracePeriod,
Territory,Class,	Region,	Cust_Disc_Code,	Transaction_Anals3,	Alpha,
Transaction_Anals2,	control_account,1,Grouping_Code,	Outlet_Quality,Credit_Days,
OrderLocation,RouteCode,PricingKey,'',1 FROM TempNewCustomer ;
COMMIT;
CREATE TEMPORARY TABLE IF NOT EXISTS TempExistingCustomer AS 
SELECT * FROM rp_customer WHERE customercode  IN (SELECT alternatecode FROM customermaster);
START TRANSACTION ;
UPDATE customermaster cm INNER JOIN TempExistingCustomer tc ON tc.customercode=cm.alternatecode
SET 
cm.Grouping_Code	= tc.Grouping_Code,
cm.Outlet_Quality	= tc.Outlet_Quality,
cm.StatementDays	= tc.Credit_Days,
cm.Analysis2	= tc.OrderLocation,
cm.alternateroutecode	= tc.RouteCode,
cm.ALTERNATEPRICINGKEY	= tc.PricingKey,
cm.DivisionCode 	= tc.Division_Code,
cm.GracePeriod	= tc.graceperiod,
cm.Territory	= tc.Territory,
cm.Class	= tc.Class,
cm.Region	= tc.Region,
cm.Cust_Disc_Code	= tc.Cust_Disc_Code,
cm.Transaction_Anals3	= tc.Transaction_Anals3,
cm.Alpha	= tc.Alpha,
cm.Transaction_Anals2	= tc.Transaction_Anals2,
cm.Control	= tc.control_account,
cm.CustomerName	= tc.CustomerName,
cm.ARBCustomerName	= tc.CustomerName,
cm.CustomerAddress1	= tc.CustomerAddress1,
cm.ARBCustomerAddress1	= tc.CustomerAddress1,
cm.CustomerAddress2	= tc.CustomerAddress2,
cm.CustomerAddress3	= tc.CustomerAddress3,
cm.ContactName	= tc.ContactName,
cm.ArbContactName	= tc.ContactName,
cm.InvoicePaymentTerms	= tc.InvoicePaymentTerms,
cm.CreditLimitDays	= tc.Credit_Days,
cm.ActiveCustomer 	= tc.Active,
cm.Memo1	= tc.Memo1,
cm.Memo2	= tc.Memo2,
cm.mdat=NOW()
 WHERE cm.ANCustomerCode= tc.customercode;
 
COMMIT;
CREATE TEMPORARY TABLE IF NOT EXISTS TempNewChainCustomer AS 
SELECT * FROM rp_chain WHERE CONCAT(customercode,ChainCode) NOT IN (SELECT alternatecode FROM customermaster);
START TRANSACTION ;
 INSERT INTO CustomerMaster (ANCustomerCode, TYPE, HeadOfficeCode, RouteCode, CustomerName, 
	ARBCustomerName, CustomerAddress1, ARBCustomerAddress1, CustomerAddress2, CustomerAddress3,ContactName, 
	ArbContactName, InvoicePaymentTerms,   CreditLimitDays, CreditLimit,ActiveCustomer, Memo1, Memo2, 
	AlternateCode,EnablePromoTrxn,EnableBuyBackFree,ForceStockCapture,EnableDraftCopy,enablereturnstrxn,
	enabledelayprint,enablesigcapture,enablearcollection,enabledamagedreturns,enablebatchselection,
	printsequence,invoicepriceprint,enablepromoeditinvs,enablepromoeditords,MDAT,pricingkey,enablesalestrxn,DivisionCode,graceperiod,Territory	,Class	,Region	,Cust_Disc_Code	,Transaction_Anals3	,Alpha	,Transaction_Anals2	,Control	,GPSSaveCount	,Grouping_Code	
	,Outlet_Quality	,StatementDays	,Analysis2,alternateroutecode,ALTERNATEPRICINGKEY,chaincode,cdat,created,modified,enableinvoicecomment )
 SELECT DISTINCT  CONCAT_WS('',tc.customercode,tc.chaincode) ,2,cm.customercode,NULL,tc.CustomerName,tc.CustomerName,cm.CustomerAddress1,cm.CustomerAddress1,cm.CustomerAddress2,cm.CustomerAddress3,cm.ContactName,cm.ContactName,cm.InvoicePaymentTerms, cm.creditlimitdays,
  cm.creditlimit  ,cm.Activecustomer,cm.Memo1,	cm.Memo2,CONCAT_WS('',tc.customercode,tc.chaincode), 2,0,0,0,4,1,2,1,3,0,2,1,3,1,NOW(),NULL,1,cm.Divisioncode,cm.GracePeriod,cm.Territory,cm.Class,	cm.Region,	cm.Cust_Disc_Code,	cm.Transaction_Anals3,	cm.Alpha,
  	cm.Transaction_Anals2,	cm.control,1,cm.Grouping_Code,	cm.Outlet_Quality,cm.Creditlimitdays,cm.Analysis2,cm.alternateroutecode,cm.ALTERNATEPRICINGKEY   ,
	tc.chaincode,NOW(),'admin','admin',1
	FROM TempNewChainCustomer tc INNER JOIN CustomerMaster cm ON cm.alternatecode=tc.customercode;
	
	COMMIT;
	START TRANSACTION ;
UPDATE customermaster cm INNER JOIN TempNewChainCustomer tc ON tc.CustomerCode=cm.alternatecode
 SET TYPE=3 ,
 cm.headofficecode=cm.customercode,
 cm.creditlimit = CASE cm.creditlimit WHEN  -1 THEN 1 WHEN -2 THEN 99999 ELSE cm.creditlimit END ;
COMMIT;	
 
CREATE TEMPORARY TABLE IF NOT EXISTS TempExistingChainCustomer AS 
SELECT * FROM rp_chain WHERE CONCAT_WS('',customercode,chaincode)  IN (SELECT alternatecode FROM customermaster);
START TRANSACTION ;
UPDATE customermaster cm INNER JOIN TempExistingChainCustomer tc ON CONCAT_WS('',tc.customercode,tc.chaincode)=cm.alternatecode
SET 
cm.CustomerName	= tc.CustomerName,
cm.ARBCustomerName	= tc.CustomerName,
cm.mdat=NOW(),
cm.chaincode=tc.chaincode
 WHERE cm.ANCustomerCode= CONCAT_WS('',tc.customercode,tc.chaincode);
 
 COMMIT;
 START TRANSACTION ;
 
 UPDATE CUSTOMERMASTER CM INNER JOIN ROUTEMASTER RM ON RM.ALTERNATEROUTECODE=CM.ALTERNATEROUTECODE SET CM.ROUTECODE=RM.ROUTECODE;
UPDATE CUSTOMERMASTER CM INNER JOIN customerpricingplanheader1 RM ON RM.ALTERNATECODE=CM.ALTERNATEPRICINGKEY SET CM.PRICINGKEY=RM.PRICINGPLANKEY;
  COMMIT ;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_import_CustomerInvoice` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_import_CustomerInvoice` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_CustomerInvoice`()
BEGIN
 
DECLARE var_invoicenumber CHAR(10);
DECLARE var_routecode CHAR(10);
DECLARE var_salesmancode CHAR(10);
DECLARE var_transactiondate DATE;
DECLARE var_customercode CHAR(10);
DECLARE var_totalinvoiceamount FLOAT;
DECLARE var_invoicebalance FLOAT;
DECLARE var_paymenttype INT(11);
DECLARE var_pdcindicator INT(11);
DECLARE var_refernce CHAR(10);
DECLARE var_analysis_codes2 CHAR(10);
DECLARE var_custtype CHAR(10);
DECLARE var_max_transactionkey BIGINT;
DELETE FROM customerinvoice;
	 
	INSERT INTO CustomerInvoice(TransactionKey,TransactionType,DocumentNumber,InvoiceNumber,TransactionDate,CustomerCode,
RouteCode,
SalesmanCode,TotalInvoiceAmount,TotalSalesAmount,InvoiceBalance,PaymentType,VoidFlag,PaymentStatus,HHCInvoiceNumber,
Remarks1,Remarks2,RouteStartDate,ERPReferenceNumber,MDat,AmountPaid,duedate)
SELECT  @curRank := @curRank + 1 AS 'rank',2 AS transactiontype,@curRank  AS docnumber,
@curRank  AS invoicenumber,transactiondate,
 sfacst.customercode  ,rm.routecode,
rm.salesmancode,totalinvoiceamount,totalinvoiceamount,invoicebalance,2,0,0,totalinvoiceamount,
refernce,'Balance from ERP',NULL,invoicenumber,NOW(),
totalinvoiceamount-invoicebalance,DATE_ADD(transactiondate,INTERVAL sfacst.statementdays DAY ) AS duedate
FROM rp_outstanding rec 
INNER JOIN customermaster sfacst ON sfacst.alternatecode  =rec.customercode
AND sfacst.customercode IS NOT NULL
INNER JOIN Salesman sm ON sm.alternatesalesmancode=rec.salesmancode
INNER JOIN routemaster rm ON rm.Salesmancode=sm.Salesmancode
INNER JOIN (SELECT @curRank := 0) r ON 1=1;
update CUSTOMERMASTER CM set balance = (select sum(ci.invoicebalance) from customerinvoice ci where ci.customercode= CM.CustomerCode);
   
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_import_CustomerPrice` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_import_CustomerPrice` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_CustomerPrice`()
BEGIN
INSERT INTO customerpricingplanheader1
(pricingplankey,description,arbdescription,alternatecode,activeindicator)
SELECT  DISTINCT  @curRank := @curRank + 1 AS sfapricingkey,rp.description,'',rp.pricingkey,STATUS FROM 
(SELECT DISTINCT pricingkey,description,STATUS FROM rp_sppricing WHERE description !='') rp 
INNER JOIN (SELECT @curRank := 0) r ON 1=1 ORDER BY pricingkey;
INSERT INTO customerpricing1
(CustomerPricingKey,PricingPlanKey,Sequencecode,Description,ARBDescription,active,startdate,enddate)
SELECT  DISTINCT  @curRank := @curRank + 1 AS  pricingkeysfa,pricingplankey,
1,description,arbdes,STATUS,
startdate,enddate
FROM (SELECT DISTINCT ph.pricingplankey,
1,cp.description,cp.description AS arbdes,STATUS,
startdate,enddate FROM  rp_sppricing cp INNER JOIN customerpricingplanheader1 ph
ON TRIM(ph.arbdescription) = TRIM(cp.pricingkey))a 
INNER JOIN (SELECT @curRank := 0) r ON 1=1 ORDER BY pricingkeysfa;
INSERT INTO pricingplanheader1(CustomerPricingKey,Description,ARBDescription,TYPE,active)
SELECT DISTINCT CustomerPricingKey,Description,Description,1,1 FROM customerpricing1;
INSERT INTO pricingdetail1(CustomerPricingKey,ItemCode,SalesPrice,ReturnPrice,RetailPrice,
SalesCasePrice,ReturnCasePrice)
SELECT  cpr.CustomerPricingKey,im.actualitemcode,cs.specialpieceprice,cs.specialreturnprice,cs.specialpieceprice,
cs.specialcaseprice,cs.specialreturncaseprice
FROM  rp_sppricing cs INNER JOIN customerpricingplanheader1 cph ON
TRIM(cph.arbdescription) =TRIM(cs.pricingkey)
INNER JOIN customerpricing1 cpr ON cpr.PricingPlanKey=cph.pricingplankey
INNER JOIN itemmaster im ON im.alternatecode =cs.itemcode;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_import_customer_from_oracle` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_import_customer_from_oracle` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_customer_from_oracle`(									
 IN var_Division_Code VARCHAR(10),									
  IN var_CustomerCode VARCHAR(20),									
  IN var_HeadOfficeCode VARCHAR(20) ,									
  IN var_RouteCode VARCHAR(10) ,									
  IN var_CustType CHAR(10) ,									
  IN var_CustomerName CHAR(50) ,									
  IN var_CustomerAddress1 CHAR(50) ,									
  IN var_CustomerAddress2 CHAR(50) ,									
  IN var_CustomerAddress3 CHAR(50) ,									
  IN var_ContactName CHAR(50) ,									
  IN var_InvoicePaymentTerms VARCHAR(10) ,  
  IN var_CreditLimit FLOAT ,   
  IN var_GracePeriod CHAR(16) ,									
  IN var_Active CHAR(1) ,     
  IN var_PricingKey varCHAR(30) ,									
  IN var_Memo1 VARCHAR(50) ,									
  IN var_Memo2 VARCHAR(50) ,									
  IN var_Territory CHAR(6) ,									
  IN var_Class CHAR(50) ,									
  IN var_Region CHAR(11) ,									
  
  IN var_Transaction_Anals3 CHAR(25) ,									
  
  
  
  IN var_Grouping_Code CHAR(40) ,									
  IN var_Outlet_Quality CHAR(6) ,									
  IN var_OrderLocation CHAR(10) ,									
  IN var_Credit_Days VARCHAR(3) ,									
  IN var_CreditTerms VARCHAR(10) 									
)
    MODIFIES SQL DATA
BEGIN									
 DECLARE var_exists INT;
  DECLARE channel_exists INT;
 DECLARE category_exists INT;	
 DECLARE var_mslExist INT ;	
 DECLARE var_itemmapkey INT;
 DECLARE var_itemmustkey INT;
DECLARE RP_RouteCode BIGINT DEFAULT 0; 
SET channel_exists =(SELECT IFNULL(COUNT(*),0) FROM channelmaster WHERE alternatecode=var_Transaction_Anals3);									
SET category_exists =(SELECT IFNULL(COUNT(*),0) FROM categorymaster WHERE alternatecode=var_Class);			
 SET var_exists =(SELECT IFNULL(COUNT(*),0) FROM customermaster WHERE ANCustomerCode=var_CustomerCode);									
 									
 SET RP_RouteCode=(SELECT IFNULL( (SELECT RouteCode FROM routemaster WHERE alternateroutecode = var_RouteCode LIMIT 1) ,(SELECT RouteCode FROM RouteMaster LIMIT 1)));
 IF var_InvoicePaymentTerms ='CASH' THEN 									
 SET var_InvoicePaymentTerms = 1;									
 ELSE 									
	SET var_InvoicePaymentTerms = 2;
	 IF 	var_CreditLimit=0 THEN
		SET 	var_CreditLimit=1;
	 END IF;							
END IF;	
								
IF var_CreditLimit = 0 THEN									
SET var_CreditLimit = 9999;									
END IF;		
							
IF var_Active = 'A' THEN 									
SET var_Active = 1;									
ELSE 									
SET var_Active = 0;									
END IF;					
	
SET var_mslExist= (SELECT EXISTS( SELECT IFNULL(itemmustkey,0)  FROM customermaster WHERE DivisionCode = var_Division_Code AND itemmustkey IS NOT NULL AND itemmustkey > 0 LIMIT 1	));
IF var_mslExist=1
THEN 
SET var_itemmustkey= (SELECT IFNULL(itemmustkey,0)   FROM customermaster WHERE DivisionCode = var_Division_Code AND itemmustkey IS NOT NULL AND itemmustkey > 0 LIMIT 1	);
END IF;
SET var_mslExist= (SELECT EXISTS( SELECT IFNULL(itemmapkey,0)  FROM customermaster WHERE DivisionCode = var_Division_Code AND itemmapkey IS NOT NULL AND itemmapkey > 0 LIMIT 1	));
IF var_mslExist=1
THEN 
SET var_itemmapkey =(SELECT IFNULL(itemmapkey,0)   FROM customermaster WHERE DivisionCode = var_Division_Code AND itemmapkey IS NOT NULL AND itemmapkey > 0 LIMIT 1	);
END IF;
	
				
IF var_exists=0 THEN 									
 									
 INSERT INTO CustomerMaster (ANCustomerCode, TYPE, HeadOfficeCode, RouteCode, CustomerName, 									
ARBCustomerName, CustomerAddress1, ARBCustomerAddress1, CustomerAddress2, CustomerAddress3,ContactName, 									
ArbContactName, InvoicePaymentTerms,   CreditLimitDays, CreditLimit,ActiveCustomer, Memo1, Memo2, 									
AlternateCode,EnablePromoTrxn,EnableBuyBackFree,ForceStockCapture,EnableDraftCopy,enablereturnstrxn,									
enabledelayprint,enablesigcapture,enablearcollection,enabledamagedreturns,enablebatchselection,									
printsequence,invoicepriceprint,enablepromoeditinvs,enablepromoeditords,MDAT,pricingkey,enablesalestrxn,DivisionCode,									
graceperiod,Territory	,Class	,Region	,Transaction_Anals3	,GPSSaveCount	,Grouping_Code	,Outlet_Quality	,StatementDays	,Analysis2,alternateroutecode,ALTERNATEPRICINGKEY,chaincode,enableinvoicecomment,itemmustkey,itemmapkey,CreditTerms	)
SELECT var_CustomerCode,1,var_HeadOfficeCode,RP_RouteCode,var_CustomerName,'',var_CustomerAddress1,									
'',var_CustomerAddress2,var_CustomerAddress3,var_ContactName,'',var_InvoicePaymentTerms,var_Credit_Days,var_CreditLimit ,var_Active,var_Memo1,
var_Memo2,var_CustomerCode, 2,0,0,0,4,1,2,1,3,0,2,1,3,1,NOW(),NULL,1,var_Division_Code,var_GracePeriod,									
var_Territory,var_Class,	var_Region,	 var_Transaction_Anals3,1,var_Grouping_Code,	var_Outlet_Quality,
0,					
var_OrderLocation,var_RouteCode,var_PricingKey,'0',1 ,CASE WHEN var_itemmustkey=0 THEN NULL ELSE var_itemmustkey END, CASE WHEN var_itemmapkey=0 THEN NULL ELSE var_itemmapkey END ,var_CreditTerms;
 
									
 ELSE  									
 
SET var_mslExist= (SELECT EXISTS( SELECT IFNULL(itemmustkey,0)  FROM customermaster WHERE DivisionCode = var_Division_Code AND itemmustkey IS NOT NULL AND itemmustkey > 0 LIMIT 1	));
IF var_mslExist=1
THEN 
SET var_itemmustkey= (SELECT IFNULL(itemmustkey,0)   FROM customermaster WHERE DivisionCode = var_Division_Code AND itemmustkey IS NOT NULL AND itemmustkey > 0 LIMIT 1	);
END IF;
SET var_mslExist= (SELECT EXISTS( SELECT IFNULL(itemmapkey,0)  FROM customermaster WHERE DivisionCode = var_Division_Code AND itemmapkey IS NOT NULL AND itemmapkey > 0 LIMIT 1	));
IF var_mslExist=1
THEN 
SET var_itemmapkey =(SELECT IFNULL(itemmapkey,0)   FROM customermaster WHERE DivisionCode = var_Division_Code AND itemmapkey IS NOT NULL AND itemmapkey > 0 LIMIT 1	);
END IF;
 	
 									
UPDATE customermaster cm  									
SET 									
cm.Grouping_Code	= var_Grouping_Code,								
cm.Outlet_Quality	= var_Outlet_Quality,								
cm.StatementDays	= var_Credit_Days,								
cm.Analysis2	= var_OrderLocation,								
cm.alternateroutecode	= var_RouteCode,								
cm.routecode= RP_RouteCode,									
cm.ALTERNATEPRICINGKEY	= var_PricingKey,								
cm.DivisionCode 	= var_Division_Code,								
cm.GracePeriod	= var_graceperiod,								
cm.Territory	= var_Territory,								
cm.Class	= var_Class,								
cm.Region	= var_Region,								
cm.Transaction_Anals3	= var_Transaction_Anals3,								
cm.CustomerName	= var_CustomerName,								
cm.ARBCustomerName	= '',								
cm.CustomerAddress1	= var_CustomerAddress1,								
cm.ARBCustomerAddress1	= '',								
cm.CustomerAddress2	= var_CustomerAddress2,								
cm.CustomerAddress3	= var_CustomerAddress3,								
cm.ContactName	= var_ContactName,								
cm.ArbContactName	= '',								
cm.InvoicePaymentTerms	= var_InvoicePaymentTerms,								
cm.CreditLimit	= var_CreditLimit,									
cm.ActiveCustomer 	= var_Active,								
cm.Memo1	= var_Memo1,								
cm.Memo2	= var_Memo2,								
cm.mdat=NOW(),
CreditTerms = 		var_CreditTerms,
cm.itemmustkey=	CASE WHEN var_itemmustkey=0 THEN NULL ELSE var_itemmustkey END,
cm.itemmapkey=CASE WHEN var_itemmapkey=0 THEN NULL ELSE var_itemmapkey END 								
 WHERE cm.ANCustomerCode= var_customercode;	
 									
END IF;									
 
	
 IF channel_exists=0 THEN 	
INSERT INTO channelmaster (alternatecode,channelname,arbchannelname,created,cdat,modified,mdat) 
SELECT var_Transaction_Anals3,var_Transaction_Anals3,var_Transaction_Anals3,'admin',NOW(),'admin',NOW();
END IF;	
 IF category_exists=0 THEN 	
INSERT INTO categorymaster (alternatecode,categoryname,arbcategoryname,created,cdat,modified,mdat) 
SELECT var_Class,var_Class,var_Class,'admin',NOW(),'admin',NOW();
END IF;	
  SELECT "success";									
 END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_import_customer_from_oracle_temp` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_import_customer_from_oracle_temp` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_customer_from_oracle_temp`(									
 IN var_Division_Code VARCHAR(10),									
  IN var_CustomerCode CHAR(8),									
  IN var_HeadOfficeCode CHAR(8) ,									
  IN var_RouteCode CHAR(10) ,									
  IN var_CustType CHAR(10) ,									
  IN var_CustomerName CHAR(32) ,									
  IN var_CustomerAddress1 CHAR(32) ,									
  IN var_CustomerAddress2 CHAR(32) ,									
  IN var_CustomerAddress3 CHAR(32) ,									
  IN var_ContactName CHAR(32) ,									
  IN var_InvoicePaymentTerms VARCHAR(10) ,  
  IN var_CreditLimit FLOAT ,   
  IN var_GracePeriod CHAR(16) ,									
  IN var_Active CHAR(1) ,     
  IN var_PricingKey CHAR(3) ,									
  IN var_Memo1 VARCHAR(1) ,									
  IN var_Memo2 VARCHAR(1) ,									
  IN var_Territory CHAR(6) ,									
  IN var_Class CHAR(6) ,									
  IN var_Region CHAR(11) ,									
 								
  IN var_Transaction_Anals3 CHAR(10) ,									
  								
  IN var_Grouping_Code CHAR(40) ,									
  IN var_Outlet_Quality CHAR(6) ,									
  IN var_OrderLocation CHAR(10) ,									
  IN var_Credit_Days VARCHAR(3) ,									
  IN var_CreditTerms VARCHAR(1) 									
)
    MODIFIES SQL DATA
BEGIN									
  	 	insert into customer_oracle_data Select var_Division_Code ,									
   var_CustomerCode ,									
   var_HeadOfficeCode  ,									
   var_RouteCode  ,									
   var_CustType  ,									
   var_CustomerName  ,									
   var_CustomerAddress1  ,									
   var_CustomerAddress2  ,									
   var_CustomerAddress3  ,									
   var_ContactName  ,									
   var_InvoicePaymentTerms  ,   									
   var_CreditLimit   ,    									
   var_GracePeriod  ,									
   var_Active  ,     								
   var_PricingKey  ,									
   var_Memo1  ,									
   var_Memo2  ,									
   var_Territory  ,									
   var_Class  ,									
   var_Region  ,									
 							
   var_Transaction_Anals3  ,									
  								
   var_Grouping_Code  ,									
   var_Outlet_Quality  ,									
   var_OrderLocation  ,									
   var_Credit_Days  ,									
   var_CreditTerms  ;
    SELECT "success";
 END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_import_customer_outstanding_oracle` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_import_customer_outstanding_oracle` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_customer_outstanding_oracle`(
IN	var_invoicenumber	VARCHAR(50),
IN	var_routecode	VARCHAR(50),
IN	var_salesmancode	VARCHAR(50),
IN	var_transactiondate	DATE,
IN	var_customercode	VARCHAR(50),
IN	var_totalinvoiceamount	FLOAT,
IN	var_invoicebalance	FLOAT,
IN	var_paymenttype	INT(11),
IN	var_pdcindicator	INT(11),
IN	var_refernce	VARCHAR(50),
IN	var_analysis_codes2	VARCHAR(50),
IN	var_custtype	VARCHAR(50) 
)
BEGIN
DECLARE var_max_transactionkey BIGINT;
DECLARE var_exits INT;
DECLARE LID INT;
DECLARE var_statementdays INT;
DECLARE var_creditterms VARCHAR(50);
SET var_statementdays =(SELECT statementdays FROM customermaster WHERE alternatecode=var_customercode);
SET var_creditterms =(SELECT CreditTerms FROM customermaster WHERE alternatecode=var_customercode);
SET var_max_transactionkey=(SELECT IFNULL(MAX(transactionkey),0)+1 FROM customerinvoice);
 SET var_exits =(SELECT IFNULL( (SELECT 1 FROM customerinvoice WHERE ERPReferenceNumber=var_invoicenumber LIMIT 1) ,0));
 
 IF var_exits = 0  THEN
 INSERT INTO CustomerInvoice(TransactionType,DocumentNumber,InvoiceNumber,TransactionDate,CustomerCode,
RouteCode,
SalesmanCode,TotalInvoiceAmount,TotalSalesAmount,InvoiceBalance,PaymentType,VoidFlag,PaymentStatus,HHCInvoiceNumber,
Remarks1,Remarks2,RouteStartDate,ERPReferenceNumber,MDat,AmountPaid,duedate)
SELECT  2 AS transactiontype,0  AS docnumber,
0  AS invoicenumber,var_transactiondate,
 (SELECT customercode FROM customermaster WHERE alternatecode=var_customercode)  ,(SELECT rm.routecode FROM routemaster rm WHERE alternateroutecode=var_routecode),
(SELECT rm.salesmancode FROM routemaster rm WHERE alternateroutecode=var_routecode) ,var_totalinvoiceamount,var_totalinvoiceamount,var_invoicebalance,2,0,0,var_totalinvoiceamount,
var_refernce,'Balance from ERP',NULL,var_invoicenumber,NOW(),
var_totalinvoiceamount-var_invoicebalance,
(CASE
    WHEN var_creditterms='DFS' THEN DATE_ADD(DATE_FORMAT(var_transactiondate + INTERVAL 1 MONTH,'%Y-%m-01'),INTERVAL var_statementdays DAY ) 
    ELSE DATE_ADD(var_transactiondate,INTERVAL var_statementdays DAY )
END)
 AS duedate;
 
	 
SET LID = LAST_INSERT_ID(); 
	 UPDATE customerinvoice ci SET DocumentNumber=LID,InvoiceNumber=LID 
  WHERE ci.TransactionKey=LID; 
	 
END IF;
SELECT var_exits;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_import_divisionmaster_oracle` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_import_divisionmaster_oracle` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_divisionmaster_oracle`(
IN var_id INT,
IN var_name  VARCHAR(20)
)
BEGIN
DECLARE var_itemcode INT;
SET var_itemcode=(SELECT IFNULL(COUNT(divisioncode),0) FROM DivisionMaster WHERE DivisionCode=var_id);
IF (var_itemcode <> 0) THEN 
UPDATE DivisionMaster SET divisionname=var_name,MDat=NOW() WHERE DivisionCode=var_id;
ELSE
INSERT INTO DivisionMaster
SELECT var_id,var_name,var_name,'admin', NOW(),'admin',NOW();
insert into company (cmpycode,NAME,parentcompany,address,telephone,activestatus,mdat,cdat,alternatecmpycode)
values(var_id,var_name,1,'','12345678',1,now(),now(),var_id);
END IF;
SELECT ROW_COUNT() AS output;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_import_get_columnnames_temporarytable` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_import_get_columnnames_temporarytable` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_get_columnnames_temporarytable`(
	IN tablenamevalue TEXT
    )
BEGIN
	IF tablenamevalue = 'temp_customermaster' THEN 
		SELECT "temp_customermaster" AS tablename;
		SHOW COLUMNS FROM temp_customermaster;
		
	
	
	
	
	
	
	
	
	ELSEIF tablenamevalue = 'temp_routegoal' THEN 
	 	SELECT "temp_routegoal" AS tablename;
	 	SHOW COLUMNS FROM temp_routegoal;
	 	
	ELSEIF tablenamevalue = 'temp_routesequence' THEN 
		SELECT "temp_routesequence" AS tablename;
		SHOW COLUMNS FROM temp_routesequence;	
	
	ELSEIF tablenamevalue = 'temp_loadrequest' THEN 
		SELECT "temp_loadrequest" AS tablename;
		SHOW COLUMNS FROM temp_loadrequest;
	
	ELSEIF tablenamevalue = 'temp_freecontract' THEN 
		SELECT "temp_freecontract" AS tablename;
		SHOW COLUMNS FROM temp_freecontract;
		
	ELSEIF tablenamevalue = 'temp_msllist' THEN 
		SELECT "temp_msllist" AS tablename;
		SHOW COLUMNS FROM temp_msllist;		
	END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_import_ItemMaster` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_import_ItemMaster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_ItemMaster`()
BEGIN
DECLARE record INT DEFAULT 0;
DECLARE var_Division_Code VARCHAR(3);
 DECLARE var_ItemCode CHAR(20);
 DECLARE var_description CHAR(20);
 DECLARE var_long_description CHAR(40);
 DECLARE var_upc FLOAT;
 DECLARE var_sellingprcbyunit FLOAT;
 DECLARE var_retunprcbyunit FLOAT;
 DECLARE var_sellingprcbyct FLOAT;
 DECLARE var_retunprcbyct FLOAT;
 DECLARE var_Active CHAR(20);
 DECLARE var_memo1 VARCHAR(1);
 DECLARE var_memo2 VARCHAR(1);
 DECLARE var_analysis_x_ref CHAR(3);
 DECLARE var_purchase_key CHAR(3);
 DECLARE var_nominal_key CHAR(3);
 DECLARE var_analysis_x_ref1 CHAR(3);
 DECLARE var_brand CHAR(50);
 DECLARE var_Category CHAR(50);
 DECLARE var_Sub_Category CHAR(50);
 DECLARE var_Barcode CHAR(20);
DECLARE reccount BIGINT;
DECLARE var_cg_exits BIGINT DEFAULT 0;
DECLARE var_mg_exits BIGINT DEFAULT 0;
DECLARE var_smg_exits BIGINT DEFAULT 0;
DECLARE var_ig_exits BIGINT DEFAULT 0;
DECLARE var_max_itemcode BIGINT DEFAULT 0;
DECLARE var_max_itemgroupcode BIGINT DEFAULT 0;
DECLARE var_max_submajorcategorycode BIGINT DEFAULT 0;
DECLARE var_max_majorcategorycode  BIGINT DEFAULT 0;
DECLARE var_max_companygroupcode  BIGINT DEFAULT 0;
DECLARE var_cur_itemcode BIGINT DEFAULT 0;
DECLARE var_cur_itemgroupcode BIGINT DEFAULT 0;
DECLARE var_cur_submajorcategorycode BIGINT DEFAULT 0;
DECLARE var_cur_majorcategorycode  BIGINT DEFAULT 0;
DECLARE var_cur_companygroupcode  BIGINT DEFAULT 0;
 
DECLARE curMain CURSOR FOR SELECT  Division_Code,ItemCode,description,long_description,upc,sellingprcbyunit,retunprcbyunit,sellingprcbyct,retunprcbyct,Active,memo1,memo2,analysis_x_ref,purchase_key,nominal_key,analysis_x_ref1,brand,Category,Sub_Category,Barcode
FROM rp_item ;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET record = 1;
SET record=0;
OPEN curMain;
read_loop: LOOP
FETCH curMain INTO var_Division_Code,var_ItemCode,var_description,var_long_description,var_upc,var_sellingprcbyunit,var_retunprcbyunit,var_sellingprcbyct,var_retunprcbyct,var_Active,var_memo1,var_memo2,var_analysis_x_ref,var_purchase_key,var_nominal_key,var_analysis_x_ref1,var_brand,var_Category,var_Sub_Category,var_Barcode;
IF record = 1 THEN
LEAVE read_loop;
END IF;
SET var_cg_exits = (SELECT IFNULL(COUNT(*),0) FROM companygroup WHERE Alternatecode = var_Division_Code);
IF var_cg_exits = 0 THEN
SET var_max_companygroupcode = (SELECT IFNULL(MAX(companygroupcode),0)+1 FROM companygroup);
INSERT INTO companygroup SELECT var_max_companygroupcode ,var_division_code,1,var_division_code,var_division_code,'ADMIN',NOW(),NULL,NULL,1 ;
ELSE
UPDATE companygroup SET description=var_division_code,arbdescription=var_division_code,modified='admin',mdat=NOW() WHERE alternatecode=var_division_code;
SET var_max_companygroupcode = (SELECT companygroupcode FROM companygroup WHERE alternatecode=var_division_code);
END IF;
SET var_mg_exits = (SELECT IFNULL(COUNT(*),0) FROM MAJORCATEGORY WHERE description = var_brand);
IF var_mg_exits = 0 THEN
SET var_max_majorcategorycode = (SELECT IFNULL(MAX(majorcategorycode),0)+1 FROM MAJORCATEGORY);
INSERT INTO MAJORCATEGORY SELECT var_max_majorcategorycode ,(SELECT DISTINCT companygroupcode FROM companygroup WHERE alternatecode=var_division_code)  ,var_brand,var_brand,var_brand,'ADMIN',NOW(),NULL,NULL,1 ;
ELSE
UPDATE MAJORCATEGORY SET description=var_brand,arbdescription=var_brand,modified='admin',mdat=NOW() WHERE alternatecode=var_brand;
SET var_max_majorcategorycode = (SELECT majorcategorycode FROM MAJORCATEGORY  WHERE alternatecode=var_brand);
END IF;
SET var_smg_exits = (SELECT IFNULL(COUNT(*),0) FROM SUBMAJORCATEGORY WHERE description = var_Category);
IF var_smg_exits = 0 THEN
SET var_max_submajorcategorycode = (SELECT IFNULL(MAX(submajorcategorycode),0)+1 FROM SUBMAJORCATEGORY);
INSERT INTO subMAJORCATEGORY SELECT var_max_submajorcategorycode ,var_Category,(SELECT DISTINCT majorcategorycode FROM majorcategory WHERE alternatecode=var_brand) , var_Category,var_Category,'ADMIN',NOW(),NULL,NULL,1 ;
ELSE
UPDATE SUBMAJORCATEGORY SET description=var_Category,arbdescription=var_Category,modified='admin',mdat=NOW() WHERE alternatecode=var_Category;
SET var_max_submajorcategorycode = (SELECT submajorcategorycode FROM SUBMAJORCATEGORY  WHERE alternatecode=var_Category);
END IF;
SET var_ig_exits = (SELECT IFNULL(COUNT(*),0) FROM ItemGroup WHERE ItemGroupName = var_Sub_Category);
IF var_ig_exits = 0 THEN
SET var_max_itemgroupcode = (SELECT IFNULL(MAX(itemgroupcode),0)+1 FROM Itemgroup);
INSERT INTO Itemgroup SELECT var_max_itemgroupcode ,(SELECT DISTINCT submajorcategorycode FROM submajorcategory WHERE alternatecode= var_Category),var_Sub_Category , var_Sub_Category,var_Sub_Category,'ADMIN',NOW(),NULL,NULL,var_Sub_Category,1 ;
ELSE
UPDATE itemgroup SET Itemgroupname=var_Sub_Category,arbitemgroup=var_Sub_Category,modified='admin',mdat=NOW() WHERE ItemGroupName=var_Sub_Category;
SET var_max_itemgroupcode = (SELECT itemgroupcode FROM Itemgroup   WHERE ItemGroupName=var_Sub_Category);
END IF;
SET reccount = (SELECT IFNULL(COUNT(*),0) FROM ItemMaster WHERE Alternatecode = var_ItemCode);
IF reccount = 0 THEN 
SET var_max_itemcode = (SELECT IFNULL(MAX(actualItemcode),0)+1 FROM ItemMaster);
INSERT INTO itemmaster 
	(actualitemcode, 	itemgroupcode, 	itemtype, 	itemshortdescription, 	itemdescription, 	unitspercase, 	defaultsalesprice, 	defaultreturnprice, 	defaultretailprice, 	pricingkey, 	arbitemshortdescription, 	arbitemdescription, 	hhcitemshortdescription, 	hhcitemdescription, 	activeitem, 	caseprice, 	returncaseprice, 	retailcaseprice, 	alternatecode, 	created, 	cdat, 	modified, 	mdat, 	liter, 	dataentry, 	leadtime, 	viewflag, 	case1, 	case2, 	memo1, 	memo2, 	tcallowed, 	itemgroupingcode, 	printsequenceroute, 	printsequencecust, 	upccasecode, 	captureshelfstock, 	filmbagbarcode, 	boxtraybarcode, 	cartonbarcode, 	highper, 	lowper, 	literperunit, 	commissionallowedflag, 	alternateitemgroupcode, 	fastmovingitemflag, 	codedateformat, 	itemtaxkey1, 	itemtaxkey2, 	itemtaxkey3, 	defpricetaxkey1, 	defpricetaxkey2, 	defpricetaxkey3, 	packagecode, 	anitemcode, 	averagesales, 	enablemeatpiecescapture, 	itemcompany, 	caseuom, 	warehousestock, 	itemgrpcode, 	parentitemcode, 	shelflife, 	defaultgoodreturnprice, 	defaultgoodreturncaseprice, 	maxpricechange, 	minpricechange, 	allowbatchentry, 	costcaseprice, 	defaultcostprice, 	allowinvoicepricechange, 	reportitemcode, 	offtakeparameter, 	barcode1, 	barcode2, 	barcode3, 	barcode4, 	barcode5, 	barcode6, 	barcode7, 	barcode8, 	barcode9, 	barcode10, 	division, 	majorcategorycode, 	majorcategorydesciption, 	submajorcategorycode, 	submajorcategorydesciption, 	companygroupcode, 	companygroupname, 	itemgroupname, 	itemexpirychk, 	shelflifecapture,Sales_Account,cos_cost_account,cos_stock_account,nominal_category	)
	VALUES
	(var_max_itemcode,(SELECT itemgroupcode FROM ItemGroup WHERE alternateitemgroupcode = var_Sub_Category), 1,var_description,var_long_description,var_upc,var_sellingprcbyunit,var_retunprcbyunit,var_sellingprcbyunit,NULL,'','','','',var_Active,var_sellingprcbyct,var_retunprcbyct,var_sellingprcbyct,var_ItemCode,'admin',NOW(),'null',NULL,0,0,0,0,0,0,var_memo1,var_memo2,'0','null','0','1','null','null','0','0','NULL','NULL','NULL','NULL','NULL',var_ItemCode,'0','0','0','0','0','0','0','0','0',var_ItemCode,'NULL','0','1','1','NULL','NULL','0','0',var_retunprcbyunit,var_retunprcbyct,'0','0','0','0','0','0',var_ItemCode,'0',var_Barcode,'barcode2','barcode3','barcode4','barcode5','barcode6','barcode7','barcode8','barcode9','barcode10',var_Division_Code,var_max_majorcategorycode, var_brand,var_max_submajorcategorycode,var_Category,var_max_companygroupcode,var_division_code,var_Sub_Category,'0','0',var_analysis_x_ref,var_purchase_key,var_analysis_x_ref1,var_nominal_key	);
	
ELSE 
UPDATE itemmaster SET 
itemshortdescription =	var_description	,
itemgroupcode=(SELECT itemgroupcode FROM ItemGroup WHERE alternateitemgroupcode = var_Sub_Category),
itemdescription =	var_long_description	,
unitspercase =	var_upc	,
defaultsalesprice =	var_sellingprcbyunit	,
defaultreturnprice =	var_retunprcbyunit	,
defaultretailprice =	var_sellingprcbyunit	,
activeitem =	var_Active	,
caseprice =	var_sellingprcbyct	,
returncaseprice =	var_retunprcbyct	,
retailcaseprice =	var_sellingprcbyct	,
modified =	'admin'	,
mdat =	NOW()	,
memo1 =	var_memo1	,
memo2 =	var_memo2	,
alternateitemgroupcode =	var_ItemCode	,
anitemcode =	var_ItemCode	,
defaultgoodreturnprice =	var_retunprcbyunit	,
defaultgoodreturncaseprice =	var_retunprcbyct	,
reportitemcode =	var_ItemCode	,
barcode1 =	var_Barcode	,
division =	var_Division_Code	,
majorcategorydesciption =	var_brand	,
submajorcategorydesciption =	var_Category	,
companygroupname =	var_division_code	,
Itemgroupcode =var_max_itemgroupcode ,
submajorcategorycode= var_max_submajorcategorycode,
majorcategorycode=var_max_majorcategorycode,
companygroupcode=var_max_companygroupcode,
itemgroupname =	var_Sub_Category	,
Sales_Account=	var_analysis_x_ref	,
cos_cost_account=	var_purchase_key	,
cos_stock_account=	var_analysis_x_ref1	,
nominal_category=	var_nominal_key	WHERE alternatecode =	var_ItemCode	;
										
END IF;
END LOOP read_loop;
CLOSE curMain;  
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_import_item_from_oracle` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_import_item_from_oracle` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_item_from_oracle`(
                    IN DIVISION_CODE TEXT,
                    IN ITEM_CODE TEXT,
                    IN DESCRIPTION TEXT,
                    IN LONG_DESCRIPTION TEXT,
                    IN UNIT_SELLING_PRICE TEXT,
                  
                    IN UNIT_SELLING_PRICE_PERUNIT TEXT,
                    IN RETURN_SELLING_PRICE_PERUNIT TEXT,
                    IN RETURN_PRICE TEXT,
                    IN BRAND_CODE TEXT,
                    IN CATEGORY_CODE TEXT,
                    IN SUB_CATEGORY_CODE TEXT,
                    IN Barcode TEXT,
                     IN UOM_RATE TEXT,
                      IN ITEM_STATUS TEXT,
                  IN UOM VARCHAR(10)
                   
)
BEGIN
DECLARE record INT DEFAULT 0;
DECLARE var_Division_Code VARCHAR(10);
DECLARE var_ItemCode CHAR(20);
DECLARE var_description CHAR(40);
DECLARE var_long_description CHAR(40);
DECLARE var_upc FLOAT;
DECLARE var_sellingprcbyunit FLOAT;
DECLARE var_retunprcbyunit FLOAT;
DECLARE var_sellingprcbyct FLOAT;
DECLARE var_retunprcbyct FLOAT;
DECLARE var_Active CHAR(20);
DECLARE var_memo1 VARCHAR(1);
DECLARE var_memo2 VARCHAR(1);
DECLARE var_analysis_x_ref CHAR(3);
DECLARE var_purchase_key CHAR(3);
DECLARE var_nominal_key CHAR(3);
DECLARE var_analysis_x_ref1 CHAR(3);
DECLARE var_brand CHAR(50);
DECLARE var_Category CHAR(50);
DECLARE var_Sub_Category CHAR(50);
DECLARE var_Barcode CHAR(20);
DECLARE reccount BIGINT;
DECLARE var_cg_exits BIGINT DEFAULT 0;
DECLARE var_mg_exits BIGINT DEFAULT 0;
DECLARE var_smg_exits BIGINT DEFAULT 0;
DECLARE var_ig_exits BIGINT DEFAULT 0;
DECLARE var_max_itemcode BIGINT DEFAULT 0;
DECLARE var_max_itemgroupcode BIGINT DEFAULT 0;
DECLARE var_max_submajorcategorycode BIGINT DEFAULT 0;
DECLARE var_max_majorcategorycode  BIGINT DEFAULT 0;
DECLARE var_max_companygroupcode  BIGINT DEFAULT 0;
DECLARE var_cur_itemcode BIGINT DEFAULT 0;
DECLARE var_cur_itemgroupcode BIGINT DEFAULT 0;
DECLARE var_cur_submajorcategorycode BIGINT DEFAULT 0;
DECLARE var_cur_majorcategorycode  BIGINT DEFAULT 0;
DECLARE var_cur_companygroupcode  BIGINT DEFAULT 0;
DECLARE var_companygroupname1 VARCHAR(250);
DECLARE var_companygroupcode1 INT;
DECLARE var_actualitemcode1 INT;
DECLARE var_itemgroupcode1 INT;
DECLARE temp_routeitemgrpcode INT(11) ;
DECLARE var_code INT DEFAULT 0;
DECLARE countval INT;
DECLARE count_customeritemgrpcode INT DEFAULT 0;
DECLARE count_customeritemmapping  INT DEFAULT 0;
DECLARE cnt VARCHAR(250);
DECLARE var_mapcount1 INT;
DECLARE curMain CURSOR FOR SELECT  DIVISION_CODE,ITEM_CODE,DESCRIPTION,LONG_DESCRIPTION,UNIT_SELLING_PRICE,UNIT_SELLING_PRICE_PERUNIT,RETURN_SELLING_PRICE_PERUNIT,RETURN_PRICE,ITEM_STATUS,BRAND_CODE,CATEGORY_CODE,SUB_CATEGORY_CODE,Barcode,UOM_RATE ;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET record = 1;
 
SET record=0;
OPEN curMain;
read_loop: LOOP
FETCH curMain INTO var_Division_Code,var_ItemCode,var_description,var_long_description,var_sellingprcbyct,var_sellingprcbyunit,
var_retunprcbyunit,var_retunprcbyct,var_Active,var_brand,var_Category,var_Sub_Category,var_Barcode,var_upc;
IF record = 1 THEN
LEAVE read_loop;
END IF;
IF(ITEM_STATUS ='A') THEN
 SET var_Active=1;
END IF;
SET var_cg_exits = (SELECT IFNULL(COUNT(*),0) FROM companygroup WHERE Alternatecode = var_Division_Code);
IF var_cg_exits = 0 THEN
SET var_max_companygroupcode = (SELECT IFNULL(MAX(companygroupcode),0)+1 FROM companygroup);
INSERT INTO companygroup SELECT var_max_companygroupcode ,var_division_code,1,var_division_code,var_division_code,'ADMIN',NOW(),NULL,NULL,1 ;
ELSE
UPDATE companygroup SET description=var_division_code,arbdescription=var_division_code,modified='admin',mdat=NOW() WHERE alternatecode=var_division_code;
END IF;
SET var_mg_exits = (SELECT IFNULL(COUNT(*),0) FROM MAJORCATEGORY WHERE alternatecode = var_brand);
IF var_mg_exits = 0 THEN
SET var_max_majorcategorycode = (SELECT IFNULL(MAX(majorcategorycode),0)+1 FROM MAJORCATEGORY);
INSERT INTO MAJORCATEGORY SELECT var_max_majorcategorycode ,(SELECT DISTINCT companygroupcode FROM companygroup WHERE alternatecode=var_division_code)  ,var_brand,var_brand,var_brand,'ADMIN',NOW(),NULL,NULL,1 ;
ELSE
UPDATE MAJORCATEGORY SET description=var_brand,arbdescription=var_brand,modified='admin',mdat=NOW() WHERE alternatecode=var_brand;
END IF;
SET var_smg_exits = (SELECT IFNULL(COUNT(*),0) FROM SUBMAJORCATEGORY WHERE alternatecode = var_Category);
IF var_smg_exits = 0 THEN
SET var_max_submajorcategorycode = (SELECT IFNULL(MAX(submajorcategorycode),0)+1 FROM SUBMAJORCATEGORY);
INSERT INTO subMAJORCATEGORY SELECT var_max_submajorcategorycode ,var_Category,(SELECT DISTINCT majorcategorycode FROM majorcategory WHERE alternatecode=var_brand) , var_Category,var_Category,'ADMIN',NOW(),NULL,NULL,1 ;
ELSE
UPDATE SUBMAJORCATEGORY SET description=var_Category,arbdescription=var_Category,modified='admin',mdat=NOW() WHERE alternatecode=var_Category;
END IF;
SET var_ig_exits = (SELECT IFNULL(COUNT(*),0) FROM ItemGroup WHERE alternateitemgroupcode = var_Sub_Category);
IF var_ig_exits = 0 THEN
SET var_max_itemgroupcode = (SELECT IFNULL(MAX(itemgroupcode),0)+1 FROM Itemgroup);
INSERT INTO Itemgroup SELECT var_max_itemgroupcode ,(SELECT DISTINCT submajorcategorycode FROM submajorcategory WHERE alternatecode= var_Category),var_Sub_Category , var_Sub_Category,var_Sub_Category,'ADMIN',NOW(),NULL,NULL,var_Sub_Category,1 ;
ELSE
UPDATE itemgroup SET Itemgroupname=var_Sub_Category,arbitemgroup=var_Sub_Category,modified='admin',mdat=NOW() WHERE alternateitemgroupcode=var_Sub_Category;
END IF;
SET reccount = (SELECT IFNULL(COUNT(*),0) FROM ItemMaster WHERE Alternatecode = var_ItemCode);
IF reccount = 0 THEN
SET var_max_itemcode = (SELECT IFNULL(MAX(actualItemcode),0)+1 FROM ItemMaster);
INSERT INTO itemmaster
                (actualitemcode,              itemgroupcode,                itemtype,            itemshortdescription,    itemdescription,                 unitspercase,     defaultsalesprice,            defaultreturnprice,         defaultretailprice,            pricingkey,                 arbitemshortdescription,              arbitemdescription,        hhcitemshortdescription,             hhcitemdescription,                 activeitem,          caseprice,            returncaseprice,               retailcaseprice, alternatecode, created,               cdat,                 modified,             mdat,    liter,       dataentry,           leadtime,             viewflag,              case1,   case2,   memo1,                 memo2,               tcallowed,           itemgroupingcode,          printsequenceroute,      printsequencecust,                 upccasecode,     captureshelfstock,           filmbagbarcode,               boxtraybarcode,               cartonbarcode,                 highper,               lowper,                 literperunit,        commissionallowedflag,                alternateitemgroupcode,                 fastmovingitemflag,        codedateformat,              itemtaxkey1,      itemtaxkey2,      itemtaxkey3,                 defpricetaxkey1,              defpricetaxkey2,              defpricetaxkey3,              packagecode,    anitemcode,                 averagesales,     enablemeatpiecescapture,          itemcompany,   caseuom,             warehousestock,                 itemgrpcode,     parentitemcode,              shelflife,               defaultgoodreturnprice,                 defaultgoodreturncaseprice,      maxpricechange,              minpricechange,               allowbatchentry,                 costcaseprice,    defaultcostprice,              allowinvoicepricechange,             reportitemcode,                 offtakeparameter,           barcode1,            barcode2,            barcode3,            barcode4,            barcode5,                 barcode6,            barcode7,            barcode8,            barcode9,            barcode10,         division,                 majorcategorycode,       majorcategorydesciption,            submajorcategorycode,                 submajorcategorydesciption,     companygroupcode,      companygroupname,     itemgroupname,                 itemexpirychk, shelflifecapture,Sales_Account,cos_cost_account,cos_stock_account,nominal_category )
                VALUES
                (var_max_itemcode,(SELECT itemgroupcode FROM ItemGroup WHERE alternateitemgroupcode = var_Sub_Category), 1,var_description,var_long_description,var_upc,var_sellingprcbyunit,var_retunprcbyunit,var_sellingprcbyunit,NULL,'','','','',var_Active,var_sellingprcbyct,var_retunprcbyct,var_sellingprcbyct,var_ItemCode,'admin',NOW(),'null',NULL,0,0,0,0,0,0,var_memo1,var_memo2,'0','null','0','1',UOM,'null','0','0','NULL','NULL','NULL','NULL','NULL',var_ItemCode,'0','0','0','0','0','0','0','0','0',var_ItemCode,'NULL','0','1','1','NULL','NULL','0','0',var_retunprcbyunit,var_retunprcbyct,'0','0','0','0','0','0',var_ItemCode,'0',var_Barcode,'barcode2','barcode3','barcode4','barcode5','barcode6','barcode7','barcode8','barcode9','barcode10',var_Division_Code,var_max_majorcategorycode, var_brand,var_max_submajorcategorycode,var_Category,var_max_companygroupcode,var_division_code,var_Sub_Category,'0','0',var_analysis_x_ref,var_purchase_key,var_analysis_x_ref1,var_nominal_key                );
               
			   
			   
SELECT im.companygroupname,im.actualitemcode ,im.itemgroupcode,cm.code  INTO @var_companygroupname1,@var_actualitemcode1,@var_itemgroupcode1,@temp_routeitemgrpcode
FROM itemmaster im INNER JOIN companydata cm ON im.companygroupname=cm.description AND  im.actualitemcode=var_max_itemcode ;
SELECT COUNT(*)  INTO countval FROM routeitemgrp WHERE routeitemgrpcode=@temp_routeitemgrpcode LIMIT 1;
IF countval =0 THEN
	INSERT INTO routeitemgrp(routeitemgrpcode,itemgroupcode,description,created,cdat,modified,mdat) 
	VALUES(@temp_routeitemgrpcode,@var_itemgroupcode1,@var_companygroupname1,'admin',NOW(),'admin',NOW());
END IF;
	   
SELECT COUNT(*) INTO @count FROM  routeitemmapping WHERE routeitemgrpcode = @temp_routeitemgrpcode AND itemcode=@var_actualitemcode1;
IF @count = 0 THEN 
	INSERT INTO routeitemmapping(routeitemgrpcode,itemcode) VALUES(@temp_routeitemgrpcode,@var_actualitemcode1);
END IF;
SET @chk = CONCAT("SELECT COUNT(*) into @counter FROM customeritemgrp WHERE description = '",var_Division_Code,"'");				
PREPARE s1 FROM @chk;
EXECUTE s1;
IF @counter > 0 THEN
	SET @chk = CONCAT("SELECT customeritemgrpcode INTO  @var_customeritemgrpcode FROM customeritemgrp WHERE description ='",var_Division_Code,"' LIMIT 1");					
	PREPARE s1 FROM @chk;
	EXECUTE s1;
ELSE 
	SELECT  MAX(customeritemgrpcode)+ 1 INTO @var_customeritemgrpcode FROM customeritemgrp ;
	INSERT INTO customeritemgrp(customeritemgrpcode,description,created,cdat,modified,mdat) VALUES(@var_customeritemgrpcode,var_Division_Code,'admin',NOW(),'admin',NOW());
END IF;
SET @chk = CONCAT("SELECT COUNT(*)  INTO @var_mapcount1 FROM customeritemmapping WHERE customeritemgrpcode= ",@var_customeritemgrpcode," AND itemcode = (SELECT actualitemcode FROM itemmaster WHERE actualitemcode = ",var_max_itemcode,")");	
PREPARE s1 FROM @chk;
EXECUTE s1;
IF @var_mapcount1 = 0 THEN
INSERT INTO customeritemmapping(customeritemgrpcode,itemcode) VALUES(@var_customeritemgrpcode,var_max_itemcode);
END IF;
			   
			   
			   
			   
			   
			   
			   
			   
			   
			   
			   
ELSE
UPDATE itemmaster SET
itemshortdescription =  var_description ,
itemdescription =             var_long_description     ,
unitspercase =   var_upc ,
defaultsalesprice =          var_sellingprcbyunit       ,
defaultreturnprice =       var_retunprcbyunit        ,
defaultretailprice =          var_sellingprcbyunit       ,
activeitem =       var_Active          ,
caseprice =          var_sellingprcbyct           ,
returncaseprice =             var_retunprcbyct             ,
retailcaseprice =               var_sellingprcbyct           ,
modified =          'admin' ,
mdat =  NOW()  ,
memo1 =             var_memo1       ,
memo2 =             var_memo2       ,
alternateitemgroupcode =           var_ItemCode   ,
anitemcode =    var_ItemCode   ,
defaultgoodreturnprice =             var_retunprcbyunit        ,
defaultgoodreturncaseprice =    var_retunprcbyct             ,
reportitemcode =            var_ItemCode   ,
barcode1 =         var_Barcode      ,
division =             var_Division_Code          ,
majorcategorycode=(SELECT majorcategorycode FROM MAJORCATEGORY WHERE alternatecode = var_brand),
majorcategorydesciption =          var_brand           ,
submajorcategorycode= (SELECT submajorcategorycode FROM SUBMAJORCATEGORY WHERE alternatecode = var_Category),
submajorcategorydesciption =   var_Category     ,
companygroupcode=(SELECT companygroupcode FROM companygroup WHERE alternatecode = var_Division_Code),
companygroupname =  var_division_code           ,
itemgroupcode =(SELECT itemgroupcode FROM itemgroup WHERE alternateitemgroupcode = var_Sub_Category),
itemgroupname =            var_Sub_Category           ,
Sales_Account= var_analysis_x_ref          ,
cos_cost_account=         var_purchase_key           ,
cos_stock_account=       var_analysis_x_ref1        ,
nominal_category=         var_nominal_key,
upccasecode=UOM        WHERE alternatecode = var_ItemCode   ;
    
 
SELECT actualitemcode INTO var_max_itemcode FROM itemmaster WHERE Alternatecode=var_ItemCode;
SELECT im.companygroupname,im.actualitemcode ,im.itemgroupcode,cm.code  INTO @var_companygroupname1,@var_actualitemcode1,@var_itemgroupcode1,@temp_routeitemgrpcode
FROM itemmaster im INNER JOIN companydata cm ON im.companygroupname=cm.description AND  im.actualitemcode=var_max_itemcode ;
SELECT COUNT(*)  INTO countval FROM routeitemgrp WHERE routeitemgrpcode=@temp_routeitemgrpcode LIMIT 1;
IF countval =0 THEN
INSERT INTO routeitemgrp(routeitemgrpcode,itemgroupcode,description,created,cdat,modified,mdat) 
VALUES(@temp_routeitemgrpcode,@var_itemgroupcode1,@var_companygroupname1,'admin',NOW(),'admin',NOW());
END IF;
SELECT COUNT(*) INTO @count FROM  routeitemmapping WHERE routeitemgrpcode = @temp_routeitemgrpcode AND itemcode=@var_actualitemcode1;
IF @count = 0 THEN 
INSERT INTO routeitemmapping(routeitemgrpcode,itemcode) VALUES(@temp_routeitemgrpcode,@var_actualitemcode1);
END IF;	
SET @chk = CONCAT("SELECT COUNT(*) into @counter FROM customeritemgrp WHERE description = '",var_Division_Code,"'");					
PREPARE s1 FROM @chk;
EXECUTE s1;
IF @counter > 0 THEN
SET @chk = CONCAT("SELECT customeritemgrpcode INTO  @var_customeritemgrpcode FROM customeritemgrp WHERE description ='",var_Division_Code,"' LIMIT 1");					
PREPARE s1 FROM @chk;
EXECUTE s1;
SELECT @var_customeritemgrpcode;
ELSE 
SELECT  MAX(customeritemgrpcode)+ 1 INTO @var_customeritemgrpcode FROM customeritemgrp ;
INSERT INTO customeritemgrp(customeritemgrpcode,description,created,cdat,modified,mdat) VALUES(@var_customeritemgrpcode,var_Division_Code,'admin',NOW(),'admin',NOW());
END IF;
SET @chk = CONCAT("SELECT COUNT(*) INTO @var_mapcount1 FROM customeritemmapping WHERE customeritemgrpcode= ",@var_customeritemgrpcode," AND itemcode = (SELECT actualitemcode FROM itemmaster WHERE actualitemcode = ",var_max_itemcode,")");	
PREPARE s1 FROM @chk;
EXECUTE s1;
IF @var_mapcount1= 0 THEN
INSERT INTO customeritemmapping(customeritemgrpcode,itemcode) VALUES(@var_customeritemgrpcode,var_max_itemcode);
END IF;
	                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 
END IF;
END LOOP read_loop;
CLOSE curMain; 
SELECT "SUCCESS";
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_import_item_from_oracle_29082018` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_import_item_from_oracle_29082018` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_item_from_oracle_29082018`(
            IN DIVISION_CODE TEXT,
	    IN ITEM_CODE TEXT,
	    IN DESCRIPTION TEXT,
	    IN LONG_DESCRIPTION TEXT,
	    IN UNIT_SELLING_PRICE TEXT,
	   
	    IN UNIT_SELLING_PRICE_PERUNIT TEXT,
	    IN RETURN_SELLING_PRICE_PERUNIT TEXT,
	    IN RETURN_PRICE TEXT,
	    IN BRAND_CODE TEXT,
	    IN CATEGORY_CODE TEXT,
	    IN SUB_CATEGORY_CODE TEXT,
	    IN Barcode TEXT,
	     IN UOM_RATE TEXT,
	      IN ITEM_STATUS TEXT,
	      in UOM varchar(10)
	    
)
BEGIN
 DECLARE record INT DEFAULT 0;
 DECLARE var_Division_Code VARCHAR(10);
 DECLARE var_ItemCode CHAR(20);
 DECLARE var_description CHAR(40);
 DECLARE var_long_description CHAR(40);
 DECLARE var_upc FLOAT;
 DECLARE var_sellingprcbyunit FLOAT;
 DECLARE var_retunprcbyunit FLOAT;
