DECLARE var_max_companygroupcode  BIGINT DEFAULT 0;
DECLARE var_cur_itemcode BIGINT DEFAULT 0;
DECLARE var_cur_itemgroupcode BIGINT DEFAULT 0;
DECLARE var_cur_submajorcategorycode BIGINT DEFAULT 0;
DECLARE var_cur_majorcategorycode  BIGINT DEFAULT 0;
DECLARE var_cur_companygroupcode  BIGINT DEFAULT 0;
DECLARE curMain CURSOR FOR SELECT  DIVISION_CODE,ITEM_CODE,DESCRIPTION,LONG_DESCRIPTION,UNIT_SELLING_PRICE,UNIT_SELLING_PRICE_PERUNIT,RETURN_SELLING_PRICE_PERUNIT,RETURN_PRICE,ITEM_STATUS,BRAND_CODE,CATEGORY_CODE,SUB_CATEGORY_CODE,Barcode,UOM_RATE ;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET record = 1;
 
 
SET record=0;
OPEN curMain;
read_loop: LOOP
FETCH curMain INTO var_Division_Code,var_ItemCode,var_description,var_long_description,var_sellingprcbyct,var_sellingprcbyunit,
var_retunprcbyunit,var_retunprcbyct,var_Active,var_brand,var_Category,var_Sub_Category,var_Barcode,var_upc;
IF record = 1 THEN
LEAVE read_loop;
END IF;
IF(ITEM_STATUS ='A') THEN 
 SET var_Active=1;
 END IF;
SET var_cg_exits = (SELECT IFNULL(COUNT(*),0) FROM companygroup WHERE Alternatecode = var_Division_Code);
IF var_cg_exits = 0 THEN
SET var_max_companygroupcode = (SELECT IFNULL(MAX(companygroupcode),0)+1 FROM companygroup);
INSERT INTO companygroup SELECT var_max_companygroupcode ,var_division_code,1,var_division_code,var_division_code,'ADMIN',NOW(),NULL,NULL,1 ;
ELSE
UPDATE companygroup SET description=var_division_code,arbdescription=var_division_code,modified='admin',mdat=NOW() WHERE alternatecode=var_division_code;
END IF;
SET var_mg_exits = (SELECT IFNULL(COUNT(*),0) FROM MAJORCATEGORY WHERE alternatecode = var_brand);
IF var_mg_exits = 0 THEN
SET var_max_majorcategorycode = (SELECT IFNULL(MAX(majorcategorycode),0)+1 FROM MAJORCATEGORY);
INSERT INTO MAJORCATEGORY SELECT var_max_majorcategorycode ,(SELECT DISTINCT companygroupcode FROM companygroup WHERE alternatecode=var_division_code)  ,var_brand,var_brand,var_brand,'ADMIN',NOW(),NULL,NULL,1 ;
ELSE
UPDATE MAJORCATEGORY SET description=var_brand,arbdescription=var_brand,modified='admin',mdat=NOW() WHERE alternatecode=var_brand;
END IF;
SET var_smg_exits = (SELECT IFNULL(COUNT(*),0) FROM SUBMAJORCATEGORY WHERE alternatecode = var_Category);
IF var_smg_exits = 0 THEN
SET var_max_submajorcategorycode = (SELECT IFNULL(MAX(submajorcategorycode),0)+1 FROM SUBMAJORCATEGORY);
INSERT INTO subMAJORCATEGORY SELECT var_max_submajorcategorycode ,var_Category,(SELECT DISTINCT majorcategorycode FROM majorcategory WHERE alternatecode=var_brand) , var_Category,var_Category,'ADMIN',NOW(),NULL,NULL,1 ;
ELSE
UPDATE SUBMAJORCATEGORY SET description=var_Category,arbdescription=var_Category,modified='admin',mdat=NOW() WHERE alternatecode=var_Category;
END IF;
SET var_ig_exits = (SELECT IFNULL(COUNT(*),0) FROM ItemGroup WHERE alternateitemgroupcode = var_Sub_Category);
IF var_ig_exits = 0 THEN
SET var_max_itemgroupcode = (SELECT IFNULL(MAX(itemgroupcode),0)+1 FROM Itemgroup);
INSERT INTO Itemgroup SELECT var_max_itemgroupcode ,(SELECT DISTINCT submajorcategorycode FROM submajorcategory WHERE alternatecode= var_Category),var_Sub_Category , var_Sub_Category,var_Sub_Category,'ADMIN',NOW(),NULL,NULL,var_Sub_Category,1 ;
ELSE
UPDATE itemgroup SET Itemgroupname=var_Sub_Category,arbitemgroup=var_Sub_Category,modified='admin',mdat=NOW() WHERE alternateitemgroupcode=var_Sub_Category;
END IF;
SET reccount = (SELECT IFNULL(COUNT(*),0) FROM ItemMaster WHERE Alternatecode = var_ItemCode);
IF reccount = 0 THEN 
SET var_max_itemcode = (SELECT IFNULL(MAX(actualItemcode),0)+1 FROM ItemMaster);
INSERT INTO itemmaster 
	(actualitemcode, 	itemgroupcode, 	itemtype, 	itemshortdescription, 	itemdescription, 	unitspercase, 	defaultsalesprice, 	defaultreturnprice, 	defaultretailprice, 	pricingkey, 	arbitemshortdescription, 	arbitemdescription, 	hhcitemshortdescription, 	hhcitemdescription, 	activeitem, 	caseprice, 	returncaseprice, 	retailcaseprice, 	alternatecode, 	created, 	cdat, 	modified, 	mdat, 	liter, 	dataentry, 	leadtime, 	viewflag, 	case1, 	case2, 	memo1, 	memo2, 	tcallowed, 	itemgroupingcode, 	printsequenceroute, 	printsequencecust, 	upccasecode, 	captureshelfstock, 	filmbagbarcode, 	boxtraybarcode, 	cartonbarcode, 	highper, 	lowper, 	literperunit, 	commissionallowedflag, 	alternateitemgroupcode, 	fastmovingitemflag, 	codedateformat, 	itemtaxkey1, 	itemtaxkey2, 	itemtaxkey3, 	defpricetaxkey1, 	defpricetaxkey2, 	defpricetaxkey3, 	packagecode, 	anitemcode, 	averagesales, 	enablemeatpiecescapture, 	itemcompany, 	caseuom, 	warehousestock, 	itemgrpcode, 	parentitemcode, 	shelflife, 	defaultgoodreturnprice, 	defaultgoodreturncaseprice, 	maxpricechange, 	minpricechange, 	allowbatchentry, 	costcaseprice, 	defaultcostprice, 	allowinvoicepricechange, 	reportitemcode, 	offtakeparameter, 	barcode1, 	barcode2, 	barcode3, 	barcode4, 	barcode5, 	barcode6, 	barcode7, 	barcode8, 	barcode9, 	barcode10, 	division, 	majorcategorycode, 	majorcategorydesciption, 	submajorcategorycode, 	submajorcategorydesciption, 	companygroupcode, 	companygroupname, 	itemgroupname, 	itemexpirychk, 	shelflifecapture,Sales_Account,cos_cost_account,cos_stock_account,nominal_category	)
	VALUES
	(var_max_itemcode,(SELECT itemgroupcode FROM ItemGroup WHERE alternateitemgroupcode = var_Sub_Category), 1,var_description,var_long_description,var_upc,var_sellingprcbyunit,var_retunprcbyunit,var_sellingprcbyunit,NULL,'','','','',var_Active,var_sellingprcbyct,var_retunprcbyct,var_sellingprcbyct,var_ItemCode,'admin',NOW(),'null',NULL,0,0,0,0,0,0,var_memo1,var_memo2,'0','null','0','1',UOM,'null','0','0','NULL','NULL','NULL','NULL','NULL',var_ItemCode,'0','0','0','0','0','0','0','0','0',var_ItemCode,'NULL','0','1','1','NULL','NULL','0','0',var_retunprcbyunit,var_retunprcbyct,'0','0','0','0','0','0',var_ItemCode,'0',var_Barcode,'barcode2','barcode3','barcode4','barcode5','barcode6','barcode7','barcode8','barcode9','barcode10',var_Division_Code,var_max_majorcategorycode, var_brand,var_max_submajorcategorycode,var_Category,var_max_companygroupcode,var_division_code,var_Sub_Category,'0','0',var_analysis_x_ref,var_purchase_key,var_analysis_x_ref1,var_nominal_key	);
	
ELSE 
UPDATE itemmaster SET 
itemshortdescription =	var_description	,
itemdescription =	var_long_description	,
unitspercase =	var_upc	,
defaultsalesprice =	var_sellingprcbyunit	,
defaultreturnprice =	var_retunprcbyunit	,
defaultretailprice =	var_sellingprcbyunit	,
activeitem =	var_Active	,
caseprice =	var_sellingprcbyct	,
returncaseprice =	var_retunprcbyct	,
retailcaseprice =	var_sellingprcbyct	,
modified =	'admin'	,
mdat =	NOW()	,
memo1 =	var_memo1	,
memo2 =	var_memo2	,
alternateitemgroupcode =	var_ItemCode	,
anitemcode =	var_ItemCode	,
defaultgoodreturnprice =	var_retunprcbyunit	,
defaultgoodreturncaseprice =	var_retunprcbyct	,
reportitemcode =	var_ItemCode	,
barcode1 =	var_Barcode	,
division =	var_Division_Code	,
majorcategorydesciption =	var_brand	,
submajorcategorydesciption =	var_Category	,
companygroupname =	var_division_code	,
itemgroupname =	var_Sub_Category	,
Sales_Account=	var_analysis_x_ref	,
cos_cost_account=	var_purchase_key	,
cos_stock_account=	var_analysis_x_ref1	,
nominal_category=	var_nominal_key,
upccasecode=UOM	WHERE alternatecode =	var_ItemCode	;
	 																																																																															
 
END IF;
END LOOP read_loop;
CLOSE curMain;  
select "SUCCESS";
END */$$
