/* Procedure structure for procedure `sp_import_post_maintable_fromtemptable` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_import_post_maintable_fromtemptable` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_post_maintable_fromtemptable`(
	IN tablenamevalue TEXT
    )
BEGIN
	IF tablenamevalue = 'temp_customermaster' THEN 
		CALL sp_post_customers_fromtemptable();
			
	ELSEIF tablenamevalue = 'temp_routegoal' THEN 
		CALL sp_post_routegoal();
		
	ELSEIF tablenamevalue = 'temp_routesequence' THEN 
		CALL sp_post_routesequence();
	
	ELSEIF tablenamevalue = 'temp_msllist' THEN 
		CALL sp_post_itemmustlist();
		
	ELSEIF tablenamevalue = 'temp_loadrequest' THEN 
		CALL sp_post_loadrequest();
	
	ELSEIF tablenamevalue = 'temp_freecontract' THEN 
		CALL sp_post_freecontract_header();
		CALL sp_post_freecontract_detail();
		DELETE FROM `temp_freecontract`;
				
	END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_import_pricing_key_oracle` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_import_pricing_key_oracle` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_pricing_key_oracle`(
IN	var_pricing_key	VARCHAR(50),
IN	var_item_code	VARCHAR(20),
IN	var_description	VARCHAR(50),
IN	var_start_date	DATE,
IN	var_end_date	DATE,
IN	var_special_case_price	FLOAT,
IN	var_special_piece_price	FLOAT,
IN	var_special_return_case_price	FLOAT,
IN	var_special_return_price FLOAT,
IN	var_price_list_status	CHAR(1),
IN	var_uom	VARCHAR(10),
IN	var_uom_rate	INT
)
proc_price: BEGIN 
DECLARE VAR_PRICINGKEY BIGINT(50);
DECLARE VAR_THIS_REC_EXIST BIGINT(50);
DECLARE VAR_REC_EXIST INT;
DECLARE VAR_ACTUALCODE INT;
DECLARE var_item_exists INT;
SET var_item_exists=(SELECT EXISTS (SELECT actualitemcode FROM itemmaster WHERE alternatecode=var_item_code));
IF (var_item_exists=0)
THEN
 SIGNAL SQLSTATE '45000'
 SET MESSAGE_TEXT = 'Item Not Found', MYSQL_ERRNO = 1001;
 LEAVE proc_price;
END IF;
SELECT IFNULL(COUNT(*),0) INTO VAR_REC_EXIST FROM customerpricingplanheader1 WHERE alternatecode=var_pricing_key;
 
IF VAR_REC_EXIST=0 THEN
SELECT MAX(pricingplankey)+1 INTO VAR_PRICINGKEY  FROM customerpricingplanheader1 ;
 
INSERT INTO customerpricingplanheader1
(pricingplankey,description,arbdescription,alternatecode,activeindicator)
SELECT  VAR_PRICINGKEY,var_pricing_key,var_pricing_key,var_pricing_key,CASE WHEN var_price_list_status='A' THEN 1 ELSE 0 END  ;
ELSE
SELECT pricingplankey INTO VAR_PRICINGKEY  FROM customerpricingplanheader1 WHERE alternatecode=var_pricing_key;
UPDATE customerpricingplanheader1 SET description=var_pricing_key,activeindicator=CASE WHEN var_price_list_status='A' THEN 1 ELSE 0 END WHERE alternatecode=var_pricing_key AND pricingplankey=VAR_PRICINGKEY;
SELECT MAX(pricingplankey) INTO VAR_PRICINGKEY  FROM customerpricingplanheader1 WHERE alternatecode=var_pricing_key;
END IF;
SELECT IFNULL(COUNT(*),0) INTO VAR_THIS_REC_EXIST FROM customerpricing1 WHERE alternatecode=var_pricing_key;
IF VAR_THIS_REC_EXIST=0 THEN
INSERT INTO customerpricing1
(CustomerPricingKey,PricingPlanKey,Sequencecode,Description,ARBDescription,active,startdate,enddate,alternatecode)
SELECT  VAR_PRICINGKEY,VAR_PRICINGKEY AS PricingPlanKey,'',var_pricing_key,'',CASE WHEN var_price_list_status='A' THEN 1 ELSE 0 END ,var_start_date,var_end_date,var_pricing_key ;
ELSE
UPDATE customerpricing1 SET Description=var_pricing_key, active =CASE WHEN var_price_list_status='A' THEN 1 ELSE 0 END WHERE alternatecode=var_pricing_key;
END IF;
SELECT IFNULL(COUNT(*),0) INTO VAR_THIS_REC_EXIST FROM pricingplanheader1 WHERE customerpricingkey=VAR_PRICINGKEY;
 
IF VAR_THIS_REC_EXIST=0 THEN
INSERT INTO pricingplanheader1(CustomerPricingKey,Description,ARBDescription,TYPE,active)
SELECT  VAR_PRICINGKEY AS CustomerPricingKey,var_pricing_key,'','1',CASE WHEN var_price_list_status='A' THEN 1 ELSE 0 END ;
ELSE
UPDATE pricingplanheader1 SET Description=var_pricing_key,active=CASE WHEN var_price_list_status='A' THEN 1 ELSE 0 END WHERE customerpricingkey=VAR_PRICINGKEY;
END IF;
SELECT actualitemcode INTO VAR_ACTUALCODE FROM itemmaster WHERE alternatecode=var_item_code;
SELECT IFNULL(COUNT(*),0) INTO VAR_THIS_REC_EXIST FROM pricingdetail1 WHERE CustomerPricingKey=VAR_PRICINGKEY AND itemcode= VAR_ACTUALCODE ;
 
IF VAR_THIS_REC_EXIST=0 THEN
INSERT INTO pricingdetail1(CustomerPricingKey,ItemCode,SalesPrice,ReturnPrice,RetailPrice,
SalesCasePrice,ReturnCasePrice,created,cdat,modified,mdat)
 SELECT  VAR_PRICINGKEY ,VAR_ACTUALCODE,var_special_piece_price,var_special_return_price,'',var_special_case_price,var_special_return_case_price,"admin",NOW(),"admin",NOW();
 ELSE
 UPDATE pricingdetail1 SET SalesPrice=var_special_piece_price,ReturnPrice=var_special_return_price,
SalesCasePrice=var_special_case_price,ReturnCasePrice=var_special_return_case_price,modified="admin",mdat=NOW() WHERE CustomerPricingKey=VAR_PRICINGKEY AND itemcode= VAR_ACTUALCODE ;
 END IF;
 
UPDATE customermaster SET pricingkey=(SELECT customerpricingkey FROM pricingplanheader1 WHERE description =customermaster.ALTERNATEPRICINGKEY);
 SELECT "Success";
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_import_routeitemgroup` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_import_routeitemgroup` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_routeitemgroup`()
BEGIN
 
DECLARE var_divisioncode VARCHAR(10);
DECLARE var_routeitemgroupcode INT;
DECLARE var_rp_exits INT DEFAULT 0;
DECLARE record INT DEFAULT 0;	
DECLARE curMain CURSOR FOR   SELECT DISTINCT division FROM division_route_setting ;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET record = 1;
SET record=0;
OPEN curMain;
read_loop: LOOP
FETCH curMain INTO var_divisioncode;
IF record = 1 THEN
LEAVE read_loop;
END IF;
SET var_rp_exits = (SELECT IFNULL(COUNT(*),0) FROM routeitemgrp WHERE description =var_divisioncode);
IF var_rp_exits = 0 THEN
SET var_routeitemgroupcode = (SELECT IFNULL(MAX(routeitemgrpcode)+1,1) FROM routeitemgrp);
INSERT INTO routeitemgrp(routeitemgrpcode,itemgroupcode,description,created,cdat,modified,mdat,transferstatus)
SELECT var_routeitemgroupcode ,var_routeitemgroupcode, var_divisioncode ,'ADMIN',NOW(),'admin',NOW(),1 ;
INSERT INTO routeitemmapping SELECT var_routeitemgroupcode,im.actualitemcode,1 FROM itemmaster im WHERE im.division=var_divisioncode ;
ELSE
SET var_routeitemgroupcode=(SELECT routeitemgrpcode  FROM routeitemgrp WHERE description =var_divisioncode);
DELETE FROM routeitemmapping WHERE routeitemgrpcode =var_routeitemgroupcode;
INSERT INTO routeitemmapping SELECT var_routeitemgroupcode,im.actualitemcode,1 FROM itemmaster im WHERE im.division=var_divisioncode ;
END IF;
END LOOP read_loop;
CLOSE curMain;  
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_import_RouteMaster` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_import_RouteMaster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_RouteMaster`()
BEGIN
 
DECLARE var_divisioncode VARCHAR(10);
DECLARE var_routecode CHAR(40);
DECLARE var_routename CHAR(40);
DECLARE var_salesmancode CHAR(20);
DECLARE var_region CHAR(40);
DECLARE var_mainwhcode CHAR(40);
DECLARE var_activestatus INT(11);
DECLARE var_rp_exits INT DEFAULT 0;
DECLARE var_max_routecode INT DEFAULT 0;
DECLARE record INT DEFAULT 0;	
DECLARE var_routestart INT ;
 
 
DECLARE curMain CURSOR FOR SELECT divisioncode, routecode, routename, salesmancode, region, mainwhcode, activestatus
FROM rp_route ;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET record = 1;
SET record=0;
OPEN curMain;
read_loop: LOOP
FETCH curMain INTO var_divisioncode, var_routecode, var_routename, var_salesmancode, var_region, var_mainwhcode, var_activestatus;
IF record = 1 THEN
LEAVE read_loop;
END IF;
SET var_rp_exits = (SELECT IFNULL(COUNT(*),0) FROM RouteMaster WHERE alternateroutecode =var_routecode);
SET var_routestart =(SELECT routestart FROM division_route_setting WHERE division=var_divisioncode);
IF var_rp_exits = 0 THEN
SET var_max_routecode = (SELECT IFNULL(MAX(routecode),var_routestart)+1 FROM RouteMaster WHERE divisioncode= var_divisioncode);
INSERT INTO routemaster(routecode,routename,alternateroutecode,salesmancode,subareacode,regionmstcode,cmpycode,activestatus,defaultdeliverydays,inventorycaseinput,
promptodominput,itemcodedisplay,usealternatecodes,password1,password5, warehouse,divisioncode,created,cdat,modified,mdat,inventoryvalueprint)
SELECT var_max_routecode ,var_routename, var_routecode ,(SELECT salesmancode FROM salesman WHERE alternatesalesmancode=var_salesmancode),1000,100,
(SELECT cmpycode FROM company WHERE alternatecmpycode= var_divisioncode),var_activestatus,1,1,1,1,1,'111111','111111',var_mainwhcode,var_divisioncode,
'admin',NOW(),'admin',NOW() ,1;
ELSE
UPDATE RouteMaster SET routename=var_routename,warehouse=var_mainwhcode,
divisioncode=var_divisioncode,
salesmancode=(SELECT salesmancode FROM salesman WHERE alternatesalesmancode=var_salesmancode),
cmpycode=(SELECT cmpycode FROM company WHERE alternatecmpycode= var_divisioncode),
activestatus=var_activestatus WHERE alternateroutecode=var_routecode;
END IF;
END LOOP read_loop;
CLOSE curMain;  
UPDATE routemaster SET routeitemgrpcode=(SELECT r.routeitemgrpcode FROM routeitemgrp r WHERE r.description =  divisioncode);
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_import_route_salesman_oracle` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_import_route_salesman_oracle` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_route_salesman_oracle`(
IN	var_division	VARCHAR(10)	,
IN	var_routecode	BIGINT	,
IN	var_routename	VARCHAR(50)	,
IN	var_salesmancode BIGINT	,
IN	var_salesmanname VARCHAR(50)	,
IN	var_whcode	VARCHAR(10)	,
IN	var_mainwh	VARCHAR(10)	,
IN	var_routetype	VARCHAR(10)	,
IN	var_status	CHAR(1)	
)
BEGIN
 
 
DECLARE var_rp_exits INT DEFAULT 0;
DECLARE var_sm_exits INT DEFAULT 0;
DECLARE var_Active INT DEFAULT 0;
 IF(var_status ='A') THEN 
 SET var_Active=1;
 END IF;
 
SET var_sm_exits = (SELECT IFNULL(COUNT(*),0) FROM Salesman WHERE SALESMANCODE =var_salesmancode);
IF var_sm_exits = 0 THEN
	 
	INSERT INTO salesman(Salesmancode,alternatesalesmancode,salesmanname1,TYPE,parentcompany,username,userpassword)
	SELECT var_salesmancode ,var_salesmancode,CASE WHEN TRIM(var_salesmanname)='' THEN 'NoName' ELSE var_salesmanname END  ,1,1,var_salesmanname,'123' ;
	 
ELSE
	UPDATE salesman SET salesmanname1=var_salesmanname WHERE salesmancode=var_salesmancode;
END IF;
 
 
SET var_rp_exits = (SELECT IFNULL(COUNT(*),0) FROM RouteMaster WHERE routecode =var_routecode);
IF var_rp_exits = 0 THEN
INSERT INTO routemaster(routecode,routename,alternateroutecode,salesmancode,subareacode,regionmstcode,cmpycode,activestatus,defaultdeliverydays,inventorycaseinput,
promptodominput,itemcodedisplay,usealternatecodes,password1,password5, division,warehouse,divisioncode,created,cdat,modified,mdat,inventoryvalueprint,enablemiddaytelecom)
SELECT var_routecode ,var_routename, var_routecode ,(SELECT salesmancode FROM salesman WHERE alternatesalesmancode=var_salesmancode),1000,100,
(SELECT cmpycode FROM company WHERE alternatecmpycode= var_division),var_Active,1,1,1,1,1,'111111','111111', var_mainwh , var_whcode ,(SELECT DIVISIONNAME  FROM DIVISIONMASTER WHERE DIVISIONCODE= var_division),
'admin',NOW(),'admin',NOW() ,1,0; 
ELSE
UPDATE RouteMaster SET routename=var_routename,warehouse=var_whcode ,
division =var_mainwh,
divisioncode=(SELECT DIVISIONNAME  FROM DIVISIONMASTER WHERE DIVISIONCODE= var_division),
salesmancode=(SELECT salesmancode FROM salesman WHERE alternatesalesmancode=var_salesmancode),
cmpycode=(SELECT cmpycode FROM company WHERE alternatecmpycode= var_division),
activestatus=var_Active WHERE routecode=var_routecode;
END IF;
SELECT ROW_COUNT();
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_import_Salesman` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_import_Salesman` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_Salesman`()
BEGIN
 declare var_salesmancode char(10);
declare var_salesmanname1 char(60); 
declare var_ansalesmancode char(10); 
declare var_supervisorcode varchar(1); 
declare var_vehregnum varchar(1);
declare var_activestatus int(11); 
declare var_salestype varchar(2);
Declare var_cg_exits int default 0;
Declare var_max_salesmancode int default 0;
Declare record int default 0;	
 
DECLARE curMain CURSOR FOR SELECT  salesmancode, salesmanname1, ansalesmancode, supervisorcode, vehregnum, activestatus, salestype
FROM rp_sman ;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET record = 1;
SET record=0;
OPEN curMain;
read_loop: LOOP
FETCH curMain INTO var_salesmancode, var_salesmanname1, var_ansalesmancode, var_supervisorcode, var_vehregnum, var_activestatus, var_salestype;
IF record = 1 THEN
LEAVE read_loop;
END IF;
SET var_cg_exits = (SELECT IFNULL(COUNT(*),0) FROM salesman WHERE alternatesalesmancode =var_salesmancode);
IF var_cg_exits = 0 THEN
SET var_max_salesmancode = (SELECT IFNULL(MAX(Salesmancode),0)+1 FROM salesman);
INSERT INTO salesman(Salesmancode,alternatesalesmancode,salesmanname1,TYPE,parentcompany,username,userpassword)
 
 SELECT var_max_salesmancode ,var_salesmancode,case when trim(var_salesmanname1)='' then 'Blank' else var_salesmanname1 end  ,1,1,var_salesmanname1,'123' ;
ELSE
UPDATE salesman SET salesmanname1=var_salesmanname1 WHERE alternatesalesmancode=var_salesmancode;
END IF;
END LOOP read_loop;
CLOSE curMain;  
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_import_salesmanstock_oracle` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_import_salesmanstock_oracle` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_salesmanstock_oracle`(
IN var_date_received DATE,
IN var_subinventory CHAR(2),
IN var_ItemCode CHAR(20),
IN var_Issued_qty FLOAT,
IN var_ERPReferenceNumber CHAR(10),
IN var_routecode NUMERIC(18,0)
)
BEGIN
DECLARE var_loadperiod INT;
DECLARE var_route_exists INT;
DECLARE var_item_exists INT;
DECLARE var_Salesman_exists INT;
DECLARE var_rec_exists INT;
SET var_route_exists =(SELECT EXISTS(SELECT routecode FROM routemaster WHERE routecode=var_routecode));
SET var_item_exists =(SELECT EXISTS(SELECT actualitemcode FROM Itemmaster WHERE Alternatecode=var_ItemCode));
SET var_Salesman_exists =(SELECT EXISTS(SELECT salesmancode FROM Routemaster WHERE routecode=var_routecode));
IF (var_route_exists AND  var_item_exists AND var_Salesman_exists) THEN 
	SET var_loadperiod =(SELECT EXISTS (SELECT loadperiodnumber FROM startingloaddetail WHERE ddate=
	var_date_received AND routecode=var_routecode AND erpreferencenumber=var_ERPReferenceNumber));
	IF(var_loadperiod=0) THEN
		SET var_loadperiod=(SELECT IFNULL(MAX(loadperiodnumber),0)+1 FROM startingloaddetail WHERE ddate=	
		var_date_received AND routecode=var_routecode);
		ELSE
		SET var_loadperiod=(SELECT MAX(loadperiodnumber) FROM startingloaddetail WHERE ddate=	
		var_date_received AND routecode=var_routecode);
	END IF;
 SET var_rec_exists=(SELECT EXISTS(SELECT 1 FROM startingloaddetail WHERE ddate = var_date_received AND Routecode=var_routecode 
AND itemcode=(SELECT actualitemcode FROM Itemmaster WHERE Alternatecode=var_ItemCode) AND erpreferencenumber =var_ERPReferenceNumber ));
IF (var_rec_exists=1 )
 THEN
 UPDATE startingloaddetail s INNER JOIN itemmaster im ON im.actualitemcode=s.itemcode SET s.cases=FLOOR(var_Issued_qty),
				s.units=CAST((var_Issued_qty*IM.UNITSPERCASE) AS UNSIGNED) MOD IM.UNITSPERCASE, 
				s.totunits=CAST(var_Issued_qty*IM.UNITSPERCASE AS UNSIGNED)  WHERE s.ddate = var_date_received AND s.Routecode=var_routecode 
AND im.Alternatecode=var_ItemCode AND erpreferencenumber =var_ERPReferenceNumber ;
SELECT ROW_COUNT() AS output; 
			ELSE
			 
INSERT INTO startingloaddetail (ddate,routecode,salesmancode,loadperiodnumber,itemcode,caseprice,cases,
				units,upc,salesprice,batchnumber,expirydate,`status`,
				returnprice,returncaseprice,transactiondate,
				totunits,suggtotunits,rcvdtotunits,currencycode,
				warehouse,warehousestock,loadtime,erpreferencenumber)
				(
				SELECT 	var_date_received,var_routecode,
				(SELECT salesmancode FROM routemaster WHERE routecode=var_routecode),
				var_loadperiod,IM.ACTUALITEMCODE,IM.CASEPRICE,FLOOR(var_Issued_qty) AS cases,
				CAST(var_Issued_qty*IM.UNITSPERCASE AS UNSIGNED) MOD IM.UNITSPERCASE  AS units,unitspercase,defaultsalesprice,'',NULL,0,defaultreturnprice,
				returncaseprice,var_date_received,
				CAST(var_Issued_qty*IM.UNITSPERCASE AS UNSIGNED),0,0,1,var_subinventory,0,CURRENT_TIME(),var_ERPReferenceNumber
				FROM ITEMMASTER IM WHERE ALTERNATECODE=var_ItemCode);
				SELECT ROW_COUNT() AS output; 
			
	END IF;
ELSE
SIGNAL SQLSTATE '45000'
 SET MESSAGE_TEXT = 'Improper Master Data', MYSQL_ERRNO = 1001;
 
 
END IF;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_import_sales_order_status_oracle` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_import_sales_order_status_oracle` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_sales_order_status_oracle`(
    IN var_sales_man  VARCHAR (20) ,
    IN var_route_code VARCHAR (20) ,
    IN var_customer_code VARCHAR (20) ,
    IN var_customer_name VARCHAR (50),
    IN var_order_number VARCHAR (30),
    IN var_order_date DATE ,
    IN var_invoice_no DECIMAL (29),
    IN var_invoice_date DATE ,
    IN var_difference_amount DECIMAL (21),
    IN var_order_status VARCHAR (30) ,
    IN var_alternate_code VARCHAR (50),
    IN var_alternate_order_number  VARCHAR (60),
    IN var_alternate_invoice_number VARCHAR (50),
    IN var_difference_date DATE
     
    
	)
BEGIN
DECLARE VAR_RECORD_EXIST BIGINT(20);
DECLARE var_salesman_code VARCHAR(10);
 
 
 
 
SELECT IFNULL(COUNT(*),0) INTO VAR_RECORD_EXIST FROM orderstatus WHERE invoicenumber=var_invoice_no;
IF VAR_RECORD_EXIST=0 THEN
 INSERT INTO orderstatus (routecode,salesmancode,customercode,customername,ordernumber,orderdate,invoicenumber,invoicedate,differenceamount,STATUS,alternatecode,alternateordernumber,alternateinvoicenumber,differencedate) SELECT var_route_code,var_sales_man,var_customer_code,var_customer_name,var_order_number,var_order_date,var_invoice_no,var_invoice_date,var_difference_amount,var_order_status,var_alternate_code,var_alternate_order_number,var_alternate_invoice_number,var_difference_date;
 
 
ELSE
 
UPDATE orderstatus SET  routecode=var_route_code,
			salesmancode=var_sales_man,
			customercode=var_customer_code,
			customername=var_customer_name,
			ordernumber=var_order_number,
			orderdate=var_order_date,
			invoicedate=var_invoice_date,
			differenceamount=var_difference_amount,
			STATUS=var_order_status,
			alternatecode=var_alternate_code,
			alternateordernumber=var_alternate_order_number,
			alternateinvoicenumber=var_alternate_invoice_number,
			differencedate=var_difference_date WHERE invoicenumber=var_invoice_no;
END IF;
 SELECT "success";
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_import_target` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_import_target` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_target`()
    MODIFIES SQL DATA
BEGIN
Delete from routegoal where routecode in (Select routecode from routemaster where alternateroutecode in(Select distinct routecode from rp_target));
INSERT INTO routegoal(routecode,salesmancode,packagenumber,fromdate,todate,quantity,achievequantity,created,cdat,modified,mdat)
SELECT rm.routecode,sm.salesmancode,2,DATE_FORMAT(CURDATE(), '%Y-%m-01'),LAST_DAY(CURDATE()),t.TargetQty,t.AchievedQty ,
'admin'	,CURDATE(),'admin',CURDATE()
FROM rp_target t INNER JOIN salesman sm ON sm.alternatesalesmancode=t.SalesmanCode
INNER JOIN routemaster rm ON rm.alternateroutecode=t.RouteCode;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_import_WareHouseStock` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_import_WareHouseStock` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_WareHouseStock`()
BEGIN
delete  FROM warehousestock;
INSERT INTO warehousestock
SELECT warehouse,NOW() AS trandate,im.actualitemcode, (physical_qty DIV im.unitspercase  ) AS cases,
((physical_qty%FLOOR(physical_qty))*im.unitspercase) AS units,physical_qty*im.unitspercase AS totalqty ,im.unitspercase,im.caseprice,im.defaultsalesprice,physical_qty 
FROM rp_whstock ws INNER JOIN itemmaster im ON im.alternatecode=ws.product;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_import_warehousestock_oracle` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_import_warehousestock_oracle` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_warehousestock_oracle`(
IN var_warehouse_code VARCHAR(10),
IN var_sub_inventory VARCHAR(10),
IN var_item_code  VARCHAR(20),
IN var_physical_qty NUMERIC
)
BEGIN
DECLARE var_itemcode INT;
SET var_itemcode=(SELECT IFNULL(COUNT(*),0) FROM warehousestock wh INNER JOIN Itemmaster im ON im.actualitemcode=wh.itemcode WHERE  wh.warehousecode= var_warehouse_code AND wh.subInventory=var_sub_inventory  AND im.alternatecode=var_item_code );
IF (var_itemcode <> 0) THEN 
UPDATE warehousestock SET cases=(var_physical_qty*upc DIV upc  ) ,
units=((var_physical_qty*upc) mod upc ) ,
totunits=var_physical_qty*upc,trandate=NOW()
WHERE  warehousecode= var_warehouse_code AND subInventory=var_sub_inventory AND itemcode=var_itemcode;
ELSE
INSERT INTO warehousestock
SELECT var_warehouse_code,NOW() AS trandate,im.actualitemcode, (var_physical_qty*im.unitspercase DIV im.unitspercase  ) AS cases,
((var_physical_qty*im.unitspercase) MOD im.unitspercase ) AS units,var_physical_qty*im.unitspercase AS totalqty ,im.unitspercase,im.caseprice,im.defaultsalesprice,var_physical_qty ,var_sub_inventory
FROM  itemmaster im WHERE im.alternatecode=var_item_code;
END IF;
SELECT ROW_COUNT() AS output;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_appversion` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_appversion` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_appversion`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
	SET @dyn_sql = CONCAT("
		SELECT rm.routecode RouteCode, rm.routename RouteName, sm.alternatesalesmancode SalesmanCode, 
			sm.salesmanname1 SalesmanName, 
			DATE_FORMAT(sed.routestartdate,'%d-%m-%Y') TripStartDate,
			DATE_FORMAT(sed.routeenddate,'%d-%m-%Y') TripEndDate, 
			sed.versionno AppVersionNo,
			sed.dataconrefnumber DeviceID
		FROM startendday sed
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
		WHERE routekey IN (SELECT MAX(sed1.routekey) FROM startendday sed1 GROUP BY sed1.routecode)");
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
	 
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_distribution_check` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_distribution_check` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_distribution_check`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
	DECLARE cond_routecode TEXT;
	
	IF var_routecode = 'All' THEN
		SET cond_routecode = '';	
	ELSE 
		SET cond_routecode = CONCAT("AND coc.routecode IN (", var_routecode, ")");   
	END IF;
	
	SET @dyn_sql = CONCAT("
		SELECT coc.routecode Route, coc.salesmancode Salesman, DATE_FORMAT(coc.visitstartdate,'%Y-%m-%d') VisitDate, 
			cm.alternatecode CustomerCode, cm.customername CustomerName, 
			im.alternatecode ItemCode, im.itemdescription Item, 
			cic.qtyloc1each Quantity, DATE_FORMAT(cic.expiry_date,'%Y-%m-%d') Expiry
	FROM customeroperationscontrol coc 
			INNER JOIN customerinventorycheck cic ON cic.routekey = coc.routekey AND cic.visitkey = coc.visitkey ", cond_routecode, " 
			INNER JOIN itemmaster im ON im.actualitemcode = cic.itemcode
			INNER JOIN customermaster cm ON cm.customercode = coc.customercode
	WHERE DATE_FORMAT(coc.visitstartdate,'%Y-%m-%d') BETWEEN '", var_fromdate , "' AND '", var_todate ,"'
	ORDER BY  coc.routecode, DATE_FORMAT(coc.visitstartdate,'%Y-%m-%d') , cm.alternatecode, im.alternatecode");
	 
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
	 
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_geocodes` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_geocodes` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_geocodes`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
	   
	SET @dyn_sql = CONCAT("
		SELECT alternatecode CustomerCode, customercode CustomerID, customername CustomerName,	
			customeraddress1 Address,
			CASE WHEN invoicepaymentterms < 2 THEN 'CASH' WHEN invoicepaymentterms = 2 THEN 'CREDIT' ELSE 'TC' END PaymentType, 
			fixedlatitude Latitude, fixedlongitude Longitude
		FROM customermaster 
		WHERE fixedlatitude > 0
		ORDER BY alternatecode");
	 
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
	 
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_geocodes_history` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_geocodes_history` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_geocodes_history`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
	   
	SET @dyn_sql = CONCAT("
		SELECT DISTINCT co.routecode Route, co.salesmancode SalesmanID, s.alternatesalesmancode SalesmanCode, s.salesmanname1 Salesman, 
			co.customercode CustomerId, cm.alternatecode CustomerCode, cm.customername Customer, 
			co.latitude Latitude, co.longitude Longitude, DATE_FORMAT(co.visitstartdate,'%Y-%m-%d') VisitDate
		FROM customeroperationscontrol co
			INNER JOIN customermaster cm ON co.customercode=cm.customercode
			INNER JOIN salesman s ON co.salesmancode=s.salesmancode
		WHERE co.latitude > 0 AND co.longitude > 0 AND DATE_FORMAT(co.visitstartdate,'%Y-%m-%d') BETWEEN '", var_fromdate , "' AND '", var_todate ,"' 
		ORDER BY s.alternatesalesmancode, cm.alternatecode");
	 
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
	 
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_otp` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_otp` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_otp`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	SET @dyn_sql = CONCAT("
		SELECT DISTINCT 
	           DATE_FORMAT(aoc.accesstime,'%d-%m-%Y') TranDate,
		   rm.routecode RouteCode, sm.alternatesalesmancode SalesmanCode, sm.salesmanname1 SalesmanName,
		   cm.customercode CustomerID, cm.alternatecode CustomerCode, cm.customername CustomerName, 
		   CASE WHEN cm.invoicepaymentterms < 2 THEN 'CASH' WHEN cm.invoicepaymentterms = 2 THEN 'CREDIT' ELSE 'TC' END PaymentType, 
		   cm.creditlimit CreditLimit, cm.creditlimitdays CreditDays,
		   CASE WHEN aoc.featureid = 1 THEN 'GPS' WHEN aoc.featureid = 2 THEN 'JourneyPlan' 
			WHEN aoc.featureid = 6 THEN 'Returns' WHEN aoc.featureid = 4 THEN 'CreditLimit' WHEN aoc.featureid = 5 THEN 'CreditDays' ELSE '' END OTPUsedFor		   
		FROM t_access_override_log aoc
		   INNER JOIN customermaster cm ON cm.customercode = aoc.customercode
		   INNER JOIN routemaster rm ON rm.routecode = aoc.routecode
		   INNER JOIN salesman sm ON sm.salesmancode = aoc.salesmancode
		WHERE DATE_FORMAT(aoc.accesstime,'%Y-%m-%d') BETWEEN '", var_fromdate , "' AND '", var_todate ,"' 
		ORDER BY aoc.routecode, aoc.customercode");
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
	 
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_running_promotions` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_running_promotions` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_running_promotions`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
	   
	SET @dyn_sql = CONCAT("
		SELECT pkd.plannumber PromoPlan, pph.plandescription Description, 
			DATE_FORMAT(pkd.startdate,'%Y-%m-%d') StartDate, DATE_FORMAT(pkd.enddate,'%Y-%m-%d') EndDate, 
			pgh.groupnumber GroupNo, im.itemdescription Item, im.defaultsalesprice SalesPrice,
			pa.rangelow RangeLow, pa.rangehigh RangeHigh, CASE pa.repeatingrange WHEN 0 THEN 'NO' ELSE 'YES' END RepeatRange, 
			pa.promotionamount PromoValue
		FROM promokeydetail pkd
				INNER JOIN promoplanheader pph ON pph.plannumber = pkd.plannumber
				INNER JOIN productgroupheader pgh ON pgh.groupnumber = pkd.qualificationgroup
				INNER JOIN productgroupdetail pgd ON pgd.groupnumber = pgh.groupnumber
				INNER JOIN itemmaster im ON im.actualitemcode = pgd.itemcode
				INNER JOIN promotionassignmentadvanced pa ON pa.assignmentnumber = pkd.assignmentnumber
		WHERE DATE_FORMAT(pkd.enddate,'%Y-%m-%d') >= CURDATE()");
	 
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
	 
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_visitplan` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_visitplan` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_visitplan`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
	DECLARE cond_routecode TEXT;
	
	IF var_routecode = 'All' THEN
		SET cond_routecode = '';	
	ELSE 
		SET cond_routecode = CONCAT("AND rs.routecode IN (", var_routecode, ")");   
	END IF;
	   
	SET @dyn_sql = CONCAT("
		SELECT rm.routecode RouteCode, rm.routename Route, rs.rp32weeknumber WeekNo, 
			cm.customercode CustomerID, cm.alternatecode CustomerCode, cm.customername CustomerName,	
			CASE WHEN rs.callrestrictiondays6 = 1 THEN 'YES' ELSE '' END Saturday,
			CASE WHEN rs.callrestrictiondays7 = 1 THEN 'YES' ELSE '' END Sunday,
			CASE WHEN rs.callrestrictiondays1 = 1 THEN 'YES' ELSE '' END Monday,
			CASE WHEN rs.callrestrictiondays2 = 1 THEN 'YES' ELSE '' END Tuesday,
			CASE WHEN rs.callrestrictiondays3 = 1 THEN 'YES' ELSE '' END Wednesday,
			CASE WHEN rs.callrestrictiondays4 = 1 THEN 'YES' ELSE '' END Thursday,
			CASE WHEN rs.callrestrictiondays5 = 1 THEN 'YES' ELSE '' END Friday,
			cm.fixedlatitude Latitude, cm.fixedlongitude Longitude
		FROM routesequence rs
			INNER JOIN customermaster cm ON cm.customercode = rs.customercode
			INNER JOIN routemaster rm ON rm.routecode = rs.routecode 
		WHERE rm.activestatus=1 ", cond_routecode, " 
		ORDER BY rm.routecode, rs.rp32weeknumber, cm.alternatecode");
	 
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
	 
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_void` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_void` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_void`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN	
	SET @dyn_sql = CONCAT("
		SELECT DATE_FORMAT(void.transactiondate,'%d-%m-%Y') TranDate, void.trantype Transaction, rm.routecode Route, 
		sm.alternatesalesmancode SalesmanCode, sm.salesmanname1 SalesmanName, 
		void.invoicenumber TransactionNo, 
		cm.customercode CustomerID, cm.alternatecode CustomerCode, cm.customername CustomerName, 
		void.totalinvoiceamount TransactionAmount
		FROM
			(
			SELECT 'SALES' trantype, transactiondate, routecode, salesmancode, invoicenumber, customercode, totalinvoiceamount
			FROM invoiceheader
			WHERE voidflag = 1 AND transactiondate BETWEEN '", var_fromdate , "' AND '", var_todate ,"' 
			UNION
			SELECT 'COLLECTION' trantype, transactiondate, routecode, salesmancode, invoicenumber, customercode, totalinvoiceamount
			FROM arheader
			WHERE voidflag = 1 AND transactiondate BETWEEN '", var_fromdate , "' AND '", var_todate ,"' 
			UNION
			SELECT 'ORDER' trantype, transactiondate, routecode, salesmancode, invoicenumber, customercode, totalinvoiceamount
			FROM salesorderheader
			WHERE voidflag = 1 AND transactiondate BETWEEN '", var_fromdate , "' AND '", var_todate ,"' 
			) void
			INNER JOIN routemaster rm on rm.routecode = void.routecode
			INNER JOIN salesman sm on sm.salesmancode = void.salesmancode
			INNER JOIN customermaster cm on cm.customercode = void.customercode
		ORDER BY void.transactiondate, void.trantype");
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
	 
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_post_category_channel` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_post_category_channel` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_category_channel`()
BEGIN
	
	DECLARE Customercategory VARCHAR(50); 
	DECLARE Customerchannel VARCHAR(50); 
	
	DECLARE done INT DEFAULT FALSE;
	
	DECLARE cur_one CURSOR FOR 
		( SELECT DISTINCT customercategory, customerchannel FROM imp_customermaster );
		
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
					
	OPEN cur_one;
	read_loop_one: LOOP
		
		FETCH cur_one INTO Customercategory, Customerchannel;
		
		IF done = TRUE THEN
			LEAVE read_loop_one;
		END IF;
		
		
		INSERT INTO channelmaster SET
			alternatecode = Customerchannel,
			channelname = Customerchannel,
			arbchannelname = Customerchannel,
			created = 'admin',
			cdat = CURDATE(),
			activestatus = 1
		ON DUPLICATE KEY UPDATE
			channelname = Customerchannel,
			arbchannelname = Customerchannel,
			modified = 'admin',
			mdat = CURDATE();
			
		
		INSERT INTO categorymaster SET 	
			alternatecode = Customercategory,
			categoryname = Customercategory,
			arbcategoryname = Customercategory,
			created = 'admin',
			cdat = CURDATE(),
			activestatus = 1
		ON DUPLICATE KEY UPDATE 
			categoryname = Customercategory,
			arbcategoryname = Customercategory,
			modified = 'admin',
			mdat = CURDATE();
		
		END LOOP read_loop_one;
	
	CLOSE cur_one;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_post_customers` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_post_customers` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_customers`()
BEGIN	
	SET @routecode = 0;
	SELECT MIN(routecode) routecode INTO @routecode  FROM routemaster;
	
	UPDATE customermaster SET alternatecode = CONCAT('XYZ.',customercode);
	UPDATE imp_customermaster SET pricingkey = 0 WHERE pricingkey = '';	
	DELETE FROM imp_customermaster WHERE customerreferenceno = '';
	
	SET @excepstarton = '2016-01-01 01:01:01';
	SET @excependon = '2016-01-01 01:01:01';
	
	INSERT INTO customermaster 
		(customercode, TYPE, headofficecode, routecode, customername, customeraddress1, customeraddress2, customeraddress3, customerphone, channelcode, customercategory, 
		pricingkey, invoicepaymentterms, invoiceformatoption, contactname, activecustomer, creditlimitdays, created, cdat, memo1, memo2, invoicepriceprint, enabledelayprint,
		printsequence, enablepriceeditinvs, enablesellprevious, enableautofillreturns, enableautofilldamaged, enablesigcapture, enablereturnstrxn, enableexchangetrxn,
		enabledamagedreturns, enablearcollection, enableinvoicecomment, forcestockcapture, enablepromotrxn, alternatecode, creditlimit, templateindicator, templatename,
		printlanguageflag, enablepromoeditinvs, enablesalestrxn, enableinvoicecopy, enableautofillsales, barcode, division, ancustomercode, arbcustomername,
		statementdays, promotionkey, graceperiod, enablereturnpassword,startdate,enddate)
		
	SELECT cm.customercode, 1 TYPE, cm.customercode headofficecode, @routecode routecode, REPLACE(cm.customername,"'","`") customername,  REPLACE(cm.customeraddress1,"'","`") customeraddress1, 
		REPLACE(cm.customeraddress2,"'","`") customeraddress2, REPLACE(cm.customeraddress3,"'","`") customeraddress3, cm.phonenumber, chm.channelcode, cat.categoryid, 
		CAST(cm.pricingkey AS UNSIGNED) pricingkey, cm.invoicepaymentterms, 2 invoiceformatoption, REPLACE(cm.contactname,"'","`") customeraddress1, cm.activestatus, 
		cm.creditlimitdays, 'admin', CURDATE(), REPLACE(cm.memo1,"'","`") memo1, REPLACE(cm.memo2,"'","`") memo2, 1 invoicepriceprint, 1 enabledelayprint, 2 printsequence, 
		1 enablepriceeditinvs, 1 enablesellprevious, 1 enableautofillreturns, 1 enableautofilldamaged, 1 enablesigcapture, 3 enablereturnstrxn, 
		CASE WHEN cm.invoicepaymentterms = 2 THEN 0 ELSE 1 END enableexchangetrxn, 
		1 enabledamagedreturns, 
		CASE WHEN cm.invoicepaymentterms = 2 THEN 1 ELSE 0 END  enablearcollection, 1 enableinvoicecomment, 
		1 forcestockcapture, 3 enablepromotrxn, 
		CASE WHEN cm.reccount > 1 THEN CONCAT(cm.atribute1,'-',cm.reccount) ELSE cm.atribute1 END alternatecode, 
		cm.creditlimitamount, 0 templateindicator, cm.customerclass, 1 printlanguageflag, 1 enablepromoeditinvs, cm.credithold enablesalestrxn, 1 enableinvoicecopy, 
		1 enableautofillsales, cm.alternatecode barcode, 0 division, cm.customerreferenceno ancustomercode, cm.arbcustomername,
		CASE WHEN cm.memo1 = 'MonthEnd' THEN 1 ELSE 0 END statementdays, 1 promotionkey,
		cm.atribute2 graceperiod, 1 enablereturnpassword, @excepstarton, @excependon
	FROM imp_customermaster cm
		LEFT OUTER JOIN categorymaster cat ON cat.alternatecode = cm.customercategory
		LEFT OUTER JOIN channelmaster chm ON chm.alternatecode = cm.customerchannel
	
		ON DUPLICATE KEY UPDATE 
			customermaster.customername = REPLACE(cm.customername,"'","`"), 
			customermaster.arbcustomername = REPLACE(cm.arbcustomername,"'","`"), 
			customermaster.customeraddress1 =  REPLACE(cm.customeraddress1,"'","`"), 
			customermaster.customeraddress2 =  REPLACE(cm.customeraddress2,"'","`"), 
			customermaster.customeraddress3 = REPLACE(cm.customeraddress3,"'","`"), 
			customermaster.contactname = REPLACE(cm.contactname,"'","`"), 
			customermaster.alternatecode = CASE WHEN cm.reccount > 1 THEN CONCAT(cm.atribute1,'-',cm.reccount) ELSE cm.atribute1 END,
			customermaster.barcode = cm.alternatecode,
			customermaster.channelcode = chm.channelcode,
			customermaster.customercategory = cat.categoryid,
			customermaster.templatename = REPLACE(cm.customerclass,"'","`"),
			customermaster.pricingkey = cm.pricingkey,
			customermaster.enableexchangetrxn = CASE WHEN cm.invoicepaymentterms = 2 THEN 0 ELSE 1 END,
			customermaster.invoicepaymentterms = cm.invoicepaymentterms,
			customermaster.creditlimit = cm.creditlimitamount,
			customermaster.creditlimitdays = cm.creditlimitdays,
			customermaster.statementdays = CASE WHEN cm.memo1 = 'MonthEnd' THEN 1 ELSE 0 END,
			customermaster.enablesalestrxn = 1, 
			customermaster.memo1 = REPLACE(cm.memo1,"'","`"),
			customermaster.memo2 = REPLACE(cm.memo2,"'","`"),
			customermaster.activecustomer = cm.activestatus,
			customermaster.modified = 'admin', 
			customermaster.mdat = CURRENT_DATE(),
			customermaster.enablearcollection = CASE WHEN cm.invoicepaymentterms = 2 THEN 1 ELSE 0 END,
			customermaster.graceperiod = cm.atribute2,
			customermaster.startdate = @excepstarton,
			customermaster.enddate = @excependon;
	
	
	UPDATE customermaster SET enablearcollection = 0 WHERE alternatecode IN ('DA8683','DA11496','DE455','DE455-2');
	
	
	SET @excepstarton = '2016-01-01 01:01:01';
	SET @excependon = '2020-12-31 01:01:01';
	UPDATE customermaster SET startdate = @excepstarton, enddate = @excependon WHERE pricingkey IN
		(SELECT pricingplankey FROM customerpricingplanheader1 WHERE description IN ('P09','P17','P18') );
		
	UPDATE customermaster SET roundnetamount= 2, roundingoffvalue=2 WHERE invoicepaymentterms < 2;
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_post_freecontract_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_post_freecontract_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_freecontract_detail`()
BEGIN
	
	DECLARE cu_customerid INT(10);
	DECLARE cu_contractid INT(10);
	DECLARE cu_startdate DATE;
	DECLARE cu_enddate DATE;
	DECLARE cu_itemid INT(10);
	DECLARE cu_qty INT(10);
	DECLARE cu_upc INT(10);
	DECLARE cu_route INT(10);
	
	DECLARE done INT DEFAULT FALSE;
		
	DECLARE cur_one CURSOR FOR 
		(SELECT customerid, customerid contractid, startdate, enddate, itemid, qty*upc qty, upc, route
			FROM temp_freecontract WHERE customerid > 0 AND itemid > 0);	
	
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
	
	OPEN cur_one;
	read_loop_one: LOOP
		
		FETCH cur_one INTO cu_customerid, cu_contractid, cu_startdate, cu_enddate, cu_itemid, cu_qty, cu_upc, cu_route;
			
			IF done = TRUE THEN
				LEAVE read_loop_one;
			END IF;
			
			INSERT INTO customer_foc (customercode, contractid, creationdate, remarks, startdate, enddate, active, depotcode)
				VALUES (cu_customerid, cu_contractid, CURDATE(), '', cu_startdate, cu_enddate, 1, cu_route)
			ON DUPLICATE KEY UPDATE
					creationdate = CURDATE(), 
					startdate = cu_startdate, 
					enddate = cu_enddate;			
			
			INSERT INTO customer_foc_detail (customercode, contractid, itemcode, freequantity, editdate, remarks)
				VALUES (cu_customerid, cu_contractid, cu_itemid, cu_qty, CURDATE(), '')
			ON DUPLICATE KEY UPDATE
					editdate = CURDATE(), 
					freequantity = cu_qty;
			
			INSERT INTO customer_foc_balance (customercode, itemcode, originalqty, balanceqty, contractid, startdate)
				VALUES (cu_customerid, cu_itemid, cu_qty, cu_qty, cu_contractid, cu_startdate)
			ON DUPLICATE KEY UPDATE
					startdate = cu_startdate, 
					originalqty = cu_qty,
					balanceqty = cu_qty;
					
	END LOOP read_loop_one;
	
	CLOSE cur_one;
	
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_post_freecontract_header` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_post_freecontract_header` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_freecontract_header`()
BEGIN
	UPDATE temp_freecontract fc
		INNER JOIN customermaster cm ON cm.alternatecode = REPLACE(fc.customercode,' ','') 
	SET fc.customerid = cm.customercode;
	
	UPDATE temp_freecontract fc
		INNER JOIN itemmaster im ON im.alternatecode = REPLACE(fc.itemcode,' ','') 
	SET fc.itemid = im.actualitemcode, fc.upc = im.unitspercase;
	
	UPDATE temp_freecontract SET 
		startdate = DATE_FORMAT(STR_TO_DATE(startdate, '%d/%m/%Y'), '%Y-%m-%d'), enddate = DATE_FORMAT(STR_TO_DATE(enddate, '%d/%m/%Y'), '%Y-%m-%d');
	
	UPDATE temp_freecontract SET customerid = 0 WHERE customerid IS NULL;
	UPDATE temp_freecontract SET itemid = 0 WHERE itemid IS NULL;
	
	UPDATE temp_freecontract SET temp_freecontract.route = 
		COALESCE((SELECT MAX(rs.routecode) FROM routesequence rs WHERE rs.customercode = temp_freecontract.customerid), 0);
    END */$$
DELIMITER ;

