/* Procedure structure for procedure `sp_post_routegoal` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_post_routegoal` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_routegoal`()
BEGIN 
  DECLARE code CHAR(5) DEFAULT '00000';
  DECLARE msg TEXT;
  DECLARE rows1 INT;
  DECLARE result TEXT;
  
   
  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
    BEGIN
      GET DIAGNOSTICS CONDITION 1
        code = RETURNED_SQLSTATE, msg = MESSAGE_TEXT;
    END;
  
UPDATE temp_routegoal SET packagenumber = 2 WHERE targettype IN (1,2,6,7) AND packagenumber=1;
	DELETE FROM routegoal 
	USING routegoal, temp_routegoal
	WHERE temp_routegoal.routecode = routegoal.routecode AND 
			temp_routegoal.packagenumber = routegoal.packagenumber AND 
			temp_routegoal.fromdate = routegoal.fromdate AND 
			temp_routegoal.todate = routegoal.todate AND
			temp_routegoal.targettype = routegoal.targettype;
	
	INSERT INTO routegoal
		(routecode, salesmancode, packagenumber, fromdate, todate, quantity, achievequantity, achieveamount,
			todaysgoal, todaysachieve, targettype, commision, commisonpercent, insentive, insentivepercent, goaltype, cdat)
	SELECT 
		rs.routecode, rm.salesmancode, rs.packagenumber, rs.fromdate, rs.todate, rs.quantity, 0, 0,
			0, 0, rs.targettype, rs.commision, 0, rs.insentive, 0, 0, NOW()
	FROM temp_routegoal rs 
		INNER JOIN routemaster rm ON rm.routecode = rs.routecode
	
	ON DUPLICATE KEY UPDATE 
		cdat = NOW(),
		quantity = rs.quantity;
 
  
  IF code = '00000' THEN
    GET DIAGNOSTICS rows1 = ROW_COUNT;
    SET result = CONCAT('insert succeeded, row count = ',rows1);
  ELSE
    SET result = CONCAT('insert failed, error = ',code,', message = ',msg);
  END IF;
  
  SELECT result;
  SELECT count(*) as counter FROM temp_routegoal;
      
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_post_routesequence` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_post_routesequence` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_routesequence`()
BEGIN 
  DECLARE CODE CHAR(5) DEFAULT '00000';
  DECLARE msg TEXT;
  DECLARE ROWS1 INT;
  DECLARE result TEXT;
  DECLARE CONTINUE HANDLER FOR SQLEXCEPTION
  BEGIN
    GET DIAGNOSTICS CONDITION 1
      CODE = RETURNED_SQLSTATE, msg = MESSAGE_TEXT;
    SET result = CONCAT('Insert failed, error = ', CODE, ', message = ', msg);
  END;
  DELETE FROM routesequence 
  WHERE routecode IN (SELECT DISTINCT routecode FROM temp_routesequence);
  INSERT INTO routesequence
    (rp32weeknumber, routecode, customercode, callrestrictiondays1, callrestrictiondays2, 
     callrestrictiondays3, callrestrictiondays4, callrestrictiondays5, callrestrictiondays6, callrestrictiondays7, 
     monseq, tueseq, wedseq, thuseq, friseq, satseq, sunseq, mdat, referenceno)
  SELECT 
    seq.weeknumber, seq.routecode, seq.customercode, 
    seq.monvisit, seq.tuevisit, seq.wedvisit, seq.thuvisit, seq.frivisit, seq.satvisit, seq.sunvisit,
    seq.monsequence, seq.tuesequence, seq.wedsequence, seq.thusequence, seq.frisequence, seq.satsequence, seq.sunsequence,
    seq.mdat, seq.refno
  FROM (
    SELECT 
      rs.weeknumber, rs.routecode, cm.customercode, 
      CASE WHEN SUM(rs.monvisit) >= 1 THEN 1 ELSE 0 END AS monvisit, 
      CASE WHEN SUM(rs.tuevisit) >= 1 THEN 1 ELSE 0 END AS tuevisit, 
      CASE WHEN SUM(rs.wedvisit) >= 1 THEN 1 ELSE 0 END AS wedvisit, 
      CASE WHEN SUM(rs.thuvisit) >= 1 THEN 1 ELSE 0 END AS thuvisit, 
      CASE WHEN SUM(rs.frivisit) >= 1 THEN 1 ELSE 0 END AS frivisit, 
      CASE WHEN SUM(rs.satvisit) >= 1 THEN 1 ELSE 0 END AS satvisit, 
      CASE WHEN SUM(rs.sunvisit) >= 1 THEN 1 ELSE 0 END AS sunvisit,
      rs.monsequence, rs.tuesequence, rs.wedsequence, rs.thusequence, rs.frisequence, rs.satsequence, rs.sunsequence,
      CURDATE() AS mdat, NULL AS refno
    FROM temp_routesequence rs
      INNER JOIN customermaster cm ON cm.alternatecode = rs.customercode
      INNER JOIN routemaster rm ON rm.routecode = rs.routecode
    GROUP BY rs.weeknumber, rs.routecode, cm.customercode
  ) seq
  ON DUPLICATE KEY UPDATE
    rp32weeknumber = seq.weeknumber,
    routecode = seq.routecode,
    customercode = seq.customercode,
    callrestrictiondays1 = seq.monvisit,
    callrestrictiondays2 = seq.tuevisit,
    callrestrictiondays3 = seq.wedvisit,
    callrestrictiondays4 = seq.thuvisit,
    callrestrictiondays5 = seq.frivisit,
    callrestrictiondays6 = seq.satvisit,
    callrestrictiondays7 = seq.sunvisit,
    monseq = seq.monsequence,
    tueseq = seq.tuesequence,
    wedseq = seq.wedsequence,
    thuseq = seq.thusequence,
    friseq = seq.frisequence,
    satseq = seq.satsequence,
    sunseq = seq.sunsequence,
    mdat = seq.mdat;
  IF CODE = '00000' THEN
    GET DIAGNOSTICS ROWS1 = ROW_COUNT;
    SET result = CONCAT('Insert succeeded, row count = ', ROWS1);
  END IF;
  SELECT result;
  SELECT COUNT(*) AS counter FROM temp_routesequence;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_post_submajorcategory` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_post_submajorcategory` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_submajorcategory`(
)
BEGIN
	DECLARE cu_majorcategoryid INT(8);
	DECLARE cu_subcategoryid INT(8);
	DECLARE cu_alternatecode VARCHAR(50);
	DECLARE cu_subcategoryname VARCHAR(50);
	
	DECLARE done INT DEFAULT FALSE;
		
	DECLARE cur_one CURSOR FOR 
		(SELECT DISTINCT (SELECT MIN(majorcategorycode) FROM majorcategory) majorcategorycode,
			subcategoryid, subcategory, CONCAT(subcategoryname,' - ', subcategory) subcategoryname
		 FROM imp_itemmaster);
	
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
	
	OPEN cur_one;
	read_loop_one: LOOP
		
		FETCH cur_one INTO cu_majorcategoryid, cu_subcategoryid, cu_alternatecode, cu_subcategoryname;
			
			IF done = TRUE THEN
				LEAVE read_loop_one;
			END IF;
			
			INSERT INTO submajorcategory SET 	
				submajorcategorycode = cu_subcategoryid,
				alternatecode = cu_alternatecode,
				description = cu_subcategoryname, 
				arbdescription = cu_subcategoryname, 
				majorcategorycode = cu_majorcategoryid,
				activestatus = 1, 
				cdat = CURDATE(), 
				created = 'admin'
		ON DUPLICATE KEY UPDATE 
				description = cu_subcategoryname, 
				arbdescription = cu_subcategoryname,
				mdat = CURDATE(),
				modified = 'admin';
			
	END LOOP read_loop_one;
	
	CLOSE cur_one;
	
					
END */$$
DELIMITER ;

/* Procedure structure for procedure `SP_Productivity_Strike_Rate_New` */

/*!50003 DROP PROCEDURE IF EXISTS  `SP_Productivity_Strike_Rate_New` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `SP_Productivity_Strike_Rate_New`(
    IN vardivisioncode VARCHAR(500),
    IN varMonth INT,
    IN varYear INT
    )
BEGIN
truncate table temp_strike_table_vw_new;
 
IF vardivisioncode = '0' THEN
INSERT INTO temp_strike_table_vw_new 
SELECT rm.divisioncode,sm.salesmancode AS salesmancode,sm.salesmanname1,  sm.arbsalesmanname1, 
0 AS Mtd_odometer,
0 AS plannedcalls, 
0 AS actualcalls, 0 AS unschedulecall,
0 AS cashsale, 0 AS creditsale , 
0 AS orders,
0 AS `returns`,
0 AS productivecalls, 
0 AS totalreceipt,
0 AS strikerate,
0 AS productiverate,
0 AS CustomerFaceTime,
0 AS OTPUsedCount,
0 AS settlementskipeddays,
0 AS CFTMin
FROM startendday sed	
INNER JOIN routemaster rm ON sed.routecode = rm.routecode
INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
WHERE 1=1  AND MONTH (sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear  
GROUP BY sed.routecode  ;
ELSE
 
INSERT INTO temp_strike_table_vw_new 
SELECT rm.divisioncode,sm.salesmancode AS salesmancode,sm.salesmanname1,  sm.arbsalesmanname1, 
0 AS Mtd_odometer,
0 AS plannedcalls, 
0 AS actualcalls, 0 AS unschedulecall,
0 AS cashsale, 0 AS creditsale , 
0 AS orders, 
0 AS `RETURNS`, 
0 AS productivecalls, 
0 AS totalreceipt,
0 AS strikerate,
0 AS productiverate,
0 AS CustomerFaceTime,
0 AS OTPUsedCount,
0 AS settlementskipeddays,
0 AS CFTMin
FROM startendday sed	
INNER JOIN routemaster rm ON sed.routecode = rm.routecode
INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
INNER JOIN divisionmaster dm ON dm.divisionname=rm.divisioncode
WHERE FIND_IN_SET(dm.divisioncode, vardivisioncode) AND MONTH (sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear  
GROUP BY sed.routecode  ;
END IF;
UPDATE temp_strike_table_vw_new t INNER JOIN (
SELECT salesmancode,SUM(CASE WHEN routeendodometer =0 THEN 0 ELSE IFNULL(routeendodometer-routestartodometer,0) END) AS mtdodometer FROM startendday   sed1
WHERE MONTH (sed1.routestartdate) = varMonth AND YEAR(sed1.routestartdate) = varYear GROUP BY salesmancode 
) u
ON t.salesmancode=u.salesmancode
SET t.Mtd_odometer=u.mtdodometer;
UPDATE temp_strike_table_vw_new t INNER JOIN (
SELECT  Salesmancode,SUM(callcount) AS plannedcalls FROM (
SELECT sed1.salesmancode,rs.routekey ,COUNT(*) AS callcount FROM routesequencecustomerstatus rs 
INNER JOIN startendday sed1 ON rs.routekey=sed1.routekey AND sed1.routecode=rs.routecode 
WHERE rs.schelduledflag = 1 AND 
MONTH (sed1.routestartdate) = varMonth AND YEAR(sed1.routestartdate) = varYear
GROUP BY rs.routekey,rs.customercode)t
GROUP BY salesmancode
) u
ON t.salesmancode=u.salesmancode
SET t.plannedcalls=u.plannedcalls;
UPDATE temp_strike_table_vw_new t INNER JOIN (
SELECT  Salesmancode,SUM(callcount) AS ActualCalls FROM (
SELECT sed1.salesmancode,rs.routekey ,COUNT(*) AS callcount FROM routesequencecustomerstatus rs 
INNER JOIN startendday sed1 ON rs.routekey=sed1.routekey AND sed1.routecode=rs.routecode 
WHERE rs.servicedflag  = 1 AND 
MONTH (sed1.routestartdate) = varMonth AND YEAR(sed1.routestartdate) = varYear
GROUP BY rs.routekey,rs.customercode)t
GROUP BY salesmancode
) u
ON t.salesmancode=u.salesmancode
SET t.actualcalls=u.ActualCalls;
UPDATE temp_strike_table_vw_new t INNER JOIN 
(SELECT ih.salesmancode,COUNT(*) AS cashSalescount  FROM INVOICEHEader ih 
INNER JOIN startendday sed ON sed.routekey=ih.routekey AND sed.routecode=ih.routecode 
INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
WHERE  ih.immediatepaid > 0 AND ih.voidflag = 0  AND (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear)  GROUP BY ih.salesmancode) 
 u
ON t.salesmancode=u.salesmancode
SET t.cashsale=u.cashSalescount;
UPDATE temp_strike_table_vw_new t INNER JOIN 
(SELECT ih.salesmancode,COUNT(*) AS creditsale  FROM INVOICEHEader ih 
INNER JOIN startendday sed ON sed.routekey=ih.routekey AND sed.routecode=ih.routecode 
INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
WHERE  ih.immediatepaid =0 AND totalsalesamount>0 AND ih.voidflag = 0  AND (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear)  GROUP BY ih.salesmancode )
 u
ON t.salesmancode=u.salesmancode
SET t.creditsale=u.creditsale;
UPDATE temp_strike_table_vw_new t INNER JOIN 
(SELECT ih.salesmancode,COUNT(*) AS grvcount  FROM INVOICEHEader ih 
INNER JOIN startendday sed ON sed.routekey=ih.routekey AND sed.routecode=ih.routecode 
INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
WHERE ih.totalinvoiceamount < 0  AND ih.totalsalesamount=0  AND ih.voidflag = 0  AND (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear)  GROUP BY ih.salesmancode )
 u
ON t.salesmancode=u.salesmancode
SET t.returns=u.grvcount;
UPDATE temp_strike_table_vw_new t INNER JOIN 
(SELECT ih.salesmancode,COUNT(*) AS ordercount  FROM Salesorderheader ih 
INNER JOIN startendday sed ON sed.routekey=ih.routekey AND sed.routecode=ih.routecode 
INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
WHERE ih.voidflag = 0  AND (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear)  GROUP BY ih.salesmancode )
 u
ON t.salesmancode=u.salesmancode
SET t.orders=u.ordercount;
UPDATE temp_strike_table_vw_new t INNER JOIN (
SELECT  Salesmancode,SUM(callcount) AS unschedulecall FROM (
SELECT sed1.salesmancode,rs.routekey ,COUNT(*) AS callcount FROM routesequencecustomerstatus rs 
INNER JOIN startendday sed1 ON rs.routekey=sed1.routekey AND sed1.routecode=rs.routecode 
WHERE rs.servicedflag = 1 AND  rs.schelduledflag = 0  AND 
MONTH (sed1.routestartdate) = varMonth AND YEAR(sed1.routestartdate) = varYear
GROUP BY rs.routekey,rs.customercode)t
GROUP BY salesmancode
) u
ON t.salesmancode=u.salesmancode
SET t.unschedulecall=u.unschedulecall;
UPDATE temp_strike_table_vw_new t INNER JOIN 
(SELECT ah.salesmancode,COUNT(*) AS receipts  FROM arheader ah 
INNER JOIN startendday sed ON ah.routekey= sed.routekey AND ah.routecode= sed.routecode 
INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
WHERE  1=1   AND (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear)  GROUP BY ah.salesmancode )
 u
ON t.salesmancode=u.salesmancode
SET t.totalreceipt=u.receipts;
 
 UPDATE temp_strike_table_vw_new t INNER JOIN (
SELECT  Salesmancode,count(DISTINCT customercode,routestartdate) as productivecalls FROM (
SELECT  coc.Salesmancode,coc.customercode,sed.routestartdate FROM invoiceheader coc
INNER JOIN startendday sed ON coc.routecode = sed.routecode AND coc.routekey = sed.routekey
WHERE  (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear)
UNION
SELECT  coc.Salesmancode,customercode,sed.routestartdate FROM salesorderheader coc
INNER JOIN startendday sed ON coc.routecode = sed.routecode AND coc.routekey = sed.routekey
WHERE  (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear)
UNION
SELECT  coc.Salesmancode,customercode,sed.routestartdate FROM arheader coc
INNER JOIN startendday sed ON coc.routecode = sed.routecode AND coc.routekey = sed.routekey
WHERE  (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear))t  GROUP BY salesmancode
) u
ON t.salesmancode=u.salesmancode
SET t.productivecalls=u.productivecalls;
UPDATE temp_strike_table_vw_new t INNER JOIN (	 
SELECT salesmancode,(((actualcalls)/plannedcalls)*100) AS strikerate FROM  temp_strike_table_vw_new
 ) u
ON t.salesmancode=u.salesmancode
SET t.strikerate=u.strikerate;
	 
	 
UPDATE temp_strike_table_vw_new t 
INNER JOIN 	 
(
	-- SELECT coc.`salesmancode`, 
	-- SUM(TIMESTAMPDIFF(MINUTE,
	--	STR_TO_DATE(CONCAT(STR_TO_DATE(visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
	--	STR_TO_DATE(CONCAT(STR_TO_DATE(visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
	-- )
	-- ) CFTMin
	-- FROM customeroperationscontrol coc INNER JOIN startendday sed ON sed.routekey=coc.routekey
	-- WHERE (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear) 
	-- GROUP BY  coc.salesmancode
	
	select salesmancode, sum(TIMESTAMPDIFF(minute,strt, endt)) CFTMin from
	(
		select distinct c.salesmancode, concat(logstartdate ,' ', logstarttime) strt, concat(logenddate ,' ', logendtime) endt 
		from customervisitlog c 
		inner join startendday sed on sed.routekey=c.routekey
		WHERE 1=1 and (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear) 
	) a GROUP BY salesmancode
) 
u
ON t.salesmancode=u.salesmancode
SET t.CFTMin=u.CFTMin;
	 
UPDATE temp_strike_table_vw_new t
set t.CustomerFaceTime=TIME_FORMAT(SEC_TO_TIME(t.CFTMin*60),'%H:%i');
  
UPDATE temp_strike_table_vw_new t INNER JOIN 	 
(SELECT sm.`salesmancode`, COUNT(customercode) OTPUsedCount
FROM otplogdetail otp  
INNER JOIN routemaster rm ON rm.routecode=otp.routecode
INNER JOIN salesman sm ON sm.salesmancode=rm.salesmancode
WHERE (MONTH(otpdate) = varMonth AND YEAR(otp.otpdate) = varYear) 
GROUP BY  sm.salesmancode) 
u
ON t.salesmancode=u.salesmancode
SET t.OTPUsedCount=u.OTPUsedCount;
 
 
  UPDATE temp_strike_table_vw_new t INNER JOIN (
 SELECT salesmancode,DATEDIFF(RouteEndDate,routestartdate) AS settlementskipeddays FROM startendday
 WHERE DATEDIFF(RouteEndDate,routestartdate)>0  AND (MONTH(routestartdate) = varMonth AND YEAR(routestartdate) = varYear) 
 ) u
ON t.salesmancode=u.salesmancode
SET t.settlementskipeddays=u.settlementskipeddays;
UPDATE temp_strike_table_vw_new t INNER JOIN (
SELECT salesmancode,((productivecalls)/(actualcalls)*100) AS productiverate FROM  temp_strike_table_vw_new 
)u
ON t.salesmancode=u.salesmancode
SET t.productiverate=u.productiverate;
 SELECT * FROM temp_strike_table_vw_new;
  END */$$
DELIMITER ;

/* Procedure structure for procedure `SP_Productivity_Strike_Rate_sand` */

