WHERE ih.voidflag = 0  AND (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear)  GROUP BY ih.salesmancode )
 u
ON t.salesmancode=u.salesmancode
SET t.orders=u.ordercount;
UPDATE temp_strike_table_vw_sand t INNER JOIN (
SELECT  Salesmancode,SUM(callcount) AS unschedulecall FROM (
SELECT sed1.salesmancode,rs.routekey ,COUNT(*) AS callcount FROM routesequencecustomerstatus rs 
INNER JOIN startendday sed1 ON rs.routekey=sed1.routekey AND sed1.routecode=rs.routecode 
WHERE rs.servicedflag = 1 AND  rs.schelduledflag = 0  AND 
MONTH (sed1.routestartdate) = varMonth AND YEAR(sed1.routestartdate) = varYear
GROUP BY rs.routekey,rs.customercode)t
GROUP BY salesmancode
) u
ON t.salesmancode=u.salesmancode
SET t.unschedulecall=u.unschedulecall;
UPDATE temp_strike_table_vw_sand t INNER JOIN 
(SELECT ah.salesmancode,COUNT(*) AS receipts  FROM arheader ah 
INNER JOIN startendday sed ON ah.routekey= sed.routekey AND ah.routecode= sed.routecode 
INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
WHERE  1=1   AND (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear)  GROUP BY ah.salesmancode )
 u
ON t.salesmancode=u.salesmancode
SET t.totalreceipt=u.receipts;
 
 UPDATE temp_strike_table_vw_sand t INNER JOIN (
SELECT  Salesmancode,COUNT(DISTINCT customercode,routestartdate) AS productivecalls FROM (
SELECT  coc.Salesmancode,coc.customercode,sed.routestartdate FROM invoiceheader coc
INNER JOIN startendday sed ON coc.routecode = sed.routecode AND coc.routekey = sed.routekey
WHERE  (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear)
UNION
SELECT  coc.Salesmancode,customercode,sed.routestartdate FROM salesorderheader coc
INNER JOIN startendday sed ON coc.routecode = sed.routecode AND coc.routekey = sed.routekey
WHERE  (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear)
UNION
SELECT  coc.Salesmancode,customercode,sed.routestartdate FROM arheader coc
INNER JOIN startendday sed ON coc.routecode = sed.routecode AND coc.routekey = sed.routekey
WHERE  (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear))t  GROUP BY salesmancode
) u
ON t.salesmancode=u.salesmancode
SET t.productivecalls=u.productivecalls;
UPDATE temp_strike_table_vw_sand t INNER JOIN (	 
SELECT salesmancode,(((actualcalls)/plannedcalls)*100) AS strikerate FROM  temp_strike_table_vw_sand
 ) u
ON t.salesmancode=u.salesmancode
SET t.strikerate=u.strikerate;
	 
	 
UPDATE temp_strike_table_vw_sand t INNER JOIN 	 
(SELECT coc.`salesmancode`, 
SUM(TIMESTAMPDIFF(MINUTE,
STR_TO_DATE(CONCAT(STR_TO_DATE(visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
STR_TO_DATE(CONCAT(STR_TO_DATE(visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
)) CFTMin
FROM customeroperationscontrol coc INNER JOIN startendday sed ON sed.routekey=coc.routekey
WHERE (MONTH(sed.routestartdate) = varMonth AND YEAR(sed.routestartdate) = varYear) 
GROUP BY  coc.salesmancode) 
u
ON t.salesmancode=u.salesmancode
SET t.CFTMin=u.CFTMin;
	 
UPDATE temp_strike_table_vw_sand t
SET t.CustomerFaceTime=TIME_FORMAT(SEC_TO_TIME(t.CFTMin*60),'%H:%i');
  
UPDATE temp_strike_table_vw_sand t INNER JOIN 	 
(SELECT sm.`salesmancode`, COUNT(customercode) OTPUsedCount
FROM otplogdetail otp  
INNER JOIN routemaster rm ON rm.routecode=otp.routecode
INNER JOIN salesman sm ON sm.salesmancode=rm.salesmancode
WHERE (MONTH(otpdate) = varMonth AND YEAR(otp.otpdate) = varYear) 
GROUP BY  sm.salesmancode) 
u
ON t.salesmancode=u.salesmancode
SET t.OTPUsedCount=u.OTPUsedCount;
 
 
  UPDATE temp_strike_table_vw_sand t INNER JOIN (
 SELECT salesmancode,DATEDIFF(RouteEndDate,routestartdate) AS settlementskipeddays FROM startendday
 WHERE DATEDIFF(RouteEndDate,routestartdate)>0  AND (MONTH(routestartdate) = varMonth AND YEAR(routestartdate) = varYear) 
 ) u
ON t.salesmancode=u.salesmancode
SET t.settlementskipeddays=u.settlementskipeddays;
UPDATE temp_strike_table_vw_sand t INNER JOIN (
SELECT salesmancode,((productivecalls)/(actualcalls)*100) AS productiverate FROM  temp_strike_table_vw_sand 
)u
ON t.salesmancode=u.salesmancode
SET t.productiverate=u.productiverate;
 SELECT * FROM temp_strike_table_vw_sand;
  END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_aandpreport_with_permission` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_aandpreport_with_permission` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_aandpreport_with_permission`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT,
IN in_user VARCHAR(25)
)
BEGIN
	
	SET @dyn_sql = CONCAT("SELECT s.salesmancode, c.ANCUSTOMERCODE customercode, c.customername,  c.divisioncode,
d.alternateinvoicenumber invno, DATE_FORMAT(d.invoicedate,'%Y/%m/%d') invdate, 
h.invoicenumber receiptno, DATE_FORMAT(h.transactiondate,'%Y/%m/%d') transactiondate, 
d.deductionamount, h.comments
FROM 
arheader H
INNER JOIN ardetail D ON H.ROUTEKEY = D.routekey AND H.VISITKEY = D.visitkey
INNER JOIN CUSTOMERMASTER C ON H.CUSTOMERCODE = C.CUSTOMERCODE
INNER JOIN SALESMAN S ON H.SALESMANCODE = S.salesmancode
WHERE h.voidflag = 0 and d.deductionamount > 0 ",in_where, " ORDER BY h.invoicenumber") ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
	 SELECT @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_account_customerpendingbalance` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_account_customerpendingbalance` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_account_customerpendingbalance`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT,
IN in_status_val INT
)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
	IF in_status_val = 1 THEN 
		SET @dyn_sql = CONCAT("SELECT 
						DATE_FORMAT(ci.transactiondate,'%Y') yearno, 
						DATE_FORMAT(ci.transactiondate,'%m') monthno, DATE_FORMAT(ci.transactiondate,'%M') monthtxt
					FROM 
						customerinvoice ci, customermaster cm
					WHERE 
						cm.customercode = ci.customercode AND ci.invoicebalance <> 0 ",in_where,"
					GROUP BY monthno,yearno
					ORDER BY yearno,monthno");
		PREPARE s1 FROM @dyn_sql;
		EXECUTE s1;
		
	ELSE
		
		SET @dyn_sql = CONCAT("SELECT  	count(*) INTO @in_counter  FROM customerinvoice ci, customermaster cm WHERE 
			cm.customercode = ci.customercode AND ci.invoicebalance <> 0", in_where);
		PREPARE s1 FROM @dyn_sql;
		EXECUTE s1;
		
		IF in_limit != "" && in_page != "" THEN 
			CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
			SELECT @new_start_limit AS start_limit,@in_counter AS counter;
			SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
		END IF;
		
		SET @dyn_sql = CONCAT("SELECT 
						DATE_FORMAT(ci.transactiondate,'%Y') yearno, 
						DATE_FORMAT(ci.transactiondate,'%m') monthno, DATE_FORMAT(ci.transactiondate,'%M') monthtxt,
						ci.routecode, ci.salesmancode, ci.customercode, DATE(ci.transactiondate) transactiondate, ci.erpreferencenumber,
						cm.customername, cm.reportcustcode,
						CASE WHEN cm.type = 1 THEN '0' WHEN cm.type = 2 THEN (SELECT cm1.reportcustcode FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE '1' END hocode,
						CASE WHEN cm.type = 1 THEN 'NORMAL CUSTOMERS' WHEN cm.type = 2 THEN (SELECT cm1.customername FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE '' END honame,
						ci.invoicebalance,ci.invoicebalance as total,ci.invoicenumber,
						(SELECT ih.comments FROM invoiceheader ih WHERE ih.invoicenumber = ci.invoicenumber) comments,
						cm.arbcustomername
					FROM 
						customerinvoice ci, customermaster cm
					WHERE 
						cm.customercode = ci.customercode AND ci.invoicebalance <> 0",in_where, " ORDER BY hocode,honame",in_orderby," ",in_sort, " ",limit_val) ;
		
		 PREPARE s1 FROM @dyn_sql;
		 EXECUTE s1;	
	
	END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_account_customerpendingbalance_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_account_customerpendingbalance_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_account_customerpendingbalance_detail`( IN cust_type INT(4)
  ,IN var_user INt(4)
  )
BEGIN
	
		SELECT `status` INTO @st FROM controlpanel WHERE flagname = 'Use Alternate Code';
		
		If var_user = 1 THEN
			
		IF @st = 1 THEN 
			SELECT customercode AS id, CONCAT(alternatecode,' -- ',customername) AS val FROM customermaster WHERE activecustomer = 1 AND templateindicator = 0 AND `type` = cust_type; 
		ELSE
			SELECT customercode AS id, CONCAT(customercode,' -- ',customername) AS val FROM customermaster WHERE activecustomer = 1 AND templateindicator = 0  AND `type` = cust_type; 
		END IF;	
		
		ELSE
		
		IF @st = 1 THEN 
			SELECT customercode AS id, CONCAT(alternatecode,' -- ',customername) AS val FROM customermaster WHERE activecustomer = 1 AND templateindicator = 0 AND `type` = cust_type
			AND customercode IN (SELECT customercode FROM routesequence WHERE routecode IN(SELECT routecode FROM routemaster WHERE templatename=var_user)); 
		ELSE
			SELECT customercode AS id, CONCAT(customercode,' -- ',customername) AS val FROM customermaster WHERE activecustomer = 1 AND templateindicator = 0  AND `type` = cust_type
			AND customercode IN (SELECT customercode FROM routesequence WHERE routecode IN(SELECT routecode FROM routemaster WHERE templatename=var_user)); 
		END IF;
		
		END IF;
			
		
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_account_customerpending_coloums` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_account_customerpending_coloums` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_account_customerpending_coloums`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
SET @dyn_sql = CONCAT("SELECT 
		DATE_FORMAT(ci.transactiondate,'%Y') yearno, 
		DATE_FORMAT(ci.transactiondate,'%m') monthno, DATE_FORMAT(ci.transactiondate,'%M') monthtxt
	FROM 
		customerinvoice ci, customermaster cm
	WHERE 
		cm.customercode = ci.customercode AND ci.invoicebalance <> 0",in_where, " GROUP BY yearno,monthno ORDER BY ",in_orderby," ",in_sort, " LIMIT ",@new_start_limit, ",",in_limit) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_account_customer_aging` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_account_customer_aging` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_account_customer_aging`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
DECLARE limit_val TEXT DEFAULT ""; 
SET @dyn_sql = CONCAT("SELECT 
				count(*) INTO @in_counter  
			FROM customerinvoice ci, customermaster cm
			WHERE 
				cm.customercode = ci.customercode AND ci.invoicebalance <> 0"
			, in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	 END IF;
	
	SET @dyn_sql = CONCAT("SELECT 
					DATE_FORMAT(ci.transactiondate, '%d %b %Y') AS transactiondate,
					CASE WHEN cm.type = 1 THEN '0' WHEN cm.type = 2 THEN (SELECT cm1.reportcustcode FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE '1' END hocode,
					CASE WHEN cm.type = 1 THEN 'normal customers' WHEN cm.type = 2 THEN (SELECT cm1.customername FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE '' END honame,		
					ci.erpreferencenumber, ci.customercode, cm.customername, cm.reportcustcode, cm.creditlimit, cm.creditlimitdays,
					DATEDIFF(NOW(), ci.transactiondate) nodays, 
					(SELECT CASE WHEN DATEDIFF(NOW(),MIN(ci1.transactiondate)) > cm.creditlimitdays THEN 'red' ELSE '' END FROM customerinvoice ci1 WHERE ci1.customercode = cm.customercode AND ci1.invoicebalance > 0) creditstatus,
					ci.invoicebalance, ci.routecode, ci.salesmancode,
					(SELECT COALESCE(ih.comments, '') FROM invoiceheader ih WHERE ih.invoicenumber = ci.invoicenumber) comments,
					CASE 
						WHEN DATEDIFF(NOW(),ci.transactiondate) > 120 THEN 121
						WHEN DATEDIFF(NOW(),ci.transactiondate) > 90 THEN 91
						WHEN DATEDIFF(NOW(),ci.transactiondate) > 60 THEN 61
						WHEN DATEDIFF(NOW(),ci.transactiondate) > 30 THEN 31
					ELSE 0 END age,
					cm.arbcustomername
				FROM 
					customerinvoice ci, customermaster cm
				WHERE 
					cm.customercode = ci.customercode AND ci.invoicebalance <> 0 ",in_where, " ORDER BY ",in_orderby," ",in_sort, " ",limit_val) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;		
	
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_account_customer_aging_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_account_customer_aging_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_account_customer_aging_detail`()
BEGIN
CALL sp_combo_customermaster() ;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_account_pdc` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_account_pdc` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_account_pdc`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT
)
BEGIN
DECLARE orderby_val TEXT DEFAULT "";
DECLARE limit_val TEXT DEFAULT "";
	SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter FROM customerinvoice ci, customermaster cm ,routemaster rm,salesman sm 
	", in_where);
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	IF in_orderby != "" && in_sort != "" THEN
		SET orderby_val = CONCAT( " ORDER BY ",in_orderby," ",in_sort);
	END IF;
	SET @dyn_sql = CONCAT("
		SELECT DATE_FORMAT( ci.transactiondate, '%d %b %y') AS transactiondate,
		 CASE 
			WHEN cm.type = 1 THEN '0'
			WHEN cm.type = 2 THEN (SELECT cm1.reportcustcode FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) 
			ELSE '1' 
			END hocode,
		 CASE 
			WHEN cm.type = 1 THEN 'NORMAL CUSTOMERS'
			WHEN cm.type = 2 THEN (SELECT cm1.customername FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode)
			ELSE '' 
			END honame,
		 ci.erpreferencenumber, ci.customercode,ci.invoicenumber, cm.customername, cm.reportcustcode, cm.creditlimit, cm.creditlimitdays, ci.invoicebalance,
		 ci.routecode, ci.salesmancode ,rm.routename, sm.salesmanname1,ci.pdcbalance,ci.pdcdate,
		 CASE WHEN DATEDIFF(ci.transactiondate, CURDATE()) > 120 THEN 121
		  WHEN DATEDIFF( ci.transactiondate, CURDATE()) > 90 THEN 91 
		  WHEN DATEDIFF( ci.transactiondate, CURDATE()) > 60 THEN 61 
		  WHEN DATEDIFF( ci.transactiondate, CURDATE()) > 30 THEN 31 
		  ELSE 0 
		  END age,
		  cm.arbcustomername,rm.arbroutename,sm.arbsalesmanname1
		FROM customerinvoice ci, customermaster cm ,routemaster rm,salesman sm
		",in_where, orderby_val,limit_val) ;
   
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_account_pdc_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_account_pdc_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_account_pdc_detail`( IN cust_type INT(4))
BEGIN
SELECT `status` INTO @st FROM controlpanel WHERE flagname = 'Use Alternate Code';
			
		IF @st = 1 THEN 
			SELECT customercode AS id, CONCAT(alternatecode,' -- ',customername) AS val FROM customermaster WHERE activecustomer = 1 AND templateindicator = 0 AND `type` = cust_type; 
		ELSE
			SELECT customercode AS id, CONCAT(customercode,' -- ',customername) AS val FROM customermaster WHERE activecustomer = 1 AND templateindicator = 0  AND `type` = cust_type; 
		END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_account_routependingbalance` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_account_routependingbalance` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_account_routependingbalance`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
	IF in_where = 1 then
		SET @dyn_sql = CONCAT("SELECT DISTINCT(DATE_FORMAT(ci.transactiondate,'%Y')) yearno
					FROM customerinvoice ci, routemaster rm, salesman sm 
					WHERE rm.routecode = ci.routecode and sm.salesmancode = ci.salesmancode 
					GROUP BY DATE_FORMAT(ci.transactiondate,'%Y'), DATE_FORMAT(ci.transactiondate,'%m'), DATE_FORMAT(ci.transactiondate,'%M'),
					ci.routecode, rm.routename, ci.salesmancode, sm.salesmanname1
					ORDER BY yearno");
		PREPARE s1 FROM @dyn_sql;
		EXECUTE s1;
	ElSE 
	
		SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter FROM (SELECT ci.routecode FROM customerinvoice ci, routemaster rm, salesman sm WHERE 
					rm.routecode = ci.routecode and sm.salesmancode = ci.salesmancode", in_where,"
					GROUP BY DATE_FORMAT(ci.transactiondate,'%Y'), DATE_FORMAT(ci.transactiondate,'%m'), DATE_FORMAT(ci.transactiondate,'%M'),
					ci.routecode, rm.routename, ci.salesmancode, sm.salesmanname1) as cnt");
		PREPARE s1 FROM @dyn_sql;
		EXECUTE s1;
		
		IF in_limit != "" && in_page != "" THEN 
			CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
			SELECT @new_start_limit AS start_limit,@in_counter AS counter;
			SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
		END IF;
		
		SET @dyn_sql = CONCAT("
			SELECT
				DATE_FORMAT(ci.transactiondate,'%Y') yearno, 
				DATE_FORMAT(ci.transactiondate,'%m') monthno, DATE_FORMAT(ci.transactiondate,'%M') monthtxt,
				ci.routecode, rm.routename, ci.salesmancode, sm.salesmanname1, sum(ci.invoicebalance) invoicebalance,
				rm.arbroutename,sm.arbsalesmanname1
			FROM customerinvoice ci, routemaster rm, salesman sm
			WHERE rm.routecode = ci.routecode and sm.salesmancode = ci.salesmancode",in_where, "
			 GROUP BY DATE_FORMAT(ci.transactiondate,'%Y'), DATE_FORMAT(ci.transactiondate,'%m'), DATE_FORMAT(ci.transactiondate,'%M'),
				ci.routecode, rm.routename, ci.salesmancode, sm.salesmanname1 ORDER BY ",in_orderby," ",in_sort, " ",limit_val) ;
		 PREPARE s1 FROM @dyn_sql;
		 EXECUTE s1;	
	 
	END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_account_routependingbalance_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_account_routependingbalance_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_account_routependingbalance_detail`()
BEGIN
CALL sp_combo_routemaster() ;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_account_route_aging` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_account_route_aging` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_account_route_aging`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
DECLARE limit_val TEXT DEFAULT "";    
    SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter  
			FROM customerinvoice ci, customermaster cm, routemaster rm, salesman sm,
				(SELECT ih.invoicenumber, ih.actualtransactiondate FROM invoiceheader ih) inv 
			WHERE cm.customercode = ci.customercode AND ci.routecode = rm.routecode AND ci.salesmancode = sm.salesmancode AND
				ci.invoicebalance <> 0 AND inv.invoicenumber =ci.invoicenumber", in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	 END IF;
	
	SET @dyn_sql = CONCAT("SELECT 
					date(COALESCE(inv.actualtransactiondate, ci.transactiondate)) AS transactiondate,
					CASE WHEN cm.type = 1 THEN '0' WHEN cm.type = 2 THEN (SELECT cm1.reportcustcode FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode order by cm1.reportcustcode LIMIT 1) ELSE '1' END hocode,
					CASE WHEN cm.type = 1 THEN 'normal customers' WHEN cm.type = 2 THEN (SELECT cm1.customername FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode order by cm1.customername LIMIT 1) ELSE '' END honame,		 
					ci.invoicenumber, ci.erpreferencenumber, ci.customercode, cm.customername,cm.arbcustomername, cm.reportcustcode, ci.routecode, rm.routename, ci.salesmancode, sm.salesmanname1, 
					cm.creditlimit, cm.creditlimitdays,
					(SELECT CASE WHEN DATEDIFF(MIN(ci1.transactiondate), NOW()) > cm.creditlimitdays THEN 'red' ELSE '' END FROM customerinvoice ci1 WHERE ci1.customercode = cm.customercode AND ci1.invoicebalance > 0 LIMIT 1) creditstatus,
					DATEDIFF(COALESCE(inv.actualtransactiondate, ci.transactiondate), NOW()) nodays, ci.invoicebalance, 
					CASE 
						WHEN DATEDIFF(NOW(),ci.transactiondate) > 120 THEN ci.invoicebalance ELSE 0 END age121, 
							CASE WHEN DATEDIFF(NOW(),ci.transactiondate) > 90 && DATEDIFF(NOW(),ci.transactiondate) <= 120 THEN ci.invoicebalance ELSE 0 END age91, 
								CASE WHEN DATEDIFF(NOW(),ci.transactiondate) > 60 && DATEDIFF(NOW(),ci.transactiondate) <= 90 THEN ci.invoicebalance ELSE 0 END age61,
									CASE WHEN DATEDIFF(NOW(),ci.transactiondate) > 30 && DATEDIFF(NOW(),ci.transactiondate) <= 60 THEN ci.invoicebalance ELSE 0 END age31,
									CASE WHEN DATEDIFF(NOW(),ci.transactiondate) > 0 && DATEDIFF(NOW(),ci.transactiondate) <= 30 THEN ci.invoicebalance ELSE 0 END age,						
					CASE WHEN ci.pdcbalance != 0 THEN ci.pdcbalance ELSE (SELECT SUM(ard.pdcbalance) FROM ardetail ard WHERE ard.pdcbalance > 0 AND ard.invoicenumber = ci.invoicenumber) END pdcamount,
					CASE WHEN ci.pdcbalance != 0 THEN 
							(SELECT ccd.checkdate FROM invoiceheader ih, cashcheckdetail ccd WHERE ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey AND ih.invoicenumber = ci.invoicenumber order by ccd.checkdate LIMIT 1)
						ELSE 
							(SELECT ccd.checkdate FROM ardetail ard, cashcheckdetail ccd WHERE ccd.routekey = ard.routekey AND ccd.visitkey = ard.visitkey AND ard.pdcbalance > 0 AND ard.invoicenumber = ci.invoicenumber order by ccd.checkdate LIMIT 1) END pdcdate,
					cm.arbcustomername,rm.arbroutename,sm.arbsalesmanname1
				FROM 
					customerinvoice ci, customermaster cm, routemaster rm, salesman sm,
					(SELECT ih.invoicenumber, ih.actualtransactiondate FROM invoiceheader ih) inv
				WHERE 
					cm.customercode = ci.customercode AND ci.routecode = rm.routecode AND ci.salesmancode = sm.salesmancode AND
					ci.invoicebalance <> 0 AND inv.invoicenumber =ci.invoicenumber",in_where, " ORDER BY ",in_orderby," ",in_sort, " ",limit_val) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;		
	
	
END */$$
DELIMITER ;

