/* Procedure structure for procedure `sp_report_customer_active_msl` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_customer_active_msl` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_customer_active_msl`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit VARCHAR(25),
IN in_page VARCHAR(25))
BEGIN
DECLARE limitval TEXT DEFAULT "";    
    SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter from customermaster cm
inner join itemmustheader imh ON imh.itemmustcode = cm.itemmustkey 
inner join itemmustdetail imd ON imh.itemmustcode = imd.itemmustcode
inner join routesequence rs ON rs.customercode = cm.customercode 
left join channelmaster chm ON chm.channelcode = cm.channelcode
 where   cm.itemmustkey != '' ", in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN
		CALL sp_report_calculate_paging_data(@in_counter,in_limit,in_page,@new_start_limit);
		IF @new_start_limit < 0 THEN  SET @new_start_limit = 0; END IF;
		SET @limitval = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	ELSE
		SET @limitval = CONCAT(" LIMIT 0,",@in_counter);
	END IF;
	  SELECT @new_start_limit AS start_limit,@in_counter AS counter;
	  SELECT decimalplaces INTO @decimal_places FROM currencymaster WHERE defaultcurrency = 1;
	  
	SET @dyn_sql = CONCAT("select itemmustkey, cm.alternatecode,itemmustdescription,im.alternatecode as itemcode,quantity,max_quantity, 
customername,cm.transaction_anals3 as categoryname,chm.channelname
from customermaster cm
inner join itemmustheader imh ON imh.itemmustcode = cm.itemmustkey 
inner join itemmustdetail imd ON imh.itemmustcode = imd.itemmustcode
inner join routesequence rs ON rs.customercode = cm.customercode
inner join itemmaster im ON im.actualitemcode = imd.itemcode 
left join channelmaster chm ON chm.channelcode = cm.channelcode
 where   cm.itemmustkey != '' ",in_where," ORDER BY ",in_orderby," ",in_sort," ",@limitval) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
SELECT @dyn_sql;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_customer_shelf_stock` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_customer_shelf_stock` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_customer_shelf_stock`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit VARCHAR(25),
IN in_page VARCHAR(25))
BEGIN
DECLARE limitval TEXT DEFAULT "";    
    SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter 
	FROM customerinventorydetail as cid
 inner join startendday as sed on sed.routekey = cid.routekey
INNER JOIN customeroperationscontrol as coc on coc.routekey = cid.routekey and coc.visitkey = cid.visitkey
INNER JOIN customermaster as cm on cm.customercode = coc.customercode
INNER JOIN routemaster as rm on rm.routecode = coc.routecode
INNER JOIN salesman as sm on sm.salesmancode = coc.salesmancode
INNER JOIN itemmaster as im on im.actualitemcode = cid.itemcode
LEFT JOIN channelmaster as chm on chm.channelcode = cm.channelcode WHERE 1=1 ", in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN
		CALL sp_report_calculate_paging_data(@in_counter,in_limit,in_page,@new_start_limit);
		IF @new_start_limit < 0 THEN  SET @new_start_limit = 0; END IF;
		SET @limitval = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	ELSE
		SET @limitval = CONCAT(" LIMIT 0,",@in_counter);
	END IF;
	  SELECT @new_start_limit AS start_limit,@in_counter AS counter;
	  SELECT decimalplaces INTO @decimal_places FROM currencymaster WHERE defaultcurrency = 1;
	  
	SET @dyn_sql = CONCAT("select shelfstockcase, shelfstockeach, DATE_FORMAT(visitstartdate,'%m-%d-%Y') as  entrydate,visitstartdate, visitstarttime,
sm.salesmanname1, sm.arbsalesmanname1, sm.alternatesalesmancode as salesmancode,
rm.routename,rm.arbroutename, rm.alternateroutecode as routecode,
im.itemshortdescription, im.arbitemshortdescription, im.alternatecode as itemcode, im.alternateitemgroupcode as igroupcode,
cm.customername, cm.arbcustomername, cm.alternatecode as customercode, cm.Grouping_Code,cm.Outlet_Quality,
chm.alternatecode as channelcode,chm.channelname
	FROM customerinventorydetail as cid
	inner join startendday as sed on sed.routekey = cid.routekey
	INNER JOIN customeroperationscontrol as coc on coc.routekey = cid.routekey and coc.visitkey = cid.visitkey
	INNER JOIN customermaster as cm on cm.customercode = coc.customercode
	INNER JOIN routemaster as rm on rm.routecode = coc.routecode
	INNER JOIN salesman as sm on sm.salesmancode = coc.salesmancode
	INNER JOIN itemmaster as im on im.actualitemcode = cid.itemcode
	LEFT JOIN channelmaster as chm on chm.channelcode = cm.channelcode WHERE 1=1 ",in_where," ORDER BY ",in_orderby,"  ",in_sort," ",@limitval) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
SELECT @dyn_sql;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_customer_visit_details` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_customer_visit_details` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_customer_visit_details`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit VARCHAR(25),
IN in_page VARCHAR(25))
BEGIN
DECLARE limitval TEXT DEFAULT "";    
    SET @dyn_sql = CONCAT("SELECT  count(*) INTO @in_counter FROM startendday as sed
	INNER JOIN routesequencecustomerstatus as rscs ON rscs.routekey = sed.routekey and rscs.routecode = sed.routecode
	LEFT JOIN invoiceheader as ih ON ih.routekey = sed.routekey and ih.routecode = sed.routecode
	LEFT JOIN routemaster as rm ON rm.routecode = sed.routecode 
INNER JOIN salesman as sm ON sm.salesmancode = sed.salesmancode 
INNER JOIN customermaster as cm ON cm.customercode = rscs.customercode 
LEFT JOIN channelmaster as chm ON chm.channelcode = cm.channelcode where 1=1 ", in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN
		CALL sp_report_calculate_paging_data(@in_counter,in_limit,in_page,@new_start_limit);
		IF @new_start_limit < 0 THEN  SET @new_start_limit = 0; END IF;
		SET @limitval = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	ELSE
		SET @limitval = CONCAT(" LIMIT 0,",@in_counter);
	END IF;
	  SELECT @new_start_limit AS start_limit,@in_counter AS counter;
	  SELECT decimalplaces INTO @decimal_places FROM currencymaster WHERE defaultcurrency = 1;
	  
	SET @dyn_sql = CONCAT("select  sed.routekey,DATE_FORMAT(routestartdate,'%m-%d-%Y') AS  transactiondate,sed.routecode, sed.salesmancode,rscs.customercode,schelduledflag,servicedflag,
sm.salesmanname1,sm.arbsalesmanname1,sm.alternatesalesmancode,rm.routename,rm.arbroutename,rm.alternateroutecode,cm.customername,cm.arbcustomername,cm.alternatecode as customeraltcode,chm.channelname,chm.arbchannelname
	FROM startendday as sed
	LEFT JOIN routesequencecustomerstatus as rscs ON rscs.routekey = sed.routekey and rscs.routecode = sed.routecode
	-- LEFT JOIN invoiceheader as ih ON ih.routekey = sed.routekey and ih.routecode = sed.routecode
	INNER JOIN routemaster as rm ON rm.routecode = sed.routecode 
INNER JOIN salesman as sm ON sm.salesmancode = sed.salesmancode 
INNER JOIN customermaster as cm ON cm.customercode = rscs.customercode 
LEFT JOIN channelmaster as chm ON chm.channelcode = cm.channelcode where 1=1 ",in_where," ORDER BY ",in_orderby," ",in_sort," ",@limitval) ;
	 PREPARE s1 FROM @dyn_sql;
	 -- select @dyn_sql;
	 EXECUTE s1;	
 -- SELECT @dyn_sql;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyreport_customerassets` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_customerassets` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_customerassets`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT,
in_export_status INT
)
BEGIN
	DECLARE limit_val TEXT DEFAULT "";
	DECLARE groupby_val TEXT DEFAULT "";
	SET groupby_val = CONCAT(" GROUP BY coc.primary_id ");
	IF in_export_status != 1 THEN 
		SET groupby_val = CONCAT(" GROUP BY coc.primary_id ");
	
	
		SET @dyn_sql = CONCAT("SELECT COUNT(t1.cnt) INTO @in_counter FROM ( SELECT count(*) as cnt 
					FROM startendday sed
	INNER JOIN customeroperationscontrol coc ON coc.routekey = sed.routekey
	INNER JOIN posequipmentchangedetail pos ON pos.routekey = coc.routekey AND pos.visitkey = coc.visitkey
	INNER JOIN customermaster cm ON cm.customercode = coc.customercode
	INNER JOIN posmaster pm ON pm.itemcode = pos.itemcode
	INNER JOIN posinstructions poi ON poi.posinstructioncode = pos.posaction join routemaster rm on rm.routecode=sed.routecode where 1  ", in_where,groupby_val," ) as t1");
		PREPARE s1 FROM @dyn_sql;
		EXECUTE s1;
		
		IF in_limit != "" && in_page != "" THEN 
			CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
			SELECT @new_start_limit AS start_limit,@in_counter AS counter;
			SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
		END IF;
	END IF;
	
	
	SET @dyn_sql = CONCAT("SELECT DATE_FORMAT(coc.visitstartdate, '%d %b %Y') VisitDate,coc.visitstarttime VisitTime, cm.customercode CustomerCode,cm.alternatecode AlternateCode, cm.customername Customer,
	pm.itemcode POSCode, pm.itemdescription POS, pos.serialnumber SerialNo, poi.posinstructionname POSStatus, pos.remarks Remarks,sed.routecode,rm.routename
			       FROM startendday sed
	INNER JOIN customeroperationscontrol coc ON coc.routekey = sed.routekey
	INNER JOIN posequipmentchangedetail pos ON pos.routekey = coc.routekey AND pos.visitkey = coc.visitkey
	INNER JOIN customermaster cm ON cm.customercode = coc.customercode
	INNER JOIN posmaster pm ON pm.itemcode = pos.itemcode
	INNER JOIN posinstructions poi ON poi.posinstructioncode = pos.posaction join routemaster rm on rm.routecode=sed.routecode where 1
				    ",in_where," ",groupby_val," ORDER BY ", in_orderby, " ",in_sort, " ",limit_val);
	
	
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyreport_dailyrouteactivity` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_dailyrouteactivity` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_dailyrouteactivity`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT
)
BEGIN
	SET @dyn_sql = CONCAT("
		SELECT t1.* from (
		SELECT 
			0 visitkey, ith.routekey, '' customercode, 'INVENTORY' customername, '' arbcustomername, rm.routecode, rm.routename, 
			sm.salesmancode, sm.salesmanname1, '' customeraddress1, '' customeraddress2, '' customeraddress3,
			DATE_FORMAT(ith.actualtransactiondate, '%d %b %Y') visitstartdate, CAST(ith.transactiontime AS TIME) visitstarttime, 
			DATE_FORMAT(ith.actualtransactiondate, '%d %b %Y') visitenddate, CAST(ith.transactiontime AS TIME) visitendtime, \"\" visited,
			CASE WHEN ith.transactiontype = 3 THEN 'UNLOAD' WHEN ith.transactiontype = 2 THEN 'LOAD TRANSFER' WHEN ith.transactiontype = 1 THEN 'LOAD' ELSE 'LOAD REQUEST' END trantype,
			ith.documentnumber documentno, 0 tranamount, 0 salePaid, 0 receiptPaid, 0 timeinhour, 0 timeinmin, 
			DATE_FORMAT(ith.actualtransactiondate, '%d %b %Y') trandate,rm.arbroutename,sm.arbsalesmanname1,rm.divisioncode
		FROM 
			startendday sed
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
			INNER JOIN inventorytransactionheader ith ON ith.routekey = sed.routekey			
		WHERE 
			1=1 ",in_where,"
		
		UNION
		
		SELECT 
			    coc.visitkey, coc.routekey, cm.alternatecode customercode, cm.customername,cm.arbcustomername, rm.routecode, rm.routename, sm.salesmancode,
			    sm.salesmanname1, cm.customeraddress1, cm.customeraddress2, cm.customeraddress3, 
			    DATE_FORMAT(coc.visitstartdate, '%d %b %Y') visitstartdate, CAST(coc.visitstarttime AS TIME) visitstarttime, 
			    DATE_FORMAT(coc.visitenddate, '%d %b %Y') visitenddate, CAST(coc.visitendtime AS TIME) visitendtime, 
			    (SELECT nsr.description FROM nosalesheader nsh, nonservreasons nsr
				WHERE nsh.routekey = coc.routekey AND nsh.visitkey = coc.visitkey AND nsh.nosalereasoncode = nsr.code LIMIT 1) AS visited,
			    \"NON SERVICE  \" trantype, CONCAT(coc.routekey,coc.visitkey) documentno, 0 tranamount, 0 salepaid, 0 receiptpaid, CASE WHEN (TIMESTAMPDIFF(MINUTE,
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
)) >= 60 THEN (TIMESTAMPDIFF(MINUTE,
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
)) DIV 60 ELSE 0 END timeinhour,
			    (TIMESTAMPDIFF(MINUTE,
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
)) % 60 AS timeinmin, DATE_FORMAT(coc.visitstartdate, '%d %b %Y') trandate,rm.arbroutename,sm.arbsalesmanname1,rm.divisioncode
		FROM 
			startendday sed
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
			INNER JOIN customeroperationscontrol coc ON coc.routekey = sed.routekey AND CASE WHEN SED.ROUTECODE in( 1100621, 1101323, 1101569, 1400054) THEN 1=1 ELSE  coc.reasoncode > 0	END		
			INNER JOIN customermaster cm ON cm.customercode = coc.customercode
		WHERE 
			1=1 ",in_where,"
		
		UNION
		
		SELECT 
			coc.visitkey, coc.routekey, cm.alternatecode customercode, cm.customername,cm.arbcustomername, rm.routecode, rm.routename,
			sm.salesmancode, sm.salesmanname1, cm.customeraddress1, cm.customeraddress2, cm.customeraddress3, 
			 DATE_FORMAT(coc.visitstartdate, '%d %b %Y') visitstartdate, CAST(coc.visitstarttime AS TIME) visitstarttime, 
			 DATE_FORMAT(coc.visitenddate, '%d %b %Y') visitenddate, CAST(coc.visitendtime AS TIME) visitendtime, \"\" visited, 
			 CONCAT('SALES', CASE WHEN ih.voidflag=0 THEN '' ELSE ' *VOIDED' END) trantype, ih.documentnumber documentno, 
			 CASE WHEN ih.voidflag=1 THEN 0 ELSE ih.totalinvoiceamount END tranamount,
			 CASE WHEN ih.voidflag=1 THEN 0 ELSE ih.immediatepaid END salepaid, 0 receiptpaid,
			  CASE WHEN 
			  (TIMESTAMPDIFF(MINUTE,
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
)) >= 60 THEN 
			  (TIMESTAMPDIFF(MINUTE,
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
)) DIV 60 ELSE 0 END timeinhour, 
			  (TIMESTAMPDIFF(MINUTE,
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
)) % 60 AS timeinmin,DATE_FORMAT(ih.actualtransactiondate, '%d %b %Y') trandate ,rm.arbroutename,sm.arbsalesmanname1,rm.divisioncode
		FROM 
			startendday sed
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
			INNER JOIN customeroperationscontrol coc ON coc.routekey = sed.routekey
			INNER JOIN invoiceheader ih ON ih.routekey = coc.routekey AND ih.visitkey = coc.visitkey
			INNER JOIN customermaster cm ON cm.customercode = coc.customercode			
		WHERE 
			1=1 ",in_where,"	
		
		UNION
		
		SELECT
			coc.visitkey, coc.routekey, cm.alternatecode customercode, cm.customername,cm.arbcustomername, rm.routecode, rm.routename, sm.salesmancode,
			sm.salesmanname1, cm.customeraddress1, cm.customeraddress2, cm.customeraddress3,
			DATE_FORMAT(coc.visitstartdate, '%d %b %Y') visitstartdate, CAST(coc.visitstarttime AS TIME) visitstarttime,
			DATE_FORMAT(coc.visitenddate, '%d %b %Y') visitenddate, CAST(coc.visitendtime AS TIME) visitendtime, \"\" visited, 
			CONCAT('ORDER', CASE WHEN soh.voidflag=0 THEN '' ELSE ' *VOIDED' END) trantype, soh.documentnumber documentno, 
			CASE WHEN soh.voidflag=1 THEN 0 ELSE soh.totalinvoiceamount END tranamount, 0 salepaid, 0 receiptpaid,
			CASE WHEN 
			(TIMESTAMPDIFF(MINUTE,
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
)) >= 60 THEN 
			(TIMESTAMPDIFF(MINUTE,
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
)) DIV 60 ELSE 0 END timeinhour,
			(TIMESTAMPDIFF(MINUTE,
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
)) % 60 AS timeinmin,
			DATE_FORMAT(soh.actualtransactiondate, '%d %b %Y') trandate ,rm.arbroutename,sm.arbsalesmanname1,rm.divisioncode			
		FROM startendday sed
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
			INNER JOIN customeroperationscontrol coc ON coc.routekey = sed.routekey
			INNER JOIN salesorderheader soh ON soh.routekey = coc.routekey AND soh.visitkey = coc.visitkey
			INNER JOIN customermaster cm ON cm.customercode = coc.customercode
		WHERE 
			1=1 ",in_where,"
		
		UNION
		
		SELECT 
			coc.visitkey, coc.routekey, cm.alternatecode customercode, cm.customername,cm.arbcustomername, rm.routecode, rm.routename, sm.salesmancode,
			sm.salesmanname1, cm.customeraddress1, cm.customeraddress2, cm.customeraddress3, 
			DATE_FORMAT(coc.visitstartdate, '%d %b %Y') visitstartdate, CAST(coc.visitstarttime AS TIME) visitstarttime, 
			DATE_FORMAT(coc.visitenddate, '%d %b %Y') visitenddate, CAST(coc.visitendtime AS TIME) visitendtime, \"\" visited, 
			CONCAT('RECEIPT', CASE WHEN ah.voidflag=0 THEN '' ELSE ' *VOIDED' END) trantype, ah.documentnumber documentno, 
			CASE WHEN ah.voidflag=1 THEN 0 ELSE ah.totalinvoiceamount END tranamount, 0 salepaid, 
			CASE WHEN ah.voidflag=1 THEN 0 ELSE ah.amountpaid END receiptpaid,
			CASE WHEN 
			(TIMESTAMPDIFF(MINUTE,
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
)) >= 60 THEN 
			(TIMESTAMPDIFF(MINUTE,
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
)) DIV 60 ELSE 0 END timeinhour,
			(TIMESTAMPDIFF(MINUTE,
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
)) % 60 AS timeinmin, 
			DATE_FORMAT(ah.transactiondate, '%d %b %Y') trandate ,rm.arbroutename,sm.arbsalesmanname1,rm.divisioncode
		FROM 
			startendday sed
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
			INNER JOIN customeroperationscontrol coc ON coc.routekey = sed.routekey
			INNER JOIN arheader ah ON ah.routekey = coc.routekey AND ah.visitkey = coc.visitkey
			INNER JOIN customermaster cm ON cm.customercode = coc.customercode
		WHERE 
			1=1 ",in_where,"	
union 
			SELECT 
			0 visitkey, 
			sed.routekey, 
			'',
			'',
			'',
			sed.routecode , 
			rm.routename, 
			sm.salesmancode,
			sm.salesmanname1, 
			'',
			'',
			'',
			'',
			'',
			'',
			'',
			'',			
			'',
			'',
			0 tranamount, 
			0 salePaid, 
			0 receiptPaid, 
			0 timeinhour, 
			0 timeinmin, 
			'',
			rm.arbroutename,
			sm.arbsalesmanname1,
			rm.divisioncode
		FROM startendday sed 
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
			WHERE 1=1 
			and NOT EXISTS (SELECT 1 FROM customeroperationscontrol c  WHERE sed.routekey = c.routekey)		
			",in_where,"	
union
SELECT 
			    coc.visitkey, 
			    coc.routekey, 
			    cm.alternatecode customercode, 
			    cm.customername,
			    cm.arbcustomername, 
			    rm.routecode, 
			    rm.routename, 
			    sm.salesmancode,
			    sm.salesmanname1, 
			    cm.customeraddress1, 
			    cm.customeraddress2, 
			    cm.customeraddress3, 
			    DATE_FORMAT(coc.visitstartdate, '%d %b %Y') visitstartdate, 
			    CAST(coc.visitstarttime AS TIME) visitstarttime, 
			    DATE_FORMAT(coc.visitenddate, '%d %b %Y') visitenddate, 
			    CAST(coc.visitendtime AS TIME) visitendtime, 
			    (SELECT nsr.description FROM nosalesheader nsh, nonservreasons nsr
				WHERE nsh.routekey = coc.routekey AND nsh.visitkey = coc.visitkey AND nsh.nosalereasoncode = nsr.code LIMIT 1) AS visited,
			    \"NON SERVICE  \" trantype, CONCAT(coc.routekey,coc.visitkey) documentno, 0 tranamount, 0 salepaid, 0 receiptpaid, CASE WHEN (TIMESTAMPDIFF(MINUTE,
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
)) >= 60 THEN (TIMESTAMPDIFF(MINUTE,
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
)) DIV 60 ELSE 0 END timeinhour,
			    (TIMESTAMPDIFF(MINUTE,
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
)) % 60 AS timeinmin, 
DATE_FORMAT(coc.visitstartdate, '%d %b %Y') trandate,
rm.arbroutename,sm.arbsalesmanname1,rm.divisioncode
		FROM 
			startendday sed
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
			INNER JOIN customeroperationscontrol coc ON coc.routekey = sed.routekey AND ifnull(coc.reasoncode,0) <= 0 
			INNER JOIN customermaster cm ON cm.customercode = coc.customercode
		WHERE 
			1=1 ",in_where,"
			) as t1 ORDER BY t1.routecode, t1.visitstartdate, t1.visitstarttime, ",in_orderby," ",in_sort) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
	  SELECT @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyreport_dailyrouteactivity_061118` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_dailyrouteactivity_061118` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_dailyrouteactivity_061118`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT
)
BEGIN
	SET @dyn_sql = CONCAT("
		SELECT t1.* from (
		SELECT 
			0 visitkey, ith.routekey, '' customercode, 'INVENTORY' customername, '' arbcustomername, rm.routecode, rm.routename, 
			sm.salesmancode, sm.salesmanname1, '' customeraddress1, '' customeraddress2, '' customeraddress3,
			DATE_FORMAT(ith.actualtransactiondate, '%d %b %Y') visitstartdate, CAST(ith.transactiontime AS TIME) visitstarttime, 
			DATE_FORMAT(ith.actualtransactiondate, '%d %b %Y') visitenddate, CAST(ith.transactiontime AS TIME) visitendtime, \"\" visited,
			CASE WHEN ith.transactiontype = 3 THEN 'UNLOAD' WHEN ith.transactiontype = 2 THEN 'LOAD TRANSFER' WHEN ith.transactiontype = 1 THEN 'LOAD' ELSE 'LOAD REQUEST' END trantype,
			ith.documentnumber documentno, 0 tranamount, 0 salePaid, 0 receiptPaid, 0 timeinhour, 0 timeinmin, 
			DATE_FORMAT(ith.actualtransactiondate, '%d %b %Y') trandate,rm.arbroutename,sm.arbsalesmanname1
		FROM 
			startendday sed
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
			INNER JOIN inventorytransactionheader ith ON ith.routekey = sed.routekey			
		WHERE 
			1=1 ",in_where,"
		
		UNION
		
		SELECT 
			    coc.visitkey, coc.routekey, cm.alternatecode customercode, cm.customername,cm.arbcustomername, rm.routecode, rm.routename, sm.salesmancode,
			    sm.salesmanname1, cm.customeraddress1, cm.customeraddress2, cm.customeraddress3, 
			    DATE_FORMAT(coc.visitstartdate, '%d %b %Y') visitstartdate, CAST(coc.visitstarttime AS TIME) visitstarttime, 
			    DATE_FORMAT(coc.visitenddate, '%d %b %Y') visitenddate, CAST(coc.visitendtime AS TIME) visitendtime, 
			    (SELECT nsr.description FROM nosalesheader nsh, nonservreasons nsr
				WHERE nsh.routekey = coc.routekey AND nsh.visitkey = coc.visitkey AND nsh.nosalereasoncode = nsr.code LIMIT 1) AS visited,
			    \"NON SERVICE  \" trantype, CONCAT(coc.routekey,coc.visitkey) documentno, 0 tranamount, 0 salepaid, 0 receiptpaid, CASE WHEN MINUTE(SUBTIME(TIME(coc.visitendtime),
			    TIME(coc.visitstarttime))) > 60 THEN MINUTE(SUBTIME(TIME(coc.visitendtime),TIME(coc.visitstarttime)))/60 ELSE 0 END timeinhour,
			    MINUTE(SUBTIME(TIME(coc.visitendtime),TIME(coc.visitstarttime))) % 60 AS timeinmin, DATE_FORMAT(coc.visitstartdate, '%d %b %Y') trandate,rm.arbroutename,sm.arbsalesmanname1
		FROM 
			startendday sed
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
			INNER JOIN customeroperationscontrol coc ON coc.routekey = sed.routekey AND coc.reasoncode > 0			
			INNER JOIN customermaster cm ON cm.customercode = coc.customercode
		WHERE 
			1=1 ",in_where,"
		
		UNION
		
		SELECT 
			coc.visitkey, coc.routekey, cm.alternatecode customercode, cm.customername,cm.arbcustomername, rm.routecode, rm.routename,
			sm.salesmancode, sm.salesmanname1, cm.customeraddress1, cm.customeraddress2, cm.customeraddress3, 
			 DATE_FORMAT(coc.visitstartdate, '%d %b %Y') visitstartdate, CAST(coc.visitstarttime AS TIME) visitstarttime, 
			 DATE_FORMAT(coc.visitenddate, '%d %b %Y') visitenddate, CAST(coc.visitendtime AS TIME) visitendtime, \"\" visited, 
			 CONCAT('SALES', CASE WHEN ih.voidflag=0 THEN '' ELSE ' *VOIDED' END) trantype, ih.documentnumber documentno, 
			 CASE WHEN ih.voidflag=1 THEN 0 ELSE ih.totalinvoiceamount END tranamount,
			 CASE WHEN ih.voidflag=1 THEN 0 ELSE ih.immediatepaid END salepaid, 0 receiptpaid,
			  CASE WHEN 
			  MINUTE(SUBTIME(TIME(coc.visitendtime),TIME(coc.visitstarttime))) > 60 THEN 
			  MINUTE(SUBTIME(TIME(coc.visitendtime),TIME(coc.visitstarttime)))/60 ELSE 0 END timeinhour, 
			  MINUTE(SUBTIME(TIME(coc.visitendtime),TIME(coc.visitstarttime))) % 60 AS timeinmin,DATE_FORMAT(ih.actualtransactiondate, '%d %b %Y') trandate ,rm.arbroutename,sm.arbsalesmanname1
		FROM 
			startendday sed
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
			INNER JOIN customeroperationscontrol coc ON coc.routekey = sed.routekey
			INNER JOIN invoiceheader ih ON ih.routekey = coc.routekey AND ih.visitkey = coc.visitkey
			INNER JOIN customermaster cm ON cm.customercode = coc.customercode			
		WHERE 
			1=1 ",in_where,"	
		
		UNION
		
		SELECT
			coc.visitkey, coc.routekey, cm.alternatecode customercode, cm.customername,cm.arbcustomername, rm.routecode, rm.routename, sm.salesmancode,
			sm.salesmanname1, cm.customeraddress1, cm.customeraddress2, cm.customeraddress3,
			DATE_FORMAT(coc.visitstartdate, '%d %b %Y') visitstartdate, CAST(coc.visitstarttime AS TIME) visitstarttime,
			DATE_FORMAT(coc.visitenddate, '%d %b %Y') visitenddate, CAST(coc.visitendtime AS TIME) visitendtime, \"\" visited, 
			CONCAT('ORDER', CASE WHEN soh.voidflag=0 THEN '' ELSE ' *VOIDED' END) trantype, soh.documentnumber documentno, 
			CASE WHEN soh.voidflag=1 THEN 0 ELSE soh.totalinvoiceamount END tranamount, 0 salepaid, 0 receiptpaid,
			CASE WHEN 
			MINUTE(SUBTIME(TIME(coc.visitendtime),TIME(coc.visitstarttime))) > 60 THEN 
			MINUTE(SUBTIME(TIME(coc.visitendtime),TIME(coc.visitstarttime)))/60 ELSE 0 END timeinhour,
			MINUTE(SUBTIME(TIME(coc.visitendtime),TIME(coc.visitstarttime))) % 60 AS timeinmin,
			DATE_FORMAT(soh.actualtransactiondate, '%d %b %Y') trandate ,rm.arbroutename,sm.arbsalesmanname1			
		FROM startendday sed
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
			INNER JOIN customeroperationscontrol coc ON coc.routekey = sed.routekey
			INNER JOIN salesorderheader soh ON soh.routekey = coc.routekey AND soh.visitkey = coc.visitkey
			INNER JOIN customermaster cm ON cm.customercode = coc.customercode
		WHERE 
			1=1 ",in_where,"
		
		UNION
		
		SELECT 
			coc.visitkey, coc.routekey, cm.alternatecode customercode, cm.customername,cm.arbcustomername, rm.routecode, rm.routename, sm.salesmancode,
			sm.salesmanname1, cm.customeraddress1, cm.customeraddress2, cm.customeraddress3, 
			DATE_FORMAT(coc.visitstartdate, '%d %b %Y') visitstartdate, CAST(coc.visitstarttime AS TIME) visitstarttime, 
			DATE_FORMAT(coc.visitenddate, '%d %b %Y') visitenddate, CAST(coc.visitendtime AS TIME) visitendtime, \"\" visited, 
			CONCAT('RECEIPT', CASE WHEN ah.voidflag=0 THEN '' ELSE ' *VOIDED' END) trantype, ah.documentnumber documentno, 
			CASE WHEN ah.voidflag=1 THEN 0 ELSE ah.totalinvoiceamount END tranamount, 0 salepaid, 
			CASE WHEN ah.voidflag=1 THEN 0 ELSE ah.amountpaid END receiptpaid,
			CASE WHEN 
			MINUTE(SUBTIME(TIME(coc.visitendtime),TIME(coc.visitstarttime))) > 60 THEN 
			MINUTE(SUBTIME(TIME(coc.visitendtime),TIME(coc.visitstarttime)))/60 ELSE 0 END timeinhour,
			MINUTE(SUBTIME(TIME(coc.visitendtime),TIME(coc.visitstarttime))) % 60 AS timeinmin, 
			DATE_FORMAT(ah.transactiondate, '%d %b %Y') trandate ,rm.arbroutename,sm.arbsalesmanname1
		FROM 
			startendday sed
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
			INNER JOIN customeroperationscontrol coc ON coc.routekey = sed.routekey
			INNER JOIN arheader ah ON ah.routekey = coc.routekey AND ah.visitkey = coc.visitkey
			INNER JOIN customermaster cm ON cm.customercode = coc.customercode
		WHERE 
			1=1 ",in_where,"	
		
			) as t1 ORDER BY t1.routecode, t1.visitstartdate, t1.visitstarttime, ",in_orderby," ",in_sort) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
	 
    END */$$
DELIMITER ;

