/* Procedure structure for procedure `sp_report_dailyreport_dailyrouteactivity_date` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_dailyrouteactivity_date` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_dailyrouteactivity_date`(
IN in_txdate DATE
)
BEGIN
	SET @dyn_sql = CONCAT("				
SELECT 
	0 visitkey, 
	ith.routekey, 
	'' customercode, 
	'INVENTORY' customername, 
	'' arbcustomername, 
	rm.routecode, 
	rm.routename, 
	sm.salesmancode, 
	sm.salesmanname1, 
	'' customeraddress1, 
	'' customeraddress2, 
	'' customeraddress3,
	DATE_FORMAT(ith.actualtransactiondate, '%d %b %Y') visitstartdate, 
	CAST(ith.transactiontime AS TIME) visitstarttime, 
	DATE_FORMAT(ith.actualtransactiondate, '%d %b %Y') visitenddate, 
	CAST(ith.transactiontime AS TIME) visitendtime, '' visited,
	CASE WHEN ith.transactiontype = 3 THEN 'UNLOAD' WHEN ith.transactiontype = 2 THEN 'LOAD TRANSFER' WHEN ith.transactiontype = 1 THEN 'LOAD' ELSE 'LOAD REQUEST' END trantype,
	ith.documentnumber documentno, 
	0 tranamount, 
	0 salePaid, 
	0 receiptPaid, 
	0 timeinhour, 
	0 timeinmin, 
	DATE_FORMAT(ith.actualtransactiondate, '%d %b %Y') trandate,rm.arbroutename,sm.arbsalesmanname1,rm.divisioncode
FROM 
	startendday sed
	INNER JOIN routemaster rm ON rm.routecode = sed.routecode
	INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
	INNER JOIN inventorytransactionheader ith ON ith.routekey = sed.routekey			
WHERE 
	1=1 and sed.routestartdate = '", in_txdate ,"'
	
union	
	
select 
coc.visitkey, 
	coc.routekey, 
	cm.alternatecode customercode, 
	cm.customername,
	cm.arbcustomername, 
	rm.routecode, 
	rm.routename, 
	sm.salesmancode,
	sm.salesmanname1, 
	cm.customeraddress1, 
	cm.customeraddress2, 
	cm.customeraddress3, 
	DATE_FORMAT(coc.visitstartdate, '%d %b %Y') visitstartdate, 
	CAST(coc.visitstarttime AS TIME) visitstarttime, 
	DATE_FORMAT(coc.visitenddate, '%d %b %Y') visitenddate, 
	CAST(coc.visitendtime AS TIME) visitendtime, 
	(SELECT nsr.description FROM nosalesheader nsh, nonservreasons nsr
	WHERE nsh.routekey = coc.routekey AND nsh.visitkey = coc.visitkey AND nsh.nosalereasoncode = nsr.code LIMIT 1) AS visited,
	'NON SERVICE' trantype, CONCAT(coc.routekey,coc.visitkey) documentno, 0 tranamount, 0 salepaid, 0 receiptpaid, CASE WHEN (TIMESTAMPDIFF(MINUTE,
	STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
	STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
	)) >= 60 THEN (TIMESTAMPDIFF(MINUTE,
	STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
	STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
	)) DIV 60 ELSE 0 END timeinhour,
					(TIMESTAMPDIFF(MINUTE,
	STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
	STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
	)) % 60 AS timeinmin, 
	DATE_FORMAT(coc.visitstartdate, '%d %b %Y') trandate,
	rm.arbroutename,
	sm.arbsalesmanname1,
	rm.divisioncode
from customeroperationscontrol coc 
inner join routemaster rm on rm.routecode = coc.routecode 
inner join salesman sm on sm.salesmancode = coc.salesmancode 
inner join customermaster cm on cm.customercode = coc.customercode 
where date(coc.visitstartdate) = '", in_txdate ,"' AND CASE WHEN coc.ROUTECODE in( 1100621, 1101323, 1101569, 1400054) THEN 1=1 ELSE  coc.reasoncode > 0 END		
			
union 
select 
	coc.visitkey, 
	coc.routekey, 
	cm.alternatecode customercode, 
	cm.customername,
	cm.arbcustomername, 
	rm.routecode, 
	rm.routename,
	sm.salesmancode, 
	sm.salesmanname1, 
	cm.customeraddress1, 
	cm.customeraddress2, 
	cm.customeraddress3, 
	DATE_FORMAT(coc.visitstartdate, '%d %b %Y') visitstartdate, CAST(coc.visitstarttime AS TIME) visitstarttime, 
	DATE_FORMAT(coc.visitenddate, '%d %b %Y') visitenddate, CAST(coc.visitendtime AS TIME) visitendtime,
	'' visited, 
	CONCAT('SALES', CASE WHEN ih.voidflag=0 THEN '' ELSE ' *VOIDED' END) trantype, 
	ih.documentnumber documentno, 
	CASE WHEN ih.voidflag=1 THEN 0 ELSE ih.totalinvoiceamount END tranamount,
	CASE WHEN ih.voidflag=1 THEN 0 ELSE ih.immediatepaid END salepaid, 0 receiptpaid,
	CASE WHEN 
		(TIMESTAMPDIFF(MINUTE,STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
		STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
		)) >= 60 THEN 
		(TIMESTAMPDIFF(MINUTE,
		STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
		STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
		)) DIV 60 ELSE 0 END timeinhour, 
	(TIMESTAMPDIFF(MINUTE,
		STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
		STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
		)) % 60 AS timeinmin,
	DATE_FORMAT(ih.actualtransactiondate, '%d %b %Y') trandate ,
	rm.arbroutename,
	sm.arbsalesmanname1,
	rm.divisioncode
from customeroperationscontrol coc 
	INNER JOIN invoiceheader ih ON ih.routekey = coc.routekey AND ih.visitkey = coc.visitkey
	inner join routemaster rm on rm.routecode = coc.routecode 
	inner join salesman sm on sm.salesmancode = coc.salesmancode 
	inner join customermaster cm on cm.customercode = coc.customercode 
	where 1=1 and date(coc.visitstartdate) = '", in_txdate ,"'
union
select 
	coc.visitkey, 
	coc.routekey, 
	cm.alternatecode customercode, 
	cm.customername,
	cm.arbcustomername, 
	rm.routecode, 
	rm.routename, 
	sm.salesmancode,
	sm.salesmanname1, 
	cm.customeraddress1, 
	cm.customeraddress2, 
	cm.customeraddress3,
	DATE_FORMAT(coc.visitstartdate, '%d %b %Y') visitstartdate, 
	CAST(coc.visitstarttime AS TIME) visitstarttime,
	DATE_FORMAT(coc.visitenddate, '%d %b %Y') visitenddate, 
	CAST(coc.visitendtime AS TIME) visitendtime, 
	'' visited, 
	CONCAT('ORDER', CASE WHEN soh.voidflag=0 THEN '' ELSE ' *VOIDED' END) trantype, 
	soh.documentnumber documentno, 
	CASE WHEN soh.voidflag=1 THEN 0 ELSE soh.totalinvoiceamount END tranamount, 
	0 salepaid, 
	0 receiptpaid,
	CASE WHEN 
	(TIMESTAMPDIFF(MINUTE,
		STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
		STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
		)) >= 60 THEN 
		(TIMESTAMPDIFF(MINUTE,
		STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
		STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
		)) DIV 60 ELSE 0 END timeinhour,
	(TIMESTAMPDIFF(MINUTE,
		STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
		STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
		)) % 60 AS timeinmin,
	DATE_FORMAT(soh.actualtransactiondate, '%d %b %Y') trandate ,
	rm.arbroutename,
	sm.arbsalesmanname1,
	rm.divisioncode	
from customeroperationscontrol coc 
	INNER JOIN  salesorderheader soh ON soh.routekey = coc.routekey AND soh.visitkey = coc.visitkey
	inner join routemaster rm on rm.routecode = coc.routecode 
	inner join salesman sm on sm.salesmancode = coc.salesmancode 
	inner join customermaster cm on cm.customercode = coc.customercode 
	where 1=1 and date(coc.visitstartdate) = '", in_txdate ,"'
UNION
select 
