		STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
		)) >= 60 THEN 
