			 CONCAT('SALES', CASE WHEN ih.voidflag=0 THEN '' ELSE ' *VOIDED' END) trantype, ih.documentnumber documentno, 
			 CASE WHEN ih.voidflag=1 THEN 0 ELSE ih.totalinvoiceamount END tranamount,
			 CASE WHEN ih.voidflag=1 THEN 0 ELSE ih.immediatepaid END salepaid, 0 receiptpaid,
			 CASE WHEN 
			 (TIMESTAMPDIFF(MINUTE,
			STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
			STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
			)) >= 60 THEN (TIMESTAMPDIFF(MINUTE, STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
			STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
			)) DIV 60 ELSE 0 END timeinhour, 
			(TIMESTAMPDIFF(MINUTE,
			STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
			STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
			)) % 60 AS timeinmin,
			clg.logstarttime, clg.logendtime,
			DATE_FORMAT(ih.actualtransactiondate, '%d %b %Y') trandate ,rm.arbroutename,sm.arbsalesmanname1,rm.divisioncode
		FROM 
			startendday sed
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
			INNER JOIN customeroperationscontrol coc ON coc.routekey = sed.routekey
			INNER JOIN invoiceheader ih ON ih.routekey = coc.routekey AND ih.visitkey = coc.visitkey
			INNER JOIN customermaster cm ON cm.customercode = coc.customercode	
			INNER JOIN CUSTOMERVISITLOG clg ON clg.routekey = sed.routekey AND clg.customercode = coc.customercode			
		WHERE 
			1=1 ",in_where,"	
		
		UNION
		
		SELECT
			coc.visitkey, coc.routekey, cm.alternatecode customercode, cm.customername,cm.arbcustomername, rm.routecode, rm.routename, sm.salesmancode,
			sm.salesmanname1, cm.customeraddress1, cm.customeraddress2, cm.customeraddress3,
			DATE_FORMAT(coc.visitstartdate, '%d %b %Y') visitstartdate, CAST(coc.visitstarttime AS TIME) visitstarttime,
			DATE_FORMAT(coc.visitenddate, '%d %b %Y') visitenddate, CAST(coc.visitendtime AS TIME) visitendtime, \"\" visited, 
			CONCAT('ORDER', CASE WHEN soh.voidflag=0 THEN '' ELSE ' *VOIDED' END) trantype, soh.documentnumber documentno, 
			CASE WHEN soh.voidflag=1 THEN 0 ELSE soh.totalinvoiceamount END tranamount, 0 salepaid, 0 receiptpaid,
			CASE WHEN 
			(TIMESTAMPDIFF(MINUTE,
			STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
			STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
			)) >= 60 THEN (TIMESTAMPDIFF(MINUTE, STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
			STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
			)) DIV 60 ELSE 0 END timeinhour,(TIMESTAMPDIFF(MINUTE,
			STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
			STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
			)) % 60 AS timeinmin, 
			clg.logstarttime, clg.logendtime,
			DATE_FORMAT(soh.actualtransactiondate, '%d %b %Y') trandate ,rm.arbroutename,sm.arbsalesmanname1,rm.divisioncode			
			FROM startendday sed
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
			INNER JOIN customeroperationscontrol coc ON coc.routekey = sed.routekey
			INNER JOIN salesorderheader soh ON soh.routekey = coc.routekey AND soh.visitkey = coc.visitkey
			INNER JOIN customermaster cm ON cm.customercode = coc.customercode
			INNER JOIN CUSTOMERVISITLOG clg ON clg.routekey = sed.routekey AND clg.customercode = coc.customercode
		WHERE 
			1=1 ",in_where,"
		
		UNION
		
		SELECT 
			coc.visitkey, coc.routekey, cm.alternatecode customercode, cm.customername,cm.arbcustomername, rm.routecode, rm.routename, sm.salesmancode,
			sm.salesmanname1, cm.customeraddress1, cm.customeraddress2, cm.customeraddress3, 
			DATE_FORMAT(coc.visitstartdate, '%d %b %Y') visitstartdate, CAST(coc.visitstarttime AS TIME) visitstarttime, 
			DATE_FORMAT(coc.visitenddate, '%d %b %Y') visitenddate, CAST(coc.visitendtime AS TIME) visitendtime, \"\" visited, 
			CONCAT('RECEIPT', CASE WHEN ah.voidflag=0 THEN '' ELSE ' *VOIDED' END) trantype, ah.documentnumber documentno, 
			CASE WHEN ah.voidflag=1 THEN 0 ELSE ah.totalinvoiceamount END tranamount, 0 salepaid, 
			CASE WHEN ah.voidflag=1 THEN 0 ELSE ah.amountpaid END receiptpaid,
			CASE WHEN 
			(TIMESTAMPDIFF(MINUTE,
			STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
			STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
			)) >= 60 THEN (TIMESTAMPDIFF(MINUTE,
			STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
			STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
			)) DIV 60 ELSE 0 END timeinhour,
			(TIMESTAMPDIFF(MINUTE,
			STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
			STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
			)) % 60 AS timeinmin, 
			clg.logstarttime, clg.logendtime,
			DATE_FORMAT(ah.transactiondate, '%d %b %Y') trandate ,rm.arbroutename,sm.arbsalesmanname1,rm.divisioncode
