			INNER JOIN arheader ah ON ah.routekey = coc.routekey AND ah.visitkey = coc.visitkey
			INNER JOIN customermaster cm ON cm.customercode = coc.customercode
			INNER JOIN CUSTOMERVISITLOG clg ON clg.routekey = sed.routekey AND clg.customercode = coc.customercode
		WHERE 
			1=1 ",in_where,"	
		
		union
		SELECT 
