			STR_TO_DATE(CONCAT(STR_TO_DATE(vd.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(vd.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
			STR_TO_DATE(CONCAT(STR_TO_DATE(vd.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(vd.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
			)) >= 60 THEN (TIMESTAMPDIFF(MINUTE,
			STR_TO_DATE(CONCAT(STR_TO_DATE(vd.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(vd.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
