			)) % 60 AS timeinmin, 
			(SELECT MIN(starttime) FROM tts_merch_cust_visit v WHERE v.routekey = sed.routekey AND v.customercode = vd.customercode) starttime, 
			(SELECT MAX(vdtl.visitendtime) FROM tts_merch_cust_visit_detl vdtl WHERE vdtl.routekey = sed.routekey AND vdtl.customercode = vd.customercode ) endtime,
			DATE_FORMAT(vd.visitstartdate, '%d %b %Y') trandate,rm.arbroutename,sm.arbsalesmanname1,rm.divisioncode		
