			-- INNER JOIN customeroperationscontrol coc ON coc.routekey = sed.routekey AND CASE WHEN SED.ROUTECODE in( 1100621, 1101323, 1101569, 1400054) THEN 1=1 ELSE  coc.reasoncode > 0	END		
			INNER JOIN tts_merch_cust_visit_detl vd ON vd.routekey = sed.routekey
