/* Procedure structure for procedure `sp_report_dailyreport_dailyrouteactivity_new_view` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_dailyrouteactivity_new_view` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_dailyrouteactivity_new_view`(
IN fromdate VARCHAR(255),
IN todate VARCHAR(255),
IN divcode VARCHAR(25)
)
BEGIN
	DECLARE div_cond VARCHAR(100) DEFAULT '';
	IF divcode  ='' THEN SET div_cond = ''; 
		ELSE SET div_cond = CONCAT(" and rm.divisioncode = '", 
			divcode, 
			"'"
			);
	END IF;
	SET
@dyn_sql = CONCAT("
SELECT 
	ifnull(coc.visitkey,0) visitkey, 
	clg.routekey, 
	cm.alternatecode customercode, 
	cm.customername,
	cm.arbcustomername, 
	rm.routecode, 
	rm.routename, 
	sm.salesmancode,
	sm.salesmanname1, 
	cm.customeraddress1, 
	cm.customeraddress2, 
	cm.customeraddress3,
	ifnull(DATE_FORMAT(coc.visitstartdate, '%d %b %Y'),'') visitstartdate, 
	ifnull(coc.visitstarttime,'00:00:00') visitstarttime,
	ifnull(DATE_FORMAT(coc.visitenddate, '%d %b %Y'),'') visitenddate,  
	ifnull(coc.visitendtime ,'00:00:00') visitendtime,
	CASE WHEN coc.trantype IS NOT NULL THEN trantype ELSE 'NON SERVICED' END trantype,
	ifnull(CASE WHEN coc.trantype IS NOT NULL THEN 'VISITED' ELSE (SELECT nsr.description FROM nosalesheader nsh, nonservreasons nsr WHERE nsh.routekey = coc.routekey AND nsh.visitkey = coc.visitkey AND nsh.nosalereasoncode = nsr.code LIMIT 1) END,'') AS visited,
	-- coc.reasoncode,
	IFNULL(coc.docno,0) documentno,IFNULL(coc.txnamoount,0) tranamount,IFNULL(coc.paidamount,0) salePaid, IFNULL(coc.rcptamount, 0) receiptPaid,
	ifnull(CASE WHEN (TIMESTAMPDIFF(MINUTE,STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s'))) > 60 THEN (TIMESTAMPDIFF(MINUTE,STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')))/60 ELSE 0 END,0) timeinhour, 
	ifnull((TIMESTAMPDIFF(MINUTE,STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'),STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s'))) % 60,0) AS timeinmin,
	clg.logstarttime custvisitstarttime, 
	clg.logendtime custvisitendtime, 
	TIME_FORMAT ( TIMEDIFF ( CONCAT(logenddate,' ', logendtime), CONCAT(logstartdate,' ', logstarttime) ), '%H:%i:%s') custvisitdur,
	ifnull(TIME_FORMAT ( TIMEDIFF ( CONCAT(DATE(coc.visitenddate),' ', coc.visitendtime), CONCAT(DATE(coc.visitstartdate),' ', coc.visitstarttime) ), '%H:%i:%s') ,'00:00:00') activitydur,	
	-- coc.trantype,   
	DATE_FORMAT(clg.logstartdate,'%d %b %Y') trandate,
	ifnull(rm.arbroutename,'') arbroutename,
	ifnull(sm.arbsalesmanname1,0) arbsalesmanname1,
	rm.divisioncode,
	DATE(sed.routestartdate) routestartdate
FROM 
startendday sed
INNER JOIN customervisitlog clg ON sed.routekey = clg.routekey and clg.customercode <>0 and clg.salesmancode <> 0
LEFT JOIN akg_cust_oprn_contl coc 
ON clg.customercode = coc.customercode 
AND coc.routekey = clg.routekey
AND TIME_FORMAT(coc.visitstarttime,'%H:%i') >= TIME_FORMAT(clg.logstarttime,'%H:%i') AND TIME_FORMAT(coc.visitendtime,'%H:%i') <= TIME_FORMAT(clg.logendtime ,'%H:%i')
LEFT JOIN customermaster cm ON clg.customercode = cm.customercode 
LEFT JOIN routemaster rm ON clg.routecode = rm.routecode 
LEFT JOIN salesman sm ON clg.salesmancode = sm.salesmancode  
WHERE 1=1",div_cond," and sed.routestartdate BETWEEN '",fromdate,"' AND '",todate,"' ORDER BY clg.routekey, coc.visitkey
		") ;
PREPARE s1
FROM
@dyn_sql;
EXECUTE s1;
SELECT
	@dyn_sql;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyreport_dailyrouteactivity_new_vw` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_dailyrouteactivity_new_vw` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_dailyrouteactivity_new_vw`(
IN fromdate VARCHAR(255),
IN todate VARCHAR(255),
IN divcode VARCHAR(25)
)
BEGIN
	DECLARE div_cond VARCHAR(100) DEFAULT '';
	IF divcode  ='' THEN SET div_cond = ''; 
		ELSE SET div_cond = CONCAT(" and rm.divisioncode = '", 
			divcode, 
			"'"
			);
	END IF;
	SET
@dyn_sql = CONCAT("
SELECT routestartdate, TRANDATE,  routekey, IFNULL(visitkey,0) visitkey,
customercode, customername, arbcustomername, customeraddress1, customeraddress2, customeraddress3, 
routecode, routename, arbroutename, divisioncode, 
salesmancode, salesmanname1, arbsalesmanname1, 
custvisitstarttime, custvisitendtime, custvisitdur, 
visitstartdate, visitstarttime, visitenddate, visitendtime, 
IFNULL(TIME_FORMAT ( TIMEDIFF ( visitend, visitstart ), '%H:%i:%s') ,'00:00:00') activitydur,
ifnull(TIMESTAMPDIFF(HOUR, visitstart, visitend),0) timeinhour,
ifnull(TIMESTAMPDIFF(MINUTE, visitstart, visitend),0) %60 timeinmin,
CASE WHEN visitkey IS NOT NULL THEN 'VISITED' ELSE '' END visited,
CASE WHEN inv IS NOT NULL THEN 'SALE' WHEN ar IS NOT NULL THEN 'RECEIPT' WHEN sh IS NOT NULL THEN 'ORDER' ELSE 'NON SERVICED' END trantype,
CASE WHEN inv IS NOT NULL THEN inv WHEN ar IS NOT NULL THEN ar WHEN sh IS NOT NULL THEN sh ELSE 0 END documentno,
CASE WHEN inv IS NOT NULL THEN invamt WHEN ar IS NOT NULL THEN 0 WHEN sh IS NOT NULL THEN ordamt ELSE 0 END tranamount,
CASE WHEN inv IS NOT NULL THEN amountpaid WHEN ar IS NOT NULL THEN 0 WHEN sh IS NOT NULL THEN 0 ELSE 0 END salePaid,
CASE WHEN inv IS NOT NULL THEN 0 WHEN ar IS NOT NULL THEN aramt WHEN sh IS NOT NULL THEN 0 ELSE 0 END receiptPaid
FROM 
(
	SELECT 
	DATE(s.routestartdate) routestartdate,
	ifnull(DATE_FORMAT(cv.logstartdate,'%d %b %Y'),'') trandate,
	cc.visitkey , cv.routekey , 
	cm.alternatecode customercode, cm.customername,	cm.arbcustomername, cm.customeraddress1, cm.customeraddress2, cm.customeraddress3,
	rm.routecode, rm.routename, IFNULL(rm.arbroutename,'') arbroutename,rm.divisioncode,	
	sm.salesmancode,sm.salesmanname1, IFNULL(sm.arbsalesmanname1,0) arbsalesmanname1,
	CONCAT(DATE(cc.visitenddate),' ', TIME_FORMAT(cc.visitendtime,'%H:%i:%s' )) visitend , 
	CONCAT(DATE(cc.visitstartdate),' ', TIME_FORMAT(cc.visitstarttime,'%H:%i:%s')  )visitstart ,
	IFNULL(DATE_FORMAT(cc.visitstartdate, '%d %b %Y'),'') visitstartdate, IFNULL(cc.visitstarttime,'00:00:00') visitstarttime,
	IFNULL(DATE_FORMAT(cc.visitenddate, '%d %b %Y'),'') visitenddate,  IFNULL(cc.visitendtime ,'00:00:00') visitendtime,
	cv.logstarttime custvisitstarttime, 
	cv.logendtime custvisitendtime, 
	TIME_FORMAT ( TIMEDIFF ( CONCAT(logenddate,' ', logendtime), CONCAT(logstartdate,' ', logstarttime) ), '%H:%i:%s') custvisitdur,
	i.documentnumber inv, i.totalinvoiceamount invamt , i.amountpaid , 
	a.documentnumber ar, a.amountpaid aramt,
	s2.documentnumber sh, s2.totalinvoiceamount ordamt
	FROM startendday s 
	INNER JOIN customervisitlog cv ON s.routekey = cv.routekey  and cv.customercode <>0 and cv.salesmancode <> 0
	LEFT JOIN customeroperationscontrol cc ON cv.routekey = cc.routekey AND cc.customercode = cv.customercode AND TIME_FORMAT(cv.logstarttime, '%H:%i') <= TIME_FORMAT(cc.visitstarttime,'%H:%i') AND TIME_FORMAT(cv.logendtime,'%H:%i') >= TIME_FORMAT(cc.visitendtime , '%H:%i')
	LEFT JOIN invoiceheader i ON i.routekey= cc.routekey AND i.visitkey = cc.visitkey 
	LEFT JOIN salesorderheader s2 ON s2.routekey = cc.routekey AND s2.visitkey = cc.visitkey 
	LEFT JOIN arheader a ON a.routekey = cc.routekey AND a.visitkey = cc.visitkey
	INNER JOIN routemaster rm ON rm.routecode = cv.routecode 
	INNER JOIN customermaster cm ON cm.customercode = cv.customercode 
	INNER JOIN salesman sm ON sm.salesmancode = cv.salesmancode 
	WHERE 1=1 ",div_cond," and s.routestartdate between '",fromdate,"' and '",todate,"' ORDER BY s.routekey, cc.visitkey
) av
") ;
PREPARE s1
FROM
@dyn_sql;
EXECUTE s1;
SELECT
	@dyn_sql;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyreport_dailyrouteactivity_vw` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_dailyrouteactivity_vw` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_dailyrouteactivity_vw`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT
)
BEGIN
	SET @dyn_sql = CONCAT("
		SELECT t1.* from (
		SELECT 
			0 visitkey, ith.routekey, '' customercode, 'INVENTORY' customername, '' arbcustomername, rm.routecode, rm.routename, 
			sm.salesmancode, sm.salesmanname1, '' customeraddress1, '' customeraddress2, '' customeraddress3,
			DATE_FORMAT(ith.actualtransactiondate, '%d %b %Y') visitstartdate, CAST(ith.transactiontime AS TIME) visitstarttime, 
			DATE_FORMAT(ith.actualtransactiondate, '%d %b %Y') visitenddate, CAST(ith.transactiontime AS TIME) visitendtime, \"\" visited,
			CASE WHEN ith.transactiontype = 3 THEN 'UNLOAD' WHEN ith.transactiontype = 2 THEN 'LOAD TRANSFER' WHEN ith.transactiontype = 1 THEN 'LOAD' ELSE 'LOAD REQUEST' END trantype,
			ith.documentnumber documentno, 0 tranamount, 0 salePaid, 0 receiptPaid, 0 timeinhour, 0 timeinmin, 
			DATE_FORMAT(ith.actualtransactiondate, '%d %b %Y') trandate,rm.arbroutename,sm.arbsalesmanname1
		FROM 
			startendday sed
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
			INNER JOIN inventorytransactionheader ith ON ith.routekey = sed.routekey			
		WHERE 
			1=1 ",in_where,"
		
		UNION
		
		SELECT 
			coc.visitkey, 
			coc.routekey, 
			cm.alternatecode customercode, 
			cm.customername,
			cm.arbcustomername, 
			rm.routecode, 
			rm.routename, 
			sm.salesmancode,
			sm.salesmanname1, 
			cm.customeraddress1, 
			cm.customeraddress2, 
			cm.customeraddress3, 
			DATE_FORMAT(coc.visitstartdate, '%d %b %Y') visitstartdate, 
			CAST(coc.visitstarttime AS TIME) visitstarttime, 
			DATE_FORMAT(coc.visitenddate, '%d %b %Y') visitenddate, 
			CAST(coc.visitendtime AS TIME) visitendtime, 
			(SELECT nsr.description FROM nosalesheader nsh, nonservreasons nsr WHERE nsh.routekey = coc.routekey AND nsh.visitkey = coc.visitkey AND nsh.nosalereasoncode = nsr.code LIMIT 1) AS visited,
			\"NON SERVICE  \" trantype, 
			CONCAT(coc.routekey,coc.visitkey) documentno, 
			0 tranamount, 
			0 salepaid, 
			0 receiptpaid, 
			CASE WHEN (TIMESTAMPDIFF(MINUTE,STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'),STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s'))) > 60 THEN (TIMESTAMPDIFF(MINUTE,STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')))/60 ELSE 0 END timeinhour,
			(TIMESTAMPDIFF(MINUTE,STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s'))) % 60 AS timeinmin, 
			DATE_FORMAT(coc.visitstartdate, '%d %b %Y') trandate,
			rm.arbroutename,
			sm.arbsalesmanname1
		FROM 
			startendday sed
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
			INNER JOIN customeroperationscontrol coc ON coc.routekey = sed.routekey AND coc.reasoncode > 0			
			INNER JOIN customermaster cm ON cm.customercode = coc.customercode
		WHERE 
			1=1 ",in_where,"
		
		UNION
		
		SELECT 
			coc.visitkey, 
			coc.routekey, 
			cm.alternatecode customercode, 
			cm.customername,
			cm.arbcustomername, 
			rm.routecode, 
			rm.routename,
			sm.salesmancode, 
			sm.salesmanname1, 
			cm.customeraddress1, 
			cm.customeraddress2, 
			cm.customeraddress3, 
			DATE_FORMAT(coc.visitstartdate, '%d %b %Y') visitstartdate, 
			CAST(coc.visitstarttime AS TIME) visitstarttime, 
			DATE_FORMAT(coc.visitenddate, '%d %b %Y') visitenddate, 
			CAST(coc.visitendtime AS TIME) visitendtime, 
			\"\" visited, 
			CONCAT('SALES', CASE WHEN ih.voidflag=0 THEN '' ELSE ' *VOIDED' END) trantype, 
			ih.documentnumber documentno, 
			CASE WHEN ih.voidflag=1 THEN 0 ELSE ih.totalinvoiceamount END tranamount,
			CASE WHEN ih.voidflag=1 THEN 0 ELSE ih.immediatepaid END salepaid, 
			0 receiptpaid,
			CASE WHEN (TIMESTAMPDIFF(MINUTE,STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s'))) > 60 THEN (TIMESTAMPDIFF(MINUTE,STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')))/60 ELSE 0 END timeinhour, 
			(TIMESTAMPDIFF(MINUTE,STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'),STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s'))) % 60 AS timeinmin,
			DATE_FORMAT(ih.actualtransactiondate, '%d %b %Y') trandate ,
			rm.arbroutename,
			sm.arbsalesmanname1
		FROM 
			startendday sed
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
			INNER JOIN customeroperationscontrol coc ON coc.routekey = sed.routekey
			INNER JOIN invoiceheader ih ON ih.routekey = coc.routekey AND ih.visitkey = coc.visitkey
			INNER JOIN customermaster cm ON cm.customercode = coc.customercode			
		WHERE 
			1=1 ",in_where,"	
		
		UNION
		
		SELECT
			coc.visitkey, 
			coc.routekey, 
			cm.alternatecode customercode, 
			cm.customername,
			cm.arbcustomername, 
			rm.routecode, 
			rm.routename, 
			sm.salesmancode,
			sm.salesmanname1, 
			cm.customeraddress1, 
			cm.customeraddress2, 
			cm.customeraddress3,
			DATE_FORMAT(coc.visitstartdate, '%d %b %Y') visitstartdate, 
			CAST(coc.visitstarttime AS TIME) visitstarttime,
			DATE_FORMAT(coc.visitenddate, '%d %b %Y') visitenddate, 
			CAST(coc.visitendtime AS TIME) visitendtime, 
			\"\" visited, 
			CONCAT('ORDER', CASE WHEN soh.voidflag=0 THEN '' ELSE ' *VOIDED' END) trantype, 
			soh.documentnumber documentno, 
			CASE WHEN soh.voidflag=1 THEN 0 ELSE soh.totalinvoiceamount END tranamount, 
			0 salepaid, 
			0 receiptpaid,
			CASE WHEN (TIMESTAMPDIFF(MINUTE,STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s'))) > 60 THEN (TIMESTAMPDIFF(MINUTE,STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')))/60 ELSE 0 END timeinhour,
			(TIMESTAMPDIFF(MINUTE,STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s'))) % 60 AS timeinmin,
			DATE_FORMAT(soh.actualtransactiondate, '%d %b %Y') trandate ,
			rm.arbroutename,
			sm.arbsalesmanname1			
		FROM startendday sed
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
			INNER JOIN customeroperationscontrol coc ON coc.routekey = sed.routekey
			INNER JOIN salesorderheader soh ON soh.routekey = coc.routekey AND soh.visitkey = coc.visitkey
			INNER JOIN customermaster cm ON cm.customercode = coc.customercode
		WHERE 
			1=1 ",in_where,"
		
		UNION
		
		SELECT 
			coc.visitkey, 
			coc.routekey, 
			cm.alternatecode customercode, 
			cm.customername,
			cm.arbcustomername, 
			rm.routecode, 
			rm.routename, 
			sm.salesmancode,
			sm.salesmanname1, 
			cm.customeraddress1, 
			cm.customeraddress2, 
			cm.customeraddress3, 
			DATE_FORMAT(coc.visitstartdate, '%d %b %Y') visitstartdate, 
			CAST(coc.visitstarttime AS TIME) visitstarttime, 
			DATE_FORMAT(coc.visitenddate, '%d %b %Y') visitenddate, 
			CAST(coc.visitendtime AS TIME) visitendtime, 
			\"\" visited, 
			CONCAT('RECEIPT', CASE WHEN ah.voidflag=0 THEN '' ELSE ' *VOIDED' END) trantype, 
			ah.documentnumber documentno, 
			CASE WHEN ah.voidflag=1 THEN 0 ELSE ah.totalinvoiceamount END tranamount, 
			0 salepaid, 
			CASE WHEN ah.voidflag=1 THEN 0 ELSE ah.amountpaid END receiptpaid,
			CASE WHEN (TIMESTAMPDIFF(MINUTE,STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s'))) > 60 THEN (TIMESTAMPDIFF(MINUTE,STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')))/60 ELSE 0 END timeinhour,
			(TIMESTAMPDIFF(MINUTE,STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), STR_TO_DATE(CONCAT(STR_TO_DATE(coc.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(coc.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s'))) % 60 AS timeinmin, 
			DATE_FORMAT(ah.transactiondate, '%d %b %Y') trandate ,
			rm.arbroutename,
			sm.arbsalesmanname1
		FROM 
			startendday sed
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
			INNER JOIN customeroperationscontrol coc ON coc.routekey = sed.routekey
			INNER JOIN arheader ah ON ah.routekey = coc.routekey AND ah.visitkey = coc.visitkey
			INNER JOIN customermaster cm ON cm.customercode = coc.customercode
		WHERE 
			1=1 ",in_where,"	
		union all 			
			select visitkey, routekey, cust_erp_code, cust_name, null, routecode, routecode,MERCH_CODE, MERCH_NAME,  
			cust_address1, cust_address2, cust_address3, txndate, starttime,txndate, endtime, null, 'serviced', 0,0,0,0,
			TIMESTAMPDIFF(hour, strtime, stoptime) hours, (TIMESTAMPDIFF(MINUTE, strtime, stoptime))%60 minutes, 
			txndate, null, fsm_name, 'MER-OU'
			from (
			select v.visitkey , v.routekey , c.cust_erp_code , c.cust_name ,  v.routecode , r.ROUTE_CODE routename, m.MERCH_CODE ,  
			m.MERCH_NAME , cust_address1 , cust_address2 , cust_address3 , txndate, v.starttime , v.endtime , 
			STR_TO_DATE(CONCAT(STR_TO_DATE(txndate,'%Y-%m-%d'),' ',STR_TO_DATE(starttime, '%H:%i')),'%Y-%m-%d %H:%i:%s') strtime,
			STR_TO_DATE(CONCAT(STR_TO_DATE(txndate,'%Y-%m-%d'),' ',STR_TO_DATE(endtime, '%H:%i')),'%Y-%m-%d %H:%i:%s') stoptime,
			f.fsm_name
			from merch_live.tts_merch_cust_visit v 
			inner join merch_live.tts_merch_route_master r on v.routecode = r.ROUTE_CODE 
			inner join merch_live.tts_merch_merchandiser_master m on v.agentcode = m.MERCH_CODE 
			inner join merch_live.tts_merch_cust_master c on v.customercode = c.cust_code 
			inner join merch_live.tts_merch_fsm_master f on m.FSM_CODE = f.fsm_code 
			where v.txndate = (DATE_SUB(CURDATE(), INTERVAL 1 DAY))
			) a
			) as t1 ORDER BY t1.routecode, t1.visitstartdate, t1.visitstarttime, ",in_orderby," ",in_sort) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
	  SELECT @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyreport_dailyroutetripanalysis` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_dailyroutetripanalysis` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_dailyroutetripanalysis`(
	IN route_enddate TEXT,
	IN routecode TEXT,
	IN in_orderby VARCHAR(255),
	IN in_sort VARCHAR(25)
)
BEGIN
	DECLARE limit_val TEXT DEFAULT "";
	DECLARE in_counter INT(8);
	    
	SET @tablename = "tmp_dailyreport_tripanalysis";
	
	SET @tmp = CONCAT("DROP TABLE IF EXISTS ",@tablename);
	PREPARE qry FROM @tmp ;
	EXECUTE qry;    
    
	SET @sqlroute = '';
	IF @route != '' THEN
	    SET @sqlroute = CONCAT(' and sed.routecode in (' , @route , ') ');
	END IF;    
    
	SET @sqlquery = CONCAT(" CREATE TABLE IF NOT EXISTS ", @tablename, " AS 
		SELECT visit.routekey, visit.visitkey, visit.trantype, visit.invoicenumber, coc.visitstartdate currentday, DAYNAME(coc.visitstartdate) `dayname`,
			rs.seqweeknumber sequenceweekday, 1 startdayorder, visit.visitkey visitsequence, sed.routestartdate, sed.routeenddate, 
			sed.routecode, rm.routename, sed.salesmancode, sm.salesmanname1, cm.alternatecode customercode, cm.customername, 
			CASE WHEN cm.invoicepaymentterms < 2 THEN 'CASH' WHEN cm.invoicepaymentterms = 2 THEN 'CREDIT' ELSE 'TC' END AS mop,
			rs.schelduledflag, inv.lastsales, pre.lastorder, CASE WHEN rs.schelduledflag = 0 THEN 'NO' ELSE 'YES' END visitsheduled, 
			coc.visitstartdate, coc.visitenddate, coc.visitstarttime, coc.visitendtime, TIMEDIFF(coc.visitendtime,coc.visitstarttime) AS timespend, 
			coc.totaltransactions, visit.visitstatus, ' ' reason, ROUND(visit.amount,2) amount, 
			coc.latitude, coc.longitude, rm.arbroutename, sm.arbsalesmanname1, cm.arbcustomername, visit.voidflag
		FROM
			startendday sed	
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
			INNER JOIN customeroperationscontrol coc ON coc.routekey = sed.routekey	
			INNER JOIN routesequencecustomerstatus rs ON rs.routekey = coc.routekey AND rs.customercode = coc.customercode
			INNER JOIN customermaster cm ON cm.customercode = coc.customercode	
			INNER JOIN
				(
				SELECT ih.routekey, ih.visitkey, 'SALES' trantype, ih.voidflag, CONCAT('SALES', CASE WHEN ih.voidflag=0 THEN ' ' ELSE ' *VOIDED*' END) visitstatus, ih.totalinvoiceamount amount, ih.invoicenumber
				FROM invoiceheader ih 
					UNION
				SELECT ih.routekey, ih.visitkey, 'RECEIPT' trantype, ih.voidflag, CONCAT('RECEIPT', CASE WHEN ih.voidflag=0 THEN ' ' ELSE ' *VOIDED*' END) visitstatus, ih.totalinvoiceamount amount, ih.invoicenumber
				FROM  arheader ih 
					UNION
				SELECT ih.routekey, ih.visitkey, 'ORDER' trantype, ih.voidflag, CONCAT('ORDER', CASE WHEN ih.voidflag=0 THEN ' ' ELSE ' *VOIDED*' END) visitstatus, ih.totalinvoiceamount amount, ih.invoicenumber
				FROM  salesorderheader ih 
					UNION
				SELECT ih.routekey, ih.visitkey, 'MERCHANDISING' trantype, 0 voidflag, 'MERCHANDISING' visitstatus, 0 amount, CONCAT(ih.routekey, ih.visitkey) invoicenumber
				FROM  surveyauditdetail ih 
					UNION
				SELECT ih.routekey, ih.visitkey, 'MERCHANDISING' trantype, 0 voidflag, 'MERCHANDISING' visitstatus, 0 amount, CONCAT(ih.routekey, ih.visitkey) invoicenumber
				FROM  posequipmentchangedetail ih
					UNION
				SELECT coc1.routekey, coc1.visitkey, 'NO SALE' trantype, 0 voidflag, ns.description visitstatus, 0 amount, CONCAT(coc1.routekey, coc1.visitkey) invoicenumber
				FROM  customeroperationscontrol AS coc1 INNER JOIN nonservreasons ns ON ns.code = coc1.reasoncode
				WHERE coc1.reasoncode > 0) visit ON visit.routekey = coc.routekey AND visit.visitkey = coc.visitkey
			LEFT OUTER JOIN 
				(SELECT routekey, customercode, MAX(transactiondate) lastsales
				FROM invoiceheader WHERE voidflag = 0 GROUP BY customercode) inv ON inv.customercode = coc.customercode AND inv.routekey < sed.routekey
			LEFT OUTER JOIN 
				(SELECT routekey, customercode, MAX(transactiondate) lastorder 
				FROM salesorderheader WHERE voidflag = 0 GROUP BY customercode) pre ON pre.customercode = coc.customercode AND pre.routekey < sed.routekey
		WHERE sed.routeenddate = '", route_enddate,"' ", @sqlroute);    
	PREPARE s1 FROM @sqlquery;
	EXECUTE s1;
	
	
	
	
	
	
	
	
	
	SET @tmp = CONCAT("
		SELECT routekey, visitkey, trantype, invoicenumber, currentday, dayname, sequenceweekday, startdayorder, visitsequence, 
		routestartdate, routeenddate, routecode, routename, salesmancode, salesmanname1, customercode reportcustcode, customername, mop,
		schelduledflag, lastsales, lastorder, visitsheduled, visitstartdate, visitenddate, visitstarttime, visitendtime, timespend, 
		totaltransactions, visitstatus, reason, CASE WHEN voidflag =0 THEN amount ELSE 0 END totalinvoiceamount, 
		latitude, longitude, arbroutename, arbsalesmanname1, arbcustomername
		FROM ", @tablename, "
		ORDER BY routekey, visitkey ") ;
	 PREPARE qry FROM @tmp;
	 EXECUTE qry;	
	 
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyreport_discountsummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_discountsummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_discountsummary`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT
)
BEGIN
	DECLARE limit_val TEXT DEFAULT "";
	
	SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter 
				FROM invoiceheader ih
					INNER JOIN customermaster cm ON cm.customercode = ih.customercode
					INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
					INNER JOIN routemaster rm ON rm.routecode = ih.routecode
				WHERE ih.voidflag = 0 AND ih.totaldiscountamount + ih.totalfreesampleamount >0 ", in_where);
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	
	SET @dyn_sql = CONCAT("SELECT
					ih.routekey, ih.visitkey, YEAR(ih.actualtransactiondate) AS noyear,
					 MONTH(ih.actualtransactiondate) AS nomonth, ih.actualtransactiondate AS trandate, 
					 DATE_FORMAT(ih.actualtransactiondate, '%d %b %y') AS transactiondate, ih.transactiontime, ih.invoicenumber, 
					 cm.reportcustcode customercode, cm.customername, sm.salesmancode, sm.salesmanname1, rm.routecode, rm.routename, 
					 ih.totalsalesamount salesamount, ih.totalreturnamount goodreturnamount, ih.totaldamagedamount, 
					 ih.totalexpiryamount, ih.totalfreesampleamount freeamount, 
					 ih.totaldiscountamount discountamount, 
					 ih.totalinvoiceamount invoiceamount, ih.immediatepaid, ih.amountpaid, ih.invoicebalance,
					 cm.arbcustomername,sm.arbsalesmanname1,rm.arbroutename
				FROM invoiceheader ih
					INNER JOIN customermaster cm ON cm.customercode = ih.customercode
					INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
					INNER JOIN routemaster rm ON rm.routecode = ih.routecode
				WHERE ih.voidflag = 0 AND ih.totaldiscountamount + ih.totalfreesampleamount >0 ",in_where, " ORDER BY ", in_orderby, " ",in_sort, " ",limit_val);
	
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyreport_discountsummary_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_discountsummary_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_discountsummary_detail`()
BEGIN
CALL sp_combo_routemaster() ;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyreport_pricingsummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_pricingsummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_pricingsummary`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT,
in_export_status int
)
BEGIN
	DECLARE limit_val TEXT DEFAULT "";
	DECLARE groupby_val TEXT DEFAULT "";
	
	IF in_export_status != 1 THEN 
		SET groupby_val = CONCAT(" GROUP BY ih.invoicenumber ");
	
	
		SET @dyn_sql = CONCAT("SELECT COUNT(t1.cnt) INTO @in_counter FROM ( SELECT count(*) as cnt 
					FROM invoiceheader ih, invoicedetail id, itemmaster im,customermaster cm, routemaster rm 
					WHERE  cm.customercode = ih.customercode AND rm.routecode = ih.routecode 
					   AND id.transactionkey = ih.transactionkey AND im.actualitemcode = id.itemcode AND id.salesprice != id.stdsalesprice  ", in_where,groupby_val," ) as t1");
		PREPARE s1 FROM @dyn_sql;
		EXECUTE s1;
		
		IF in_limit != "" && in_page != "" THEN 
			CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
			SELECT @new_start_limit AS start_limit,@in_counter AS counter;
			SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
		END IF;
	END IF;
	
	
	SET @dyn_sql = CONCAT("SELECT DATE_FORMAT(ih.transactiondate, '%d %b %Y') as transactiondate,ih.transactiontime, ih.invoicenumber, rm.routecode, rm.routename, cm.alternatecode `code`, cm.customername,
					ih.totalinvoiceamount,ih.totalfreesampleamount, im.alternatecode itemcode, im.itemdescription, im.unitspercase, id.salesqty, id.stdsalesprice,
					id.salesprice, id.stdsalesprice - id.salesprice difference  ,id.salescaseprice,id.stdsalescaseprice,
					cm.arbcustomername
			       FROM invoiceheader ih, invoicedetail id, itemmaster im,customermaster cm, routemaster rm
			       WHERE cm.customercode = ih.customercode AND rm.routecode = ih.routecode
				   AND id.transactionkey = ih.transactionkey AND im.actualitemcode = id.itemcode AND id.salesprice != id.stdsalesprice
				    ",in_where," ",groupby_val," ORDER BY ", in_orderby, " ",in_sort, " ",limit_val);
	
	
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyreport_pricingsummary_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_pricingsummary_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_pricingsummary_detail`()
BEGIN
CALL sp_combo_routemaster() ;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyreport_pricingsummary_subgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_pricingsummary_subgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_pricingsummary_subgrid`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25)
)
BEGIN
	SET @dyn_sql = CONCAT("SELECT im.alternatecode itemcode, im.itemdescription, im.unitspercase, id.salesqty, id.stdsalesprice,
					id.salesprice, id.stdsalesprice - id.salesprice difference  ,id.salescaseprice,id.stdsalescaseprice,
					im.arbitemdescription
			       FROM invoiceheader ih, invoicedetail id, itemmaster im
			       WHERE id.transactionkey = ih.transactionkey AND im.actualitemcode = id.itemcode AND id.salesprice != id.stdsalesprice 
				    ",in_where, " ORDER BY ", in_orderby, " ",in_sort);
	
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyreport_routeactivity` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_routeactivity` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_routeactivity`(
IN fromdate VARCHAR(255),
IN todate VARCHAR(255),
IN divcode VARCHAR(25)
)
BEGIN
	DECLARE div_cond VARCHAR(100) DEFAULT '';
	IF divcode  ='' THEN SET div_cond = ''; 
		ELSE SET div_cond = CONCAT(" and rm.divisioncode = '", 
			divcode, 
			"'"
			);
	END IF;
	SET
@dyn_sql = CONCAT("
SELECT routestartdate, TRANDATE,  routekey, IFNULL(visitkey,0) visitkey,
customercode, customername, arbcustomername, customeraddress1, customeraddress2, customeraddress3, 
routecode, routename, arbroutename, divisioncode, 
salesmancode, salesmanname1, arbsalesmanname1, 
custvisitstarttime, custvisitendtime, custvisitdur, 
visitstartdate, visitstarttime, visitenddate, visitendtime, 
IFNULL(TIME_FORMAT ( TIMEDIFF ( visitend, visitstart ), '%H:%i:%s') ,'00:00:00') activitydur,
ifnull(TIMESTAMPDIFF(HOUR, visitstart, visitend),0) timeinhour,
ifnull(TIMESTAMPDIFF(MINUTE, visitstart, visitend),0) %60 timeinmin,
CASE WHEN visitkey IS NOT NULL THEN 'VISITED' ELSE '' END visited,
CASE WHEN inv IS NOT NULL THEN 'SALE' WHEN ar IS NOT NULL THEN 'RECEIPT' WHEN sh IS NOT NULL THEN 'ORDER' ELSE 'NON SERVICED' END trantype,
CASE WHEN inv IS NOT NULL THEN inv WHEN ar IS NOT NULL THEN ar WHEN sh IS NOT NULL THEN sh ELSE 0 END documentno,
CASE WHEN inv IS NOT NULL THEN invamt WHEN ar IS NOT NULL THEN 0 WHEN sh IS NOT NULL THEN ordamt ELSE 0 END tranamount,
CASE WHEN inv IS NOT NULL THEN amountpaid WHEN ar IS NOT NULL THEN 0 WHEN sh IS NOT NULL THEN 0 ELSE 0 END salePaid,
CASE WHEN inv IS NOT NULL THEN 0 WHEN ar IS NOT NULL THEN aramt WHEN sh IS NOT NULL THEN 0 ELSE 0 END receiptPaid
FROM 
(
	SELECT 
	DATE(s.routestartdate) routestartdate,
	ifnull(DATE_FORMAT(cv.logstartdate,'%d %b %Y'),'') trandate,
	cc.visitkey , cv.routekey , 
	cm.alternatecode customercode, cm.customername,	cm.arbcustomername, cm.customeraddress1, cm.customeraddress2, cm.customeraddress3,
	rm.routecode, rm.routename, IFNULL(rm.arbroutename,'') arbroutename,rm.divisioncode,	
	sm.salesmancode,sm.salesmanname1, IFNULL(sm.arbsalesmanname1,0) arbsalesmanname1,
	CONCAT(DATE(cc.visitenddate),' ', TIME_FORMAT(cc.visitendtime,'%H:%i:%s' )) visitend , 
	CONCAT(DATE(cc.visitstartdate),' ', TIME_FORMAT(cc.visitstarttime,'%H:%i:%s')  )visitstart ,
	IFNULL(DATE_FORMAT(cc.visitstartdate, '%d %b %Y'),'') visitstartdate, IFNULL(cc.visitstarttime,'00:00:00') visitstarttime,
	IFNULL(DATE_FORMAT(cc.visitenddate, '%d %b %Y'),'') visitenddate,  IFNULL(cc.visitendtime ,'00:00:00') visitendtime,
	cv.logstarttime custvisitstarttime, 
	cv.logendtime custvisitendtime, 
	TIME_FORMAT ( TIMEDIFF ( CONCAT(logenddate,' ', logendtime), CONCAT(logstartdate,' ', logstarttime) ), '%H:%i:%s') custvisitdur,
	i.documentnumber inv, i.totalinvoiceamount invamt , i.amountpaid , 
	a.documentnumber ar, a.amountpaid aramt,
	s2.documentnumber sh, s2.totalinvoiceamount ordamt
	FROM startendday s 
	INNER JOIN customervisitlog cv ON s.routekey = cv.routekey  and cv.customercode <>0 and cv.salesmancode <> 0
	LEFT JOIN customeroperationscontrol cc ON cv.routekey = cc.routekey AND cc.customercode = cv.customercode AND TIME_FORMAT(cv.logstarttime, '%H:%i') <= TIME_FORMAT(cc.visitstarttime,'%H:%i') AND TIME_FORMAT(cv.logendtime,'%H:%i') >= TIME_FORMAT(cc.visitendtime , '%H:%i')
	LEFT JOIN invoiceheader i ON i.routekey= cc.routekey AND i.visitkey = cc.visitkey 
	LEFT JOIN salesorderheader s2 ON s2.routekey = cc.routekey AND s2.visitkey = cc.visitkey 
	LEFT JOIN arheader a ON a.routekey = cc.routekey AND a.visitkey = cc.visitkey
	INNER JOIN routemaster rm ON rm.routecode = cv.routecode 
	INNER JOIN customermaster cm ON cm.customercode = cv.customercode 
	INNER JOIN salesman sm ON sm.salesmancode = cv.salesmancode 
	WHERE 1=1 ",div_cond," and s.routestartdate between '",fromdate,"' and '",todate,"' ORDER BY s.routekey, cc.visitkey
) av
") ;
PREPARE s1
FROM
@dyn_sql;
EXECUTE s1;
SELECT
	@dyn_sql;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyreport_routedepositsummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_routedepositsummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_routedepositsummary`(
	IN in_where TEXT,
	IN in_orderby VARCHAR(255),
	IN in_sort VARCHAR(25),
	IN in_limit INT,
	IN in_page INT,
	IN routecode TEXT
)
BEGIN
SET @strihroute = '';
IF routecode != '' THEN
	SET @strihroute = CONCAT(' AND ih.routecode IN (', routecode , ') ');
END IF;
SET @strarroute = '';
IF routecode != '' THEN
	SET @strarroute = CONCAT(' AND arh.routecode IN (' , routecode , ') ');
END IF;
SET @dyn_sql = CONCAT('
			SELECT t1.* from (
					SELECT
						"INVOICE" `type`,DATE_FORMAT(sed.routeenddate, "%d %b %Y") routeenddate, ih.routekey, ih.visitkey, ih.invoicenumber,
						DATE_FORMAT(ih.actualtransactiondate, "%d %b %Y") transactiondate, ih.totalinvoiceamount as transactiontime,
						DATE_FORMAT(ih.salesmancode, "%d %b %Y") invoicedby, " " againstinv, DATE_FORMAT(ih.actualtransactiondate, "%d %b %Y") saleinvoiceddate,
						cm.alternatecode as customercode, cm.reportcustcode, customeraddress1 as customername, ih.routecode, rm.routename, ih.salesmancode, sm.salesmanname1, ccd.typecode,
						CASE WHEN ccd.typecode = 0 THEN "CASH" ELSE "CHEQUE" END paytype,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE ccd.checknumber END checknumber,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE DATE_FORMAT(ccd.checkdate, "%d %b %Y") END checkdate,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE ccd.bankcode END bankcode,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE bm.bankname END bankname,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE bm.arbbankname END arbbankname,
						ccd.amount,
						CASE WHEN ccd.typecode = 0 THEN ccd.amount ELSE 0 END cashamt,
						CASE WHEN ccd.typecode = 1 THEN ccd.amount ELSE 0 END checkamt,
						cm.arbcustomername,rm.arbroutename,sm.arbsalesmanname1, cm.alternatecode,ih.comments
					FROM
						startendday sed
						INNER JOIN invoiceheader ih ON ih.routekey = sed.routekey and ih.voidflag = 0
						INNER JOIN cashcheckdetail ccd ON ccd.routekey = ih.routekey and ccd.visitkey = ih.visitkey
						INNER JOIN customermaster cm ON cm.customercode = ih.customercode
						INNER JOIN routemaster rm ON rm.routecode = ih.routecode
						INNER JOIN salesman sm on sm.salesmancode = ih.salesmancode
						LEFT JOIN bankmaster bm on bm.bankcode = ccd.bankcode
					WHERE 1=1 ',@strihroute ,' ',in_where,'
					UNION
					SELECT
						"AR" `type`, DATE_FORMAT(sed.routeenddate, "%d %b %Y") routeenddate, arh.routekey, arh.visitkey, arh.invoicenumber, DATE_FORMAT(arh.transactiondate, "%d %b %Y") transactiondate, ard.totalinvoiceamount as  transactiontime,
						(SELECT ih1.salesmancode FROM invoiceheader ih1 WHERE ih1.invoicenumber = ard.invoicenumber)  invoicedby,
						ard.alternateinvoicenumber againstinv, DATE_FORMAT(ard.invoicedate, "%d %b %Y") saleinvoiceddate,
						cm.alternatecode as  customercode, cm.reportcustcode, customeraddress1 as customername,
						arh.routecode, rm.routename, arh.salesmancode, sm.salesmanname1, ccd.typecode,
						CASE WHEN ccd.typecode = 0 THEN "CASH" ELSE "CHEQUE" END paytype,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE ccd.checknumber END checknumber,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE DATE_FORMAT(ccd.checkdate, "%d %b %Y") END checkdate,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE ccd.bankcode END bankcode,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE bm.bankname END bankname,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE bm.arbbankname END arbbankname,
						ard.amountpaid as amount,
						CASE WHEN ccd.typecode = 0 THEN ard.amountpaid  ELSE 0 END cashamt,
						CASE WHEN ccd.typecode = 1 THEN ard.amountpaid  ELSE 0 END checkamt,
						cm.arbcustomername,rm.arbroutename,sm.arbsalesmanname1, cm.alternatecode,arh.comments
					FROM
						startendday sed
						INNER JOIN arheader arh ON arh.routekey = sed.routekey AND arh.voidflag = 0
						INNER JOIN ardetail ard ON ard.routekey = arh.routekey and ard.visitkey = arh.visitkey
						INNER JOIN cashcheckdetail ccd ON ccd.routekey = arh.routekey and ccd.visitkey = arh.visitkey
						INNER JOIN customermaster cm ON cm.customercode = arh.customercode
						INNER JOIN routemaster rm ON rm.routecode = arh.routecode
						INNER JOIN salesman sm on sm.salesmancode = arh.salesmancode
						LEFT JOIN bankmaster bm on bm.bankcode = ccd.bankcode
					WHERE
						1=1 ',@strarroute ,' ',in_where,'
					UNION
					SELECT
						"ADVANCE PAYMENT" `type`, DATE_FORMAT(sed.routeenddate, "%d %b %Y") routeenddate, arh.routekey, arh.visitkey, arh.invoicenumber,  DATE_FORMAT(arh.transactiondate, "%d %b %Y") transactiondate, arh.totalinvoiceamount as transactiontime,
						"" invoicedby, "" againstinv, "" saleinvoiceddate,
						cm.alternatecode as customercode, cm.reportcustcode, customeraddress1 as customername,
						arh.routecode, rm.routename, arh.salesmancode, sm.salesmanname1, ccd.typecode,
						CASE WHEN ccd.typecode = 0 THEN "CASH" ELSE "CHEQUE" END paytype,
						CASE WHEN ccd.typecode = 0 THEN "" ELSE ccd.checknumber END checknumber,
						CASE WHEN ccd.typecode = 0 THEN "" ELSE  DATE_FORMAT(ccd.checkdate, "%d %b %Y") END checkdate,
						CASE WHEN ccd.typecode = 0 THEN "" ELSE ccd.bankcode END bankcode,
						CASE WHEN ccd.typecode = 0 THEN "" ELSE bm.bankname END bankname,
						CASE WHEN ccd.typecode = 0 THEN "" ELSE bm.arbbankname END arbbankname,
						arh.amountpaid amount,
						CASE WHEN ccd.typecode = 0 THEN arh.amountpaid ELSE 0 END cashamt,
						CASE WHEN ccd.typecode = 1 THEN arh.amountpaid ELSE 0 END checkamt,
						cm.arbcustomername,rm.arbroutename,sm.arbsalesmanname1, cm.alternatecode,arh.comments
					FROM
						startendday sed
						INNER JOIN arheader arh ON arh.routekey = sed.routekey AND arh.voidflag = 0
						INNER JOIN cashcheckdetail ccd ON ccd.routekey = arh.routekey and ccd.visitkey = arh.visitkey
						INNER JOIN customermaster cm ON cm.customercode = arh.customercode
						INNER JOIN routemaster rm ON rm.routecode = arh.routecode
						INNER JOIN salesman sm on sm.salesmancode = arh.salesmancode
						LEFT JOIN bankmaster bm on bm.bankcode = ccd.bankcode
					WHERE
					         
						1=1 and advancepaymentflag=1 ',@strarroute ,' ',in_where,'
				) as t1 ORDER BY t1.',in_orderby,' ',in_sort) ;
	 		
PREPARE S1 FROM @DYN_SQL;
EXECUTE S1;
 SELECT @dyn_sql;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyreport_routedepositsummary3102021` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_routedepositsummary3102021` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_routedepositsummary3102021`(
	IN in_where TEXT,
	IN in_orderby VARCHAR(255),
	IN in_sort VARCHAR(25),
	IN in_limit INT,
	IN in_page INT,
	IN routecode TEXT
)
BEGIN
SET @strihroute = '';
IF routecode != '' THEN
	SET @strihroute = CONCAT(' AND ih.routecode IN (', routecode , ') ');
END IF;
SET @strarroute = '';
IF routecode != '' THEN
	SET @strarroute = CONCAT(' AND arh.routecode IN (' , routecode , ') ');
END IF;
SET @dyn_sql = CONCAT('
			SELECT t1.* from (
					SELECT
						"INVOICE" `type`,DATE_FORMAT(sed.routeenddate, "%d %b %Y") routeenddate, ih.routekey, ih.visitkey, ih.invoicenumber,
						DATE_FORMAT(ih.actualtransactiondate, "%d %b %Y") transactiondate, ih.transactiontime,
						DATE_FORMAT(ih.salesmancode, "%d %b %Y") invoicedby, " " againstinv, DATE_FORMAT(ih.actualtransactiondate, "%d %b %Y") saleinvoiceddate,
						ih.customercode, cm.reportcustcode, cm.customername, ih.routecode, rm.routename, ih.salesmancode, sm.salesmanname1, ccd.typecode,
						CASE WHEN ccd.typecode = 0 THEN "CASH" ELSE "CHEQUE" END paytype,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE ccd.checknumber END checknumber,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE DATE_FORMAT(ccd.checkdate, "%d %b %Y") END checkdate,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE ccd.bankcode END bankcode,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE bm.bankname END bankname,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE bm.arbbankname END arbbankname,
						ccd.amount,
						CASE WHEN ccd.typecode = 0 THEN ccd.amount ELSE 0 END cashamt,
						CASE WHEN ccd.typecode = 1 THEN ccd.amount ELSE 0 END checkamt,
						cm.arbcustomername,rm.arbroutename,sm.arbsalesmanname1, cm.alternatecode,ih.comments
					FROM
						startendday sed
						INNER JOIN invoiceheader ih ON ih.routekey = sed.routekey and ih.voidflag = 0
						INNER JOIN cashcheckdetail ccd ON ccd.routekey = ih.routekey and ccd.visitkey = ih.visitkey
						INNER JOIN customermaster cm ON cm.customercode = ih.customercode
						INNER JOIN routemaster rm ON rm.routecode = ih.routecode
						INNER JOIN salesman sm on sm.salesmancode = ih.salesmancode
						LEFT JOIN bankmaster bm on bm.bankcode = ccd.bankcode
					WHERE 1=1 ',@strihroute ,' ',in_where,'
					UNION
					SELECT
						"AR" `type`, DATE_FORMAT(sed.routeenddate, "%d %b %Y") routeenddate, arh.routekey, arh.visitkey, arh.invoicenumber, DATE_FORMAT(arh.transactiondate, "%d %b %Y") transactiondate, arh.transactiontime,
						(SELECT ih1.salesmancode FROM invoiceheader ih1 WHERE ih1.invoicenumber = ard.invoicenumber)  invoicedby,
						ard.alternateinvoicenumber againstinv, DATE_FORMAT(ard.invoicedate, "%d %b %Y") saleinvoiceddate,
						arh.customercode, cm.reportcustcode, cm.customername,
						arh.routecode, rm.routename, arh.salesmancode, sm.salesmanname1, ccd.typecode,
						CASE WHEN ccd.typecode = 0 THEN "CASH" ELSE "CHEQUE" END paytype,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE ccd.checknumber END checknumber,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE DATE_FORMAT(ccd.checkdate, "%d %b %Y") END checkdate,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE ccd.bankcode END bankcode,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE bm.bankname END bankname,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE bm.arbbankname END arbbankname,
						ard.amountpaid as amount,
						CASE WHEN ccd.typecode = 0 THEN ard.amountpaid  ELSE 0 END cashamt,
						CASE WHEN ccd.typecode = 1 THEN ard.amountpaid  ELSE 0 END checkamt,
						cm.arbcustomername,rm.arbroutename,sm.arbsalesmanname1, cm.alternatecode,arh.comments
					FROM
						startendday sed
						INNER JOIN arheader arh ON arh.routekey = sed.routekey AND arh.voidflag = 0
						INNER JOIN ardetail ard ON ard.routekey = arh.routekey and ard.visitkey = arh.visitkey
						INNER JOIN cashcheckdetail ccd ON ccd.routekey = arh.routekey and ccd.visitkey = arh.visitkey
						INNER JOIN customermaster cm ON cm.customercode = arh.customercode
						INNER JOIN routemaster rm ON rm.routecode = arh.routecode
						INNER JOIN salesman sm on sm.salesmancode = arh.salesmancode
						LEFT JOIN bankmaster bm on bm.bankcode = ccd.bankcode
					WHERE
						1=1 ',@strarroute ,' ',in_where,'
					UNION
					SELECT
						"ADVANCE PAYMENT" `type`, DATE_FORMAT(sed.routeenddate, "%d %b %Y") routeenddate, arh.routekey, arh.visitkey, arh.invoicenumber,  DATE_FORMAT(arh.transactiondate, "%d %b %Y") transactiondate, arh.transactiontime,
						"" invoicedby, "" againstinv, "" saleinvoiceddate,
						arh.customercode, cm.reportcustcode, cm.customername,
						arh.routecode, rm.routename, arh.salesmancode, sm.salesmanname1, ccd.typecode,
						CASE WHEN ccd.typecode = 0 THEN "CASH" ELSE "CHEQUE" END paytype,
						CASE WHEN ccd.typecode = 0 THEN "" ELSE ccd.checknumber END checknumber,
						CASE WHEN ccd.typecode = 0 THEN "" ELSE  DATE_FORMAT(ccd.checkdate, "%d %b %Y") END checkdate,
						CASE WHEN ccd.typecode = 0 THEN "" ELSE ccd.bankcode END bankcode,
						CASE WHEN ccd.typecode = 0 THEN "" ELSE bm.bankname END bankname,
						CASE WHEN ccd.typecode = 0 THEN "" ELSE bm.arbbankname END arbbankname,
						arh.amountpaid amount,
						CASE WHEN ccd.typecode = 0 THEN arh.amountpaid ELSE 0 END cashamt,
						CASE WHEN ccd.typecode = 1 THEN arh.amountpaid ELSE 0 END checkamt,
						cm.arbcustomername,rm.arbroutename,sm.arbsalesmanname1, cm.alternatecode,arh.comments
					FROM
						startendday sed
						INNER JOIN arheader arh ON arh.routekey = sed.routekey AND arh.voidflag = 0
						INNER JOIN cashcheckdetail ccd ON ccd.routekey = arh.routekey and ccd.visitkey = arh.visitkey
						INNER JOIN customermaster cm ON cm.customercode = arh.customercode
						INNER JOIN routemaster rm ON rm.routecode = arh.routecode
						INNER JOIN salesman sm on sm.salesmancode = arh.salesmancode
						LEFT JOIN bankmaster bm on bm.bankcode = ccd.bankcode
					WHERE
					         
						1=1 and advancepaymentflag=1 ',@strarroute ,' ',in_where,'
				) as t1 ORDER BY t1.',in_orderby,' ',in_sort) ;
	 		
PREPARE S1 FROM @DYN_SQL;
EXECUTE S1;
 SELECT @dyn_sql;
END */$$
DELIMITER ;

