/* Procedure structure for procedure `sp_report_dailyreport_routedepositsummary_with_permission` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_routedepositsummary_with_permission` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_routedepositsummary_with_permission`(
	IN in_where TEXT,
	IN in_orderby VARCHAR(255),
	IN in_sort VARCHAR(25),
	IN in_limit INT,
	IN in_page INT,
	IN routecode TEXT,
	IN username TEXT			 
)
BEGIN
SET @strihroute = '';
IF routecode != '' THEN
	SET @strihroute = CONCAT(' AND ih.routecode IN (', routecode , ') ');
END IF;
SET @strarroute = '';
IF routecode != '' THEN
	SET @strarroute = CONCAT(' AND arh.routecode IN (' , routecode , ') ');
END IF;
SET @extrawhere = CONCAT(" and rm.subareacode IN (SELECT DISTINCT subareacode  FROM `useraccesscodes` WHERE username='", username ,"')");
		SET in_where=CONCAT(in_where,@extrawhere);
SET @dyn_sql = CONCAT('
			SELECT t1.* from (
					SELECT
						"INVOICE" `type`,DATE_FORMAT(sed.routeenddate, "%d %b %Y") routeenddate, ih.routekey, ih.visitkey, ih.invoicenumber,
						DATE_FORMAT(ih.actualtransactiondate, "%d %b %Y") transactiondate, ih.totalinvoiceamount as transactiontime,
						DATE_FORMAT(ih.salesmancode, "%d %b %Y") invoicedby, " " againstinv, DATE_FORMAT(ih.actualtransactiondate, "%d %b %Y") saleinvoiceddate,
						cm.alternatecode as customercode, cm.reportcustcode, customeraddress1 as customername, ih.routecode, rm.routename, ih.salesmancode, sm.salesmanname1, ccd.typecode,
						CASE WHEN ccd.typecode = 0 THEN "CASH" ELSE "CHEQUE" END paytype,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE ccd.checknumber END checknumber,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE DATE_FORMAT(ccd.checkdate, "%d %b %Y") END checkdate,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE ccd.bankcode END bankcode,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE bm.bankname END bankname,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE bm.arbbankname END arbbankname,
						ccd.amount,
						CASE WHEN ccd.typecode = 0 THEN ccd.amount ELSE 0 END cashamt,
						CASE WHEN ccd.typecode = 1 THEN ccd.amount ELSE 0 END checkamt,
						cm.arbcustomername,rm.arbroutename,sm.arbsalesmanname1, cm.alternatecode,ih.comments,rm.divisioncode
					FROM
						startendday sed
						INNER JOIN invoiceheader ih ON ih.routekey = sed.routekey and ih.voidflag = 0
						INNER JOIN cashcheckdetail ccd ON ccd.routekey = ih.routekey and ccd.visitkey = ih.visitkey AND ccd.hhctransactionkey > 0
						INNER JOIN customermaster cm ON cm.customercode = ih.customercode
						INNER JOIN routemaster rm ON rm.routecode = ih.routecode
						INNER JOIN salesman sm on sm.salesmancode = ih.salesmancode
						LEFT JOIN bankmaster bm on bm.bankcode = ccd.bankcode
					WHERE 1=1 AND CCD.AMOUNT != 0 ',@strihroute ,' ',in_where,'
					UNION
					SELECT
						"AR" `type`, DATE_FORMAT(sed.routeenddate, "%d %b %Y") routeenddate, arh.routekey, arh.visitkey, arh.invoicenumber, DATE_FORMAT(arh.transactiondate, "%d %b %Y") transactiondate, ard.totalinvoiceamount as  transactiontime,
						(SELECT ih1.salesmancode FROM invoiceheader ih1 WHERE ih1.invoicenumber = ard.invoicenumber)  invoicedby,
						ard.alternateinvoicenumber againstinv, DATE_FORMAT(ard.invoicedate, "%d %b %Y") saleinvoiceddate,
						cm.alternatecode as  customercode, cm.reportcustcode, customeraddress1 as customername,
						arh.routecode, rm.routename, arh.salesmancode, sm.salesmanname1, ccd.typecode,
						CASE WHEN ccd.typecode = 0 THEN "CASH" ELSE "CHEQUE" END paytype,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE ccd.checknumber END checknumber,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE DATE_FORMAT(ccd.checkdate, "%d %b %Y") END checkdate,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE ccd.bankcode END bankcode,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE bm.bankname END bankname,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE bm.arbbankname END arbbankname,
						ard.amountpaid as amount,
						CASE WHEN ccd.typecode = 0 THEN ard.amountpaid  ELSE 0 END cashamt,
						CASE WHEN ccd.typecode = 1 THEN ard.amountpaid  ELSE 0 END checkamt,
						cm.arbcustomername,rm.arbroutename,sm.arbsalesmanname1, cm.alternatecode,arh.comments,rm.divisioncode
					FROM
						startendday sed
						INNER JOIN arheader arh ON arh.routekey = sed.routekey AND arh.voidflag = 0
						INNER JOIN ardetail ard ON ard.routekey = arh.routekey and ard.visitkey = arh.visitkey
						INNER JOIN cashcheckdetail ccd ON ccd.routekey = arh.routekey and ccd.visitkey = arh.visitkey
						INNER JOIN customermaster cm ON cm.customercode = arh.customercode
						INNER JOIN routemaster rm ON rm.routecode = arh.routecode
						INNER JOIN salesman sm on sm.salesmancode = arh.salesmancode
						LEFT JOIN bankmaster bm on bm.bankcode = ccd.bankcode
					WHERE
						1=1 AND CCD.AMOUNT != 0 ',@strarroute ,' ',in_where,'
					UNION
					SELECT
						"ADVANCE PAYMENT" `type`, DATE_FORMAT(sed.routeenddate, "%d %b %Y") routeenddate, arh.routekey, arh.visitkey, arh.invoicenumber,  DATE_FORMAT(arh.transactiondate, "%d %b %Y") transactiondate, arh.totalinvoiceamount as transactiontime,
						"" invoicedby, "" againstinv, "" saleinvoiceddate,
						cm.alternatecode as customercode, cm.reportcustcode, customeraddress1 as customername,
						arh.routecode, rm.routename, arh.salesmancode, sm.salesmanname1, ccd.typecode,
						CASE WHEN ccd.typecode = 0 THEN "CASH" ELSE "CHEQUE" END paytype,
						CASE WHEN ccd.typecode = 0 THEN "" ELSE ccd.checknumber END checknumber,
						CASE WHEN ccd.typecode = 0 THEN "" ELSE  DATE_FORMAT(ccd.checkdate, "%d %b %Y") END checkdate,
						CASE WHEN ccd.typecode = 0 THEN "" ELSE ccd.bankcode END bankcode,
						CASE WHEN ccd.typecode = 0 THEN "" ELSE bm.bankname END bankname,
						CASE WHEN ccd.typecode = 0 THEN "" ELSE bm.arbbankname END arbbankname,
						arh.amountpaid amount,
						CASE WHEN ccd.typecode = 0 THEN arh.amountpaid ELSE 0 END cashamt,
						CASE WHEN ccd.typecode = 1 THEN arh.amountpaid ELSE 0 END checkamt,
						cm.arbcustomername,rm.arbroutename,sm.arbsalesmanname1, cm.alternatecode,arh.comments,rm.divisioncode
					FROM
						startendday sed
						INNER JOIN arheader arh ON arh.routekey = sed.routekey AND arh.voidflag = 0
						INNER JOIN cashcheckdetail ccd ON ccd.routekey = arh.routekey and ccd.visitkey = arh.visitkey
						INNER JOIN customermaster cm ON cm.customercode = arh.customercode
						INNER JOIN routemaster rm ON rm.routecode = arh.routecode
						INNER JOIN salesman sm on sm.salesmancode = arh.salesmancode
						LEFT JOIN bankmaster bm on bm.bankcode = ccd.bankcode
					WHERE
					         
						1=1 AND CCD.AMOUNT != 0 and advancepaymentflag=1 ',@strarroute ,' ',in_where,'
				) as t1 ORDER BY t1.',in_orderby,' ',in_sort) ;
	 		
PREPARE S1 FROM @DYN_SQL;
EXECUTE S1;
 SELECT @dyn_sql;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyreport_routedepositsummary_with_permission_new` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_routedepositsummary_with_permission_new` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_routedepositsummary_with_permission_new`(
	IN in_where TEXT,
	IN in_orderby VARCHAR(255),
	IN in_sort VARCHAR(25),
	IN in_limit INT,
	IN in_page INT,	
	IN username TEXT			 
)
BEGIN
SET @extrawhere = CONCAT(" and rm.subareacode IN (SELECT DISTINCT subareacode  FROM `useraccesscodes` WHERE username='", username ,"')");
SET @dyn_sql = CONCAT('SELECT t1.* from (SELECT type, date_format(routeenddate, "%d-%b-%Y") routeenddate, routekey, visitkey, invoicenumber, date_format(transactiondate, "%d-%b-%Y")transactiondate, 
                                transactiontime, invoicedby, againstinv, date_format(saleinvoiceddate, "%d-%b-%Y") saleinvoiceddate, customercode, reportcustcode, customername, routecode, routename, 
                                salesmancode, salesmanname1, typecode, paytype, checknumber, date_format(checkdate, "%d-%b-%Y") checkdate, bankcode, bankname, arbbankname, amount, cashamt, 
                                checkamt, arbcustomername, arbroutename, 
                                arbsalesmanname1, alternatecode, comments, divisioncode FROM tts_mtd_monthly WHERE 1=1 and amount > 0 ',
			in_where,
			') as t1 ORDER BY ',
			in_orderby,
			' ',
			in_sort
			) ;
	 		
PREPARE S1 FROM @DYN_SQL;
EXECUTE S1;
 SELECT @dyn_sql;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyreport_routeinventory` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_routeinventory` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_routeinventory`(
	IN in_where TEXT,
	IN in_orderby VARCHAR(500),
	IN in_sort VARCHAR(50),
	IN in_limit INT,
	IN in_page INT)
BEGIN
	DECLARE limit_val TEXT DEFAULT "";
	DECLARE in_counter INT(8);
	
	SET @tablename = "tmp_routeinventory_report";
	
	SET @tmp = CONCAT("DROP TABLE IF EXISTS ",@tablename);
	PREPARE qry FROM @tmp ;
	EXECUTE qry;
	
	SET @tmp = CONCAT(" CREATE TABLE IF NOT EXISTS ", @tablename, " AS 
		SELECT
			sed.routekey, sed.routecode, rm.routename, sed.salesmancode, sm.salesmanname1 salesman,
			mc.majorcategorycode, mc.description majorcategroy, im.alternatecode itemcode, im.unitspercase upc, im.itemdescription,		    
			isd.beginstockqty, isd.loadqty, isd.loadaddqty, isd.loadcutqty, 
			COALESCE(isd.saleqty,0) salesqty, COALESCE(isd.returnqty,0) returnqty, COALESCE(isd.damageqty,0) damagedqty, COALESCE(isd.freesampleqty,0) freeqty,
			(isd.endstockqty + isd.unloadqty) endqty,			    
			isd.vanstockvalue truckstockvalue,
			(isd.damageqty - isd.damagedunloadqty) damagevariance,
			rm.arbroutename, sm.arbsalesmanname1, mc.arbdescription as arbmajorcatdes, im.arbitemdescription,
			stdsalescaseprice, stdsalesprice
		FROM 
			startendday sed
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
			INNER JOIN inventorysummarydetail isd ON isd.routekey = sed.routekey
			INNER JOIN itemmaster im ON im.actualitemcode = isd.itemcode
			INNER JOIN itemgroup ig ON ig.itemgroupcode = im.itemgroupcode
			INNER JOIN submajorcategory smc ON smc.submajorcategorycode = ig.submajorcategorycode
			INNER JOIN majorcategory mc ON mc.majorcategorycode = smc.majorcategorycode
			
			WHERE 1=1 ", in_where);
	
	
	
	
	
	
	
	 PREPARE qry FROM @tmp;
	 EXECUTE qry;	
	
	SELECT COUNT(cnt.counter) INTO in_counter
	FROM
	(SELECT COUNT(*) AS counter
	FROM tmp_routeinventory_report
	GROUP BY routekey, routecode, majorcategorycode, itemcode) cnt;
	SELECT in_counter;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data (in_counter, in_limit, in_page, @new_start_limit);
		SELECT @new_start_limit AS start_limit, in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ", @new_start_limit, ",", in_limit);
	END IF;
	
	SET @tmp = CONCAT("
		SELECT
		routekey, routecode, routename, salesmancode, salesman, majorcategorycode, majorcategroy, itemcode, itemdescription, upc, 
		-- beginstockqty, loadqty, loadaddqty, loadcutqty, salesqty, returnqty, damagedqty, freeqty, endqty, 
		CONCAT(FLOOR(beginstockqty/upc),'/',(CASE WHEN beginstockqty MOD upc <> 0 THEN beginstockqty MOD upc ELSE 0 END)) beginstock,		
		CONCAT(FLOOR(loadqty/upc),'/',(CASE WHEN loadqty MOD upc <> 0 THEN loadqty MOD upc ELSE 0 END)) loadstock,		
		CONCAT(FLOOR(loadaddqty/upc),'/',(CASE WHEN loadaddqty MOD upc <> 0 THEN loadaddqty MOD upc ELSE 0 END)) loadaddstock,		
		CONCAT(FLOOR(loadcutqty/upc),'/',(CASE WHEN loadcutqty MOD upc <> 0 THEN loadcutqty MOD upc ELSE 0 END)) loadcutstock,		
		CONCAT(FLOOR(salesqty/upc),'/',(CASE WHEN salesqty MOD upc <> 0 THEN salesqty MOD upc ELSE 0 END)) salesstock,		
		CONCAT(FLOOR(returnqty/upc),'/',(CASE WHEN returnqty MOD upc <> 0 THEN returnqty MOD upc ELSE 0 END)) returnqstock,		
		CONCAT(FLOOR(damagedqty/upc),'/',(CASE WHEN damagedqty MOD upc <> 0 THEN damagedqty MOD upc ELSE 0 END)) damagedstock,		
		CONCAT(FLOOR(freeqty/upc),'/',(CASE WHEN freeqty MOD upc <> 0 THEN freeqty MOD upc ELSE 0 END)) freestock,		
		CONCAT(FLOOR(endqty/upc),'/',(CASE WHEN endqty MOD upc <> 0 THEN endqty MOD upc ELSE 0 END)) endstock,
		truckstockvalue,
		((endqty/upc) * stdsalescaseprice) + (CASE WHEN endqty MOD upc <> 0 THEN (endqty MOD upc) * stdsalesprice ELSE 0 END) endstockvalue,
		damagevariance damagevarianceqty, 
		CONCAT(FLOOR(damagevariance/upc),'/',(CASE WHEN damagevariance MOD upc <> 0 THEN damagevariance MOD upc ELSE 0 END)) damagevariancestock,		
		((damagevariance/upc) * stdsalescaseprice) + (CASE WHEN damagevariance MOD upc <> 0 THEN (damagevariance MOD upc) * stdsalesprice ELSE 0 END) damagevariancevalue,
		arbroutename, arbsalesmanname1, arbmajorcatdes, arbitemdescription
		FROM ", @tablename, "
		GROUP BY routekey, routecode, routename, arbroutename, salesmancode, majorcategorycode, majorcategroy, itemcode, itemdescription, upc
		ORDER BY ",in_orderby," ",in_sort," ",limit_val) ;
	 PREPARE qry FROM @tmp;
	 EXECUTE qry;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyreport_routeinventory_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_routeinventory_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_routeinventory_detail`()
BEGIN
CALL sp_combo_routemaster() ;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyreport_routesummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_routesummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_routesummary`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT
)
BEGIN
	DECLARE limit_val TEXT DEFAULT "";
	
	SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter 
				FROM startendday sed, routemaster rm, salesman sm
				WHERE sed.routecode = rm.routecode AND sed.salesmancode = sm.salesmancode ", in_where);
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	
	SET @dyn_sql = CONCAT("SELECT sed.routekey, rm.routecode, rm.routename, CONCAT(rm.routecode,'-',rm.routename) AS routes, 
					sm.salesmancode, sm.salesmanname1, CONCAT(sm.salesmancode,'-', sm.salesmanname1) AS salesman,
					DATE_FORMAT(sed.routestartdate, '%d %b %Y') routestartdate, sed.routestarttime,DATE_FORMAT(sed.routeenddate, '%d %b %Y') routeenddate, sed.routeendtime, sed.routestartodometer, sed.routeendodometer, 
					COALESCE((SELECT COUNT(ih.invoicenumber) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND ih.voidflag = 0 AND ih.totalsalesamount + ih.totalfreesampleamount + ih.totalmanualfree > 0), 0 ) totalinvdocuments, 
					COALESCE((SELECT COUNT(ih.invoicenumber) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND ih.voidflag = 0 AND ih.totalsalesamount + ih.totalfreesampleamount + ih.totalmanualfree = 0), 0 ) totalinvretdocuments,
					COALESCE((SELECT SUM(ih.totalinvoiceamount) FROM invoiceheader ih INNER JOIN customermaster cm ON cm.customercode = ih.customercode AND cm.invoicepaymentterms < 2 WHERE ih.routekey = sed.routekey AND ih.voidflag = 0), 0 ) totalcashsales, 
					COALESCE((SELECT SUM(ih.totalinvoiceamount) FROM invoiceheader ih INNER JOIN customermaster cm ON cm.customercode = ih.customercode AND cm.invoicepaymentterms = 2 WHERE ih.routekey = sed.routekey AND ih.voidflag = 0), 0 ) totalgcsales,
					COALESCE((SELECT SUM(ih.totalinvoiceamount) FROM invoiceheader ih INNER JOIN customermaster cm ON cm.customercode = ih.customercode AND cm.invoicepaymentterms > 2 WHERE ih.routekey = sed.routekey AND ih.voidflag = 0), 0 ) totaltcsales,
					COALESCE((SELECT SUM(ih.totalinvoiceamount) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND ih.voidflag = 0), 0 ) totalinvoiceamount, 
					COALESCE((SELECT COUNT(arh.invoicenumber) FROM arheader arh WHERE arh.routekey = sed.routekey AND arh.amountpaid <> 0 AND arh.voidflag = 0), 0 ) totalardocuments, 
					COALESCE((SELECT SUM(arh.totalinvoiceamount) FROM arheader arh WHERE arh.routekey = sed.routekey AND arh.voidflag = 0), 0 ) totalacctsreceivable,
					COALESCE((SELECT SUM(ccd.amount) FROM cashcheckdetail ccd INNER JOIN invoiceheader ih ON ih.routekey= ccd.routekey AND ih.visitkey = ccd.visitkey AND ih.voidflag = 0 WHERE  ih.immediatepaid !=0 AND ccd.routekey = sed.routekey AND ccd.typecode = 0), 0)
					+
					COALESCE((SELECT SUM(ccd.amount) FROM cashcheckdetail ccd INNER JOIN arheader ar ON ar.routekey= ccd.routekey AND ar.visitkey = ccd.visitkey AND ar.voidflag = 0 WHERE ccd.routekey = sed.routekey AND ccd.typecode = 0), 0) totalcash,
					COALESCE((SELECT SUM(ccd.amount) FROM cashcheckdetail ccd INNER JOIN invoiceheader ih ON ih.routekey= ccd.routekey AND ih.visitkey = ccd.visitkey AND ih.voidflag = 0 WHERE ccd.routekey = sed.routekey AND ccd.typecode = 1), 0)
					+
					COALESCE((SELECT SUM(ccd.amount) FROM cashcheckdetail ccd INNER JOIN arheader ar ON ar.routekey= ccd.routekey AND ar.visitkey = ccd.visitkey AND ar.voidflag = 0 WHERE ccd.routekey = sed.routekey AND ccd.typecode = 1), 0 ) totalchecks, 
					COALESCE((SELECT SUM(soh.totalinvoiceamount) FROM salesorderheader soh WHERE soh.routekey = sed.routekey AND soh.voidflag = 0), 0 ) totalorderamount,
					sed.totalexpenses, sed.cashvariance, sed.inventoryvariance
				 FROM startendday sed, routemaster rm,salesman sm 
				 WHERE sed.routecode = rm.routecode AND sed.salesmancode = sm.salesmancode 
					  ",in_where, " ORDER BY ", in_orderby, " ",in_sort, " ",limit_val);
	
	
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyreport_routesyncstatus` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_routesyncstatus` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_routesyncstatus`(
	IN in_where TEXT,
	IN in_orderby VARCHAR(255),
	IN in_sort VARCHAR(25),
	IN in_limit INT,
	IN in_page INT
)
BEGIN
	DECLARE limit_val TEXT DEFAULT "";
	
	SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter 
				FROM startendday sed, synclog rs, routemaster rm, salesman sm
				WHERE rs.routekey = sed.routekey AND rm.routecode = rs.routecode AND sm.salesmancode = rs.userid
				 ", in_where);
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	
	SET @dyn_sql = CONCAT("SELECT sed.routekey,rs.routecode, rm.routename, rs.userid, sm.salesmanname1, DATE_FORMAT(rs.syncdate, '%d %b %Y') as syncdate1,
					rs.synctime,IF(rs.synctype = '1','UPLOAD','DOWNLOAD') as synctype, 
					IF(rs.routeclosed = '0','LIVE','CLOSED') as routeclosed
				FROM startendday sed, synclog rs, routemaster rm, salesman sm
				WHERE rs.routekey = sed.routekey AND rm.routecode = rs.routecode AND sm.salesmancode = rs.userid
				    ",in_where, " ORDER BY ", in_orderby, " ",in_sort, " ",limit_val);
	
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyreport_routesyncstatus_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_routesyncstatus_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_routesyncstatus_detail`()
BEGIN
CALL sp_combo_routemaster() ;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyreport_visit_log` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_visit_log` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_visit_log`(
IN fromdate VARCHAR(255),
IN todate VARCHAR(255),
IN divcode VARCHAR(25)
    )
BEGIN
	DECLARE div_cond VARCHAR(100) DEFAULT '';
	IF divcode  ='' THEN SET div_cond = ''; 
		ELSE SET div_cond = CONCAT(" and rm.divisioncode = '", 
			divcode, 
			"'"
			);
	END IF;
	 SET @dyn_sql1 = CONCAT(" SELECT distinct sed.routekey,l.routecode, l.salesmancode, s.salesmanname1 , 
	 l.customercode, c.customername, logstartdate, logstarttime, logenddate, logendtime , 
	 TIMEDIFF(logendtime, logstarttime) duration, 	 
	 TIMESTAMPDIFF(MINUTE, CONCAT(logstartdate, ' ', logstarttime), CONCAT(logenddate, ' ', logendtime) ) minuts
	 FROM customervisitlog l 
	 INNER JOIN startendday sed ON sed.routekey = l.routekey
	 INNER JOIN customermaster c ON l.customercode = c.customercode
	 INNER JOIN salesman s ON l.salesmancode = s.salesmancode 
	 INNER JOIN routemaster rm ON sed.`routecode` = rm.`routecode`
	 WHERE 1=1",div_cond," and sed.routestartdate BETWEEN '",fromdate,"' AND '",todate,"' 
	 and l.logstartdate <> '0000-00-00' and logenddate <> '0000-00-00'
	 ORDER BY l.logstartdate "
	 );
	
	PREPARE s1 FROM @dyn_sql1;
	
	EXECUTE s1;	
		
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyreport_wastagestock` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_wastagestock` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_wastagestock`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT,
IN in_export_status INT
)
BEGIN
	DECLARE limit_val TEXT DEFAULT "";
	DECLARE groupby_val TEXT DEFAULT "";
	SET groupby_val = CONCAT(" GROUP BY coc.primary_id ");
	IF in_export_status != 1 THEN 
		 SET groupby_val = CONCAT(" GROUP BY coc.primary_id ");
	
	
		SET @dyn_sql = CONCAT("SELECT COUNT(t1.cnt) INTO @in_counter FROM ( SELECT count(*) as cnt 
					FROM startendday sed
	INNER JOIN customeroperationscontrol coc ON coc.routekey = sed.routekey
	INNER JOIN customerinventorycheck cic ON cic.routekey = coc.routekey AND cic.visitkey = coc.visitkey
	INNER JOIN customermaster cm ON cm.customercode = coc.customercode
	INNER JOIN itemmaster im ON im.actualitemcode = cic.itemcode join routemaster rm on rm.routecode=sed.routecode where 1  ", in_where,groupby_val," ) as t1");
		PREPARE s1 FROM @dyn_sql;
		EXECUTE s1;
		
		IF in_limit != "" && in_page != "" THEN 
			CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
			SELECT @new_start_limit AS start_limit,@in_counter AS counter;
			SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
		END IF;
	END IF;
	
	
	SET @dyn_sql = CONCAT("SELECT DATE_FORMAT(coc.visitstartdate, '%d %b %Y') VisitDate, coc.visitstarttime VisitTime, cm.customercode CustomerCode,cm.alternatecode AlternateCode, cm.customername Customer,
	im.actualitemcode ItemCode, im.itemdescription Item, im.unitspercase UPC, im.caseprice CasePrice, im.defaultsalesprice UnitPrice, 
	cic.qtyloc1each Location1Qty, cic.qtyloc2each Location2Qty, cic.qtyloc3each Location3Qty, DATE_FORMAT(cic.expiry_date, '%d %b %Y') Expiry,sed.routecode,rm.routename
			       FROM startendday sed
	INNER JOIN customeroperationscontrol coc ON coc.routekey = sed.routekey
	INNER JOIN customerinventorycheck cic ON cic.routekey = coc.routekey AND cic.visitkey = coc.visitkey
	INNER JOIN customermaster cm ON cm.customercode = coc.customercode
	INNER JOIN itemmaster im ON im.actualitemcode = cic.itemcode join routemaster rm on rm.routecode=sed.routecode where 1
				    ",in_where," ",groupby_val," ORDER BY ", in_orderby, " ",in_sort, " ",limit_val);
	
	
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyrouteactivity_merchant` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyrouteactivity_merchant` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyrouteactivity_merchant`(
IN date_from VARCHAR(255),
IN date_to VARCHAR(255),
IN division VARCHAR(25)
)
BEGIN
	declare fdate varchar(100);
	declare tdate varchar(100);
	declare divcode varchar(100) default '';
	declare divcodesfa varchar(100) default '';
	set fdate = concat("DATE_SUB(CURDATE(), INTERVAL ", date_from , " DAY)");
	SET tdate = CONCAT("DATE_SUB(CURDATE(), INTERVAL ", date_to , " DAY)");
	if division <> '' then 
		set divcode = concat(" and  r.div_name= '",division, "'"); 
		SET divcodesfa = CONCAT(" and  rm.divisioncode= '",division, "'"); 
	end if;
	SET
@dyn_sql = CONCAT("
select
			visitkey,routekey,cust_erp_code customercode, cust_name customername, null arbcustomername, route_code routecode, 
			route_code routename,MERCH_CODE salesmancode, MERCH_NAME salesmanname1,  
			cust_address1 customeraddress1, cust_address2 customeraddress2, cust_address3 customeraddress3, 
			DATE_FORMAT(txndate, '%d %b %Y') visitstartdate, starttime visitstarttime, DATE_FORMAT(txndate, '%d %b %Y') visitenddate, endtime visitendtime, 			
			case when cust_erp_code is null then 'Not Serviced' else 'serviced' end visited, 
			operationtype trantype, 
			0 documentno,0 tranamount,0 salepaid,0 receiptpaid,
			TIMESTAMPDIFF(hour,strtime,stoptime) timeinhour,
			(TIMESTAMPDIFF(minute,strtime,stoptime))%60 timeinmin, 
			visitstarttime custvisitstarttime,
			visitendtime custvisitendtime, 
			TIME_FORMAT ( TIMEDIFF ( CONCAT(TXNDATE, ' ', visitendtime),
				CONCAT(TXNDATE, ' ', visitstarttime) ),
				'%H:%i:%s') custvisitdur,
			TIME_FORMAT ( TIMEDIFF ( CONCAT(TXNDATE, ' ', endtime),
				CONCAT(TXNDATE, ' ', starttime) ),
				'%H:%i:%s') activitydur,
			DATE_FORMAT(txndate, '%d %b %Y') trandate,
			null arbroutename,
			fsm_name arbsalesmanname1,
			'MER OU' divisioncode
from
	(
	select
		v.visitkey ,
		v.routekey ,
		c.cust_erp_code ,
		c.cust_name ,
		r.route_code ,
		r.ROUTE_CODE routename,
		m.MERCH_CODE ,  
		m.MERCH_NAME ,
		cust_address1 ,
		cust_address2 ,
		cust_address3 ,
		txndate,
		v.starttime visitstarttime,
		v.endtime visitendtime, 
			concat(date(txndate), ' ', visitstarttime) strtime,
		concat( date(txndate), ' ', visitendtime) stoptime,
			f.fsm_name,
		D.visitstarttime starttime,
		D.visitendtime endtime , 
		D.operationtype
	from
		merch_live.tts_merch_route_master r
	left join merch_live.tts_merch_cust_visit V on
		v.routecode = r.ROUTE_CODE
		and v.txndate between ", fdate ," and ", tdate ,"
	left join merch_live.tts_merch_cust_visit_detl D on
		V.routekey = D.routekey
		and V.visitkey = D.visitkey
		and D.visitendtime <> ''
	left join merch_live.tts_merch_merchandiser_master m on
		r.merch_code = m.MERCH_CODE
	left join merch_live.tts_merch_cust_master c on
		v.customercode = c.cust_code
	left join merch_live.tts_merch_fsm_master f on
		m.FSM_CODE = f.fsm_code
	where
		r.route_sts = 1 ", divcode ,"
) A
union 
SELECT visitkey,routekey, customercode, customername,arbcustomername, routecode, routename, salesmancode,
			salesmanname1, 
			customeraddress1, 
			customeraddress2, 
			customeraddress3, 
			activitystartdateformat, activitystarttime,activityenddateformat, activityendtime, 			
			visited,trantype, documentno, tranamount,salepaid,receiptpaid,timeinhour,timeinmin, 
			visitstarttime, visitendtime,						
			TIME_FORMAT ( TIMEDIFF ( CONCAT(visitdate,' ', visitendtime), CONCAT(visitdate,' ', visitstarttime) ), '%H:%i')  custvisitdur,
			TIME_FORMAT ( TIMEDIFF ( CONCAT(activityenddate,' ', activityendtime), CONCAT(activitystartdate,' ', activitystarttime) ), '%H:%i')  activitydur,
			trandate,arbroutename,arbsalesmanname1,divisioncode
			FROM(
		SELECT 
			vd.visitkey, 
			vd.routekey, 
			cm.alternatecode customercode, 
			cm.customername,
			cm.arbcustomername, 
			rm.routecode, 
			rm.routename, 
			sm.salesmancode,
			sm.salesmanname1, 
			cm.customeraddress1, 
			cm.customeraddress2, 
			cm.customeraddress3, 
			DATE_FORMAT(vd.visitstartdate, '%Y-%m-%d') activitystartdate, DATE_FORMAT(vd.visitstartdate, '%d %b %Y') activitystartdateformat, 
			CAST(vd.visitstarttime AS TIME) activitystarttime, 
			DATE_FORMAT(vd.visitenddate, '%Y-%m-%d') activityenddate, DATE_FORMAT(vd.visitenddate, '%d %b %Y') activityenddateformat, 
			CAST(vd.visitendtime AS TIME) activityendtime, 
			(SELECT MIN(TXNDATE) FROM tts_merch_cust_visit v WHERE v.routekey = sed.routekey AND v.customercode = vd.customercode) visitdate, 
			(SELECT MIN(starttime) FROM tts_merch_cust_visit v WHERE v.routekey = sed.routekey AND v.customercode = vd.customercode) visitstarttime, 
			(SELECT MAX(vdtl.visitendtime) FROM tts_merch_cust_visit_detl vdtl WHERE vdtl.routekey = sed.routekey AND vdtl.customercode = vd.customercode ) visitendtime,	
			-- (SELECT nsr.description FROM nosalesheader nsh, nonservreasons nsr WHERE nsh.routekey = vd.routekey AND nsh.visitkey = vd.visitkey AND nsh.nosalereasoncode = nsr.code LIMIT 1) AS visited,
			'visited' AS visited,
			vd.operationtype trantype, 
			CONCAT(vd.routekey,vd.visitkey) documentno, 
			0 tranamount, 
			0 salepaid, 
			0 receiptpaid, 
			CASE WHEN (TIMESTAMPDIFF(MINUTE,STR_TO_DATE(CONCAT(STR_TO_DATE(vd.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(vd.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 		STR_TO_DATE(CONCAT(STR_TO_DATE(vd.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(vd.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s'))) >= 60 THEN (TIMESTAMPDIFF(MINUTE,			STR_TO_DATE(CONCAT(STR_TO_DATE(vd.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(vd.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 			STR_TO_DATE(CONCAT(STR_TO_DATE(vd.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(vd.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s'))) DIV 60 ELSE 0 END timeinhour,
			(TIMESTAMPDIFF(MINUTE,STR_TO_DATE(CONCAT(STR_TO_DATE(vd.visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(vd.visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 			STR_TO_DATE(CONCAT(STR_TO_DATE(vd.visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(vd.visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s'))) % 60 AS timeinmin, 									
			DATE_FORMAT(vd.visitstartdate, '%d %b %Y') trandate,
			rm.arbroutename,
			sm.arbsalesmanname1,rm.divisioncode
		FROM 
			startendday sed
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode 
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
			-- INNER JOIN customeroperationscontrol coc ON coc.routekey = sed.routekey AND CASE WHEN SED.ROUTECODE in( 1100621, 1101323, 1101569, 1400054) THEN 1=1 ELSE  coc.reasoncode > 0	END		
			INNER JOIN tts_merch_cust_visit_detl vd ON vd.routekey = sed.routekey
			INNER JOIN customermaster cm ON cm.customercode = vd.customercode
			-- INNER JOIN tts_merch_cust_visit clg ON clg.routekey = sed.routekey AND clg.customercode = vd.customercode
		WHERE 
			1=1 ",divcodesfa,"and sed.routestartdate between ", fdate ," and ", tdate ,"
			)a
order by 6,3, 14,16	
		") ;
PREPARE s1
FROM
@dyn_sql;
EXECUTE s1;
SELECT
	@dyn_sql;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_daily_strikerate_productivity` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_daily_strikerate_productivity` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_daily_strikerate_productivity`(
IN fromdate VARCHAR(255),
IN divcode VARCHAR(25)
)
BEGIN
DECLARE limitval TEXT DEFAULT "";  
DECLARE div_cond VARCHAR(100) DEFAULT '';
DECLARE div_cond_mer VARCHAR(100) DEFAULT '';
	IF divcode  ='' THEN SET div_cond = ''; 
		ELSE SET div_cond = CONCAT(" and rm.divisioncode = '", 
			divcode, 
			"'"
			);
			SET div_cond_mer = CONCAT(" and rm.div_code = '", 
			divcode, 
			"'"
			);
	END IF;  
	
	
	  SELECT decimalplaces INTO @decimal_places FROM currencymaster WHERE defaultcurrency = 1;
	  
	  SET @dyn_sql3 = "delete from temp_strike_table_vw";
	  PREPARE s3 FROM @dyn_sql3;
	 EXECUTE s3;	
	  
	SET @dyn_sql = CONCAT("select sm.salesmanname1, sm.arbsalesmanname1, sm.alternatesalesmancode as salesmancode,
		rm.routename,rm.arbroutename, rm.alternateroutecode as routecode,
		0 as plannedcalls, 
		0 as actualcalls, 0 as unschedulecall,
		0 as cashsale, 0 as creditsale , 
		0 AS productivecalls, 
		0 as totalreceipt,
		0 as strikerate,
		0 as productiverate,
		0 as CustomerFaceTime
		 FROM startendday sed	
		LEFT JOIN routesequencecustomerstatus rcs ON rcs.routecode = sed.routecode AND rcs.routekey = sed.routekey AND  rcs.schelduledflag = 1
		LEFT JOIN routesequencecustomerstatus vis ON vis.routecode = sed.routecode AND vis.routekey = sed.routekey AND  vis.servicedflag = 1
		LEFT JOIN routesequencecustomerstatus uns ON uns.routecode = sed.routecode AND uns.routekey = sed.routekey AND  uns.servicedflag = 1 AND  uns.schelduledflag = 0
		LEFT JOIN invoiceheader ih ON ih.routekey= sed.routekey AND ih.routecode= sed.routecode AND ih.immediatepaid <> 0 and ih.voidflag = 0
		LEFT JOIN invoiceheader ihc ON ihc.routekey= sed.routekey AND ihc.routecode= sed.routecode AND ihc.immediatepaid = 0 and ihc.voidflag = 0
		INNER JOIN routemaster rm ON sed.routecode = rm.routecode
		INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
WHERE 1=1 ",div_cond," and sed.routestartdate = '",fromdate,"'
 GROUP BY sed.routecode ") ;
SET @dyn_sql2 = CONCAT("insert into temp_strike_table_vw ",@dyn_sql) ;
	 PREPARE s1 FROM @dyn_sql2;
	EXECUTE s1;
SET @dyn_sql4 = CONCAT("UPDATE temp_strike_table_vw str INNER JOIN 
(SELECT sed.salesmancode,COUNT(*) counts
	 FROM startendday sed	
	 INNER JOIN (
	SELECT rs.routekey ,COUNT(*) AS callcount FROM routesequencecustomerstatus rs INNER JOIN startendday sed1 ON rs.routekey=sed1.routekey AND sed1.routecode=rs.routecode WHERE rs.schelduledflag = 1  GROUP BY rs.routekey,rs.customercode) caltbl ON   caltbl.routekey = sed.routekey 
   	INNER JOIN routemaster rm ON sed.routecode = rm.routecode
	INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
	
	WHERE 1=1 ",div_cond," and sed.routestartdate = '",fromdate,"'
	 GROUP BY sed.salesmancode) 	temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.plannedcalls=temtbl.counts");
 PREPARE s4 FROM @dyn_sql4;
	 EXECUTE s4;
	  
	  
	  
	SET @dyn_sql6 = CONCAT("UPDATE temp_strike_table_vw str INNER JOIN 
(SELECT sed.salesmancode,COUNT(*) counts
	 FROM startendday sed	
	 INNER JOIN (
	SELECT rs.routekey ,COUNT(*) AS callcount FROM routesequencecustomerstatus rs INNER JOIN startendday sed1 ON rs.routekey=sed1.routekey AND sed1.routecode=rs.routecode WHERE rs.servicedflag = 1  GROUP BY rs.routekey,rs.customercode) caltbl ON   caltbl.routekey = sed.routekey 
   	INNER JOIN routemaster rm ON sed.routecode = rm.routecode
	INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
	
	WHERE 1=1 ",div_cond," and sed.routestartdate = '",fromdate,"'
	 GROUP BY sed.salesmancode) 	temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.actualcalls=temtbl.counts");
 PREPARE s6 FROM @dyn_sql6;
	 EXECUTE s6;  
	   
	   
	   
	SET @dyn_sql9 = CONCAT("UPDATE temp_strike_table_vw str INNER JOIN 
(SELECT sed.salesmancode,COUNT(*) counts
	 FROM startendday sed	
	 INNER JOIN (
	SELECT rs.routekey ,COUNT(*) AS callcount FROM routesequencecustomerstatus rs INNER JOIN startendday sed1 ON rs.routekey=sed1.routekey AND sed1.routecode=rs.routecode WHERE rs.servicedflag = 1  AND  rs.schelduledflag = 0 GROUP BY rs.routekey,rs.customercode) caltbl ON   caltbl.routekey = sed.routekey 
   	INNER JOIN routemaster rm ON sed.routecode = rm.routecode
	INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
	
	WHERE 1=1 ",div_cond," and sed.routestartdate = '",fromdate,"' 
	 GROUP BY sed.salesmancode) 	temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.unschedulecall=temtbl.counts");
 PREPARE s9 FROM @dyn_sql9;
	EXECUTE s9;     
	   
	   
	   
	  
	  SET @dyn_sql7 = CONCAT("UPDATE temp_strike_table_vw str INNER JOIN 
(SELECT ih.salesmancode,COUNT(*) AS counts  FROM INVOICEHEader ih 
	INNER JOIN startendday sed ON sed.routekey=ih.routekey AND sed.routecode=ih.routecode 
	INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
	WHERE  ih.immediatepaid <> 0 AND ih.voidflag = 0 ",div_cond," and sed.routestartdate = '",fromdate,"' 
	 GROUP BY ih.salesmancode) 	temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.cashsale=temtbl.counts");
 PREPARE s7 FROM @dyn_sql7;
	  -- EXECUTE s7; 
	  
	   SET @dyn_sql8 = CONCAT("UPDATE temp_strike_table_vw str INNER JOIN 
(	 SELECT ih.salesmancode,COUNT(*) AS counts  FROM INVOICEHEader ih 
	INNER JOIN startendday sed ON sed.routekey=ih.routekey AND sed.routecode=ih.routecode 
	INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
	WHERE  ih.immediatepaid =0 AND ih.voidflag = 0 ",div_cond," and sed.routestartdate = '",fromdate,"' 
	 GROUP BY ih.salesmancode ) temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.creditsale=temtbl.counts");
 PREPARE s8 FROM @dyn_sql8;
	EXECUTE s8; 
	 
	  
	  
	  SET @dyn_sql10 = CONCAT("UPDATE temp_strike_table_vw str INNER JOIN 
(	 SELECT ah.salesmancode,COUNT(*) AS counts  FROM arheader ah 
	INNER JOIN startendday sed ON ah.routekey= sed.routekey AND ah.routecode= sed.routecode 
	INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
	WHERE  1=1  ",div_cond," and sed.routestartdate = '",fromdate,"'
	 GROUP BY ah.salesmancode ) temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.totalreceipt=temtbl.counts");
 PREPARE s10 FROM @dyn_sql10;
	 EXECUTE s10;  
	  
	  
 
	 SET @dyn_sql11 = CONCAT("UPDATE temp_strike_table_vw str INNER JOIN 
(	 SELECT coc.salesmancode,COUNT(distinct customercode) AS counts  FROM customeroperationscontrol coc 
	INNER JOIN startendday sed ON coc.routecode = sed.routecode and coc.routekey = sed.routekey
	INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
	WHERE  totaltransactions >0 
		-- and coc.primary_id not in (
		-- select primary_id from customeroperationscontrol c join arheader a on c.routekey = a.routekey and c.visitkey = a.visitkey 
		-- where c.routekey  = coc.routekey 
		-- )
	 ",div_cond," and sed.routestartdate = '",fromdate,"'
	  GROUP BY coc.salesmancode ) temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.productivecalls=temtbl.counts");
 PREPARE s11 FROM @dyn_sql11;
	EXECUTE s11;  
 
	  
	  
	  
	  SET @dyn_sql12 = CONCAT("UPDATE temp_strike_table_vw str INNER JOIN 
(	 SELECT salesmancode,(((actualcalls)/plannedcalls)*100) as strikerate from  temp_strike_table_vw ) temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.strikerate=ROUND(temtbl.strikerate)");
 PREPARE s12 FROM @dyn_sql12;
	 EXECUTE s12;  
	  
	 SET @dyn_sql13 = CONCAT("UPDATE temp_strike_table_vw str INNER JOIN 
(	 SELECT salesmancode,((productivecalls)/(plannedcalls)*100) as productiverate from  temp_strike_table_vw ) temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.productiverate=ROUND(temtbl.productiverate)");
 PREPARE s13 FROM @dyn_sql13;
	EXECUTE s13;  
	  
	SET @dyn_sql14 = CONCAT("UPDATE temp_strike_table_vw str INNER JOIN 
	(
		select salesmancode, sum(TIMESTAMPDIFF(minute,strt, endt)) TotalMinutesSpend from
		(
			select distinct c.salesmancode, concat(logstartdate ,' ', logstarttime) strt, concat(logenddate ,' ', logendtime) endt from customervisitlog c 
			inner join startendday sed on sed.routekey=c.routekey
			WHERE 1=1 ",div_cond," and sed.routestartdate = '",fromdate,"' 
		) a GROUP BY salesmancode
	) 
	temtbl ON str.salesmancode=temtbl.salesmancode
	SET str.CustomerFaceTime=temtbl.TotalMinutesSpend");
	-- Select @dyn_sql14;
	PREPARE s14 FROM @dyn_sql14;
	 EXECUTE s14; 
	  
	  
	--   SELECT @dyn_sql2; Select @dyn_sql4; Select @dyn_sql6; Select @dyn_sql7; Select @dyn_sql8; Select @dyn_sql9; Select @dyn_sql10; Select @dyn_sql11; Select @dyn_sql12; Select  @dyn_sql13; Select @dyn_sql14;
	
	set @dyn_sql15 = concat("
	INSERT INTO temp_strike_table_vw
	SELECT
	merch_name,
	fsm_name,
	salesmancode,
	routecode,
	routecode,
	routecode,
	planned,
	serviced,
	unplanned,
	cashsale,
	creditsale,
	productive,
	receipts,
	serviced / planned * 100 strikerate,
	productive / planned * 100 productiverate,
	facetime
FROM
	(
	SELECT
		routecode,
		salesmancode,
		merch_name,
		f.fsm_name,
		(
		SELECT
			COUNT(DISTINCT jp_cust_code)
		FROM
			merch_live.tts_merch_journey_plan jp
		WHERE
			jp.jp_date = (DATE_SUB(CURDATE(), INTERVAL 1 DAY))
			AND jp_routecode = routecode
			AND jp_planned_yn = 1 ) planned,
		(
		SELECT
			COUNT(DISTINCT jp_cust_code)
		FROM
			merch_live.tts_merch_journey_plan jp
		WHERE
			jp.jp_date = (DATE_SUB(CURDATE(), INTERVAL 1 DAY))
			AND jp_routecode = routecode
			AND jp_serviced_yn = 1 ) serviced,
		(
		SELECT
			COUNT(DISTINCT jp_cust_code)
		FROM
			merch_live.tts_merch_journey_plan jp
		WHERE
			jp.jp_date = (DATE_SUB(CURDATE(), INTERVAL 1 DAY))
			AND jp_routecode = routecode
			AND jp_planned_yn = 0
			AND jp_serviced_yn = 1 ) unplanned,
		0 cashsale,
		0 creditsale,
		(
		SELECT
			COUNT(DISTINCT customercode)
		FROM
			merch_live.tts_merch_cust_visit_detl d
		WHERE
			visitstartdate = (DATE_SUB(CURDATE(), INTERVAL 1 DAY))
			AND d.routecode = tmr.routecode) productive,
			(
				SELECT 
				SUM(TIMESTAMPDIFF(MINUTE, CONCAT(txndate, ' ', starttime), CONCAT(txndate, ' ', endtime) )) 
				FROM
					merch_live.tts_merch_cust_visit v
				WHERE
				txndate = (DATE_SUB(CURDATE(), INTERVAL 1 DAY))
				AND v.routecode = tmr.routecode
			) facetime,
		0 receipts
	FROM
		merch_live.tts_merch_routekey tmr
	INNER JOIN merch_live.tts_merch_merchandiser_master m ON
		tmr.salesmancode = m.MERCH_CODE
	INNER JOIN merch_live.tts_merch_fsm_master f ON
		m.FSM_CODE = f.fsm_code
	inner join merch_live.tts_merch_route_master rm on tmr.routecode = rm.route_code
	WHERE
		1=1 ",div_cond_mer," and tmr.routestartdate = ",fromdate,"
) a ");
	  PREPARE s15 FROM @dyn_sql15;
	 EXECUTE s15; 
	 
SET @dyn_sql5 = "select * from temp_strike_table_vw";
 PREPARE s5 FROM @dyn_sql5;
	 EXECUTE s5;
	  
END */$$
DELIMITER ;

