BEGIN
CALL sp_combo_routemaster() ;
	CALL sp_combo_itemmaster();
	CALL sp_combo_majorcategory();
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_distributioncheck_distributionchechsummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_distributioncheck_distributionchechsummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_distributioncheck_distributionchechsummary`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
DECLARE limitval TEXT DEFAULT "";
 SET @dyn_sql = CONCAT("SELECT COUNT(DISTINCT CONCAT(coc.routekey,coc.visitkey,rmast.routename,coc.visitstarttime,im.alternatecode)) INTO @in_counter				
				FROM customeroperationscontrol coc
				  JOIN `customerinventorycheck` cid
				    ON cid.routekey = coc.routekey
				      AND cid.visitkey = coc.visitkey
				  LEFT JOIN itemmaster im
				    ON im.actualitemcode = cid.itemcode
				  LEFT JOIN distributioncheckdetail dcd
				    ON dcd.itemcode = cid.itemcode
				  LEFT JOIN startendday sed
				    ON sed.routekey = coc.routekey
				      AND sed.routecode = coc.routecode
				   LEFT JOIN routemaster rmast 
				    ON rmast.routecode = coc.routecode
				WHERE 1 = 1
				",in_where, "");
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN
		SET @limitval = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	 CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
	
	  SELECT @new_start_limit AS start_limit,@in_counter AS counter;
	
	SET @dyn_sql = CONCAT("SELECT DISTINCT				
				coc.routecode,
				rmast.routename,
				coc.visitstarttime,  
				  im.alternatecode,
				  im.itemdescription,
				  FORMAT(im.defaultsalesprice,2) AS defaultsalesprice,
				  FORMAT(im.caseprice,2) AS caseprice,
				  dcd.cutoff_qty,
				  dcd.max_qty,
				  CONCAT(FLOOR(cid.qtyloc1each/im.unitspercase),'/',cid.qtyloc1each%im.unitspercase)    location1,
				  CONCAT(FLOOR(cid.qtyloc2each/im.unitspercase),'/',cid.qtyloc2each%im.unitspercase)    location2,
				  im.unitspercase,
				  DATE_FORMAT(cid.expiry_date,'%d-%m-%Y') AS expiry_date
				FROM customeroperationscontrol coc
				  JOIN `customerinventorycheck` cid
				    ON cid.routekey = coc.routekey
				      AND cid.visitkey = coc.visitkey
				  LEFT JOIN itemmaster im
				    ON im.actualitemcode = cid.itemcode
				  LEFT JOIN distributioncheckdetail dcd
				    ON dcd.itemcode = cid.itemcode
				  LEFT JOIN startendday sed
				    ON sed.routekey = coc.routekey
				      AND sed.routecode = coc.routecode
				   LEFT JOIN routemaster rmast 
				    ON rmast.routecode = coc.routecode
				WHERE 1 = 1
				",in_where, " ORDER BY ",in_orderby," ",in_sort,", actualitemcode ASC ",limitval);
	
	 PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	 
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_division_salesreport` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_division_salesreport` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_division_salesreport`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit VARCHAR(25),
IN in_page VARCHAR(25),
IN in_type VARCHAR(25)
)
BEGIN
	IF in_type = 1 THEN 
	SET @dyn_sql = CONCAT("SELECT sum(cnt) INTO @in_counter FROM (SELECT 
			count( *)  as cnt 
				FROM 
				InvoiceHeader IH, InvoiceDetail ID, CustomerMaster CM, RouteMaster RM, Salesman SM, ItemMaster IM
				WHERE 
			IH.RouteKey = ID.RouteKey AND IH.VisitKey = ID.VisitKey AND 
			IH.RouteCode = RM.RouteCode AND IH.CustomerCode = CM.CustomerCode AND ID.ItemCode = IM.ActualItemCode AND
			IH.SalesmanCode = SM.SalesmanCode AND ID.SalesQty + ID.FreeSampleQty + ID.ManualFreeQty > 0 AND IH.VoidFlag = 0 ",in_where,"  
		UNION ALL
		SELECT 
			count( *) as cnt
		FROM 
		SalesorderHeader IH, salesorderDetail ID, CustomerMaster CM, RouteMaster RM, Salesman SM, ItemMaster IM
		WHERE 
			IH.RouteKey = ID.RouteKey AND IH.VisitKey = ID.VisitKey AND 
			IH.RouteCode = RM.RouteCode AND IH.CustomerCode = CM.CustomerCode AND ID.ItemCode = IM.ActualItemCode AND
			IH.SalesmanCode = SM.SalesmanCode AND ID.ReturnQty + ID.DamagedQty  > 0 AND IH.VoidFlag = 0 ",in_where,") AS t1");
	 
	ELSEIF in_type = 2 THEN
	 SET @dyn_sql = CONCAT("SELECT sum(cnt) INTO @in_counter FROM (SELECT  count( *)  as cnt 
		FROM 
		InvoiceHeader IH, InvoiceDetail ID, CustomerMaster CM, RouteMaster RM, ItemMaster IM, Salesman SM
	WHERE 
		IH.RouteKey = ID.RouteKey AND IH.VisitKey = ID.VisitKey AND 
		IH.RouteCode = RM.RouteCode AND IH.CustomerCode = CM.CustomerCode AND ID.ItemCode = IM.ActualItemCode AND
		IH.SalesmanCode = SM.SalesmanCode AND ID.SalesQty > 0 AND IH.VoidFlag = 0 ",in_where,"
	
	UNION ALL
	
	SELECT 
		count( *)  as cnt 
	FROM 
		SalesorderHeader IH, SalesorderDetail ID, CustomerMaster CM, RouteMaster RM, ItemMaster IM, Salesman SM
	WHERE 
		IH.RouteKey = ID.RouteKey AND IH.VisitKey = ID.VisitKey AND 
		IH.RouteCode = RM.RouteCode AND IH.CustomerCode = CM.CustomerCode AND ID.ItemCode = IM.ActualItemCode AND
		IH.SalesmanCode = SM.SalesmanCode AND ID.ReturnQty + ID.DamagedQty  > 0 AND IH.VoidFlag = 0 ",in_where," ) AS t1 ");
					
	 END IF;
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	IF in_limit != "" && in_page != "" THEN
		CALL sp_report_calculate_paging_data(@in_counter,in_limit,in_page,@new_start_limit);
		IF @new_start_limit < 0 THEN  SET @new_start_limit = 0; END IF;
		SET @limitval = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
	ELSE
		SET @limitval = "";
	END IF;	
	IF in_type = 1 THEN 
		SET @dyn_sql = CONCAT("SELECT 
			RM.AlternateRouteCode RouteCode, RM.RouteName RouteName, SM.AlternateSalesmanCode SalesmanCode, SM.SalesmanName1 SalesmanName, 
			REPLACE(CM.AlternateCode,'-','') CustomerCode, CM.CustomerName Customer, CM.Region Channel, IH.InvoiceNumber InvoiceNumber, IH.ActualTransactionDate InvoiceDate,
			CASE WHEN ID.ReturnQty > 0 THEN 'RETURN' ELSE (CASE WHEN CM.InvoicePaymentTerms < 2 THEN 'CASH' WHEN CM.InvoicePaymentTerms = 2 THEN 'CREDIT' ELSE 'TC' END) END as  InvoiceType,IM.AlternateCode ItemCode, 
			IM.ItemDescription ItemDescription, CASE WHEN ID.ReturnQty > 0  THEN ID.ReturnQty * -1 ELSE ID.SalesQty END SalesQuantity, (ID.FreeSampleQty + ID.ManualFreeQty) FreeQuantity,
			(ID.SalesQty + ID.FreeSampleQty + ID.ManualFreeQty + ID.ReturnQty*-1) NetQuantity, CM.Grouping_Code GroupingCode, CM.Outlet_Quality OutletQuality
				FROM 
				InvoiceHeader IH, InvoiceDetail ID, CustomerMaster CM, RouteMaster RM, Salesman SM, ItemMaster IM
				WHERE 
			IH.RouteKey = ID.RouteKey AND IH.VisitKey = ID.VisitKey AND 
			IH.RouteCode = RM.RouteCode AND IH.CustomerCode = CM.CustomerCode AND ID.ItemCode = IM.ActualItemCode AND
			IH.SalesmanCode = SM.SalesmanCode AND ID.SalesQty + ID.FreeSampleQty + ID.ManualFreeQty + ID.ReturnQty > 0 AND IH.VoidFlag = 0 ",in_where,"  
		UNION ALL
		SELECT 
			RM.AlternateRouteCode RouteCode, RM.RouteName RouteName, SM.AlternateSalesmanCode SalesmanCode, SM.SalesmanName1 SalesmanName, 	
			REPLACE(CM.AlternateCode,'-','') CustomerCode, CM.CustomerName Customer, CM.Region Channel, IH.InvoiceNumber InvoiceNumber, 
			IH.ActualTransactionDate InvoiceDate,'RETURN' InvoiceType, IM.AlternateCode ItemCode, IM.ItemDescription ItemDescription, 
			(ID.ReturnQty + ID.DamagedQty ) * -1 SalesQuantity,0 as FreeQuantity, 
			(ID.ReturnQty + ID.DamagedQty ) * -1 NetQuantity,CM.Grouping_Code GroupingCode, CM.Outlet_Quality OutletQuality
		FROM 
		SalesorderHeader IH, SalesorderDetail ID, CustomerMaster CM, RouteMaster RM, Salesman SM, ItemMaster IM
		WHERE 
			IH.RouteKey = ID.RouteKey AND IH.VisitKey = ID.VisitKey AND 
			IH.RouteCode = RM.RouteCode AND IH.CustomerCode = CM.CustomerCode AND ID.ItemCode = IM.ActualItemCode AND
			IH.SalesmanCode = SM.SalesmanCode AND ID.ReturnQty + ID.DamagedQty  > 0 AND IH.VoidFlag = 0 ",in_where," ",@limitval);
		
	ELSEIF in_type = 2 THEN
	 SET @dyn_sql = CONCAT("SELECT 
		RM.AlternateRouteCode RouteCode, RM.RouteName RouteName, SM.AlternateSalesmanCode SalesmanCode, SM.SalesmanName1 SalesmanName, 
			REPLACE(CM.AlternateCode,'-','') CustomerCode, CM.CustomerName Customer, CM.Region Channel, IH.InvoiceNumber InvoiceNumber, IH.ActualTransactionDate InvoiceDate,
			CASE WHEN CM.InvoicePaymentTerms < 2 THEN 'CASH' WHEN CM.InvoicePaymentTerms = 2 THEN 'CREDIT' ELSE 'TC' END InvoiceType,IM.AlternateCode ItemCode, 
			IM.ItemDescription ItemDescription, FORMAT((((FLOOR(salesqty/IM.unitspercase)*ID.salescaseprice)+((salesqty%IM.unitspercase)*ID.salesprice))-((FLOOR(returnqty/IM.unitspercase)*ID.returncaseprice)+((returnqty%IM.unitspercase)*ID.returnprice))-((FLOOR(damagedqty/IM.unitspercase)*ID.returncaseprice)+((damagedqty%IM.unitspercase)*ID.returnprice))-promoamount),3) AS SalesQuantity, 0 as FreeQuantity, 0 as NetQuantity, CM.Grouping_Code GroupingCode, CM.Outlet_Quality OutletQuality
		
	FROM 
		InvoiceHeader IH, InvoiceDetail ID, CustomerMaster CM, RouteMaster RM, ItemMaster IM, Salesman SM
	WHERE 
		IH.RouteKey = ID.RouteKey AND IH.VisitKey = ID.VisitKey AND 
		IH.RouteCode = RM.RouteCode AND IH.CustomerCode = CM.CustomerCode AND ID.ItemCode = IM.ActualItemCode AND
		IH.SalesmanCode = SM.SalesmanCode AND ID.SalesQty > 0 AND IH.VoidFlag = 0 ",in_where,"
	
	UNION ALL
	
	SELECT 
			RM.AlternateRouteCode RouteCode, RM.RouteName RouteName, SM.AlternateSalesmanCode SalesmanCode, SM.SalesmanName1 SalesmanName, 	
			REPLACE(CM.AlternateCode,'-','') CustomerCode, CM.CustomerName Customer, CM.Region Channel, IH.InvoiceNumber InvoiceNumber, 
			IH.ActualTransactionDate InvoiceDate,'RETURN' InvoiceType, IM.AlternateCode ItemCode, IM.ItemDescription ItemDescription, 
			FORMAT(((FLOOR(salesqty/IM.unitspercase)*ID.salescaseprice)+((salesqty%IM.unitspercase)*ID.salesprice))-((FLOOR(returnqty/IM.unitspercase)*ID.returncaseprice+((returnqty%IM.unitspercase)*ID.returnprice))-((FLOOR(damagedqty/IM.unitspercase)*ID.returncaseprice)+((damagedqty%IM.unitspercase)*ID.returnprice))-promoamount),3) SalesQuantity, 0 FreeQuantity, 
			0 NetQuantity,CM.Grouping_Code GroupingCode, CM.Outlet_Quality OutletQuality
	FROM 
		SalesorderHeader IH, salesorderDetail ID, CustomerMaster CM, RouteMaster RM, ItemMaster IM, Salesman SM
	WHERE 
		IH.RouteKey = ID.RouteKey AND IH.VisitKey = ID.VisitKey AND 
		IH.RouteCode = RM.RouteCode AND IH.CustomerCode = CM.CustomerCode AND ID.ItemCode = IM.ActualItemCode AND
		IH.SalesmanCode = SM.SalesmanCode AND ID.ReturnQty + ID.DamagedQty  > 0 AND IH.VoidFlag = 0 ",in_where,"  ",@limitval
	);
					
	 END IF;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
SELECT @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_division_salesreport_031018` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_division_salesreport_031018` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_division_salesreport_031018`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit VARCHAR(25),
IN in_page VARCHAR(25),
IN in_type VARCHAR(25)
)
BEGIN
	IF in_type = 1 THEN 
	SET @dyn_sql = CONCAT("SELECT sum(cnt) INTO @in_counter FROM (SELECT 
			count( *)  as cnt 
				FROM 
				InvoiceHeader IH, InvoiceDetail ID, CustomerMaster CM, RouteMaster RM, Salesman SM, ItemMaster IM
				WHERE 
			IH.RouteKey = ID.RouteKey AND IH.VisitKey = ID.VisitKey AND 
			IH.RouteCode = RM.RouteCode AND IH.CustomerCode = CM.CustomerCode AND ID.ItemCode = IM.ActualItemCode AND
			IH.SalesmanCode = SM.SalesmanCode AND ID.SalesQty + ID.FreeSampleQty + ID.ManualFreeQty > 0 AND IH.VoidFlag = 0 ",in_where,"  
		UNION ALL
		SELECT 
			count( *) as cnt
		FROM 
		InvoiceHeader IH, InvoiceDetail ID, CustomerMaster CM, RouteMaster RM, Salesman SM, ItemMaster IM
		WHERE 
			IH.RouteKey = ID.RouteKey AND IH.VisitKey = ID.VisitKey AND 
			IH.RouteCode = RM.RouteCode AND IH.CustomerCode = CM.CustomerCode AND ID.ItemCode = IM.ActualItemCode AND
			IH.SalesmanCode = SM.SalesmanCode AND ID.ReturnQty + ID.DamagedQty + ID.ExpiryQty > 0 AND IH.VoidFlag = 0 ",in_where,") AS t1");
	 
	ELSEIF in_type = 2 THEN
	 SET @dyn_sql = CONCAT("SELECT sum(cnt) INTO @in_counter FROM (SELECT  count( *)  as cnt 
		FROM 
		InvoiceHeader IH, InvoiceDetail ID, CustomerMaster CM, RouteMaster RM, ItemMaster IM, Salesman SM
	WHERE 
		IH.RouteKey = ID.RouteKey AND IH.VisitKey = ID.VisitKey AND 
		IH.RouteCode = RM.RouteCode AND IH.CustomerCode = CM.CustomerCode AND ID.ItemCode = IM.ActualItemCode AND
		IH.SalesmanCode = SM.SalesmanCode AND ID.SalesQty > 0 AND IH.VoidFlag = 0 ",in_where,"
	
	UNION ALL
	
	SELECT 
		count( *)  as cnt 
	FROM 
		InvoiceHeader IH, InvoiceDetail ID, CustomerMaster CM, RouteMaster RM, ItemMaster IM, Salesman SM
	WHERE 
		IH.RouteKey = ID.RouteKey AND IH.VisitKey = ID.VisitKey AND 
		IH.RouteCode = RM.RouteCode AND IH.CustomerCode = CM.CustomerCode AND ID.ItemCode = IM.ActualItemCode AND
		IH.SalesmanCode = SM.SalesmanCode AND ID.ReturnQty + ID.DamagedQty + ID.ExpiryQty > 0 AND IH.VoidFlag = 0 ",in_where," ) AS t1 ");
					
	 END IF;
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	IF in_limit != "" && in_page != "" THEN
		CALL sp_report_calculate_paging_data(@in_counter,in_limit,in_page,@new_start_limit);
		IF @new_start_limit < 0 THEN  SET @new_start_limit = 0; END IF;
		SET @limitval = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
	ELSE
		SET @limitval = "";
	END IF;	
	IF in_type = 1 THEN 
		SET @dyn_sql = CONCAT("SELECT 
			RM.AlternateRouteCode RouteCode, RM.RouteName RouteName, SM.AlternateSalesmanCode SalesmanCode, SM.SalesmanName1 SalesmanName, 
			REPLACE(CM.AlternateCode,'-','') CustomerCode, CM.CustomerName Customer, CM.Region Channel, IH.InvoiceNumber InvoiceNumber, IH.ActualTransactionDate InvoiceDate,
			CASE WHEN CM.InvoicePaymentTerms < 2 THEN 'CASH' WHEN CM.InvoicePaymentTerms = 2 THEN 'CREDIT' ELSE 'TC' END InvoiceType,IM.AlternateCode ItemCode, 
			IM.ItemDescription ItemDescription, ID.SalesQty SalesQuantity, (ID.FreeSampleQty + ID.ManualFreeQty) FreeQuantity,
			(ID.SalesQty + ID.FreeSampleQty + ID.ManualFreeQty) NetQuantity, CM.Grouping_Code GroupingCode, CM.Outlet_Quality OutletQuality
				FROM 
				InvoiceHeader IH, InvoiceDetail ID, CustomerMaster CM, RouteMaster RM, Salesman SM, ItemMaster IM
				WHERE 
			IH.RouteKey = ID.RouteKey AND IH.VisitKey = ID.VisitKey AND 
			IH.RouteCode = RM.RouteCode AND IH.CustomerCode = CM.CustomerCode AND ID.ItemCode = IM.ActualItemCode AND
			IH.SalesmanCode = SM.SalesmanCode AND ID.SalesQty + ID.FreeSampleQty + ID.ManualFreeQty > 0 AND IH.VoidFlag = 0 ",in_where,"  
		UNION ALL
		SELECT 
			RM.AlternateRouteCode RouteCode, RM.RouteName RouteName, SM.AlternateSalesmanCode SalesmanCode, SM.SalesmanName1 SalesmanName, 	
			REPLACE(CM.AlternateCode,'-','') CustomerCode, CM.CustomerName Customer, CM.Region Channel, IH.InvoiceNumber InvoiceNumber, 
			IH.ActualTransactionDate InvoiceDate,'RETURN' InvoiceType, IM.AlternateCode ItemCode, IM.ItemDescription ItemDescription, 
			(ID.ReturnQty + ID.DamagedQty + ID.ExpiryQty) * -1 SalesQuantity, ID.ReturnFreeQty * -1 FreeQuantity, 
			(ID.ReturnQty + ID.DamagedQty + ID.ExpiryQty+ID.ReturnFreeQty) * -1 NetQuantity,CM.Grouping_Code GroupingCode, CM.Outlet_Quality OutletQuality
		FROM 
		InvoiceHeader IH, InvoiceDetail ID, CustomerMaster CM, RouteMaster RM, Salesman SM, ItemMaster IM
		WHERE 
			IH.RouteKey = ID.RouteKey AND IH.VisitKey = ID.VisitKey AND 
			IH.RouteCode = RM.RouteCode AND IH.CustomerCode = CM.CustomerCode AND ID.ItemCode = IM.ActualItemCode AND
			IH.SalesmanCode = SM.SalesmanCode AND ID.ReturnQty + ID.DamagedQty + ID.ExpiryQty > 0 AND IH.VoidFlag = 0 ",in_where," ",@limitval);
		
	ELSEIF in_type = 2 THEN
	 SET @dyn_sql = CONCAT("SELECT 
		RM.AlternateRouteCode RouteCode, RM.RouteName RouteName, SM.AlternateSalesmanCode SalesmanCode, SM.SalesmanName1 SalesmanName, 
			REPLACE(CM.AlternateCode,'-','') CustomerCode, CM.CustomerName Customer, CM.Region Channel, IH.InvoiceNumber InvoiceNumber, IH.ActualTransactionDate InvoiceDate,
			CASE WHEN CM.InvoicePaymentTerms < 2 THEN 'CASH' WHEN CM.InvoicePaymentTerms = 2 THEN 'CREDIT' ELSE 'TC' END InvoiceType,IM.AlternateCode ItemCode, 
			IM.ItemDescription ItemDescription, 
		((ID.SalesQty/IM.UnitsPerCase) * ID.SalesCasePrice  + 
			(CASE WHEN ID.SalesQty % IM.UnitsPerCase <> 0 THEN (ID.SalesQty % IM.UnitsPerCase) * ID.SalesPrice ELSE 0 END) - COALESCE(ID.PromoValue, 0)) AS SalesQuantity, 0 as FreeQuantity, 0 as NetQuantity, CM.Grouping_Code GroupingCode, CM.Outlet_Quality OutletQuality
		
	FROM 
		InvoiceHeader IH, InvoiceDetail ID, CustomerMaster CM, RouteMaster RM, ItemMaster IM, Salesman SM
	WHERE 
		IH.RouteKey = ID.RouteKey AND IH.VisitKey = ID.VisitKey AND 
		IH.RouteCode = RM.RouteCode AND IH.CustomerCode = CM.CustomerCode AND ID.ItemCode = IM.ActualItemCode AND
		IH.SalesmanCode = SM.SalesmanCode AND ID.SalesQty > 0 AND IH.VoidFlag = 0 ",in_where,"
	
	UNION ALL
	
	SELECT 
			RM.AlternateRouteCode RouteCode, RM.RouteName RouteName, SM.AlternateSalesmanCode SalesmanCode, SM.SalesmanName1 SalesmanName, 	
			REPLACE(CM.AlternateCode,'-','') CustomerCode, CM.CustomerName Customer, CM.Region Channel, IH.InvoiceNumber InvoiceNumber, 
			IH.ActualTransactionDate InvoiceDate,'RETURN' InvoiceType, IM.AlternateCode ItemCode, IM.ItemDescription ItemDescription, 
			(((((ID.ReturnQty + ID.DamagedQty + ID.ExpiryQty)/IM.UnitsPerCase) * ID.ReturnCasePrice) + 
			(CASE WHEN (ID.ReturnQty + ID.DamagedQty + ID.ExpiryQty) % IM.UnitsPerCase <> 0 THEN ((ID.ReturnQty + ID.DamagedQty + ID.ExpiryQty) % IM.UnitsPerCase) * ID.ReturnPrice ELSE 0 END)) * -1) SalesQuantity, 0 FreeQuantity, 
			0 NetQuantity,CM.Grouping_Code GroupingCode, CM.Outlet_Quality OutletQuality
	FROM 
		InvoiceHeader IH, InvoiceDetail ID, CustomerMaster CM, RouteMaster RM, ItemMaster IM, Salesman SM
	WHERE 
		IH.RouteKey = ID.RouteKey AND IH.VisitKey = ID.VisitKey AND 
		IH.RouteCode = RM.RouteCode AND IH.CustomerCode = CM.CustomerCode AND ID.ItemCode = IM.ActualItemCode AND
		IH.SalesmanCode = SM.SalesmanCode AND ID.ReturnQty + ID.DamagedQty + ID.ExpiryQty > 0 AND IH.VoidFlag = 0 ",in_where,"  ",@limitval
	);
					
	 END IF;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
SELECT @dyn_sql;
    END */$$
DELIMITER ;

