INNER JOIN routemaster rm ON rm.routecode = soh.routecode
INNER JOIN salesman sm ON sm.salesmancode = rm.salesmancode
INNER JOIN itemmaster im ON im.actualitemcode = imd.itemcode
 WHERE 1=1   ", in_where
 );
	SET @dyn_sql = CONCAT(
"SELECT count(*) INTO @in_counter  from 
(
SELECT DISTINCT rm.alternateroutecode as route, sm.salesmanname1 as salesman, cm.alternatecode as customer, cm.customername,im.alternatecode as itemcode,
im.itemshortdescription, IFNULL(FLOOR(cid.qtyloc1each/im.unitspercase),0) as shelfcases,IFNULL((cid.qtyloc1each%im.unitspercase),0) as shelfpcs,salesqty, DATE_FORMAT(transactiondate,'%d-%m-%Y') AS transactiondate,cm.transaction_anals3 as categoryname
FROM itemmustdetail imd 
INNER JOIN customermaster cm ON imd.itemmustcode = cm.itemmustkey AND cm.itemmustkey IS NOT NULL
INNER JOIN salesorderheader soh ON cm.customercode = soh.customercode
INNER JOIN customerinventorydetail cid ON cid.routekey = soh.routekey AND cid.visitkey = soh.visitkey 
LEFT JOIN salesorderdetail sod ON sod.routekey = soh.routekey AND sod.visitkey = soh.visitkey and sod.itemcode= cid.itemcode
INNER JOIN routemaster rm ON rm.routecode = soh.routecode
INNER JOIN salesman sm ON sm.salesmancode = rm.salesmancode
INNER JOIN itemmaster im ON im.actualitemcode = imd.itemcode
 WHERE 1=1    ",in_where," 
union all
SELECT DISTINCT rm.alternateroutecode as route, sm.salesmanname1 as salesman, cm.alternatecode as customer, cm.customername,im.alternatecode as itemcode,
im.itemshortdescription, IFNULL(FLOOR(cid.qtyloc1each/im.unitspercase),0) as shelfcases,IFNULL((cid.qtyloc1each%im.unitspercase),0) as shelfpcs,salesqty, DATE_FORMAT(transactiondate,'%d-%m-%Y') AS transactiondate,cm.transaction_anals3 as categoryname
FROM itemmustdetail imd 
INNER JOIN customermaster cm ON imd.itemmustcode = cm.itemmustkey AND cm.itemmustkey IS NOT NULL
INNER JOIN invoiceheader soh ON cm.customercode = soh.customercode
INNER JOIN customerinventorydetail cid ON cid.routekey = soh.routekey AND cid.visitkey = soh.visitkey 
LEFT JOIN invoicedetail sod ON sod.routekey = soh.routekey AND sod.visitkey = soh.visitkey and sod.itemcode= cid.itemcode
INNER JOIN routemaster rm ON rm.routecode = soh.routecode
INNER JOIN salesman sm ON sm.salesmancode = rm.salesmancode
INNER JOIN itemmaster im ON im.actualitemcode = imd.itemcode
 WHERE 1=1    ",in_where," 
 ) a "
 	
	);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN
		CALL sp_report_calculate_paging_data(@in_counter,in_limit,in_page,@new_start_limit);
		IF @new_start_limit < 0 THEN  SET @new_start_limit = 0; END IF;
		SET @limitval = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	ELSE
		SET @limitval = CONCAT(" LIMIT 0,",@in_counter);
	END IF;
	  SELECT @new_start_limit AS start_limit,@in_counter AS counter;
	  SELECT decimalplaces INTO @decimal_places FROM currencymaster WHERE defaultcurrency = 1;
	  
	SET @dyn_sql = CONCAT("SELECT DISTINCT rm.alternateroutecode as route, sm.salesmanname1 as salesman, cm.alternatecode as customer, cm.customername,im.alternatecode as itemcode,
im.itemshortdescription, IFNULL(FLOOR(cid.qtyloc1each/im.unitspercase),0) as shelfcases,IFNULL((cid.qtyloc1each%im.unitspercase),0) as shelfpcs,salesqty, DATE_FORMAT(transactiondate,'%d-%m-%Y') AS transactiondate,cm.transaction_anals3 as categoryname
FROM itemmustdetail imd 
INNER JOIN customermaster cm ON imd.itemmustcode = cm.itemmustkey AND cm.itemmustkey IS NOT NULL
INNER JOIN salesorderheader soh ON cm.customercode = soh.customercode
INNER JOIN customerinventorydetail cid ON cid.routekey = soh.routekey AND cid.visitkey = soh.visitkey 
LEFT JOIN salesorderdetail sod ON sod.routekey = soh.routekey AND sod.visitkey = soh.visitkey and sod.itemcode= cid.itemcode
INNER JOIN routemaster rm ON rm.routecode = soh.routecode
INNER JOIN salesman sm ON sm.salesmancode = rm.salesmancode
INNER JOIN itemmaster im ON im.actualitemcode = imd.itemcode
 WHERE 1=1    ",in_where," 
union all
SELECT DISTINCT rm.alternateroutecode as route, sm.salesmanname1 as salesman, cm.alternatecode as customer, cm.customername,im.alternatecode as itemcode,
im.itemshortdescription, IFNULL(FLOOR(cid.qtyloc1each/im.unitspercase),0) as shelfcases,IFNULL((cid.qtyloc1each%im.unitspercase),0) as shelfpcs,salesqty, DATE_FORMAT(transactiondate,'%d-%m-%Y') AS transactiondate,cm.transaction_anals3 as categoryname
FROM itemmustdetail imd 
INNER JOIN customermaster cm ON imd.itemmustcode = cm.itemmustkey AND cm.itemmustkey IS NOT NULL
INNER JOIN invoiceheader soh ON cm.customercode = soh.customercode
INNER JOIN customerinventorydetail cid ON cid.routekey = soh.routekey AND cid.visitkey = soh.visitkey 
LEFT JOIN invoicedetail sod ON sod.routekey = soh.routekey AND sod.visitkey = soh.visitkey and sod.itemcode= cid.itemcode
INNER JOIN routemaster rm ON rm.routecode = soh.routecode
INNER JOIN salesman sm ON sm.salesmancode = rm.salesmancode
INNER JOIN itemmaster im ON im.actualitemcode = imd.itemcode
 WHERE 1=1    ",in_where," 
  ORDER BY 1, 3" ," ",in_sort," ",@limitval) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
SELECT @dyn_sql;
END */$$
DELIMITER ;

