BEGIN
DECLARE limitval TEXT DEFAULT "";    
    SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter FROM startendday as sed	
	LEFT JOIN salesorderheader as ih ON ih.routekey = sed.routekey and ih.routecode = sed.routecode
	INNER JOIN routemaster as rm ON rm.routecode = sed.routecode 
	INNER JOIN salesman as sm ON sm.salesmancode = sed.salesmancode where 1=1 ", in_where," ");
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN
		CALL sp_report_calculate_paging_data(@in_counter,in_limit,in_page,@new_start_limit);
		IF @new_start_limit < 0 THEN  SET @new_start_limit = 0; END IF;
		SET @limitval = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	ELSE
		SET @limitval = CONCAT(" LIMIT 0,",@in_counter);
	END IF;
	  SELECT @new_start_limit AS start_limit,@in_counter AS counter;
	  SELECT decimalplaces INTO @decimal_places FROM currencymaster WHERE defaultcurrency = 1;
	  
	SET @dyn_sql = CONCAT("select ih.transactiondate,MIN(transactiontime) as firstvisit,MAX(transactiontime) as lastvisit,
	(select MIN(invoicenumber) from salesorderheader where  routekey = sed.routekey and routecode = sed.routecode and transactiondate= ih.transactiondate GROUP BY sed.routekey,sed.routecode,transactiondate) as firstinvoice,
	(select Max(invoicenumber) from salesorderheader where  routekey = sed.routekey and routecode = sed.routecode and transactiondate= ih.transactiondate GROUP BY sed.routekey,sed.routecode,transactiondate) as lastinvoice,
	(select count(transactionkey) from salesorderheader where routekey = sed.routekey and routecode= sed.routecode and voidflag =0 and transactiondate= ih.transactiondate) as validinvoice,
	(select count(transactionkey) from salesorderheader where routekey = sed.routekey and routecode= sed.routecode and voidflag >0 and transactiondate= ih.transactiondate) as cancelledinvoice,
	sm.salesmanname1,sm.arbsalesmanname1,sm.alternatesalesmancode,rm.routename,rm.arbroutename,rm.alternateroutecode
	FROM startendday as sed	
	INNER JOIN salesorderheader as ih ON ih.routekey = sed.routekey and ih.routecode = sed.routecode
	INNER JOIN routemaster as rm ON rm.routecode = sed.routecode 
	INNER JOIN salesman as sm ON sm.salesmancode = sed.salesmancode 
	where 1=1 ",in_where," GROUP BY sed.routekey,sed.routecode,transactiondate   
	
	UNION
	select ih.transactiondate,MIN(transactiontime) as firstvisit,MAX(transactiontime) as lastvisit,
	(select MIN(invoicenumber) from invoiceheader where  routekey = sed.routekey and routecode = sed.routecode and transactiondate= ih.transactiondate GROUP BY sed.routekey,sed.routecode,transactiondate) as firstinvoice,
	(select Max(invoicenumber) from invoiceheader where  routekey = sed.routekey and routecode = sed.routecode and transactiondate= ih.transactiondate GROUP BY sed.routekey,sed.routecode,transactiondate) as lastinvoice,
	(select count(transactionkey) from invoiceheader where routekey = sed.routekey and routecode= sed.routecode and voidflag =0 and transactiondate= ih.transactiondate) as validinvoice,
	(select count(transactionkey) from invoiceheader where routekey = sed.routekey and routecode= sed.routecode and voidflag >0 and transactiondate= ih.transactiondate) as cancelledinvoice,
	sm.salesmanname1,sm.arbsalesmanname1,sm.alternatesalesmancode,rm.routename,rm.arbroutename,rm.alternateroutecode
	FROM startendday as sed	
	INNER JOIN invoiceheader as ih ON ih.routekey = sed.routekey and ih.routecode = sed.routecode
	INNER JOIN routemaster as rm ON rm.routecode = sed.routecode 
	INNER JOIN salesman as sm ON sm.salesmancode = sed.salesmancode 
	where 1=1 ",in_where," GROUP BY sed.routekey,sed.routecode,transactiondate 
	  ",in_sort," ",@limitval) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
 select @dyn_sql;
END */$$
DELIMITER ;

