	  EXECUTE s4;
	  
	  
	  
	
	 SET @dyn_sql6 = CONCAT("UPDATE temp_strike_table str INNER JOIN 
(	SELECT rs.routecode, sed.salesmancode,rs.routekey ,COUNT(DISTINCT customercode) AS callcount FROM routesequencecustomerstatus rs 
