	  EXECUTE s6;  
	   
	   
	   
	SET @dyn_sql9 = CONCAT("UPDATE temp_strike_table str INNER JOIN 
(SELECT sed.salesmancode,COUNT(*) counts
	 FROM startendday sed	
	 INNER JOIN (
	SELECT rs.routekey ,COUNT(*) AS callcount FROM routesequencecustomerstatus rs INNER JOIN startendday sed1 ON rs.routekey=sed1.routekey AND sed1.routecode=rs.routecode WHERE rs.servicedflag = 1  AND  rs.schelduledflag = 0 GROUP BY rs.routekey,rs.customercode) caltbl ON   caltbl.routekey = sed.routekey 
   	INNER JOIN routemaster rm ON sed.routecode = rm.routecode
	INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
	
	WHERE 1=1 ",in_where,"GROUP BY sed.salesmancode) 	temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.unschedulecall=temtbl.counts");
 PREPARE s9 FROM @dyn_sql9;
	  EXECUTE s9;     
	   
	   
	   
	   
	   
	  
	  SET @dyn_sql7 = CONCAT("UPDATE temp_strike_table str INNER JOIN 
(SELECT ih.salesmancode,COUNT(*) AS counts  FROM INVOICEHEader ih 
	INNER JOIN startendday sed ON sed.routekey=ih.routekey AND sed.routecode=ih.routecode 
	INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
	WHERE  ih.immediatepaid <> 0 AND ih.voidflag = 0 ",in_where," GROUP BY ih.salesmancode) 	temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.cashsale=temtbl.counts");
 PREPARE s7 FROM @dyn_sql7;
	  EXECUTE s7; 
	  
	   SET @dyn_sql8 = CONCAT("UPDATE temp_strike_table str INNER JOIN 
(	 SELECT ih.salesmancode,COUNT(*) AS counts  FROM INVOICEHEader ih 
	INNER JOIN startendday sed ON sed.routekey=ih.routekey AND sed.routecode=ih.routecode 
	INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
	WHERE  ih.immediatepaid =0 AND ih.voidflag = 0 ",in_where," GROUP BY ih.salesmancode ) temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.creditsale=temtbl.counts");
 PREPARE s8 FROM @dyn_sql8;
	  EXECUTE s8; 
	 
	  
	  
	  SET @dyn_sql10 = CONCAT("UPDATE temp_strike_table str INNER JOIN 
(	 SELECT ah.salesmancode,COUNT(*) AS counts  FROM arheader ah 
	INNER JOIN startendday sed ON ah.routekey= sed.routekey AND ah.routecode= sed.routecode 
	INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
	WHERE  1=1  ",in_where," GROUP BY ah.salesmancode ) temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.totalreceipt=temtbl.counts");
 PREPARE s10 FROM @dyn_sql10;
	  EXECUTE s10;  
	  
	  
	  
	SET @dyn_sql11 = CONCAT("UPDATE temp_strike_table str INNER JOIN 
(	 SELECT coc.salesmancode,COUNT(DISTINCT customercode) as counts 
	FROM customeroperationscontrol coc    
	INNER JOIN startendday sed ON sed.routekey=coc.routekey  
	WHERE totaltransactions > 0",in_where," GROUP BY coc.salesmancode ) temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.productivecalls=temtbl.counts"); 
 PREPARE s11 FROM @dyn_sql11;
	  EXECUTE s11;  
	  
	  
	  
	  SET @dyn_sql12 = CONCAT("UPDATE temp_strike_table str INNER JOIN 
(	 SELECT salesmancode,(((cashsale +creditsale)/plannedcalls)*100) as strikerate from  temp_strike_table ) temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.strikerate=ROUND(temtbl.strikerate)");
 PREPARE s12 FROM @dyn_sql12;
	  EXECUTE s12;  
	  
	 SET @dyn_sql13 = CONCAT("UPDATE temp_strike_table str INNER JOIN 
(	 SELECT salesmancode,((cashsale+creditsale)/(actualcalls+unschedulecall)*100) as productiverate from  temp_strike_table ) temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.productiverate=ROUND(temtbl.productiverate)");
 PREPARE s13 FROM @dyn_sql13;
	  EXECUTE s13;  
	  
	  
	  
	  
	  
SET @dyn_sql5 = "select * from temp_strike_table";
 PREPARE s5 FROM @dyn_sql5;
	  EXECUTE s5;
	  
SELECT @dyn_sql4;
END */$$
DELIMITER ;

