		LEFT JOIN invoiceheader ihc ON ihc.routekey= sed.routekey AND ihc.routecode= sed.routecode AND ihc.immediatepaid = 0 and ihc.voidflag = 0
		INNER JOIN routemaster rm ON sed.routecode = rm.routecode
		INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
WHERE 1=1 ",in_where,"  GROUP BY sed.routecode   ORDER BY ",in_orderby," ",in_sort," ") ;
SET @dyn_sql2 = CONCAT("insert into temp_strike_table_vw_2 ",@dyn_sql) ;
	 PREPARE s1 FROM @dyn_sql2;
	EXECUTE s1;
SET @dyn_sql4 = CONCAT("UPDATE temp_strike_table_vw_2 str INNER JOIN 
(
	SELECT sed.salesmancode,COUNT(*) counts
	 FROM startendday sed	
	 INNER JOIN (
	SELECT rs.routekey ,COUNT(*) AS callcount FROM routesequencecustomerstatus rs INNER JOIN startendday sed1 ON rs.routekey=sed1.routekey AND sed1.routecode=rs.routecode WHERE rs.schelduledflag = 1  GROUP BY rs.routekey,rs.customercode) caltbl ON   caltbl.routekey = sed.routekey 
   	INNER JOIN routemaster rm ON sed.routecode = rm.routecode
	INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
	
	WHERE 1=1 ",in_where,"GROUP BY sed.salesmancode
	) 	temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.plannedcalls=temtbl.counts");
 PREPARE s4 FROM @dyn_sql4;
	 EXECUTE s4;
	  
	  
	  
	SET @dyn_sql6 = CONCAT("UPDATE temp_strike_table_vw_2 str INNER JOIN 
(SELECT sed.salesmancode,COUNT(*) counts
	 FROM startendday sed	
	 INNER JOIN (
	SELECT rs.routekey ,COUNT(*) AS callcount FROM routesequencecustomerstatus rs INNER JOIN startendday sed1 ON rs.routekey=sed1.routekey AND sed1.routecode=rs.routecode WHERE rs.servicedflag = 1  GROUP BY rs.routekey,rs.customercode) caltbl ON   caltbl.routekey = sed.routekey 
   	INNER JOIN routemaster rm ON sed.routecode = rm.routecode
	INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
	
	WHERE 1=1 ",in_where,"GROUP BY sed.salesmancode) 	temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.actualcalls=temtbl.counts");
 PREPARE s6 FROM @dyn_sql6;
	 EXECUTE s6;  
	   
	   
	   
	SET @dyn_sql9 = CONCAT("UPDATE temp_strike_table_vw_2 str INNER JOIN 
(SELECT sed.salesmancode,COUNT(*) counts
	 FROM startendday sed	
	 INNER JOIN (
	SELECT rs.routekey ,COUNT(*) AS callcount FROM routesequencecustomerstatus rs INNER JOIN startendday sed1 ON rs.routekey=sed1.routekey AND sed1.routecode=rs.routecode WHERE rs.servicedflag = 1  AND  rs.schelduledflag = 0 GROUP BY rs.routekey,rs.customercode) caltbl ON   caltbl.routekey = sed.routekey 
   	INNER JOIN routemaster rm ON sed.routecode = rm.routecode
	INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
	
	WHERE 1=1 ",in_where,"GROUP BY sed.salesmancode) 	temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.unschedulecall=temtbl.counts");
 PREPARE s9 FROM @dyn_sql9;
	EXECUTE s9;     
	   
	   
	   
	  
	  SET @dyn_sql7 = CONCAT("UPDATE temp_strike_table_vw_2 str INNER JOIN 
(SELECT ih.salesmancode,COUNT(*) AS counts  FROM INVOICEHEader ih 
	INNER JOIN startendday sed ON sed.routekey=ih.routekey AND sed.routecode=ih.routecode 
	INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
	WHERE  ih.immediatepaid <> 0 AND ih.voidflag = 0 ",in_where," GROUP BY ih.salesmancode) 	temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.cashsale=temtbl.counts");
 PREPARE s7 FROM @dyn_sql7;
	  -- EXECUTE s7; 
	  
	   SET @dyn_sql8 = CONCAT("UPDATE temp_strike_table_vw_2 str INNER JOIN 
(	 SELECT ih.salesmancode,COUNT(*) AS counts  FROM INVOICEHEader ih 
	INNER JOIN startendday sed ON sed.routekey=ih.routekey AND sed.routecode=ih.routecode 
	INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
	WHERE  ih.immediatepaid =0 AND ih.voidflag = 0 ",in_where," GROUP BY ih.salesmancode ) temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.creditsale=temtbl.counts");
 PREPARE s8 FROM @dyn_sql8;
	EXECUTE s8; 
	 
	  
	  
	  SET @dyn_sql10 = CONCAT("UPDATE temp_strike_table_vw_2 str INNER JOIN 
(	 SELECT ah.salesmancode,COUNT(*) AS counts  FROM arheader ah 
	INNER JOIN startendday sed ON ah.routekey= sed.routekey AND ah.routecode= sed.routecode 
	INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
	WHERE  1=1  ",in_where," GROUP BY ah.salesmancode ) temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.totalreceipt=temtbl.counts");
	-- PREPARE s10 FROM @dyn_sql10;
	 -- EXECUTE s10;  
	  
	  
 
	 SET @dyn_sql11 = CONCAT("UPDATE temp_strike_table_vw_2 str INNER JOIN 
(	 SELECT coc.salesmancode,COUNT(distinct customercode) AS counts  FROM customeroperationscontrol coc 
	INNER JOIN startendday sed ON coc.routecode = sed.routecode and coc.routekey = sed.routekey
	INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
	WHERE  totaltransactions >0 
		 and coc.primary_id not in (
		 select primary_id from customeroperationscontrol c join arheader a on c.routekey = a.routekey and c.visitkey = a.visitkey 
		 where c.routekey  = coc.routekey 
		 )
	 ",in_where," GROUP BY coc.salesmancode ) temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.productivecalls=temtbl.counts");
 PREPARE s11 FROM @dyn_sql11;
	EXECUTE s11;  
 
	  
	  
	  
	  SET @dyn_sql12 = CONCAT("UPDATE temp_strike_table_vw_2 str INNER JOIN 
(	 SELECT salesmancode,(((actualcalls)/plannedcalls)*100) as strikerate from  temp_strike_table_vw_2 ) temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.strikerate=ROUND(temtbl.strikerate)");
 PREPARE s12 FROM @dyn_sql12;
	 EXECUTE s12;  
	  
	 SET @dyn_sql13 = CONCAT("UPDATE temp_strike_table_vw_2 str INNER JOIN 
(	 SELECT salesmancode,((productivecalls)/(plannedcalls)*100) as productiverate from  temp_strike_table_vw_2 ) temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.productiverate=ROUND(temtbl.productiverate)");
 PREPARE s13 FROM @dyn_sql13;
	EXECUTE s13;  
	  
	SET @dyn_sql14 = CONCAT("UPDATE temp_strike_table_vw_2 str INNER JOIN 
	(	 SELECT coc.`salesmancode`,
SUM(TIMESTAMPDIFF(MINUTE,
STR_TO_DATE(CONCAT(STR_TO_DATE(visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
STR_TO_DATE(CONCAT(STR_TO_DATE(visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
)) TotalMinutesSpend
FROM customeroperationscontrol coc INNER JOIN startendday sed ON sed.routekey=coc.routekey
	WHERE 1=1 ",in_where," GROUP BY coc.salesmancode ) temtbl ON str.salesmancode=temtbl.salesmancode
	SET str.CustomerFaceTime=temtbl.TotalMinutesSpend");
	-- Select @dyn_sql14;
	PREPARE s14 FROM @dyn_sql14;
	 EXECUTE s14; 
	  
	  
	--   SELECT @dyn_sql2; Select @dyn_sql4; Select @dyn_sql6; Select @dyn_sql7; Select @dyn_sql8; Select @dyn_sql9; Select @dyn_sql10; Select @dyn_sql11; Select @dyn_sql12; Select  @dyn_sql13; Select @dyn_sql14;
	insert into temp_strike_table_vw_2
	select
	merch_name,
	fsm_name,
	salesmancode,
	routecode,
	routecode,
	routecode,
	planned,
	serviced,
	unplanned,
	cashsale,
	creditsale,
	productive,
	receipts,
	serviced / planned * 100 strikerate,
	productive / planned * 100 productiverate,
	facetime
from
	(
	select
		routecode,
		salesmancode,
		merch_name,
		f.fsm_name,
		(
		select
			count(distinct jp_cust_code)
		from
			merch_live.tts_merch_journey_plan jp
		where
			jp.jp_date = (DATE_SUB(CURDATE(), INTERVAL 1 DAY))
			and jp_routecode = routecode
			and jp_planned_yn = 1 ) planned,
		(
		select
			count(distinct jp_cust_code)
		from
			merch_live.tts_merch_journey_plan jp
		where
			jp.jp_date = (DATE_SUB(CURDATE(), INTERVAL 1 DAY))
			and jp_routecode = routecode
			and jp_serviced_yn = 1 ) serviced,
		(
		select
			count(distinct jp_cust_code)
		from
			merch_live.tts_merch_journey_plan jp
		where
			jp.jp_date = (DATE_SUB(CURDATE(), INTERVAL 1 DAY))
			and jp_routecode = routecode
			and jp_planned_yn = 0
			and jp_serviced_yn = 1 ) unplanned,
		0 cashsale,
		0 creditsale,
		(
		select
			count(distinct customercode)
		from
			merch_live.tts_merch_cust_visit_detl d
		where
			visitstartdate = (DATE_SUB(CURDATE(), INTERVAL 1 DAY))
			and d.routecode = tmr.routecode) productive,
		(
		select
			SUM(TIMESTAMPDIFF(minute,
STR_TO_DATE(CONCAT(STR_TO_DATE(txndate, '%Y-%m-%d'), ' ', STR_TO_DATE(starttime, '%H:%i')), '%Y-%m-%d %H:%i:%s'), 
STR_TO_DATE(CONCAT(STR_TO_DATE(txndate, '%Y-%m-%d'), ' ', STR_TO_DATE(endtime, '%H:%i')), '%Y-%m-%d %H:%i:%s')
)) TotalMinutesSpend
		from
			merch_live.tts_merch_cust_visit v
		where
			txndate = (DATE_SUB(CURDATE(), INTERVAL 1 DAY))
			and v.routecode = tmr.routecode) facetime,
		0 receipts
	from
		merch_live.tts_merch_routekey tmr
	inner join merch_live.tts_merch_merchandiser_master m on
		tmr.salesmancode = m.MERCH_CODE
	inner join merch_live.tts_merch_fsm_master f on
		m.FSM_CODE = f.fsm_code
	where
		tmr.routestartdate = (DATE_SUB(CURDATE(), INTERVAL 1 DAY))
) a; 
	  
	  
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_route_strikerate_and_productivity_test` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_route_strikerate_and_productivity_test` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_route_strikerate_and_productivity_test`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit VARCHAR(25),
IN in_page VARCHAR(25))
BEGIN
DECLARE limitval TEXT DEFAULT "";    
    SET @dyn_sql = CONCAT("SELECT count(distinct sed.routecode) INTO @in_counter 
	 FROM startendday sed	
    LEFT JOIN routesequencecustomerstatus rcs ON rcs.routecode = sed.routecode AND rcs.routekey = sed.routekey AND  rcs.schelduledflag = 1
    LEFT JOIN routesequencecustomerstatus vis ON vis.routecode = sed.routecode AND vis.routekey = sed.routekey AND  vis.servicedflag = 1
    LEFT JOIN routesequencecustomerstatus uns ON uns.routecode = sed.routecode AND uns.routekey = sed.routekey AND  uns.servicedflag = 1 AND  uns.schelduledflag = 0
    LEFT JOIN invoiceheader ih ON ih.routekey= sed.routekey AND ih.routecode= sed.routecode AND ih.immediatepaid <> 0 and ih.voidflag = 0
    LEFT JOIN invoiceheader ihc ON ihc.routekey= sed.routekey AND ihc.routecode= sed.routecode AND ihc.immediatepaid = 0 and ihc.voidflag = 0
WHERE 1=1 ", in_where ,"  ");
	 PREPARE s1 FROM @dyn_sql;
	
	
	IF in_limit != "" && in_page != "" THEN
		CALL sp_report_calculate_paging_data(@in_counter,in_limit,in_page,@new_start_limit);
		IF @new_start_limit < 0 THEN  SET @new_start_limit = 0; END IF;
		SET @limitval = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	ELSE
		SET @limitval = CONCAT(" LIMIT 0,",@in_counter);
	END IF;
	  SELECT @new_start_limit AS start_limit,@in_counter AS counter;
	  SELECT decimalplaces INTO @decimal_places FROM currencymaster WHERE defaultcurrency = 1;
	  
	  SET @dyn_sql3 = "delete from temp_strike_table";
	  PREPARE s3 FROM @dyn_sql3;
	  EXECUTE s3;	
	  
	SET @dyn_sql = CONCAT("select sm.salesmanname1, sm.arbsalesmanname1, sm.alternatesalesmancode as salesmancode,
rm.routename,rm.arbroutename, rm.alternateroutecode as routecode,
0 as plannedcalls, 
0 as actualcalls, 0 as unschedulecall,
0 as cashsale, 0 as creditsale , 
0 AS productivecalls, 
0 as totalreceipt,
0 as strikerate,
0 as productiverate
	 FROM startendday sed	
    LEFT JOIN routesequencecustomerstatus rcs ON rcs.routecode = sed.routecode AND rcs.routekey = sed.routekey AND  rcs.schelduledflag = 1
    LEFT JOIN routesequencecustomerstatus vis ON vis.routecode = sed.routecode AND vis.routekey = sed.routekey AND  vis.servicedflag = 1
    LEFT JOIN routesequencecustomerstatus uns ON uns.routecode = sed.routecode AND uns.routekey = sed.routekey AND  uns.servicedflag = 1 AND  uns.schelduledflag = 0
    LEFT JOIN invoiceheader ih ON ih.routekey= sed.routekey AND ih.routecode= sed.routecode AND ih.immediatepaid <> 0 and ih.voidflag = 0
    LEFT JOIN invoiceheader ihc ON ihc.routekey= sed.routekey AND ihc.routecode= sed.routecode AND ihc.immediatepaid = 0 and ihc.voidflag = 0
	INNER JOIN routemaster rm ON sed.routecode = rm.routecode
	INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
WHERE 1=1 ",in_where,"  GROUP BY sed.routecode   ORDER BY ",in_orderby," ",in_sort," ",@limitval) ;
SET @dyn_sql2 = CONCAT("insert into temp_strike_table ",@dyn_sql) ;
	 PREPARE s1 FROM @dyn_sql;
	  EXECUTE s1;
SET @dyn_sql4 = CONCAT("UPDATE temp_strike_table str INNER JOIN 
(SELECT sed.salesmancode,COUNT( rs.customercode) counts 
FROM  routesequence rs
INNER JOIN startendday sed ON sed.routecode=rs.routecode WHERE
CASE WHEN DAYNAME(sed.routeenddate)='Monday' THEN rs.callrestrictiondays1=1
WHEN DAYNAME(sed.routeenddate)='Tuesday' THEN rs.callrestrictiondays2=1
WHEN DAYNAME(sed.routeenddate)='Wednesday' THEN rs.callrestrictiondays3=1
WHEN DAYNAME(sed.routeenddate)='Thursday' THEN rs.callrestrictiondays4=1
WHEN DAYNAME(sed.routeenddate)='Friday' THEN rs.callrestrictiondays5=1
WHEN DAYNAME(sed.routeenddate)='Saturday' THEN rs.callrestrictiondays6=1
WHEN DAYNAME(sed.routeenddate)='Sunday' THEN rs.callrestrictiondays7=1
ELSE  0 END and sed.routeclosed=1  ",in_where,"  GROUP BY rs.routecode 
 ) 	temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.plannedcalls=temtbl.counts");
 PREPARE s4 FROM @dyn_sql4;
	 
	  
	  
	  
	
	 SET @dyn_sql6 = CONCAT("UPDATE temp_strike_table str INNER JOIN 
(SELECT sed.salesmancode,SUM(callcount) counts
	 FROM startendday sed	
	 INNER JOIN (
	SELECT rs.routekey ,COUNT(DISTINCT customercode) AS callcount FROM routesequencecustomerstatus rs 
	INNER JOIN startendday sed1 ON rs.routekey=sed1.routekey AND sed1.routecode=rs.routecode 
	WHERE rs.servicedflag = 1  GROUP BY sed1.routekey) caltbl ON   caltbl.routekey = sed.routekey 
	WHERE 1=1 ",in_where,"GROUP BY sed.salesmancode) 	temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.actualcalls=temtbl.counts");
 PREPARE s6 FROM @dyn_sql6;
	 
	   
	SET @dyn_sql9 = CONCAT("UPDATE temp_strike_table str INNER JOIN 
(SELECT sed.salesmancode,COUNT(*) counts
	 FROM startendday sed	
	 INNER JOIN (
	SELECT rs.routekey ,COUNT(*) AS callcount FROM routesequencecustomerstatus rs INNER JOIN startendday sed1 ON rs.routekey=sed1.routekey AND sed1.routecode=rs.routecode WHERE rs.servicedflag = 1  AND  rs.schelduledflag = 0 GROUP BY rs.routekey,rs.customercode) caltbl ON   caltbl.routekey = sed.routekey 
   	INNER JOIN routemaster rm ON sed.routecode = rm.routecode
	INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
	
	WHERE 1=1 ",in_where,"GROUP BY sed.salesmancode) temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.unschedulecall=temtbl.counts");
 PREPARE s9 FROM @dyn_sql9;
	
	  
	  SET @dyn_sql7 = CONCAT("UPDATE temp_strike_table str INNER JOIN 
(SELECT ih.salesmancode,COUNT(*) AS counts  FROM INVOICEHEader ih 
	INNER JOIN startendday sed ON sed.routekey=ih.routekey AND sed.routecode=ih.routecode 
	INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
	WHERE  ih.immediatepaid <> 0 AND ih.voidflag = 0 ",in_where," GROUP BY ih.salesmancode) temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.cashsale=temtbl.counts");
 PREPARE s7 FROM @dyn_sql7;
	 
	  
	   SET @dyn_sql8 = CONCAT("UPDATE temp_strike_table str INNER JOIN 
(	 SELECT ih.salesmancode,COUNT(*) AS counts  FROM INVOICEHEader ih 
	INNER JOIN startendday sed ON sed.routekey=ih.routekey AND sed.routecode=ih.routecode 
	INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
	WHERE  ih.immediatepaid =0 AND ih.voidflag = 0 ",in_where," GROUP BY ih.salesmancode ) temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.creditsale=temtbl.counts");
 PREPARE s8 FROM @dyn_sql8;
	 
	 
 
	  SET @dyn_sql10 = CONCAT("UPDATE temp_strike_table str INNER JOIN 
(	 SELECT ah.salesmancode,COUNT(*) AS counts  FROM arheader ah 
	INNER JOIN startendday sed ON ah.routekey= sed.routekey AND ah.routecode= sed.routecode 
	INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
	WHERE  1=1  ",in_where," GROUP BY ah.salesmancode ) temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.totalreceipt=temtbl.counts");
 PREPARE s10 FROM @dyn_sql10;
	 
	  
	  
	  
	SET @dyn_sql11 = CONCAT("UPDATE temp_strike_table str INNER JOIN 
(	 SELECT sed.salesmancode,SUM(callcount) counts
	 FROM startendday sed	
	 INNER JOIN (
	SELECT coc.routekey ,COUNT(DISTINCT customercode) AS callcount FROM customeroperationscontrol coc    
	INNER JOIN startendday sed ON sed.routekey=coc.routekey  
	WHERE totaltransactions > 0 GROUP BY sed.routekey) caltbl ON   caltbl.routekey = sed.routekey 
	WHERE 1=1",in_where," GROUP BY sed.salesmancode ) temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.productivecalls=temtbl.counts"); 
 PREPARE s11 FROM @dyn_sql11;
	 
	  
	  
	  
	  SET @dyn_sql12 = CONCAT("UPDATE temp_strike_table str INNER JOIN 
( SELECT salesmancode,(((cashsale +creditsale)/plannedcalls)*100) as strikerate from  temp_strike_table ) temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.strikerate=ROUND(temtbl.strikerate)");
 PREPARE s12 FROM @dyn_sql12;
	
	  
	 SET @dyn_sql13 = CONCAT("UPDATE temp_strike_table str INNER JOIN 
(	 SELECT salesmancode,((cashsale+creditsale)/(actualcalls+unschedulecall)*100) as productiverate from  temp_strike_table ) temtbl ON str.salesmancode=temtbl.salesmancode
	 SET str.productiverate=ROUND(temtbl.productiverate)");
 PREPARE s13 FROM @dyn_sql13;
	
	  
  
SET @dyn_sql5 = "select * from temp_strike_table";
 PREPARE s5 FROM @dyn_sql5;
	 
	   SELECT @dyn_sql;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_route_strikerate_and_productivity_vw` */

