/* Procedure structure for procedure `sp_report_salesman_routestatus` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_salesman_routestatus` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_salesman_routestatus`(in days int)
BEGIN
	declare daystr varchar(50) default '';
	set daystr = concat("curdate() - interval ",days, " day" );
	
	set @dyn_sql = concat("
		select
    `sfa_enhance`.`routemaster`.`divisioncode` as `divisioncode`,
    `sfa_enhance`.`salesman`.`arbsalesmanname1` as `fsm`,
    `sfa_enhance`.`salesman`.`salesmancode` as `salesmancode`,
    `sfa_enhance`.`salesman`.`salesmanname1` as `salesmanname1`,
    (case
        when isnull(`sfa_enhance`.`startendday`.`routeenddate`) then `sfa_enhance`.`startendday`.`routestartdate`
        else `sfa_enhance`.`startendday`.`routeenddate`
    end) as `maxdate`,
    `sfa_enhance`.`startendday`.`routestartdate` as `routestartdate`,
    `sfa_enhance`.`startendday`.`routestarttime` as `routestarttime`,
    `sfa_enhance`.`startendday`.`routeenddate` as `routeenddate`,
    `sfa_enhance`.`startendday`.`routeendtime` as `routeendtime`,
    (case
        when isnull(`sfa_enhance`.`startendday`.`routestartodometer`) then 0
        else `sfa_enhance`.`startendday`.`routestartodometer`
    end) as `routestartodometer`,
    (case
        when isnull(`sfa_enhance`.`startendday`.`routeendodometer`) then 0
        else `sfa_enhance`.`startendday`.`routeendodometer`
    end) as `routeendodometer`
from
    ((`sfa_enhance`.`routemaster`
left join `sfa_enhance`.`startendday` on
    ((`sfa_enhance`.`routemaster`.`routecode` = `sfa_enhance`.`startendday`.`routecode`)))
left join `sfa_enhance`.`salesman` on
    ((`sfa_enhance`.`routemaster`.`salesmancode` = `sfa_enhance`.`salesman`.`salesmancode`)))
where
    (`sfa_enhance`.`startendday`.`routestartdate` = ( ",daystr," ))
union
select
    'MER OU' as `MER OU`,
    `f`.`fsm_name` as `fsm_name`,
    `r`.`MERCH_CODE` as `MERCH_CODE`,
    `m`.`MERCH_NAME` as `MERCH_NAME`,
    `k`.`routeenddate` as `routeenddate`,
    `k`.`routestartdate` as `routestartdate`,
    `k`.`routestarttime` as `routestarttime`,
    `k`.`routeenddate` as `routeenddate`,
    `k`.`routeendtime` as `routeendtime`,
    `k`.`routestartodometer` as `routestartodometer`,
    `k`.`routeendodometer` as `routeendodometer`
from
    (((`merch_live`.`tts_merch_route_master` `r`
left join `merch_live`.`tts_merch_routekey` `k` on
    (((`r`.`ROUTE_CODE` = `k`.`routecode`)
        and (`k`.`routestartdate` = ( ",daystr," )))))
left join `merch_live`.`tts_merch_merchandiser_master` `m` on
    ((`r`.`MERCH_CODE` = `m`.`MERCH_CODE`)))
left join `merch_live`.`tts_merch_fsm_master` `f` on
    ((`m`.`FSM_CODE` = `f`.`fsm_code`)))
where
    (`r`.`ROUTE_STS` = 1)
order by
    3,
    6
	");
	PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
	  SELECT @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_tabletreport_cashcheque_collection` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_tabletreport_cashcheque_collection` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_tabletreport_cashcheque_collection`(
	IN in_where TEXT,
	IN in_orderby VARCHAR(255),
	IN in_sort VARCHAR(25),
	IN in_limit INT,
	IN in_page INT
)
BEGIN
	SET @dyn_sql = CONCAT('SELECT t1.* from (
				SELECT "COLLECTION" trantype, arh.transactiondate, arh.routecode, arh.invoicenumber AS receiptnumber, cm.alternatecode `code`, cm.customername, cm.arbcustomername,arh.amountpaid,
					CASE WHEN ccd.typecode = 0 THEN "CASH" ELSE "CHEQUE" END AS mop,
					CASE WHEN ccd.typecode = 0 THEN "" ELSE CAST(ccd.checknumber AS CHAR) END AS checknumber, 
					CASE WHEN ccd.typecode = 0 THEN "" ELSE DATE_FORMAT(ccd.checkdate, "%d %b %Y") END AS checkdate,
					CASE WHEN ccd.typecode = 0 THEN "" ELSE bm.bankname END AS bankname,
					CASE WHEN ccd.typecode = 0 THEN "" ELSE bm.arbbankname END AS arbbankname,
					CASE WHEN ccd.typecode = 0 THEN 0 ELSE ccd.amount END AS checkamount
				FROM startendday AS sed INNER JOIN
					arheader AS arh ON sed.routekey = arh.routekey INNER JOIN
					cashcheckdetail AS ccd ON arh.routekey = ccd.routekey AND arh.visitkey = ccd.visitkey INNER JOIN
					bankmaster AS bm ON ccd.bankcode = bm.bankcode INNER JOIN
					customermaster AS cm ON arh.customercode = cm.customercode
				WHERE (arh.voidflag = 0)
				', in_where, '
			UNION
				SELECT "INVOICE" trantype, ih.transactiondate, ih.routecode, ih.invoicenumber AS receiptnumber, cm.alternatecode CODE, cm.customername,cm.arbcustomername, ih.immediatepaid amountpaid,
					CASE WHEN ccd.typecode = 0 THEN "CASH" ELSE "CHEQUE" END AS mop,
					CASE WHEN ccd.typecode = 0 THEN "" ELSE CAST(ccd.checknumber AS CHAR) END AS checknumber,
					CASE WHEN ccd.typecode = 0 THEN "" ELSE DATE_FORMAT(ccd.checkdate, "%d %b %Y") END AS checkdate,
					CASE WHEN ccd.typecode = 0 THEN "" ELSE bm.bankname END AS bankname,
					CASE WHEN ccd.typecode = 0 THEN "" ELSE bm.arbbankname END AS arbbankname,
					CASE WHEN ccd.typecode = 0 THEN 0 ELSE ccd.amount END AS checkamount
				FROM startendday AS sed INNER JOIN
					invoiceheader AS ih ON sed.routekey = ih.routekey INNER JOIN
					cashcheckdetail AS ccd ON ih.routekey = ccd.routekey AND ih.visitkey = ccd.visitkey INNER JOIN
					bankmaster AS bm ON ccd.bankcode = bm.bankcode INNER JOIN
					customermaster AS cm ON ih.customercode = cm.customercode
				WHERE (ih.immediatepaid > 0) AND ( ih.voidflag = 0)
				',in_where,'
				) as t1 ORDER BY t1.',in_orderby,' ',in_sort) ;
	 		
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_tabletreport_cashcheque_collection_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_tabletreport_cashcheque_collection_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_tabletreport_cashcheque_collection_detail`()
