/* Procedure structure for procedure `sp_report_tabletreport_returnorbuybacksummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_tabletreport_returnorbuybacksummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_tabletreport_returnorbuybacksummary`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT
)
BEGIN
DECLARE orderby_val TEXT DEFAULT "";
DECLARE limit_val TEXT DEFAULT "";
	SET @dyn_sql = CONCAT("
		SELECT 
			count(*) INTO @in_counter
		FROM
			invoiceheader ih, invoicedetail id, invoicerxddetail ir,
			routemaster rm, customermaster cm, itemmaster im, retitmreasons rr,
			itemgroup ig, submajorcategory sc, majorcategory mc
		WHERE
			ih.routecode = rm.routecode AND ih.customercode = cm.customercode AND
			ih.routekey = id.routekey AND ih.visitkey = id.visitkey AND
			id.routekey = ir.routekey AND id.visitkey = ir.visitkey AND id.itemcode = ir.itemcode AND
			ir.reasoncode = rr.code AND ir.itemcode = im.actualitemcode AND ig.itemgroupcode = im.itemgroupcode AND
			sc.submajorcategorycode = ig.submajorcategorycode AND mc.majorcategorycode = sc.majorcategorycode
			  AND ir.itemtransactiontype = 1
		", in_where);
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	IF in_orderby != "" && in_sort != "" THEN
		SET orderby_val = CONCAT( " ORDER BY ",in_orderby," ",in_sort);
	END IF;
	SET @dyn_sql = CONCAT('
		SELECT
			ih.actualtransactiondate, ih.routecode, rm.routename, rm.arbroutename, ih.salesmancode, cm.reportcustcode customercode,
			CASE WHEN cm.type = 1 THEN "0" WHEN cm.type = 2 THEN (SELECT cm1.reportcustcode FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE "1" END hocode,
			CASE WHEN cm.type = 1 THEN "normal customers" WHEN cm.type = 2 THEN (SELECT cm1.customername FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE "" END honame,
			mc.majorcategorycode, mc.description majorcategroy, im.reportitemcode itemcode, im.itemdescription,im.arbitemdescription, im.unitspercase,
			ir.quantity,
			(CAST(ir.quantity/im.unitspercase AS UNSIGNED) * id.returncaseprice) +
			(CASE WHEN ir.quantity % im.unitspercase <> 0 THEN ir.quantity % im.unitspercase ELSE 0 END * id.returnprice) AS value,
			(ir.quantity * id.returnprice) value1,
			id.returnprice returnprice,
			ir.itemtransactiontype, ir.reasoncode, rr.description,rr.arbdescription
		FROM
			invoiceheader ih, invoicedetail id, invoicerxddetail ir,
			routemaster rm, customermaster cm, itemmaster im, retitmreasons rr,
			itemgroup ig, submajorcategory sc, majorcategory mc
		WHERE
			ih.routecode = rm.routecode AND ih.customercode = cm.customercode AND
			ih.routekey = id.routekey AND ih.visitkey = id.visitkey AND
			id.routekey = ir.routekey AND id.visitkey = ir.visitkey AND id.itemcode = ir.itemcode AND
			ir.reasoncode = rr.code AND ir.itemcode = im.actualitemcode AND ig.itemgroupcode = im.itemgroupcode AND
			sc.submajorcategorycode = ig.submajorcategorycode AND mc.majorcategorycode = sc.majorcategorycode
			  AND ir.itemtransactiontype = 1
		',in_where, orderby_val,limit_val) ;
  
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
    END */$$
DELIMITER ;

