/* Procedure structure for procedure `sp_report_tablet_free_summary` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_tablet_free_summary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_tablet_free_summary`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter FROM invoiceheader ih, invoicedetail id, routemaster rm, customermaster cm, itemmaster im, itemgroup ig, submajorcategory sc, majorcategory mc WHERE 
		ih.routecode = rm.routecode AND ih.customercode = cm.customercode AND
		ih.routekey = id.routekey AND ih.visitkey = id.visitkey AND ig.itemgroupcode = im.itemgroupcode AND 
		sc.submajorcategorycode = ig.submajorcategorycode AND mc.majorcategorycode = sc.majorcategorycode AND (freesampleqty + manualfreeqty) > 0", in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	
	SET @dyn_sql = CONCAT("SELECT
		ih.actualtransactiondate, ih.routecode, rm.routename, rm.arbroutename, ih.salesmancode, cm.reportcustcode customercode, cm.customername, cm.arbcustomername, 
		CASE WHEN cm.type = 1 THEN '0' WHEN cm.type = 2 THEN (SELECT cm1.reportcustcode FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE '1' END hocode,
		CASE WHEN cm.type = 1 THEN 'NORMAL CUSTOMERS' WHEN cm.type = 2 THEN (SELECT cm1.customername FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE '' END honame,
		mc.majorcategorycode, im.reportitemcode itemcode, im.itemdescription,  im.arbitemdescription, im.unitspercase, 
		id.freesampleqty + id.manualfreeqty freeqty,(id.freesampleqty + id.manualfreeqty)% im.unitspercase AS units,CAST((id.freesampleqty + id.manualfreeqty) / im.unitspercase AS UNSIGNED) AS cases,
		(CAST(id.manualfreeqty/im.unitspercase AS UNSIGNED) * id.returncaseprice) + 
			(CASE WHEN id.manualfreeqty % im.unitspercase <> 0 THEN id.manualfreeqty % im.unitspercase ELSE 0 END * id.returnprice) AS value,	
				
		id.returnprice returnprice
		
	FROM 
		invoiceheader ih, invoicedetail id, routemaster rm, customermaster cm, itemmaster im, itemgroup ig, submajorcategory sc, majorcategory mc
	WHERE 
		ih.routecode = rm.routecode AND ih.customercode = cm.customercode AND
		ih.routekey = id.routekey AND ih.visitkey = id.visitkey AND ig.itemgroupcode = im.itemgroupcode AND 
		sc.submajorcategorycode = ig.submajorcategorycode AND mc.majorcategorycode = sc.majorcategorycode AND 
		(freesampleqty + manualfreeqty) > 0",in_where, " ORDER BY ",in_orderby," ",in_sort, " ",limit_val) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
	 
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_tablet_report` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_tablet_report` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_tablet_report`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT
)
BEGIN
SET @dyn_sql = CONCAT("SELECT  	count(*) INTO @in_counter  FROM routemaster ", in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	
	 CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
	
	  SELECT @new_start_limit AS start_limit,@in_counter AS counter;
	
	SET @dyn_sql = CONCAT(" SELECT  
			invoiceheader.routecode	,
			get_name_type_base(invoiceheader.routecode,3) as routename,
			invoiceheader.transactiondate , TIME(invoiceheader.transactiondate)AS time1,
			invoiceheader.invoicenumber,invoiceheader.salesmancode,invoiceheader.customercode,
			get_name_type_base(invoiceheader.customercode,1) AS customername,
			invoiceheader.totalsalesamount,
			invoiceheader.totalreturnamount,
			invoiceheader.totaldamagedamount,
			invoiceheader.totalexpiryamount,
			invoiceheader.totalfreesampleamount,
			invoiceheader.invoicebalance,
			invoiceheader.totalpromoamount,
			invoiceheader.amountpaid,
			CASE invoicepaymentterms 
						WHEN 0 THEN 'CASH Only'
						WHEN 1 THEN 'CASH or CHEQUE' 
						WHEN 2 THEN 'CHARGE Only (GC)' 
						WHEN 3 THEN 'TC (CASH or CHEQUE)' 
						WHEN 4 THEN 'TC (CASH Only)' 
					 ELSE 'CASH Only' END AS invoice_paynent_terms_text
			 
			FROM invoiceheader
			LEFT JOIN customermaster ON invoiceheader.customercode = customermaster.customercode
			",in_where, " ORDER BY ",in_orderby," ",in_sort, " LIMIT ",@new_start_limit, ",",in_limit) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_tablet_routeinventory` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_tablet_routeinventory` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_tablet_routeinventory`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT
)
BEGIN
DECLARE orderby_val TEXT DEFAULT "";
DECLARE limit_val TEXT DEFAULT "";
	SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter  
				FROM startendday sed, 
					routemaster rm, 
					salesman sm, 
					inventorysummarydetail isd,
					itemmaster im, itemgroup ig,
					submajorcategory smc,
					majorcategory mc, 
					(SELECT id.routekey, id.itemcode, COALESCE(SUM(id.salesqty), 0) salesqty,
					COALESCE(SUM(id.returnqty), 0) returnqty, COALESCE(SUM(id.damagedqty), 0) damagedqty,
					COALESCE(SUM(id.expiryqty), 0) expiryqty, COALESCE(SUM(id.freesampleqty), 0) freesampleqty,
					COALESCE(SUM(id.manualfreeqty), 0) manualfreeqty 
					FROM invoicedetail id GROUP BY id.routekey, id.itemcode) sales 
				WHERE sed.routekey = isd.routekey AND 
					sed.routecode = rm.routecode AND
					sed.salesmancode = sm.salesmancode AND 
					im.actualitemcode = isd.itemcode AND
					ig.itemgroupcode = im.itemgroupcode AND
					smc.submajorcategorycode = ig.submajorcategorycode AND 
					mc.majorcategorycode = smc.majorcategorycode AND 
					sales.routekey = isd.routekey
					AND sales.itemcode = isd.itemcode ", in_where);
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	IF in_orderby != "" && in_sort != "" THEN
		SET orderby_val = CONCAT( " ORDER BY ",in_orderby," ",in_sort);
	END IF;
	SET @dyn_sql = CONCAT("SELECT sed.routekey, 
					sed.routecode, 
					rm.routename, 
					rm.arbroutename, 
					sed.salesmancode, 
					sm.salesmanname1 salesman,
					mc.majorcategorycode, 
					mc.description majorcategroy,
					im.actualitemcode, 
					im.reportitemcode, 
					im.itemdescription, 
					im.arbitemdescription, 
					isd.beginstockqty,
					CAST(isd.beginstockqty/im.unitspercase AS UNSIGNED) beginqtycase,
					CASE WHEN isd.beginstockqty % im.unitspercase <> 0 THEN isd.beginstockqty % im.unitspercase ELSE 0 END beginqtypcs,
					isd.loadqty, 
					CAST(isd.loadqty/im.unitspercase AS UNSIGNED) loadqtycase, 
					CASE WHEN isd.loadqty % im.unitspercase <> 0 THEN isd.loadqty % im.unitspercase ELSE 0 END loadqtypcs,
					isd.loadaddqty, 
					CAST(isd.loadaddqty/im.unitspercase AS UNSIGNED) loadaddqtycase,
					CASE WHEN isd.loadaddqty % im.unitspercase <> 0 THEN isd.loadaddqty % im.unitspercase ELSE 0 END loadaddqtypcs,
					isd.loadcutqty,
					CAST(isd.loadcutqty/im.unitspercase AS UNSIGNED) loadcutqtycase, 
					CASE WHEN isd.loadcutqty % im.unitspercase <> 0 THEN isd.loadcutqty % im.unitspercase ELSE 0 END loadcutqtypcs, 
					sales.salesqty,
					CAST(sales.salesqty/im.unitspercase AS UNSIGNED) salesqtycase,
					CASE WHEN sales.salesqty % im.unitspercase <> 0 THEN sales.salesqty % im.unitspercase ELSE 0 END salesqtypcs,
					sales.returnqty, 
					CAST(sales.returnqty/im.unitspercase AS UNSIGNED) returnqtycase, 
					CASE WHEN sales.returnqty % im.unitspercase <> 0 THEN sales.returnqty % im.unitspercase ELSE 0 END returnqtypcs,
					sales.damagedqty,
					CAST(sales.damagedqty/im.unitspercase AS UNSIGNED) damagedqtycase, 
					CASE WHEN sales.damagedqty % im.unitspercase <> 0 THEN sales.damagedqty % im.unitspercase ELSE 0 END damagedqtypcs,
					sales.expiryqty, 
					CAST(sales.expiryqty/im.unitspercase AS UNSIGNED) expiryqtycase,
					CASE WHEN sales.expiryqty % im.unitspercase <> 0 THEN sales.expiryqty % im.unitspercase ELSE 0 END expiryqtypcs,
					sales.freesampleqty,
					CAST(sales.freesampleqty/im.unitspercase AS UNSIGNED) freesampleqtycase,
					CASE WHEN sales.freesampleqty % im.unitspercase <> 0 THEN sales.freesampleqty % im.unitspercase ELSE 0 END freesampleqtypcs,
					sales.manualfreeqty,
					CAST(sales.manualfreeqty/im.unitspercase AS UNSIGNED) manualfreeqtycase,
					CASE WHEN sales.manualfreeqty % im.unitspercase <> 0 THEN sales.manualfreeqty % im.unitspercase ELSE 0 END manualfreeqtypcs,
					(isd.endstockqty + isd.unloadqty) endqty, 
					CAST((isd.endstockqty + isd.unloadqty)/im.unitspercase AS UNSIGNED) endqtycase, 
					CASE WHEN (isd.endstockqty + isd.unloadqty) % im.unitspercase <> 0 THEN (isd.endstockqty + isd.unloadqty) % im.unitspercase ELSE 0 END endqtypcs,
					(CAST(((isd.beginstockqty + isd.loadqty + isd.loadaddqty)-isd.loadcutqty)/im.unitspercase AS UNSIGNED) * isd.stdsalescaseprice) 
					+ (CASE WHEN ((isd.beginstockqty + isd.loadqty + isd.loadaddqty)-isd.loadcutqty) % im.unitspercase <> 0 THEN
					(((isd.beginstockqty + isd.loadqty + isd.loadaddqty)-isd.loadcutqty) % im.unitspercase) * isd.stdsalesprice ELSE 0 END) truckstockvalue, 
					(CAST((isd.endstockqty + isd.unloadqty)/im.unitspercase AS UNSIGNED) * isd.stdsalescaseprice) + (CASE WHEN (isd.endstockqty + isd.unloadqty) % im.unitspercase <> 0 THEN ((isd.endstockqty + isd.unloadqty) % im.unitspercase) * isd.stdsalesprice ELSE 0 END) endstockvalue
				 FROM startendday sed, 
					routemaster rm, 
					salesman sm, 
					inventorysummarydetail isd,
					itemmaster im, itemgroup ig,
					submajorcategory smc,
					majorcategory mc, 
					(SELECT id.routekey, id.itemcode, COALESCE(SUM(id.salesqty), 0) salesqty,
					COALESCE(SUM(id.returnqty), 0) returnqty, COALESCE(SUM(id.damagedqty), 0) damagedqty,
					COALESCE(SUM(id.expiryqty), 0) expiryqty, COALESCE(SUM(id.freesampleqty), 0) freesampleqty,
					COALESCE(SUM(id.manualfreeqty), 0) manualfreeqty 
					FROM invoicedetail id GROUP BY id.routekey, id.itemcode) sales 
				WHERE sed.routekey = isd.routekey AND 
					sed.routecode = rm.routecode AND
					sed.salesmancode = sm.salesmancode AND 
					im.actualitemcode = isd.itemcode AND
					ig.itemgroupcode = im.itemgroupcode AND
					smc.submajorcategorycode = ig.submajorcategorycode AND 
					mc.majorcategorycode = smc.majorcategorycode AND 
					sales.routekey = isd.routekey
					AND sales.itemcode = isd.itemcode ",in_where," ",orderby_val," ",limit_val) ;
	 
	
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
    END */$$
DELIMITER ;

