/* Procedure structure for procedure `sp_report_tablet_route_activity` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_tablet_route_activity` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_tablet_route_activity`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
DECLARE limitval TEXT DEFAULT "";
SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter FROM (SELECT ci.routecode FROM customerinvoice ci, routemaster rm, salesman sm WHERE 
		rm.routecode = ci.routecode and sm.salesmancode = ci.salesmancode", in_where," group by DATE_FORMAT(ci.transactiondate,'%Y'), DATE_FORMAT(ci.transactiondate,'%m'), DATE_FORMAT(ci.transactiondate,'%M'),
	ci.routecode, rm.routename, ci.salesmancode, sm.salesmanname1) as cnt");
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN
		SET @limitval = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	 CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
	
	  SELECT @new_start_limit AS start_limit,@in_counter AS counter;
	
	SET @dyn_sql = CONCAT("select 
	DATE_FORMAT(ci.transactiondate,'%Y') yearno, 
		DATE_FORMAT(ci.transactiondate,'%m') monthno, DATE_FORMAT(ci.transactiondate,'%M') monthtxt,
	ci.routecode, rm.routename, ci.salesmancode, sm.salesmanname1, sum(ci.invoicebalance) invoicebalance
from customerinvoice ci, routemaster rm, salesman sm
where rm.routecode = ci.routecode and sm.salesmancode = ci.salesmancode",in_where, " group by DATE_FORMAT(ci.transactiondate,'%Y'), DATE_FORMAT(ci.transactiondate,'%m'), DATE_FORMAT(ci.transactiondate,'%M'),
	ci.routecode, rm.routename, ci.salesmancode, sm.salesmanname1 ORDER BY ",in_orderby," ",in_sort, "",limitval) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
	 
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_tablet_salessummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_tablet_salessummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_tablet_salessummary`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter  FROM invoiceheader ih, customermaster cm, routemaster rm, salesman sm WHERE 
		ih.customercode = cm.customercode AND ih.routecode = rm.routecode AND ih.salesmancode = sm.salesmancode", in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	
	 CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
	
	  SELECT @new_start_limit AS start_limit,@in_counter AS counter;
	
	SET @dyn_sql = CONCAT("SELECT
		ih.routekey, ih.visitkey, ih.actualtransactiondate sqltrandate,
		DATE(ih.actualtransactiondate) AS transactiondate, ih.transactiontime, ih.invoicenumber, 
		CASE WHEN ih.paymenttype < 2 THEN 'Cash' WHEN ih.paymenttype = 2 THEN 'Credit' ELSE 'TC' END AS mop,
		CASE WHEN cm.type = 1 THEN '0' WHEN cm.type = 2 THEN (SELECT cm1.reportcustcode FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE '1' END hocode,
		CASE WHEN cm.type = 1 THEN 'normal customers' WHEN cm.type = 2 THEN (SELECT cm1.customername FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE '' END honame,
		cm.reportcustcode customercode, cm.customername, cm.arbcustomername,rm.routecode, rm.routename, rm.arbroutename,
		ih.salesmancode, sm.salesmanname1 salesman,ih.totalsalesamount salesamount, ih.totalreturnamount goodreturnamount, (ih.totaldamagedamount+ih.totalexpiryamount) as totaldamagedamount, 
		ih.totalfreesampleamount + ih.totalmanualfree freeamount, 
		ROUND((ih.totalsalesamount-ih.totalreturnamount-ih.totaldamagedamount-ih.totalexpiryamount) - ih.totalinvoiceamount, 3) discountamount,
		ih.totaldiscountamount discountamount1, 
		ih.totalinvoiceamount invoiceamount, 		
		ih.immediatepaid,
		ih.amountpaid, ih.invoicebalance
	FROM 
		invoiceheader ih, customermaster cm, routemaster rm, salesman sm
	WHERE 
		ih.customercode = cm.customercode AND ih.routecode = rm.routecode AND ih.salesmancode = sm.salesmancode",in_where, " ORDER BY ",in_orderby," ",in_sort, " LIMIT ",@new_start_limit, ",",in_limit) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;		
	
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_tablet_salessummary_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_tablet_salessummary_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_tablet_salessummary_detail`()
BEGIN
CALL sp_combo_routemaster() ;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_tablet_void_transaction` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_tablet_void_transaction` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_tablet_void_transaction`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
SET @dyn_sql = CONCAT("
				SELECT t1.* from (
				SELECT 'Sales' trantype,
		ih.routekey, ih.visitkey, DATE_FORMAT(ih.actualtransactiondate,'%d %b %Y') AS transactiondate, ih.transactiontime, ih.invoicenumber, 
		cm.reportcustcode customercode, cm.customername, rm.routecode, rm.routename, ih.salesmancode, sm.salesmanname1 salesman,
		ih.totalinvoiceamount invoiceamount, ih.immediatepaid amountpaid
	FROM 
		invoiceheader ih, customermaster cm, routemaster rm, salesman sm
	WHERE 
		ih.customercode = cm.customercode AND ih.routecode = rm.routecode AND ih.salesmancode = sm.salesmancode AND ih.voidflag = 1",in_where," 
		
	
	UNION
	
	SELECT 'Collection' trantype,
		ih.routekey, ih.visitkey, DATE_FORMAT(ih.transactiondate,'%d-%b-%Y') AS transactiondate, ih.transactiontime, ih.invoicenumber, 
		cm.reportcustcode customercode, cm.customername, rm.routecode, rm.routename, ih.salesmancode, sm.salesmanname1 salesman,
		ih.totalinvoiceamount invoiceamount, ih.amountpaid
	FROM 
		arheader ih, customermaster cm, routemaster rm, salesman sm
	WHERE 
		ih.customercode = cm.customercode AND ih.routecode = rm.routecode AND ih.salesmancode = sm.salesmancode AND ih.voidflag = 1",in_where,"	
				
					) as t1 ORDER BY t1.",in_orderby," ",in_sort) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_tablet_void_transaction_detail` */

