/* Procedure structure for procedure `sp_report_transaction_deposit_summary` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_deposit_summary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_deposit_summary`(
	IN in_where TEXT,
	IN in_orderby VARCHAR(255),
	IN in_sort VARCHAR(25),
	IN in_limit INT,
	IN in_page INT)
BEGIN
	DECLARE limit_val TEXT DEFAULT "";
	DECLARE in_counter INT(8);
	SET @tablename = "tmp_transaction_deposit_summary";
	
	SET @tmp = CONCAT("DROP TABLE IF EXISTS ",@tablename);
	PREPARE qry FROM @tmp ;
	EXECUTE qry;
	
	SET @tmp = CONCAT("CREATE TABLE IF NOT EXISTS ", @tablename, " AS 
		SELECT 'INVOICE' trantype, ih.transactiondate, ih.routecode, ih.salesmancode, ih.customercode,
			CASE WHEN ccd.typecode = 0 THEN ccd.amount ELSE 0 END AS immediatecash,
			CASE WHEN ccd.typecode = 1 THEN ccd.amount ELSE 0 END AS immediatecheck,
			ccd.amount AS totalamount	
		FROM 
			invoiceheader ih
			INNER JOIN cashcheckdetail ccd ON ccd.routekey = ih.routekey and ccd.visitkey = ih.visitkey
		WHERE 
			ih.voidflag=0 ",in_where, " 
		UNION
		
		SELECT 'RECEIPT' trantype, ih.transactiondate, ih.routecode, ih.salesmancode, ih.customercode,
			CASE WHEN ccd.typecode = 0 THEN ccd.amount ELSE 0 END AS immediatecash,
			CASE WHEN ccd.typecode = 1 THEN ccd.amount ELSE 0 END AS immediatecheck,
			ccd.amount AS totalamount
		FROM 
			arheader ih
			INNER JOIN cashcheckdetail ccd ON ccd.routekey = ih.routekey and ccd.visitkey = ih.visitkey
		WHERE 
			ih.voidflag=0 ",in_where) ;
	 PREPARE qry FROM @tmp;
	 EXECUTE qry;
	SELECT COUNT(cnt.counter) INTO in_counter
	FROM
		(SELECT COUNT(*) AS counter
		FROM tmp_transaction_deposit_summary
		GROUP BY trantype, transactiondate, routecode, salesmancode) cnt;
	SELECT in_counter;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data (in_counter, in_limit, in_page, @new_start_limit);
		SELECT @new_start_limit AS start_limit, in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ", @new_start_limit, ",", in_limit);
	END IF;
	SET @dyn_sql = CONCAT("
		SELECT ih.trantype, ih.transactiondate, rm.routecode, rm.routename, rm.arbroutename, 
			sm.salesmancode, sm.salesmanname1, sm.arbsalesmanname1,
			SUM(ih.immediatecash) immediatecash, SUM(ih.immediatecheck) immediatecheck, SUM(ih.totalamount) AS total	
		FROM " ,@tablename, " ih
			INNER JOIN routemaster rm ON rm.routecode = ih.routecode
			INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
		GROUP BY ih.trantype, ih.transactiondate, rm.routecode, sm.salesmancode
		ORDER BY ",in_orderby," ",in_sort," ",limit_val) ; 
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	-- select @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_dsrsummary_modified_temp` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_dsrsummary_modified_temp` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_dsrsummary_modified_temp`(
 IN routestr TEXT,
 IN fromdate DATE,
 IN todate DATE
)
BEGIN
DROP TABLE IF EXISTS planned_temp;
DROP TABLE IF EXISTS actual_temp;
DROP TABLE IF EXISTS productive_temp;
DROP TABLE IF EXISTS invoicedet_temp;
DROP TABLE IF EXISTS invoiceamount_temp;
DROP TABLE IF EXISTS invoiceqty_temp;
DROP TABLE IF EXISTS routedet_temp;
SET @dyn_sql = CONCAT("CREATE TABLE  planned_temp 
		SELECT  COUNT(DISTINCT rs.customercode) as planned,sed.routecode
		FROM routesequence rs 
		INNER JOIN startendday sed ON sed.routecode=rs.routecode WHERE
		CASE WHEN DAYNAME(sed.routeenddate)='Monday' THEN rs.callrestrictiondays1=1
		WHEN DAYNAME(sed.routeenddate)='Tuesday' THEN rs.callrestrictiondays2=1
		WHEN DAYNAME(sed.routeenddate)='Wednesday' THEN rs.callrestrictiondays3=1
		WHEN DAYNAME(sed.routeenddate)='Thursday' THEN rs.callrestrictiondays4=1
		WHEN DAYNAME(sed.routeenddate)='Friday' THEN rs.callrestrictiondays5=1
		WHEN DAYNAME(sed.routeenddate)='Saturday' THEN rs.callrestrictiondays6=1
		WHEN DAYNAME(sed.routeenddate)='Sunday' THEN rs.callrestrictiondays7=1
		ELSE  0 END AND  sed.routecode IN (",routestr,") AND sed.routeenddate BETWEEN '",fromdate,"' AND '",todate,"' group by sed.routecode");
PREPARE s1 FROM @dyn_sql;
EXECUTE s1;
SET @dyn_sql1 = CONCAT("CREATE TABLE  actual_temp
		SELECT COUNT(DISTINCT rcs.customercode)  as actual,sed.routecode
		FROM startendday sed
		INNER JOIN routesequencecustomerstatus rcs ON rcs.routecode = sed.routecode AND rcs.routekey = sed.routekey AND  rcs.servicedflag = 1
		WHERE  sed.routecode IN (",routestr,") AND sed.routeenddate BETWEEN '",fromdate,"' AND '",todate,"' group by sed.routecode");
PREPARE s2 FROM @dyn_sql1;
EXECUTE s2;
SET @dyn_sql2 = CONCAT("CREATE TABLE  productive_temp
		SELECT sed.routecode,COUNT(DISTINCT coc.customercode)  as productive
		FROM startendday sed
		INNER JOIN customeroperationscontrol coc  ON `coc`.`routekey` = `sed`.`routekey` AND  coc.routecode = sed.routecode AND totaltransactions > 0
		WHERE  sed.routecode IN (",routestr,") AND sed.routeenddate BETWEEN '",fromdate,"' AND '",todate,"' group by sed.routecode");
PREPARE s3 FROM @dyn_sql2;
EXECUTE s3;
SET @dyn_sql3 = CONCAT("CREATE TABLE  invoicedet_temp
		SELECT CASE WHEN routetype = 2 THEN COUNT(DISTINCT soh.invoicenumber) ELSE COUNT(DISTINCT ih.invoicenumber) END  invbilled,sed.routecode,
		CASE WHEN routetype = 2 THEN COUNT(DISTINCT sod.itemcode) ELSE COUNT(DISTINCT id.itemcode) END  as itembilled,
		CASE WHEN routetype = 2 THEN COUNT(DISTINCT soh.customercode) ELSE COUNT(DISTINCT ih.customercode) END  as customerbilled
		FROM  startendday sed
		LEFT JOIN salesorderheader soh ON sed.routekey =soh.routekey AND soh.voidflag = 0
		LEFT JOIN  salesorderdetail sod ON sed.routekey =sod.routekey
		LEFT JOIN invoiceheader ih ON sed.routekey =ih.routekey AND ih.voidflag = 0
		LEFT JOIN invoicedetail id ON sed.routekey =id.routekey
		INNER JOIN routemaster rm ON sed.routecode = rm.routecode
		WHERE  sed.routecode IN (",routestr,") AND (ih.transactiondate BETWEEN '",fromdate,"' AND '",todate,"' OR soh.transactiondate BETWEEN '",fromdate,"' AND '",todate,"') group by  sed.routecode");
		
PREPARE s4 FROM @dyn_sql3;
EXECUTE s4;
SET @dyn_sql4 = CONCAT("CREATE TABLE  invoiceamount_temp
		SELECT CASE WHEN routetype = 2 THEN SUM(soh.totalsalesamount) ELSE SUM(ih.totalinvoiceamount) END  invoiceamt,sed.routecode,
		CASE WHEN routetype = 2 THEN SUM(soh.totalreturnamount) ELSE SUM(ih.totalreturnamount) END  as returnamt,
CASE WHEN routetype = 2 THEN round((sum(soh.totalinvoiceamount)/count(soh.invoicenumber)),3) ELSE round((sum(ih.totalinvoiceamount)/count(ih.invoicenumber)),3)  END  as avginv
		FROM  startendday sed
		LEFT JOIN salesorderheader soh ON sed.routekey =soh.routekey AND soh.voidflag = 0
		LEFT JOIN invoiceheader ih ON sed.routekey =ih.routekey AND ih.voidflag = 0
		INNER JOIN routemaster rm ON sed.routecode = rm.routecode
		WHERE  sed.routecode IN (",routestr,") AND (ih.transactiondate BETWEEN '",fromdate,"' AND '",todate,"' OR soh.transactiondate BETWEEN '",fromdate,"' AND '",todate,"') group by sed.routecode");
		
PREPARE s5 FROM @dyn_sql4;
EXECUTE s5;
SET @dyn_sql5 = CONCAT("CREATE TABLE  invoiceqty_temp
		SELECT sed.routecode,CASE WHEN routetype = 2 THEN SUM(sod.manualfreeqty) ELSE SUM(id.manualfreeqty) END manualfreeqty,
		CASE WHEN routetype = 2 THEN SUM(sod.freesampleqty) ELSE SUM(id.freesampleqty) END freesampleqty FROM  startendday sed 
		LEFT JOIN invoicedetail id ON sed.routekey =id.routekey
		LEFT JOIN salesorderdetail sod ON sed.routekey =sod.routekey
		INNER JOIN routemaster rm ON sed.routecode = rm.routecode
		WHERE  sed.routecode IN (",routestr,") AND sed.routeenddate BETWEEN '",fromdate,"' AND '",todate,"' group by sed.routecode");
		
PREPARE s6 FROM @dyn_sql5;
EXECUTE s6;
SET @dyn_sql6 = CONCAT("CREATE TABLE  routedet_temp
		SELECT rm.routecode AS routecode, rgm.regionmstcode AS regionmstcode, CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.routename) AS route, CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.arbroutename) AS arbroutename,
		CONCAT(CAST(sm.salesmancode AS CHAR) , ' - ' , sm.salesmanname1) AS salesman,  	regionmstname,arbregionmstname,areaname,arbareaname,
		rg.quantity AS mtdtarget,rm.routetype,
		CASE WHEN routetype = 2 THEN (SELECT SUM(totalsalesamount) FROM salesorderheader WHERE  routecode = sed.routecode  AND (voidflag = 0) AND  transactiondate BETWEEN DATE_FORMAT('",fromdate ,"' ,'%Y-%m-01')  AND '",todate,"' GROUP BY routecode)  
		ELSE (SELECT SUM(totalinvoiceamount) FROM invoiceheader WHERE  routecode = sed.routecode  AND (voidflag = 0) AND  transactiondate BETWEEN DATE_FORMAT('",fromdate ,"' ,'%Y-%m-01')  AND '",todate,"' GROUP BY routecode) END  MTDsales,
		CASE WHEN routetype = 2 THEN 
		( SELECT COUNT(DISTINCT customercode) FROM salesorderheader ih WHERE  ih.routecode = sed.routecode  AND (voidflag = 0) AND  transactiondate BETWEEN DATE_SUB('",fromdate ,"' ,INTERVAL 2 MONTH)  AND '",todate,"' GROUP BY routecode ) 
		ELSE ( SELECT COUNT(DISTINCT customercode) FROM invoiceheader ih WHERE  ih.routecode = sed.routecode  AND (voidflag = 0) AND  transactiondate BETWEEN DATE_SUB('",fromdate ,"' ,INTERVAL 2 MONTH)  AND '",todate,"' GROUP BY routecode) END as lastcustomerbilled,
		(SELECT SUM(amountpaid) FROM  arheader ah WHERE ah.routekey = sed.routekey  AND  ah.routecode = sed.routecode AND (ah.voidflag = 0) GROUP BY ah.routekey,routecode) AS collection
		FROM startendday sed	
		LEFT JOIN routegoal  rg ON sed.routecode = rg.routecode
		INNER JOIN routemaster rm ON sed.routecode = rm.routecode
		INNER JOIN subareamaster sam ON sam.subareacode = rm.subareacode
		INNER JOIN areamaster am ON am.areacode = sam.areacode
		INNER JOIN depotmaster dm ON dm.depotcode = am.depotcode
		INNER JOIN regionmaster rgm ON rgm.regionmstcode = dm.regionmstcode
		INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
		WHERE  sed.routecode IN (",routestr,") AND sed.routeenddate BETWEEN '",fromdate,"' AND '",todate,"' ");
PREPARE s7 FROM @dyn_sql6;
EXECUTE s7;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_dsrsummary_temp` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_dsrsummary_temp` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_dsrsummary_temp`(
IN routestr TEXT
)
BEGIN
	SET @dyn_sql = CONCAT("DROP TABLE IF EXISTS dsrsummary_temp");
	PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	SET @dyn_sql = CONCAT("
		CREATE TABLE dsrsummary_temp
	
	SELECT  
sed.routestartdate,rm.routetype, sed.routeenddate,
col.collection,rm.routecode AS routecode, rgm.regionmstcode AS regionmstcode, CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.routename) AS route, CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.arbroutename) AS arbroutename,
CONCAT(CAST(sm.salesmancode AS CHAR) , ' - ' , sm.salesmanname1) AS salesman,  	regionmstname,arbregionmstname,areaname,arbareaname, 
actualvisits,
productivecalls,
rg.quantity AS mtdtarget,
customerbilled,totalreturnamount,invbilled,freesampleqty,manualfreeqty,sales.salesamount,
sed.routestartdate AS transactiondate,itemsbilled
FROM startendday sed
	
INNER JOIN (SELECT sed2.routestartdate,sed2.routecode,COUNT(DISTINCT customercode)customerbilled,SUM(totalreturnamount)totalreturnamount,COUNT(DISTINCT invoicenumber)invbilled,(SELECT SUM(sd.freesampleqty) FROM salesorderdetail sd WHERE sd.transactionkey=ih.transactionkey AND sd.freesampleqty>0)freesampleqty,
(SELECT COUNT(DISTINCT sd.itemcode) FROM salesorderdetail sd WHERE sd.transactionkey=ih.transactionkey )  itemsbilled,
(SELECT SUM(sd.manualfreeqty) FROM salesorderdetail sd WHERE sd.transactionkey=ih.transactionkey AND sd.manualfreeqty>0)manualfreeqty,SUM(ih.totalinvoiceamount)salesamount FROM salesorderheader  ih INNER JOIN startendday sed2 ON sed2.routekey=ih.routekey  WHERE     (voidflag = 0) GROUP BY sed2.routestartdate,sed2.routecode) sales ON sales.routestartdate=sed.routestartdate AND sales.routecode=sed.routecode
INNER JOIN ( SELECT sed2.routestartdate,sed2.routecode,COUNT(DISTINCT customercode)productivecalls FROM customeroperationscontrol coc    INNER JOIN startendday sed2 ON sed2.routekey=coc.routekey  WHERE totaltransactions > 0 GROUP BY sed2.routestartdate,sed2.routecode)  AS pc
ON  pc.routestartdate=sed.routestartdate AND pc.routecode=sed.routecode 
INNER JOIN 
(SELECT sed2.routestartdate,sed2.routecode,COUNT(DISTINCT customercode)actualvisits FROM routesequencecustomerstatus vis  INNER JOIN startendday sed2 ON sed2.routekey=vis.routekey  WHERE vis.servicedflag = 1 GROUP BY sed2.routestartdate,sed2.routecode) AS av
ON  av.routestartdate=sed.routestartdate AND av.routecode=sed.routecode 
INNER JOIN 
(SELECT sed2.routestartdate,sed2.routecode,SUM(amountpaid)collection  FROM  arheader ah INNER JOIN startendday sed2 ON sed2.routekey=ah.routekey WHERE (ah.voidflag = 0) GROUP BY sed2.routestartdate,sed2.routecode)AS col
ON  col.routestartdate=sed.routestartdate AND col.routecode=sed.routecode 
LEFT JOIN routegoal  rg ON sed.routecode = rg.routecode
INNER JOIN routemaster rm ON sed.routecode = rm.routecode
INNER JOIN subareamaster sam ON sam.subareacode = rm.subareacode
INNER JOIN areamaster am ON am.areacode = sam.areacode
INNER JOIN depotmaster dm ON dm.depotcode = am.depotcode
INNER JOIN regionmaster rgm ON rgm.regionmstcode = dm.regionmstcode
INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
WHERE 1=1 ",routestr, " 
");
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
  
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_dsrsummary_temp_07102018` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_dsrsummary_temp_07102018` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_dsrsummary_temp_07102018`(
IN routestr TEXT
)
BEGIN
	SET @dyn_sql = CONCAT("DROP TABLE IF EXISTS dsrsummary_temp");
	PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	SET @dyn_sql = CONCAT("
		CREATE TABLE dsrsummary_temp
		SELECT  
sed.routestartdate,rm.routetype, sed.routeenddate,sed.routekey,
(SELECT SUM(amountpaid) FROM  arheader ah WHERE ah.routekey = sed.routekey  AND  ah.routecode = sed.routecode AND (ah.voidflag = 0) GROUP BY ah.routekey,routecode)AS collection,
rm.routecode AS routecode, rgm.regionmstcode AS regionmstcode, CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.routename) AS route, CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.arbroutename) AS arbroutename,
CONCAT(CAST(sm.salesmancode AS CHAR) , ' - ' , sm.salesmanname1) AS salesman,  	regionmstname,arbregionmstname,areaname,arbareaname, 
(SELECT COUNT(DISTINCT customercode) FROM routesequencecustomerstatus vis WHERE vis.routecode = sed.routecode AND vis.routekey = sed.routekey AND  vis.servicedflag = 1) AS actualvisits,
( SELECT COUNT(DISTINCT customercode) FROM customeroperationscontrol coc  WHERE `coc`.`routekey` = `sed`.`routekey` AND  coc.routecode = sed.routecode AND totaltransactions > 0)  AS productivecalls,  
rg.quantity AS mtdtarget,
CASE WHEN rm.routetype = 2 THEN
(SELECT COUNT(DISTINCT customercode) FROM salesorderheader WHERE  routekey = sed.routekey  AND (voidflag = 0) GROUP BY routekey, routecode)
ELSE 
(SELECT COUNT(DISTINCT customercode) FROM invoiceheader WHERE  routekey = sed.routekey  AND (voidflag = 0) GROUP BY routekey, routecode)
 END customerbilled,
 
CASE WHEN rm.routetype = 2 THEN
(SELECT transactiondate FROM salesorderheader WHERE  routekey = sed.routekey  AND (voidflag = 0) GROUP BY routekey, routecode)
ELSE 
(SELECT transactiondate FROM invoiceheader WHERE  routekey = sed.routekey  AND (voidflag = 0) GROUP BY routekey, routecode)
 END transactiondate,
CASE WHEN rm.routetype = 2 THEN
(SELECT totalreturnamount FROM salesorderheader WHERE  routekey = sed.routekey  AND (voidflag = 0) GROUP BY routekey, routecode)
ELSE 
(SELECT totalreturnamount FROM invoiceheader WHERE  routekey = sed.routekey  AND (voidflag = 0) GROUP BY routekey, routecode)
 END totalreturnamount,
CASE WHEN rm.routetype = 2 THEN
(SELECT COUNT(DISTINCT invoicenumber) FROM salesorderheader WHERE  routekey = sed.routekey  AND (voidflag = 0) GROUP BY routekey, routecode)
ELSE (SELECT COUNT(DISTINCT invoicenumber) FROM invoiceheader WHERE  routekey = sed.routekey  AND (voidflag = 0) GROUP BY routekey, routecode)
 END invbilled,
(SELECT SUM(freesampleqty) FROM salesorderdetail WHERE  routekey =sed.routekey  GROUP BY routekey) AS freesampleqty,
(SELECT SUM(manualfreeqty) FROM salesorderdetail WHERE  routekey = sed.routekey  GROUP BY routekey) AS manualfreeqty,
CASE WHEN rm.routetype = 2 THEN (SELECT SUM(totalsalesamount) FROM salesorderheader WHERE  routekey = sed.routekey  AND (voidflag = 0) GROUP BY routekey, routecode)  ELSE (SELECT SUM(totalinvoiceamount) FROM invoiceheader WHERE  routekey = sed.routekey  AND (voidflag = 0) GROUP BY routekey, routecode) END salesamount
FROM startendday sed	
LEFT JOIN routegoal  rg ON sed.routecode = rg.routecode
INNER JOIN routemaster rm ON sed.routecode = rm.routecode
INNER JOIN subareamaster sam ON sam.subareacode = rm.subareacode
INNER JOIN areamaster am ON am.areacode = sam.areacode
INNER JOIN depotmaster dm ON dm.depotcode = am.depotcode
INNER JOIN regionmaster rgm ON rgm.regionmstcode = dm.regionmstcode
INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
WHERE 1=1 ",routestr, " 
GROUP BY sed.routekey, sed.routecode,sm.salesmancode, rgm.regionmstcode");
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
 
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_dsrsummary_temp_27082018` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_dsrsummary_temp_27082018` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_dsrsummary_temp_27082018`(
)
BEGIN
	SET @dyn_sql = CONCAT("DROP TABLE dsrsummary_temp");
	PREPARE s1 FROM @dyn_sql;
	  EXECUTE s1;
	SET @dyn_sql = CONCAT("
		CREATE TABLE dsrsummary_temp
		SELECT  
sed.routestartdate, sed.routeenddate,sed.routekey,ih.transactiondate,ih.totalsalesamount,ih.totalreturnamount,ah.amountpaid AS collection,
rm.routecode AS routecode, rgm.regionmstcode AS regionmstcode, CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.routename) AS route, CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.arbroutename) AS arbroutename,
CONCAT(CAST(sm.salesmancode AS CHAR) , ' - ' , sm.salesmanname1) AS salesman,  	regionmstname,arbregionmstname,areaname,arbareaname,
(SELECT COUNT(DISTINCT customercode) FROM routesequencecustomerstatus rcs WHERE rcs.routecode = sed.routecode AND rcs.routekey = sed.routekey AND  rcs.schelduledflag = 1) AS plannedvisit,
(SELECT COUNT(DISTINCT customercode) FROM routesequencecustomerstatus vis WHERE vis.routecode = sed.routecode AND vis.routekey = sed.routekey AND  vis.servicedflag = 1) AS actualvisits,
( SELECT COUNT(DISTINCT customercode) FROM customeroperationscontrol coc  WHERE `coc`.`routekey` = `sed`.`routekey` AND  coc.routecode = sed.routecode AND totaltransactions > 0)  AS productivecalls,  
rg.quantity AS mtdtarget,
COUNT(DISTINCT ih.customercode) AS customerbilled,
COUNT(DISTINCT ih.invoicenumber) AS invbilled,
( SELECT COUNT(DISTINCT itemcode) FROM salesorderdetail WHERE routekey =sed.routekey GROUP BY routekey ) AS itembilled,
(SELECT SUM(freesampleqty) FROM salesorderdetail WHERE  routekey =sed.routekey  GROUP BY routekey) AS freesampleqty,
(SELECT SUM(manualfreeqty) FROM salesorderdetail WHERE  routekey = sed.routekey  GROUP BY routekey) AS manualfreeqty,
(SELECT ROUND((SUM(totalinvoiceamount)/COUNT(invoicenumber)),3) FROM salesorderheader  WHERE routekey = sed.routekey  AND (voidflag = 0) GROUP BY routekey, routecode) AS avginv,
(SELECT SUM(totalsalesamount) FROM salesorderheader WHERE  routekey = sed.routekey  AND (voidflag = 0) GROUP BY routekey, routecode) AS salesamount
FROM startendday sed	
LEFT JOIN routegoal  rg ON sed.routecode = rg.routecode
INNER JOIN salesorderheader ih ON ih.routecode = sed.routecode AND ih.routekey = sed.routekey  AND (ih.voidflag = 0)
LEFT JOIN arheader ah ON ah.routekey = ih.routekey  AND  ah.routecode = sed.routecode AND (ah.voidflag = 0)
INNER JOIN routemaster rm ON sed.routecode = rm.routecode
INNER JOIN subareamaster sam ON sam.subareacode = rm.subareacode
INNER JOIN areamaster am ON am.areacode = sam.areacode
INNER JOIN depotmaster dm ON dm.depotcode = am.depotcode
INNER JOIN regionmaster rgm ON rgm.regionmstcode = dm.regionmstcode
INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
GROUP BY sed.routekey, sed.routecode,sm.salesmancode, rgm.regionmstcode");
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
 
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_dsrsummary_temp_270918` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_dsrsummary_temp_270918` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_dsrsummary_temp_270918`(
IN routestr TEXT
)
BEGIN
	SET @dyn_sql = CONCAT("DROP TABLE dsrsummary_temp");
	PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	SET @dyn_sql = CONCAT("
		CREATE TABLE dsrsummary_temp
		SELECT  
sed.routestartdate, sed.routeenddate,sed.routekey,ih.transactiondate,ih.totalsalesamount,ih.totalreturnamount,ah.amountpaid AS collection,
rm.routecode AS routecode, rgm.regionmstcode AS regionmstcode, CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.routename) AS route, CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.arbroutename) AS arbroutename,
CONCAT(CAST(sm.salesmancode AS CHAR) , ' - ' , sm.salesmanname1) AS salesman,  	regionmstname,arbregionmstname,areaname,arbareaname,
(SELECT COUNT(DISTINCT customercode) FROM routesequencecustomerstatus rcs WHERE rcs.routecode = sed.routecode AND rcs.routekey = sed.routekey AND  rcs.schelduledflag = 1) AS plannedvisit,
(SELECT COUNT(DISTINCT customercode) FROM routesequencecustomerstatus vis WHERE vis.routecode = sed.routecode AND vis.routekey = sed.routekey AND  vis.servicedflag = 1) AS actualvisits,
( SELECT COUNT(DISTINCT customercode) FROM customeroperationscontrol coc  WHERE `coc`.`routekey` = `sed`.`routekey` AND  coc.routecode = sed.routecode AND totaltransactions > 0)  AS productivecalls,  
rg.quantity AS mtdtarget,
COUNT(DISTINCT ih.customercode) AS customerbilled,
COUNT(DISTINCT ih.invoicenumber) AS invbilled,
( SELECT COUNT(DISTINCT itemcode) FROM salesorderdetail WHERE routekey =sed.routekey GROUP BY routekey ) AS itembilled,
(SELECT SUM(freesampleqty) FROM salesorderdetail WHERE  routekey =sed.routekey  GROUP BY routekey) AS freesampleqty,
(SELECT SUM(manualfreeqty) FROM salesorderdetail WHERE  routekey = sed.routekey  GROUP BY routekey) AS manualfreeqty,
(SELECT ROUND((SUM(totalinvoiceamount)/COUNT(invoicenumber)),3) FROM salesorderheader  WHERE routekey = sed.routekey  AND (voidflag = 0) GROUP BY routekey, routecode) AS avginv,
(SELECT SUM(totalsalesamount) FROM salesorderheader WHERE  routekey = sed.routekey  AND (voidflag = 0) GROUP BY routekey, routecode) AS salesamount
FROM startendday sed	
LEFT JOIN routegoal  rg ON sed.routecode = rg.routecode
LEFT JOIN salesorderheader ih ON ih.routecode = sed.routecode AND ih.routekey = sed.routekey  AND (ih.voidflag = 0)
LEFT OUTER JOIN arheader ah ON ah.routekey = sed.routekey  AND  ah.routecode = sed.routecode AND (ah.voidflag = 0)
INNER JOIN routemaster rm ON sed.routecode = rm.routecode
INNER JOIN subareamaster sam ON sam.subareacode = rm.subareacode
INNER JOIN areamaster am ON am.areacode = sam.areacode
INNER JOIN depotmaster dm ON dm.depotcode = am.depotcode
INNER JOIN regionmaster rgm ON rgm.regionmstcode = dm.regionmstcode
INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
AND 1=1 ",routestr, " 
GROUP BY sed.routekey, sed.routecode,sm.salesmancode, rgm.regionmstcode");
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
 
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_foc` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_foc` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_foc`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter FROM invoiceheader ih, routemaster rm, customermaster cm WHERE 
		ih.routecode = rm.routecode AND ih.customercode = cm.customercode AND ih.totalfreesampleamount > 0 ", in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	
	SET @dyn_sql = CONCAT("SELECT
		ih.actualtransactiondate actualtransactiondate,ih.transactiontime,ih.invoicenumber, ih.routecode, rm.routename, rm.arbroutename, ih.salesmancode, 
		cm.alternatecode customercode, cm.customername, cm.arbcustomername,
		CASE WHEN cm.type = 1 THEN '0' WHEN cm.type = 2 THEN (SELECT cm1.reportcustcode FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE '1' END hocode,
		CASE WHEN cm.type = 1 THEN 'normal customers' WHEN cm.type = 2 THEN (SELECT cm1.customername FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE '' END honame,
		ih.totalinvoiceamount,
		ih.totalsalesamount,
		ih.totaldiscountamount,
		ih.totalfreesampleamount+ totalmanualfree totalfreesampleamount,
		(ih.totalinvoiceamount-IFNULL(ih.totaldiscountamount,0)) AS netamount		
	FROM 
		invoiceheader ih, routemaster rm, customermaster cm
	WHERE 
		ih.routecode = rm.routecode AND ih.customercode = cm.customercode AND ih.totalfreesampleamount + totalmanualfree > 0 ",in_where, " ORDER BY ih.invoicenumber");
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
select @dyn_sql;	 
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_itemhistory` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_itemhistory` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_itemhistory`(
	IN in_where TEXT,
	IN in_orderby VARCHAR(500),
	IN in_sort VARCHAR(50),
	IN in_limit INT,
	IN in_page INT)
BEGIN
	DECLARE limit_val TEXT DEFAULT "";
	DECLARE in_counter INT(8);
	
	SET @tablename = "tmp_transaction_itemhistory_report";
	
	SET @tmp = CONCAT("DROP TABLE IF EXISTS ",@tablename);
	PREPARE qry FROM @tmp ;
	EXECUTE qry;
	
	SELECT CODE INTO @damage FROM expiryreturnreasons WHERE UPPER(description) LIKE '%DAMAGE%' LIMIT 1;
	SELECT CODE INTO @expiry FROM expiryreturnreasons WHERE UPPER(description) LIKE '%EXPIRY%' LIMIT 1;
	
	SET @tmp = CONCAT(" CREATE TABLE IF NOT EXISTS ", @tablename, " AS 
		SELECT 
			sed.routekey, 
			DATE_FORMAT(sed.routestartdate, '%d %b %Y') AS routestartdate, 
			DATE_FORMAT(sed.routeenddate, '%d %b %Y') AS routeenddate, 
			sed.routecode, rm.routename, rm.arbroutename, sed.salesmancode, sm.salesmanname1 salesman,
			mc.majorcategorycode,mc.description majorcategroy,
			im.alternatecode itemcode, im.itemdescription,im.arbitemdescription, im.unitspercase upc, 
			isd.stdsalescaseprice caseprice, isd.stdsalesprice pcsprice, 
			isd.beginstockqty, isd.loadqty, isd.loadaddqty, isd.loadcutqty, isd.loadaddqty transferin, isd.loadcutqty transferout, 
			coalesce(sales.salesqty,0) salesqty, coalesce(sales.returnqty,0) returnqty, coalesce(sales.damagedqty,0) damagedqty, coalesce(sales.freesampleqty,0) freesampleqty, 
			(isd.endstockqty + isd.unloadqty) vanstock,
			(isd.damageqty - isd.damagedunloadqty) damagevariance
		FROM 
			startendday sed
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
			INNER JOIN inventorysummarydetail isd ON isd.routekey = sed.routekey
			INNER JOIN itemmaster im ON im.actualitemcode = isd.itemcode
			INNER JOIN itemgroup ig ON ig.itemgroupcode = im.itemgroupcode
			INNER JOIN submajorcategory smc ON smc.submajorcategorycode = ig.submajorcategorycode
			INNER JOIN majorcategory mc ON mc.majorcategorycode = smc.majorcategorycode
			LEFT OUTER JOIN 
			(SELECT id.routekey, id.itemcode, COALESCE(SUM(id.salesqty), 0) salesqty, COALESCE(SUM(id.returnqty), 0) returnqty, 
				COALESCE(SUM(id.damagedqty), 0) damagedqty, COALESCE(SUM(id.expiryqty), 0) expiryqty, COALESCE(SUM(id.freesampleqty), 0) freesampleqty, 
				COALESCE(SUM(id.manualfreeqty), 0) manualfreeqty
			 FROM invoicedetail id 
				INNER JOIN invoiceheader ih ON ih.transactionkey = id.transactionkey AND ih.voidflag = 0
			 GROUP BY id.routekey, id.itemcode) sales ON sales.routekey = isd.routekey AND sales.itemcode = isd.itemcode
		WHERE 
			1=1 ", in_where) ;
	 PREPARE qry FROM @tmp;
	 EXECUTE qry;	
	
	SELECT COUNT(cnt.counter) INTO in_counter
	FROM
	(SELECT COUNT(*) AS counter
	FROM tmp_transaction_itemhistory_report
	GROUP BY routekey, routestartdate, routeenddate, routecode,majorcategorycode, itemcode) cnt;
	SELECT in_counter;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data (in_counter, in_limit, in_page, @new_start_limit);
		SELECT @new_start_limit AS start_limit, in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ", @new_start_limit, ",", in_limit);
	END IF;
	
	SET @tmp = CONCAT("
		SELECT 
			routekey, routestartdate, routeenddate, 
			routecode, routename, arbroutename, salesmancode, salesman,
			majorcategorycode, majorcategroy,
			itemcode, itemdescription, arbitemdescription, upc,
			-- beginstockqty, loadqty, transferin, transferout, salesqty, returnqty, damagedqty, freesampleqty, vanstock, 
			CONCAT(FLOOR(beginstockqty/upc),'/',(CASE WHEN beginstockqty MOD upc <> 0 THEN beginstockqty MOD upc ELSE 0 END)) openingqty,		
			-- (FLOOR(beginstockqty/upc) * caseprice) + (CASE WHEN beginstockqty MOD upc <> 0 THEN (beginstockqty MOD upc) * pcsprice ELSE 0 END) openingvalue,
			CONCAT(FLOOR(loadqty/upc),'/',(CASE WHEN loadqty MOD upc <> 0 THEN loadqty MOD upc ELSE 0 END)) loadqty,		
			-- (FLOOR(loadqty/upc) * caseprice) + (CASE WHEN loadqty MOD upc <> 0 THEN (loadqty MOD upc) * pcsprice ELSE 0 END) loadvalue,
			CONCAT(FLOOR(transferin/upc),'/',(CASE WHEN transferin MOD upc <> 0 THEN transferin MOD upc ELSE 0 END)) transferinqty,		
			-- (FLOOR(transferin/upc) * caseprice) + (CASE WHEN transferin MOD upc <> 0 THEN (transferin MOD upc) * pcsprice ELSE 0 END) transferinvalue,
			CONCAT(FLOOR(transferout/upc),'/',(CASE WHEN transferout MOD upc <> 0 THEN transferout MOD upc ELSE 0 END)) transferoutqty,		
			-- (FLOOR(transferout/upc) * caseprice) + (CASE WHEN transferout MOD upc <> 0 THEN (transferout MOD upc) * pcsprice ELSE 0 END) transferoutvalue,
			CONCAT(FLOOR(salesqty/upc),'/',(CASE WHEN salesqty MOD upc <> 0 THEN salesqty MOD upc ELSE 0 END)) saleqty,
			CONCAT(FLOOR(returnqty/upc),'/',(CASE WHEN returnqty MOD upc <> 0 THEN returnqty MOD upc ELSE 0 END)) retqty,
			CONCAT(FLOOR(damagedqty/upc),'/',(CASE WHEN damagedqty MOD upc <> 0 THEN damagedqty MOD upc ELSE 0 END)) dmgqty,
			CONCAT(FLOOR(freesampleqty/upc),'/',(CASE WHEN freesampleqty MOD upc <> 0 THEN freesampleqty MOD upc ELSE 0 END)) freeqty,
			CONCAT(FLOOR(vanstock/upc),'/',(CASE WHEN vanstock MOD upc <> 0 THEN vanstock MOD upc ELSE 0 END)) vanstockqty,		
			(FLOOR(vanstock/upc) * caseprice) + (CASE WHEN vanstock MOD upc <> 0 THEN (vanstock MOD upc) * pcsprice ELSE 0 END) vanstockvalue,
			CONCAT(FLOOR(damagevariance/upc),'/',(CASE WHEN damagevariance MOD upc <> 0 THEN damagevariance MOD upc ELSE 0 END)) damagevariancestock,		
			((damagevariance/upc) * caseprice) + (CASE WHEN damagevariance MOD upc <> 0 THEN (damagevariance MOD upc) * pcsprice ELSE 0 END) damagevariancevalue
		FROM ", @tablename, "
		GROUP BY routekey, routestartdate, routeenddate, routecode, routename, arbroutename, salesmancode, salesman,
			majorcategorycode, majorcategroy, itemcode, itemdescription, arbitemdescription, upc
		ORDER BY ",in_orderby," ",in_sort," ",limit_val) ;
	 PREPARE qry FROM @tmp;
	 EXECUTE qry;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_itemhistory_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_itemhistory_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_itemhistory_detail`()
BEGIN
	CALL sp_combo_routemaster() ;
	call sp_combo_itemmaster();
	call sp_combo_majorcategory();
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_ordersummery` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_ordersummery` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_ordersummery`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT
)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter 
			FROM
				salesorderheader soh, customermaster cm, routemaster rm, salesman sm
			WHERE
				soh.customercode = cm.customercode AND soh.routecode = rm.routecode 
				AND soh.salesmancode = sm.salesmancode ", in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	
	 IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	
	SET @dyn_sql = CONCAT("SELECT
					soh.routekey, soh.visitkey, soh.transactiondate sqltrandate,
					DATE_FORMAT(soh.transactiondate,'%d-%b-%Y') AS transactiondate, soh.transactiontime, soh.invoicenumber,
					CASE WHEN soh.paymenttype < 2 THEN 'CASH' WHEN soh.paymenttype = 2 THEN 'CREDIT' ELSE 'TC' END AS mop,
					CASE WHEN cm.type = 1 THEN '0' WHEN cm.type = 2 THEN (SELECT cm1.reportcustcode FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE '1' END hocode,
					CASE WHEN cm.type = 1 THEN 'normal customers' WHEN cm.type = 2 THEN (SELECT cm1.customername FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE '' END honame,
					cm.reportcustcode customercode, cm.customername, rm.routecode, rm.routename, soh.salesmancode, sm.salesmanname1 salesman,
					soh.totalsalesamount AS salesamount, soh.totalreturnamount AS goodreturnamount, soh.totaldamagedamount,
					soh.totalfreesampleamount AS freeamount,
					ROUND((soh.totalsalesamount-soh.totalreturnamount-soh.totaldamagedamount) - soh.totalinvoiceamount, 3) AS discountamount,
					soh.totalinvoiceamount AS invoiceamount, '00:00:00' receivedtime
				FROM
					salesorderheader soh, customermaster cm, routemaster rm, salesman sm
				WHERE
					soh.customercode = cm.customercode AND soh.routecode = rm.routecode 
					AND soh.salesmancode = sm.salesmancode
		",in_where, " ORDER BY ",in_orderby," ",in_sort, " ", limit_val) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;		
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_ordersummery_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_ordersummery_detail` */;

