)
BEGIN
CALL sp_combo_routemaster() ;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_paymentsummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_paymentsummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_paymentsummary`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
DECLARE limitval TEXT DEFAULT "";
    SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter  FROM invoiceheader ih, customermaster cm, routemaster rm, salesman sm
	WHERE 
		cm.customercode = ih.customercode AND rm.routecode = ih.routecode AND sm.salesmancode = ih.salesmancode", in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN
		SET @limitval = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	 CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
	
	  SELECT @new_start_limit AS start_limit,@in_counter AS counter;
	
	SET @dyn_sql = CONCAT("
	SELECT 
		DATE_FORMAT(ih.actualtransactiondate, '%d %b %Y') AS transactiondate, ih.routecode, rm.routename, rm.arbroutename, 
		ih.salesmancode, sm.salesmanname1,  sm.arbsalesmanname1,
		ih.transactiontime, cm.reportcustcode customercode, cm.customername,cm.arbcustomername, ih.invoicenumber, ih.totalinvoiceamount,
		CASE WHEN ih.paymenttype < 2 THEN 'CASH' WHEN ih.paymenttype = 2 THEN 'CREDIT' ELSE 'TC' END AS mop,
		CASE WHEN cm.type = 1 THEN '0' WHEN cm.type = 2 THEN (SELECT cm1.reportcustcode FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE '1' END hocode,
		CASE WHEN cm.type = 1 THEN 'NORMAL CUSTOMERS' WHEN cm.type = 2 THEN (SELECT cm1.customername FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE '-' END honame,
		CASE WHEN cm.type = 1 THEN 'NORMAL CUSTOMERS' WHEN cm.type = 2 THEN (SELECT cm1.arbcustomername FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE '-' END arbhoname,
		COALESCE((SELECT SUM(ccd.amount) FROM cashcheckdetail ccd WHERE ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey AND ccd.typecode = 0), 0) AS immediatecash,
		COALESCE((SELECT SUM(ccd.amount) FROM cashcheckdetail ccd WHERE ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey AND ccd.typecode = 1), 0) AS immediatecheck,
		COALESCE((SELECT SUM(ard.amountpaid) FROM ardetail ard WHERE ard.alternateinvoicenumber = CAST(ih.invoicenumber AS CHAR)), 0) AS artotalpaid,
		COALESCE((SELECT SUM(ard.amountpaid) FROM ardetail ard, cashcheckdetail ccd WHERE ard.routekey = ccd.routekey AND ard.visitkey = ccd.visitkey AND ccd.typecode = 0 AND ard.invoicenumber = ih.invoicenumber), 0) arcash,
		COALESCE((SELECT SUM(ard.amountpaid) FROM ardetail ard, cashcheckdetail ccd WHERE ard.routekey = ccd.routekey AND ard.visitkey = ccd.visitkey AND ccd.typecode = 1 AND ard.invoicenumber = ih.invoicenumber), 0) archeck
	FROM 
		invoiceheader ih
		INNER JOIN customermaster cm ON cm.customercode = ih.customercode
		INNER JOIN routemaster rm ON rm.routecode = ih.routecode
		INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
	WHERE 
		ih.voidflag = 0 ",in_where, " ORDER BY ",in_orderby," ",in_sort,limitval) ;
			 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_paymentsummary_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_paymentsummary_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_paymentsummary_detail`()
BEGIN
CALL sp_combo_routemaster() ;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_penaltysalessummary_with_permission` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_penaltysalessummary_with_permission` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_penaltysalessummary_with_permission`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT,
	IN username TEXT
)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
SET @extrawhere = CONCAT(" and rm.subareacode IN (SELECT DISTINCT subareacode  FROM `useraccesscodes` WHERE username='", username ,"')");
		SET in_where=CONCAT(in_where,@extrawhere);
SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter 
			FROM
				invoiceheader ih
					INNER JOIN customermaster cm ON cm.customercode = ih.customercode
					INNER JOIN routemaster rm ON rm.routecode = ih.routecode
					INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
			WHERE
				ih.voidflag = 0 ", in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	 IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	 END IF;
	
	SET @dyn_sql = CONCAT("SELECT
					ih.routekey, ih.visitkey, ih.actualtransactiondate sqltrandate,
					DATE_FORMAT(ih.actualtransactiondate,'%d-%b-%Y') AS transactiondate, ih.transactiontime, ih.invoicenumber,
					
					cm.alternatecode customercode, cm.customername,cm.arbcustomername, rm.routecode, rm.routename,rm.arbroutename, ih.salesmancode, sm.salesmanname1 salesman,
					id.itemcode,im.itemdescription,id.salesqty,id.salesprice,
					ih.totalinvoiceamount AS invoiceamount
					
							
				FROM
					invoiceheader ih
					INNER JOIN invoicedetail id ON ih.routekey = id.routekey AND ih.visitkey = id.visitkey
					INNER JOIN itemmaster im ON id.itemcode = im.actualitemcode
					INNER JOIN customermaster cm ON cm.customercode = ih.customercode
					INNER JOIN routemaster rm ON rm.routecode = ih.routecode
					INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
				WHERE
					ih.voidflag = 0 and ih.dexflag=1 ",in_where, "  ORDER BY ih.invoicenumber ASC") ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
	 SELECT @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_penaltysalessummary_with_permission1` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_penaltysalessummary_with_permission1` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_penaltysalessummary_with_permission1`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT,
	IN username TEXT
)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
SET @extrawhere = CONCAT(" and rm.subareacode IN (SELECT DISTINCT subareacode  FROM `useraccesscodes` WHERE username='", username ,"')");
		SET in_where=CONCAT(in_where,@extrawhere);
SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter 
			FROM
				invoiceheader ih
					INNER JOIN customermaster cm ON cm.customercode = ih.customercode
					INNER JOIN routemaster rm ON rm.routecode = ih.routecode
					INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
			WHERE
				ih.voidflag = 0 ", in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	 IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	 END IF;
	
	SET @dyn_sql = CONCAT("SELECT
					ih.routekey, ih.visitkey, ih.actualtransactiondate sqltrandate,
					DATE_FORMAT(ih.actualtransactiondate,'%d-%b-%Y') AS transactiondate, ih.transactiontime, ih.invoicenumber,
					
					cm.alternatecode customercode, cm.customername,cm.arbcustomername, rm.routecode, rm.routename,rm.arbroutename, ih.salesmancode, sm.salesmanname1 salesman,
					id.itemcode,im.itemdescription,id.salesqty,id.salesprice,
					ih.totalinvoiceamount AS netamount,
					
							
				FROM
					invoiceheader ih
					INNER JOIN invoicedetail id ON ih.routekey = id.routekey AND ih.visitkey = id.visitkey
					INNER JOIN itemmaster im ON id.itemcode = im.actualitemcode
					INNER JOIN customermaster cm ON cm.customercode = ih.customercode
					INNER JOIN routemaster rm ON rm.routecode = ih.routecode
					INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
				WHERE
					ih.voidflag = 0 and ih.dexflag=1 ",in_where, " GROUP BY ih.routekey,ih.visitkey ORDER BY ih.invoicenumber") ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
	 SELECT @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_penaltysalessummary_with_permissionbk` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_penaltysalessummary_with_permissionbk` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_penaltysalessummary_with_permissionbk`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT,
	IN username TEXT
)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
SET @extrawhere = CONCAT(" and rm.subareacode IN (SELECT DISTINCT subareacode  FROM `useraccesscodes` WHERE username='", username ,"')");
		SET in_where=CONCAT(in_where,@extrawhere);
SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter 
			FROM
				invoiceheader ih
					INNER JOIN customermaster cm ON cm.customercode = ih.customercode
					INNER JOIN routemaster rm ON rm.routecode = ih.routecode
					INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
			WHERE
				ih.voidflag = 0 ", in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	 IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	 END IF;
	
	SET @dyn_sql = CONCAT("SELECT
					ih.routekey, ih.visitkey, ih.actualtransactiondate sqltrandate,
					DATE_FORMAT(ih.actualtransactiondate,'%d-%b-%Y') AS transactiondate, ih.transactiontime, ih.invoicenumber,
					CASE WHEN cm.invoicepaymentterms < 2 THEN 'CASH' WHEN cm.invoicepaymentterms = 2 THEN 'CREDIT' ELSE 'TC' END AS mop,
					cm.alternatecode customercode, cm.customername,cm.arbcustomername, rm.routecode, rm.routename,rm.arbroutename, ih.salesmancode, sm.salesmanname1 salesman,
					ih.totalsalesamount AS salesamount, ih.totalreturnamount AS goodreturnamount, ih.totaldamagedamount, ih.totalexpiryamount,
					SUM(FLOOR((freesampleqty+manualfreeqty)/im.unitspercase)) * im.caseprice AS freeamount,
					ROUND((ih.totalsalesamount-ih.totalreturnamount-ih.totaldamagedamount-ih.totalexpiryamount) - ih.totalinvoiceamount, 3) AS discountamount,
					ih.totaldiscountamount AS discountamount1,
					ih.totalinvoiceamount AS invoiceamount,
					ih.immediatepaid,
					ih.amountpaid, ih.invoicebalance,
					SUM(promoamount) as totallinediscount,
					SUM(FLOOR(salesqty/im.unitspercase)) as salescase,	SUM((salesqty%im.unitspercase)) as salespcs,	
					SUM(FLOOR(returnqty/im.unitspercase)) as returncase,	SUM((returnqty%im.unitspercase)) as returnpcs,
					SUM(FLOOR(damagedqty/im.unitspercase)) as damagedcase,	SUM((damagedqty%im.unitspercase)) as damagedpcs,
					SUM(FLOOR((freesampleqty+manualfreeqty)/im.unitspercase)) as freecase,	SUM(((freesampleqty+manualfreeqty)%im.unitspercase)) as freepcs,id.itemcode,im.itemdescription		
				FROM
					invoiceheader ih
					INNER JOIN invoicedetail id ON ih.routekey = id.routekey AND ih.visitkey = id.visitkey
					INNER JOIN itemmaster im ON id.itemcode = im.actualitemcode
					INNER JOIN customermaster cm ON cm.customercode = ih.customercode
					INNER JOIN routemaster rm ON rm.routecode = ih.routecode
					INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
				WHERE
					ih.voidflag = 0 and ih.dexflag=1 ",in_where, " GROUP BY ih.routekey,ih.visitkey ORDER BY ih.invoicenumber") ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
	 SELECT @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_returnsummery` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_returnsummery` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_returnsummery`(
	IN in_where TEXT,
	IN in_orderby VARCHAR(500),
	IN in_sort VARCHAR(50),
	IN in_limit INT,
	IN in_page INT)
BEGIN
	DECLARE limit_val TEXT DEFAULT "";
	DECLARE in_counter INT(8);
	
	SET @tablename = "tmp_itemreturn_summary_report";
	
	SET @tmp = CONCAT("DROP TABLE IF EXISTS ",@tablename);
	PREPARE qry FROM @tmp ;
	EXECUTE qry;
	
	SELECT CODE INTO @damage FROM expiryreturnreasons WHERE UPPER(description) LIKE '%DAMAGE%' LIMIT 1;
	SELECT CODE INTO @expiry FROM expiryreturnreasons WHERE UPPER(description) LIKE '%EXPIRY%' LIMIT 1;
	
	SET @tmp = CONCAT(" CREATE TABLE IF NOT EXISTS ", @tablename, " AS 
		SELECT
			ih.transactiondate, ih.routecode, rm.routename, rm.arbroutename, ih.salesmancode, sm.salesmanname1 salesman, cm.alternatecode customercode,
			mc.majorcategorycode, mc.description majorcategroy, im.alternatecode itemcode, im.itemdescription, im.unitspercase upc,
			COALESCE(dmg.quantity, 0) damagedqty, COALESCE(exp.quantity, 0) expiredqty, COALESCE(oth.quantity, 0) otherdamagedqty, 
			id.returnprice, id.returncaseprice
		FROM
			invoiceheader ih 
			INNER JOIN invoicedetail id ON id.transactionkey = ih.transactionkey AND ih.voidflag = 0
			INNER JOIN routemaster rm ON rm.routecode = ih.routecode
			INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
			INNER JOIN customermaster cm ON cm.customercode = ih.customercode
			INNER JOIN itemmaster im ON id.itemcode = im.actualitemcode
			INNER JOIN itemgroup ig ON  ig.itemgroupcode = im.itemgroupcode
			INNER JOIN submajorcategory sc ON sc.submajorcategorycode = ig.submajorcategorycode
			INNER JOIN majorcategory mc ON mc.majorcategorycode = sc.majorcategorycode
			
			LEFT OUTER JOIN (SELECT transactionkey, itemcode, SUM(quantity) quantity
				FROM  invoicerxddetail WHERE itemtransactiontype = 2 and reasoncode = ", @damage," GROUP BY transactionkey, itemcode) dmg ON dmg.transactionkey = id.transactionkey AND dmg.itemcode = id.itemcode
			
			LEFT OUTER JOIN (SELECT transactionkey, itemcode, SUM(quantity) quantity
				FROM  invoicerxddetail WHERE itemtransactiontype = 2 and reasoncode = ", @expiry," GROUP BY transactionkey, itemcode) exp ON exp.transactionkey = id.transactionkey AND exp.itemcode = id.itemcode
			
			LEFT OUTER JOIN (SELECT transactionkey, itemcode, SUM(quantity) quantity
				FROM  invoicerxddetail WHERE itemtransactiontype = 2 and reasoncode NOT IN ( ", @expiry, ",", @damage,") GROUP BY transactionkey, itemcode) oth ON oth.transactionkey = id.transactionkey AND oth.itemcode = id.itemcode
		WHERE 
			COALESCE(dmg.quantity, 0) + COALESCE(exp.quantity, 0) + COALESCE(oth.quantity, 0) != 0 ", in_where) ;
	 PREPARE qry FROM @tmp;
	 EXECUTE qry;	
	
	SELECT COUNT(cnt.counter) INTO in_counter
	FROM
	(SELECT COUNT(*) AS counter
	FROM tmp_itemreturn_summary_report
	GROUP BY transactiondate, routecode, majorcategorycode, itemcode) cnt;
	SELECT in_counter;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data (in_counter, in_limit, in_page, @new_start_limit);
		SELECT @new_start_limit AS start_limit, in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ", @new_start_limit, ",", in_limit);
	END IF;
	
	SET @tmp = CONCAT("
		SELECT 
			transactiondate, routecode, routename, arbroutename, salesmancode, salesman, 
			majorcategorycode, majorcategroy, itemcode, itemdescription, upc, returncaseprice, returnprice,
			damagedqty,
			(FLOOR(damagedqty/upc) * returncaseprice) + ((damagedqty % upc) * returnprice) AS damagevalue,
			expiredqty,
			(FLOOR(expiredqty/upc) * returncaseprice) + ((expiredqty % upc) * returnprice) AS expvalue,
			otherdamagedqty,
			(FLOOR(otherdamagedqty/upc) * returncaseprice) + ((otherdamagedqty % upc) * returnprice) AS otherdamagevalue,			
			damagedqty + expiredqty + otherdamagedqty totaldamage,
			(FLOOR(damagedqty/upc) * returncaseprice) + ((damagedqty % upc) * returnprice) +
			(FLOOR(expiredqty/upc) * returncaseprice) + ((expiredqty % upc) * returnprice) +
			(FLOOR(otherdamagedqty/upc) * returncaseprice) + ((otherdamagedqty % upc) * returnprice) AS totaldamagevalue			
		FROM ", @tablename, "
		GROUP BY transactiondate, routecode, routename, arbroutename, salesmancode, majorcategorycode, majorcategroy, itemcode, itemdescription, upc
		ORDER BY ",in_orderby," ",in_sort," ",limit_val) ;
	 PREPARE qry FROM @tmp;
	 EXECUTE qry;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_returnsummery_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_returnsummery_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_returnsummery_detail`(
)
