	CALL sp_combo_routemaster() ;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_routedailytrack` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_routedailytrack` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_routedailytrack`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT
)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter 
			FROM 
			(
				SELECT STR.ROUTEKEY,str.salesmancode, salesmanname1, routestartdate, routestarttime, routeendtime, 
TIMEDIFF(routeendtime, routestarttime) totime, 
routestartodometer, routeendodometer,
routeendodometer - routestartodometer totkm, 
(SELECT CONCAT(LATITUDE,',', LONGITUDE) FROM CUSTOMEROPERATIONSCONTROL C WHERE C.ROUTEKEY = STR.ROUTEKEY AND PRIMARY_ID = (SELECT MIN(PRIMARY_ID) FROM CUSTOMEROPERATIONSCONTROL B WHERE B.ROUTEKEY = C.ROUTEKEY AND LATITUDE <> 0) ) FIRSTGEO,
(SELECT CONCAT(LATITUDE,',', LONGITUDE) FROM CUSTOMEROPERATIONSCONTROL C WHERE C.ROUTEKEY = STR.ROUTEKEY AND PRIMARY_ID = (SELECT MAX(PRIMARY_ID) FROM CUSTOMEROPERATIONSCONTROL B WHERE B.ROUTEKEY = C.ROUTEKEY AND LATITUDE <> 0) ) LASTGEO
 FROM STARTENDDAY str
INNER JOIN salesman sls ON str.salesmancode = sls.salesmancode
WHERE 1=1 ",in_where,"
			) a
			");
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	 IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	 END IF;
	
	SET @dyn_sql = CONCAT("SELECT STR.ROUTEKEY,str.salesmancode, salesmanname1,ansalesmancode, dayname(routestartdate) dayname,  
	DATE_FORMAT(routestartdate, '%Y-%m-%d') routestartdate, routestarttime, 	
	DATE_FORMAT(ROUTEENDDATE, '%Y-%m-%d') ROUTEENDDATE, routeendtime, 	
	TIME_FORMAT(ABS(TIMEDIFF(CAST(CONCAT(DATE(routestartdate), ' ', routestarttime) AS DATETIME), CAST(CONCAT(DATE(routeenddate), ' ', routeendtime) AS DATETIME))),'%H:%i:%s') AS rdur, 
	TIMEDIFF(routeendtime, routestarttime) totime, 
	routestartodometer, routeendodometer,
	routeendodometer - routestartodometer totkm, 
	(SELECT CONCAT(LATITUDE,',', LONGITUDE) FROM CUSTOMEROPERATIONSCONTROL C WHERE C.ROUTEKEY = STR.ROUTEKEY AND PRIMARY_ID = (SELECT MIN(PRIMARY_ID) FROM CUSTOMEROPERATIONSCONTROL B WHERE B.ROUTEKEY = C.ROUTEKEY AND LATITUDE <> 0) ) FIRSTGEO,
	-- (SELECT logstarttime FROM customervisitlog C WHERE C.ROUTEKEY = STR.ROUTEKEY AND logkey = (SELECT MIN(logkey) FROM customervisitlog B WHERE B.ROUTEKEY = C.ROUTEKEY) ) FIRSTtime,
	-- (SELECT VISITSTARTTIME FROM CUSTOMEROPERATIONSCONTROL C WHERE C.ROUTEKEY = STR.ROUTEKEY AND PRIMARY_ID = (SELECT MIN(PRIMARY_ID) FROM CUSTOMEROPERATIONSCONTROL B WHERE B.ROUTEKEY = C.ROUTEKEY AND LATITUDE <> 0) ) FIRSTTIME,
        (SELECT VISITSTARTTIME FROM CUSTOMEROPERATIONSCONTROL C WHERE C.ROUTEKEY = STR.ROUTEKEY AND PRIMARY_ID = (SELECT MIN(PRIMARY_ID) FROM CUSTOMEROPERATIONSCONTROL B WHERE B.ROUTEKEY = C.ROUTEKEY ) ) FIRSTTIME,	
	(SELECT CONCAT(LATITUDE,',', LONGITUDE) FROM CUSTOMEROPERATIONSCONTROL C WHERE C.ROUTEKEY = STR.ROUTEKEY AND PRIMARY_ID = (SELECT MAX(PRIMARY_ID) FROM CUSTOMEROPERATIONSCONTROL B WHERE B.ROUTEKEY = C.ROUTEKEY AND LATITUDE <> 0) ) LASTGEO,
	-- (SELECT logstarttime FROM customervisitlog C WHERE C.ROUTEKEY = STR.ROUTEKEY AND logkey = (SELECT MAX(logkey) FROM customervisitlog B WHERE B.ROUTEKEY = C.ROUTEKEY) ) lasttime
	-- (SELECT VISITENDTIME FROM CUSTOMEROPERATIONSCONTROL C WHERE C.ROUTEKEY = STR.ROUTEKEY AND PRIMARY_ID = (SELECT MAX(PRIMARY_ID) FROM CUSTOMEROPERATIONSCONTROL B WHERE B.ROUTEKEY = C.ROUTEKEY AND LATITUDE <> 0) ) LASTTIME
	(SELECT VISITENDTIME FROM CUSTOMEROPERATIONSCONTROL C WHERE C.ROUTEKEY = STR.ROUTEKEY AND PRIMARY_ID = (SELECT MAX(PRIMARY_ID) FROM CUSTOMEROPERATIONSCONTROL B WHERE B.ROUTEKEY = C.ROUTEKEY ) ) LASTTIME
	FROM STARTENDDAY str
	INNER JOIN salesman sls ON str.salesmancode = sls.salesmancode
	WHERE 1=1 and str.routeclosed =1 ",in_where, " ORDER BY routestartdate, str.salesmancode ") ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
	 SELECT @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_route_review` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_route_review` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_route_review`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter  FROM routemaster rm, salesman sm,startendday sed
	LEFT JOIN total_sheduled ON sed.routekey = total_sheduled.routekey AND sed.routecode = total_sheduled.routecode
	LEFT JOIN total_visited ON sed.routekey = total_visited.routekey AND sed.routecode = total_visited.routecode
	LEFT JOIN total_unsheduled_visit ON sed.routekey = total_unsheduled_visit.routekey AND sed.routecode = total_unsheduled_visit.routecode
	LEFT JOIN total_sheduled_sale ON sed.routekey = total_sheduled_sale.routekey AND sed.routecode = total_sheduled_sale.routecode
	LEFT JOIN total_unsheduled_sale ON sed.routekey = total_unsheduled_sale.routekey AND sed.routecode = total_unsheduled_sale.routecode
	LEFT JOIN total_sheduled_nosale ON sed.routekey = total_sheduled_nosale.routekey AND sed.routecode = total_sheduled_nosale.routecode
	LEFT JOIN total_unsheduled_nosale ON sed.routekey = total_unsheduled_nosale.routekey AND sed.routecode = total_unsheduled_nosale.routecode
	LEFT JOIN total_unscanned ON sed.routekey = total_unscanned.routekey AND sed.routecode = total_unscanned.routecode
	LEFT JOIN totaltime ON sed.routekey = totaltime.routekey AND sed.routecode = totaltime.routecode
	LEFT JOIN totalcashsale ON sed.routekey = totalcashsale.routekey AND sed.routecode = totalcashsale.routecode
	LEFT JOIN totalcreditsale ON sed.routekey = totalcreditsale.routekey AND sed.routecode = totalcreditsale.routecode
	WHERE (sed.routecode = rm.routecode) AND (sed.salesmancode = sm.salesmancode)", in_where,"");
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	
	SET @dyn_sql = CONCAT("SELECT
		YEAR(routeenddate) AS tranyear, 
		MONTH(routeenddate) AS tranmonthno, 
		DATE_FORMAT(routeenddate,'%M') AS tranmonthtxt, 
		DATE_FORMAT(routestartdate,'%d-%b-%Y')  AS routestartdate1,
		DATE_FORMAT(routeenddate,'%W') AS daytxt,
		DATE_FORMAT(routeenddate,'%d-%b-%Y') AS routeenddate1,
		rm.routecode AS routecode, 
		CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.routename) AS route, 
		CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.arbroutename) AS arbroutename, 
		CONCAT(CAST(sm.salesmancode AS CHAR) , ' - ' , sm.salesmanname1) AS salesman, 
		CONCAT(CAST(sm.salesmancode AS CHAR) , ' - ' , sm.arbsalesmanname1) AS arbsalesman, 
		CAST(SUM(COALESCE(total_sheduled.totalcust, 0)) AS CHAR) AS targettovisit, 
		CAST(SUM(COALESCE(total_visited.totalcust, 0)) AS CHAR) AS targetvisits, 
		CAST(SUM(COALESCE(total_sheduled.totalcust, 0)) - SUM(COALESCE(total_visited.totalcust, 0)) AS CHAR) AS callexceptions, 
		CAST(SUM((SELECT COUNT(ih.invoicenumber) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND (ih.voidflag = 0) AND ih.customercode NOT IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) +
			COALESCE(total_unsheduled_visit.totalcust, 0)) AS CHAR) AS nontargetvisits, 
		CAST(SUM(COALESCE(total_visited.totalcust, 0)) + SUM((SELECT COUNT(ih.invoicenumber) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND (ih.voidflag = 0) AND ih.customercode NOT IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) +
			COALESCE(total_unsheduled_visit.totalcust, 0)) AS CHAR) AS totalvisits, 
		CAST(SUM(COALESCE(total_sheduled_sale.totalcust, 0)) AS CHAR) AS schedulesale, 
		CAST(SUM((SELECT COUNT(ih.invoicenumber) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND (ih.voidflag = 0) AND ih.customercode NOT IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) +
			COALESCE(total_unsheduled_sale.totalcust, 0)) AS CHAR) AS unschedsale, 
		CAST(SUM(COALESCE(total_sheduled_nosale.totalcust, 0)) AS CHAR) AS schedulenosale, 
		CAST(SUM(COALESCE(total_unsheduled_nosale.totalcust, 0)) AS CHAR) AS unschedulenosale, 
		CAST(SUM(COALESCE(total_sheduled_sale.totalcust, 0)) + SUM((SELECT COUNT(ih.invoicenumber) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND (ih.voidflag = 0) AND ih.customercode NOT IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) +
			COALESCE(total_unsheduled_sale.totalcust, 0)) AS CHAR) AS effectivevisit, 
		CAST(MIN(routestartodometer) AS CHAR) AS startkms, 
		CAST(MAX(routeendodometer) AS CHAR) AS endkms, 
		CAST((CASE WHEN (MAX(routeendodometer) - MIN(routestartodometer)) < 0 THEN 0 ELSE (MAX(routeendodometer) - MIN(routestartodometer)) END) AS CHAR) AS kmscovered
	FROM routemaster rm, salesman sm,startendday sed
	LEFT JOIN total_sheduled ON sed.routekey = total_sheduled.routekey AND sed.routecode = total_sheduled.routecode
	LEFT JOIN total_visited ON sed.routekey = total_visited.routekey AND sed.routecode = total_visited.routecode
	LEFT JOIN total_unsheduled_visit ON sed.routekey = total_unsheduled_visit.routekey AND sed.routecode = total_unsheduled_visit.routecode
	LEFT JOIN total_sheduled_sale ON sed.routekey = total_sheduled_sale.routekey AND sed.routecode = total_sheduled_sale.routecode
	LEFT JOIN total_unsheduled_sale ON sed.routekey = total_unsheduled_sale.routekey AND sed.routecode = total_unsheduled_sale.routecode
	LEFT JOIN total_sheduled_nosale ON sed.routekey = total_sheduled_nosale.routekey AND sed.routecode = total_sheduled_nosale.routecode
	LEFT JOIN total_unsheduled_nosale ON sed.routekey = total_unsheduled_nosale.routekey AND sed.routecode = total_unsheduled_nosale.routecode
	LEFT JOIN total_unscanned ON sed.routekey = total_unscanned.routekey AND sed.routecode = total_unscanned.routecode
	LEFT JOIN totaltime ON sed.routekey = totaltime.routekey AND sed.routecode = totaltime.routecode
	LEFT JOIN totalcashsale ON sed.routekey = totalcashsale.routekey AND sed.routecode = totalcashsale.routecode
	LEFT JOIN totalcreditsale ON sed.routekey = totalcreditsale.routekey AND sed.routecode = totalcreditsale.routecode
	WHERE (sed.routecode = rm.routecode) AND (sed.salesmancode = sm.salesmancode)",in_where, " GROUP BY YEAR(routeenddate), MONTH(routeenddate), routestartdate, routeenddate, 
		rm.routecode, rm.routename, sm.salesmancode, salesmanname1 ORDER BY ",in_orderby," ",in_sort, " ", limit_val) ;
	
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_route_review_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_route_review_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_route_review_detail`(
)
BEGIN
	CALL sp_combo_routemaster() ;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_salesman_route_format` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_salesman_route_format` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_salesman_route_format`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN fromdate DATE,
IN todate DATE,
IN startdate DATE,
IN in_limit VARCHAR(25),
IN in_page VARCHAR(25)
)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
	
	SET @dyn_sql = CONCAT("SELECT YEAR(routeenddate) AS tranyear, 
		MONTH(routeenddate) AS tranmonthno, 
		DATE_FORMAT(routeenddate,'%M') AS tranmonthtxt, 
		DATE_FORMAT(routestartdate,'%d-%b-%Y')  AS routestartdate1,
		DATE_FORMAT(routeenddate,'%W') AS daytxt,
		DATE_FORMAT(routeenddate,'%d-%b-%Y') AS routeenddate1,
		rm.routecode AS routecode, 
		CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.routename) AS route, 
		CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.arbroutename) AS arbroutename, 
		CONCAT(CAST(sm.salesmancode AS CHAR) , ' - ' , sm.salesmanname1) AS salesman, 
		CONCAT(CAST(sm.salesmancode AS CHAR) , ' - ' , sm.arbsalesmanname1) AS arbsalesman,tagetcount AS targettovisit, servicecount AS targetvisits, coccount AS productivecalls,ORD1.returntarget,ORD1.foc,ORD1.returnamt,INV.*,CAST(MIN(routestartodometer) AS CHAR) AS startkms, routestartodometer,
		CAST(MAX(routeendodometer) AS CHAR) AS endkms, 
		CAST((CASE WHEN (MAX(routeendodometer) - MIN(routestartodometer)) < 0 THEN 0 ELSE (MAX(routeendodometer) - MIN(routestartodometer)) END) AS CHAR) AS kmscovered,((SUM(ORD1.totalsalesamount)/ rg.quantity)*100) AS salestarget,
		COL.amountpaid as collection,
		CASE WHEN rm.routetype = 2 THEN (SELECT SUM(totalsalesamount) FROM salesorderheader WHERE  routecode = sed1.routecode  AND (voidflag = 0) AND  transactiondate BETWEEN DATE_FORMAT(sed1.routeenddate ,'%Y-%m-01')  and sed1.routeenddate GROUP BY routecode)  
ELSE (SELECT SUM(totalinvoiceamount) FROM invoiceheader WHERE  routecode = sed1.routecode  AND (voidflag = 0) AND  transactiondate BETWEEN DATE_FORMAT(sed1.routeenddate ,'%Y-%m-01')  and sed1.routeenddate GROUP BY routecode) END MTDsales
 
		FROM StartEndDay sed1 
		INNER JOIN routemaster rm ON rm.routecode=sed1.routecode     
		INNER JOIN salesman sm ON sm.salesmancode=sed1.salesmancode 
		LEFT  OUTER JOIN 
(SELECT sed.routekey,sed.routecode, COUNT(DISTINCT customercode) AS tagetcount  
FROM routesequencecustomerstatus rcs 
INNER JOIN startendday sed ON  rcs.routekey = sed.routekey 
WHERE rcs.schelduledflag=1  AND sed.routeenddate BETWEEN '",fromdate,"' and '",todate,"' GROUP BY sed.routekey) TARGET ON TARGET.routekey=sed1.routekey AND TARGET.routecode=sed1.routecode
		LEFT OUTER JOIN 
(SELECT sed.routekey,sed.routecode, COUNT(DISTINCT customercode) AS  servicecount 
FROM routesequencecustomerstatus rcs INNER JOIN startendday sed ON  rcs.routekey = sed.routekey
WHERE rcs.servicedflag=1 
AND sed.routeenddate BETWEEN '",fromdate,"' and '",todate,"'  GROUP BY sed.routekey) SERVICED  ON sed1.Routekey=SERVICED.Routekey AND  sed1.Routecode=SERVICED.Routecode
		LEFT OUTER JOIN 
(SELECT sed.routekey,sed.routecode,COUNT(DISTINCT customercode) AS coccount 
FROM customeroperationscontrol coc  
INNER JOIN startendday sed ON  coc.routekey = sed.routekey WHERE  totaltransactions >0 AND sed.routeenddate BETWEEN '",fromdate,"' and '",todate,"' GROUP BY sed.routekey)ACT ON ACT.RouteKey=sed1.Routekey AND ACT.Routecode=sed1.Routecode
		LEFT OUTER JOIN 
 (SELECT totalsalesamount,ih.routekey,sed.routecode,(totalsalesamount) MTDsales,(totalsalesamount)-(totalreturnamount) AS todayssale,(((ih.totalreturnamount)/(totalsalesamount))*100) AS returntarget, (totalreturnamount) AS returnamt,SUM(freesampleqty + manualfreeqty) AS foc 
FROM startendday sed 
INNER JOIN salesorderheader ih ON ih.routekey=sed.routekey 
INNER JOIN salesorderdetail sd ON sd.transactionkey=ih.transactionkey  
WHERE  (ih.voidflag = 0) AND ih.transactiondate  BETWEEN   '",fromdate,"' and '",todate,"'   GROUP BY ih.routekey,totalsalesamount,totalreturnamount )ORD1 ON ORD1.RouteKEy=sed1.routekey AND  ORD1.Routecode=sed1.routecode
		LEFT OUTER JOIN 
(SELECT iv.routekey,sed.routecode,(iv.totalsalesamount) MTDinvoice,SUM((iv.totalinvoiceamount)-(totalreturnamount)) AS todaysinvoice 
FROM startendday sed 
INNER JOIN invoiceheader iv WHERE iv.routekey = sed.routekey AND (iv.voidflag = 0) AND iv.transactiondate BETWEEN   '",fromdate,"' and '",todate,"' GROUP BY sed.routekey )INV ON INV.RouteKey=sed1.RouteKey AND INV.RouteCode=sed1.Routecode 
LEFT OUTER JOIN routegoal  rg ON sed1.routecode = rg.routecode
LEFT JOIN
(SELECT ah.routekey,sed.routecode,SUM(ah.amountpaid)  amountpaid
FROM arheader ah 
INNER JOIN startendday sed ON ah.routekey = sed.routekey  AND ah.voidflag = 0 AND ah.transactiondate BETWEEN   '",fromdate,"' and '",todate,"' GROUP BY sed.routekey )COL ON COL.routekey=sed1.Routekey AND COL.routecode=sed1.Routecode 
WHERE 1=1 
",in_where, " GROUP BY YEAR(routeenddate), MONTH(routeenddate), routestartdate, routeenddate, 
		sed1.routekey, rm.routecode, rm.routename, sm.salesmancode, salesmanname1 ORDER BY ",in_orderby," ",in_sort, " ", limit_val);
	 PREPARE s1 FROM @dyn_sql;
	   EXECUTE s1;	
SELECT @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_salesman_route_format_110717` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_salesman_route_format_110717` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_salesman_route_format_110717`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN fromdate DATE,
IN todate DATE,
IN in_limit VARCHAR(25),
IN in_page VARCHAR(25)
)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
SET @dyn_sql = CONCAT("SELECT count(distinct sed.routekey) INTO @in_counter  FROM routemaster rm, salesman sm,startendday sed
	LEFT JOIN routesequencecustomerstatus rcs ON rcs.routecode = sed.routecode AND rcs.routekey = sed.routekey AND  rcs.schelduledflag = 1
    LEFT JOIN routesequencecustomerstatus vis ON vis.routecode = sed.routecode AND vis.routekey = sed.routekey AND  vis.servicedflag = 1 
    LEFT  JOIN customeroperationscontrol coc on(((coc.routekey = vis.routekey) and (coc.customercode = vis.customercode)))
	LEFT JOIN routegoal  rg ON sed.routecode = rg.routecode	
	LEFT JOIN salesorderheader ih ON ih.routekey = sed.routekey AND (ih.voidflag = 0)
	LEFT JOIN salesorderdetail as id ON id.routekey = ih.routekey AND id.visitkey = ih.visitkey 
	LEFT JOIN arheader ah ON  ah.routekey = ih.routekey  AND (ah.voidflag = 0)
	WHERE (sed.routecode = rm.routecode) AND (sed.salesmancode = sm.salesmancode)",in_where, "");
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	
	SET @dyn_sql = CONCAT("SELECT
		YEAR(routeenddate) AS tranyear, 
		MONTH(routeenddate) AS tranmonthno, 
		DATE_FORMAT(routeenddate,'%M') AS tranmonthtxt, 
		DATE_FORMAT(routestartdate,'%d-%b-%Y')  AS routestartdate1,
		DATE_FORMAT(routeenddate,'%W') AS daytxt,
		DATE_FORMAT(routeenddate,'%d-%b-%Y') AS routeenddate1,
		rm.routecode AS routecode, 
		CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.routename) AS route, 
		CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.arbroutename) AS arbroutename, 
		CONCAT(CAST(sm.salesmancode AS CHAR) , ' - ' , sm.salesmanname1) AS salesman, 
		CONCAT(CAST(sm.salesmancode AS CHAR) , ' - ' , sm.arbsalesmanname1) AS arbsalesman, 		
		count(distinct vis.customercode) as targetvisits,count(distinct rcs.customercode) as targettovisit,
		( select count(distinct customercode) from customeroperationscontrol coc  where `coc`.`routekey` = `sed`.`routekey` and  coc.routecode = sed.routecode and totaltransactions >0) AS productivecalls, 
		rg.quantity as target,
		(SELECT SUM(totalsalesamount) FROM salesorderheader ih WHERE ih.routecode = sed.routecode AND (ih.voidflag = 0) AND ih.transactiondate BETWEEN '",fromdate,"' and '",todate,"') as MTDsales,
		(SELECT SUM(totalsalesamount) FROM salesorderheader  WHERE routekey = sed.routekey AND (voidflag = 0) group by routekey) AS todayssale, 
(SELECT ((SUM(totalsalesamount)/ rg.quantity)*100) FROM salesorderheader  WHERE routekey = sed.routekey AND (voidflag = 0) group by routekey) AS  salestarget,
(SELECT ((sum(ih.totalreturnamount)/SUM(totalsalesamount))*100) FROM salesorderheader  WHERE routekey = sed.routekey AND (voidflag = 0) group by routekey) AS  returntarget,
(SELECT SUM(totalreturnamount) FROM salesorderheader  WHERE routekey = sed.routekey AND (voidflag = 0) group by routekey) AS returnamt,
		
		( SELECT SUM(freesampleqty + manualfreeqty) FROM salesorderdetail where routekey = ih.routekey group by routekey) as foc,
		ah.amountpaid as collection,
		CAST(MIN(routestartodometer) AS CHAR) AS startkms, 
		CAST(MAX(routeendodometer) AS CHAR) AS endkms, 
		CAST((CASE WHEN (MAX(routeendodometer) - MIN(routestartodometer)) < 0 THEN 0 ELSE (MAX(routeendodometer) - MIN(routestartodometer)) END) AS CHAR) AS kmscovered
	FROM routemaster rm, salesman sm,startendday sed
LEFT JOIN routesequencecustomerstatus rcs ON rcs.routecode = sed.routecode AND rcs.routekey = sed.routekey AND  rcs.schelduledflag = 1
    LEFT JOIN routesequencecustomerstatus vis ON vis.routecode = sed.routecode AND vis.routekey = sed.routekey AND  vis.servicedflag = 1 
    LEFT  JOIN customeroperationscontrol coc on(((coc.routekey = vis.routekey) and (coc.customercode = vis.customercode)))
	LEFT JOIN routegoal  rg ON sed.routecode = rg.routecode	
	LEFT JOIN salesorderheader ih ON ih.routekey = sed.routekey AND (ih.voidflag = 0)
	LEFT JOIN salesorderdetail as id ON id.routekey = ih.routekey AND id.visitkey = ih.visitkey 
	LEFT JOIN arheader ah ON  ah.routekey = ih.routekey  AND (ah.voidflag = 0)
	WHERE (sed.routecode = rm.routecode) AND (sed.salesmancode = sm.salesmancode)",in_where, " GROUP BY YEAR(routeenddate), MONTH(routeenddate), routestartdate, routeenddate, 
		sed.routekey, rm.routecode, rm.routename, sm.salesmancode, salesmanname1 ORDER BY ",in_orderby," ",in_sort, " ", limit_val) ;
	
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
select @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_salesman_route_format_old` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_salesman_route_format_old` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_salesman_route_format_old`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN fromdate DATE,
IN todate DATE,
IN in_limit VARCHAR(25),
IN in_page VARCHAR(25)
)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
SET @dyn_sql = CONCAT("SELECT count(distinct sed.routecode) INTO @in_counter  FROM startendday sed
	LEFT JOIN routesequence as rs ON rs.routecode = sed.routecode 	
	LEFT JOIN routesequencecustomerstatus rcs ON rcs.routecode = sed.routecode AND rcs.servicedflag = 1
	LEFT JOIN routegoal  rg ON sed.routecode = rg.routecode
	LEFT JOIN invoiceheader ih ON ih.routecode = sed.routecode AND (ih.voidflag = 0)
	LEFT JOIN invoicedetail as id ON id.routekey = ih.routekey AND id.visitkey = ih.visitkey 
	INNER JOIN routemaster rm ON sed.routecode = rm.routecode
	INNER JOIN subareamaster sam ON sam.subareacode = rm.subareacode
	INNER JOIN areamaster am ON am.areacode = sam.areacode
	INNER JOIN depotmaster dm ON dm.depotcode = am.depotcode
	INNER JOIN regionmaster rgm ON rgm.regionmstcode = dm.regionmstcode
	INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
	Where 1=1 ", in_where,"");
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	
	SET @dyn_sql = CONCAT("SELECT sed.routecode,count(distinct rcs.customercode) as targetvisits,count(distinct rs.customercode) as targettovisit, count(distinct ih.customercode) as productivecalls, mtdtarget, mtdtarget as target,
(SELECT SUM(totalsalesamount) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND ih.voidflag = 0 AND ih.transactiondate BETWEEN date_sub('",fromdate,"', interval 1 month) AND '",todate,"') as MTDsales,ih.totalsalesamount AS todayssale, FORMAT((ih.totalsalesamount * mtdtarget/100), @decimal_places) as salestarget, ih.totalreturnamount as returnamt,FORMAT((ih.totalreturnamount * mtdtarget/100), @decimal_places) as returntarget,SUM(freesampleqty) as foc,ih.amountpaid as collection,rm.routecode AS routecode, rgm.regionmstcode as regionmstcode, CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.routename) AS route, CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.arbroutename) AS arbroutename, CONCAT(CAST(sm.salesmancode AS CHAR) , ' - ' , sm.salesmanname1) AS salesman, regionmstname, arbregionmstname, areaname, arbareaname,	YEAR(routeenddate) AS tranyear, MONTH(routeenddate) AS tranmonthno, DATE_FORMAT(routeenddate,'%M') AS tranmonthtxt, 	DATE_FORMAT(routestartdate,'%d-%b-%Y')  AS routestartdate1, DATE_FORMAT(routeenddate,'%W') AS daytxt, DATE_FORMAT(routeenddate,'%d-%b-%Y') AS routeenddate1,		CAST(MIN(routestartodometer) AS CHAR) AS startkms, CAST(MAX(routeendodometer) AS CHAR) AS endkms, CAST((CASE WHEN (MAX(routeendodometer) - MIN(routestartodometer)) < 0 THEN 0 ELSE (MAX(routeendodometer) - MIN(routestartodometer)) END) AS CHAR) AS kmscovered
	FROM startendday sed
	LEFT JOIN routesequence as rs ON rs.routecode = sed.routecode 	
	LEFT JOIN routesequencecustomerstatus rcs ON rcs.routecode = sed.routecode AND rcs.servicedflag = 1
	LEFT JOIN routegoal  rg ON sed.routecode = rg.routecode
	LEFT JOIN invoiceheader ih ON ih.routecode = sed.routecode AND (ih.voidflag = 0)
	LEFT JOIN invoicedetail as id ON id.routekey = ih.routekey AND id.visitkey = ih.visitkey 
	INNER JOIN routemaster rm ON sed.routecode = rm.routecode
	INNER JOIN subareamaster sam ON sam.subareacode = rm.subareacode
	INNER JOIN areamaster am ON am.areacode = sam.areacode
	INNER JOIN depotmaster dm ON dm.depotcode = am.depotcode
	INNER JOIN regionmaster rgm ON rgm.regionmstcode = dm.regionmstcode
	INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
	Where 1=1",in_where, " GROUP BY sed.routekey,routeenddate,YEAR(routeenddate), MONTH(routeenddate), DAY(routeenddate),sed.routecode ORDER BY ",in_orderby," ",in_sort, " ", limit_val) ;
	
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_salesman_route_format_temp` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_salesman_route_format_temp` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_salesman_route_format_temp`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN fromdate DATE,
IN todate DATE,
IN startdate DATE,
IN in_limit VARCHAR(25),
IN in_page VARCHAR(25),
IN routestr TEXT
)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
	DROP TABLE IF EXISTS temp_dsrformat;
	SET @dyn_sql = CONCAT("CREATE TABLE temp_dsrformat
SELECT 
		 
		DATE_FORMAT(routestartdate,'%d-%b-%Y')  AS routestartdate1,
		DATE_FORMAT(routeenddate,'%W') AS daytxt,
		DATE_FORMAT(routeenddate,'%d-%b-%Y') AS routeenddate1,
		rm.routecode AS routecode, sed1.routekey,
		CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.routename) AS route, 
		CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.arbroutename) AS arbroutename, 
		CAST(MAX(routeendodometer) AS CHAR) AS endkms, rg.quantity,
		CAST((CASE WHEN (MAX(routeendodometer) - MIN(routestartodometer)) < 0 THEN 0 ELSE (MAX(routeendodometer) - MIN(routestartodometer)) END) AS CHAR) AS kmscovered,
		0 AS plannedvisit,0 AS actualvisits, 0 AS productivecalls, 0 AS actualotpvisits, 0 AS productiveotpcalls,
0 AS todaysinvoice,0 AS todayssale,0 AS salestarget,0 AS returntarget,0 AS returnamt,0 AS foc,0 AS collection,CASE WHEN rm.routetype = 2 THEN (SELECT SUM(totalsalesamount) FROM salesorderheader WHERE  routecode = sed1.routecode  AND (voidflag = 0) AND  transactiondate BETWEEN DATE_FORMAT(sed1.routeenddate ,'%Y-%m-01')  and sed1.routeenddate GROUP BY routecode)  
ELSE (SELECT SUM(totalinvoiceamount) FROM invoiceheader WHERE  routecode = sed1.routecode  AND (voidflag = 0) AND  transactiondate BETWEEN DATE_FORMAT(sed1.routeenddate ,'%Y-%m-01')  and sed1.routeenddate GROUP BY routecode) END  AS MTDsales 
FROM StartEndDay sed1 
		INNER JOIN routemaster rm ON rm.routecode=sed1.routecode  
LEFT OUTER JOIN routegoal  rg ON sed1.routecode = rg.routecode
WHERE 1=1  AND rm.routecode IN (",routestr,") AND sed1.routeenddate BETWEEN  '",startdate,"' and '",todate,"'
 GROUP BY YEAR(routeenddate), MONTH(routeenddate), routestartdate, routeenddate, 
		sed1.routekey, rm.routecode, rm.routename");
PREPARE s1 FROM @dyn_sql;
	   EXECUTE s1;
		
SET @dyn_sql1 = CONCAT("UPDATE temp_dsrformat tds 
	INNER JOIN
	(
		SELECT sed.routekey,sed.routecode, COUNT(DISTINCT customercode) AS planned 
	FROM routesequencecustomerstatus rcs 
	INNER JOIN startendday sed ON  rcs.routekey = sed.routekey 
	WHERE rcs.schelduledflag=1 AND sed.routecode IN (",routestr,") AND sed.routeenddate BETWEEN  '",startdate,"' and '",todate,"' GROUP BY sed.routekey
	) pl ON pl.routecode= tds.routecode and pl.routekey = tds.routekey
	SET  tds.plannedvisit = pl.planned ");
PREPARE s11 FROM @dyn_sql1;
	   EXECUTE s11;
SET @dyn_sql2 = CONCAT("UPDATE temp_dsrformat tds 
	INNER JOIN
	(
	   SELECT sed.routekey,sed.routecode, COUNT(DISTINCT rcs.customercode) AS  actualvisit 
	FROM routesequencecustomerstatus rcs INNER JOIN startendday sed ON  rcs.routekey = sed.routekey
	WHERE rcs.servicedflag=1  AND rcs.customercode NOT IN (select distinct customercode from otplogdetail where otpdate =sed.routeenddate and routecode =sed.routecode)
	 AND sed.routecode IN (",routestr,") AND sed.routeenddate BETWEEN  '",startdate,"' and '",todate,"' GROUP BY sed.routekey
	) pl ON pl.routecode= tds.routecode and pl.routekey = tds.routekey
	SET  tds.actualvisits = pl.actualvisit");
PREPARE s12 FROM @dyn_sql2;
	   EXECUTE s12;
	
SET @dyn_sql3 = CONCAT("UPDATE temp_dsrformat tds 
	INNER JOIN
	(
	SELECT sed.routekey,sed.routecode, COUNT(DISTINCT rcs.customercode) AS  actualvisitotp 
	FROM routesequencecustomerstatus rcs INNER JOIN startendday sed ON  rcs.routekey = sed.routekey
	INNER JOIN otplogdetail OLD ON  old.routecode = rcs.routecode AND old.otpdate = sed.routeenddate AND old.customercode = rcs.customercode
	WHERE rcs.servicedflag=1 AND sed.routecode IN (",routestr,") AND sed.routeenddate BETWEEN  '",startdate,"' and '",todate,"' GROUP BY sed.routekey
	) pl ON pl.routecode= tds.routecode and pl.routekey = tds.routekey
	SET  tds.actualotpvisits = pl.actualvisitotp ");
PREPARE s13 FROM @dyn_sql3;
	   EXECUTE s13;
	
SET @dyn_sql4 = CONCAT("UPDATE temp_dsrformat tds 
	INNER JOIN
	(
	SELECT sed.routekey,sed.routecode,COUNT(DISTINCT coc.customercode) AS productive 
	FROM customeroperationscontrol coc  
	INNER JOIN startendday sed ON  coc.routekey = sed.routekey 
	WHERE  totaltransactions >0  AND coc.customercode NOT IN (select distinct customercode from otplogdetail where otpdate =sed.routeenddate and routecode =sed.routecode)
	AND sed.routecode IN (",routestr,") AND sed.routeenddate BETWEEN  '",startdate,"' and '",todate,"' GROUP BY sed.routekey
	) pl ON pl.routecode= tds.routecode and pl.routekey = tds.routekey
	SET  tds.productivecalls = pl.productive ");
PREPARE s14 FROM @dyn_sql4;
	   EXECUTE s14;
	
SET @dyn_sql5 = CONCAT("UPDATE temp_dsrformat tds 
	INNER JOIN
	(
	SELECT sed.routekey,sed.routecode,COUNT(DISTINCT coc.customercode) AS productiveotp 
	FROM customeroperationscontrol coc  
	INNER JOIN startendday sed ON  coc.routekey = sed.routekey 
	INNER JOIN otplogdetail old ON  old.routecode = coc.routecode and old.otpdate = sed.routeenddate and old.customercode = coc.customercode
	WHERE  totaltransactions >0 AND sed.routecode IN (",routestr,") AND sed.routeenddate BETWEEN  '",startdate,"' and '",todate,"' GROUP BY sed.routekey
	) pl ON pl.routecode= tds.routecode and pl.routekey = tds.routekey
	SET  tds.productiveotpcalls = pl.productiveotp ");
PREPARE s15 FROM @dyn_sql5;
	   EXECUTE s15;
SET @dyn_sql6 = CONCAT("UPDATE temp_dsrformat tds 
	INNER JOIN
	(
	SELECT ah.routekey,sed.routecode,SUM(ah.amountpaid)  amountpaid
	FROM arheader ah 
	INNER JOIN startendday sed ON ah.routekey = sed.routekey  AND ah.voidflag = 0 AND sed.routecode IN (",routestr,") AND sed.routeenddate BETWEEN  '",startdate,"' and '",todate,"' GROUP BY sed.routekey
	) pl ON pl.routecode= tds.routecode and pl.routekey = tds.routekey
	SET  tds.collection = pl.amountpaid ");
PREPARE s16 FROM @dyn_sql6;
	   EXECUTE s16;
SET @dyn_sql7 = CONCAT("UPDATE temp_dsrformat tds 
	INNER JOIN
	(
	SELECT iv.routekey,sed.routecode,SUM(freesampleqty + manualfreeqty) AS foc 
	FROM startendday sed 
	INNER JOIN invoiceheader iv ON iv.routekey = sed.routekey
	INNER JOIN invoicedetail sd ON sd.transactionkey=iv.transactionkey 
	WHERE (iv.voidflag = 0) AND sed.routecode IN (",routestr,") AND sed.routeenddate BETWEEN  '",startdate,"' and '",todate,"' GROUP BY sed.routekey
	UNION 
	SELECT ih.routekey,sed.routecode,SUM(freesampleqty + manualfreeqty) AS foc
	FROM startendday sed 
	INNER JOIN salesorderheader ih ON ih.routekey=sed.routekey 
	INNER JOIN salesorderdetail sd ON sd.transactionkey=ih.transactionkey 
	WHERE  (ih.voidflag = 0) AND sed.routecode IN (",routestr,") AND sed.routeenddate BETWEEN  '",startdate,"' and '",todate,"'  GROUP BY ih.routekey
	) pl ON pl.routecode= tds.routecode and pl.routekey = tds.routekey
	SET  tds.foc = pl.foc");
PREPARE s17 FROM @dyn_sql7;
	   EXECUTE s17;
SET @dyn_sql8 = CONCAT("UPDATE temp_dsrformat tds 
	INNER JOIN
	(
	SELECT totalsalesamount, ih.routekey,sed.routecode,SUM((totalsalesamount)-(totalreturnamount)) AS todayssale,
	 ((sum(ih.totalreturnamount)/sum(totalsalesamount))*100) AS returntarget, sum(totalreturnamount) AS returnamt,0 as todaysinvoice
	FROM startendday sed 
	INNER JOIN salesorderheader ih ON ih.routekey=sed.routekey 
	WHERE  (ih.voidflag = 0) AND sed.routecode IN (",routestr,") AND sed.routeenddate BETWEEN  '",startdate,"' and '",todate,"'  GROUP BY ih.routekey
	UNION 
	SELECT iv.routekey,sed.routecode,iv.totalinvoiceamount, SUM((iv.totalinvoiceamount)-(totalreturnamount)) AS todaysinvoice,0 AS todayssale,
	((sum(iv.totalreturnamount)/sum(iv.totalinvoiceamount))*100) AS returntarget, sum(totalreturnamount) AS returnamt 
	FROM startendday sed 
	INNER JOIN invoiceheader iv ON iv.routekey = sed.routekey
	WHERE (iv.voidflag = 0) AND sed.routecode IN (",routestr,") AND sed.routeenddate BETWEEN  '",startdate,"' and '",todate,"' GROUP BY sed.routekey
	) pl ON pl.routecode= tds.routecode and pl.routekey = tds.routekey
	SET  tds.todayssale = pl.todayssale ,
	tds.todaysinvoice = pl.todaysinvoice,
	tds.returntarget = pl.returntarget,
	tds.returnamt = pl.returnamt");
PREPARE s18 FROM @dyn_sql8;
	   EXECUTE s18;
	SELECT * FROM temp_dsrformat;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_salesman_route_summary` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_salesman_route_summary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_salesman_route_summary`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN fromdate DATE,
IN todate DATE,
IN in_limit VARCHAR(25),
IN in_page VARCHAR(25),
IN routestr TEXT,IN routestr1 TEXT
)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
 CALL sp_report_transaction_dsrsummary_temp(routestr);   
	SET @dyn_sql = CONCAT("SELECT 
(SELECT  COUNT(DISTINCT rs.customercode)
FROM routesequencecustomerstatus  res LEFT JOIN routesequence rs
ON res.routecode=rs.routecode  INNER JOIN startendday sed ON sed.routekey=res.routekey WHERE
CASE WHEN DAYNAME(sed.routeenddate)='Monday' THEN rs.callrestrictiondays1=1
WHEN DAYNAME(sed.routeenddate)='Tuesday' THEN rs.callrestrictiondays2=1
WHEN DAYNAME(sed.routeenddate)='Wednesday' THEN rs.callrestrictiondays3=1
WHEN DAYNAME(sed.routeenddate)='Thursday' THEN rs.callrestrictiondays4=1
WHEN DAYNAME(sed.routeenddate)='Friday' THEN rs.callrestrictiondays5=1
WHEN DAYNAME(sed.routeenddate)='Saturday' THEN rs.callrestrictiondays6=1
WHEN DAYNAME(sed.routeenddate)='Sunday' THEN rs.callrestrictiondays7=1
ELSE  0 END and sed.routeclosed=1  ",routestr, " 
 ) as targettovisit,sum(actualvisits) as targetvisits, sum(productivecalls) as productivecalls,
 mtdtarget,sum(salesamount) as todayssale,
((SUM(salesamount)/ mtdtarget)*100) as salestarget,
((sum(totalreturnamount)/SUM(salesamount))*100) as returntarget,SUM(totalreturnamount) AS returnamt,
sum(freesampleqty+manualfreeqty) as foc,sum(collection) as collection,
sum(invbilled) invbilled, 
sum(itemsbilled) as itembilled,
sum(customerbilled)  customerbilled, 
sum(salesamount)/sum(invbilled)avginv,
CASE WHEN routetype = 2 THEN (SELECT SUM(totalsalesamount) FROM salesorderheader WHERE  routecode = dsrt.routecode  AND (voidflag = 0) AND  transactiondate BETWEEN DATE_FORMAT('",fromdate,"' ,'%Y-%m-01')  AND '",todate,"' GROUP BY routecode)  
ELSE (SELECT SUM(totalinvoiceamount) FROM invoiceheader WHERE  routecode = dsrt.routecode  AND (voidflag = 0) AND  transactiondate BETWEEN DATE_FORMAT('",fromdate,"' ,'%Y-%m-01')  AND '",todate,"' GROUP BY routecode) END  MTDsales, 
CASE WHEN routetype = 2 THEN 
( SELECT COUNT(DISTINCT customercode) FROM salesorderheader ih
INNER JOIN startendday sed ON sed.routekey =ih.routekey AND voidflag = 0  WHERE 1=1 ",routestr1, " ) 
ELSE ( SELECT COUNT(DISTINCT customercode) FROM invoiceheader ih 
INNER JOIN startendday sed ON sed.routekey =ih.routekey  WHERE 1=1 ",routestr1, ") END as lastcustomerbilled,
routecode, regionmstcode,route, arbroutename, salesman, regionmstname, arbregionmstname, arbareaname
FROM dsrsummary_temp dsrt
	Where 1=1 ",in_where, " GROUP BY routecode  ORDER BY ",in_orderby," ",in_sort, " ", limit_val) ;  
	
	 PREPARE s1 FROM @dyn_sql;
	  EXECUTE s1;
	
	 
	
	 
    END */$$
DELIMITER ;

