CASE WHEN routetype = 2 THEN
(SELECT round((sum(soh.totalinvoiceamount)/count(soh.invoicenumber)),3) FROM salesorderheader soh where soh.routecode = routecode  AND soh.voidflag = 0 ) ELSE 
(SELECT round((sum(soh.totalinvoiceamount)/count(soh.invoicenumber)),3) FROM invoiceheader soh where soh.routecode = routecode  AND soh.voidflag = 0 )
