DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_salesman_route_summary_modified`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN fromdate DATE,
IN todate DATE,
IN in_limit VARCHAR(25),
IN in_page VARCHAR(25),
IN routestr text
)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
 CALL sp_report_transaction_dsrsummary_modified_temp(routestr,fromdate,todate);   
	SET @dyn_sql = CONCAT(" SELECT  plt.planned as targettovisit,act.actual as targetvisits,pdt.productive as productivecalls,rdt.mtdtarget,
							invaat.invoiceamt as todayssale,((invoiceamt/ mtdtarget)*100) as salestarget,((invaat.returnamt/invaat.invoiceamt)*100) as returntarget,invaat.returnamt AS returnamt,
							(invqt.freesampleqty+invqt.manualfreeqty) as foc,rdt.collection as collection,invaat.avginv as avginv,rdt.MTDsales,rdt.lastcustomerbilled,
							rdt.routecode, regionmstcode,route, arbroutename, salesman, regionmstname, arbregionmstname, arbareaname,
							invt.invbilled as invbilled, invt.itembilled as itembilled, invt.customerbilled as customerbilled 
						 FROM startendday sed
							LEFT JOIN planned_temp plt ON plt.routecode = sed.routecode
							LEFT JOIN actual_temp act ON act.routecode = sed.routecode
							LEFT JOIN productive_temp pdt ON pdt.routecode = sed.routecode
							LEFT JOIN invoicedet_temp invt ON invt.routecode = sed.routecode
							LEFT JOIN invoiceamount_temp invaat ON invaat.routecode = sed.routecode
							LEFT JOIN invoiceqty_temp invqt ON invqt.routecode = sed.routecode
							LEFT JOIN routedet_temp  rdt ON sed.routecode = rdt.routecode
				Where 1=1 ",in_where, " GROUP BY routecode  ORDER BY ",in_orderby," ",in_sort, " ", limit_val) ;  
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	 
	  select @dyn_sql,routestr,fromdate,todate;
	 
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_salesman_route_summary_old` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_salesman_route_summary_old` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_salesman_route_summary_old`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN fromdate DATE,
IN todate DATE,
IN in_limit VARCHAR(25),
IN in_page VARCHAR(25)
)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
SET @dyn_sql = CONCAT("SELECT count(distinct sed.routecode)	 INTO @in_counter  FROM startendday sed
LEFT JOIN routesequence as rs ON rs.routecode = sed.routecode 
LEFT JOIN routesequencecustomerstatus rcs ON rcs.routecode = sed.routecode AND rcs.servicedflag = 1
LEFT JOIN routegoal  rg ON sed.routecode = rg.routecode
LEFT JOIN invoiceheader ih ON ih.routecode = sed.routecode AND (ih.voidflag = 0)
LEFT JOIN invoicedetail as id ON id.routekey = ih.routekey AND id.visitkey = ih.visitkey 
INNER JOIN routemaster rm ON sed.routecode = rm.routecode
INNER JOIN subareamaster sam ON sam.subareacode = rm.subareacode
INNER JOIN areamaster am ON am.areacode = sam.areacode
INNER JOIN depotmaster dm ON dm.depotcode = am.depotcode
INNER JOIN regionmaster rgm ON rgm.regionmstcode = dm.regionmstcode
INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
	Where 1=1", in_where," GROUP BY rgm.regionmstcode");
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	SELECT decimalplaces INTO @decimal_places FROM currencymaster WHERE defaultcurrency = 1;    
	SET @dyn_sql = CONCAT("SELECT sed.routecode,count(distinct rcs.customercode) as targetvisits,count(distinct rs.customercode) as targettovisit, count(distinct ih.customercode) as productivecalls, mtdtarget, mtdtarget as target,
(SELECT SUM(totalsalesamount) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND ih.voidflag = 0 AND ih.transactiondate BETWEEN date_sub('",fromdate,"', interval 1 month) AND '",todate,"') as MTDsales,ih.totalsalesamount AS todayssale, FORMAT((ih.totalsalesamount * mtdtarget/100), @decimal_places) as salestarget, ih.totalreturnamount as returnamt,FORMAT((ih.totalreturnamount * mtdtarget/100), @decimal_places) as returntarget,SUM(freesampleqty) as foc,ih.amountpaid as collection,
(select count(distinct customercode) from invoiceheader where transactiondate  between date_sub('",fromdate,"', interval 3 month) and '",todate,"' group by routecode) as lastcustomerbilled,	count(distinct ih.customercode) as customerbilled,count(distinct ih.invoicenumber) as invbilled,count(distinct id.itemcode) as itembilled, FORMAT((sum(ih.totalinvoiceamount)/count(ih.invoicenumber)), @decimal_places) as avginv,rm.routecode AS routecode, rgm.regionmstcode as regionmstcode, CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.routename) AS route, CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.arbroutename) AS arbroutename, CONCAT(CAST(sm.salesmancode AS CHAR) , ' - ' , sm.salesmanname1) AS salesman,  	regionmstname,arbregionmstname,areaname,arbareaname
	FROM startendday sed
	LEFT JOIN routesequence as rs ON rs.routecode = sed.routecode 	
	LEFT JOIN routesequencecustomerstatus rcs ON rcs.routecode = sed.routecode AND rcs.servicedflag = 1
	LEFT JOIN routegoal  rg ON sed.routecode = rg.routecode
	LEFT JOIN invoiceheader ih ON ih.routecode = sed.routecode AND (ih.voidflag = 0)
	LEFT JOIN invoicedetail as id ON id.routekey = ih.routekey AND id.visitkey = ih.visitkey 
	INNER JOIN routemaster rm ON sed.routecode = rm.routecode
	INNER JOIN subareamaster sam ON sam.subareacode = rm.subareacode
	INNER JOIN areamaster am ON am.areacode = sam.areacode
	INNER JOIN depotmaster dm ON dm.depotcode = am.depotcode
	INNER JOIN regionmaster rgm ON rgm.regionmstcode = dm.regionmstcode
	INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
	Where 1=1",in_where, " GROUP BY rm.routecode ORDER BY ",in_orderby," ",in_sort, " ", limit_val) ;
	
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_salesman_route_summary_old1507` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_salesman_route_summary_old1507` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_salesman_route_summary_old1507`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN fromdate DATE,
IN todate DATE,
IN in_limit VARCHAR(25),
IN in_page VARCHAR(25)
)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
SET @dyn_sql = CONCAT("SELECT count(distinct sed.routecode)	 INTO @in_counter  FROM startendday sed
	LEFT JOIN routesequencecustomerstatus rcs ON rcs.routecode = sed.routecode AND rcs.routekey = sed.routekey AND  rcs.schelduledflag = 1
    LEFT JOIN routesequencecustomerstatus vis ON vis.routecode = sed.routecode AND vis.routekey = sed.routekey AND  vis.schelduledflag = 1 AND vis.servicedflag > 0
    LEFT  JOIN customeroperationscontrol coc on(((coc.routekey = sed.routekey) and ( coc.routecode = sed.routecode)))
	LEFT JOIN routegoal  rg ON sed.routecode = rg.routecode
	LEFT JOIN invoiceheader ih ON ih.routecode = sed.routecode AND ih.routekey = sed.routekey  AND (ih.voidflag = 0)
	LEFT JOIN arheader ah ON ah.routekey = ih.routekey  AND (ah.voidflag = 0)
	LEFT JOIN invoicedetail as id ON id.routekey = ih.routekey AND id.visitkey = ih.visitkey 
INNER JOIN routemaster rm ON sed.routecode = rm.routecode
INNER JOIN subareamaster sam ON sam.subareacode = rm.subareacode
INNER JOIN areamaster am ON am.areacode = sam.areacode
INNER JOIN depotmaster dm ON dm.depotcode = am.depotcode
INNER JOIN regionmaster rgm ON rgm.regionmstcode = dm.regionmstcode
INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
	Where 1=1", in_where," "); 
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		IF @new_start_limit < 0 THEN  SET @new_start_limit = 0; END IF;
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	
	SET @dyn_sql = CONCAT("SELECT sed.routecode,
(select count(distinct customercode) from routesequencecustomerstatus rcs WHERE rcs.routecode = sed.routecode AND rcs.routekey = sed.routekey AND  rcs.schelduledflag = 1) as targetvisits,
(select count(distinct customercode) from routesequencecustomerstatus vis WHERE vis.routecode = sed.routecode AND vis.routekey = sed.routekey AND  vis.servicedflag = 1) as targettovisit,
( select count(distinct customercode) from customeroperationscontrol coc  where `coc`.`routekey` = `sed`.`routekey` and  coc.routecode = sed.routecode and totaltransactions > 0)
 AS productivecalls,   rg.quantity as mtdtarget,
(SELECT SUM(totalsalesamount) FROM salesorderheader ih WHERE ih.routecode = sed.routecode AND (ih.voidflag = 0) AND ih.transactiondate BETWEEN '",fromdate,"'  and '",todate,"') as MTDsales,
(SELECT SUM(totalsalesamount) FROM salesorderheader  WHERE routekey = sed.routekey AND (voidflag = 0) group by routekey) AS todayssale, 
(SELECT ((SUM(totalsalesamount)/ rg.quantity)*100) FROM salesorderheader  WHERE routekey = sed.routekey AND (voidflag = 0) group by routekey) AS  salestarget,
(SELECT ((sum(ih.totalreturnamount)/SUM(totalsalesamount))*100) FROM salesorderheader  WHERE routekey = sed.routekey AND (voidflag = 0) group by routekey) AS  returntarget,
(SELECT SUM(totalreturnamount) FROM salesorderheader  WHERE routekey = sed.routekey AND (voidflag = 0) group by routekey) AS returnamt,
( SELECT SUM(freesampleqty + manualfreeqty) FROM salesorderdetail where routekey = ih.routekey group by routekey) as foc,ah.amountpaid as collection,
(select count(distinct customercode) from salesorderheader where routekey = sed.routekey AND transactiondate  between date_sub('",fromdate,"', interval 2 month) and '",todate,"' group by  routecode) as lastcustomerbilled,	count(distinct ih.customercode) as customerbilled,count(distinct ih.invoicenumber) as invbilled,
count(distinct id.itemcode) as itembilled, (select round((sum(totalinvoiceamount)/count(invoicenumber)),3) FROM salesorderheader  where routekey = sed.routekey  AND (ih.voidflag = 0) group by routekey, routecode) as avginv,rm.routecode AS routecode, rgm.regionmstcode as regionmstcode, CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.routename) AS route, CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.arbroutename) AS arbroutename, CONCAT(CAST(sm.salesmancode AS CHAR) , ' - ' , sm.salesmanname1) AS salesman,  	regionmstname,arbregionmstname,areaname,arbareaname
	FROM startendday sed	
	LEFT JOIN routesequencecustomerstatus rcs ON rcs.routecode = sed.routecode AND rcs.routekey = sed.routekey AND  rcs.schelduledflag = 1
    LEFT JOIN routesequencecustomerstatus vis ON vis.routecode = sed.routecode AND vis.routekey = sed.routekey AND  vis.servicedflag = 1 
    LEFT  JOIN customeroperationscontrol coc on(((coc.routekey = vis.routekey) and (coc.customercode = vis.customercode)))
	LEFT JOIN routegoal  rg ON sed.routecode = rg.routecode
	LEFT JOIN salesorderheader ih ON ih.routecode = sed.routecode AND ih.routekey = sed.routekey  AND (ih.voidflag = 0)
	LEFT JOIN arheader ah ON ah.routekey = ih.routekey  AND (ah.voidflag = 0)
	LEFT JOIN salesorderdetail as id ON id.routekey = ih.routekey AND id.visitkey = ih.visitkey
	INNER JOIN routemaster rm ON sed.routecode = rm.routecode
	INNER JOIN subareamaster sam ON sam.subareacode = rm.subareacode
	INNER JOIN areamaster am ON am.areacode = sam.areacode
	INNER JOIN depotmaster dm ON dm.depotcode = am.depotcode
	INNER JOIN regionmaster rgm ON rgm.regionmstcode = dm.regionmstcode
	INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
	Where 1=1",in_where, "  ORDER BY ",in_orderby," ",in_sort, " ", limit_val) ; 
	
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
select @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_salessummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_salessummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_salessummary`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT
)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter 
			FROM
				invoiceheader ih
					INNER JOIN customermaster cm ON cm.customercode = ih.customercode
					INNER JOIN routemaster rm ON rm.routecode = ih.routecode
					INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
			WHERE
				ih.voidflag = 0 ", in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	 IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	 END IF;
	
	SET @dyn_sql = CONCAT("SELECT
					ih.routekey, ih.visitkey, ih.actualtransactiondate sqltrandate,
					DATE_FORMAT(ih.actualtransactiondate,'%d-%b-%Y') AS transactiondate, ih.transactiontime, ih.invoicenumber,
					CASE WHEN cm.invoicepaymentterms < 2 THEN 'CASH' WHEN cm.invoicepaymentterms = 2 THEN 'CREDIT' ELSE 'TC' END AS mop,
					cm.alternatecode customercode, cm.customername,cm.arbcustomername, rm.routecode, rm.routename,rm.arbroutename, ih.salesmancode, sm.salesmanname1 salesman,
					ih.totalsalesamount AS salesamount, ih.totalreturnamount AS goodreturnamount, ih.totaldamagedamount, ih.totalexpiryamount,
					ih.totalfreesampleamount + ih.totalmanualfree AS freeamount,
					ROUND((ih.totalsalesamount-ih.totalreturnamount-ih.totaldamagedamount-ih.totalexpiryamount) - ih.totalinvoiceamount, 3) AS discountamount,
					ih.totaldiscountamount AS discountamount1,
					ih.totalinvoiceamount AS invoiceamount,
					ih.immediatepaid,
					ih.amountpaid, ih.invoicebalance
				FROM
					invoiceheader ih
					INNER JOIN customermaster cm ON cm.customercode = ih.customercode
					INNER JOIN routemaster rm ON rm.routecode = ih.routecode
					INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
				WHERE
					ih.voidflag = 0 ",in_where, " ORDER BY ih.invoicenumber") ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
	 SELECT @dyn_sql;
    END */$$
DELIMITER ;

