/* Procedure structure for procedure `sp_report_transaction_salessummary_with_permission` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_salessummary_with_permission` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_salessummary_with_permission`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT,
	IN username TEXT
)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
SET @extrawhere = CONCAT(" and rm.subareacode IN (SELECT DISTINCT subareacode  FROM `useraccesscodes` WHERE username='", username ,"')");
		SET in_where=CONCAT(in_where,@extrawhere);
SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter 
			FROM
				invoiceheader ih
					INNER JOIN customermaster cm ON cm.customercode = ih.customercode
					INNER JOIN routemaster rm ON rm.routecode = ih.routecode
					INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
			WHERE
				ih.voidflag = 0 ", in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	 IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	 END IF;
	
	SET @dyn_sql = CONCAT("SELECT
					ih.routekey, ih.visitkey, ih.actualtransactiondate sqltrandate,
					DATE_FORMAT(ih.actualtransactiondate,'%d-%b-%Y') AS transactiondate, ih.transactiontime, ih.invoicenumber,
					CASE WHEN cm.invoicepaymentterms < 2 THEN 'CASH' WHEN cm.invoicepaymentterms = 2 THEN 'CREDIT' ELSE 'TC' END AS mop,
					cm.alternatecode customercode, cm.customername,cm.arbcustomername, rm.routecode, rm.routename,rm.arbroutename, ih.salesmancode, sm.salesmanname1 salesman,
					ih.totalsalesamount AS salesamount, ih.totalreturnamount AS goodreturnamount, ih.totaldamagedamount, ih.totalexpiryamount,
					SUM(FLOOR((freesampleqty+manualfreeqty)/im.unitspercase)) * im.caseprice AS freeamount,
					ROUND((ih.totalsalesamount-ih.totalreturnamount-ih.totaldamagedamount-ih.totalexpiryamount) - ih.totalinvoiceamount, 3) AS discountamount,
					ih.totaldiscountamount AS discountamount1,
					ih.totalinvoiceamount AS invoiceamount,
					ih.immediatepaid,
					ih.amountpaid, ih.invoicebalance,
					SUM(promoamount) as totallinediscount,
					SUM(FLOOR(salesqty/im.unitspercase)) as salescase,	SUM((salesqty%im.unitspercase)) as salespcs,	
					SUM(FLOOR(returnqty/im.unitspercase)) as returncase,	SUM((returnqty%im.unitspercase)) as returnpcs,
					SUM(FLOOR(damagedqty/im.unitspercase)) as damagedcase,	SUM((damagedqty%im.unitspercase)) as damagedpcs,
					SUM(FLOOR((freesampleqty+manualfreeqty)/im.unitspercase)) as freecase,	SUM(((freesampleqty+manualfreeqty)%im.unitspercase)) as freepcs		
				FROM
					invoiceheader ih
					INNER JOIN invoicedetail id ON ih.routekey = id.routekey AND ih.visitkey = id.visitkey
					INNER JOIN itemmaster im ON id.itemcode = im.actualitemcode
					INNER JOIN customermaster cm ON cm.customercode = ih.customercode
					INNER JOIN routemaster rm ON rm.routecode = ih.routecode
					INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
				WHERE
					ih.voidflag = 0 ",in_where, " GROUP BY ih.routekey,ih.visitkey ORDER BY ih.invoicenumber") ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
	 SELECT @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_value_sales_order` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_value_sales_order` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_value_sales_order`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit VARCHAR(25),
IN in_page VARCHAR(25))
BEGIN
DECLARE limitval TEXT DEFAULT "";    
    SET @dyn_sql = CONCAT("SELECT SUM(cnt) INTO @in_counter FROM (select count(*) as cnt
	FROM salesorderheader ih 
INNER JOIN salesorderdetail id ON ih.routekey = id.routekey AND ih.visitkey = id.visitkey
INNER JOIN itemmaster im ON id.itemcode = im.actualitemcode
INNER JOIN customermaster as cm on cm.customercode = ih.customercode
INNER JOIN routemaster as rm on rm.routecode = ih.routecode
INNER JOIN salesman as sm on sm.salesmancode = ih.salesmancode
LEFT JOIN channelmaster as chm on chm.channelcode = cm.channelcode 
where 1=1 ",in_where," union all 
SELECT count(*) as cnt
	FROM InvoiceHeader ih 
INNER JOIN invoicedetail id ON ih.routekey = id.routekey AND ih.visitkey = id.visitkey
INNER JOIN itemmaster im ON id.itemcode = im.actualitemcode
INNER JOIN customermaster AS cm ON cm.customercode = ih.customercode
INNER JOIN routemaster AS rm ON rm.routecode = ih.routecode
INNER JOIN salesman AS sm ON sm.salesmancode = ih.salesmancode
LEFT JOIN channelmaster AS chm ON chm.channelcode = cm.channelcode 
WHERE 1=1 and id.Salesqty>0  ",in_where," union all 
SELECT count(*) as cnt
	FROM InvoiceHeader ih 
INNER JOIN invoicedetail id ON ih.routekey = id.routekey AND ih.visitkey = id.visitkey
INNER JOIN itemmaster im ON id.itemcode = im.actualitemcode
INNER JOIN customermaster AS cm ON cm.customercode = ih.customercode
INNER JOIN routemaster AS rm ON rm.routecode = ih.routecode
INNER JOIN salesman AS sm ON sm.salesmancode = ih.salesmancode
LEFT JOIN channelmaster AS chm ON chm.channelcode = cm.channelcode 
WHERE 1=1 and id.returnqty>0  ",in_where,") AS t1");
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN
		CALL sp_report_calculate_paging_data(@in_counter,in_limit,in_page,@new_start_limit);
		IF @new_start_limit < 0 THEN  SET @new_start_limit = 0; END IF;
		SET @limitval = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	ELSE
		SET @limitval = "";
	END IF;
	  SELECT @new_start_limit AS start_limit,@in_counter AS counter;
	  SELECT decimalplaces INTO @decimal_places FROM currencymaster WHERE defaultcurrency = 1;
	  
	SET @dyn_sql = CONCAT("select sm.salesmanname1, sm.arbsalesmanname1, sm.alternatesalesmancode as salesmancode,
rm.routename,rm.arbroutename, rm.alternateroutecode as routecode,
im.itemshortdescription, im.arbitemshortdescription, im.alternatecode as itemcode, im.companygroupcode as igroupcode,
cm.customername, cm.arbcustomername, cm.alternatecode as customercode, cm.Grouping_Code,cm.Outlet_Quality,
chm.alternatecode as channelcode,chm.channelname, ih.invoicenumber, DATE_FORMAT(transactiondate,'%m-%d-%Y') as invoicedate,id.salesqty,
FORMAT(((FLOOR(salesqty/im.unitspercase)*id.salescaseprice)+((salesqty%im.unitspercase)*id.salesprice)),@decimal_places) as salesvalue,
 'ORDER' AS invoicepayment
	FROM salesorderheader ih 
INNER JOIN salesorderdetail id ON ih.routekey = id.routekey AND ih.visitkey = id.visitkey
INNER JOIN itemmaster im ON id.itemcode = im.actualitemcode
INNER JOIN customermaster as cm on cm.customercode = ih.customercode
INNER JOIN routemaster as rm on rm.routecode = ih.routecode
INNER JOIN salesman as sm on sm.salesmancode = ih.salesmancode
LEFT JOIN channelmaster as chm on chm.channelcode = cm.channelcode 
where 1=1 ",in_where," union all 
SELECT sm.salesmanname1, sm.arbsalesmanname1, sm.alternatesalesmancode AS salesmancode,
rm.routename,rm.arbroutename, rm.alternateroutecode AS routecode,
im.itemshortdescription, im.arbitemshortdescription, im.alternatecode AS itemcode, im.companygroupcode AS igroupcode,
cm.customername, cm.arbcustomername, cm.alternatecode AS customercode, cm.Grouping_Code,cm.Outlet_Quality,
chm.alternatecode AS channelcode,chm.channelname, ih.invoicenumber, DATE_FORMAT(transactiondate,'%m-%d-%Y') AS invoicedate,id.salesqty,
FORMAT(((FLOOR(salesqty/im.unitspercase)*id.salescaseprice)+((salesqty%im.unitspercase)*id.salesprice)),@decimal_places) AS salesvalue,
 payment_mode(case when ih.totalinvoiceamount=ih.immediatepaid then 0 else 2 end ) AS invoicepayment
	FROM InvoiceHeader ih 
INNER JOIN invoicedetail id ON ih.routekey = id.routekey AND ih.visitkey = id.visitkey
INNER JOIN itemmaster im ON id.itemcode = im.actualitemcode
INNER JOIN customermaster AS cm ON cm.customercode = ih.customercode
INNER JOIN routemaster AS rm ON rm.routecode = ih.routecode
INNER JOIN salesman AS sm ON sm.salesmancode = ih.salesmancode
LEFT JOIN channelmaster AS chm ON chm.channelcode = cm.channelcode 
WHERE 1=1 and id.Salesqty>0  ",in_where," union all 
SELECT sm.salesmanname1, sm.arbsalesmanname1, sm.alternatesalesmancode AS salesmancode,
rm.routename,rm.arbroutename, rm.alternateroutecode AS routecode,
im.itemshortdescription, im.arbitemshortdescription, im.alternatecode AS itemcode, im.companygroupcode AS igroupcode,
cm.customername, cm.arbcustomername, cm.alternatecode AS customercode, cm.Grouping_Code,cm.Outlet_Quality,
chm.alternatecode AS channelcode,chm.channelname, ih.invoicenumber, DATE_FORMAT(transactiondate,'%m-%d-%Y') AS invoicedate,id.returnqty,
FORMAT(((FLOOR(returnqty/im.unitspercase)*id.returncaseprice)+((returnqty%im.unitspercase)*id.returnprice)),@decimal_places) AS salesvalue,
 'RETURN' AS invoicepayment
	FROM InvoiceHeader ih 
INNER JOIN invoicedetail id ON ih.routekey = id.routekey AND ih.visitkey = id.visitkey
INNER JOIN itemmaster im ON id.itemcode = im.actualitemcode
INNER JOIN customermaster AS cm ON cm.customercode = ih.customercode
INNER JOIN routemaster AS rm ON rm.routecode = ih.routecode
INNER JOIN salesman AS sm ON sm.salesmancode = ih.salesmancode
LEFT JOIN channelmaster AS chm ON chm.channelcode = cm.channelcode 
WHERE 1=1 and id.returnqty>0  ",in_where,
" ORDER BY ",in_orderby,"  ",in_sort," ",@limitval) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
SELECT @dyn_sql;
END */$$
DELIMITER ;

