/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_volume_sales_order`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit VARCHAR(25),
IN in_page VARCHAR(25))
BEGIN
DECLARE limitval TEXT DEFAULT "";    
    SET @dyn_sql = CONCAT("SELECT SUM(cnt) INTO @in_counter FROM ( SELECT count(*) as cnt
FROM salesorderheader ih 
INNER JOIN salesorderdetail id ON ih.routekey = id.routekey AND ih.visitkey = id.visitkey
INNER JOIN itemmaster im ON id.itemcode = im.actualitemcode
INNER JOIN customermaster as cm on cm.customercode = ih.customercode
INNER JOIN routemaster as rm on rm.routecode = ih.routecode
INNER JOIN salesman as sm on sm.salesmancode = ih.salesmancode
LEFT JOIN channelmaster as chm on chm.channelcode = cm.channelcode 
where 1=1 ", in_where," UNION 
SELECT count(*) as cnt
FROM invoiceheader ih 
INNER JOIN invoicedetail id ON ih.routekey = id.routekey AND ih.visitkey = id.visitkey
INNER JOIN itemmaster im ON id.itemcode = im.actualitemcode
INNER JOIN customermaster as cm on cm.customercode = ih.customercode
INNER JOIN routemaster as rm on rm.routecode = ih.routecode
INNER JOIN salesman as sm on sm.salesmancode = ih.salesmancode
LEFT JOIN channelmaster as chm on chm.channelcode = cm.channelcode 
where 1=1 ", in_where," ) volume ");
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN
		CALL sp_report_calculate_paging_data(@in_counter,in_limit,in_page,@new_start_limit);
		IF @new_start_limit < 0 THEN  SET @new_start_limit = 0; END IF;
		SET @limitval = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	ELSE
		SET @new_start_limit = 0; 
		SET @limitval = CONCAT(" LIMIT 0,",@in_counter);
	END IF;
	  SELECT @new_start_limit AS start_limit,@in_counter AS counter;
	  SELECT decimalplaces INTO @decimal_places FROM currencymaster WHERE defaultcurrency = 1;
	  
	SET @dyn_sql = CONCAT(" SELECT salesmanname1,arbsalesmanname1,salesmancode,routename,arbroutename,routecode,itemshortdescription,arbitemshortdescription,itemcode,
	igroupcode,customername,arbcustomername,customercode,Grouping_Code,Outlet_Quality,channelcode,channelname,invoicenumber,invoicedate,salesqty,freeqty,netqty,invoicepayment
	FROM (SELECT sm.salesmanname1, sm.arbsalesmanname1, sm.alternatesalesmancode as salesmancode ,
rm.routename,rm.arbroutename, rm.alternateroutecode as routecode,
im.itemshortdescription, im.arbitemshortdescription, im.alternatecode as itemcode, im.companygroupcode as igroupcode,
cm.customername, cm.arbcustomername, cm.alternatecode as customercode, cm.Grouping_Code,cm.Outlet_Quality,
chm.alternatecode as channelcode,chm.channelname, ih.invoicenumber, DATE_FORMAT(transactiondate,'%m-%d-%Y') as invoicedate,id.salesqty, (freesampleqty + manualfreeqty) as freeqty,
 (freesampleqty + manualfreeqty+salesqty) as netqty, payment_mode(ih.paymenttype) AS invoicepayment
	FROM salesorderheader ih 
INNER JOIN salesorderdetail id ON ih.routekey = id.routekey AND ih.visitkey = id.visitkey
INNER JOIN itemmaster im ON id.itemcode = im.actualitemcode
INNER JOIN customermaster as cm on cm.customercode = ih.customercode
INNER JOIN routemaster as rm on rm.routecode = ih.routecode
INNER JOIN salesman as sm on sm.salesmancode = ih.salesmancode
LEFT JOIN channelmaster as chm on chm.channelcode = cm.channelcode 
where 1=1  ",in_where,"
UNION
SELECT sm.salesmanname1, sm.arbsalesmanname1, sm.alternatesalesmancode assalesmancode ,
rm.routename,rm.arbroutename, rm.alternateroutecode as routecode,
im.itemshortdescription, im.arbitemshortdescription, im.alternatecode as itemcode, im.companygroupcode as igroupcode,
cm.customername, cm.arbcustomername, cm.alternatecode as customercode, cm.Grouping_Code,cm.Outlet_Quality,
chm.alternatecode as channelcode,chm.channelname, ih.invoicenumber, DATE_FORMAT(transactiondate,'%m-%d-%Y') as invoicedate,id.salesqty, (freesampleqty + manualfreeqty) as freeqty,
 (freesampleqty + manualfreeqty+salesqty) as netqty, payment_mode(ih.paymenttype) AS invoicepayment
	FROM invoiceheader ih 
INNER JOIN invoicedetail id ON ih.routekey = id.routekey AND ih.visitkey = id.visitkey
INNER JOIN itemmaster im ON id.itemcode = im.actualitemcode
INNER JOIN customermaster as cm on cm.customercode = ih.customercode
INNER JOIN routemaster as rm on rm.routecode = ih.routecode
INNER JOIN salesman as sm on sm.salesmancode = ih.salesmancode
LEFT JOIN channelmaster as chm on chm.channelcode = cm.channelcode 
where 1=1  ",in_where,"
)volume ORDER BY ",in_orderby,"  ",in_sort," ",@limitval) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
SELECT @dyn_sql;
END */$$
DELIMITER ;

