/* Procedure structure for procedure `sp_rollback_account_notes_adddebitnotecustomer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_rollback_account_notes_adddebitnotecustomer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_rollback_account_notes_adddebitnotecustomer`(
		IN var_customercode BIGINT(18),
		IN var_trankey 		BIGINT(28)
    )
BEGIN
		declare custocode bigint(18);
		DECLARE amtpaid decimal(18,4);
		DECLARE invoiceno BIGINT(18);
		select customercode,amountpaid into custocode,amtpaid from dcarheader WHERE transactionkey = var_trankey;
		SELECT invoicenumber INTO invoiceno FROM dcardetail WHERE transactionkey = var_trankey and customercode = var_customercode;		
		
		if custocode != var_customercode then
			UPDATE 	dcardetail SET				
					totalinvoiceamount  	= amtpaid,
					amountpaid 				= amtpaid,
					invoicebalance 			= (amtpaid-amtpaid)
			WHERE transactionkey 			= var_trankey;
			
			
			UPDATE customerinvoice SET					
					totalinvoiceamount 		= (totalinvoiceamount-dnamountpaid),
					invoicebalance			= (invoicebalance+dnamountpaid),
					dnamountpaid			= 0
			WHERE invoicenumber 			= invoiceno;
		end IF;
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_routename_salesmancode` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_routename_salesmancode` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_routename_salesmancode`(
			IN var_salesmancode BIGINT
    )
BEGIN
	
	DECLARE cnt INT DEFAULT 0;
	DECLARE records_count INT DEFAULT 0;
	SELECT COUNT(*) INTO cnt FROM routemaster WHERE salesmancode = var_salesmancode ;
	
 	IF cnt > 0 THEN
	
	SELECT routename,routecode,salesmantargetdays FROM routemaster WHERE salesmancode = var_salesmancode LIMIT 1;
	ELSE
	
	SELECT "" AS routename,"" AS routecode,1 AS salesmantargetdays;
	END IF;
	
	
	SELECT COUNT(*) AS records_count,targettype FROM routegoal WHERE salesmancode = var_salesmancode;
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_save_account_customer_addcustomercluster` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_save_account_customer_addcustomercluster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_save_account_customer_addcustomercluster`(
    IN var_divisioncode VARCHAR(255),
    IN var_channel_cft_json JSON
)
BEGIN
    DECLARE valid_division_count INT DEFAULT 0;
    DECLARE saved_rows INT DEFAULT 0;

    SELECT COUNT(*)
    INTO valid_division_count
    FROM company
    WHERE TRIM(NAME) = TRIM(var_divisioncode);

    IF valid_division_count = 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Invalid Division';
    END IF;

    START TRANSACTION;

    DELETE FROM customerclustermapping
    WHERE divisioncode = var_divisioncode;

    INSERT INTO customerclustermapping
    (
        `channel`,
        divisioncode,
        cft
    )
    SELECT
        channel.channelname,
        var_divisioncode,
        COALESCE(input.cft, 0)
    FROM channelmaster AS CHANNEL
    INNER JOIN JSON_TABLE(
        var_channel_cft_json,
        '$[*]' COLUMNS (
            channelname VARCHAR(255) PATH '$.channel',
            cft INT PATH '$.cft'
                NULL ON EMPTY
                NULL ON ERROR
        )
    ) AS input
        ON input.channelname = channel.channelname
    WHERE channel.channelname IS NOT NULL
      AND TRIM(channel.channelname) <> '';

    SET saved_rows = ROW_COUNT();

    IF saved_rows = 0 THEN
        ROLLBACK;

        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'No valid Channel records found';
    ELSE
        COMMIT;
    END IF;

    SELECT saved_rows AS saved_count;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_search_fieldname` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_search_fieldname` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_search_fieldname`(in table_name varchar(50),in database_name varchar(50))
BEGIN
    
		set @qry = 	concat("SELECT DISTINCT TABLE_NAME, COLUMN_NAME  
					FROM INFORMATION_SCHEMA.COLUMNS  
					WHERE column_name LIKE '%",table_name,"%'
					AND TABLE_SCHEMA='",database_name,"'");
		PREPARE s1 FROM @qry;
		EXECUTE s1;
					
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_sfa_report_dailydepositsummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_sfa_report_dailydepositsummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_sfa_report_dailydepositsummary`(
	IN in_where TEXT
)
BEGIN
	SET @temptable = 'sfa_report_dailydepositsummary';
	
	SET @s1 =  CONCAT("DROP TABLE IF EXISTS ", @temptable);
	PREPARE s1 FROM @s1;
	EXECUTE s1;	
	
	SET @sql = CONCAT("
	select 
		'INVOICE' trantype, sed.routestartdate, sed.routeenddate, ih.routekey, ih.visitkey, ih.invoicenumber, 
		ih.actualtransactiondate, ih.transactiontime, 
		ih.salesmancode invoicedby, 0 againstinv, ih.transactiondate saleinvoiceddate,
		ih.customercode, cm.reportcustcode, cm.customername, ih.routecode, rm.routename, ih.salesmancode, sm.salesmanname1, ccd.typecode,
		case when ccd.typecode = 0 then 'CASH' else 'CHEQUE' end paytype,
		ccd.checknumber,
		ccd.checkdate,
		ccd.bankcode,
		bm.bankname,
		ccd.amount,
		case when ccd.typecode = 0 then ccd.amount else 0 end cashamt, 
		case when ccd.typecode = 1 then ccd.amount else 0 end checkamt
	from 
		startendday sed
			inner join invoiceheader ih on ih.routekey = sed.routekey and ih.voidflag = 0
			inner join cashcheckdetail ccd on ccd.routekey = ih.routekey and ccd.visitkey = ih.visitkey and ccd.hhctransactionkey = ih.hhctransactionkey
			inner join customermaster cm on cm.customercode = ih.customercode
			inner join routemaster rm on rm.routecode = ih.routecode
			inner join salesman sm on sm.salesmancode = ih.salesmancode
			left outer join bankmaster bm on bm.bankcode = ccd.bankcode
	where ", in_where,
	
	" union
	
	select 
		'COLLECTION' trantype, sed.routestartdate, sed.routeenddate, arh.routekey, arh.visitkey, arh.invoicenumber, 
		arh.transactiondate, arh.transactiontime, 
		coalesce((select ih1.salesmancode from invoiceheader ih1 where ih1.invoicenumber= ard.invoicenumber),0) invoicedby, 
		ard.alternateinvoicenumber againstinv, ard.invoicedate saleinvoiceddate, 
		arh.customercode, cm.reportcustcode, cm.customername, 
		arh.routecode, rm.routename, arh.salesmancode, sm.salesmanname1, ccd.typecode,
		case when ccd.typecode = 0 then 'CASH' else 'CHEQUE' end paytype,
		ccd.checknumber,
		ccd.checkdate,
		ccd.bankcode,
		bm.bankname, 
		ard.amountpaid + ard.pdcbalance amount,	
		case when ccd.typecode = 0 then ard.amountpaid + ard.pdcbalance else 0 end cashamt, 
		case when ccd.typecode = 1 then ard.amountpaid + ard.pdcbalance else 0 end checkamt
	from 
		startendday sed
			inner join arheader arh on arh.routekey = sed.routekey and arh.voidflag = 0
			inner join ardetail ard on ard.routekey = arh.routekey and ard.visitkey = arh.visitkey 
			inner join cashcheckdetail ccd on ccd.routekey = arh.routekey and ccd.visitkey = arh.visitkey and ccd.hhctransactionkey = arh.hhctransactionkey
			inner join customermaster cm on cm.customercode = arh.customercode
			inner join routemaster rm on rm.routecode = arh.routecode
			inner join salesman sm on sm.salesmancode = arh.salesmancode
			left outer join bankmaster bm on bm.bankcode = ccd.bankcode
	where ", in_where,
	
	" union
	
	select 
		'ADVANCE PAYMENT' trantype, sed.routestartdate, sed.routeenddate, arh.routekey, arh.visitkey, arh.invoicenumber, 
		arh.transactiondate, arh.transactiontime, 
		0 invoicedby, 0 againstinv, '' saleinvoiceddate, 
		arh.customercode, cm.reportcustcode, cm.customername, 
		arh.routecode, rm.routename, arh.salesmancode, sm.salesmanname1, ccd.typecode,
		case when ccd.typecode = 1 then 'CASH' else 'CHEQUE' end paytype,
		ccd.checknumber,
		ccd.checkdate,
		ccd.bankcode,
		bm.bankname,
		arh.amountpaid amount,	
		case when ccd.typecode = 0 then arh.amountpaid else 0 end cashamt, 
		case when ccd.typecode = 1 then arh.amountpaid else 0 end checkamt
	from 
		startendday sed
			inner join arheader arh on arh.routekey = sed.routekey and arh.voidflag = 0
			inner join cashcheckdetail ccd on ccd.routekey = arh.routekey and ccd.visitkey = arh.visitkey and ccd.hhctransactionkey = arh.hhctransactionkey
			inner join customermaster cm on cm.customercode = arh.customercode
			inner join routemaster rm on rm.routecode = arh.routecode
			inner join salesman sm on sm.salesmancode = arh.salesmancode
			left outer join bankmaster bm on bm.bankcode = ccd.bankcode
	where ", in_where);
	SET @s2 =  CONCAT("CREATE TABLE ", @temptable, " AS ", @sql);
	PREPARE s2 FROM @s2;
	EXECUTE s2;	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_sfa_report_dailyrouteinventory` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_sfa_report_dailyrouteinventory` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_sfa_report_dailyrouteinventory`(
	IN in_where TEXT
)
BEGIN
	SET @s1 =  'DROP TABLE IF EXISTS sfa_report_dailyrouteinventory';
	PREPARE s1 FROM @s1;
	EXECUTE s1;	
	
	SET @sql = CONCAT("
	select 
		sed.routekey, sed.routecode, rm.routename, sed.salesmancode, sm.salesmanname1 salesman,
		mc.majorcategorycode, mc.description majorcategroy, 
		im.actualitemcode, im.reportitemcode, im.itemdescription, 	
		
		isd.beginstockqty, 
		cast(isd.beginstockqty/im.unitspercase as UNSIGNED) beginqtycase,
		case when isd.beginstockqty % im.unitspercase <> 0 then isd.beginstockqty % im.unitspercase else 0 end beginqtypcs,
		
		isd.loadqty, 
		cast(isd.loadqty/im.unitspercase as UNSIGNED) loadqtycase,
		case when isd.loadqty % im.unitspercase <> 0 then isd.loadqty % im.unitspercase else 0 end loadqtypcs,
		
		isd.loadaddqty, 
		cast(isd.loadaddqty/im.unitspercase as UNSIGNED) loadaddqtycase,
		case when isd.loadaddqty % im.unitspercase <> 0 then isd.loadaddqty % im.unitspercase else 0 end loadaddqtypcs,
		
		isd.loadcutqty, 
		cast(isd.loadcutqty/im.unitspercase as UNSIGNED) loadcutqtycase,
		case when isd.loadcutqty % im.unitspercase <> 0 then isd.loadcutqty % im.unitspercase else 0 end loadcutqtypcs,
		
		cast(isd.saleqty as UNSIGNED) salesqty, 
		cast(isd.saleqty/im.unitspercase as UNSIGNED) salesqtycase,
		cast(case when isd.saleqty % im.unitspercase <> 0 then isd.saleqty % im.unitspercase else 0 end as UNSIGNED)  salesqtypcs,
		
		cast(isd.returnqty as UNSIGNED) returnqty, 
		cast(isd.returnqty/im.unitspercase as UNSIGNED) returnqtycase,
		cast(case when isd.returnqty % im.unitspercase <> 0 then isd.returnqty % im.unitspercase else 0 end as UNSIGNED)  returnqtypcs,
		
		cast(isd.damageqty as UNSIGNED) damagedqty, 
		cast(isd.damageqty/im.unitspercase as UNSIGNED) damagedqtycase,
		cast(case when isd.damageqty % im.unitspercase <> 0 then isd.damageqty % im.unitspercase else 0 end as UNSIGNED)  damagedqtypcs,
		
		cast(isd.expiryqty as UNSIGNED) expiryqty, 
		cast(isd.expiryqty/im.unitspercase as UNSIGNED) expiryqtycase,
		cast(case when isd.expiryqty % im.unitspercase <> 0 then isd.expiryqty % im.unitspercase else 0 end as UNSIGNED)  expiryqtypcs,
		
		cast(isd.freesampleqty as UNSIGNED) freesampleqty, 
		cast(isd.freesampleqty/im.unitspercase as UNSIGNED) freesampleqtycase,
		cast(case when isd.freesampleqty % im.unitspercase <> 0 then isd.freesampleqty % im.unitspercase else 0 end  as UNSIGNED) freesampleqtypcs,
				
		(isd.endstockqty + isd.unloadqty) endqty, 
		cast((isd.endstockqty + isd.unloadqty)/im.unitspercase as UNSIGNED) endqtycase,
		case when (isd.endstockqty + isd.unloadqty) % im.unitspercase <> 0 then (isd.endstockqty + isd.unloadqty) % im.unitspercase else 0 end endqtypcs,
		
		cast( (cast(((isd.beginstockqty + isd.loadqty + isd.loadaddqty)-isd.loadcutqty)/im.unitspercase as UNSIGNED) * isd.stdsalescaseprice) +
		(case when ((isd.beginstockqty + isd.loadqty + isd.loadaddqty)-isd.loadcutqty) % im.unitspercase <> 0 then (((isd.beginstockqty + isd.loadqty + isd.loadaddqty)-isd.loadcutqty) % im.unitspercase) * isd.stdsalesprice else 0 end) as DECIMAL(18,4)) truckstockvalue,
		
		cast( (cast((isd.endstockqty + isd.unloadqty)/im.unitspercase as UNSIGNED) * isd.stdsalescaseprice) +
		(case when (isd.endstockqty + isd.unloadqty) % im.unitspercase <> 0 then ((isd.endstockqty + isd.unloadqty) % im.unitspercase) * isd.stdsalesprice else 0 end) as DECIMAL(18,4)) endstockvalue
	from 
		startendday sed 
			inner join routemaster rm on sed.routecode = rm.routecode
			inner join salesman sm on sed.salesmancode = sm.salesmancode
			inner join inventorysummarydetail isd on sed.routekey = isd.routekey 
			inner join itemmaster im on isd.itemcode = im.actualitemcode
			inner join itemgroup ig on im.itemgroupcode = ig.itemgroupcode
			inner join submajorcategory smc on ig.submajorcategorycode = smc.submajorcategorycode
			inner join majorcategory mc on smc.majorcategorycode = mc.majorcategorycode			
	where ", in_where) ;
	SET @s2 =  CONCAT("CREATE TABLE sfa_report_dailyrouteinventory AS ", @sql);
	PREPARE s2 FROM @s2;
	EXECUTE s2;	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_sfa_report_invoice` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_sfa_report_invoice` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_sfa_report_invoice`(
	IN invoiceno VARCHAR(15),
	IN datatype VARCHAR(15)
)
BEGIN
	
		IF datatype = 'HEADER' THEN
			
			SET @sql = CONCAT("SELECT
					  ih.documentnumber, 
					  ih.invoicenumber, 
					  ih.transactiondate,
					  rm.routecode AS mboroutecode, rm.alternateroutecode AS erproutecode, rm.routename,
					  sm.salesmancode AS mbosalesmancode, sm.ansalesmancode AS erpsalesmancode, sm.salesmanname1 AS salesman,
					  cm.customercode AS mbocustcode, cm.alternatecode AS erpcustcode, cm.reportcustcode, cm.customername,
					  COALESCE(cm.customeraddress1,'-') customeraddress1, COALESCE(cm.customeraddress2, '-') customeraddress2, COALESCE(cm.customeraddress3, '-') customeraddress3, 
					  COALESCE(cm.customerphone, '-') customerphone, COALESCE(cm.contactname, '-') contactname,
					  ih.totalinvoiceamount, ih.totalsalesamount, ih.totalreturnamount, ih.totaldamagedamount + ih.totalexpiryamount totaldamagedamount,
					  ih.totalfreesampleamount + ih.totalmanualfree totalfreesampleamount,
					  COALESCE((SELECT SUM(pd.promotionamount * pd.promotionquantity) FROM promotiondetail pd WHERE pd.routekey = ih.routekey AND pd.visitkey = ih.visitkey AND pd.itemcode = 0), 0 ) AS totalpromoamount,
					  ih.totalpromoamount AS oldpromoamt, ih.totaldiscountamount AS totaldiscountamount1,
					  ((ih.totalsalesamount-ih.totalreturnamount-ih.totaldamagedamount-ih.totalexpiryamount) - ih.totalinvoiceamount) totaldiscountamount, COALESCE(ih.comments,'-') comments,
					  CASE WHEN ih.voidflag = 1 THEN 'CANCELLED' ELSE 'NORMAL' END AS voidflag,
					  CASE WHEN ih.paymenttype = 1 THEN 'CASH INVOICE' ELSE 'CREDIT INVOICE' END AS paymenttype
				FROM
					  invoiceheader ih
					  INNER JOIN routemaster rm ON ih.routecode = rm.routecode
					  INNER JOIN customermaster cm ON ih.customercode = cm.customercode
					  INNER JOIN salesman sm ON ih.salesmancode = sm.salesmancode
				WHERE
					  ih.invoicenumber = ", invoiceno);			
			
		ELSEIF datatype = 'DETAIL' THEN
		
			SET @sql = CONCAT("SELECT 
				ih.routekey, ih.visitkey, ih.invoicenumber, COALESCE(im.reportitemcode,'') reportitemcode,
				id.itemcode, im.alternatecode, im.itemdescription, im.arbitemdescription, im.unitspercase, 
				
				id.salesqty, 
				CAST(id.salesqty/im.unitspercase AS UNSIGNED) AS salescse,
				CASE WHEN id.salesqty % im.unitspercase <> 0 THEN id.salesqty % im.unitspercase ELSE 0 END AS salespcs,
				
				id.returnqty, 
				CAST(id.returnqty/im.unitspercase AS UNSIGNED) AS returncse,
				CASE WHEN id.returnqty % im.unitspercase <> 0 THEN id.returnqty % im.unitspercase ELSE 0 END AS returnpcs,
				
				id.damagedqty,
				CAST((id.damagedqty+id.expiryqty) /im.unitspercase AS UNSIGNED) AS damagecse,
				CASE WHEN (id.damagedqty+id.expiryqty) % im.unitspercase <> 0 THEN (id.damagedqty+id.expiryqty) % im.unitspercase ELSE 0 END AS damagepcs,
				
				(id.freesampleqty+id.manualfreeqty) freesampleqty, 
				CAST((id.freesampleqty+id.manualfreeqty)/im.unitspercase AS UNSIGNED) AS freecse,
				CASE WHEN (id.freesampleqty+id.manualfreeqty) % im.unitspercase <> 0 THEN (id.freesampleqty+id.manualfreeqty) % im.unitspercase ELSE 0 END AS freepcs,
				
				COALESCE (pq.promoqty,0) AS promoqty, 
				CAST(COALESCE (pq.promoqty,0)/im.unitspercase AS UNSIGNED) AS promocse,
				CASE WHEN COALESCE (pq.promoqty,0) % im.unitspercase <> 0 THEN COALESCE (pq.promoqty,0) % im.unitspercase ELSE 0 END AS promopcs,
				
				COALESCE (pa_s.promoamt,0) - COALESCE (pa_r.promoamt,0) AS promoamt, 
				
				id.salesprice, id.returnprice, id.salescaseprice, id.returncaseprice, 
				id.stdsalesprice, id.stdreturnprice, id.stdsalescaseprice, id.stdreturncaseprice
			FROM 
				invoiceheader ih 
					INNER JOIN invoicedetail id ON ih.routekey = id.routekey AND ih.visitkey = id.visitkey AND ih.invoicenumber = ", invoiceno, "
					INNER JOIN itemmaster im ON id.itemcode = im.actualitemcode
					LEFT OUTER JOIN (SELECT routekey, visitkey, itemcode, SUM(promotionquantity) AS promoqty 
							FROM promotiondetail 
							WHERE promotiontypecode IN (4,7) AND itemtransactiontype = 1 
							GROUP BY routekey, visitkey, itemcode
						) pq ON id.routekey = pq.routekey AND id.visitkey = pq.visitkey AND id.itemcode = pq.itemcode 
					LEFT OUTER JOIN (SELECT routekey, visitkey, itemcode, SUM(promotionamount*promotionquantity) AS promoamt 
							FROM promotiondetail 
							WHERE promotiontypecode IN (1,2,3) AND itemtransactiontype = 1 
							GROUP BY routekey, visitkey, itemcode
						) pa_s ON id.routekey = pa_s.routekey AND id.visitkey = pa_s.visitkey AND id.itemcode = pa_s.itemcode 
					LEFT OUTER JOIN (SELECT routekey, visitkey, itemcode, SUM(promotionamount*promotionquantity) AS promoamt 
							FROM promotiondetail 
							WHERE promotiontypecode IN (1,2,3) AND itemtransactiontype IN (2,3)
							GROUP BY routekey, visitkey, itemcode
						) pa_r ON id.routekey = pa_r.routekey AND id.visitkey = pa_r.visitkey AND id.itemcode = pa_r.itemcode");
			
		END IF;
	
		SET @s2 =  @sql;
		PREPARE s2 FROM @s2;
		EXECUTE s2;	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_sfa_report_kpi_strikerate_callrate_avgtime` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_sfa_report_kpi_strikerate_callrate_avgtime` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_sfa_report_kpi_strikerate_callrate_avgtime`(
	IN in_where TEXT
)
BEGIN
	SET @s1 =  'DROP TABLE IF EXISTS sfa_kpi_report_strikerate_callrate_avgtime';
	PREPARE s1 FROM @s1;
	EXECUTE s1;	
	
	SET @sql = CONCAT("
	SELECT 
		YEAR(sed.routestartdate) AS tranyear,
		MONTH(sed.routestartdate) AS tranmonthno,
		DATE_FORMAT(sed.routestartdate,'%M') AS tranmonthtxt,
		sed.routestartdate, sed.routeenddate, 
		dm.depotcode, dm.depotname, am.areacode, am.areaname, sam.subareacode, sam.subareaname, 
		sed.routecode, rm.routename, rm.alternateroutecode, rm.arbroutename,
		sed.salesmancode, sm.salesmanname1 AS salesman, sm.alternatesalesmancode, sm.arbsalesmanname1,
		
		COALESCE (totaltime.routetime, '00:00:00') routetimespendinminutes,		
		COALESCE (total_sheduled.totalcust, 0) AS totalsheduled, 		
		COALESCE (total_visited.totalcust, 0) AS totalvisited,
		
		COALESCE (total_sheduled_sale.totalcust, 0) AS totalsheduledsale, 
		
		(SELECT COUNT(ih.invoicenumber) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND (ih.voidflag = 0) AND ih.customercode NOT IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) +
		(SELECT COUNT(ih.invoicenumber) FROM salesorderheader ih WHERE ih.routekey = sed.routekey AND (ih.voidflag = 0) AND ih.customercode NOT IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) +
			COALESCE (total_unsheduled_visit.totalcust, 0) AS totalunsheduledvisit,	
				
		(SELECT COUNT(ih.invoicenumber) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND (ih.voidflag = 0) AND ih.customercode NOT IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) +
		(SELECT COUNT(ih.invoicenumber) FROM salesorderheader ih WHERE ih.routekey = sed.routekey AND (ih.voidflag = 0) AND ih.customercode NOT IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) +
			COALESCE (total_unsheduled_sale.totalcust, 0) AS totalunsheduledsale,
					
		COALESCE (total_sheduled_nosale.totalcust, 0) AS totalshedulednosale,
		COALESCE (total_unsheduled_nosale.totalcust, 0) AS totalunshedulednosale,	
		COALESCE (total_unscanned.totalunscan, 0) AS totalunscannedcust,	
		COALESCE (totalcashsale.noofinv, 0) AS totalcashsale,
		COALESCE (totalcreditsale.noofinv, 0) AS totalcreditsale,	
		COALESCE(totalorder.noofinv, 0) AS totalorders,
		
		CASE WHEN COALESCE (total_sheduled.totalcust, 0) > 0 THEN
			((COALESCE (total_visited.totalcust, 0) + COALESCE (total_unsheduled_visit.totalcust, 0)) * 100)  / COALESCE (total_sheduled.totalcust, 0)
		ELSE
			0
		END AS strikerate,	
		
		CASE WHEN COALESCE (total_visited.totalcust, 0) + COALESCE (total_unsheduled_visit.totalcust, 0) > 0 THEN
			CAST(COALESCE (totalcashsale.noofinv, 0) + COALESCE (totalcreditsale.noofinv, 0) + COALESCE(totalorder.noofinv, 0) AS DECIMAL) / CAST(COALESCE (total_visited.totalcust, 0) + COALESCE (total_unsheduled_visit.totalcust, 0) AS DECIMAL) * 100
		ELSE
			0
		END AS productivity,
		
		(COALESCE(total_visited.totalcust,0) * 100) / 
			CASE WHEN COALESCE(total_sheduled.totalcust,0) = 0 THEN 1 ELSE COALESCE(total_sheduled.totalcust,0) END AS callcompleted,
		 
		(COALESCE(total_visited.totalcust,0) * 100) / 
			CASE WHEN (COALESCE(total_visited.totalcust,0)+ COALESCE(total_unsheduled_visit.totalcust,0)) = 0 THEN 1 ELSE 
				(COALESCE(total_visited.totalcust,0)+ COALESCE(total_unsheduled_visit.totalcust,0)) END AS discipline,
	
		COALESCE(sed.routeendodometer, 0) routeendodometer, COALESCE(sed.routestartodometer, 0) routestartodometer, 
		
		CASE WHEN COALESCE(sed.routeendodometer, 0) - COALESCE(sed.routestartodometer, 0) < 0 THEN 0 ELSE 
			COALESCE(sed.routeendodometer, 0) - COALESCE(sed.routestartodometer, 0) END AS kmscovered
		
	FROM 
		startendday sed
		INNER JOIN routemaster rm ON sed.routecode = rm.routecode
		INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
		INNER JOIN subareamaster sam ON rm.subareacode = sam.subareacode
		INNER JOIN areamaster am ON sam.areacode = am.areacode
		INNER JOIN depotmaster dm ON am.depotcode = dm.depotcode
		
		LEFT OUTER JOIN
			(SELECT rsc.routekey, rsc.routecode, COUNT(distinct rsc.customercode) AS totalcust FROM routesequencecustomerstatus rsc 
			WHERE (rsc.schelduledflag = 1) 
			GROUP BY rsc.routekey, rsc.routecode) AS total_sheduled ON sed.routekey = total_sheduled.routekey AND sed.routecode = total_sheduled.routecode
			
		LEFT OUTER JOIN
			(SELECT vis.routekey, vis.routecode, COUNT(distinct vis.customercode) AS totalcust FROM routesequencecustomerstatus vis 
			WHERE (vis.schelduledflag = 1) AND (vis.servicedflag <> 0) 
			GROUP BY vis.routekey, vis.routecode) AS total_visited ON sed.routekey = total_visited.routekey AND sed.routecode = total_visited.routecode
			
		LEFT OUTER JOIN
			(SELECT visout.routekey, visout.routecode, COUNT(distinct visout.customercode) AS totalcust FROM routesequencecustomerstatus visout 
			WHERE (visout.schelduledflag = 0) AND (visout.servicedflag <> 0) 
			GROUP BY visout.routekey, visout.routecode) AS total_unsheduled_visit ON sed.routekey = total_unsheduled_visit.routekey AND sed.routecode = total_unsheduled_visit.routecode
			
		LEFT OUTER JOIN
			(SELECT sale.routekey, sale.routecode, COUNT(distinct sale.customercode) AS totalcust FROM routesequencecustomerstatus sale 
			WHERE (sale.schelduledflag = 1) AND (sale.servicedflag = 1) 
			GROUP BY sale.routekey, sale.routecode) AS total_sheduled_sale ON sed.routekey = total_sheduled_sale.routekey AND sed.routecode = total_sheduled_sale.routecode 
		
		LEFT OUTER JOIN
			(SELECT sale.routekey, sale.routecode, COUNT(distinct sale.customercode) AS totalcust FROM routesequencecustomerstatus sale 
			WHERE (sale.schelduledflag = 0) AND (sale.servicedflag = 1) 
			GROUP BY sale.routekey, sale.routecode) AS total_unsheduled_sale ON sed.routekey = total_unsheduled_sale.routekey AND sed.routecode = total_unsheduled_sale.routecode
			
		LEFT OUTER JOIN
			(SELECT nsale.routekey, nsale.routecode, COUNT(distinct nsale.customercode) AS totalcust FROM routesequencecustomerstatus nsale 
			WHERE (nsale.schelduledflag = 1) AND (nsale.servicedflag = 2) 
			GROUP BY nsale.routekey, nsale.routecode) AS total_sheduled_nosale ON sed.routekey = total_sheduled_nosale.routekey AND sed.routecode = total_sheduled_nosale.routecode
			
		LEFT OUTER JOIN
			(SELECT nsale.routekey, nsale.routecode, COUNT(distinct nsale.customercode) AS totalcust FROM routesequencecustomerstatus nsale 
			WHERE (nsale.schelduledflag = 0) AND (nsale.servicedflag = 2) 
			GROUP BY nsale.routekey, nsale.routecode) AS total_unsheduled_nosale ON sed.routekey = total_unsheduled_nosale.routekey AND sed.routecode = total_unsheduled_nosale.routecode
			
		LEFT OUTER JOIN
			(SELECT nsale.routekey, nsale.routecode, COUNT(distinct nsale.customercode) AS totalunscan FROM routesequencecustomerstatus nsale 
			WHERE (nsale.servicedflag <> 0) AND (nsale.scannedflag = 0) 
			GROUP BY nsale.routekey, nsale.routecode) AS total_unscanned ON sed.routekey = total_unscanned.routekey AND sed.routecode = total_unscanned.routecode
			
		LEFT OUTER JOIN
			(SELECT ih.routekey, ih.routecode, TIMEDIFF(MAX(TIME_FORMAT(ih.transactiontime, '%h:%i %p')),MIN(TIME_FORMAT(ih.transactiontime, '%h:%i %p'))) AS routetime FROM invoiceheader ih 
			GROUP BY ih.routekey, ih.routecode) AS totaltime ON sed.routekey = totaltime.routekey AND sed.routecode = totaltime.routecode
			
		LEFT OUTER JOIN
			(SELECT ih.routekey, ih.routecode, COUNT(DISTINCT ih.customercode) noofinv FROM invoiceheader ih 
			WHERE (ih.immediatepaid != 0) AND (ih.voidflag = 0) AND (ih.totalsalesamount > 0)
			GROUP BY ih.routekey, ih.routecode) AS totalcashsale ON sed.routekey = totalcashsale.routekey AND sed.routecode = totalcashsale.routecode
			
		LEFT OUTER JOIN
			(SELECT ih.routekey, ih.routecode, COUNT(DISTINCT ih.customercode) noofinv FROM invoiceheader ih 
			WHERE (ih.immediatepaid = 0) AND (ih.voidflag = 0) AND (ih.totalsalesamount > 0) 
			GROUP BY ih.routekey, ih.routecode) AS totalcreditsale ON sed.routekey = totalcreditsale.routekey AND sed.routecode = totalcreditsale.routecode 
		
		LEFT OUTER JOIN
			(SELECT ih.routekey, ih.routecode, COUNT(DISTINCT ih.customercode) noofinv FROM salesorderheader ih 
			WHERE (ih.voidflag = 0) 
			GROUP BY ih.routekey, ih.routecode) AS totalorder ON sed.routekey = totalorder.routekey AND sed.routecode = totalorder.routecode
				
	WHERE coalesce(sed.routeclosed,0) = 1 and ",in_where) ;
	SET @s2 =  CONCAT("CREATE TABLE sfa_kpi_report_strikerate_callrate_avgtime AS ", @sql);
	PREPARE s2 FROM @s2;
	EXECUTE s2;	
	SET @s3 = 'UPDATE sfa_kpi_report_strikerate_callrate_avgtime SET routetimespendinminutes = ''00:00:00'' WHERE routetimespendinminutes=''0'' ';
	PREPARE s3 FROM @s3;
	EXECUTE s3;	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_sfa_report_routedailyactivity` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_sfa_report_routedailyactivity` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_sfa_report_routedailyactivity`(
	IN in_where TEXT
)
BEGIN
	SET @s1 =  'DROP TABLE IF EXISTS sfa_report_routedailyactivity';
	PREPARE s1 FROM @s1;
	EXECUTE s1;	
	
	SET @sql = CONCAT("
	select 
		0 visitkey, ith.routekey, 0 customercode, ' ' reportcustcode, ' ' customername, rm.routecode, rm.routename, sm.salesmancode, sm.salesmanname1, 
		' ' customeraddress1, ' ' customeraddress2, ' ' customeraddress3,
		ith.transactiondate visitstartdate, ith.transactiontime visitstarttime, 
		ith.transactiondate visitenddate, ith.transactiontime visitendtime, 
		case when ith.transactiontype = 1 then 'LOAD' when ith.transactiontype = 2 then 'LOAD TRANSFER' when ith.transactiontype = 3 then 'UN-LOAD' else 'LOAD REQUEST ' end trantype,
		ith.documentnumber, 0 tranamount, 0 salepaid, 0 receiptpaid, '00:00:00' timespend, 
		ith.transactiondate trandate
	from 
		startendday sed 
			inner join inventorytransactionheader ith on ith.routekey = sed.routekey
			inner join routemaster rm on rm.routecode = sed.routecode
			inner join salesman sm on sm.salesmancode = sed.salesmancode
	where ", in_where,
		
	" union 
	
	select 
		coc.visitkey, coc.routekey, cm.customercode, cm.reportcustcode, cm.customername, rm.routecode, rm.routename, sm.salesmancode, sm.salesmanname1, 
		cm.customeraddress1, cm.customeraddress2, cm.customeraddress3,
		coc.visitstartdate, CONCAT(coc.visitstarttime,':00') visitstarttime, 
		coc.visitenddate, CONCAT(coc.visitendtime,':00') visitendtime, 
		(select nsr.description from nonservreasons nsr where nsr.code = coc.reasoncode limit 1) as trantype,
		0 documentno, 0 tranamount, 0 salepaid, 0 receiptpaid,
		TIMEDIFF(coc.visitendtime,coc.visitstarttime) timespend,
		coc.visitstartdate trandate
	from 
		startendday sed
			inner join customeroperationscontrol coc on coc.routekey = sed.routekey and coc.reasoncode > 0 
			inner join routemaster rm on rm.routecode = sed.routecode
			inner join salesman sm on sm.salesmancode = sed.salesmancode
			inner join customermaster cm on cm.customercode = coc.customercode
	where 	", in_where,
		
" union
	
	select 
		coc.visitkey, coc.routekey, cm.customercode, cm.reportcustcode, cm.customername, rm.routecode, rm.routename, sm.salesmancode, sm.salesmanname1, 
		cm.customeraddress1, cm.customeraddress2, cm.customeraddress3,
		coc.visitstartdate, CONCAT(coc.visitstarttime,':00') visitstarttime, 
		coc.visitenddate, CONCAT(coc.visitendtime,':00') visitendtime, 
		'INVOICE' trantype, ih.invoicenumber documentno, ih.totalinvoiceamount tranamount, ih.immediatepaid salepaid, 0 receiptpaid,
		TIMEDIFF(coc.visitendtime,coc.visitstarttime) timespend,
		ih.transactiondate trandate
	from 
		startendday sed
			inner join customeroperationscontrol coc on coc.routekey = sed.routekey and coc.reasoncode = 0 and coc.voidflag = 0
			inner join routemaster rm on rm.routecode = sed.routecode
			inner join salesman sm on sm.salesmancode = sed.salesmancode
			inner join customermaster cm on cm.customercode = coc.customercode
			inner join invoiceheader ih on ih.routekey = coc.routekey and ih.visitkey = coc.visitkey
	where ", in_where,
	
	"union
	
	select 
		coc.visitkey, coc.routekey, cm.customercode, cm.reportcustcode, cm.customername, rm.routecode, rm.routename, sm.salesmancode, sm.salesmanname1, 
		cm.customeraddress1, cm.customeraddress2, cm.customeraddress3,
		coc.visitstartdate, CONCAT(coc.visitstarttime,':00') visitstarttime, 
		coc.visitenddate, CONCAT(coc.visitendtime,':00') visitendtime, 
		'ORDER' trantype, soh.invoicenumber documentno, soh.totalinvoiceamount tranamount, 0 salepaid, 0 receiptpaid,
		TIMEDIFF(coc.visitendtime,coc.visitstarttime) timespend,
		soh.transactiondate trandate
	from 
		startendday sed
			inner join customeroperationscontrol coc on coc.routekey = sed.routekey and coc.reasoncode = 0 and coc.voidflag = 0
			inner join routemaster rm on rm.routecode = sed.routecode
			inner join salesman sm on sm.salesmancode = sed.salesmancode
			inner join customermaster cm on cm.customercode = coc.customercode
			inner join salesorderheader soh on soh.routekey = coc.routekey and soh.visitkey = coc.visitkey
	where ", in_where,
	"union
	select 
		coc.visitkey, coc.routekey, cm.customercode, cm.reportcustcode, cm.customername, rm.routecode, rm.routename, sm.salesmancode, sm.salesmanname1, 
		cm.customeraddress1, cm.customeraddress2, cm.customeraddress3,
		coc.visitstartdate, CONCAT(coc.visitstarttime,':00') visitstarttime, 
		coc.visitenddate, CONCAT(coc.visitendtime,':00') visitendtime, 
		'COLLECTION' trantype, ah.invoicenumber documentno, ah.totalinvoiceamount tranamount, 0 salepaid, ah.amountpaid receiptpaid,
		TIMEDIFF(coc.visitendtime,coc.visitstarttime) timespend,
		ah.transactiondate trandate
	from 
		startendday sed
			inner join customeroperationscontrol coc on coc.routekey = sed.routekey and coc.reasoncode = 0 and coc.voidflag = 0
			inner join routemaster rm on rm.routecode = sed.routecode
			inner join salesman sm on sm.salesmancode = sed.salesmancode
			inner join customermaster cm on cm.customercode = coc.customercode
			inner join arheader ah on ah.routekey = coc.routekey and ah.visitkey = coc.visitkey and ah.documentnumber > 0 
	where ", in_where) ;
	SET @s2 =  CONCAT("CREATE TABLE sfa_report_routedailyactivity AS ", @sql);
	PREPARE s2 FROM @s2;
	EXECUTE s2;	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_sfa_report_routedailysummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_sfa_report_routedailysummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_sfa_report_routedailysummary`(
	IN in_where TEXT
)
BEGIN
	SET @s1 =  'DROP TABLE IF EXISTS sfa_report_routedailysummary';
	PREPARE s1 FROM @s1;
	EXECUTE s1;	
	
	SET @sql = CONCAT("SELECT
		sed.routekey, 
		rm.routecode, 
		rm.routename, 
		sm.salesmancode,
		sm.salesmanname1, 
		sed.routestartdate, 
		sed.routestarttime, 
		sed.routeenddate, 
		sed.routeendtime, 
		sed.routestartodometer, 
		COALESCE(sed.routeendodometer,0) routeendodometer,  
		COALESCE ((SELECT COUNT(ih.invoicenumber) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND ih.totalsalesamount + ih.totalfreesampleamount + ih.totalmanualfree > 0), 0 ) totalinvdocuments,
		COALESCE ((SELECT COUNT(ih.invoicenumber) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND ih.totalsalesamount + ih.totalfreesampleamount + ih.totalmanualfree = 0), 0 ) totalinvretdocuments,
		CAST(COALESCE ((SELECT SUM(ih.totalinvoiceamount) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND ih.invoicepaymentterms < 2), 0 ) AS decimal(19,4)) totalcashsales,
		CAST(COALESCE ((SELECT SUM(ih.totalinvoiceamount) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND ih.invoicepaymentterms = 2), 0 ) AS decimal(19,4)) totalgcsales,
		CAST(COALESCE ((SELECT SUM(ih.totalinvoiceamount) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND ih.invoicepaymentterms > 2), 0 ) AS decimal(19,4)) totaltcsales,
		CAST(COALESCE ((SELECT SUM(ih.totalinvoiceamount) FROM invoiceheader ih WHERE ih.routekey = sed.routekey), 0) AS decimal(19,4)) totalinvoiceamount,
		COALESCE ((SELECT COUNT(arh.invoicenumber) FROM arheader arh WHERE arh.routekey = sed.routekey AND arh.amountpaid <> 0), 0 ) totalardocuments,	
		CAST(COALESCE ((SELECT SUM(arh.totalinvoiceamount) FROM arheader arh WHERE arh.routekey = sed.routekey), 0) AS decimal(19,4)) totalacctsreceivable,
		CAST(COALESCE ((SELECT SUM(ccd.amount) FROM cashcheckdetail ccd WHERE ccd.routekey = sed.routekey AND ccd.typecode = 1), 0) AS decimal(19,4)) totalcash,
		CAST(COALESCE ((SELECT SUM(ccd.amount) FROM cashcheckdetail ccd WHERE ccd.routekey = sed.routekey AND ccd.typecode = 2), 0) AS decimal(19,4)) totalchecks,
		CAST(COALESCE ((SELECT SUM(soh.totalinvoiceamount) FROM salesorderheader soh WHERE soh.routekey = sed.routekey), 0) AS decimal(19,4)) totalorderamount,
		COALESCE(sed.totalexpenses, 0) totalexpenses, 
		COALESCE(sed.cashvariance, 0) cashvariance, 
		COALESCE(sed.inventoryvariance,0) inventoryvariance
	FROM 
		startendday sed 
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
	WHERE ",in_where) ;
	SET @s2 =  CONCAT("CREATE TABLE sfa_report_routedailysummary AS ", @sql);
	PREPARE s2 FROM @s2;
	EXECUTE s2;	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_sfa_report_routedepositsummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_sfa_report_routedepositsummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_sfa_report_routedepositsummary`(
	IN in_where TEXT
)
BEGIN
	SET @s1 =  'DROP TABLE IF EXISTS sfa_report_depositsummary';
	PREPARE s1 FROM @s1;
	EXECUTE s1;	
	
	SET @sql = CONCAT("
	select 
		'INVOICE' trantype, ih.transactiondate, 
		ih.routecode, rm.routename, ih.salesmancode, sm.salesmanname1, 
		case when ccd.typecode = 0 then ccd.amount else 0 end as immediatecash,
		case when ccd.typecode = 1 then ccd.amount else 0 end as immediatecheck	
	from
		startendday sed
			inner join invoiceheader ih on ih.routekey = sed.routekey
			inner join routemaster rm on rm.routecode = ih.routecode
			inner join salesman sm on sm.salesmancode = ih.salesmancode
			inner join cashcheckdetail ccd on ccd.routekey = ih.routekey and ccd.visitkey = ih.visitkey and ccd.hhctransactionkey = ih.hhctransactionkey
	where ", in_where,
	
	" union
	
	select 
		'COLLECTION' trantype, arh.transactiondate, 
		arh.routecode, rm.routename, arh.salesmancode, sm.salesmanname1, 
		case when ccd.typecode = 0 then ccd.amount else 0 end as immediatecash,
		case when ccd.typecode = 1 then ccd.amount else 0 end as immediatecheck	
	from 
		startendday sed
			inner join arheader arh on arh.routekey = sed.routekey
			inner join routemaster rm on rm.routecode = arh.routecode
			inner join salesman sm on sm.salesmancode = arh.salesmancode
			inner join cashcheckdetail ccd on ccd.routekey = arh.routekey and ccd.visitkey = arh.visitkey and ccd.hhctransactionkey = arh.hhctransactionkey
	where ", in_where);
	SET @s2 =  CONCAT("CREATE TABLE sfa_report_depositsummary AS ", @sql);
	PREPARE s2 FROM @s2;
	EXECUTE s2;	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_sfa_report_routejourneypaln` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_sfa_report_routejourneypaln` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_sfa_report_routejourneypaln`(
	IN in_where TEXT
)
BEGIN
	SET @s1 =  'DROP TABLE IF EXISTS sfa_report_routejourneypaln';
	PREPARE s1 FROM @s1;
	EXECUTE s1;	
	
	SET @sql = CONCAT("
	SELECT 
		rs.rp32weeknumber, rs.customercode, cm.alternatecode, cm.customername, cm.reportcustcode, cm.customerphone, cm.customeraddress1, customeraddress2, customeraddress3, 
		CASE WHEN cm.invoicepaymentterms > 2 THEN 'TC' WHEN cm.invoicepaymentterms = 2 THEN 'CREDIT' ELSE 'CASH' END mop, 1 AS weekdayno, 'Saturday' AS weekdayname, rs.satseq AS sequenceday, cm.creditlimit, cm.balance, 
		cm.customercategory, cg.categoryname, cm.fixedlatitude, cm.fixedlongitude, satseq visitsequence, rs.routecode, rm.routename
	FROM routesequence rs
		inner join routemaster rm on rm.routecode = rs.routecode
		INNER JOIN customermaster cm ON cm.customercode = rs.customercode
		INNER JOIN categorymaster cg ON cg.categoryid= cm.customercategory 
	WHERE rs.callrestrictiondays6 = 1 AND cm.activecustomer = 1 and ", in_where, "
	UNION 
	SELECT 
		rs.rp32weeknumber, rs.customercode, cm.alternatecode, cm.customername, cm.reportcustcode, cm.customerphone, cm.customeraddress1, customeraddress2, customeraddress3, 
		CASE WHEN cm.invoicepaymentterms > 2 THEN 'TC' WHEN cm.invoicepaymentterms = 2 THEN 'CREDIT' ELSE 'CASH' END mop, 2 AS weekdayno, 'Sunday' AS weekdayname, rs.sunseq AS sequenceday, cm.creditlimit, cm.balance, 
		cm.customercategory, cg.categoryname, cm.fixedlatitude, cm.fixedlongitude, sunseq visitsequence, rs.routecode, rm.routename
	FROM routesequence rs
		inner join routemaster rm on rm.routecode = rs.routecode
		INNER JOIN customermaster cm ON cm.customercode = rs.customercode
		INNER JOIN categorymaster cg ON cg.categoryid= cm.customercategory 
	WHERE rs.callrestrictiondays7 = 1 AND cm.activecustomer = 1 and ", in_where, "
	UNION 
	SELECT 
		rs.rp32weeknumber, rs.customercode, cm.alternatecode, cm.customername, cm.reportcustcode, cm.customerphone, cm.customeraddress1, customeraddress2, customeraddress3, 
		CASE WHEN cm.invoicepaymentterms > 2 THEN 'TC' WHEN cm.invoicepaymentterms = 2 THEN 'CREDIT' ELSE 'CASH' END mop, 3 AS weekdayno, 'Monday' AS weekdayname, rs.monseq AS sequenceday, cm.creditlimit, cm.balance, 
		cm.customercategory, cg.categoryname, cm.fixedlatitude, cm.fixedlongitude, monseq visitsequence, rs.routecode, rm.routename
	FROM routesequence rs
		inner join routemaster rm on rm.routecode = rs.routecode
		INNER JOIN customermaster cm ON cm.customercode = rs.customercode
		INNER JOIN categorymaster cg ON cg.categoryid= cm.customercategory 
	WHERE rs.callrestrictiondays1 = 1 AND cm.activecustomer = 1 and ", in_where, "
	UNION 
	SELECT 
		rs.rp32weeknumber, rs.customercode, cm.alternatecode, cm.customername, cm.reportcustcode, cm.customerphone, cm.customeraddress1, customeraddress2, customeraddress3, 
		CASE WHEN cm.invoicepaymentterms > 2 THEN 'TC' WHEN cm.invoicepaymentterms = 2 THEN 'CREDIT' ELSE 'CASH' END mop, 4 AS weekdayno, 'Tuesday' AS weekdayname, rs.tueseq AS sequenceday, cm.creditlimit, cm.balance, 
		cm.customercategory, cg.categoryname, cm.fixedlatitude, cm.fixedlongitude, tueseq visitsequence, rs.routecode, rm.routename
	FROM routesequence rs
		inner join routemaster rm on rm.routecode = rs.routecode
		INNER JOIN customermaster cm ON cm.customercode = rs.customercode
		INNER JOIN categorymaster cg ON cg.categoryid= cm.customercategory 
		WHERE rs.callrestrictiondays2 = 1 AND cm.activecustomer = 1 and ", in_where, "
	UNION 
	SELECT 
		rs.rp32weeknumber, rs.customercode, cm.alternatecode, cm.customername, cm.reportcustcode, cm.customerphone, cm.customeraddress1, customeraddress2, customeraddress3, 
		CASE WHEN cm.invoicepaymentterms > 2 THEN 'TC' WHEN cm.invoicepaymentterms = 2 THEN 'CREDIT' ELSE 'CASH' END mop, 5 AS weekdayno, 'Wednesday' AS weekdayname, rs.wedseq AS sequenceday, cm.creditlimit, cm.balance, 
		cm.customercategory, cg.categoryname, cm.fixedlatitude, cm.fixedlongitude, wedseq visitsequence, rs.routecode, rm.routename
	FROM routesequence rs
		inner join routemaster rm on rm.routecode = rs.routecode
		INNER JOIN customermaster cm ON cm.customercode = rs.customercode
		INNER JOIN categorymaster cg ON cg.categoryid= cm.customercategory 
	WHERE rs.callrestrictiondays3 = 1 AND cm.activecustomer = 1 and ", in_where, "
	UNION 
	SELECT 
		rs.rp32weeknumber, rs.customercode, cm.alternatecode, cm.customername, cm.reportcustcode, cm.customerphone, cm.customeraddress1, customeraddress2, customeraddress3, 
		CASE WHEN cm.invoicepaymentterms > 2 THEN 'TC' WHEN cm.invoicepaymentterms = 2 THEN 'CREDIT' ELSE 'CASH' END mop, 6 AS weekdayno, 'Thursday' AS weekdayname, rs.thuseq AS sequenceday, cm.creditlimit, cm.balance, 
		cm.customercategory, cg.categoryname, cm.fixedlatitude, cm.fixedlongitude, thuseq visitsequence, rs.routecode, rm.routename
	FROM routesequence rs
		inner join routemaster rm on rm.routecode = rs.routecode
		INNER JOIN customermaster cm ON cm.customercode = rs.customercode
		INNER JOIN categorymaster cg ON cg.categoryid= cm.customercategory 
	WHERE rs.callrestrictiondays4 = 1 AND cm.activecustomer = 1 and ", in_where, "
	UNION 
	SELECT 
		rs.rp32weeknumber, rs.customercode, cm.alternatecode, cm.customername, cm.reportcustcode, cm.customerphone, cm.customeraddress1, customeraddress2, customeraddress3, 
		CASE WHEN cm.invoicepaymentterms > 2 THEN 'TC' WHEN cm.invoicepaymentterms = 2 THEN 'CREDIT' ELSE 'CASH' END mop, 7 AS weekdayno, 'Friday' AS weekdayname, rs.friseq AS sequenceday, cm.creditlimit, cm.balance, 
		cm.customercategory, cg.categoryname, cm.fixedlatitude, cm.fixedlongitude, friseq visitsequence, rs.routecode, rm.routename
	FROM routesequence rs
		inner join routemaster rm on rm.routecode = rs.routecode
		INNER JOIN customermaster cm ON cm.customercode = rs.customercode
		INNER JOIN categorymaster cg ON cg.categoryid= cm.customercategory 
	WHERE rs.callrestrictiondays5 = 1 AND cm.activecustomer = 1 and ", in_where) ;
	SET @s2 =  CONCAT("CREATE TABLE sfa_report_routejourneypaln AS ", @sql);
	PREPARE s2 FROM @s2;
	EXECUTE s2;	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_sfa_report_routetripanalysis` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_sfa_report_routetripanalysis` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_sfa_report_routetripanalysis`(
	IN in_where TEXT
)
BEGIN
	SET @s1 =  'DROP TABLE IF EXISTS sfa_report_routetripanalysis';
	PREPARE s1 FROM @s1;
	EXECUTE s1;	
	
	SET @sql = CONCAT("
	SELECT 
		coc.visitstartdate currentdate, 
		sed.routekey,
		COALESCE(coc.visitkey, 9999) visitkey,
		sed.routestartdate,	
		sed.routeenddate,	
		rscs.seqweekday, 	
		DAYNAME(coc.visitstartdate) currentdayname,		
		rscs.sequencenumber visitsequence, 
		sed.routecode, rm.routename, 
		sed.salesmancode, sm.salesmanname1 salesmanname, 
		rscs.customercode, cm.alternatecode reportcustcode, cm.customername, 
		CASE WHEN cm.invoicepaymentterms < 2 THEN 'CASH' WHEN cm.invoicepaymentterms = 2 THEN 'CREDIT' ELSE 'TC' END AS mop,
		rscs.schelduledflag, 
		(SELECT MAX(coc.visitstartdate) lastvisit FROM customeroperationscontrol coc WHERE coc.customercode = cm.customercode) lastviiston,
		(SELECT MAX(ih.transactiondate) lastvisit FROM invoiceheader ih WHERE ih.customercode = cm.customercode) lastsalesdate,
		(SELECT MAX(soh.transactiondate) lastvisit FROM salesorderheader soh WHERE soh.customercode = cm.customercode) lastorderdate,
		CASE WHEN rscs.schelduledflag = 0 THEN 'NO' ELSE 'YES' END visitsheduled, 
			
		coc.visitstartdate, 
		coc.visitenddate, 
		
		CONCAT(COALESCE(coc.visitstarttime, '00:00'),':00') visitstarttime, 
		CONCAT(COALESCE(coc.visitendtime, '00:00'),':00') visitendtime, 
					
		COALESCE(coc.totaltransactions, 0) totaldocs, 
		COALESCE(sale.docscount, 0) invdocs, 
		COALESCE(ar.docscount, 0) ardocs,	
		rscs.servicedflag,
		
		CASE WHEN rscs.servicedflag = 1 THEN 'VISITED' ELSE 'NOT VISITED' END visitstatus, 
							
		CASE 
			WHEN (rscs.servicedflag > 0 AND COALESCE(coc.totaltransactions, 0) = 0) THEN 'NO TRANSACTION'			
				WHEN (rscs.servicedflag = 1 AND COALESCE(sale.docscount, 0) = 1) THEN 'SALES'
					WHEN (rscs.servicedflag = 1 AND COALESCE(so.docscount, 0) = 1) THEN 'ORDER'
						WHEN (rscs.servicedflag = 1 AND COALESCE(ar.docscount, 0) = 1) THEN 'COLLECTION' 
							ELSE 'NOT VISITED' END servicetype, 
					   
		CASE
			WHEN COALESCE(sale.docscount, 0) = 1 THEN sale.totalinvoiceamount
				WHEN COALESCE(so.docscount, 0) = 1 THEN so.totalorderamount
					WHEN COALESCE(ar.docscount, 0) = 1 THEN ar.amountpaid 
						ELSE 0 END transactionamount,	
		
		CASE
			WHEN COALESCE(sale.docscount, 0) = 1 THEN sale.invoicenumber
				WHEN COALESCE(so.docscount, 0) = 1 THEN so.invoicenumber
					WHEN COALESCE(ar.docscount, 0) = 1 THEN ar.invoicenumber 
						ELSE 0 END transactionno,	
						
		(SELECT nsr.description 
			FROM nonservicedcustomer nsc, nonservreasons nsr 
			WHERE nsc.routekey = rscs.routekey AND nsc.customercode = rscs.customercode AND nsc.reasoncode = nsr.code LIMIT 1) nosalereason		
		
	FROM 
		startendday sed
			INNER JOIN routesequencecustomerstatus rscs ON sed.routekey = rscs.routekey
			INNER JOIN routemaster rm ON sed.routecode = rm.routecode
			INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
			INNER JOIN customermaster cm ON rscs.customercode = cm.customercode
			INNER JOIN customeroperationscontrol coc ON rscs.routekey = coc.routekey AND rscs.customercode = coc.customercode AND coc.voidflag = 0
			
			LEFT OUTER JOIN
				(SELECT ih.routekey, ih.visitkey, ih.routecode, ih.customercode, ih.invoicenumber, 
					COUNT(ih.invoicenumber) AS docscount, CAST(SUM(ih.totalinvoiceamount) AS DECIMAL(19,4)) totalinvoiceamount
					FROM invoiceheader ih
					GROUP BY ih.routekey, ih.visitkey, ih.routecode, ih.customercode, ih.invoicenumber) sale ON coc.routekey = sale.routekey AND coc.customercode = sale.customercode AND coc.visitkey = sale.visitkey
			
			LEFT OUTER JOIN
				(SELECT soh.routekey, soh.visitkey, soh.routecode, soh.customercode, soh.invoicenumber, 
					COUNT(soh.invoicenumber) AS docscount, CAST(SUM(soh.totalinvoiceamount) AS DECIMAL(19,4)) totalorderamount
					FROM salesorderheader soh
					GROUP BY soh.routekey, soh.visitkey, soh.routecode, soh.customercode, soh.invoicenumber) so ON coc.routekey = so.routekey AND coc.customercode = so.customercode AND coc.visitkey = so.visitkey
					
			LEFT OUTER JOIN
				(SELECT arh.routekey, arh.visitkey, arh.routecode, arh.customercode, arh.invoicenumber, 
					COUNT(arh.invoicenumber) AS docscount, CAST(SUM(arh.amountpaid) AS DECIMAL(19,4)) amountpaid
					FROM arheader arh
					GROUP BY arh.routekey, arh.visitkey, arh.routecode, arh.customercode, arh.invoicenumber) ar ON coc.routekey = ar.routekey AND coc.customercode = ar.customercode AND coc.visitkey = ar.visitkey
			
			LEFT OUTER JOIN  
				(SELECT ns.routekey, ns.visitkey, ns.routecode, ns.customercode, ns.nosalereasoncode, nsr.description  
					FROM nosalesheader ns, nonservreasons nsr
					WHERE ns.nosalereasoncode = nsr.code) nosale ON coc.routekey = nosale.routekey AND coc.customercode = nosale.customercode AND coc.visitkey = nosale.visitkey
	WHERE ", in_where) ;
	SET @s2 =  CONCAT("CREATE TABLE sfa_report_routetripanalysis AS ", @sql);
	PREPARE s2 FROM @s2;
	EXECUTE s2;	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_sfa_report_salesmanproductivity` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_sfa_report_salesmanproductivity` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_sfa_report_salesmanproductivity`(
	IN in_where TEXT
)
BEGIN
	SET @s1 =  'DROP TABLE IF EXISTS sfa_report_salesmanproductivity';
	PREPARE s1 FROM @s1;
	EXECUTE s1;	
	
	SET @sql = CONCAT("
	SELECT 'SALES' transactiontype, YEAR(ih.transactiondate) yearno,MONTH(ih.transactiondate) monthno, MONTHNAME(ih.transactiondate) monthtxt, SUM(ih.totalinvoiceamount) amount,
		ih.salesmancode, sm.salesmanname1, 
		ih.routecode, rm.routename
	FROM invoiceheader ih
		INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
		INNER JOIN routemaster rm ON rm.routecode = ih.routecode
	WHERE ih.voidflag = 0 and ", in_where, "
	GROUP BY YEAR(ih.transactiondate),MONTH(ih.transactiondate), MONTHNAME(ih.transactiondate), ih.salesmancode, sm.salesmanname1, ih.routecode, rm.routename
	UNION
	SELECT 'ORDER' transactiontype,  YEAR(ih.transactiondate) yearno,MONTH(ih.transactiondate) monthno, MONTHNAME(ih.transactiondate) monthtxt, SUM(ih.totalinvoiceamount) amount,
		ih.salesmancode, sm.salesmanname1, 
		ih.routecode, rm.routename
	FROM salesorderheader ih
		INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
		INNER JOIN routemaster rm ON rm.routecode = ih.routecode
	WHERE ih.voidflag = 0 and ", in_where, "
	GROUP BY YEAR(ih.transactiondate),MONTH(ih.transactiondate), MONTHNAME(ih.transactiondate), ih.salesmancode, sm.salesmanname1, ih.routecode, rm.routename
	UNION
	SELECT 'COLLECTION' transactiontype,  YEAR(ih.transactiondate) yearno,MONTH(ih.transactiondate) monthno, MONTHNAME(ih.transactiondate) monthtxt, SUM(ih.totalinvoiceamount) amount,
		ih.salesmancode, sm.salesmanname1, 
		ih.routecode, rm.routename
	FROM arheader ih
		INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
		INNER JOIN routemaster rm ON rm.routecode = ih.routecode
	WHERE ih.voidflag = 0 and ", in_where, "
	GROUP BY YEAR(ih.transactiondate),MONTH(ih.transactiondate), MONTHNAME(ih.transactiondate), ih.salesmancode, sm.salesmanname1, ih.routecode, rm.routename
") ;
	SET @s2 =  CONCAT("CREATE TABLE sfa_report_salesmanproductivity AS ", @sql);
	PREPARE s2 FROM @s2;
	EXECUTE s2;	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_site_modules_forms_list` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_site_modules_forms_list` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_site_modules_forms_list`(
		IN moduleids TEXT
	)
BEGIN
	
	DECLARE add_where TEXT DEFAULT NULL;
	DECLARE where_cond TEXT;
	DECLARE flag_status INT(1);
	
	SELECT `status` INTO flag_status FROM controlpanel WHERE flagid = 77;
	
	IF moduleids != '' THEN
		SET add_where = CONCAT(" mh.moduleid IN( ",moduleids,")");		
	ELSE
		SET add_where = "1 = 1";
	END IF;
	
	if flag_status = 0 then 
		set where_cond = ' md.moduleid <> 9 ';
	ELSE
		SET where_cond = " 2 = 2";
	end if;
	
	
	SET @dyn_sql = CONCAT("SELECT mh.moduleid, mh.modulename, md.formid,md.formname, md.formdescription FROM moduledetail as md
	LEft join moduleheader as mh ON mh.moduleid = md.moduleid
	where ",add_where," AND ",where_cond," AND formname NOT LIKE '%**%'
	order by FIELD(md.moduleid,1,2,3,4,5,6,7,9,8,10,11,12,13),md.order");
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_site_search_modules_forms_list` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_site_search_modules_forms_list` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_site_search_modules_forms_list`(
	IN type_val INT,
	IN searchval INT,
	IN moduleids TEXT
)
BEGIN
	DECLARE add_where TEXT DEFAULT NULL;
	DECLARE tablename TEXT DEFAULT NULL;
	DECLARE user_where TEXT DEFAULT NULL;
	declare cloud_tran_status int;
	
	select `status` into cloud_tran_status from controlpanel WHERE flagid = 77;
	
	SET add_where = "1 = 1";
	IF moduleids != "" THEN 
		if cloud_tran_status = 1 then
			set moduleids = replace(moduleids,8,'8,9');
		end if;	
		SET add_where = CONCAT(add_where," and mh.moduleid IN (",moduleids,")");
	END IF;
	
	IF type_val != "" && searchval != "" THEN 
		IF type_val = 1 THEN
			SET user_where = CONCAT( " and ud.userid = ",searchval);
			SET tablename = "userdetail";
		ELSE
			SET user_where = CONCAT(" and usertypeid = ",searchval);
			SET tablename = "usertypedetail";
		END IF;
	END IF;
	
	SET @dyn_sql = CONCAT("SELECT count(*) as cnt FROM ",tablename," as ud
				WHERE 1=1 ",user_where);
	
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	SET @dyn_sql = CONCAT("SELECT mh.moduleid, mh.modulename, md.formid,md.formname, md.formdescription,ud.readdata,ud.updatedata,ud.insertdata,ud.deletedata,ud.allpermissions
	 FROM moduledetail AS md
	  LEFT JOIN moduleheader AS mh
		ON mh.moduleid = md.moduleid
	  LEFT JOIN ",tablename," AS ud 
		ON ud.formid = md.formid  ",user_where," 
	where ",add_where," GROUP BY formid 
	order by FIELD(md.moduleid,1,2,3,4,5,6,7,9,8,10,11,12,13),md.order");
	 
	 PREPARE s1 FROM @dyn_sql;	 
	 EXECUTE s1;
	 
	 
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_split` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_split` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_split`( in str text, in del char(10))
BEGIN
    
    declare my_name 	varchar(55);
    DECLARE my_surname 	VARCHAR(55);
    DECLARE my_village 	VARCHAR(55);
    declare from_start	int;
    set from_start = 1;
    
    WHILE from_start <= 3 DO
		  set my_name = split(str,del,from_start);
		  SET  from_start = from_start + 1;
		  SELECT my_name;
	END WHILE;	
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_test_demo` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_test_demo` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_test_demo`(
in route_code int
)
BEGIN
DECLARE in_flag_id int;
DECLARE in_depo_code INT;
 DECLARE rcode INT;
    DECLARE gen_customercode INT;	
SELECT flagid into in_flag_id  FROM controlpanel  WHERE flagid IN ('7','8','9','76') AND `status`=1;
SELECT flagid INTO in_flag_id  FROM controlpanel  WHERE flagid IN ('7','8','9','76') AND `status`=1;
	IF in_flag_id = 7 THEN 
	
	SELECT MAX(customercode) INTO rcode FROM customermaster
	WHERE routecode =route_code  AND SUBSTRING(customercode,1,3) LIKE route_code
	GROUP BY routecode ;	
	
		IF rcode IS NULL   THEN
			SET rcode =1;
			SET gen_customercode = CONCAT(route_code,'0000',rcode);
		 ELSE
			SET rcode = rcode +1 ;
			SET gen_customercode = CONCAT(route_code,rcode);
		END IF;
		
	ELSE
	SELECT MAX(customercode) INTO rcode FROM customermaster;
		IF rcode IS NULL   THEN
			SET rcode =1;
			SET gen_customercode = CONCAT('0000',rcode);
		 ELSE
			SET rcode = rcode +1 ;
			SET gen_customercode = CONCAT(rcode);
		END IF;
	
	END IF;
	
	SELECT gen_customercode,rcode,in_flag_id;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_text_query` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_text_query` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_text_query`(
	    IN txtquery text,	    
	    IN `createdby` VARCHAR(30)
	)
BEGIN	
	IF txtquery != '' THEN
		
		SET @chk = txtquery;	
		PREPARE s1 FROM @chk;
		EXECUTE s1;		
	END IF;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_trasfer_ordertransaction_salesorderadd_tempdata` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_trasfer_ordertransaction_salesorderadd_tempdata` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_trasfer_ordertransaction_salesorderadd_tempdata`(
IN in_transaction_key INT,
IN in_routekey INT,
IN in_visitkey INT,
IN in_route_code BIGINT
)
BEGIN
	DECLARE new_document_no varchar(255);
	DECLARE new_invoice_no varchar(255);
	DECLARE lastinsert_id INT;
	DECLARE new_visit_key INT;
	DECLARE new_amount DECIMAL(19,4);
	DECLARE in_customer_id INT;
	
	UPDATE routemaster SET  boordseq = IFNULL(boordseq,0) + 1, bodocseq = IFNULL(bodocseq,0) + 1
	WHERE  routecode =in_route_code;	
	
	SELECT get_number_type_base(in_route_code,3), get_number_type_base(in_route_code,2)
	INTO new_invoice_no,new_document_no;
	
			
	
	SELECT IFNULL(MAX(customeroperationscontrol.visitkey),0) INTO new_visit_key FROM customeroperationscontrol
	WHERE  customeroperationscontrol.routekey =in_routekey ;
	SET new_visit_key =new_visit_key + 1;
	
	
	INSERT INTO customeroperationscontrol (visitkey,routekey,customercode,salesmancode,routecode,visitstartdate,
	visitstarttime,visitenddate,visitendtime,totaltransactions,voidflag)
	SELECT new_visit_key,in_routekey,customercode,salesmancode ,routecode,transactiondate,transactiontime,
	DATE(CURRENT_DATE()),TIME(CURRENT_DATE()),1,voidflag FROM 
	salesorderheader_temp WHERE transactionkey = in_transaction_key;
		
	
	CALL sp_trasfer_ordertransaction_salesorderadd_tempdata_invoice(in_transaction_key,in_routekey,new_visit_key,new_document_no,new_invoice_no,@new_transaction_key);
	SET lastinsert_id = @new_transaction_key;
	
	CALL sp_trasfer_ordertransaction_salesorderadd_tempdata_item(lastinsert_id,in_routekey,new_visit_key,in_transaction_key);
	CALL sp_trasfer_ordertransaction_salesorderadd_tempdata_promotion(lastinsert_id,in_routekey,new_visit_key,in_transaction_key);
	CALL sp_trasfer_ordertransaction_salesorderadd_tempdata_signaturedet(lastinsert_id,in_routekey,new_visit_key,in_transaction_key,new_document_no);
	call sp_trasfer_ordertransaction_salesorderadd_tempdata_delete(in_transaction_key);
    
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_trasfer_ordertransaction_salesorderadd_tempdata_delete` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_trasfer_ordertransaction_salesorderadd_tempdata_delete` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_trasfer_ordertransaction_salesorderadd_tempdata_delete`(
IN in_transaction_key INT
)
BEGIN
	DELETE FROM salesorderheader_temp WHERE salesorderheader_temp.transactionkey = in_transaction_key;
	DELETE FROM salesorderdetail_temp WHERE salesorderdetail_temp.transactionkey = in_transaction_key;
	DELETE FROM promotiondetail_temp WHERE promotiondetail_temp.transactionkey = in_transaction_key;
	DELETE FROM sigcapturedata_temp WHERE sigcapturedata_temp.transactionkey = in_transaction_key;
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_trasfer_ordertransaction_salesorderadd_tempdata_invoice` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_trasfer_ordertransaction_salesorderadd_tempdata_invoice` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_trasfer_ordertransaction_salesorderadd_tempdata_invoice`(
IN in_transaction_key INT,
IN in_routekey INT,
IN new_visit_key INT,
IN new_document_no DECIMAL(28),
IN new_invoice_no DECIMAL(28),
OUT new_transaction_key INT
)
BEGIN
	UPDATE salesorderheader_temp 
	SET 
	totalinvoiceamount=(IFNULL(totalsalesamount,0)-IFNULL(totalreturnamount,0)-IFNULL(totalpromoamount,0)-IFNULL(totaldamagedamount,0))
	WHERE 
	salesorderheader_temp.transactionkey = in_transaction_key;
	INSERT INTO salesorderheader 
	(routekey,visitkey,documentnumber,invoicenumber,transactiondate,transactiontime,dsdnumber,ponumber,
	customercode,routecode,salesmancode,orderdeliveryroutecode,orderdeliverydate,totalinvoiceamount,
	totalsalesamount,totalreturnamount,totaldamagedamount,dexflag,splittransaction,voidflag,transmitindicator,
	hhcinvoicenumber,paymenttype,hhcdocumentnumber,voidreasoncode,advanceused,paymentstatus,advancebalance,mdat,
	advancereceived,currencycode,`status`,refnumber,totalfreesampleamount,deliverystatus,`data`,comments,
	actualtransactiondate,comments2,hhctransactionkey,totalpromoamount,record_flag)
	
	select  
	in_routekey,new_visit_key,new_document_no,new_invoice_no,transactiondate,transactiontime,dsdnumber,ponumber,
	customercode,routecode,salesmancode,orderdeliveryroutecode,orderdeliverydate,totalinvoiceamount,
	totalsalesamount,totalreturnamount,totaldamagedamount,dexflag,splittransaction,voidflag,transmitindicator,
	hhcinvoicenumber,paymenttype,hhcdocumentnumber,voidreasoncode,advanceused,paymentstatus,advancebalance,mdat,
	advancereceived,get_default_currencycode(),`status`,refnumber,totalfreesampleamount,deliverystatus,`data`,comments,
	actualtransactiondate,comments2,hhctransactionkey,totalpromoamount,0
	from salesorderheader_temp
	where 
	salesorderheader_temp.transactionkey = in_transaction_key;
	
	SELECT LAST_INSERT_ID() INTO new_transaction_key;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_trasfer_ordertransaction_salesorderadd_tempdata_item` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_trasfer_ordertransaction_salesorderadd_tempdata_item` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_trasfer_ordertransaction_salesorderadd_tempdata_item`(
IN in_auto_transaction_key INT,
IN in_routekey INT,
IN in_visit_key INT,
IN in_transaction_key INT
)
BEGIN
DECLARE in_line_item_discount DECIMAL(19,4);
	INSERT INTO salesorderdetail
	(routekey,visitkey,transactionkey,itemcode,salesqty,returnqty,damagedqty,freesampleqty,salesprice,returnprice, 
	stdsalesprice,stdreturnprice,coopid,salescaseprice,returncaseprice,stdsalescaseprice,stdreturncaseprice,currencycode, 
	allocated,freegoodcases,freegoodpcs,salespcs,allocatedcases,salescases,allocatedpcs,returncases,returnpcs, 
	promoamount,manualfreeqty,sales_amount,promovalue,goodreturnprice,goodreturncaseprice)
	
	SELECT in_routekey,in_visit_key,in_auto_transaction_key,itemcode,salesqty,returnqty,damagedqty,freesampleqty,salesprice,returnprice, 
	stdsalesprice,stdreturnprice,coopid,salescaseprice,returncaseprice,stdsalescaseprice,stdreturncaseprice,get_default_currencycode(), 
	allocated,freegoodcases,freegoodpcs,salespcs,allocatedcases,salescases,allocatedpcs,returncases,returnpcs, 
	promoamount,manualfreeqty,sales_amount,promovalue,goodreturnprice,goodreturncaseprice
	FROM salesorderdetail_temp WHERE 
	transactionkey = in_transaction_key;
	
	SET in_line_item_discount = 0;
	
	SELECT IFNULL(SUM(salesorderdetail.promoamount),0) INTO in_line_item_discount FROM salesorderdetail WHERE 
	salesorderdetail.transactionkey =in_auto_transaction_key;
	
	UPDATE salesorderheader SET  
	lineitemdiscount =  in_line_item_discount,
	hhctransactionkey = in_auto_transaction_key
	WHERE transactionkey =in_auto_transaction_key;
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_trasfer_ordertransaction_salesorderadd_tempdata_promotion` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_trasfer_ordertransaction_salesorderadd_tempdata_promotion` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_trasfer_ordertransaction_salesorderadd_tempdata_promotion`(
in_auto_transaction_key INT,
IN in_routekey INT,
IN in_visit_key INT,
IN in_transaction_key INT
)
BEGIN
	UPDATE promotiondetail_temp SET itemcode = 0
	WHERE promotiondetail_temp.transactionkey = in_transaction_key
	AND promotiontypecode IN(5,6);
	
	INSERT INTO promotiondetail 
	(routekey,visitkey,transactionkey,itemtransactiontype,itemcode,promotiontypecode,
	promotionamount,promotionquantity,catchweightqty,weighted,promotionplannumber,assignmentkey,exclusionoption, 
	promochgindicator,oldpromotionamount,performindicator,performcriteriakey,promotioncaseprice, 
	currencycode,salesamount,rangelow, repeatingrange)
	
	SELECT in_routekey,in_visit_key,in_auto_transaction_key,itemtransactiontype,itemcode,
	promotiontypecode,promotionamount,promotionquantity,catchweightqty,weighted,promotionplannumber,
	assignmentkey,exclusionoption, promochgindicator,oldpromotionamount,performindicator,performcriteriakey,
	promotioncaseprice, get_default_currencycode(),salesamount,rangelow, repeatingrange
	FROM promotiondetail_temp
	WHERE promotiondetail_temp.transactionkey = in_transaction_key AND itemtransactiontype = 4;
	
	
	UPDATE promotiondetail AS p JOIN salesorderdetail ON salesorderdetail.itemcode = p.itemcode
	 AND salesorderdetail.visitkey=p.visitkey AND salesorderdetail.routekey=p.routekey 
	 SET p.promotionquantity=salesorderdetail.freesampleqty WHERE p.promotiontypecode=7 
	 AND p.visitkey = in_visit_key AND p.routekey = in_routekey;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_trasfer_ordertransaction_salesorderadd_tempdata_signaturedet` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_trasfer_ordertransaction_salesorderadd_tempdata_signaturedet` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_trasfer_ordertransaction_salesorderadd_tempdata_signaturedet`(
in_auto_transaction_key INT,
IN in_routekey INT,
IN in_visit_key INT,
IN in_transaction_key INT,
IN new_document_no  varchar(255)
)
BEGIN
	INSERT INTO sigcapturedata 
	(routekey, visitkey, transactionkey, customercode, transactiondate,  balancedueamount,signaturedata,documentnumber,transaction_type)
	
	SELECT in_routekey,in_visit_key,in_auto_transaction_key,customercode,transactiondate,balancedueamount,signaturedata,new_document_no,transaction_type
	FROM sigcapturedata_temp WHERE 
	sigcapturedata_temp.transactionkey =in_transaction_key AND transaction_type =4;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_trasfer_transaction_invoiceadd_tempdata` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_trasfer_transaction_invoiceadd_tempdata` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_trasfer_transaction_invoiceadd_tempdata`(
IN in_transaction_key INT,
IN in_routekey INT,
IN in_visitkey INT,
IN in_route_code BIGINT,
IN in_gcpayment_type INT,
IN in_paymenttype INT
)
BEGIN
DECLARE new_document_no VARCHAR(255);
DECLARE new_invoice_no VARCHAR(255);
DECLARE lastinsert_id INT;
DECLARE new_visit_key INT;
DECLARE new_amount DECIMAL(19,4);
DECLARE in_customer_id BIGINT;
DECLARE gc_paymenttype INT DEFAULT 0;
DECLARE pdc_as_cash INT DEFAULT 0;
 
	UPDATE routemaster SET  boinvseq = IFNULL(boinvseq,0) + 1, bodocseq = IFNULL(bodocseq,0) + 1
	WHERE  routecode =in_route_code;
	
	SELECT get_number_type_base(in_route_code,2), get_number_type_base(in_route_code,1)
	INTO new_document_no,new_invoice_no;
		
	
	
	
	
	
	SELECT IFNULL(MAX(customeroperationscontrol.visitkey),0) INTO new_visit_key FROM customeroperationscontrol
	WHERE  customeroperationscontrol.routekey =in_routekey ;
	SET new_visit_key =new_visit_key + 1;
	
	
	INSERT INTO customeroperationscontrol (visitkey,routekey,customercode,salesmancode,routecode,visitstartdate,
	visitstarttime,visitenddate,visitendtime,totaltransactions,voidflag)
	SELECT new_visit_key,in_routekey,customercode,salesmancode ,routecode,transactiondate,transactiontime,
	DATE(CURRENT_DATE()),TIME(CURRENT_DATE()),1,voidflag FROM 
	invoiceheader_temp WHERE invoiceheader_temp.transactionkey = in_transaction_key;
	
	
	
	CALL sp_trasfer_transaction_invoiceadd_tempdata_invoice(in_transaction_key,in_routekey,new_visit_key,new_document_no,new_invoice_no,in_gcpayment_type,in_paymenttype,@new_transaction_key);
	SET lastinsert_id = @new_transaction_key;
	
	
	SET new_amount = 0;
	SELECT totalinvoiceamount,customercode INTO new_amount,in_customer_id FROM invoiceheader WHERE transactionkey = lastinsert_id;
	
	
	SELECT invoicepaymentterms INTO gc_paymenttype FROM customermaster WHERE customercode = in_customer_id;
	
	
	CALL sp_trasfer_transaction_invoiceadd_tempdata_item(lastinsert_id,in_routekey,new_visit_key,in_transaction_key);
	CALL sp_trasfer_transaction_invoiceadd_tempdata_promotion(lastinsert_id,in_routekey,new_visit_key,in_transaction_key);
	CALL sp_trasfer_transaction_invoiceadd_tempdata_cashdetail(lastinsert_id,in_routekey,new_visit_key,in_transaction_key);
	CALL sp_trasfer_transaction_invoiceadd_tempdata_signaturedetail(lastinsert_id,in_routekey,new_visit_key,in_transaction_key,new_document_no);
	CALL sp_trasfer_transaction_invoiceadd_tempdata_batchexpirydetail(lastinsert_id,in_routekey,new_visit_key,in_transaction_key);	
 	CALL sp_trasfer_transaction_invoiceadd_tempdata_delete(in_transaction_key,in_routekey,in_visitkey);	
	
	
	IF in_paymenttype = 0 THEN
	
		INSERT INTO customerinvoice(documentnumber,invoicenumber,transactiondate,transactiontime,
		customercode,routecode,salesmancode,totalinvoiceamount,totalsalesamount,totalreturnamount,
		totaldamagedamount,totalfreesampleamount,amountpaid,invoicebalance,paymenttype,transactiontype,
		voidflag,currencycode,totalexpiryamount,totalmanualfree,
		totalpromoamount,totaldiscountamount,totalbuybackfreeamount) 
		SELECT documentnumber,invoicenumber,transactiondate,invoiceheader.transactiontime,customercode,routecode,
		salesmancode,totalinvoiceamount,totalsalesamount,totalreturnamount,totaldamagedamount,
		totalfreesampleamount,IFNULL(amountpaid,0) AS amountpaid,invoicebalance,paymenttype,2,0,
		get_default_currencycode_routecode(routecode),totalexpiryamount,totalmanualfree,
		totalpromoamount,totaldiscountamount,totalbuybackfreeamount
		FROM invoiceheader WHERE invoiceheader.transactionkey  =lastinsert_id;
	
	ELSEIF gc_paymenttype = 2 THEN  
	
		INSERT INTO customerinvoice(documentnumber,invoicenumber,transactiondate,transactiontime,
		customercode,routecode,salesmancode,totalinvoiceamount,totalsalesamount,totalreturnamount,
		totaldamagedamount,totalfreesampleamount,invoicebalance,paymenttype,transactiontype,
		voidflag,pdcbalance,pdcindicator,currencycode,totalexpiryamount,totalmanualfree,
		totalpromoamount,totaldiscountamount,totalbuybackfreeamount)
		SELECT documentnumber,invoicenumber,transactiondate,invoiceheader.transactiontime,customercode,routecode,
		salesmancode,totalinvoiceamount,totalsalesamount,totalreturnamount,totaldamagedamount,
		totalfreesampleamount,invoicebalance,1,2,0,IFNULL(amountpaid,0),1,
		get_default_currencycode_routecode(routecode),totalexpiryamount,totalmanualfree,
		totalpromoamount,totaldiscountamount,totalbuybackfreeamount
		FROM invoiceheader WHERE invoiceheader.transactionkey  = lastinsert_id;
		
		
		
	ELSE 
		
		INSERT INTO customerinvoice(documentnumber,invoicenumber,transactiondate,transactiontime,
		customercode,routecode,salesmancode,totalinvoiceamount,totalsalesamount,totalreturnamount,
		totaldamagedamount,totalfreesampleamount,invoicebalance,paymenttype,transactiontype,
		voidflag,pdcbalance,pdcindicator,pdcdate,currencycode,totalexpiryamount,totalmanualfree,
		totalpromoamount,totaldiscountamount,totalbuybackfreeamount)
		SELECT documentnumber,invoicenumber,transactiondate,invoiceheader.transactiontime,customercode,routecode,
		salesmancode,totalinvoiceamount,totalsalesamount,totalreturnamount,totaldamagedamount,
		totalfreesampleamount,invoicebalance,1,2,0,IFNULL(amountpaid,0),1,DATE(cashcheckdetail.checkdate),
		get_default_currencycode_routecode(routecode),totalexpiryamount,totalmanualfree,
		totalpromoamount,totaldiscountamount,totalbuybackfreeamount
		FROM invoiceheader,cashcheckdetail WHERE invoiceheader.transactionkey  =lastinsert_id AND cashcheckdetail.visitkey=invoiceheader.visitkey 
		AND cashcheckdetail.routekey=invoiceheader.routekey;
		
	END IF;	
	
	SELECT getpdctocashstatus() INTO pdc_as_cash;
	
	IF in_customer_id != '' THEN
		
		IF gc_paymenttype = 2 OR gc_paymenttype = 3 THEN
			UPDATE customermaster SET balance = IFNULL(balance,0) + new_amount WHERE customercode = in_customer_id;
		ELSEIF gc_paymenttype = 4 AND pdc_as_cash = 1 THEN
			UPDATE customermaster SET balance = IFNULL(balance,0) + new_amount WHERE customercode = in_customer_id;
		END IF;	
	END IF;
	SELECT new_amount,in_customer_id;
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_trasfer_transaction_invoiceadd_tempdata_batchexpirydetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_trasfer_transaction_invoiceadd_tempdata_batchexpirydetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_trasfer_transaction_invoiceadd_tempdata_batchexpirydetail`(
in in_auto_transaction_key INT,
IN in_routekey INT,
IN in_visit_key INT,
IN in_transaction_key INT
)
BEGIN
	
	
	insert into batchexpirydetail 
	(routekey,batchdetailkey,batchnumber,itemcode,quantity,transactiontypecode,expirydate,visitkey)
	
	select in_routekey,batchdetailkey,batchnumber,itemcode,quantity,transactiontypecode,expirydate,in_visit_key
	from batchexpirydetail_temp where transactionkey =in_transaction_key;
	
	UPDATE batchmaster,
	(SELECT 
		(quantity - salesquantity - rentalquantity - freequantity + returnquantity + buybackquantity - promoquantity) AS quantity,
		batchnumber,itemcode
		FROM batchmaster_temp
		WHERE
		visitkey = in_transaction_key) AS a
	SET batchmaster.quantity = a.quantity
	where batchmaster.batchnumber = a.batchnumber
	and batchmaster.itemcode = a.itemcode;
	
	
	
	INSERT INTO batchmaster(quantity,batchdetailkey,batchnumber,expirydate,itemcode,damagequantity,routekey) 
	SELECT IFNULL((quantity - salesquantity - rentalquantity - freequantity + returnquantity + buybackquantity - promoquantity),0) AS quantity,
	batchdetailkey,batchnumber,expirydate,itemcode,
	(IFNULL(quantity,0)+IFNULL(damagequantity,0)+IFNULL(expiryquantity,0)) AS damagequantity,
	in_routekey
	FROM   batchmaster_temp
	WHERE  NOT EXISTS 
	(
		SELECT batchnumber FROM batchmaster WHERE batchmaster_temp.batchnumber =  batchmaster.batchnumber 
		AND batchmaster_temp.routekey = batchmaster.routekey
	)
	AND batchmaster_temp.visitkey = in_transaction_key;
	
	
	
	 DELETE FROM batchexpirydetail_temp WHERE transactionkey =in_transaction_key;
	 DELETE FROM batchmaster_temp WHERE visitkey = in_transaction_key AND routekey = in_routekey;
	
	
	   
	   
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_trasfer_transaction_invoiceadd_tempdata_cashdetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_trasfer_transaction_invoiceadd_tempdata_cashdetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_trasfer_transaction_invoiceadd_tempdata_cashdetail`(
in in_auto_transaction_key INT,
IN in_routekey INT,
IN in_visit_key INT,
IN in_transaction_key INT
)
BEGIN
declare in_amount decimal(19,2);
insert into cashcheckdetail
(routekey,visitkey,typecode,checknumber,amount,updateindicator,checkdate,bankcode,checkstatus, 
	branchcode,drawercode,chequestatusindicator,sapchequestatusindicator,currencycode,hhctransactionkey,transactiontype)
select in_routekey,in_visit_key,typecode,checknumber,amount,updateindicator,checkdate,bankcode,checkstatus, 
	branchcode,drawercode,chequestatusindicator,sapchequestatusindicator,get_default_currencycode(),
	in_auto_transaction_key,1 from cashcheckdetail_temp where 
	cashcheckdetail_temp.hhctransactionkey  =in_transaction_key;
	
	select amount into in_amount from cashcheckdetail where 
	cashcheckdetail.visitkey  =in_visit_key;
	
	if in_amount is not null then	
		UPDATE invoiceheader
		SET 
		invoicebalance= invoicebalance - in_amount
		WHERE invoiceheader.transactionkey =in_auto_transaction_key;
	end if;
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_trasfer_transaction_invoiceadd_tempdata_delete` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_trasfer_transaction_invoiceadd_tempdata_delete` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_trasfer_transaction_invoiceadd_tempdata_delete`(
IN in_transaction_key INT,
IN in_routekey INT,
IN in_visitkey INT
)
BEGIN
	delete from invoiceheader_temp where invoiceheader_temp.transactionkey = in_transaction_key;
	DELETE FROM invoicedetail_temp WHERE invoicedetail_temp.transactionkey = in_transaction_key;
	delete from invoicerxddetail_temp where invoicerxddetail_temp.transactionkey = in_transaction_key;
	delete from promotiondetail_temp where promotiondetail_temp.transactionkey = in_transaction_key;
	delete from cashcheckdetail_temp where cashcheckdetail_temp.hhctransactionkey = in_transaction_key;
	delete from sigcapturedata_temp where sigcapturedata_temp.transactionkey = in_transaction_key;	
	DELETE FROM batchmaster_temp WHERE routekey = in_routekey and visitkey = in_visitkey;
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_trasfer_transaction_invoiceadd_tempdata_invoice` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_trasfer_transaction_invoiceadd_tempdata_invoice` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_trasfer_transaction_invoiceadd_tempdata_invoice`(
IN in_transaction_key INT,
IN in_routekey INT,
IN new_visit_key INT,
IN new_document_no DECIMAL(28),
IN new_invoice_no DECIMAL(28),
IN in_gcpayment_type INT,
IN in_paymenttype INT,
OUT new_transaction_key INT
)
BEGIN
DECLARE in_payment_status INT;
 SET in_payment_status = in_paymenttype;
 
 
 
INSERT INTO invoiceheader (routekey,visitkey,documentnumber,invoicenumber,transactiondate,transactiontime, 
	customercode,routecode,salesmancode,totalinvoiceamount,	totalsalesamount, totalreturnamount,totaldamagedamount, 
	totalfreesampleamount, 	immediatepaid,amountpaid,invoicebalance, paymenttype,paymentstatus, hhcinvoicenumber, 
	totalpromoamount,gcpaymenttype,hhcdocumentnumber,inventorykey,totaltaxesamount,itemlinetaxamount,totaldiscountamount,voidreasoncode,totalexpiryamount, 
	currencycode,totalmanualfree,totallimitedfree,totalrebaterent,totalfixedrent,actualtransactiondate,boentry, 
	hhctransactionkey,`data`,comments,totaldiscdistributionamount,totalreplacementamount,comments2,record_flag, 
	lineitemdiscount,voidflag,totalbuybackfreeamount)
SELECT  in_routekey, new_visit_key,new_document_no,new_invoice_no,transactiondate,transactiontime, 
	customercode, routecode,salesmancode,totalinvoiceamount,totalsalesamount,totalreturnamount, 
	totaldamagedamount, totalfreesampleamount, immediatepaid,amountpaid,invoicebalance,
	in_paymenttype,	in_payment_status,hhcinvoicenumber, totalpromoamount,in_gcpayment_type, 
	hhcdocumentnumber,inventorykey,	totaltaxesamount,itemlinetaxamount,totaldiscountamount,	voidreasoncode, 
	totalexpiryamount,get_default_currencycode(),	totalmanualfree,totallimitedfree,totalrebaterent,totalfixedrent, 
	actualtransactiondate, boentry,	hhctransactionkey, `data`,comments,totaldiscdistributionamount, 
	totalreplacementamount,	comments2, record_flag,	lineitemdiscount,voidflag,totalbuybackfreeamount FROM invoiceheader_temp WHERE 
	transactionkey =in_transaction_key;
	
SELECT LAST_INSERT_ID() INTO new_transaction_key;
UPDATE invoiceheader 
	SET 
	totalinvoiceamount=(IFNULL(totalsalesamount,0)-IFNULL(totalreturnamount,0)-IFNULL(totalpromoamount,0)-IFNULL(totaldamagedamount,0)),
	invoicebalance=(IFNULL(totalsalesamount,0)-IFNULL(totalreturnamount,0)-IFNULL(totalpromoamount,0)-IFNULL(totaldamagedamount,0)) 
		
	WHERE 
	transactionkey =new_transaction_key;
	
	SELECT invoicebalance,customercode INTO @invbal,@ccode FROM invoiceheader_temp WHERE transactionkey =new_transaction_key;
	
	UPDATE customermaster SET balance = balance + @invbal
	WHERE customercode = @ccode;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_trasfer_transaction_invoiceadd_tempdata_item` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_trasfer_transaction_invoiceadd_tempdata_item` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_trasfer_transaction_invoiceadd_tempdata_item`(
IN in_auto_transaction_key INT,
IN in_routekey INT,
IN in_visit_key INT,
IN in_transaction_key INT
)
BEGIN
DECLARE in_line_item_discount DECIMAL(19,4);
DECLARE in_return_line_item_discount DECIMAL(19,4);
DECLARE in_amount_paid DECIMAL(19,4);
	INSERT INTO invoicedetail
	(routekey,visitkey,transactionkey,itemcode,salesqty, returnqty, damagedqty, freesampleqty, salesprice,returnprice, 
	stdsalesprice, stdreturnprice, promoqty, salesitemexcisetax, salesitemgsttax, returnitemexcisetax, returnitemgsttax, 
	damageditemexcisetax, damageditemgsttax, fgitemexcisetax,fgitemgsttax, promoitemexcisetax,promoitemgsttax, 
	coopid, batchdetailkey, salescaseprice,returncaseprice, stdsalescaseprice, stdreturncaseprice,goodreturnprice, 
	goodreturncaseprice, stdgoodreturncaseprice,stdgoodreturnprice, expiryqty,currencycode,returnfreeqty, manualfreeqty, 
	limitedfreeqty, rebaterentqty, fixedrentqty,pricechgindicator,discountamount,discountpercentage,promoamount, 
	replacementqty, replacementprice, replacementcaseprice,promovalue,mdat,sales_amount)
	
	SELECT in_routekey,in_visit_key,in_auto_transaction_key,itemcode,salesqty, returnqty, damagedqty, freesampleqty, salesprice,returnprice, 
	stdsalesprice, stdreturnprice, promoqty, salesitemexcisetax, salesitemgsttax, returnitemexcisetax, returnitemgsttax, 
	damageditemexcisetax, damageditemgsttax, fgitemexcisetax,fgitemgsttax, promoitemexcisetax,promoitemgsttax, 
	coopid, batchdetailkey, salescaseprice,returncaseprice, stdsalescaseprice, stdreturncaseprice,goodreturnprice, 
	goodreturncaseprice, stdgoodreturncaseprice,stdgoodreturnprice, expiryqty,get_default_currencycode(),returnfreeqty, manualfreeqty, 
	limitedfreeqty, rebaterentqty, fixedrentqty,pricechgindicator,discountamount,discountpercentage,promoamount, 
	replacementqty, replacementprice, replacementcaseprice,promovalue,mdat,sales_amount
	FROM invoicedetail_temp WHERE 
	invoicedetail_temp.transactionkey = in_transaction_key;
	
	SET in_amount_paid = 0;	
	SET in_line_item_discount = 0;
	SET in_return_line_item_discount = 0;
	SELECT IFNULL(SUM(invoicedetail.promoamount),0) INTO in_line_item_discount FROM invoicedetail WHERE 
	invoicedetail.transactionkey =in_auto_transaction_key;
	
	SELECT IFNULL(SUM(invoicedetail.returnpromoamount),0) INTO in_return_line_item_discount FROM invoicedetail WHERE 
	invoicedetail.transactionkey =in_auto_transaction_key;
	
	
	
	SELECT IFNULL(amount,0) INTO in_amount_paid FROM cashcheckdetail_temp WHERE  typecode =0 
	AND hhctransactionkey = in_transaction_key;
	
	UPDATE invoiceheader SET  invoiceheader.lineitemdiscount = in_line_item_discount,
	invoiceheader.returnlineitemdiscount = in_return_line_item_discount,
	hhctransactionkey = in_auto_transaction_key,
	immediatepaid = in_amount_paid
	WHERE invoiceheader.transactionkey =in_auto_transaction_key;
	
	
	INSERT INTO invoicerxddetail (
	routekey,visitkey,transactionkey,itemtransactiontype,itemcode,itemtranstypeseq,reasoncode,quantity, 
	catchweightqty, weighted,instructioncode,currencycode)
	SELECT  
	in_routekey,in_visit_key,in_auto_transaction_key,itemtransactiontype,itemcode,itemtranstypeseq,reasoncode,quantity, 
	catchweightqty, weighted,instructioncode,get_default_currencycode()	
	FROM invoicerxddetail_temp WHERE 
	invoicerxddetail_temp.transactionkey = in_transaction_key;
	
	
	INSERT INTO inventorysummarydetail
	(inventorykey,routekey,itemcode,stdsalesprice,stdsalescaseprice,stdreturnprice,stdreturncaseprice,mdat,currencycode)
	SELECT id.routekey,id.routekey,id.itemcode,i.defaultsalesprice,i.caseprice,i.defaultreturnprice,
		i.returncaseprice,CURRENT_DATE(),get_default_currencycode_routekey(in_routekey)
	FROM invoicedetail AS id
	JOIN itemmaster AS i ON i.actualitemcode = id.itemcode
	WHERE 
	NOT EXISTS (
	SELECT * FROM inventorysummarydetail
	WHERE inventorysummarydetail.routekey = id.routekey
	AND inventorysummarydetail.itemcode = id.itemcode
	) AND id.visitkey = in_visit_key AND id.routekey = in_routekey;
	
	
	UPDATE inventorysummarydetail,invoicedetail
		SET inventorysummarydetail.saleqty =  IFNULL(inventorysummarydetail.saleqty,0) +  IFNULL(invoicedetail.salesqty,0),
		    inventorysummarydetail.returnqty =  IFNULL(inventorysummarydetail.returnqty,0) +  IFNULL(invoicedetail.returnqty,0),
		    inventorysummarydetail.damageqty =  IFNULL(inventorysummarydetail.damageqty,0) +  IFNULL(invoicedetail.damagedqty,0),
		    inventorysummarydetail.freesampleqty =  IFNULL(inventorysummarydetail.freesampleqty,0) +  IFNULL(invoicedetail.freesampleqty,0),
		    inventorysummarydetail.expiryqty =  IFNULL(inventorysummarydetail.expiryqty,0) +  IFNULL(invoicedetail.expiryqty,0),
		    inventorysummarydetail.returnfreeqty =  IFNULL(inventorysummarydetail.returnfreeqty,0) +  IFNULL(invoicedetail.returnfreeqty,0),
		    inventorysummarydetail.rentqty =  IFNULL(inventorysummarydetail.rentqty,0) +  IFNULL(invoicedetail.fixedrentqty,0)
	WHERE inventorysummarydetail.itemcode = invoicedetail.itemcode
	AND inventorysummarydetail.routekey = invoicedetail.routekey
	AND invoicedetail.routekey = in_routekey
	AND invoicedetail.visitkey = in_visit_key;
	
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_trasfer_transaction_invoiceadd_tempdata_promotion` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_trasfer_transaction_invoiceadd_tempdata_promotion` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_trasfer_transaction_invoiceadd_tempdata_promotion`(
IN in_auto_transaction_key INT,
IN in_routekey INT,
IN in_visit_key INT,
IN in_transaction_key INT
)
BEGIN
update promotiondetail_temp set itemcode = 0
where promotiondetail_temp.transactionkey = in_transaction_key
	AND promotiontypecode in(5,6);
	
insert into promotiondetail (routekey,visitkey,transactionkey,itemtransactiontype,itemcode,promotiontypecode,
	promotionamount,promotionquantity,catchweightqty,weighted,promotionplannumber,assignmentkey,exclusionoption, 
	promochgindicator,oldpromotionamount,performindicator,performcriteriakey,promotioncaseprice, 
	currencycode,salesamount,rangelow, repeatingrange)
select in_routekey,in_visit_key,in_auto_transaction_key,itemtransactiontype,itemcode,promotiontypecode,	promotionamount, 
	promotionquantity,catchweightqty,weighted,promotionplannumber,assignmentkey,exclusionoption, 
	promochgindicator,oldpromotionamount,performindicator,performcriteriakey,promotioncaseprice, 
	get_default_currencycode(),salesamount,rangelow, repeatingrange
from promotiondetail_temp
where promotiondetail_temp.transactionkey = in_transaction_key;
UPDATE promotiondetail AS p JOIN invoicedetail ON invoicedetail.itemcode = p.itemcode
 AND invoicedetail.visitkey=p.visitkey AND invoicedetail.routekey=p.routekey 
 SET p.promotionquantity=invoicedetail.freesampleqty WHERE p.promotiontypecode=7 
 and p.visitkey = in_visit_key and p.routekey = in_routekey;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_trasfer_transaction_invoiceadd_tempdata_signaturedetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_trasfer_transaction_invoiceadd_tempdata_signaturedetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_trasfer_transaction_invoiceadd_tempdata_signaturedetail`(
in in_auto_transaction_key INT,
IN in_routekey INT,
IN in_visit_key INT,
IN in_transaction_key INT,
in new_document_no  varchar(255)
)
BEGIN
INSERT INTO sigcapturedata 
	(routekey, visitkey, transactionkey, customercode, transactiondate,  balancedueamount,signaturedata,documentnumber,transaction_type)
	
select in_routekey,in_visit_key,in_auto_transaction_key,customercode,transactiondate,balancedueamount,signaturedata,new_document_no,transaction_type
from sigcapturedata_temp where 
sigcapturedata_temp.transactionkey =in_transaction_key and transaction_type ='1';
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_upcstatus_itempackage` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_upcstatus_itempackage` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_upcstatus_itempackage`(
			IN var_itempackagecode BIGINT
    )
BEGIN
	
	SELECT COUNT(*) AS cnt FROM (SELECT unitspercase,GROUP_CONCAT(actualitemcode) AS actualitemcode
									FROM itemmaster WHERE packagecode = var_itempackagecode 
									GROUP BY unitspercase
								) AS upc;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_update_account_customer_customeritemmust` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_update_account_customer_customeritemmust` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_update_account_customer_customeritemmust`(
IN var_enforce BIGINT,
IN var_mslid text
)
BEGIN
SET @q4 = CONCAT("UPDATE customermaster SET  enforcemsl=",var_enforce," WHERE customercode IN (",var_mslid,")");
PREPARE s4 FROM @q4;
EXECUTE s4;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_update_customer_GPS` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_update_customer_GPS` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_update_customer_GPS`(
    )
BEGIN
	
DROP TABLE IF EXISTS tmp_gps;
  CREATE TEMPORARY TABLE IF NOT EXISTS tmp_gps AS 
  SELECT customercode, MAX(visitstartdate) visitdate FROM customeroperationscontrol WHERE latitude > 0 GROUP BY customercode;
DROP TABLE IF EXISTS tmp_gps_latest;
  CREATE TEMPORARY TABLE IF NOT EXISTS tmp_gps_latest AS 
SELECT DISTINCT coc.customercode, coc.visitstartdate, coc.latitude, coc.longitude
FROM customeroperationscontrol coc
	INNER JOIN tmp_gps gps ON gps.customercode = coc.customercode AND gps.visitdate = coc.visitstartdate AND coc.latitude > 0;
UPDATE customermaster cm
	INNER JOIN tmp_gps_latest gps ON gps.customercode = cm.customercode
SET cm.fixedlatitude= gps.latitude, cm.fixedlongitude= gps.longitude, cm.mdat= NOW();
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_update_customer_promokey` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_update_customer_promokey` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_update_customer_promokey`(IN param_custcode BIGint, IN param_promokey INT)
BEGIN
	declare var_plannumber_combo int default 0;
	DECLARE var_plannumber_inv INT DEFAULT 0;
	select plannumber into var_plannumber_combo from promokeydetail where promotionkey = param_promokey and promotiontypecode = 8 limit 1;
	if var_plannumber_combo >0 then
		update customermaster set combopromoyn = 1, combopromoplan = var_plannumber_combo where customercode = param_custcode;
		insert into invpromoupdatelog values(param_custcode,param_promokey, var_plannumber_combo,'COMBO', now());
	ELSE
		UPDATE customermaster SET combopromoyn = 0, combopromoplan = NULL WHERE customercode = param_custcode;
	end if;
	
	SELECT plannumber INTO var_plannumber_inv FROM promokeydetail WHERE promotionkey = param_promokey and qualificationgroup = 1 AND assignmentgroup = 1 limit 1;
	IF var_plannumber_inv >0 THEN
		UPDATE customermaster SET invpromoyn = 1, invpromoplan = var_plannumber_inv WHERE customercode = param_custcode;
		INSERT INTO invpromoupdatelog values(param_custcode,param_promokey, var_plannumber_combo,'1-1', NOW());
	ELSE
		UPDATE customermaster SET invpromoyn = 0, invpromoplan = NULL WHERE customercode = param_custcode;
	END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_update_invoice_posted_status` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_update_invoice_posted_status` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_update_invoice_posted_status`(
IN var_invoicenumber BIGINT
)
BEGIN
UPDATE InvoiceHeader SET posted=1 WHERE invoicenumber=var_invoicenumber;
SELECT ROW_COUNT() AS output;
END */$$
DELIMITER ;

