DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_companyid_device`(
	IN var_deviceid VARCHAR(255)
    )
BEGIN
	
	  
	
	SELECT count(*) into @count FROM tbl_device WHERE device_id = var_deviceid;
	if @count>0 then
		SELECT company_id FROM tbl_device WHERE device_id = var_deviceid;
	else
		INSERT INTO tbl_device values('',1,var_deviceid,'Auto Registered');
		SELECT company_id FROM tbl_device WHERE device_id = var_deviceid;
	end if;
	
	
    END */$$
