/* Procedure structure for procedure `sp_ws_from_tablet_endday` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_from_tablet_endday` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_from_tablet_endday`(
        IN var_routekey BIGINT(20),
        IN var_routeenddate DATE,
        IN var_routeendtime VARCHAR(10),
        IN var_routeendodometer DECIMAL(18,0),    
	IN var_totaldocuments INT(4),
	IN var_totalcash DOUBLE(8,4),
	IN var_totalchecks DOUBLE(8,0),	
	IN var_totalorderamount DOUBLE(8,0),
	IN var_totalinvoiceamount DOUBLE(8,4),
	IN var_totalchargesales DOUBLE(8,4),
	IN var_totalcashsales DOUBLE(8,4),
	IN var_totalacctsreceivable DOUBLE(8,0),
	IN var_totalexpenses DOUBLE(8,0),
	IN var_inventoryvariance DOUBLE(8,4),
	IN var_cashvariance DOUBLE(8,0)
    )
BEGIN
	UPDATE startendday SET 	
		routeenddate = var_routeenddate,
		routeendodometer = var_routeendodometer,
		routeendtime= var_routeendtime,
		routeclosed = '1',
		totaldocuments = var_totaldocuments,
		totalcash = var_totalcash,
		totalchecks = var_totalchecks,
		totalcheckrequests = '0',
		totalorderamount = var_totalorderamount,
		totalinvoiceamount = var_totalinvoiceamount,
		totalchargesales = var_totalchargesales,
		totalcashsales = var_totalcashsales,
		totalacctsreceivable = var_totalacctsreceivable,
		totalexpenses = var_totalexpenses,
		inventoryvariance = var_inventoryvariance,
		cashvariance = var_cashvariance,
		totalfullservicesales = '0',
		totalfullservicecash = '0',
		
		exportedflag = '0',
		routejourneyid = '0',
		modifieddate=CURDATE(),
		modifiedtime=CURTIME(),
		DATA = '0'				
		WHERE routekey = var_routekey; --  AND triptype = 0;
				
	UPDATE routemaster SET vehicleodometer = var_routeendodometer WHERE routecode = (SELECT routecode FROM startendday WHERE routekey = var_routekey AND triptype = 0 );	
				
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getareamaster` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getareamaster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getareamaster`(
	IN rwcnt INT,			
	IN srchvalue VARCHAR(500), 	
	IN order_by VARCHAR(500),	
	IN order_type VARCHAR(10),	
	IN lmt_strt INT,		
	IN lmt_end INT 			
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	IF order_by = '' THEN
		SET order_by = 'AreaCode';
	END IF;
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
    IF rwcnt = 1 THEN
	SET @dyn_sql = CONCAT("SELECT COUNT(area.areacode) AS counter FROM areamaster AS area
	LEFT JOIN `areamanager` AS `manager` ON manager.areamanagercode = area.areamanagercode
	LEFT JOIN `depotmaster` AS `depot` ON depot.depotcode = area.depotcode
	WHERE (areaname LIKE('%",srchvalue,"%') OR areamanagername LIKE('%",srchvalue,"%')  OR depotname LIKE('%",srchvalue,"%'))");
    ELSE
	SET @dyn_sql = CONCAT("SELECT `area`.`areaCode`, `area`.`areaname`, `manager`.`areamanagername`, `depot`.`depotname`,
	`area`.`activestatus` FROM `areamaster` AS `area`
	LEFT JOIN `areamanager` AS `manager` ON manager.areamanagercode = area.areamanagercode
	LEFT JOIN `depotmaster` AS `depot` ON depot.depotcode = area.depotcode
	WHERE (areaname LIKE('%",srchvalue,"%') OR areamanagername LIKE('%",srchvalue,"%')  OR depotname LIKE('%",srchvalue,"%'))
	ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    END IF;
	PREPARE s1 FROM @dyn_sql;
	
	EXECUTE s1;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getcompany` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getcompany` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getcompany`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500),
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_where TEXT 		)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	IF order_by = '' THEN
		SET order_by = 'CmpyCode';
	END IF;
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
    IF rwcnt = 1 THEN
	SET @dyn_sql = CONCAT("SELECT COUNT(cmpny.cmpycode) AS counter FROM company AS cmpny
	LEFT JOIN `nationalsalesmanager` AS `salesmngr` ON salesmngr.nationalsalesmanagercode = cmpny.nationalsalesmanagercode
	WHERE (countryname LIKE('%",srchvalue,"%') OR arbcompanyname LIKE('%",srchvalue,"%') OR name LIKE('%",srchvalue,"%')) ",table_where);
    ELSE
	SET @dyn_sql = CONCAT("SELECT `cmpny`.*, `salesmngr`.`nationalsalesmanagername`
	FROM `company` AS `cmpny` LEFT JOIN `nationalsalesmanager` AS `salesmngr` ON salesmngr.nationalsalesmanagercode = cmpny.nationalsalesmanagercode
	WHERE (countryname LIKE('%",srchvalue,"%') OR arbcompanyname LIKE('%",srchvalue,"%') OR name LIKE('%",srchvalue,"%')) ",table_where, "
	ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    END IF;
	
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getcountrymaster` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getcountrymaster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getcountrymaster`(
	in rwcnt int,	IN srchvalue VARCHAR(500), in order_by varchar(500),IN order_type VARCHAR(10),	IN lmt_strt int,  IN lmt_end INT, IN table_fields TEXT, IN table_where text 		)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	IF order_by = '' THEN
		SET order_by = 'CountryCode';
	END IF;
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	if table_fields = '' then
		set table_fields = 'cnt.*';
	end if;
    if rwcnt = 1 THEN
	SET @dyn_sql = concat("SELECT COUNT(cnt.countrycode) AS counter FROM country AS cnt
	LEFT JOIN `currencymaster` AS `cur` ON cur.CurrencyCode = cnt.CurrencyCode
	WHERE (CountryName LIKE('%",srchvalue,"%') OR CurrencyName LIKE('%",srchvalue,"%')) ",table_where);
    ELSE
	SET @dyn_sql = concat("SELECT ", table_fields ," ,`cur`.`currencyname`
	FROM `country` AS `cnt` LEFT JOIN `currencymaster` AS `cur` ON cur.currencycode = cnt.currencycode
	WHERE (countryname LIKE('%",srchvalue,"%') OR currencyname LIKE('%",srchvalue,"%')) ",table_where, "
	ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    END IF;
    	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getcustomercategory` */

