    IF rwcat = 1 THEN
	SET @dyn_sql = CONCAT("SELECT COUNT(cat.categoryid) AS counter FROM categorymaster AS cat
	WHERE (categoryname LIKE('%",srchvalue,"%') OR arbcategoryname LIKE('%",srchvalue,"%'))");
    ELSE
	SET @dyn_sql = CONCAT("SELECT cat.categoryid,`cat`.`categoryname`, `cat`.`arbcategoryname`
	FROM `categorymaster` AS `cat`
	WHERE (categoryname LIKE('%",srchvalue,"%') OR arbcategoryname LIKE('%",srchvalue,"%'))
