/* Procedure structure for procedure `sp_ws_getcustomer_balance` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getcustomer_balance` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getcustomer_balance`(
	var_routeid  VARCHAR(15),
	var_customercode  VARCHAR(15)
    )
BEGIN
	
	SET @dyn_sql = CONCAT("
		SELECT ci.transactionkey,ci.transactiontype,ci.documentnumber,ci.invoicenumber,ci.transactiondate,ci.transactiontime,ci.customercode,", var_routeid, " routecode,ci.salesmancode,
			ci.totalinvoiceamount,ci.totalsalesamount,ci.totalreturnamount,ci.totaldamagedamount,ci.totalfreesampleamount,ci.immediatepaid,ci.amountpaid,ci.dnamountpaid,ci.cnamountpaid,
			ci.invoicebalance,ci.paymenttype,ci.voidflag,ci.paymentstatus,ci.hhcinvoicenumber, sm.alternatesalesmancode remarks1,'' remarks2,ci.routestartdate,ci.erpreferencenumber,ci.mdat,ci.totalpromoamount,
			ci.gcpaymenttype,ci.totaltaxesamount,ci.itemlinetaxamount,ci.totaldiscountamount,ci.pdcindicator,ci.chequecollection,ci.totalexpiryamount,ci.currencycode,ci.pdcbalance,
			ci.totalmanualfree,ci.totallimitedfree,ci.totalrebaterent,ci.totalfixedrent,ci.data,ci.totaldiscdistributionamount,ci.totalreplacementamount,ci.pdcdate,ci.totalbuybackfreeamount, 
			ci.duedate
		FROM customerinvoice ci 
			INNER JOIN salesman sm ON sm.salesmancode = ci.salesmancode
		WHERE ci.transactiontype = 2 AND ci.voidflag = 0 AND ci.duedate IS NOT NULL AND ci.customercode=",var_customercode);        
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_delivery` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_delivery` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_delivery`(
	var_cust VARCHAR(15),
	var_orderdate VARCHAR(15),
	var_orderno VARCHAR(15),
	var_lpono  VARCHAR(15),
	var_routeid  VARCHAR(15)
    )
BEGIN
	
	
	SET @tablename = CONCAT("temp_delivery_",var_routeid);
	SET @tempdel = CONCAT("DROP TABLE IF EXISTS ",@tablename);
	PREPARE qry1 FROM @tempdel ;
	EXECUTE qry1;
	
	SET @temppromotable = '';
	IF var_cust <> '' THEN
		SET @temppromotable = CONCAT("CREATE TABLE IF NOT EXISTS ", @tablename, " AS 
		SELECT dh.orderno FROM deliveryheader dh INNER JOIN customermaster cm ON cm.customercode = dh.customercode 
		WHERE UPPER(cm.alternatecode) LIKE '%", UPPER(var_cust) ,"%' ORDER BY dh.orderno LIMIT 10");
		
	ELSEIF var_orderno <> '' THEN
		SET @temppromotable = CONCAT("CREATE TABLE IF NOT EXISTS ", @tablename, " AS 
		SELECT DISTINCT orderno FROM deliveryheader WHERE orderno LIKE '%", var_orderno ,"%' ORDER BY orderno LIMIT 10");
	
	ELSEIF var_lpono <> '' THEN
		SET @temppromotable = CONCAT("CREATE TABLE IF NOT EXISTS ", @tablename, " AS 
		SELECT DISTINCT orderno FROM deliveryheader WHERE UPPER(loadsheetnumber) LIKE '%", UPPER(var_lpono) ,"%' ORDER BY orderno LIMIT 10");
	END IF;	
	PREPARE qry2 FROM @temppromotable;
	EXECUTE qry2;
	
	
	SET @dyn_sql1 = CONCAT("SELECT dh.deliveryno,dh.orderno,dh.customercode,dh.deliveryroute,dh.deliverydate,
			dh.drivercode,dh.loadsheetnumber, cm.alternatecode reference,dh.totalamount
		FROM deliveryheader dh INNER JOIN customermaster cm on cm.customercode = dh.customercode
		WHERE orderno IN (SELECT orderno FROM ", @tablename ,")");
	PREPARE s1 FROM @dyn_sql1;
	EXECUTE s1;	
		
        
        
	SET @dyn_sql2 = CONCAT("SELECT dd.*
		FROM deliveryheader dh 
			INNER JOIN deliverydetail dd ON dd.deliveryno = dh.deliveryno AND dh.orderno IN (SELECT orderno FROM ", @tablename ,")");
	PREPARE s2 FROM @dyn_sql2;
	EXECUTE s2;
	
	SET @tempdel = CONCAT("DROP TABLE IF EXISTS ",@tablename);
	PREPARE qry1 FROM @tempdel ;
	EXECUTE qry1;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_ardetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_ardetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_ardetail`(
					IN var_routekey DECIMAL(28,0),
					IN var_visitkey DECIMAL(28,0),
					IN var_transactionkey DECIMAL(28,0),
					IN var_invoicenumber DECIMAL(18,0),
					IN var_invoicedate DATETIME,
					IN var_totalinvoiceamount DECIMAL(19,4),
					IN var_onacctreasoncode INT(11),
					IN var_amountpaid DECIMAL(19,4),
					IN var_invoicebalance DECIMAL(19,4),
					IN var_arcollectiontype INT(11),
					IN var_chequestatusindicator DECIMAL(18,0),
					IN var_sapchequestatusindicator Varchar(50),
					IN var_currencycode DECIMAL(18,0),
					IN var_pdcbalance DECIMAL(19,4),
					IN var_alternateinvoicenumber VARCHAR(30),
					IN var_salesmancode BIGINT(18),
					IN var_deductionamount DECIMAL(19,4)
				)
BEGIN
DECLARE cnt INT DEFAULT 0;
SELECT COUNT(*) INTO cnt FROM ardetail WHERE `routekey` = var_routekey AND `visitkey` =var_visitkey AND `invoicenumber` =var_invoicenumber;
	IF cnt = 0 THEN	
		
		INSERT INTO ardetail SET 	
			routekey = var_routekey,
			visitkey = var_visitkey,
			transactionkey = var_transactionkey,
			invoicenumber = var_invoicenumber,
			salesmancode=var_salesmancode,
			invoicedate = var_invoicedate,
			totalinvoiceamount = var_totalinvoiceamount,
			onacctreasoncode = var_onacctreasoncode,
			amountpaid = var_amountpaid,
			invoicebalance = var_invoicebalance,
			arcollectiontype = var_arcollectiontype,
			chequestatusindicator = var_chequestatusindicator,
			referenceno = var_sapchequestatusindicator,
			currencycode = get_default_currencycode_routekey(var_routekey),
			pdcbalance = var_pdcbalance,
			alternateinvoicenumber = var_alternateinvoicenumber,
			receivedtime = CURTIME(),
			deductionamount = var_deductionamount;								
			
		UPDATE customerinvoice SET amountpaid = amountpaid + var_amountpaid, invoicebalance = invoicebalance - var_amountpaid WHERE `invoicenumber` = var_invoicenumber;
		
	END IF;								
	
 				
	SELECT var_transactionkey AS lastid;	
	
    END */$$
DELIMITER ;

