/* Procedure structure for procedure `sp_ws_getdata_from_batchdetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_batchdetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_batchdetail`(
					IN var_routekey BIGINT(28),
					IN var_batchdetailkey DECIMAL(18,0),
					IN var_batchnumber VARCHAR(20),
					IN var_itemcode BIGINT(18),
					IN var_quantity DECIMAL(18,0),
					IN var_transactiontypecode INT(11),
					IN var_expirydate DATETIME,
					IN var_visitkey BIGINT(28)
				)
BEGIN
	DECLARE flag INT DEFAULT 0;
	DECLARE cnt INT DEFAULT 0;
	
	SELECT STATUS INTO flag FROM controlpanel WHERE flagid = 1;
	
	IF flag = 1 THEN
	
		SELECT COUNT(*) INTO cnt FROM batchexpirydetail WHERE routekey = var_routekey AND batchnumber = var_batchnumber AND itemcode = var_itemcode AND visitkey=var_visitkey AND transactiontypecode = var_transactiontypecode AND batchdetailkey = var_batchdetailkey;
		
		IF cnt = 0 THEN
		
			INSERT INTO batchexpirydetail SET 
			routekey = var_routekey,
			batchdetailkey = var_batchdetailkey,
			batchnumber = var_batchnumber,
			itemcode = var_itemcode, 
			quantity = var_quantity,
			transactiontypecode = var_transactiontypecode,
			expirydate = var_expirydate,visitkey=var_visitkey;
			
		ELSE		
			UPDATE batchexpirydetail SET
			batchdetailkey = var_batchdetailkey,
			quantity = var_quantity,
			expirydate = var_expirydate 
			WHERE routekey = var_routekey AND batchnumber = var_batchnumber AND itemcode = var_itemcode AND visitkey=var_visitkey AND transactiontypecode = var_transactiontypecode AND batchdetailkey = var_batchdetailkey; 				
		
		END IF;	
	       			
	END IF;
	
	SELECT var_routekey AS lastid; 
	
    END */$$
DELIMITER ;

