	IN var_amount DECIMAL(19,4),
	IN var_updateindicator INT(11),
	IN var_checkdate DATETIME,
	IN var_bankcode BIGINT(20),
	IN var_checkstatus INT(11),
	IN var_branchcode DECIMAL(18,0),
	IN var_drawercode DECIMAL(18,0),
	IN var_chequestatusindicator DECIMAL(18,0),
