				currencycode = get_default_currencycode_routekey(var_routekey),
				hhctransactionkey = var_hhctransactionkey,
				paymenttype = var_paymenttype,
				transactiontype = var_transactiontype,
				checktype = var_checktype;
		
 	ELSE
 	
		UPDATE cashcheckdetail SET routekey = var_routekey,
			visitkey = var_visitkey,
			typecode = var_typecode,
			checknumber = var_checknumber,
			amount = var_amount,
			updateindicator = var_updateindicator,
			checkdate = var_checkdate,
			bankcode = var_bankcode,
			checkstatus = var_checkstatus,
			branchcode = var_branchcode,
			drawercode = var_drawercode,
			chequestatusindicator = var_chequestatusindicator,
			sapchequestatusindicator = var_sapchequestatusindicator,
			currencycode = get_default_currencycode_routekey(var_routekey),
			hhctransactionkey = var_hhctransactionkey,
			paymenttype = var_paymenttype,
			transactiontype = var_transactiontype,
			checktype = var_checktype
			WHERE routekey = var_routekey AND visitkey =var_visitkey AND hhctransactionkey =var_hhctransactionkey;
 	END IF;
 	
	SELECT var_routekey AS lastid;
	
    END */$$
DELIMITER ;

