/* Procedure structure for procedure `sp_ws_getdata_from_customervisitlog` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_customervisitlog` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_customervisitlog`(
    IN var_logkey INT(20),
    IN var_routekey INT(20),    
    IN var_routecode INT(20),
    IN var_salesmancode INT(20),
    IN var_customercode INT(20),
    IN var_logstartdate DATE,
    IN var_logstarttime TIME,
    IN var_logenddate DATE,
    IN var_logendtime TIME,
    IN cft INT,
    IN var_autocheckout TINYINT
)
BEGIN
    
    DECLARE cnt INT DEFAULT 0;
    
    SELECT IFNULL(COUNT(*), 0) INTO cnt 
    FROM customervisitlog 
    WHERE routekey = var_routekey 
      AND logkey = var_logkey;
        
    IF cnt = 0 THEN
	
        INSERT INTO customervisitlog SET 
            logkey = var_logkey,
            routekey = var_routekey,
            customercode = var_customercode,
            routecode = var_routecode,
            salesmancode = var_salesmancode,
            logstartdate = var_logstartdate,
            logstarttime = var_logstarttime,
            logenddate = var_logenddate,
            logendtime = var_logendtime,
            cft = cft,
            autocheckout = var_autocheckout,
            mdate = CURRENT_DATE();
    ELSE
        UPDATE customervisitlog SET
            customercode = var_customercode,
            routecode = var_routecode,
            salesmancode = var_salesmancode,
            logstartdate = var_logstartdate,
            logstarttime = var_logstarttime,
            logenddate = var_logenddate,
            logendtime = var_logendtime,
            cft = cft,
            autocheckout = var_autocheckout,
            mdate = CURRENT_DATE()
        WHERE routekey = var_routekey 
          AND logkey = var_logkey;
    END IF;
    SELECT var_routekey AS lastid;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_deviceroutetrack` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_deviceroutetrack` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_deviceroutetrack`(
	IN var_latitude DECIMAL(18,6),
	IN var_longitude DECIMAL(18,6),
	IN var_deviceid VARCHAR(50),
	IN var_timestamp DATETIME
	)
BEGIN
	
	SELECT COALESCE(MAX(routekey),0) routekey INTO @routekey
	FROM startendday
	WHERE routeclosed = 0 AND dataconrefnumber = var_deviceid;
	
	IF @routekey > 0 THEN
		SELECT routecode, salesmancode INTO @routecode, @salesmancode
		FROM startendday
		WHERE routekey = @routekey;
		
		INSERT INTO routetrack SET 	
			routekey = @routekey,
			routecode = @routecode,
			salesmancode = @salesmancode,
			entrydate = CURDATE(),
			entrytime = CURTIME(),
			deviceid = var_deviceid,
			latitude = var_latitude,
			longitude = var_longitude,
			devicetimestamp = var_timestamp;
			
		SELECT LAST_INSERT_ID() AS lastid ; 
		
	ELSE
		SELECT 0 AS lastid;
				
	END IF;								
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_inventorysummarydetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_inventorysummarydetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_inventorysummarydetail`(
					IN var_inventorykey DECIMAL(28,0),
