					IN var_cashpromoitemgsttax DOUBLE(8,0),
					IN var_tcsalesitemexcisetax DOUBLE(8,0),
					IN var_tcsalesitemgsttax DOUBLE(8,0),
					IN var_tcreturnitemexcisetax DOUBLE(8,0),
					IN var_tcreturnitemgsttax DOUBLE(8,0),
					IN var_tcdamageditemexcisetax DOUBLE(8,0),
					IN var_tcdamageditemgsttax DOUBLE(8,0),
					IN var_tcfgitemexcisetax DOUBLE(8,0),
					IN var_tcfgitemgsttax DOUBLE(8,0),
					IN var_tcpromoitemexcisetax DOUBLE(8,0),
					IN var_tcpromoitemgsttax DOUBLE(8,0),
					IN var_gcsalesitemexcisetax DOUBLE(8,0),
					IN var_gcsalesitemgsttax DOUBLE(8,0),
					IN var_gcreturnitemexcisetax DOUBLE(8,0),
					IN var_gcreturnitemgsttax DOUBLE(8,0),
					IN var_gcdamageditemexcisetax DOUBLE(8,0),
					IN var_gcdamageditemgsttax DOUBLE(8,0),
					IN var_gcfgitemexcisetax DOUBLE(8,0),
					IN var_gcfgitemgsttax DOUBLE(8,0),
					IN var_gcpromoitemexcisetax DOUBLE(8,0),
					IN var_gcpromoitemgsttax DOUBLE(8,0),
					IN var_batchdetailkey DECIMAL(18,0),
					IN var_stdsalescaseprice DECIMAL(18,6),
					IN var_stdreturncaseprice DECIMAL(18,6),
					IN var_expiryqty DECIMAL(18,0),
					IN var_stdgoodreturncaseprice DECIMAL(18,6),
					IN var_stdgoodreturnprice DECIMAL(18,6),
					IN var_currencycode DECIMAL(18,0),
					IN var_returnfreeqty DECIMAL(18,0),
					IN var_damageqty DECIMAL(18,0),
					IN var_expdmgfreeqty DECIMAL(18,0),
					IN var_expunloadqty DECIMAL(18,0),
					IN var_dmgunloadqty DECIMAL(18,0),
					IN var_expdmgfreeunloadqty DECIMAL(18,0),
					IN var_rentqty DECIMAL(18,0),
					IN var_mdate DATETIME,	
					IN var_loadadjustqty DECIMAL(18,0)
				)
BEGIN
	DECLARE cnt INT DEFAULT 0;
	
	SELECT COUNT(*) INTO cnt FROM inventorysummarydetail WHERE itemcode = var_itemcode AND routekey = var_routekey AND record_flag='1';
	
	IF cnt = 0 THEN
	
		INSERT INTO inventorysummarydetail SET 	
						inventorykey = var_inventorykey,
						itemcode = var_itemcode,
						routekey = var_routekey,
						weighted = var_weighted,
						beginstockqty = var_beginstockqty,
						loadqty = var_loadqty,
						loadaddqty = var_loadaddqty,
						loadcutqty = var_loadcutqty,
						loadreqqty = var_loadreqqty,
						saleqty = var_saleqty,
						returnqty = var_returnqty,
