/* Procedure structure for procedure `sp_ws_getdata_from_invoicerxddetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_invoicerxddetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_invoicerxddetail`(	    
		IN var_routekey DECIMAL(28,0),
		IN var_visitkey DECIMAL(28,0),
		IN var_transactionkey DECIMAL(28,0),
		IN var_itemtransactiontype INT(11),
		IN var_itemcode DECIMAL(18,0),
		IN var_itemtranstypeseq INT(11),
		IN var_reasoncode INT(11),
		IN var_quantity DECIMAL(18,0),
		IN var_catchweightqty DECIMAL(18,0),
		IN var_weighted INT(11),
		IN var_instructioncode INT(11),
		IN var_currencycode DECIMAL(18,0),
		IN var_expirydate DATETIME,
		IN var_invoiceno DECIMAL(28,0)
	)
BEGIN
	DECLARE cnt INT DEFAULT 0;
	
	SELECT COUNT(*) INTO cnt FROM invoicerxddetail 
		WHERE routekey = var_routekey AND visitkey =var_visitkey AND itemcode =var_itemcode AND 
			itemtransactiontype = var_itemtransactiontype AND reasoncode = var_reasoncode;
			
 	IF cnt = 0 and var_itemcode > 0 THEN
	
		INSERT INTO invoicerxddetail SET 	
			routekey = var_routekey,
			visitkey = var_visitkey,
			transactionkey = var_transactionkey,
			itemtransactiontype = var_itemtransactiontype,
			itemcode = var_itemcode,
			itemtranstypeseq = var_itemtranstypeseq,
			reasoncode = var_reasoncode,
			quantity = var_quantity,
			catchweightqty = var_catchweightqty,
			weighted = var_weighted,
			instructioncode = var_instructioncode,
			currencycode = get_default_currencycode_routekey(var_routekey),
			expirydate = var_expirydate,
			invoiceno = var_invoiceno,
			receivedtime = CURTIME();
	
	END IF;
	
	SELECT var_routekey AS lastid; 	
	
    END */$$
DELIMITER ;

