/* Procedure structure for procedure `sp_ws_getdata_from_salesorderheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_salesorderheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_salesorderheader`(
	IN var_transactionkey DECIMAL(28,0),
	IN var_routekey DECIMAL(28,0),
	IN var_visitkey DECIMAL(28,0),
	IN var_documentnumber DECIMAL(28,0),
	IN var_invoicenumber DECIMAL(28,0),
	IN var_transactiondate DATETIME,
	IN var_transactiontime VARCHAR(10),
	IN var_dsdnumber VARCHAR(20),
	IN var_ponumber VARCHAR(20),
	IN var_customercode DECIMAL(18,0),
	IN var_routecode DECIMAL(18,0),
	IN var_salesmancode DECIMAL(10,0),
	IN var_orderdeliveryroutecode DECIMAL(18,0),
	IN var_orderdeliverydate DATE,
	IN var_totalinvoiceamount DOUBLE(19,4),
	IN var_totalsalesamount DOUBLE(19,4),
	IN var_totalreturnamount DOUBLE(19,4),
	IN var_totaldamagedamount DOUBLE(19,4),
	IN var_dexflag INT(4),
	IN var_splittransaction INT(4),
	IN var_voidflag INT(4),
	IN var_transmitindicator INT(4),
	IN var_hhcinvoicenumber DECIMAL(28,0),
	IN var_paymenttype INT(4),
	IN var_hhcdocumentnumber DECIMAL(28,0),
	IN var_voidreasoncode INT(4),
	IN var_advanceused DOUBLE(8,0),
	IN var_paymentstatus INT(4),
	IN var_advancebalance DOUBLE(8,0),					
	IN var_advancereceived DOUBLE(8,0),
	IN var_currencycode DECIMAL(18,0),
	IN var_status INT(4),
	IN var_refnumber DECIMAL(28,0),
	IN var_totalfreesampleamount DOUBLE(8,0),
	IN var_deliverystatus VARCHAR(25),
	IN var_data INT(4),
	IN var_comments VARCHAR(400),
	IN var_actualtransactiondate DATETIME,
	IN var_comments2 VARCHAR(400),
	IN var_hhctransactionkey DECIMAL(18,0),
	IN var_mdate DATETIME,
	IN var_totalpromoamount DECIMAL(19,4),
	in var_totallineitemtax decimal(19,4)
)
BEGIN
	
DECLARE cnt INT DEFAULT 0;
DECLARE docnumber DECIMAL(28,0) ;
	
		
	SELECT IFNULL(MAX(documentnumber)+1,CAST(CONCAT( CAST(var_routecode AS CHAR(10)),'000001')AS UNSIGNED)) INTO docnumber   FROM salesorderheader WHERE 
	routecode=var_routecode;
	
	
SELECT COUNT(*) INTO cnt FROM salesorderheader WHERE `invoicenumber` = var_invoicenumber;
IF cnt = 0 THEN	
 	
	INSERT INTO salesorderheader SET 	
		routekey = var_routekey,
		visitkey = var_visitkey,
		documentnumber = docnumber,
		invoicenumber = var_invoicenumber,
		transactiondate = var_transactiondate,
		transactiontime = var_transactiontime,
		dsdnumber = var_dsdnumber,
		ponumber = var_ponumber,
		customercode = var_customercode,
		routecode = var_routecode,
		salesmancode = var_salesmancode,
		orderdeliveryroutecode = var_orderdeliveryroutecode,
		orderdeliverydate = var_orderdeliverydate,
		totalinvoiceamount = var_totalinvoiceamount,
		totalsalesamount = var_totalsalesamount,
		totalreturnamount = var_totalreturnamount,
		totaldamagedamount = var_totaldamagedamount,
		dexflag = var_dexflag,
		splittransaction = var_splittransaction,
		voidflag = var_voidflag,
		transmitindicator = var_transmitindicator,
		hhcinvoicenumber = var_hhcinvoicenumber,
		paymenttype = var_paymenttype,
		hhcdocumentnumber = var_hhcdocumentnumber,
		voidreasoncode = var_voidreasoncode,
		advanceused = var_advanceused,
		paymentstatus = var_paymentstatus,
		advancebalance = var_advancebalance,
		mdat = CURRENT_DATE(),
		advancereceived = var_advancereceived,
		currencycode = get_default_currencycode_routekey(var_routekey),
		`status` = var_status,
		refnumber = var_refnumber,
		totalfreesampleamount = var_totalfreesampleamount,
		deliverystatus = var_deliverystatus,
		`data` = var_data,
		comments = var_comments,
		actualtransactiondate = var_actualtransactiondate,
		comments2 = var_comments2,
		hhctransactionkey = var_hhctransactionkey,
		totalpromoamount=var_totalpromoamount,
		record_flag='1',
		receivedtime = CURTIME(),
		totallineitemtax=var_totallineitemtax;	
 				
	SELECT LAST_INSERT_ID() AS lastid ; 					
			
ELSE
	UPDATE salesorderheader SET voidflag = var_voidflag WHERE `invoicenumber` = var_invoicenumber;
		
	SELECT transactionkey AS lastid FROM salesorderheader WHERE `invoicenumber` = var_invoicenumber;
END IF;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_sigcaptchdata` */

