/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_t_access_override_log` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_t_access_override_log`(
IN var_routekey DECIMAL(28,0),
IN var_visitkey DECIMAL(28,0),
IN var_type DECIMAL(3,0),
