END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_invoiceheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_invoiceheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_invoiceheader`(
		IN var_transactionkey BIGINT(20),
		IN var_routekey BIGINT(20),
		IN var_visitkey BIGINT(20),
		IN var_documentnumber DECIMAL(28,0),
		IN var_invoicenumber DECIMAL(28,0),
		IN var_transactiondate DATETIME,
		IN var_transactiontime VARCHAR(10),
		IN var_dsdnumber VARCHAR(20),
		IN var_ponumber VARCHAR(20),
		IN var_customercode BIGINT(20),
		IN var_routecode BIGINT(20),
		IN var_salesmancode BIGINT(20),
		IN var_presoldordernumber DECIMAL(18,0),
		IN var_presalesmancode DECIMAL(18,0),
		IN var_presalesroutecode DECIMAL(18,0),
		IN var_orderdeliverydate DATETIME,
		IN var_orderdeliveryroutecode DECIMAL(18,0),
		IN var_totalinvoiceamount DECIMAL(19,4),
		IN var_totalsalesamount DECIMAL(19,4),
		IN var_totalreturnamount DECIMAL(19,4),
		IN var_totaldamagedamount DECIMAL(19,4),
		IN var_totalfreesampleamount DECIMAL(19,4),
		IN var_immediatepaid DECIMAL(19,4),
		IN var_amountpaid DECIMAL(19,4),
		IN var_invoicebalance DECIMAL(19,4),
		IN var_dexflag INT(11),
		IN var_dexg86signature VARCHAR(13),
		IN var_paymenttype INT(11),
		IN var_splittransaction INT(11),
		IN var_voidflag INT(11),
		IN var_transmitindicator INT(11),
		IN var_paymentstatus INT(11),
		IN var_hhcinvoicenumber DECIMAL(28,0),
		IN var_totalpromoamount DECIMAL(19,4),
		IN var_gcpaymenttype INT(11),
		IN var_hhcdocumentnumber DECIMAL(28,0),
		IN var_inventorykey DECIMAL(28,0),
		IN var_totaltaxesamount DECIMAL(19,4),
		IN var_itemlinetaxamount DECIMAL(19,4),
		IN var_totaldiscountamount DECIMAL(19,4),
		IN var_voidreasoncode INT(11),
		IN var_totalexpiryamount DECIMAL(19,4),
		IN var_currencycode DECIMAL(18,0),
		IN var_totalmanualfree DECIMAL(19,4),
		IN var_totallimitedfree DECIMAL(19,4),
		IN var_totalrebaterent DECIMAL(19,4),
		IN var_totalfixedrent DECIMAL(19,4),
		IN var_actualtransactiondate DATETIME,
		IN var_boentry INT(11),
		IN var_hhctransactionkey DECIMAL(18,0),
		IN var_data INT(11),
		IN var_comments VARCHAR(200),
		IN var_totaldiscdistributionamount DECIMAL(19,4),
		IN var_totalreplacementamount DECIMAL(19,4),
		IN var_comments2 VARCHAR(200),
		IN var_lineitemdiscount DECIMAL(19,4),
		IN var_totalreturnpromoamount DECIMAL(19,4),
		IN var_returnlineitemdiscount DECIMAL(19,4),
		IN var_totalbuybackfreeamount DECIMAL(19,4),
		IN var_roundtotalsalesamount DECIMAL(18,4),
		IN var_diffround DECIMAL(18,4),
		IN var_headerdisctaxamount DECIMAL(19,4))
BEGIN
	
 	DECLARE cnt INT DEFAULT 0;
 	DECLARE docnumber DECIMAL(28,0) ;
		
	SELECT COUNT(*) INTO cnt FROM invoiceheader WHERE `invoicenumber` = var_invoicenumber;
	
	
	SELECT IFNULL(MAX(documentnumber)+1,CAST(CONCAT( CAST(var_routecode AS CHAR(10)),'000001')AS UNSIGNED)) INTO docnumber   FROM invoiceheader WHERE 
	routecode=var_routecode;
   
 	
 	IF cnt = 0 THEN		
		INSERT INTO invoiceheader SET 
			routekey = var_routekey,
			visitkey = var_visitkey,
		         documentnumber =  docnumber, 
			invoicenumber = var_invoicenumber,
			transactiondate = check_monthclosing_time(var_transactiondate),
			transactiontime = var_transactiontime,
			dsdnumber = var_dsdnumber,
			ponumber = var_ponumber,
			customercode = var_customercode,
			routecode = var_routecode,
			salesmancode = var_salesmancode,
			presoldordernumber = var_presoldordernumber,
			presalesmancode = var_presalesmancode,
			presalesroutecode = var_presalesroutecode,
			orderdeliverydate = var_orderdeliverydate,
			orderdeliveryroutecode = var_orderdeliveryroutecode,
			totalinvoiceamount = var_totalinvoiceamount,
			totalsalesamount = var_totalsalesamount,
			totalreturnamount = var_totalreturnamount,
			totaldamagedamount = var_totaldamagedamount,
			totalfreesampleamount = var_totalfreesampleamount,
			immediatepaid = var_immediatepaid,
			amountpaid = var_amountpaid,
			invoicebalance = var_invoicebalance,
			dexflag = var_dexflag,
			dexg86signature = var_dexg86signature,
			paymenttype = var_paymenttype,
			splittransaction = CASE WHEN var_invoicebalance = 0 AND var_totalsalesamount > 0 AND var_totalreturnamount > 0 THEN 1 ELSE 0 END,
			voidflag = var_voidflag,
			transmitindicator = var_transmitindicator,
			paymentstatus = var_paymentstatus,
			hhcinvoicenumber = var_invoicenumber*10,
			totalpromoamount = var_totalpromoamount,
			gcpaymenttype = var_gcpaymenttype,
			hhcdocumentnumber = var_hhcdocumentnumber,
			inventorykey = var_inventorykey,
			totaltaxesamount = var_totaltaxesamount,
			itemlinetaxamount = var_itemlinetaxamount,
			totaldiscountamount = var_totaldiscountamount,
			voidreasoncode = var_voidreasoncode,
			totalexpiryamount = var_totalexpiryamount,
			currencycode = get_default_currencycode_routecode(var_routecode),
			totalmanualfree = var_totalmanualfree,
			totallimitedfree = var_totallimitedfree,
			totalrebaterent = var_totalrebaterent,
			totalfixedrent = var_totalfixedrent,
			actualtransactiondate = var_transactiondate,
			boentry = var_boentry,
			hhctransactionkey = var_hhctransactionkey,
			`data` = var_data,
			comments = var_comments,
			totaldiscdistributionamount = var_totaldiscdistributionamount,
			totalreplacementamount = var_totalreplacementamount,
			comments2 = var_comments2,
			record_flag='1',
			lineitemdiscount = var_lineitemdiscount,
			totalreturnpromoamount = var_totalreturnpromoamount,
			returnlineitemdiscount = var_returnlineitemdiscount,
			totalbuybackfreeamount = var_totalbuybackfreeamount,
			roundtotalsalesamount=var_roundtotalsalesamount,
			diffround=var_diffround,
			receivedtime = CURTIME(),
			headerdiscounttaxamt = var_headerdisctaxamount;
				
			SELECT LAST_INSERT_ID() AS lastid ; 					
			
		ELSE
			UPDATE invoiceheader SET voidflag = var_voidflag WHERE `invoicenumber` = var_invoicenumber;
			UPDATE customerinvoice SET voidflag = var_voidflag WHERE `invoicenumber` = var_invoicenumber;
			
			SELECT transactionkey AS lastid FROM invoiceheader WHERE `invoicenumber` = var_invoicenumber;
		END IF;
		
    END */$$
DELIMITER ;

