/* Procedure structure for procedure `sp_ws_getdata_whstock` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_whstock` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_whstock`(
	var_routeid  VARCHAR(15)
    )
BEGIN
	
	SET @dyn_sql = CONCAT("SELECT item.actualitemcode, 
		item.defaultsalesprice, item.defaultreturnprice, item.caseprice, item.returncaseprice, 
		item.warehousestock		
		FROM itemmaster AS item	
		LEFT JOIN routeitemmapping AS rim ON rim.itemcode = item.actualitemcode
		LEFT JOIN routemaster AS rm ON rm.routeitemgrpcode = rim.routeitemgrpcode	
	        WHERE  item.activeitem = 1 AND rm.routecode = ",var_routeid, " ");
                
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdepotmaster` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdepotmaster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdepotmaster`(
	IN rwcnt INT,			
	IN srchvalue VARCHAR(500), 	
	IN order_by VARCHAR(500),	
	IN order_type VARCHAR(10),	
	IN lmt_strt INT,		
	IN lmt_end INT 			
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	IF order_by = '' THEN
		SET order_by = 'DepotCode';
	END IF;
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
    IF rwcnt = 1 THEN
	SET @dyn_sql = CONCAT("SELECT COUNT(depot.depotcode) AS counter FROM depotmaster AS depot
	LEFT JOIN `branchmanager` AS `branch` ON branch.branchmanagercode = depot.branchmanagercode
	LEFT JOIN `company` AS `cmp` ON cmp.cmpycode = depot.cmpycode
	WHERE (Name LIKE('%",srchvalue,"%') OR depotname LIKE('%",srchvalue,"%')  OR branchmanagername LIKE('%",srchvalue,"%'))");
    ELSE
	SET @dyn_sql = CONCAT("SELECT `depot`.`depotcode`, `depot`.`depotname`, `branch`.`branchmanagername`, `cmp`.`name`,
	`depot`.`activestatus` FROM `depotmaster` AS `depot`
	LEFT JOIN `branchmanager` AS `branch` ON branch.branchmanagercode = depot.branchmanagercode
	LEFT JOIN `company` AS `cmp` ON cmp.cmpycode = depot.cmpycode
	WHERE (name LIKE('%",srchvalue,"%') OR depotName LIKE('%",srchvalue,"%')  OR branchmanagername LIKE('%",srchvalue,"%'))
	ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    END IF;
	PREPARE s1 FROM @dyn_sql;
	
	EXECUTE s1;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getfrom_customer_foc_balance` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getfrom_customer_foc_balance` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getfrom_customer_foc_balance`(
					IN var_customercode bigint(20),
					IN var_itemcode bigint(20),
					IN var_originalqty decimal(9,0),
					IN var_balanceqty decimal(9,0),
					IN var_contractid varchar(20),
					IN var_startdate datetime				
				)
BEGIN
    DECLARE cnt INT DEFAULT 0;
SELECT COUNT(*) INTO cnt FROM customer_foc_balance WHERE customercode = var_customercode AND itemcode = var_itemcode;
 	IF cnt = 0 THEN
 	
 	INSERT INTO customer_foc_balance SET customercode = var_customercode,
						itemcode = var_itemcode,
						originalqty = var_originalqty,
						balanceqty = var_balanceqty,
						contractid = var_contractid,
						startdate = var_startdate;
ELSE
			
UPDATE customer_foc_balance SET customercode = var_customercode,
						itemcode = var_itemcode,
						originalqty = var_originalqty,
						balanceqty = var_balanceqty,
						contractid = var_contractid,
						startdate = var_startdate WHERE customercode = var_customercode AND itemcode = var_itemcode;
		END IF;			
											
			SELECT customercode,itemcode  FROM customer_foc_balance WHERE customercode = var_customercode AND itemcode = var_itemcode; 
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getfrom_table_enddaydetail` */

