DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getfrom_table_enddaydetail`( 
	IN var_routekey decimal(28,0),
	IN var_detailtypecode int(11),
	IN var_listtypecode int(11),
	IN var_amount decimal(19,4),
	IN var_currencycode decimal(18,0))
BEGIN
    INSERT INTO enddaydetail SET routekey = var_routekey,
		detailtypecode = var_detailtypecode,
		listtypecode = var_listtypecode,
