/* Procedure structure for procedure `sp_ws_getsubareamaster` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getsubareamaster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getsubareamaster`(
	IN rwcnt INT,			
	IN srchvalue VARCHAR(500), 	
	IN order_by VARCHAR(500),	
	IN order_type VARCHAR(10),	
	IN lmt_strt INT,		
	IN lmt_end INT 			
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	IF order_by = '' THEN
		SET order_by = 'subareacode';
	END IF;
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
    IF rwcnt = 1 THEN
	SET @dyn_sql = CONCAT("SELECT COUNT(subarea.subareacode) AS counter FROM subareamaster AS subarea
	LEFT JOIN `supervisor` AS `supervisor` ON supervisor.supervisorcode = subarea.supervisorcode
	LEFT JOIN `areamaster` AS `area` ON area.areacode = subarea.areacode
	LEFT JOIN `depotmaster` AS `depot` ON depot.depotcode = area.depotcode
	WHERE (subareaname LIKE('%",srchvalue,"%') OR supervisorname LIKE('%",srchvalue,"%') OR depotname LIKE('%",srchvalue,"%') OR areaname LIKE('%",srchvalue,"%'))");
    ELSE
	SET @dyn_sql = CONCAT("SELECT `subarea`.`subareacode`, `subarea`.`subareaname`, `supervisor`.`supervisorname`, `area`.`areaname`,`depot`.`depotname`,
	`subarea`.`activestatus` FROM `subareamaster` AS `subarea`
	LEFT JOIN `supervisor` AS `supervisor` ON supervisor.supervisorcode = subarea.supervisorcode
	LEFT JOIN `areamaster` AS `area` ON area.areacode = subarea.areacode
	LEFT JOIN `depotmaster` AS `depot` ON depot.depotcode = area.depotcode
	WHERE (subareaname LIKE('%",srchvalue,"%') OR supervisorname LIKE('%",srchvalue,"%') OR depotname LIKE('%",srchvalue,"%') OR areaname LIKE('%",srchvalue,"%'))
	ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    END IF;
	PREPARE s1 FROM @dyn_sql;
	
	EXECUTE s1;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_gettourid_routekey` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_gettourid_routekey` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_gettourid_routekey`(
	IN var_routekey BIGINT(28)
	)
BEGIN
	
	DECLARE var_new_routekey BIGINT(28) DEFAULT 0;	
	DECLARE var_routestartdate DATETIME;   
	
   
		SELECT sed.tourid, COUNT(ith.documentnumber) requests FROM  startendday sed
		LEFT OUTER JOIN inventorytransactionheader ith ON ith.routekey = sed.routekey AND ith.transactiontype = 4 AND transmitindicator = 0
			WHERE 
			sed.routekey = var_routekey
			GROUP BY
		sed.tourid;
	
END */$$
DELIMITER ;

