/* Procedure structure for procedure `sp_ws_import_getdata_from_salesman` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_import_getdata_from_salesman` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_import_getdata_from_salesman`(
	in var_salesmancode VARCHAR(25),
	in var_salemanname1 varchar(250),
	IN var_ANSalesmanCode varchar(25),
	IN var_SupervisorCode VARCHAR(25),
	IN var_VehRegNum VARCHAR(250),
	IN var_activestatus VARCHAR(25),
	IN var_SalesType  VARCHAR(25)
    )
BEGIN
    DECLARE alternateSCode  VARCHAR(25);
    DECLARE supName  VARCHAR(250);
    DECLARE vehNum  VARCHAR(25);
    
    SELECT alternatesalesmancode INTO alternateSCode FROM salesman where alternatesalesmancode=var_salesmancode and type=0;
    SELECT salesmanname1 INTO supName FROM salesman WHERE salesmanname1=var_SupervisorCode AND TYPE=2;
    SELECT vandescription INTO vehNum FROM vanmaster WHERE vandescription=var_VehRegNum ;
    if alternateSCode is null then
         INSERT INTO salesman(salesmanname1,alternatesalesmancode,ansalesmancode,activestatus,type,cdat)
	 VALUES( var_salemanname1, var_salesmancode,var_ANSalesmanCode,var_activestatus,0, NOW());
     else
	update salesman set salesmanname1=var_salemanname1,ansalesmancode=var_ANSalesmanCode ,activestatus=var_activestatus
        where alternatesalesmancode=var_salesmancode;
     end IF;
     
     
          IF supName IS NULL THEN
              IF   (var_SupervisorCode IS NOT NULL OR var_SupervisorCode !='') THEN
                 INSERT INTO supervisor(parentcompany,supervisorname)
                 VALUES(1, var_SupervisorCode);
                  INSERT INTO salesman(salesmanname1,activestatus,TYPE,cdat)
	          VALUES( var_SupervisorCode,var_activestatus ,2, NOW());
           
            END IF;
           END IF;  
     
          IF vehNum IS NULL THEN
              IF   (var_VehRegNum IS NOT NULL OR var_VehRegNum !='') THEN
                 INSERT INTO vanmaster(vandescription,activestatus,cdat)
                 VALUES(var_VehRegNum, var_activestatus,NOW());
            END IF;   
          END IF;    	
END */$$
DELIMITER ;

