/* Procedure structure for procedure `sp_ws_itemlistbyroute` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_itemlistbyroute` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_itemlistbyroute`(
	IN RouteCode INT,
	IN SalesmanCode INT
    )
BEGIN
	SELECT im.itemshortdescription, im.unitspercase,im.case1,im.case2,im.actualitemcode FROM itemmaster AS im
	INNER JOIN inventorytransactiondetail AS itd ON itd.RouteKey = RouteCode AND itd.transactiontypecode = 1 AND itd.itemcode = im.actualitemcode;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_salesman_login` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_salesman_login` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_salesman_login`(
	var_username VARCHAR(255),
	var_userpassword  VARCHAR(255),
	var_deviceid  VARCHAR(255)
    )
BEGIN
	DECLARE cnt INT DEFAULT 0;	
	
	update routemaster set device_assigned_id = var_deviceid 
	where salesmancode = (select salesmancode from salesman where username = var_username limit 1) 
	and routecode in (select routecode from auto_reg_device_routes where sts = 1);
	
	SELECT COUNT(*) INTO cnt FROM salesman AS sm WHERE sm.username = var_username AND sm.userpassword = var_userpassword;
	
	SET @deviceID = '';
	SELECT CASE WHEN COALESCE(rm.device_assigned_id,'') = '' THEN '-' ELSE COALESCE(rm.device_assigned_id,'') END INTO @deviceID 
	FROM routemaster rm INNER JOIN salesman sm ON sm.salesmancode = rm.salesmancode 
	WHERE sm.username = var_username AND sm.userpassword = var_userpassword;
	
	SELECT CASE WHEN INSTR(VERSION(),'ubuntu') THEN 1 ELSE 0 END useencription INTO @useencription;
	
	IF cnt = 0 THEN
		SELECT  1 AS STATUS;
		
	ELSE
		IF @deviceID = '-' THEN
			SELECT 3 AS STATUS;
			
		ELSEIF @deviceID <> var_deviceid THEN
			SELECT 2 AS STATUS;
			
		ELSE				 
			IF cnt > 0 THEN				 
				SELECT 0 AS  STATUS, rm.routecode , rm.cdat, sm.* , @useencription useencription
				FROM salesman AS sm LEFT JOIN routemaster AS rm ON rm.salesmancode = sm.salesmancode
				WHERE sm.username = var_username AND sm.userpassword = var_userpassword;
			 
			ELSE				
				SELECT  1 AS STATUS;
			 
			END IF;	
		END IF;	
	END IF;	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_salesman_loginbk` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_salesman_loginbk` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_salesman_loginbk`(
	var_username VARCHAR(255),
	var_userpassword  VARCHAR(255),
	var_deviceid  VARCHAR(255)
    )
BEGIN
	DECLARE cnt INT DEFAULT 0;	
	SELECT COUNT(*) INTO cnt FROM salesman AS sm WHERE sm.username = var_username AND sm.userpassword = var_userpassword;
	
	SET @deviceID = '';
	SELECT CASE WHEN COALESCE(rm.device_assigned_id,'') = '' THEN '-' ELSE COALESCE(rm.device_assigned_id,'') END INTO @deviceID 
	FROM routemaster rm INNER JOIN salesman sm ON sm.salesmancode = rm.salesmancode 
	WHERE sm.username = var_username AND sm.userpassword = var_userpassword;
	
	SELECT CASE WHEN INSTR(VERSION(),'ubuntu') THEN 1 ELSE 0 END useencription INTO @useencription;
	
	
	
	
	
	IF cnt = 0 THEN
		SELECT  1 AS STATUS;
		
	ELSE
	
	
		IF @deviceID = '-' THEN
			SELECT 3 AS STATUS;
			
		ELSE  IF @deviceID <> var_deviceid THEN
		
		
		-- starts here
		
		INSERT INTO tbl_device_reassigned
		SELECT primary_key,company_id,device_id,remarks,var_deviceid FROM tbl_device WHERE device_id=@deviceID;
		
		
		
		
		SELECT COUNT(*) INTO @count FROM tbl_device WHERE device_id=var_deviceid;
		-- SELECT @count;
		IF @count>0 THEN
		DELETE FROM tbl_device WHERE device_id=var_deviceid;
		END IF;
		
		-- update tbl_device set device_id=var_deviceid WHERE device_id=@deviceID;
		-- INSERT INTO tbl_device 
		-- SELECT primary_key,company_id,var_deviceid,remarks FROM tbl_device WHERE device_id=@deviceID;
		
		
			SET @qry1 = CONCAT("INSERT INTO tbl_device 
		SELECT primary_key,company_id,'",var_deviceid,"',remarks FROM tbl_device WHERE device_id='",@deviceID,"'");
									
			 	PREPARE res1 FROM @qry1;
			 	EXECUTE res1;
		
		-- SELECT @qry1;
		
		DELETE FROM tbl_device WHERE device_id=@deviceID;
		
		-- DELETE FROM tbl_device WHERE device_id=@deviceID;
		
		
	SET @qry6 = CONCAT("UPDATE routemaster rm 
		INNER JOIN salesman sm ON sm.salesmancode = rm.salesmancode 
		SET rm.device_assigned_id='",var_deviceid,"' WHERE sm.username = '",var_username,"' AND sm.userpassword = '",var_userpassword,"'");
									
			 	PREPARE res6 FROM @qry6;
			 	EXECUTE res6;
		-- SELECT @qry6;		
	
		IF cnt > 0 THEN				 
				SELECT 0 AS  STATUS, rm.routecode , rm.cdat, sm.* , @useencription useencription
				FROM salesman AS sm LEFT JOIN routemaster AS rm ON rm.salesmancode = sm.salesmancode
				WHERE sm.username = var_username AND sm.userpassword = var_userpassword;
			 
			ELSE				
				SELECT  1 AS STATUS;
			 
			END IF;
	
		-- ends	
		
		
		
		--	SELECT 2 AS STATUS,(SELECT routecode FROM routemaster WHERE 
          --  device_assigned_id=var_deviceid)AS routecode;
			
		ELSE				 
			IF cnt > 0 THEN				 
				SELECT 0 AS  STATUS, rm.routecode , rm.cdat, sm.* , @useencription useencription
				FROM salesman AS sm LEFT JOIN routemaster AS rm ON rm.salesmancode = sm.salesmancode
				WHERE sm.username = var_username AND sm.userpassword = var_userpassword;
			 
			ELSE				
				SELECT  1 AS STATUS;
			 
			END IF;
       END IF;			
		END IF;	
	END IF;	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_stratendday` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_stratendday` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_stratendday`(
    IN var_routecode BIGINT(20),
    IN var_salesmancode BIGINT(20),
    IN var_routestartodometer DECIMAL(18,0),
    IN var_deviceid VARCHAR(50),
    IN var_version VARCHAR(50),
    IN var_routestartdate datetime	    
    )
BEGIN
	DECLARE var_routeclosed INT(1) DEFAULT 2;
	DECLARE var_currentdate datetime;
	
		DECLARE vno VARCHAR(50) DEFAULT '0';
		DECLARE vsts VARCHAR(50)  DEFAULT '0';	
		SELECT VER_NO, VER_STS INTO vno, vsts FROM route_version_map 
		WHERE route_code = var_routecode LIMIT 1;
	
SELECT routeclosed INTO var_routeclosed FROM startendday WHERE routecode = var_routecode ORDER BY routekey DESC LIMIT 0,1;
select  CURDATE() into var_currentdate;
IF var_currentdate != var_routestartdate THEN
SELECT 2 AS `status`;
	ELSEIF vsts = 1 AND vno <> var_version  THEN
		SELECT 3 AS `status`; 
Else
	IF (var_routeclosed <> 0 ) THEN 
	
		SELECT rm.subareacode,sam.supervisorcode,sam.areacode,am.areamanagercode,am.depotcode,dm.branchmanagercode,
			   dm.cmpycode,co.nationalsalesmanagercode,rm.amountdecimaldigits,rm.memo1
		INTO   @subareacode,@supervisorcode,@areacode,@areamanagercode,@depotcode,@branchmanagercode,
			   @cmpycode,@nationalsalesmanagercode,@amountdecimaldigits,@tourid
		FROM routemaster rm,subareamaster sam,areamaster am,depotmaster dm,company co
		
		WHERE sam.subareacode = rm.subareacode AND am.areacode = sam.areacode AND dm.depotcode = am.depotcode
			  AND co.cmpycode = dm.cmpycode AND rm.routecode = var_routecode;	
	
		
		
		INSERT INTO startendday SET 
				routecode = var_routecode,
				salesmancode = var_salesmancode,
				routestartdate = CURDATE(),
				routestarttime = CURTIME(),
				routestartodometer = var_routestartodometer,
				triptype = 0,
				areacode = @areacode,
				areamanagercode = @areamanagercode,
				branchmanagercode = @branchmanagercode,
				cmpycode = @cmpycode,
				currencycode = @amountdecimaldigits,
				depotcode=@depotcode,
				nationalsalesmanagercode=@nationalsalesmanagercode,
				subareacode=@subareacode,
				supervisorcode=@supervisorcode,
				dataconrefnumber = var_deviceid,
				versionno=var_version,
				tourid=@tourid;
				
				
		SELECT LAST_INSERT_ID()INTO @last_id ;		
		SELECT routekey,routestartdate,routestarttime,routestartodometer FROM startendday WHERE routekey= @last_id;
		
	ELSE
		
		
		SELECT 1 AS `status`;
			
	   END IF;
	END IF;
	
    END */$$
DELIMITER ;

