/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_syncicsdata`(
	IN var_userid INT,
	IN var_deviceid VARCHAR(255),
	IN var_routeid INT,
	IN var_checkmdate INT
