	DECLARE var_where29 VARCHAR(250);
	
	SET var_where1 = "";
	SET var_where2 = "";
	SET var_where3 = "";
	SET var_where4 = "";
	SET var_where5 = "";
	SET var_where6 = "";
	SET var_where7 = "";
	SET var_where8 = "";
	SET var_where9 = "";
	
	SET var_where11 = "";
	SET var_where12 = "";
	SET var_where13 = "";
	SET var_where14 = "";
	SET var_where15 = "";
	SET var_where16 = "";
	SET var_where17 = "";
	SET var_where18 = "";
	SET var_where19 = "";
	SET var_where20 = "";
	SET var_where21 = "";
	SET var_where22 = "";
	SET var_where23 = "";
	SET var_where24 = "";
	SET var_where25 = "";
	SET var_where26 = "";
	SET var_where27 = "";
	SET var_where28 = "";
	SET var_where29 = "";
		
	IF var_checkmdate = 1 THEN
		
		SELECT syncdate INTO var_syncdate FROM tbl_syncservice WHERE userid = var_userid AND deviceid = var_deviceid;
		   IF var_syncdate != '' THEN
			
			SET var_where1 = CONCAT(" AND item.mdat > '",var_syncdate,"' ");
			SET var_where2 = CONCAT(" AND cust.mdat > '",var_syncdate,"' ");
			SET var_where3 = CONCAT(" AND cust.mdat > '",var_syncdate,"' ");
			SET var_where4 = CONCAT(" AND sman.mdat > '",var_syncdate,"' ");
			SET var_where5 = CONCAT(" AND route.mdat > '",var_syncdate,"' ");
			SET var_where6 = CONCAT(" AND bankmaster.mdat > '",var_syncdate,"' ");			
			SET var_where7 = CONCAT(" AND company.mdat > '",var_syncdate,"' ");
			SET var_where8 = CONCAT(" AND controlpanel.modifieddate > '",var_syncdate,"' ");
			SET var_where9 = CONCAT(" AND setup.modifieddate > '",var_syncdate,"' ");			
			SET var_where11 = CONCAT(" AND sd.mdat > '",var_syncdate,"' ");
			SET var_where12 = CONCAT(" AND ig.mdat > '",var_syncdate,"' ");			
			SET var_where13 = CONCAT(" AND startendday.modifieddate > '",var_syncdate,"' ");			
			SET var_where14 = CONCAT(" AND isd.mdat > '",var_syncdate,"' ");
			SET var_where15 = CONCAT(" AND customerinvoice.mdat > '",var_syncdate,"' ");
			SET var_where16 = CONCAT(" AND discountkeydetail.mdat > '",var_syncdate,"' ");
			SET var_where17 = CONCAT(" AND discountkeyheader.mdat > '",var_syncdate,"' ");
			SET var_where18 = CONCAT(" AND pricingdetail1.mdat > '",var_syncdate,"' ");
			SET var_where19 = CONCAT(" AND promoplandetail.mdat > '",var_syncdate,"' ");
			SET var_where20 = CONCAT(" AND promoplanheader.mdat > '",var_syncdate,"' ");
			SET var_where21 = CONCAT(" AND promokeydetail.mdat > '",var_syncdate,"' ");
			SET var_where22 = CONCAT(" AND promokeyheader.mdat > '",var_syncdate,"' ");
			SET var_where23 = CONCAT(" AND promotionassignmentadvance.mdat > '",var_syncdate,"' ");
			SET var_where24 = CONCAT(" AND promotioncontrol.mdat > '7",var_syncdate,"' ");
			SET var_where25 = CONCAT(" AND promotiondetail.mdat > '",var_syncdate,"' ");
			SET var_where26 = CONCAT(" AND distributionkeydetails.mdat > '",var_syncdate,"' ");
			SET var_where27 = CONCAT(" AND mdat > '",var_syncdate,"' ");
			SET var_where28 = CONCAT(" AND mdat > '",var_syncdate,"' ");
			SET var_where29 = CONCAT(" AND customerpricing1.mdat > '",var_syncdate,"' ");
			
		   END IF;
	   END IF;
	   
	   SELECT `status` INTO var_pendinginvoicests FROM controlpanel WHERE flagid = 51;
		
		SET @dyn_sql1 = CONCAT("SELECT  item.actualitemcode, item.itemgroupcode, item.itemtype, item.itemshortdescription, item.itemdescription, item.unitspercase, item.defaultsalesprice, item.defaultreturnprice, item.defaultretailprice, item.pricingkey, item.arbitemshortdescription, item.arbitemdescription, item.hhcitemshortdescription, item.hhcitemdescription, item.activeitem, item.caseprice, item.returncaseprice,
		item.retailcaseprice,
		item.alternatecode,
		item.created,
		item.cdat,
		item.modified,
		item.mdat,
		item.liter,
		item.dataentry,
		item.leadtime,
		item.viewflag,
		item.case1,
		item.case2,
		item.memo1,
		item.memo2,
		item.tcallowed,
		item.itemgroupingcode,
		item.printsequenceroute,
		item.printsequencecust,
		item.upccasecode,
		item.captureshelfstock,
		item.filmbagbarcode,
		item.boxtraybarcode,
		item.cartonbarcode,
		item.highper,
		item.lowper,
		item.literperunit,
		item.commissionallowedflag,
		item.alternateitemgroupcode,
		item.fastmovingitemflag,
		item.codedateformat,
		item.itemtaxkey1,
		item.itemtaxkey2,
		item.itemtaxkey3,
		item.defpricetaxkey1,
		item.defpricetaxkey2,
		item.defpricetaxkey3,
		item.packagecode,
		item.anitemcode,
		item.averagesales,
		item.enablemeatpiecescapture,
