/* Procedure structure for procedure `sp_ws_syncicsdata_customeritemgrp` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_syncicsdata_customeritemgrp` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_syncicsdata_customeritemgrp`(
	IN var_userid INT,
	IN var_deviceid VARCHAR(255),
	IN var_routeid INT  
    )
BEGIN
	
	DECLARE var_syncdate DATETIME;
	
	
	DECLARE var_where1 VARCHAR(250);
	DECLARE var_where2 VARCHAR(250);
	
	SET var_where1 = "";
	SET var_where2 = "";
	
        
	
	SET @dyn_sql1 = CONCAT("SELECT DISTINCT cig.customeritemgrpcode,cig.* FROM customeritemgrp cig
INNER JOIN customermaster cm ON cm.itemmapkey=cig.customeritemgrpcode LEFT JOIN
 routesequence rs ON rs.customercode=cm.customercode WHERE rs.routecode =", var_routeid, " ORDER BY cig.customeritemgrpcode");
	PREPARE s1 FROM @dyn_sql1;
	EXECUTE s1;
        
        
	
	 
	SET @dyn_sql2 = CONCAT("SELECT DISTINCT cim.customeritemgrpcode,cim.* FROM customeritemmapping cim INNER JOIN customeritemgrp cig 
	ON cim.customeritemgrpcode=cig.customeritemgrpcode 
	INNER JOIN customermaster cm ON cm.itemmapkey=cig.customeritemgrpcode 
	LEFT JOIN routesequence rs ON rs.customercode=cm.customercode 
	WHERE rs.routecode=", var_routeid, " ORDER BY cim.itemcode ");
	PREPARE s2 FROM @dyn_sql2;
	EXECUTE s2;      	
	  
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_syncicsdata_customeritemmapping` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_syncicsdata_customeritemmapping` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_syncicsdata_customeritemmapping`(
    IN var_userid INT,	
     IN var_routeid INT
)
BEGIN
DECLARE divcode VARCHAR(250);
SELECT divisioncode INTO @divcode FROM routemaster WHERE routecode=var_routeid;
  
	SET @dyn_sql1 = CONCAT("SELECT DISTINCT cig.* FROM customeritemgrp cig  
     INNER JOIN customermaster cm ON cm.itemmapkey=cig.customeritemgrpcode
     WHERE cm.routecode =", var_routeid, "");
	PREPARE s1 FROM @dyn_sql1;
	
	 EXECUTE s1;
		
        
        
	SET @dyn_sql2 = CONCAT("SELECT DISTINCT  cmp.customeritemgrpcode,cmp.* FROM customeritemmapping cmp 
	INNER JOIN itemmaster im ON im.actualitemcode=cmp.itemcode
        INNER JOIN customermaster cm ON cm.itemmapkey=cmp.customeritemgrpcode
        WHERE im.companygroupname  ='",@divcode, "' and cm.routecode  =", var_routeid, "");
	 PREPARE s2 FROM @dyn_sql2;
        
	 EXECUTE s2;  
	 
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_syncicsdata_customeroutstanding` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_syncicsdata_customeroutstanding` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_syncicsdata_customeroutstanding`(
	IN var_userid INT,	
	IN var_routeid INT  
    )
BEGIN
	
	DECLARE var_syncdate DATETIME;
	DECLARE var_where1 VARCHAR(250);
	DECLARE var_where2 VARCHAR(250);	
	SET var_where1 = "";
	SET var_where2 = "";
		 
	SET @dyn_sql2 = CONCAT(" SELECT DISTINCT ci.transactionkey,
ci.transactiontype,
ci.documentnumber,
ci.invoicenumber,
ci.transactiondate,
ci.transactiontime,
ci.customercode,
ci.routecode route_id, 
ci.routecode,
ci.salesmancode,
ci.totalinvoiceamount,
ci.totalsalesamount,
ci.totalreturnamount,
ci.totaldamagedamount,
ci.totalfreesampleamount,
ci.immediatepaid,
ci.amountpaid,
ci.dnamountpaid,
ci.cnamountpaid,
ci.invoicebalance,
ci.paymenttype,
ci.voidflag,
ci.paymentstatus,
ci.hhcinvoicenumber, 
sm.alternatesalesmancode remarks1,
'' remarks2,
ci.routestartdate,
ci.erpreferencenumber,
ci.mdat,
ci.totalpromoamount,
ci.gcpaymenttype,
ci.totaltaxesamount,
ci.itemlinetaxamount,
ci.totaldiscountamount,
ci.pdcindicator,
ci.chequecollection,
ci.totalexpiryamount,
ci.currencycode,
ci.pdcbalance,
ci.totalmanualfree,
ci.totallimitedfree,
ci.totalrebaterent,
ci.totalfixedrent,
ci.data,
ci.totaldiscdistributionamount,
ci.totalreplacementamount,
ci.pdcdate,
ci.totalbuybackfreeamount, 
ci.duedate
FROM (SELECT DISTINCT customercode FROM routesequence WHERE routecode = ",var_routeid," ) cm 
INNER JOIN customerinvoice ci ON ci.customercode = cm.customercode
INNER JOIN salesman sm ON sm.salesmancode = ci.salesmancode
WHERE ci.transactiontype = 2  AND ci.voidflag = 0   AND ci.duedate IS NOT NULL ");
	PREPARE s2 FROM @dyn_sql2;
	EXECUTE s2;  
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_syncicsdata_customers` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_syncicsdata_customers` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_syncicsdata_customers`(
  IN var_userid INT,
  IN var_deviceid VARCHAR (255),
  IN var_routeid INT,
  IN var_checkmdate INT
)
BEGIN
  DECLARE var_syncdate DATETIME ;
  DECLARE var_where1 VARCHAR (250) ;
  DECLARE var_where2 VARCHAR (250) ;
  DECLARE var_where3 VARCHAR (250) ;
  DECLARE var_where4 VARCHAR (250) ;
  DECLARE var_where5 VARCHAR (250) ;
  DECLARE var_msl VARCHAR (10) ;
  DECLARE var_tempflag INT ;
  DECLARE var_plan INT ;
  DECLARE var_sequence INT ;
  DECLARE var_day INT ;
  DECLARE var_week INT ;
  SET var_where1 = "" ;
  SET var_where2 = "" ;
  SET var_where3 = "" ;
  SET var_where4 = "" ;
  SET var_where5 = "" ;
  SET var_checkmdate = 0 ;
  IF var_checkmdate = 1 
  THEN 
  SELECT 
    syncdate INTO var_syncdate 
  FROM
    tbl_syncservice 
  WHERE userid = var_userid 
    AND deviceid = var_deviceid ;
  IF var_syncdate != '' 
  THEN SET var_where1 = CONCAT(
    " AND mdat > '",
    var_syncdate,
    "' "
  ) ;
  SET var_where2 = CONCAT(
    " AND mdat > '",
    var_syncdate,
    "' "
  ) ;
  SET var_where3 = CONCAT(
    " AND salescalender.mdat > '",
    var_syncdate,
    "' "
  ) ;
  SET var_where4 = CONCAT(
    " AND routesequence.mdat > '",
    var_syncdate,
    "' "
  ) ;
  SET var_where5 = CONCAT(
    " AND customerinvoice.mdat > '",
    var_syncdate,
    "' "
  ) ;
  END IF ;
  END IF ;
  SET @TEMPTABLE = CONCAT("temp_sequence_", var_routeid) ;
  SET @tempseqtable = CONCAT(
    "DROP TABLE IF EXISTS ",
    @TEMPTABLE
  ) ;
  PREPARE qry3 FROM @tempseqtable ;
  EXECUTE qry3 ;
  SELECT 
    journeyplanflag INTO var_plan 
  FROM
    setup ;
  SELECT 
    routesequenceplanflag INTO var_sequence 
  FROM
    setup ;
  SELECT 
    DAYOFWEEK(CURRENT_DATE()) INTO var_day ;
  IF var_sequence = '1' 
  THEN 
  SELECT 
    9 INTO var_week ;
  ELSE 
  SELECT 
    rp32weeknumber INTO var_week 
  FROM
    salescalender 
  WHERE CURRENT_DATE() BETWEEN weekstartdate 
    AND weekenddate ;
  END IF ;
  IF var_plan = '2' 
  THEN SET @tempseqtable = CONCAT(
    "CREATE TEMPORARY TABLE IF NOT EXISTS ",
    @TEMPTABLE,
    " AS SELECT DISTINCT customercode FROM routesequence WHERE routecode = ",
    var_routeid
  ) ;
  ELSE 
  /*sujee removed " AND rp32weeknumber = ", var_week to download all customer  08/02/2021  as per sandeep request*/
  IF var_day = '1' 
  THEN SET @tempseqtable = CONCAT(
    "CREATE TEMPORARY TABLE IF NOT EXISTS ",
    @TEMPTABLE,
    " AS SELECT DISTINCT customercode FROM routesequence WHERE callrestrictiondays7 = 1 AND routecode = ",
    var_routeid
  ) ;
  ELSEIF var_day = '2' 
  THEN SET @tempseqtable = CONCAT(
    "CREATE TEMPORARY TABLE IF NOT EXISTS ",
    @TEMPTABLE,
    " AS SELECT DISTINCT customercode FROM routesequence WHERE callrestrictiondays1 = 1 AND routecode = ",
    var_routeid
  ) ;
  ELSEIF var_day = '3' 
  THEN SET @tempseqtable = CONCAT(
    "CREATE TEMPORARY TABLE IF NOT EXISTS ",
    @TEMPTABLE,
    " AS SELECT DISTINCT customercode FROM routesequence WHERE callrestrictiondays2 = 1 AND routecode = ",
    var_routeid
  ) ;
  ELSEIF var_day = '4' 
  THEN SET @tempseqtable = CONCAT(
    "CREATE TEMPORARY TABLE IF NOT EXISTS ",
    @TEMPTABLE,
    " AS SELECT DISTINCT customercode FROM routesequence WHERE callrestrictiondays3 = 1 AND routecode = ",
    var_routeid
  ) ;
  ELSEIF var_day = '5' 
  THEN SET @tempseqtable = CONCAT(
    "CREATE TEMPORARY TABLE IF NOT EXISTS ",
    @TEMPTABLE,
    " AS SELECT DISTINCT customercode FROM routesequence WHERE callrestrictiondays4 = 1 AND routecode = ",
    var_routeid
  ) ;
  ELSEIF var_day = '6' 
  THEN SET @tempseqtable = CONCAT(
    "CREATE TEMPORARY TABLE IF NOT EXISTS ",
    @TEMPTABLE,
    " AS SELECT DISTINCT customercode FROM routesequence WHERE callrestrictiondays5 = 1 AND routecode = ",
    var_routeid
  ) ;
  ELSE SET @tempseqtable = CONCAT(
    "CREATE TEMPORARY TABLE IF NOT EXISTS ",
    @TEMPTABLE,
    " AS SELECT DISTINCT customercode FROM routesequence WHERE callrestrictiondays6 = 1 AND routecode = ",
    var_routeid
  ) ;
  END IF ;
  END IF ;
  PREPARE qry4 FROM @tempseqtable ;
  EXECUTE qry4 ;
  SET @division = 0 ;
  SELECT 
    COALESCE(division, 0) INTO @division 
  FROM
    routemaster 
  WHERE routecode = var_routeid ;
  SELECT 
    COALESCE(itemmustkey, 0) INTO var_msl 
  FROM
    routemaster 
  WHERE routecode = var_routeid ;
  SET @dyn_sql1 = CONCAT(
    "
			SELECT cm.customercode,cm.type,cm.headofficecode,cm.routecode,cm.streetcode,cm.districtcode,cm.locationcode,cm.customersequence,
				REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(cm.customername,' ',''),'É',''),',','.'),'–','.'),'''','')customername,
				 REPLACE(REPLACE(REPLACE(REPLACE(cm.customeraddress1,' ',''),'É','')
,'–','.'),'Â','') customeraddress1,
				REPLACE(REPLACE(REPLACE(cm.customeraddress2,' ',''),'É',''),'–','.') customeraddress2,
				REPLACE(REPLACE(cm.customerphone,' ',''),'É','') customerphone,
				cm.balance,cm.channelcode,cm.customercategory,
				cm.pricingkey,cm.promotionkey,cm.authorizeditemgrpkey,cm.messagekey1,cm.messagekey2,cm.invoicepaymentterms,cm.invoiceretailoption,cm.invoicepriceoverride,cm.invoiceretailoverride,cm.invoiceformatoption,cm.invoiceextensionopt,cm.invoicedsdpromptopt,cm.invoicecopies,
				cm.salesinputoprion,cm.returnsinputoption,cm.invoiceinputstyle,cm.onhandspromptopt,cm.inventoryselectopt,cm.invencontaineropt,cm.queuedreportoption,cm.surveykey, 
				CASE WHEN COALESCE(cm.itemmustkey,0) > 0 THEN cm.itemmustkey ELSE ",
    var_msl,
    " END itemmustkey,
				REPLACE(REPLACE(cm.contactname,' ',''),'É','') contactname,
				cm.customertype,cm.callfrequency,cm.routenumber,cm.arbcustomernameshort,
				REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(cm.arbcustomername,' ',''),'É',''),',','.'),'–','.'),'''','') arbcustomername,
				REPLACE(REPLACE(REPLACE(cm.arbcustomeraddress1,' ',''),'É',''),'Â','') arbcustomeraddress1,
				REPLACE(REPLACE(cm.arbcustomeraddress2,' ',''),'É','') arbcustomeraddress2,
				cm.hhccustomernameshort,cm.hhccustomername,cm.hhccustomeraddress1,cm.hhccustomeraddress2,
				cm.allowbeyondlimit,cm.tclimit,cm.activecustomer,
				CASE WHEN cm.invoicepaymentterms = 2 THEN cm.creditlimitdays ELSE 0 END creditlimitdays,
				cm.created,cm.cdat,cm.modified,cm.mdat,cm.forcehand,cm.renteddisplay,cm.installedchiller,cm.monthlydepreciation,cm.typeofgiveaway,cm.giveawayflag,cm.lastvisiteddate,'' memo1,cm.memo2,
				cm.tcsubtype,cm.rentperc,cm.customeraddress3,cm.customercity,cm.customerstate,cm.customerzip,cm.authorizeditemlistctl,cm.invoicepriceprint,cm.messagekey3,cm.messagekey4,cm.messagekey5,cm.messagekey6,cm.orderformat,cm.enableupcprint,cm.enabledelayprint,
				cm.printsequence,cm.enablepriceeditinvs,cm.enablesellprevious,cm.enablesuggestsales,cm.enableautofillreturns,cm.enableautofilldamaged,cm.enablesigcapture,cm.enablereturnstrxn,cm.enableexchangetrxn,cm.enabledamagedreturns,
				CASE WHEN cm.invoicepaymentterms > 1 THEN cm.enablearcollection ELSE 0 END enablearcollection,
				cm.enablesurveyaudit,cm.enabledelivinstruct,
				cm.enableinvoicecomment,cm.invoicedetailentry,cm.orderdetailentry,cm.forcestockcapture,
				cm.enablepromotrxn,
				cm.alternatecode,
				CASE WHEN cm.invoicepaymentterms = 2 THEN cm.creditlimit ELSE 0 END creditlimit,
				cm.allowcashoncreditexceed,cm.arbcustomeraddress3,cm.templateindicator,cm.templatename,
				cm.arbcontactname,cm.printlanguageflag,cm.quantumno,cm.lostplacementdelivs,cm.newplacementdelivs,cm.currencycode,cm.histmaxdeliveries,cm.arcustomertype,cm.custtaxkey1,cm.custtaxkey2,cm.custtaxkey3,cm.customertaxid,cm.customertaxidoptions,cm.outletsubtype,cm.volume,cm.enablegovtaxnote,
				cm.forwardcoverfactor,cm.enablepromoeditinvs,cm.enableaddlpromoinvs,cm.badcreditcustomer,cm.enableduplicateprinting,cm.numoutstandinginv,cm.enablefocprinting,cm.promooptions,cm.groupcode,cm.forceposcheck,cm.ancustomercode,cm.printoutletitemcode,cm.reportprintcontrol,cm.invoicelimiter,
				cm.exclusiveopmode,cm.returnpromotionkey,cm.invoiceformat,cm.liquorlicprint,cm.enablepromoeditords,cm.enableaddlpromoords,cm.enableaddlpromoinvoices,cm.enableposequipment,cm.enablesalestrxn,cm.enableadvancepayment,cm.printcheckdetails,
				COALESCE(dc.discount,0) tcspecialdiscount,
				cm.spldiscountdays,cm.arabiccustomercity,
				cm.threshholdlimit,cm.discountkey,cm.enforcepromotion,cm.gpcustcode,cm.cashonlypromo,cm.roundnetamount,cm.roundingoffvalue,cm.partialcollection,cm.transactiontype,cm.enabledraftcopy,cm.enablebuybackfree,cm.enablecpd,cm.enablepaymentsel,cm.gpsdata,cm.fixedlatitude,cm.fixedlongitude,cm.rentkey,
				cm.startdate,cm.enddate,cm.definitionvalue,cm.runningvalue,cm.rentcontrol,cm.disablebalanceupdate,cm.enablecreditlimit,cm.autosettlecollection,cm.enableinvoicecopy,cm.pobox,cm.shoptelephonenumber,cm.shopfaxnumber,cm.ownername,cm.ownerlandlinenumber,cm.ownermobilenumber,cm.contactpersonlandlinenumber,
				cm.contactpersonmobilenumber,cm.contactpersonemail,cm.purchasemanagername,cm.purchasemanagerlandlinenumber,cm.purchasemanagermobilenumber,cm.purchasemanageremail,cm.warehousemanagername,cm.warehousemanagerlandlinenumber,cm.warehousemanagermobilenumber,cm.warehousemanageremail,
				cm.expirylimit,cm.exprunningvalue,cm.distributionkey,cm.gpssavecount,cm.graceperiod,cm.reportcustcode,cm.enablerental,cm.enableautofillsales,cm.enablebatchselection,
				cm.barcode,cm.gracelimit,ifnull(visualcode,0) as visualcode,ifnull(distribution_check_id,0) as distribution_check_id,0 as splitfree, cm.enablereturnpassword, cm.statementdays,cm.itemmapkey,cm.enforcemsl,cm.custemail,cm.applytax,cm.traname,cm.tranamearabic,cm.taxregistrationnumber,cm.anpflag,cm.CreditTerms,cm.taxcardno,cm.crno, 
				ifnull(CASE WHEN cm.nrp_flag = 'Y' THEN 0 ELSE 1 END,1) as nrp_flag, cm.saleslimitflag,cm.minsaleslimit,cm.maxsaleslimit, 
				ifnull(invpromoyn,0) invpromoyn, ifnull(invpromoplan,0) invpromoplan, 
				ifnull(combopromoyn,0) combopromoyn, ifnull(combopromoplan,0) combopromoplan,
				ifnull(rebateprintyn,0) rebateprintyn,
				CASE
					WHEN COALESCE(cm.customerfacetime, 0) = 0 THEN
					    COALESCE(
						(
						    SELECT ifnull(ccm.cft,0) as cft
						    FROM customerclustermapping AS ccm
						    WHERE ccm.`channel` = cm.channel
						      AND ccm.divisioncode = cm.divisioncode
						),
						0
					    )
						ELSE cm.customerfacetime
					END AS customerfacetime,
					COALESCE(cm.enableautocheckout, 0) AS enableautocheckout,
					COALESCE(cm.autocheckoutradius, 0) AS autocheckoutradius 
			FROM ",
    @TEMPTABLE,
    " cmt
			INNER JOIN customermaster cm ON cm.customercode = cmt.customercode 
			LEFT OUTER JOIN customerdiscountcap dc ON dc.customercode = cmt.customercode AND dc.divison = '",
    @division,
    "' 
			WHERE cm.type <= 3 AND cm.activecustomer = 1
			
				UNION 
				
			SELECT cm.customercode,cm.type,cm.headofficecode,cm.routecode,cm.streetcode,cm.districtcode,cm.locationcode,cm.customersequence,cm.customername,cm.customeraddress1,cm.customeraddress2,cm.customerphone,cm.balance,cm.channelcode,cm.customercategory,
				cm.pricingkey,cm.promotionkey,cm.authorizeditemgrpkey,cm.messagekey1,cm.messagekey2,cm.invoicepaymentterms,cm.invoiceretailoption,cm.invoicepriceoverride,cm.invoiceretailoverride,cm.invoiceformatoption,cm.invoiceextensionopt,cm.invoicedsdpromptopt,cm.invoicecopies,
				cm.salesinputoprion,cm.returnsinputoption,cm.invoiceinputstyle,cm.onhandspromptopt,cm.inventoryselectopt,cm.invencontaineropt,cm.queuedreportoption,cm.surveykey,cm.itemmustkey,cm.contactname,cm.customertype,cm.callfrequency,cm.routenumber,cm.arbcustomernameshort,
				cm.arbcustomername,cm.arbcustomeraddress1,cm.arbcustomeraddress2,cm.hhccustomernameshort,cm.hhccustomername,cm.hhccustomeraddress1,cm.hhccustomeraddress2,cm.allowbeyondlimit,cm.tclimit,cm.activecustomer,
				CASE WHEN cm.invoicepaymentterms = 2 THEN cm.creditlimitdays ELSE 0 END creditlimitdays,
				cm.created,cm.cdat,cm.modified,cm.mdat,cm.forcehand,cm.renteddisplay,cm.installedchiller,cm.monthlydepreciation,cm.typeofgiveaway,cm.giveawayflag,cm.lastvisiteddate,cm.memo1,cm.memo2,
				cm.tcsubtype,cm.rentperc,cm.customeraddress3,cm.customercity,cm.customerstate,cm.customerzip,cm.authorizeditemlistctl,cm.invoicepriceprint,cm.messagekey3,cm.messagekey4,cm.messagekey5,cm.messagekey6,cm.orderformat,cm.enableupcprint,cm.enabledelayprint,
				cm.printsequence,cm.enablepriceeditinvs,cm.enablesellprevious,cm.enablesuggestsales,cm.enableautofillreturns,cm.enableautofilldamaged,cm.enablesigcapture,cm.enablereturnstrxn,cm.enableexchangetrxn,cm.enabledamagedreturns,
				CASE WHEN cm.invoicepaymentterms > 1 THEN cm.enablearcollection ELSE 0 END enablearcollection,
				cm.enablesurveyaudit,cm.enabledelivinstruct,
				cm.enableinvoicecomment,cm.invoicedetailentry,cm.orderdetailentry,cm.forcestockcapture,cm.enablepromotrxn,ABS(cm.alternatecode) alternatecode,
				CASE WHEN cm.invoicepaymentterms = 2 THEN cm.creditlimit ELSE 0 END creditlimit,
				cm.allowcashoncreditexceed,cm.arbcustomeraddress3,cm.templateindicator,cm.templatename,
				cm.arbcontactname,cm.printlanguageflag,cm.quantumno,cm.lostplacementdelivs,cm.newplacementdelivs,cm.currencycode,cm.histmaxdeliveries,cm.arcustomertype,cm.custtaxkey1,cm.custtaxkey2,cm.custtaxkey3,cm.customertaxid,cm.customertaxidoptions,cm.outletsubtype,cm.volume,cm.enablegovtaxnote,
				cm.forwardcoverfactor,cm.enablepromoeditinvs,cm.enableaddlpromoinvs,cm.badcreditcustomer,cm.enableduplicateprinting,cm.numoutstandinginv,cm.enablefocprinting,cm.promooptions,cm.groupcode,cm.forceposcheck,cm.ancustomercode,cm.printoutletitemcode,cm.reportprintcontrol,cm.invoicelimiter,
				cm.exclusiveopmode,cm.returnpromotionkey,cm.invoiceformat,cm.liquorlicprint,cm.enablepromoeditords,cm.enableaddlpromoords,cm.enableaddlpromoinvoices,cm.enableposequipment,cm.enablesalestrxn,cm.enableadvancepayment,cm.printcheckdetails,cm.tcspecialdiscount,cm.spldiscountdays,cm.arabiccustomercity,
				cm.threshholdlimit,cm.discountkey,cm.enforcepromotion,cm.gpcustcode,cm.cashonlypromo,cm.roundnetamount,cm.roundingoffvalue,cm.partialcollection,cm.transactiontype,cm.enabledraftcopy,cm.enablebuybackfree,cm.enablecpd,cm.enablepaymentsel,cm.gpsdata,cm.fixedlatitude,cm.fixedlongitude,cm.rentkey,
				cm.startdate,cm.enddate,cm.definitionvalue,cm.runningvalue,cm.rentcontrol,cm.disablebalanceupdate,cm.enablecreditlimit,cm.autosettlecollection,cm.enableinvoicecopy,cm.pobox,cm.shoptelephonenumber,cm.shopfaxnumber,cm.ownername,cm.ownerlandlinenumber,cm.ownermobilenumber,cm.contactpersonlandlinenumber,
				cm.contactpersonmobilenumber,cm.contactpersonemail,cm.purchasemanagername,cm.purchasemanagerlandlinenumber,cm.purchasemanagermobilenumber,cm.purchasemanageremail,cm.warehousemanagername,cm.warehousemanagerlandlinenumber,cm.warehousemanagermobilenumber,cm.warehousemanageremail,
				cm.expirylimit,cm.exprunningvalue,cm.distributionkey,cm.gpssavecount,cm.graceperiod,cm.reportcustcode,cm.enablerental,cm.enableautofillsales,cm.enablebatchselection,
				cm.barcode,cm.gracelimit,ifnull(visualcode,0) as visualcode,ifnull(distribution_check_id,0) as distribution_check_id,0 as splitfree, cm.enablereturnpassword, cm.statementdays,cm.itemmapkey,cm.enforcemsl,cm.custemail,cm.applytax,cm.traname,cm.tranamearabic,cm.taxregistrationnumber,cm.anpflag,cm.CreditTerms,cm.taxcardno,cm.crno,
				ifnull(CASE WHEN cm.nrp_flag = 'Y' THEN 0 ELSE 1 END,1) as nrp_flag, cm.saleslimitflag,cm.minsaleslimit,cm.maxsaleslimit, 
				ifnull(invpromoyn,0) invpromoyn, ifnull(invpromoplan,0) invpromoplan, 
				ifnull(combopromoyn,0) combopromoyn, ifnull(combopromoplan,0) combopromoplan,
				ifnull(rebateprintyn,0) rebateprintyn,
				CASE
					WHEN COALESCE(cm.customerfacetime, 0) = 0 THEN
					    COALESCE(
						(
						    SELECT ifnull(ccm.cft,0) as cft
						    FROM customerclustermapping AS ccm
						    WHERE ccm.`channel` = cm.channel
						      AND ccm.divisioncode = cm.divisioncode
						),
						0
					    )
						ELSE cm.customerfacetime
					END AS customerfacetime,
					COALESCE(cm.enableautocheckout, 0) AS enableautocheckout,
					COALESCE(cm.autocheckoutradius, 0) AS autocheckoutradius 
			FROM customermaster cm
			WHERE cm.templateindicator = 1 AND cm.activecustomer = 1 ",
    var_where1
  ) ;
  PREPARE s1 FROM @dyn_sql1 ;
  EXECUTE s1 ;
  SET @dyn_sql3 = CONCAT(
    "
				SELECT sc.salesyear,sc.weeknumber,sc.weekstartdate,sc.weekenddate,sc.rp32weeknumber,sc.salesperiod
				FROM salescalender sc
				WHERE sc.salesyear = YEAR(CURRENT_DATE())"
  ) ;
  PREPARE s3 FROM @dyn_sql3 ;
  EXECUTE s3 ;
  SET @dyn_sql4 = CONCAT(
    "
				SELECT rs.rp32weeknumber,rs.routecode,rs.customercode,
					rs.callrestrictiondays1,rs.callrestrictiondays2,rs.callrestrictiondays3,rs.callrestrictiondays4,rs.callrestrictiondays5,rs.callrestrictiondays6,rs.callrestrictiondays7,
					rs.monseq,rs.tueseq,rs.wedseq,rs.thuseq,rs.friseq,rs.satseq,rs.sunseq
				FROM ",
    @TEMPTABLE,
    " cm 
						INNER JOIN routesequence rs ON rs.customercode = cm.customercode
				WHERE rs.rp32weeknumber=",
    var_week,
    " AND rs.routecode = ",
    var_routeid,
    " ",
    var_where4
  ) ;
  PREPARE s4 FROM @dyn_sql4 ;
  EXECUTE s4 ;
  SELECT 
    `status` INTO var_tempflag 
  FROM
    controlpanel 
  WHERE flagid = 51 ;
  SET @dyn_sql5 = CONCAT(
    "DELETE FROM ",
    @TEMPTABLE,
    " WHERE customercode IN (SELECT customercode FROM customermaster WHERE invoicepaymentterms > 1 and enablearcollection = 0)"
  ) ;
  PREPARE s5 FROM @dyn_sql5 ;
  EXECUTE s5 ;
  IF var_tempflag = '1' 
  THEN SET @dyn_sql5 = CONCAT(
    "
					SELECT ci.transactionkey,ci.transactiontype,ci.documentnumber,ci.invoicenumber,ci.transactiondate,ci.transactiontime,ci.customercode,",
    var_routeid,
    " routecode,ci.salesmancode,
						ci.totalinvoiceamount,ci.totalsalesamount,ci.totalreturnamount,ci.totaldamagedamount,ci.totalfreesampleamount,ci.immediatepaid,ci.amountpaid,ci.dnamountpaid,ci.cnamountpaid,
						ci.invoicebalance,ci.paymenttype,ci.voidflag,ci.paymentstatus,ci.hhcinvoicenumber, sm.alternatesalesmancode remarks1,'' remarks2,ci.routestartdate,ci.erpreferencenumber,ci.mdat,ci.totalpromoamount,
						ci.gcpaymenttype,ci.totaltaxesamount,ci.itemlinetaxamount,ci.totaldiscountamount,ci.pdcindicator,ci.chequecollection,ci.totalexpiryamount,ci.currencycode,ci.pdcbalance,
						ci.totalmanualfree,ci.totallimitedfree,ci.totalrebaterent,ci.totalfixedrent,ci.data,ci.totaldiscdistributionamount,ci.totalreplacementamount,ci.pdcdate,ci.totalbuybackfreeamount, 
						ci.duedate
					FROM ",
    @TEMPTABLE,
    " cm 
						INNER JOIN customerinvoice ci ON ci.customercode = cm.customercode
						INNER JOIN salesman sm ON sm.salesmancode = ci.salesmancode
					WHERE ci.transactiontype = 2  AND ci.voidflag = 0   AND ci.duedate IS NOT NULL ",
    var_where5
  ) ;
  ELSE SET @dyn_sql5 = CONCAT(
    "
					SELECT ci.transactionkey,ci.transactiontype,ci.documentnumber,ci.invoicenumber,ci.transactiondate,ci.transactiontime,ci.customercode,",
    var_routeid,
    " routecode,ci.salesmancode,
						ci.totalinvoiceamount,ci.totalsalesamount,ci.totalreturnamount,ci.totaldamagedamount,ci.totalfreesampleamount,ci.immediatepaid,ci.amountpaid,ci.dnamountpaid,ci.cnamountpaid,
						ci.invoicebalance,ci.paymenttype,ci.voidflag,ci.paymentstatus,ci.hhcinvoicenumber, sm.alternatesalesmancode remarks1,'' remarks2,ci.routestartdate,ci.erpreferencenumber,ci.mdat,ci.totalpromoamount,
						ci.gcpaymenttype,ci.totaltaxesamount,ci.itemlinetaxamount,ci.totaldiscountamount,ci.pdcindicator,ci.chequecollection,ci.totalexpiryamount,ci.currencycode,ci.pdcbalance,
						ci.totalmanualfree,ci.totallimitedfree,ci.totalrebaterent,ci.totalfixedrent,ci.data,ci.totaldiscdistributionamount,ci.totalreplacementamount,ci.pdcdate,ci.totalbuybackfreeamount, 
						ci.duedate
					FROM ",
    @TEMPTABLE,
    " cm 
						INNER JOIN customerinvoice ci ON ci.customercode = cm.customercode
					WHERE ci.transactiontype = 2   AND ci.voidflag = 0 AND ci.duedate IS NOT NULL AND ci.routecode = ",
    var_routeid,
    " ",
    var_where5
  ) ;
  END IF ;
  PREPARE s5 FROM @dyn_sql5 ;
  EXECUTE s5 ;
  SET @tempseqtable = CONCAT(
    "DROP TABLE IF EXISTS ",
    @TEMPTABLE
  ) ;
  PREPARE qry5 FROM @tempseqtable ;
  EXECUTE qry5 ;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_syncicsdata_customers1` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_syncicsdata_customers1` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_syncicsdata_customers1`(
	IN var_userid INT,
	IN var_deviceid VARCHAR(255),
	IN var_routeid INT,
	IN var_checkmdate INT
)
BEGIN 
 
	DECLARE var_syncdate DATETIME;	
	DECLARE var_where1 VARCHAR(250);
	DECLARE var_where2 VARCHAR(250);
	DECLARE var_where3 VARCHAR(250);
	DECLARE var_where4 VARCHAR(250);
	DECLARE var_where5 VARCHAR(250);
	
	DECLARE var_msl VARCHAR(10);
	DECLARE var_tempflag INT;
	DECLARE var_plan INT;
	DECLARE var_sequence INT;
	DECLARE var_day INT;
	DECLARE var_week INT;
	
	SET var_where1 = "";
	SET var_where2 = "";
	SET var_where3 = "";
	SET var_where4 = "";
	SET var_where5 = "";
	
	SET var_checkmdate = 0 ;
	
	IF var_checkmdate = 1 THEN
		
		SELECT syncdate INTO var_syncdate FROM tbl_syncservice WHERE userid = var_userid AND deviceid = var_deviceid;
		
		IF var_syncdate != '' THEN
			
			SET var_where1 = CONCAT(" AND mdat > '",var_syncdate,"' ");
			SET var_where2 = CONCAT(" AND mdat > '",var_syncdate,"' ");
			SET var_where3 = CONCAT(" AND salescalender.mdat > '",var_syncdate,"' ");
			SET var_where4 = CONCAT(" AND routesequence.mdat > '",var_syncdate,"' ");
			SET var_where5 = CONCAT(" AND customerinvoice.mdat > '",var_syncdate,"' ");
		END IF;
	END IF;
	
	SET @TEMPTABLE = CONCAT("temp_sequence_",var_routeid);
	
	SET @tempseqtable = CONCAT("DROP TABLE IF EXISTS ",@TEMPTABLE);
	PREPARE qry3 FROM @tempseqtable;
	EXECUTE qry3;
	
	SELECT journeyplanflag INTO var_plan FROM setup;											
	SELECT routesequenceplanflag INTO var_sequence FROM setup;				
	SELECT DAYOFWEEK(CURRENT_DATE()) INTO var_day;									
	
	IF  var_sequence = '1' THEN
		SELECT 9 INTO var_week;	
	ELSE
		SELECT rp32weeknumber INTO var_week FROM salescalender WHERE CURRENT_DATE() BETWEEN weekstartdate AND weekenddate;	
	END IF;
	IF  var_plan = '2' THEN
		SET @tempseqtable =  CONCAT("CREATE TEMPORARY TABLE IF NOT EXISTS ",@TEMPTABLE, " AS SELECT DISTINCT customercode FROM routesequence WHERE routecode = ",var_routeid, " AND rp32weeknumber = ", var_week);
	ELSE
		IF var_day = '1' THEN
			SET @tempseqtable =  CONCAT("CREATE TEMPORARY TABLE IF NOT EXISTS ",@TEMPTABLE, " AS SELECT DISTINCT customercode FROM routesequence WHERE callrestrictiondays7 = 1 AND routecode = ",var_routeid, " AND rp32weeknumber = ", var_week);
		ELSEIF var_day = '2' THEN
			SET @tempseqtable =  CONCAT("CREATE TEMPORARY TABLE IF NOT EXISTS ",@TEMPTABLE, " AS SELECT DISTINCT customercode FROM routesequence WHERE callrestrictiondays1 = 1 AND routecode = ",var_routeid, " AND rp32weeknumber = ", var_week);		
		ELSEIF var_day = '3' THEN
			SET @tempseqtable =  CONCAT("CREATE TEMPORARY TABLE IF NOT EXISTS ",@TEMPTABLE, " AS SELECT DISTINCT customercode FROM routesequence WHERE callrestrictiondays2 = 1 AND routecode = ",var_routeid, " AND rp32weeknumber = ", var_week);		
		ELSEIF var_day = '4' THEN
			SET @tempseqtable =  CONCAT("CREATE TEMPORARY TABLE IF NOT EXISTS ",@TEMPTABLE, " AS SELECT DISTINCT customercode FROM routesequence WHERE callrestrictiondays3 = 1 AND routecode = ",var_routeid, " AND rp32weeknumber = ", var_week);		
		ELSEIF var_day = '5' THEN
			SET @tempseqtable =  CONCAT("CREATE TEMPORARY TABLE IF NOT EXISTS ",@TEMPTABLE, " AS SELECT DISTINCT customercode FROM routesequence WHERE callrestrictiondays4 = 1 AND routecode = ",var_routeid, " AND rp32weeknumber = ", var_week);		
		ELSEIF var_day = '6' THEN
			SET @tempseqtable =  CONCAT("CREATE TEMPORARY TABLE IF NOT EXISTS ",@TEMPTABLE, " AS SELECT DISTINCT customercode FROM routesequence WHERE callrestrictiondays5 = 1 AND routecode = ",var_routeid, " AND rp32weeknumber = ", var_week);		
		ELSE
			SET @tempseqtable =  CONCAT("CREATE TEMPORARY TABLE IF NOT EXISTS ",@TEMPTABLE, " AS SELECT DISTINCT customercode FROM routesequence WHERE callrestrictiondays6 = 1 AND routecode = ",var_routeid, " AND rp32weeknumber = ", var_week);		
		END IF;
	END IF;
	PREPARE qry4 FROM @tempseqtable;
	
	EXECUTE qry4;	
	
	SET @division = 0;
	SELECT COALESCE(division, 0) INTO @division FROM routemaster WHERE routecode = var_routeid;
	
	
	
	SELECT COALESCE(itemmustkey,0) INTO var_msl FROM routemaster WHERE routecode = var_routeid;
	
	SET @dyn_sql1 = CONCAT("
			SELECT cm.customercode,cm.type,cm.headofficecode,cm.routecode,cm.streetcode,cm.districtcode,cm.locationcode,cm.customersequence,
				REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(cm.customername,' ',''),'É',''),',','.'),'–','.'),'''','')customername,
				 REPLACE(REPLACE(REPLACE(REPLACE(cm.customeraddress1,' ',''),'É','')
,'–','.'),'Â','') customeraddress1,
				REPLACE(REPLACE(REPLACE(cm.customeraddress2,' ',''),'É',''),'–','.') customeraddress2,
				REPLACE(REPLACE(cm.customerphone,' ',''),'É','') customerphone,
				cm.balance,cm.channelcode,cm.customercategory,
				cm.pricingkey,cm.promotionkey,cm.authorizeditemgrpkey,cm.messagekey1,cm.messagekey2,cm.invoicepaymentterms,cm.invoiceretailoption,cm.invoicepriceoverride,cm.invoiceretailoverride,cm.invoiceformatoption,cm.invoiceextensionopt,cm.invoicedsdpromptopt,cm.invoicecopies,
				cm.salesinputoprion,cm.returnsinputoption,cm.invoiceinputstyle,cm.onhandspromptopt,cm.inventoryselectopt,cm.invencontaineropt,cm.queuedreportoption,cm.surveykey, 
				CASE WHEN COALESCE(cm.itemmustkey,0) > 0 THEN cm.itemmustkey ELSE ", var_msl , " END itemmustkey,
				REPLACE(REPLACE(cm.contactname,' ',''),'É','') contactname,
				cm.customertype,cm.callfrequency,cm.routenumber,cm.arbcustomernameshort,
				REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(cm.arbcustomername,' ',''),'É',''),',','.'),'–','.'),'''','') arbcustomername,
				REPLACE(REPLACE(REPLACE(cm.arbcustomeraddress1,' ',''),'É',''),'Â','') arbcustomeraddress1,
				REPLACE(REPLACE(cm.arbcustomeraddress2,' ',''),'É','') arbcustomeraddress2,
				cm.hhccustomernameshort,cm.hhccustomername,cm.hhccustomeraddress1,cm.hhccustomeraddress2,
				cm.allowbeyondlimit,cm.tclimit,cm.activecustomer,
				CASE WHEN cm.invoicepaymentterms = 2 THEN cm.creditlimitdays ELSE 0 END creditlimitdays,
				cm.created,cm.cdat,cm.modified,cm.mdat,cm.forcehand,cm.renteddisplay,cm.installedchiller,cm.monthlydepreciation,cm.typeofgiveaway,cm.giveawayflag,cm.lastvisiteddate,'' memo1,cm.memo2,
				cm.tcsubtype,cm.rentperc,cm.customeraddress3,cm.customercity,cm.customerstate,cm.customerzip,cm.authorizeditemlistctl,cm.invoicepriceprint,cm.messagekey3,cm.messagekey4,cm.messagekey5,cm.messagekey6,cm.orderformat,cm.enableupcprint,cm.enabledelayprint,
				cm.printsequence,cm.enablepriceeditinvs,cm.enablesellprevious,cm.enablesuggestsales,cm.enableautofillreturns,cm.enableautofilldamaged,cm.enablesigcapture,cm.enablereturnstrxn,cm.enableexchangetrxn,cm.enabledamagedreturns,
				CASE WHEN cm.invoicepaymentterms > 1 THEN cm.enablearcollection ELSE 0 END enablearcollection,
				cm.enablesurveyaudit,cm.enabledelivinstruct,
				cm.enableinvoicecomment,cm.invoicedetailentry,cm.orderdetailentry,cm.forcestockcapture,
				cm.enablepromotrxn,
				cm.alternatecode,
				CASE WHEN cm.invoicepaymentterms = 2 THEN cm.creditlimit ELSE 0 END creditlimit,
				cm.allowcashoncreditexceed,cm.arbcustomeraddress3,cm.templateindicator,cm.templatename,
				cm.arbcontactname,cm.printlanguageflag,cm.quantumno,cm.lostplacementdelivs,cm.newplacementdelivs,cm.currencycode,cm.histmaxdeliveries,cm.arcustomertype,cm.custtaxkey1,cm.custtaxkey2,cm.custtaxkey3,cm.customertaxid,cm.customertaxidoptions,cm.outletsubtype,cm.volume,cm.enablegovtaxnote,
				cm.forwardcoverfactor,cm.enablepromoeditinvs,cm.enableaddlpromoinvs,cm.badcreditcustomer,cm.enableduplicateprinting,cm.numoutstandinginv,cm.enablefocprinting,cm.promooptions,cm.groupcode,cm.forceposcheck,cm.ancustomercode,cm.printoutletitemcode,cm.reportprintcontrol,cm.invoicelimiter,
				cm.exclusiveopmode,cm.returnpromotionkey,cm.invoiceformat,cm.liquorlicprint,cm.enablepromoeditords,cm.enableaddlpromoords,cm.enableaddlpromoinvoices,cm.enableposequipment,cm.enablesalestrxn,cm.enableadvancepayment,cm.printcheckdetails,
				COALESCE(dc.discount,0) tcspecialdiscount,
				cm.spldiscountdays,cm.arabiccustomercity,
				cm.threshholdlimit,cm.discountkey,cm.enforcepromotion,cm.gpcustcode,cm.cashonlypromo,cm.roundnetamount,cm.roundingoffvalue,cm.partialcollection,cm.transactiontype,cm.enabledraftcopy,cm.enablebuybackfree,cm.enablecpd,cm.enablepaymentsel,cm.gpsdata,cm.fixedlatitude,cm.fixedlongitude,cm.rentkey,
				cm.startdate,cm.enddate,cm.definitionvalue,cm.runningvalue,cm.rentcontrol,cm.disablebalanceupdate,cm.enablecreditlimit,cm.autosettlecollection,cm.enableinvoicecopy,cm.pobox,cm.shoptelephonenumber,cm.shopfaxnumber,cm.ownername,cm.ownerlandlinenumber,cm.ownermobilenumber,cm.contactpersonlandlinenumber,
				cm.contactpersonmobilenumber,cm.contactpersonemail,cm.purchasemanagername,cm.purchasemanagerlandlinenumber,cm.purchasemanagermobilenumber,cm.purchasemanageremail,cm.warehousemanagername,cm.warehousemanagerlandlinenumber,cm.warehousemanagermobilenumber,cm.warehousemanageremail,
				cm.expirylimit,cm.exprunningvalue,cm.distributionkey,cm.gpssavecount,cm.graceperiod,cm.reportcustcode,cm.enablerental,cm.enableautofillsales,cm.enablebatchselection,
				cm.barcode,cm.gracelimit,ifnull(visualcode,0) as visualcode,ifnull(distribution_check_id,0) as distribution_check_id,0 as splitfree, cm.enablereturnpassword, cm.statementdays,cm.itemmapkey,cm.enforcemsl,cm.custemail
			FROM ",@TEMPTABLE, " cmt
			INNER JOIN customermaster cm ON cm.customercode = cmt.customercode 
			LEFT OUTER JOIN customerdiscountcap dc ON dc.customercode = cmt.customercode AND dc.divison = '", @division, "' 
			WHERE cm.type <= 3 AND cm.activecustomer = 1
			
				UNION 
				
			SELECT cm.customercode,cm.type,cm.headofficecode,cm.routecode,cm.streetcode,cm.districtcode,cm.locationcode,cm.customersequence,cm.customername,cm.customeraddress1,cm.customeraddress2,cm.customerphone,cm.balance,cm.channelcode,cm.customercategory,
				cm.pricingkey,cm.promotionkey,cm.authorizeditemgrpkey,cm.messagekey1,cm.messagekey2,cm.invoicepaymentterms,cm.invoiceretailoption,cm.invoicepriceoverride,cm.invoiceretailoverride,cm.invoiceformatoption,cm.invoiceextensionopt,cm.invoicedsdpromptopt,cm.invoicecopies,
				cm.salesinputoprion,cm.returnsinputoption,cm.invoiceinputstyle,cm.onhandspromptopt,cm.inventoryselectopt,cm.invencontaineropt,cm.queuedreportoption,cm.surveykey,cm.itemmustkey,cm.contactname,cm.customertype,cm.callfrequency,cm.routenumber,cm.arbcustomernameshort,
				cm.arbcustomername,cm.arbcustomeraddress1,cm.arbcustomeraddress2,cm.hhccustomernameshort,cm.hhccustomername,cm.hhccustomeraddress1,cm.hhccustomeraddress2,cm.allowbeyondlimit,cm.tclimit,cm.activecustomer,
				CASE WHEN cm.invoicepaymentterms = 2 THEN cm.creditlimitdays ELSE 0 END creditlimitdays,
				cm.created,cm.cdat,cm.modified,cm.mdat,cm.forcehand,cm.renteddisplay,cm.installedchiller,cm.monthlydepreciation,cm.typeofgiveaway,cm.giveawayflag,cm.lastvisiteddate,cm.memo1,cm.memo2,
				cm.tcsubtype,cm.rentperc,cm.customeraddress3,cm.customercity,cm.customerstate,cm.customerzip,cm.authorizeditemlistctl,cm.invoicepriceprint,cm.messagekey3,cm.messagekey4,cm.messagekey5,cm.messagekey6,cm.orderformat,cm.enableupcprint,cm.enabledelayprint,
				cm.printsequence,cm.enablepriceeditinvs,cm.enablesellprevious,cm.enablesuggestsales,cm.enableautofillreturns,cm.enableautofilldamaged,cm.enablesigcapture,cm.enablereturnstrxn,cm.enableexchangetrxn,cm.enabledamagedreturns,
				CASE WHEN cm.invoicepaymentterms > 1 THEN cm.enablearcollection ELSE 0 END enablearcollection,
				cm.enablesurveyaudit,cm.enabledelivinstruct,
				cm.enableinvoicecomment,cm.invoicedetailentry,cm.orderdetailentry,cm.forcestockcapture,cm.enablepromotrxn,ABS(cm.alternatecode) alternatecode,
				CASE WHEN cm.invoicepaymentterms = 2 THEN cm.creditlimit ELSE 0 END creditlimit,
				cm.allowcashoncreditexceed,cm.arbcustomeraddress3,cm.templateindicator,cm.templatename,
				cm.arbcontactname,cm.printlanguageflag,cm.quantumno,cm.lostplacementdelivs,cm.newplacementdelivs,cm.currencycode,cm.histmaxdeliveries,cm.arcustomertype,cm.custtaxkey1,cm.custtaxkey2,cm.custtaxkey3,cm.customertaxid,cm.customertaxidoptions,cm.outletsubtype,cm.volume,cm.enablegovtaxnote,
				cm.forwardcoverfactor,cm.enablepromoeditinvs,cm.enableaddlpromoinvs,cm.badcreditcustomer,cm.enableduplicateprinting,cm.numoutstandinginv,cm.enablefocprinting,cm.promooptions,cm.groupcode,cm.forceposcheck,cm.ancustomercode,cm.printoutletitemcode,cm.reportprintcontrol,cm.invoicelimiter,
				cm.exclusiveopmode,cm.returnpromotionkey,cm.invoiceformat,cm.liquorlicprint,cm.enablepromoeditords,cm.enableaddlpromoords,cm.enableaddlpromoinvoices,cm.enableposequipment,cm.enablesalestrxn,cm.enableadvancepayment,cm.printcheckdetails,cm.tcspecialdiscount,cm.spldiscountdays,cm.arabiccustomercity,
				cm.threshholdlimit,cm.discountkey,cm.enforcepromotion,cm.gpcustcode,cm.cashonlypromo,cm.roundnetamount,cm.roundingoffvalue,cm.partialcollection,cm.transactiontype,cm.enabledraftcopy,cm.enablebuybackfree,cm.enablecpd,cm.enablepaymentsel,cm.gpsdata,cm.fixedlatitude,cm.fixedlongitude,cm.rentkey,
				cm.startdate,cm.enddate,cm.definitionvalue,cm.runningvalue,cm.rentcontrol,cm.disablebalanceupdate,cm.enablecreditlimit,cm.autosettlecollection,cm.enableinvoicecopy,cm.pobox,cm.shoptelephonenumber,cm.shopfaxnumber,cm.ownername,cm.ownerlandlinenumber,cm.ownermobilenumber,cm.contactpersonlandlinenumber,
				cm.contactpersonmobilenumber,cm.contactpersonemail,cm.purchasemanagername,cm.purchasemanagerlandlinenumber,cm.purchasemanagermobilenumber,cm.purchasemanageremail,cm.warehousemanagername,cm.warehousemanagerlandlinenumber,cm.warehousemanagermobilenumber,cm.warehousemanageremail,
				cm.expirylimit,cm.exprunningvalue,cm.distributionkey,cm.gpssavecount,cm.graceperiod,cm.reportcustcode,cm.enablerental,cm.enableautofillsales,cm.enablebatchselection,
				cm.barcode,cm.gracelimit,ifnull(visualcode,0) as visualcode,ifnull(distribution_check_id,0) as distribution_check_id,0 as splitfree, cm.enablereturnpassword, cm.statementdays,cm.itemmapkey,cm.enforcemsl,cm.custemail
			FROM customermaster cm
			WHERE cm.templateindicator = 1 AND cm.activecustomer = 1 ",var_where1 );
								
	PREPARE s1 FROM @dyn_sql1;
	EXECUTE s1;
	
	
	SET @dyn_sql3 = CONCAT("
				SELECT sc.salesyear,sc.weeknumber,sc.weekstartdate,sc.weekenddate,sc.rp32weeknumber,sc.salesperiod
				FROM salescalender sc
				WHERE sc.salesyear = YEAR(CURRENT_DATE())");
	PREPARE s3 FROM @dyn_sql3;
	EXECUTE s3;
	
	
	SET @dyn_sql4 = CONCAT("
				SELECT rs.rp32weeknumber,rs.routecode,rs.customercode,
					rs.callrestrictiondays1,rs.callrestrictiondays2,rs.callrestrictiondays3,rs.callrestrictiondays4,rs.callrestrictiondays5,rs.callrestrictiondays6,rs.callrestrictiondays7,
					rs.monseq,rs.tueseq,rs.wedseq,rs.thuseq,rs.friseq,rs.satseq,rs.sunseq
				FROM ",@TEMPTABLE, " cm 
						INNER JOIN routesequence rs ON rs.customercode = cm.customercode
				WHERE rs.rp32weeknumber=", var_week, " AND rs.routecode = ",var_routeid," ",var_where4);
	PREPARE s4 FROM @dyn_sql4;
	EXECUTE s4;
	
	
	SELECT `status` INTO var_tempflag FROM controlpanel WHERE flagid = 51;
    
	SET @dyn_sql5 = CONCAT("DELETE FROM ",@TEMPTABLE, " WHERE customercode IN (SELECT customercode FROM customermaster WHERE invoicepaymentterms > 1 and enablearcollection = 0)");
	PREPARE s5 FROM @dyn_sql5;
	EXECUTE s5;
	
	IF  var_tempflag = '1' THEN 
		SET @dyn_sql5 = CONCAT("
					SELECT ci.transactionkey,ci.transactiontype,ci.documentnumber,ci.invoicenumber,ci.transactiondate,ci.transactiontime,ci.customercode,", var_routeid, " routecode,ci.salesmancode,
						ci.totalinvoiceamount,ci.totalsalesamount,ci.totalreturnamount,ci.totaldamagedamount,ci.totalfreesampleamount,ci.immediatepaid,ci.amountpaid,ci.dnamountpaid,ci.cnamountpaid,
						ci.invoicebalance,ci.paymenttype,ci.voidflag,ci.paymentstatus,ci.hhcinvoicenumber, sm.alternatesalesmancode remarks1,'' remarks2,ci.routestartdate,ci.erpreferencenumber,ci.mdat,ci.totalpromoamount,
						ci.gcpaymenttype,ci.totaltaxesamount,ci.itemlinetaxamount,ci.totaldiscountamount,ci.pdcindicator,ci.chequecollection,ci.totalexpiryamount,ci.currencycode,ci.pdcbalance,
						ci.totalmanualfree,ci.totallimitedfree,ci.totalrebaterent,ci.totalfixedrent,ci.data,ci.totaldiscdistributionamount,ci.totalreplacementamount,ci.pdcdate,ci.totalbuybackfreeamount, 
						ci.duedate
					FROM ",@TEMPTABLE, " cm 
						INNER JOIN customerinvoice ci ON ci.customercode = cm.customercode
						INNER JOIN salesman sm ON sm.salesmancode = ci.salesmancode
					WHERE ci.transactiontype = 2  AND ci.voidflag = 0 AND ci.duedate IS NOT NULL ",var_where5);
	ELSE
		SET @dyn_sql5 = CONCAT("
					SELECT ci.transactionkey,ci.transactiontype,ci.documentnumber,ci.invoicenumber,ci.transactiondate,ci.transactiontime,ci.customercode,", var_routeid, " routecode,ci.salesmancode,
						ci.totalinvoiceamount,ci.totalsalesamount,ci.totalreturnamount,ci.totaldamagedamount,ci.totalfreesampleamount,ci.immediatepaid,ci.amountpaid,ci.dnamountpaid,ci.cnamountpaid,
						ci.invoicebalance,ci.paymenttype,ci.voidflag,ci.paymentstatus,ci.hhcinvoicenumber, sm.alternatesalesmancode remarks1,'' remarks2,ci.routestartdate,ci.erpreferencenumber,ci.mdat,ci.totalpromoamount,
						ci.gcpaymenttype,ci.totaltaxesamount,ci.itemlinetaxamount,ci.totaldiscountamount,ci.pdcindicator,ci.chequecollection,ci.totalexpiryamount,ci.currencycode,ci.pdcbalance,
						ci.totalmanualfree,ci.totallimitedfree,ci.totalrebaterent,ci.totalfixedrent,ci.data,ci.totaldiscdistributionamount,ci.totalreplacementamount,ci.pdcdate,ci.totalbuybackfreeamount, 
						ci.duedate
					FROM ",@TEMPTABLE, " cm 
						INNER JOIN customerinvoice ci ON ci.customercode = cm.customercode
					WHERE ci.transactiontype = 2   AND ci.voidflag = 0 AND ci.duedate IS NOT NULL AND ci.routecode = ",var_routeid," ",var_where5);        
	END IF;	
	PREPARE s5 FROM @dyn_sql5;
	
	EXECUTE s5;
	
	SET @tempseqtable = CONCAT("DROP TABLE IF EXISTS ",@TEMPTABLE);
	PREPARE qry5 FROM @tempseqtable;
	EXECUTE qry5;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_syncicsdata_group` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_syncicsdata_group` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_syncicsdata_group`(
	IN var_userid INT,
	IN var_deviceid VARCHAR(255),
	IN var_routeid INT,
	IN var_checkmdate INT
    )
BEGIN
	DECLARE var_syncdate DATETIME;
	DECLARE var_pendinginvoicests INT;
	
	DECLARE var_where1 VARCHAR(250);
	
	
	
	SET var_where1 = "";
	
		
	IF var_checkmdate = 1 THEN
		
		SELECT syncdate INTO var_syncdate FROM tbl_syncservice WHERE userid = var_userid AND deviceid = var_deviceid;
		   IF var_syncdate != '' THEN
			
			SET var_where1 = CONCAT(" AND productgroupdetail.mdat > '",var_syncdate,"' ");
           
		   END IF;
	   END IF;
	
        
		SET @dyn_sql1 = CONCAT("SELECT * FROM productgroupdetail limit 130,130");		
		PREPARE s1 FROM @dyn_sql1;
		EXECUTE s1;
		
		SET @dyn_sql2 = CONCAT("SELECT * FROM productgroupdetail limit 260,130");		
		PREPARE s2 FROM @dyn_sql2;
		EXECUTE s2;
		
		SET @dyn_sql3 = CONCAT("SELECT * FROM productgroupdetail limit 390,130");		
		PREPARE s3 FROM @dyn_sql3;
		EXECUTE s3;
		
        
        	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_syncicsdata_inventory` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_syncicsdata_inventory` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_syncicsdata_inventory`(
	IN var_userid INT,
	IN var_deviceid VARCHAR(255),
	IN var_routeid INT,
	IN var_checkmdate INT
    )
BEGIN
 
	DECLARE var_syncdate DATETIME;
	DECLARE var_pendinginvoicests INT;
	
	DECLARE var_where1 VARCHAR(250);
	DECLARE var_where2 VARCHAR(250);
	
	SET var_where1 = "";
	SET var_where2 = "";
	
	SET var_checkmdate = 0;
	
	IF var_checkmdate = 1 THEN
		
		SELECT syncdate INTO var_syncdate FROM tbl_syncservice WHERE userid = var_userid AND deviceid = var_deviceid;
		
		IF var_syncdate != '' THEN
			
			 SET var_where1 = CONCAT(" AND sd.mdat > '",var_syncdate,"' ");
			 SET var_where2 = CONCAT(" AND isd.mdat > '",var_syncdate,"' ");		
		END IF;
	END IF;
	   
    
    
    
	SET @dyn_sql1 = CONCAT("SELECT itemcode, routecode, ddate, caseprice, loadperiodnumber, cases, units, totunits, suggtotunits,
		rcvdtotunits, upc, loadtime, salesmancode, salesprice, returnprice, status, transactiondate, erpreferencenumber, currencycode,
		batchnumber, expirydate, warehouse, warehousestock, mdat 
		FROM startingloaddetail
		WHERE routecode = ",var_routeid," and status=0  AND ddate = CURDATE() AND totunits > 0 ");
		PREPARE s1 FROM @dyn_sql1;
		EXECUTE s1;
        
    
	SET @dyn_sql2 = CONCAT(" SELECT
		isd.inventorykey,
		isd.itemcode,
		isd.routekey,
		isd.weighted,
		isd.beginstockqty,
		isd.loadqty,
		isd.loadaddqty,
		isd.loadcutqty,
		isd.loadreqqty,
		isd.saleqty,
		isd.returnqty,
		isd.damagedaddqty,
		isd.damagedcutqty,
		isd.endstockqty,
		isd.unloadqty,
		isd.damagedunloadqty,
		isd.freesampleqty,
		isd.truckdamagedunloadqty,
		isd.stdsalesprice,
		isd.stdreturnprice,
		isd.cashsalesqty,
		isd.cashsalesvalue,
		isd.tcsalesqty,
		isd.tcsalesvalue,
		isd.gcsalesqty,
		isd.gcsalesvalue,
		isd.cashdamagedqty,
		isd.cashdamagedvalue,
		isd.tcdamagedqty,
		isd.tcdamagedvalue,
		isd.gcdamagedqty,
		isd.gcdamagedvalue,
		isd.cashreturnqty,
		isd.cashreturnvalue,
		isd.tcreturnqty,
		isd.tcreturnvalue,
		isd.gcreturnqty,
		isd.gcreturnvalue,
		isd.promoqty,
		isd.cashsalesitemexcisetax,
		isd.cashsalesitemgsttax,
		isd.cashreturnitemexcisetax,
		isd.cashreturnitemgsttax,
		isd.cashdamageditemexcisetax,
		isd.cashdamageditemgsttax,
		isd.cashfgitemexcisetax,
		isd.cashfgitemgsttax,
		isd.cashpromoitemexcisetax,
		isd.cashpromoitemgsttax,
		isd.tcsalesitemexcisetax,
		isd.tcsalesitemgsttax,
		isd.tcreturnitemexcisetax,
		isd.tcreturnitemgsttax,
		isd.tcdamageditemexcisetax,
		isd.tcdamageditemgsttax,
		isd.tcfgitemexcisetax,
		isd.tcfgitemgsttax,
		isd.tcpromoitemexcisetax,
		isd.tcpromoitemgsttax,
		isd.gcsalesitemexcisetax,
		isd.gcsalesitemgsttax,
		isd.gcreturnitemexcisetax,
		isd.gcreturnitemgsttax,
		isd.gcdamageditemexcisetax,
		isd.gcdamageditemgsttax,
		isd.gcfgitemexcisetax,
		isd.gcfgitemgsttax,
		isd.gcpromoitemexcisetax,
		isd.gcpromoitemgsttax,
		isd.batchdetailkey,
		isd.stdsalescaseprice,
		isd.stdreturncaseprice,
		isd.expiryqty,
		isd.stdgoodreturncaseprice,
		isd.stdgoodreturnprice,
		isd.currencycode,
		isd.returnfreeqty,
		isd.damageqty,
		isd.expdmgfreeqty,
		isd.expunloadqty,
		isd.dmgunloadqty,
		isd.expdmgfreeunloadqty,
		isd.rentqty,
		isd.mdat
		FROM inventorysummarydetail AS isd
		WHERE isd.routekey = (SELECT MAX(sed.routekey) FROM startendday sed WHERE sed.routecode=",var_routeid, ")");
		PREPARE s2 FROM @dyn_sql2;
		EXECUTE s2;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_syncicsdata_inventory1` */

