/* Procedure structure for procedure `sp_ws_syncicsdata_itemmust` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_syncicsdata_itemmust` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_syncicsdata_itemmust`(
	IN var_userid INT,
	IN var_deviceid VARCHAR(255),
	IN var_routeid INT,
	IN var_checkmdate INT  
    )
BEGIN
	
	DECLARE var_syncdate DATETIME;
	
	
	DECLARE var_where1 VARCHAR(250);
	DECLARE var_where2 VARCHAR(250);
	
	SET var_where1 = "";
	SET var_where2 = "";
	
	SET var_checkmdate = 0;
	
	IF var_checkmdate = 1 THEN
		
		SELECT syncdate INTO var_syncdate FROM tbl_syncservice WHERE userid = var_userid AND deviceid = var_deviceid;
		IF var_syncdate != '' THEN
			
			SET var_where1 = CONCAT(" AND itemmustheader.mdat > '",var_syncdate,"' ");
			SET var_where2 = CONCAT(" AND itemmustdetail.mdat > '",var_syncdate,"' ");
		END IF;
	END IF;
		
		
        
	
	 
	SET @dyn_sql1 = CONCAT("SELECT * FROM itemmustheader 
		WHERE  itemmustcode IN (SELECT DISTINCT itemmustkey FROM CustomerMaster WHERE routecode=", var_routeid, ")");
	PREPARE s1 FROM @dyn_sql1;
	EXECUTE s1;
		
        
        
	SET @dyn_sql2 = CONCAT("SELECT *
		FROM itemmustdetail  
		WHERE  itemmustcode IN (SELECT DISTINCT itemmustkey FROM CustomerMaster WHERE routecode=", var_routeid, ")");
	PREPARE s2 FROM @dyn_sql2;
	EXECUTE s2;      
	
	SET @dyn_sql3 = CONCAT("SELECT ITEM.ACTUALITEMCODE, 
		CASE WHEN ITEM.NRP_FLAG = 'Y' THEN 0 ELSE 1 END ITEM_RET, 
		DM.DIVISIONNAME, 
		CASE WHEN DM.NRP_FLAG = 'Y' THEN 0 ELSE 1 END DIV_RET
		FROM ITEMMASTER ITEM
		JOIN DIVISIONMASTER DM ON ITEM.DIVISION =  DM.DIVISIONNAME
		LEFT JOIN routeitemmapping AS rim ON rim.itemcode = item.actualitemcode
		LEFT JOIN routemaster AS rm ON rm.routeitemgrpcode = rim.routeitemgrpcode	
	        WHERE rm.routecode =", var_routeid );
	PREPARE s3 FROM @dyn_sql3;
	EXECUTE s3; 
	
	SET @dyn_sql4 = CONCAT("SELECT DISTINCT CN.CUSTOMERCODE,
	        CASE WHEN cn.nrp_flag = 'Y' THEN 0 ELSE 1 END CUST_RET
	        FROM CUSTOMERMASTER CN, ROUTESEQUENCE RS 
		WHERE CN.CUSTOMERCODE = RS.CUSTOMERCODE 		
		AND RS.ROUTECODE = ", var_routeid );
	PREPARE s4 FROM @dyn_sql4;
	EXECUTE s4;    
		
	SET @dyn_sql5 = CONCAT("select * from nrp_rule");
	PREPARE s5 FROM @dyn_sql5;
	EXECUTE s5;    
	  
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_syncicsdata_items` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_syncicsdata_items` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_syncicsdata_items`(
	IN var_userid INT,
	IN var_deviceid VARCHAR(255),
	IN var_routeid INT,
	IN var_checkmdate INT
    )
BEGIN
	
	
	DECLARE var_syncdate DATETIME;
	DECLARE var_pendinginvoicests INT;
	
	DECLARE var_where1 VARCHAR(250);
	DECLARE var_where2 VARCHAR(250);
	DECLARE var_where3 VARCHAR(250);
	DECLARE var_where4 VARCHAR(250);
	
	
	SET var_where1 = "";
	SET var_where2 = "";
	SET var_where3 = "";
	SET var_where4 = "";
	  
	
	SET @dyn_sql1 = CONCAT("SELECT  
		ig.itemgroupcode, 
		ig.submajorcategorycode, 
		ig.itemgroupname, 
		CASE WHEN ig.arbitemgroup = '' THEN ig.itemgroupname ELSE ig.arbitemgroup END arbitemgroup, 
		ig.activestatus
		FROM itemgroup AS ig
		WHERE ig.activestatus = 1 AND ig.itemgroupcode IN 
			(SELECT DISTINCT im.itemgroupcode 
			FROM itemmaster im 
				INNER JOIN routeitemmapping map ON map.itemcode = im.actualitemcode AND im.activeitem = 1
				INNER JOIN routemaster rm ON rm.routeitemgrpcode =  map.routeitemgrpcode AND rm.routecode = ", var_routeid,") ", var_where1, " ");
		PREPARE s1 FROM @dyn_sql1;
	
		EXECUTE s1;		
	
    
    
		SET @dyn_sql2 = CONCAT("SELECT  item.actualitemcode, item.itemgroupcode, item.itemtype, 
		REPLACE(REPLACE(REPLACE(item.itemshortdescription,' ',''),'É',''),'''','') itemshortdescription, 
		 replace(REPLACE(REPLACE(REPLACE(item.itemdescription,' ',''),'É',''),'''',''),'Â','') itemdescription, 
		item.unitspercase, item.defaultsalesprice, item.defaultreturnprice, 
		-- REPLACE(REPLACE(item.arbitemshortdescription,' ',''),'É','') arbitemshortdescription,
		REPLACE(REPLACE(item.barcode1,'Â',''),' ','') as arbitemshortdescription,
		-- REPLACE(REPLACE(item.arbitemdescription,' ',''),'É','') arbitemdescription,
		'' arbitemdescription,
		item.activeitem, 
		item.caseprice, item.returncaseprice, 
		item.alternatecode,		
		ifnull(item.memo1,0) as memo1,
		ifnull(item.memo2,0) as memo2,
		item.tcallowed,		
		item.printsequenceroute,
		item.printsequencecust,		
		item.packagecode,		
		item.warehousestock,		
		item.defaultgoodreturnprice,
		item.defaultgoodreturncaseprice,		
		item.allowbatchentry,		
		REPLACE(REPLACE(REPLACE(trim(item.barcode1),' ','0'),'É',''),'Â','') AS barcode1,
ifnull(item.barcode2,0) as barcode2,
		item.barcode3,
		item.majorcategorycode,
		item.majorcategorydesciption,
		item.submajorcategorycode,
	        item.submajorcategorydesciption,
		item.companygroupcode,
		item.companygroupname,
		item.itemgroupname,
		item.enabletax,
		item.itemtaxkey1,
		item.itemtaxkey2,
		item.itemtaxkey3,
		ifnull(case when item.nrp_flag = 'Y' then 0 else 1 end,1) as nrp_flag,
		ifnull(case when item.div_nrp_flag = 'Y' then 0 else 1 end,1) as div_nrp_flag
		FROM itemmaster AS item	
		LEFT JOIN routeitemmapping AS rim ON rim.itemcode = item.actualitemcode
		LEFT JOIN routemaster AS rm ON rm.routeitemgrpcode = rim.routeitemgrpcode	
	        WHERE  item.activeitem = 1 AND rm.routecode = ",var_routeid, "   ");
                
		PREPARE s2 FROM @dyn_sql2;
		 EXECUTE s2;
    
    
    
                   
    
		SET @dyn_sql3 = CONCAT("SELECT packagecode,
						alternatecode,
						packagedescription,
						arbpackagedescription,
						activestatus
						FROM itempackagemaster WHERE 1=1 ",var_where3);
		PREPARE s3 FROM @dyn_sql3;
		EXECUTE s3;
        
        
		
		SET @dyn_sql4 = CONCAT("
			SELECT primary_key,
				routecode, salesmancode, packagenumber, fromdate, todate, quantity, achievequantity, todaysgoal,
				todaysachieve, targettype, commision, commisonpercent, insentive, insentivepercent, goaltype
			FROM routegoal 
			WHERE routecode = ",var_routeid," AND (CURDATE() BETWEEN fromdate AND todate)");
		PREPARE s4 FROM @dyn_sql4;
		EXECUTE s4;
		
		
		SET @dyn_sql5 = CONCAT("SELECT table_id,itemcode,routecode,itemqty FROM averagesalesqty WHERE routecode = ",var_routeid);
		PREPARE s5 FROM @dyn_sql5;
		EXECUTE s5;
		
		
		
		SET @dyn_sql6 = CONCAT("select primary_key,groupcode,itemcode,outletitemcode,IFNULL(customercode,0) as customercode  from     outletitemcodes 	WHERE groupcode IN(SELECT outletsubtype FROM customermaster WHERE routecode=",var_routeid," AND outletsubtype>0) and 1=0 order by itemcode ");
		PREPARE s6 FROM @dyn_sql6;
		EXECUTE s6;
		
		#FROM taxmaster
		SET @dyn_sql7 = CONCAT("select taxcode,taxdescription,arbtaxdescription,taxtype,taxpercentage,taxbase from tbltaxmaster");
		PREPARE s7 FROM @dyn_sql7;
		EXECUTE s7;
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_syncicsdata_orders` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_syncicsdata_orders` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_syncicsdata_orders`(
	IN var_userid INT,
	IN var_deviceid VARCHAR(255),
	IN var_routeid INT,
	IN var_checkmdate INT  
    )
BEGIN
  
	DECLARE var_syncdate DATETIME;
	
    
	DECLARE var_where1 VARCHAR(250);
	DECLARE var_where3 VARCHAR(250);
	
	SET var_where1 = "";
	SET var_where3 = "";
	
	SET var_checkmdate = 0;
	
	IF var_checkmdate = 1 THEN
	
	SELECT syncdate INTO var_syncdate FROM tbl_syncservice WHERE userid = var_userid AND deviceid = var_deviceid;
		IF var_syncdate != '' THEN
		
		SET var_where1 = CONCAT(" AND salesorderheader.mdat > '",var_syncdate,"' ");
		SET var_where3 = CONCAT(" AND suggestedsalesinvoice.mdat > '",var_syncdate,"' ");		        
	   END IF;
	END IF;
	
	
	SELECT COALESCE(MAX(routekey),0) INTO @routekey FROM startendday WHERE routeclosed = 1 AND routecode = var_routeid;
	
	SET @tableopenstk = CONCAT("temp_openstock_",var_routeid);
	SET @tabletmp1 = CONCAT("DROP TABLE IF EXISTS ",@tableopenstk);
	PREPARE qry1 FROM @tabletmp1 ;
	EXECUTE qry1;
	
	SET @tabletmp1 =  CONCAT("CREATE TABLE IF NOT EXISTS ", @tableopenstk, " AS SELECT * FROM inventorytransactiondetail WHERE transactiontypecode = 5 AND quantity > 0 AND routekey= ", @routekey);
	PREPARE qry2 FROM @tabletmp1;
	EXECUTE qry2;
	
	
        
	SET @dyn_sql1 = CONCAT("SELECT * FROM deliveryheader 
		WHERE delivered = 0 AND deliveryroute = ",var_routeid," AND deliverydate= '",CURRENT_DATE(), "'");
	PREPARE s1 FROM @dyn_sql1;
	EXECUTE s1;		
        
        
	SET @dyn_sql2 = CONCAT("SELECT dd.*
		FROM deliveryheader dh 
			INNER JOIN deliverydetail dd ON dd.deliveryno = dh.deliveryno AND dh.delivered = 0 AND 
			dh.deliveryroute = ", var_routeid," AND dh.deliverydate= '",CURRENT_DATE(), "'");
	PREPARE s2 FROM @dyn_sql2;
	EXECUTE s2;
        
        
	SET @dyn_sql3 = CONCAT("SELECT * FROM suggestedsalesinvoice WHERE routecode =  ", var_routeid);
	PREPARE s3 FROM @dyn_sql3;
	EXECUTE s3;
	
        
	SET @dyn_sql4 = CONCAT("SELECT * FROM ", @tableopenstk, " WHERE quantity > 0");
	PREPARE s4 FROM @dyn_sql4;
	EXECUTE s4;
		
	
	SET @tableseq = CONCAT("temp_seqcustomers_",var_routeid);
	SET @tabletmp2 = CONCAT("DROP TABLE IF EXISTS ",@tableseq);
	PREPARE qry1 FROM @tabletmp2 ;
	EXECUTE qry1;
		
	SET @tabletmp2 =  CONCAT("CREATE TABLE IF NOT EXISTS ", @tableseq, " AS SELECT DISTINCT customercode AS code FROM routesequence WHERE routecode = ",var_routeid);
	PREPARE qry2 FROM @tabletmp2;
	EXECUTE qry2;				
		
        
	SET @dyn_sql5 = CONCAT("SELECT * FROM customer_foc_balance WHERE customercode IN (SELECT code FROM ",@tableseq,")");
	PREPARE s5 FROM @dyn_sql5;
	EXECUTE s5;
		        
        
	SET @dyn_sql6 = CONCAT("SELECT * FROM customer_foc_detail WHERE customercode IN (SELECT code FROM ",@tableseq,")");
	PREPARE s6 FROM @dyn_sql6;
	EXECUTE s6;
	
	
	SET @dyn_sql7 = CONCAT("SELECT * FROM journeyplancreditlimit WHERE 1=1 ");
	PREPARE s7 FROM @dyn_sql7;
	EXECUTE s7;
		
        
	SET @dyn_sql8 = CONCAT("SELECT * FROM batchexpirydetail WHERE routekey = ",@routekey);
	PREPARE s8 FROM @dyn_sql8;
	EXECUTE s8;
	
	
	SET @dyn_sql9 = CONCAT("SELECT * FROM customer_foc 
		WHERE customercode IN (SELECT code FROM ",@tableseq,") AND '", DATE_FORMAT(CURRENT_DATE(),"%Y-%m-%d"), "' BETWEEN startdate AND enddate");
	PREPARE s9 FROM @dyn_sql9;
	EXECUTE s9;
		
	SET @tabletmp1 = CONCAT("DROP TABLE IF EXISTS ",@tableopenstk);
	PREPARE qry1 FROM @tabletmp1 ;
	EXECUTE qry1;
	
	SET @tabletmp2 = CONCAT("DROP TABLE IF EXISTS ",@tableseq);
	PREPARE qry1 FROM @tabletmp2 ;
	EXECUTE qry1;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_syncicsdata_others` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_syncicsdata_others` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_syncicsdata_others`(
    	IN var_userid INT,
