						mdat,activestatus
						FROM salesmanmessages WHERE 1=1 ",var_where2);
		PREPARE s2 FROM @dyn_sql2;
		EXECUTE s2;
        
        
        
		SET @dyn_sql3 = CONCAT("SELECT vancode,
						alternatecode,
						vandescription,
						arbvandescription,
						activestatus,
						vanregno,
						vanmodel,
						vantype,
						created,
						cdat,
						modified,
						mdat
						FROM vanmaster WHERE 1=1 ",var_where3);
		PREPARE s3 FROM @dyn_sql3;
		EXECUTE s3;
		
        
        
		SET @dyn_sql4 = CONCAT("SELECT 
		bankcode,
		bankname,
		arbbankname,
		bankbalance,
		created,
		cdat,
		modified,
		mdat,
		activestatus,
		alternatecode,
		type,
		acnumber		
		 FROM bankmaster WHERE 1=1 ",var_where4);
		PREPARE s4 FROM @dyn_sql4;
		EXECUTE s4;
        
        
        
        
		SET @dyn_sql5 = CONCAT("SELECT code,
						alternatecode,
						description,
						arbdescription,
						hhcdescription,
						created,
						cdat,
						modified,
						mdat
						FROM cashdesc WHERE 1=1 ",var_where5);
		PREPARE s5 FROM @dyn_sql5;
		EXECUTE s5;
		
        
        
		SET @dyn_sql6 = CONCAT("SELECT code,
						alternatecode,
