/* Procedure structure for procedure `sp_ws_syncicsdata_reasons` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_syncicsdata_reasons` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_syncicsdata_reasons`(
	IN var_userid INT,
	IN var_deviceid VARCHAR(255),
	IN var_routeid INT,
	IN var_checkmdate INT
    )
BEGIN
	
	DECLARE var_syncdate DATETIME;
	
	DECLARE var_where1 VARCHAR(250);
	DECLARE var_where2 VARCHAR(250);
	DECLARE var_where3 VARCHAR(250);
	DECLARE var_where4 VARCHAR(250);
	DECLARE var_where5 VARCHAR(250);
	DECLARE var_where6 VARCHAR(250);
        
        SET var_where1 = "";
        SET var_where2 = "";
        SET var_where3 = "";
        SET var_where4 = "";
        SET var_where5 = "";
        SET var_where6 = "";        
        
        
	SET @dyn_sql1 = CONCAT("
		SELECT 
			code, alternatecode, description, arbdescription, hhcdescription, created, cdat, modified, mdat
		FROM 
			nonservreasons "," ");
	PREPARE s1 FROM @dyn_sql1;
	EXECUTE s1;        
        
        
	SET @dyn_sql2 = CONCAT("
		SELECT 
			code, alternatecode, description, arbdescription, hhcdescription, created, cdat, modified, mdat
		FROM 
			expreasons ", " ");
	PREPARE s2 FROM @dyn_sql2;
	EXECUTE s2;
        
        
	SET @dyn_sql3 = CONCAT("
		SELECT 
			code, alternatecode, description, arbdescription, hhcdescription, created, cdat, modified, mdat
		FROM 
			expiryreturnreasons ", " ");
	PREPARE s3 FROM @dyn_sql3;
	EXECUTE s3;
        
        
	SET @dyn_sql4 = CONCAT("
		SELECT 
