/* Procedure structure for procedure `sp_ws_syncicsdata_schemes` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_syncicsdata_schemes` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_syncicsdata_schemes`(
	IN var_userid INT,
	IN var_deviceid VARCHAR(255),
	IN var_routeid INT,
	IN var_checkmdate INT
    )
BEGIN
	DECLARE var_syncdate DATETIME;
	DECLARE var_pendinginvoicests INT;
	
	DECLARE var_where1 VARCHAR(250);
	DECLARE var_where2 VARCHAR(250);
	DECLARE var_where3 VARCHAR(250);
	DECLARE var_where4 VARCHAR(250);
	DECLARE var_where5 VARCHAR(250);
	DECLARE var_where6 VARCHAR(250);
	DECLARE var_where7 VARCHAR(250);
	DECLARE var_where8 VARCHAR(250);
	DECLARE var_where9 VARCHAR(250);
	DECLARE var_where10 VARCHAR(250);
	DECLARE var_where11 VARCHAR(250);
	DECLARE var_where12 VARCHAR(250);
	
	
	SET var_where1 = "";
	SET var_where2 = "";
	SET var_where3 = "";
	SET var_where4 = "";
	SET var_where5 = "";
	SET var_where6 = "";
	SET var_where7 = "";
	SET var_where8 = "";
	SET var_where9 = "";
	SET var_where10 = "";
	SET var_where11 = "";
	SET var_where12 = "";
	
	SET var_checkmdate = 0;
		
	IF var_checkmdate = 1 THEN
		
		SELECT syncdate INTO var_syncdate FROM tbl_syncservice WHERE userid = var_userid AND deviceid = var_deviceid;
		
		IF var_syncdate != '' THEN
			
			SET var_where1 = "";
			SET var_where2 = "";
			SET var_where3 = "";
			SET var_where4 = CONCAT(" AND mdat > '",var_syncdate,"' ");
			SET var_where5 = CONCAT(" AND mdat > '",var_syncdate,"' ");
			SET var_where6 = CONCAT(" AND promokeyheader.mdat > '",var_syncdate,"' ");
			SET var_where7 = CONCAT("('" ,CURRENT_DATE(), "' BETWEEN promokeydetail.startdate AND startdate.enddate) AND promokeydetail.mdat > '",var_syncdate,"' ");
			SET var_where8 = CONCAT(" AND promoplanheader.mdat > '",var_syncdate,"' ");
			SET var_where9 = CONCAT(" AND promoplandetail.mdat > '",var_syncdate,"' ");
			SET var_where10 = CONCAT(" AND promotionassignmentadvanced.mdat > '",var_syncdate,"' ");
			SET var_where11 = CONCAT(" AND customerpricing1.mdat > '",var_syncdate,"' ");
			SET var_where12 = CONCAT(" AND pricingdetail1.mdat > '",var_syncdate,"' ");
		END IF;
	END IF;
	
	
	SET @dyn_sql1 = CONCAT("
			SELECT dkh.discountkey,dkh.description,dkh.arbdescription,dkh.startdate,dkh.enddate,dkh.active
			FROM discountkeyheader dkh
			WHERE dkh.enddate>= CURRENT_DATE()");
	PREPARE s1 FROM @dyn_sql1;
	
	EXECUTE s1;
	
	
	SET @dyn_sql2 = CONCAT("
			SELECT dkd.discountkey,dkd.actualitemcode,dkd.mindiscount,dkd.maxdiscount
			FROM discountkeydetail dkd
			WHERE 1=1 ",var_where2);
	PREPARE s2 FROM @dyn_sql2;
	EXECUTE s2;
	
	
	SET @dyn_sql3 = CONCAT("
			SELECT dkd.distributionkey,dkd.item,dkd.value		
			FROM distributionkeydetails dkd
			WHERE 1=1",var_where3);
	PREPARE s3 FROM @dyn_sql3;
	EXECUTE s3;
	
	
	SET @tablename = CONCAT("temp_promotable_",var_routeid);
	SET @temppromotable = CONCAT("DROP TABLE IF EXISTS ",@tablename);
	PREPARE qry1 FROM @temppromotable ;
	EXECUTE qry1;
	
	SET @temppromotable =  CONCAT("CREATE TABLE IF NOT EXISTS ", @tablename, " AS 
		SELECT DISTINCT(cm.promotionkey) keyval 
		FROM customermaster cm INNER JOIN routesequence rs ON cm.customercode = rs.customercode AND rs.routecode = ",var_routeid);
	PREPARE qry2 FROM @temppromotable;
	EXECUTE qry2;
	
	SET @groupname = CONCAT("temp_grouptable_",var_routeid);
	SET @tempgrouptable = CONCAT("DROP TABLE IF EXISTS ",@groupname);
	PREPARE qry3 FROM @tempgrouptable ;
	EXECUTE qry3;
	
	SET @tempgrouptable =  CONCAT("CREATE TABLE IF NOT EXISTS ", @groupname, " AS 
		SELECT DISTINCT (groupnumber) groupid
		FROM productgroupdetail 
		WHERE itemcode IN (SELECT DISTINCT itemcode FROM routeitemmapping WHERE routeitemgrpcode = 
			(SELECT routeitemgrpcode FROM routemaster WHERE routecode = ",var_routeid, "))");
	PREPARE qry4 FROM @tempgrouptable;
	EXECUTE qry4;
		
	
	SET @dyn_sql4 = CONCAT("
				SELECT DISTINCT pgh.* 
				FROM productgroupheader pgh
				WHERE pgh.groupnumber IN
					(
					SELECT ppd.qualificationgroup		
					FROM promokeyheader pkh 
						INNER JOIN promokeydetail pkd ON pkh.promotionkey = pkd.promotionkey AND CURRENT_DATE() between pkd.startdate and pkd.enddate
						INNER JOIN promoplanheader pph ON pkd.plannumber = pph.plannumber
						INNER JOIN promoplandetail ppd ON pph.plannumber = ppd.plannumber
					WHERE pkh.promotionkey IN (SELECT keyval FROM ",@tablename,") AND pkd.qualificationgroup IN (SELECT groupid FROM ", @groupname ,")
						UNION
					SELECT ppd.assignmentgroup
					FROM promokeyheader pkh 
						INNER JOIN promokeydetail pkd ON pkh.promotionkey = pkd.promotionkey AND CURRENT_DATE() between pkd.startdate and pkd.enddate
						INNER JOIN promoplanheader pph ON pkd.plannumber = pph.plannumber
						INNER JOIN promoplandetail ppd ON pph.plannumber = ppd.plannumber
					WHERE pkh.promotionkey IN (SELECT keyval FROM ",@tablename,"))");	
	PREPARE s4 FROM @dyn_sql4;
	
	 EXECUTE s4;
	
	
	SET @dyn_sql5 = CONCAT("
				SELECT DISTINCT pgd.* 
				FROM productgroupdetail pgd
				WHERE pgd.groupnumber IN
					(
					SELECT ppd.qualificationgroup		
					FROM promokeyheader pkh 
						INNER JOIN promokeydetail pkd ON pkh.promotionkey = pkd.promotionkey AND CURRENT_DATE() between pkd.startdate and pkd.enddate
						INNER JOIN promoplanheader pph ON pkd.plannumber = pph.plannumber
						INNER JOIN promoplandetail ppd ON pph.plannumber = ppd.plannumber
					WHERE pkh.promotionkey IN (SELECT keyval FROM ",@tablename,") 
						UNION
					SELECT ppd.assignmentgroup
					FROM promokeyheader pkh 
						INNER JOIN promokeydetail pkd ON pkh.promotionkey = pkd.promotionkey AND CURRENT_DATE() between pkd.startdate and pkd.enddate
						INNER JOIN promoplanheader pph ON pkd.plannumber = pph.plannumber
						INNER JOIN promoplandetail ppd ON pph.plannumber = ppd.plannumber
					WHERE pkh.promotionkey IN (SELECT keyval FROM ",@tablename,") )");		
	PREPARE s5 FROM @dyn_sql5;
	EXECUTE s5;
	
	
	SET @dyn_sql6 = CONCAT("
				SELECT pkh.promotionkey,pkh.description,pkh.arbdescription,pkh.activeindicator,pkh.type	
				FROM promokeyheader pkh 
				WHERE pkh.promotionkey IN (SELECT keyval FROM ",@tablename,")");
	PREPARE s6 FROM @dyn_sql6;
	EXECUTE s6;
	
	
	
	
	SET @dyn_sql7 = CONCAT("
			SELECT pkd.primary_key,pkd.plannumber,pkd.promotionkey,pkd.startdate,pkd.enddate,pkd.promotiontypecode,pkd.qualificationgroup,pkd.assignmentgroup,pkd.assignmentnumber,pkd.performcriteriakey,
				pkd.rangebasis,pkd.amountbasis,pkd.exclusionoption,pkd.active,pkd.iscase	
			FROM promokeyheader pkh 
				INNER JOIN promokeydetail pkd ON pkh.promotionkey = pkd.promotionkey AND CURRENT_DATE() between pkd.startdate and pkd.enddate
			WHERE pkh.promotionkey IN (SELECT keyval FROM ",@tablename,")");
	PREPARE s7 FROM @dyn_sql7;
	EXECUTE s7;		
	
	
	SET @dyn_sql8 = CONCAT("
			SELECT DISTINCT pph.plannumber,pph.plandescription,pph.arbplandescription,pph.plantypecode,pph.activeindicator	
			FROM promokeyheader pkh 
				INNER JOIN promokeydetail pkd ON pkh.promotionkey = pkd.promotionkey AND CURRENT_DATE() between pkd.startdate and pkd.enddate
				INNER JOIN promoplanheader pph ON pkd.`plannumber` = pph.`plannumber`
			WHERE pkh.promotionkey IN (SELECT keyval FROM ",@tablename,") ");
	PREPARE s8 FROM @dyn_sql8;
	EXECUTE s8;
	
	
	SET @dyn_sql9 = CONCAT("
			SELECT DISTINCT ppd.plannumber,ppd.qualificationgroup,ppd.assignmentgroup,ppd.performcriteriakey,ppd.rangebasis,ppd.amountbasis,ppd.exclusionoption,ppd.assignmentnumber,ppd.plandescription,
				ppd.arbplandescription,ppd.promotiontypecode,ppd.rentindicator,ppd.iscase,ppd.onetimeuse,ppd.enforcepromotion		
			FROM promokeyheader pkh 
				INNER JOIN promokeydetail pkd ON pkh.promotionkey = pkd.promotionkey AND CURRENT_DATE() between pkd.startdate and pkd.enddate
				INNER JOIN promoplanheader pph ON pkd.plannumber = pph.plannumber
				INNER JOIN promoplandetail ppd ON pph.plannumber = ppd.plannumber
			WHERE pkh.promotionkey IN (SELECT keyval FROM ",@tablename,") ");
	PREPARE s9 FROM @dyn_sql9;
	EXECUTE s9;
	
	
	SET @dyn_sql10 = CONCAT("		
				SELECT DISTINCT pa.range_id,pa.plannumber,pa.assignmentnumber,pa.rangelow,pa.rangehigh,pa.repeatingrange,pa.promotionamount		
				FROM promokeyheader pkh 
					INNER JOIN promokeydetail pkd ON pkh.promotionkey = pkd.promotionkey AND CURRENT_DATE() between pkd.startdate and pkd.enddate
					INNER JOIN promoplanheader pph ON pkd.plannumber = pph.plannumber
					INNER JOIN promotionassignmentadvanced pa ON pph.plannumber = pa.plannumber
				WHERE pkh.promotionkey IN (SELECT keyval FROM ",@tablename,") ");
	PREPARE s10 FROM @dyn_sql10;
	EXECUTE s10;
	
	SET @temppromotable = CONCAT("DROP TABLE IF EXISTS ",@tablename);
	PREPARE qry1 FROM @temppromotable ;
	EXECUTE qry1;
	
	SET @tempgrouptable = CONCAT("DROP TABLE IF EXISTS ",@groupname);
	PREPARE qry3 FROM @tempgrouptable ;
	EXECUTE qry3;
	
	
	
	SET @temppricetable = "DROP TABLE IF EXISTS temp_pricekey";
	PREPARE qry3 FROM @temppricetable;
	EXECUTE qry3;
	
	SET @temppricetable =  CONCAT("CREATE TEMPORARY TABLE IF NOT EXISTS temp_pricekey AS SELECT DISTINCT(cm.pricingkey) keyval FROM customermaster cm INNER JOIN routesequence rs ON cm.customercode = rs.customercode AND rs.routecode = ",var_routeid);
	PREPARE qry4 FROM @temppricetable;
	EXECUTE qry4;
	
	SET @dyn_sql11 = CONCAT("
				SELECT 
					cp.primary_key,cp.pricingplankey,cp.customerpricingkey,cp.description,cp.startdate,cp.enddate,cp.arbdescription,cp.contractno,cp.active,cp.sequencecode
				FROM customerpricingplanheader1 cpph 
					INNER JOIN customerpricing1 cp ON cpph.pricingplankey = cp.pricingplankey AND (cp.enddate >= CURRENT_DATE() OR cp.enddate = '0000-00-00 00:00:00')
					INNER JOIN pricingplanheader1 pph ON cp.customerpricingkey = pph.customerpricingkey	
				WHERE cpph.pricingplankey IN (SELECT keyval FROM temp_pricekey)");
	PREPARE s11 FROM @dyn_sql11;
	EXECUTE s11;
	
	
	SET @dyn_sql12 = CONCAT("
				SELECT DISTINCT
					pd.primary_key, pd.customerpricingkey, pd.itemcode, pd.salesprice, pd.returnprice, pd.retailprice, pd.salescaseprice, pd.returncaseprice, pd.unitspercase,
					pd.stdsalesunitprice, pd.stdreturnunitprice, pd.stdsalescaseprice, pd.stdreturncaseprice
				FROM customerpricingplanheader1 cpph 
					INNER JOIN customerpricing1 cp ON cpph.pricingplankey = cp.pricingplankey AND (cp.enddate >= CURRENT_DATE() OR cp.enddate = '0000-00-00 00:00:00')
					INNER JOIN pricingplanheader1 pph ON cp.customerpricingkey = pph.customerpricingkey	
					INNER JOIN pricingdetail1 pd ON cp.customerpricingkey = pd.customerpricingkey
					INNER JOIN routeitemmapping rit ON rit.itemcode = pd.itemcode AND rit.routeitemgrpcode = COALESCE((SELECT routeitemgrpcode FROM routemaster WHERE routecode = ", var_routeid,"), 0)
				WHERE cpph.pricingplankey IN (SELECT keyval FROM temp_pricekey)");
	PREPARE s12 FROM @dyn_sql12;
	  EXECUTE s12;	
	 
    END */$$
DELIMITER ;

