/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_syncicsdata_schemes_sujeecomment`(
	IN var_userid INT,
	IN var_deviceid VARCHAR(255),
	IN var_routeid INT,
	IN var_checkmdate INT
    )
BEGIN
	DECLARE var_syncdate DATETIME;
	DECLARE var_pendinginvoicests INT;
	
	DECLARE var_where1 VARCHAR(250);
	DECLARE var_where2 VARCHAR(250);
	DECLARE var_where3 VARCHAR(250);
	DECLARE var_where4 VARCHAR(250);
	DECLARE var_where5 VARCHAR(250);
	DECLARE var_where6 VARCHAR(250);
	DECLARE var_where7 VARCHAR(250);
	DECLARE var_where8 VARCHAR(250);
	DECLARE var_where9 VARCHAR(250);
	DECLARE var_where10 VARCHAR(250);
	DECLARE var_where11 VARCHAR(250);
	DECLARE var_where12 VARCHAR(250);
	
	
