		SET @dyn_sql34 = CONCAT("SELECT * FROM batchexpirydetail WHERE routekey = (SELECT MAX(routekey) FROM startendday where routecode = ",var_routeid," AND salesmancode = ",var_userid,")");
		PREPARE s34 FROM @dyn_sql34;
		EXECUTE s34;
				
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_syncicsdata_setting` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_syncicsdata_setting` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_syncicsdata_setting`(
	IN var_userid INT,
	IN var_deviceid VARCHAR(255),
	IN var_routeid INT,
	IN var_checkmdate INT
)
BEGIN
	
	DECLARE var_syncdate DATETIME;
	DECLARE rcnt INT;	
	DECLARE var_depots INT;	
	DECLARE var_transfer INT;	
	DECLARE var_condition VARCHAR(250);
	declare nonarcount int;
	
	SET @routekey = 0; SET @routegroup = 0;
	SELECT COALESCE(MAX(routekey), 0) INTO @routekey FROM startendday WHERE routeclosed = 1 AND routecode = var_routeid;
	SELECT COALESCE(routeitemgrpcode, 0) INTO @routegroup FROM routemaster WHERE routecode = var_routeid;
	
	
	SET @tableopenstk = CONCAT("temp_openstock_",var_routeid);
	SET @tabletmp1 = CONCAT("DROP TABLE IF EXISTS ",@tableopenstk);
	PREPARE qry1 FROM @tabletmp1 ;
	EXECUTE qry1;
	
	SET @tabletmp1 =  CONCAT("CREATE TABLE IF NOT EXISTS ", @tableopenstk, " AS SELECT * FROM inventorytransactiondetail WHERE transactiontypecode = 5 AND quantity > 0 AND routekey= ", @routekey);
	PREPARE qry2 FROM @tabletmp1;
	EXECUTE qry2;
	
	
	
	SET @tabletmp1 =  CONCAT("INSERT INTO routeitemmapping
		SELECT ", @routegroup, "  routeitemgrpcode, itd.itemcode, 0
		FROM ", @tableopenstk, " itd
			LEFT OUTER JOIN routeitemmapping rim ON rim.itemcode = itd.itemcode AND rim.routeitemgrpcode = ", @routegroup," 
		WHERE itd.transactiontypecode = 5 AND itd.routekey = ", @routekey, " AND rim.itemcode IS NULL");
	PREPARE qry3 FROM @tabletmp1;
	EXECUTE qry3;
	
	
	
	SET @tabletmp1 =  CONCAT("UPDATE routemaster SET inventoryreportcontrol = COALESCE((SELECT SUM(quantity) FROM ", @tableopenstk, "), 0) WHERE routecode = ", var_routeid);
	PREPARE qry4 FROM @tabletmp1;
	EXECUTE qry4;
	
	
	
	  
	SET @tabletmp1 =  CONCAT("UPDATE routemaster SET enablestockicon = (SELECT COALESCE(SUM(sld.totunits),0) FROM startingloaddetail sld WHERE sld.status = 0 AND sld.ddate = curdate() AND sld.routecode = ", var_routeid,") WHERE routecode = ", var_routeid);
	PREPARE qry4 FROM @tabletmp1;
	EXECUTE qry4;
	
	
	
	SET @dyn_sql8 = CONCAT("SELECT  controlpanel.flagid, controlpanel.formid, controlpanel.flagname, controlpanel.status, 0 as flagvalue FROM controlpanel ORDER BY flagid");		
	PREPARE s8 FROM @dyn_sql8;
	EXECUTE s8;
	
	SET @dyn_sql9 = CONCAT("SELECT * FROM setup");		
	PREPARE s9 FROM @dyn_sql9;
	EXECUTE s9;
	
	SET @dyn_sql7 = CONCAT("SELECT * FROM company ");
	PREPARE s7 FROM @dyn_sql7;
	EXECUTE s7;
	SET @dyn_sql4 = CONCAT("SELECT 
		sm.salesmancode, sm.salesmanname1, sm.salesmanname2, sm.arbsalesmanname1, sm.messagekey, sm.pricingkey,
		sm.created, sm.cdat, sm.modified, sm.mdat, sup.supervisorname AS memo1, sup.contactno AS memo2, sm.alternatesalesmancode, sm.type, 
		sm.activestatus, sm.parentcompany, sm.ansalesmancode, sm.username, sm.userpassword 
	FROM routemaster rm
		INNER JOIN salesman sm ON sm.salesmancode = rm.salesmancode
		INNER JOIN subareamaster sam ON sam.subareacode = rm.subareacode
		INNER JOIN supervisor sup ON sup.supervisorcode = sam.supervisorcode
	WHERE routecode =  ",var_routeid);
	PREPARE s4 FROM @dyn_sql4;
	EXECUTE s4;
		
	SELECT am.depotcode INTO var_depots FROM areamaster am 
		INNER JOIN subareamaster sam ON am.areacode = sam.areacode INNER JOIN routemaster rm ON sam.subareacode = rm.subareacode  WHERE rm.routecode = var_routeid;	
	
	
	SELECT transferinventoryflag INTO var_transfer FROM setup;
	
	SET @temproutetable = "DROP TABLE IF EXISTS temp_route"; 
	PREPARE qry3 FROM @temproutetable;
	EXECUTE qry3;
	
	IF  var_transfer = '0' THEN
		SET var_condition = CONCAT(" AND rm.routecode = ",var_routeid, " ");
	ELSEIF  var_transfer = '1' THEN
		SET var_condition = CONCAT(" AND rm.depotrouteflag = ","0 ");
	ELSEIF  var_transfer = '2' THEN
		SET var_condition = CONCAT(" AND rm.depotrouteflag = ","1 ");
	ELSE
		SET var_condition = CONCAT(" AND rm.depotrouteflag < ", "2 ");
	END IF;
	
	SET @temproutetable =  CONCAT("CREATE TEMPORARY TABLE IF NOT EXISTS temp_route AS 
			SELECT DISTINCT rm.routecode routecode FROM areamaster am 
				INNER JOIN subareamaster sam ON am.areacode = sam.areacode INNER JOIN routemaster rm ON sam.subareacode = rm.subareacode
			WHERE rm.activestatus = 1 AND am.depotcode = ", var_depots, var_condition);
	PREPARE qry4 FROM @temproutetable;
	EXECUTE qry4;
	
	IF  var_transfer = '2' THEN
		SET @temproutetable =  CONCAT("INSERT INTO temp_route (routecode) VALUES (",var_routeid,")");
		PREPARE qry4 FROM @temproutetable;
		EXECUTE qry4;
	END IF;
	
	
	
	
	CALL sp_update_sequence_numbers(var_routeid);	  
	 
	
	SET @dyn_sql5 = CONCAT("SELECT  route.routecode, 
			route.routename, 
			route.arbroutename, 
			route.subareacode, 
			route.salesmancode, 
			route.created, 
			route.cdat, 
			route.modified, 
			route.mdat, 
			route.memo1, 
			route.memo2, 
			route.hhcordseq, 
			route.hhcinvseq, 
			route.hhccshseq, 
			route.hhcivtseq, 
			route.bodocseq, 
			route.boinvseq, 
			route.vehiclenumber, 
			route.vehicleodometer, 
			route.enablescanneruse, 
			route.password1, 
			route.password2, 
			route.password3, 
			route.password4, 
			route.password5, 
			route.passwordarray01, 
			route.passwordarray02, 
			route.passwordarray03, 
			route.passwordarray04, 
			route.passwordarray05, 
			route.passwordarray06, 
			route.passwordarray07, 
			route.passwordarray08, 
			route.passwordarray09, 
			route.passwordarray10, 
			route.passwordarray11, 
			route.passwordarray12, 
			route.passwordarray13, 
			route.passwordarray14, 
			route.passwordarray15, 
			route.passwordarray16, 
			route.enabledelayprint, 
			route.promptodominput, 
			route.enableeodexpenses, 
			route.enableeodadjchecks, 
			route.enableeodaddchecks, 
			route.reqeoddepositreport, 
			route.reqeodsalesreport, 
			route.reqeodrteactivreport, 
			route.reqeodrtestlmtreport, 
			route.reqeodroutereviewrpt, 
			route.reqeodrtnexchreport, 
			route.reqeodplacementsrpt, 
			route.reqeodprcchgreport, 
			route.reqeodpromosreport, 
			route.reqeodnosalereport, 
			route.reqeodnondelreport, 
			route.reqeodexceptionrpt, 
			route.reqeodunauthbalance, 
			route.reqeodroasummary, 
			route.inventorycaseinput, 
			route.loadreqreportformat, 
			route.includeloadrequest, 
			route.loadoutadjustments, 
			route.autocalculateloadin, 
			route.requireloadin, 
			route.loadsheetreport, 
			route.inventoryvariance, 
			route.invenoversell, 
			route.enablenosale, 
			route.enablepostvoid, 
			route.cashbalance, 
			route.amountdecimaldigits as amountdecimaldigits, 
			route.unloadoversellmessage, 
			route.displayinvsummary, 
			route.alternateroutecode, 
			route.enabledamagedtrxn, 
			route.defaultdeliverydays, 
			route.reqeodnonscannedreport, 
			route.reqeododomlogreport, 
			route.inventoryvalueprint, 
			route.loadaccessafterunload, 
			route.routebalance, 
			route.depotrouteflag, 
			route.routeinventoryvariance, 
			route.allowpopulateload, 
			route.enableaddcustomer, 
			route.allowgctocash, 
			route.usesalesdateflag, 
			route.enablestartdaydatetimeedit, 
			route.newcustomerseqnumber, 
			route.enableloadtransfer, 
			route.loadreqmethod, 
			route.loadreqrolluporders, 
			route.routeprinter, 
			route.depotprinter, 
			route.routetype, 
			route.enablescancustomer, 
			route.enforcecallsequence, 
			route.enablefoclimit, 
			route.enablemiddaytelecom, 
			route.printdocumentnumber, 
			route.activestatus, 
			route.enablecashonlydiscount, 
			route.eodreportcontrol, 
			route.pdcthreshold, 
			route.itemcodedisplay, 
			route.routeitemgrpcode, 
			route.itemdescriptiondisplay, 
			route.lastcustomersequence, 
			route.loadsecurityflag, 
			route.routecatcode, 
			route.usealternatecodes, 
			route.enabledraftcopy, 
			route.boarseq, 
			route.boordseq, 
			route.hhcarseq, 
			route.hhcloadseq, 
			route.boloadseq, 
			route.deliveryroute, 
			route.presalesorder, 
			route.hhcappversion, 
			route.usesequenceflag, 
			route.customerseq, 
			route.routeseqno, 
			route.allowbalcheck, 
			route.allowedradius, 
			route.cmpycode, 
			route.regionmstcode, 
			route.expirylimit, 
			route.runningvalue,
			route.transactionnoseq,
			route.enablefreereason,
			route.maximumgpsallowed,
			route.defaultrequestdays,
			route.defaultweeksetting,
			route.voidoverride,
			route.salesmantargetdays,
			route.hhcinvretseq,
			route.hhcswapseq,
			route.enableautopostingaccount,
			route.variancecustomercode,
			route.forcesettlementdays,
			route.routecreditcheck,
			route.creditlimit routecreditlimit, 
			route.routecreditlimitdays,
			route.itemmustkey, 
			route.inventoryreportcontrol,
			route.enablestockicon,
			route.enablegps,
			route.enforcegps,
			route.updategps,
			route.divisioncode,
			route.viewdeductionflag,
			route.saleslimitflag,
			route.minsaleslimit,
			route.maxsaleslimit,
			route.maxorderholddays,
			route.enforcegeocheckout,
			route.enablefss,
			route.enablegpstracking,
			route.enablearcollection,
			route.directcollection,
			COALESCE(route.enableautocheckout, 0) AS enableautocheckout,
COALESCE(route.autocheckoutaccuracy, 0) AS autocheckoutaccuracy,
    
    TIME_FORMAT(
    COALESCE(route.starttime, '08:00:00'),
    '%H:%i:%s'
) AS starttime,
TIME_FORMAT(
    COALESCE(route.endtime, '17:00:00'),
    '%H:%i:%s'
) AS endtime 
		FROM routemaster AS route LEFT JOIN currencymaster as curr on curr.currencycode = route.amountdecimaldigits
		WHERE route.routecode IN (SELECT routecode FROM temp_route)");
	PREPARE s5 FROM @dyn_sql5;
	EXECUTE s5;
		
	SET @dyn_sql13 = CONCAT(" SELECT
			startendday.routekey,
			startendday.routecode,
			startendday.salesmancode,
			startendday.routestartdate,
			startendday.routestarttime,
			startendday.routeenddate,
			startendday.routeendtime,
			startendday.routestartodometer,
			startendday.routeendodometer,
			startendday.totaldocuments,
			startendday.totalcash,
			startendday.totalchecks,
			startendday.totalcheckrequests,
			startendday.totalorderamount,
			startendday.totalinvoiceamount,
			startendday.totalchargesales,
			startendday.totalcashsales,
			startendday.totalacctsreceivable,
			startendday.totalexpenses,
			startendday.inventoryvariance,
			startendday.totalfullservicesales,
			startendday.totalfullservicecash,
			startendday.routeclosed,
			startendday.cashvariance,
			startendday.modifieddate,
			startendday.modifiedtime,
			startendday.subareacode,
			startendday.supervisorcode,
			startendday.areacode,
			startendday.areamanagercode,
			startendday.depotcode,
			startendday.branchmanagercode,
			startendday.cmpycode,
			startendday.nationalsalesmanagercode,
			startendday.dataconrefnumber,
			startendday.exportedflag,
			startendday.routesequence,
			startendday.currencycode,
			startendday.routejourneyid,
			startendday.data 
		FROM startendday 
		WHERE startendday.routecode = ",var_routeid," AND startendday.routeclosed = 1 ORDER BY 1 DESC LIMIT 0");
	PREPARE s13 FROM @dyn_sql13;
	EXECUTE s13;
    
	SET @dyn_sql10 = CONCAT("SELECT CURRENT_DATE() as synctime");
	PREPARE s10 FROM @dyn_sql10;
	EXECUTE s10;
	
	SELECT * FROM currencymaster WHERE currencycode IN (SELECT amountdecimaldigits FROM routemaster WHERE routecode = var_routeid);
	
	SELECT * FROM TTS_MONTH_TARGET WHERE ROUTECODE = var_routeid AND YEAR = YEAR(CURDATE()) AND MONTH = MONTH(CURDATE());
	
	SET @tabletmp1 = CONCAT("DROP TABLE IF EXISTS ",@tableopenstk);
	PREPARE qry1 FROM @tabletmp1 ;
	EXECUTE qry1;
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_syncicsdata_survey` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_syncicsdata_survey` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_syncicsdata_survey`(
    	IN var_userid INT,
	IN var_deviceid VARCHAR(255),
	IN var_routeid INT,
	IN var_checkmdate INT
    )
BEGIN
 
	DECLARE var_syncdate DATETIME;
	
    
	DECLARE var_where1 VARCHAR(250);
	DECLARE var_where2 VARCHAR(250);
	DECLARE var_where3 VARCHAR(250);
	DECLARE var_where4 VARCHAR(250);
	DECLARE var_where5 VARCHAR(250);
	DECLARE var_where6 VARCHAR(250); 
	DECLARE var_where7 VARCHAR(250);
	DECLARE var_where8 VARCHAR(250);
	DECLARE var_where9 VARCHAR(250);
	DECLARE var_where10 VARCHAR(250);
	DECLARE var_where11 VARCHAR(250);
	DECLARE var_where12 VARCHAR(250);
	SET var_where1 = "";
	SET var_where2 = "";
	SET var_where3 = "";
	SET var_where4 = "";
	SET var_where5 = "";
	SET var_where6 = "";
	SET var_where7 = "";
	SET var_where8 = "";
	SET var_where9 = "";
	SET var_where10 = "";
	SET var_where11 = "";
	SET var_where12 = "";
	
	SET var_checkmdate = 0;
	
	IF var_checkmdate = 1 THEN
	
	SELECT syncdate INTO var_syncdate FROM tbl_syncservice WHERE userid = var_userid AND deviceid = var_deviceid;
	   IF var_syncdate != '' THEN
		
		
		SET var_where1 = CONCAT(" AND posmaster.mdat > '",var_syncdate,"' ");
		SET var_where2 = CONCAT(" AND customerposinventory.mdat > '",var_syncdate,"' ");
		SET var_where3 = CONCAT(" AND customerposlimit.mdat > '",var_syncdate,"' ");
		SET var_where4 = CONCAT(" AND posinstructions.mdat > '",var_syncdate,"' ");
		SET var_where5 = CONCAT(" AND customersurveyplan.mdat > '",var_syncdate,"' ");
		SET var_where6 = CONCAT(" AND customersurveykeyplan.mdat > '",var_syncdate,"' ");
		SET var_where7 = CONCAT(" AND customersurveykey.mdat > '",var_syncdate,"' ");
		SET var_where8 = CONCAT(" AND activestatus = 1 AND  customersurveydefinition.mdat > '",var_syncdate,"' ");
		SET var_where9 = CONCAT(" AND customersurveydefassign.cdat > '",var_syncdate,"' ");
		SET var_where10 = CONCAT(" AND lookupindexdetail.mdat > '",var_syncdate,"' ");
		
	   END IF;
	END IF;
		
		
    
		SET @dyn_sql1 = CONCAT("SELECT itemcode ,alternatecode, itemdescription , arbitemdescription , itemvalue , inventorytype , created , cdat , modified , mdat , activestatus FROM posmaster WHERE 1=1 ",var_where1);
		PREPARE s1 FROM @dyn_sql1;
		EXECUTE s1;
        
    
		SET @dyn_sql2 = CONCAT("SELECT customercode,
						itemcode,
						quantity,
						serialnumber
						FROM customerposinventory WHERE 1=1 ",var_where2);
		PREPARE s2 FROM @dyn_sql2;
		EXECUTE s2;
        
	
		SET @dyn_sql3 = CONCAT("SELECT customercode,
						poslimit,
						posbalance
						FROM customerposlimit WHERE 1=1",var_where3);
		PREPARE s3 FROM @dyn_sql3;
		EXECUTE s3;
	
    
		SET @dyn_sql4 = CONCAT("SELECT posinstructioncode,
						posinstructionname,
						arbposinstructionname,
						created,
						cdat,
						modified,
						mdat
						FROM posinstructions WHERE 1=1 ",var_where4);
		PREPARE s4 FROM @dyn_sql4;
		EXECUTE s4;
        
        
    
    SET @dyn_sql5 = CONCAT("SELECT surveyplankey,
                    surveysequencenumber,
                    surveymandatory,
                    surveydescription,
                    arbsurveydescription
                    FROM customersurveyplan WHERE 1=1 ",var_where5);
    PREPARE s5 FROM @dyn_sql5;
    EXECUTE s5;
    
    
		SET @dyn_sql6 = CONCAT("SELECT primary_key,
						surveyplankey,
						surveykey
						FROM customersurveykeyplan WHERE 1=1 ",var_where6);
		PREPARE s6 FROM @dyn_sql6;
		EXECUTE s6;
        
    
		SET @dyn_sql7 = CONCAT("SELECT surveykey,
						surveydescription,
						arbsurveydescription,
						surveyplankey,
						created,
						cdat,
						modified,
						mdat,
						activestatus
						FROM customersurveykey WHERE 1=1 ",var_where7);
		PREPARE s7 FROM @dyn_sql7;
		EXECUTE s7;
	
    
    
		SET @dyn_sql8 = CONCAT("SELECT surveydefkey,
						surveyindex,
						lineindex,
						surveyrectype,
						surveyprompt,
						arbsurveyprompt,
						responselength,
						responsedecimalpos,
						lookuptype,
						lookupindex,
						retainvalue,
						activestatus,
						created,
						cdat,
						modified,
						mdat
						FROM customersurveydefinition WHERE 1=1 ",var_where8);
		PREPARE s8 FROM @dyn_sql8;
		EXECUTE s8;
		
		
		
			
    
		SET @dyn_sql9 = CONCAT("SELECT surveyplankey,
						surveydefkey
						FROM customersurveydefassign WHERE 1=1 ",var_where9);
		PREPARE s9 FROM @dyn_sql9;
		EXECUTE s9;	
		
		
		
		
    
		SET @dyn_sql10 = CONCAT("SELECT primary_key,
						transactionkey,
						description,
						arbdescription
						FROM lookupindexdetail WHERE 1=1 ",var_where10);
		PREPARE s10 FROM @dyn_sql10;
		EXECUTE s10;
    
		SET @dyn_sql11 = CONCAT("SELECT visualcode,
						visualdescription,
						remarks,
						arbvisualdescription
						FROM visualheader WHERE 1=1 ",var_where11);
		PREPARE s11 FROM @dyn_sql11;
		EXECUTE s11;
		
		
		SET @dyn_sql12 = CONCAT("SELECT visualdetail_id,
						visualcode,
						imagename,
						imagepath,imagedescription
						FROM visualdetail WHERE 1=1 ",var_where12);
		PREPARE s12 FROM @dyn_sql12;
		EXECUTE s12;			
    
   
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_syncicsdata_visualdata` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_syncicsdata_visualdata` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_syncicsdata_visualdata`(
    IN var_userid INT,	
     IN var_routeid INT
)
BEGIN
  
	SET @dyn_sql1 = CONCAT("SELECT visualcode,
						visualdescription,						
						arbvisualdescription,remarks
						FROM visualheader WHERE 1=1");
	PREPARE s1 FROM @dyn_sql1;
	EXECUTE s1;
		
        
        
	SET @dyn_sql2 = CONCAT("SELECT visualdetail_id,
						visualcode,
						imagename,
						imagepath,imagedescription
						FROM visualdetail WHERE 1=1");
	PREPARE s2 FROM @dyn_sql2;
	EXECUTE s2;   
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_tablet_check_load` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_tablet_check_load` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_tablet_check_load`(
    IN var_userid INT,	
	IN var_routeid INT
	)
BEGIN
    DECLARE sts INT DEFAULT 0;
    SELECT STATUS INTO sts FROM controlpanel WHERE controlpanel.flagid=72;   
     IF sts = 0 THEN
   
     SELECT 1 AS cnt ; 
     
     ELSE
      
         
      SELECT COUNT(*) AS cnt FROM startingloaddetail AS sd
		WHERE 1=1 and sd.status = 0 AND sd.routecode = var_routeid AND DATE(sd.ddate)=DATE(CURRENT_DATE()) AND sd.salesmancode = var_userid;
      
     End if ;		
     		
		
     
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_tablet_deletemaster` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_tablet_deletemaster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_tablet_deletemaster`(
IN tblname VARCHAR(255),
IN var_userid INT,
IN var_deviceid VARCHAR(255)
)
BEGIN
DECLARE var_syncdate DATETIME;
    
    SELECT syncdate INTO var_syncdate FROM tbl_syncservice WHERE userid = var_userid AND deviceid = var_deviceid;
    
    SELECT CODE,tablename,recordid, show_pk(tablename)AS fieldname FROM logmaster WHERE operation_type='delete' AND cdat > var_syncdate AND tablename  IN('customermaster','salesman','routemaster','startingloaddetail','itemgroup','salescalender','promoplandetail','promoplanheader','promokeydetail','promokeyheader','promotionassignmentadvanced','promotioncontrol','bankmaster','productgroupheader','productgroupdetail','companydetail','posmaster','customerposinventory','customerposlimit','posinstructions','nonservreasons','expreasons','expiryreturnreasons','retitmreasons','freegoodreasons','voidreasons','customersurveyplan','customersurveykeyplan','customersurveykey','customersurveydefinition','customersurveydefassign','lookupindexdetail','pricingdetail1','customerpricing1');
    
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_tablet_get_deliveryorderstatus` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_tablet_get_deliveryorderstatus` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_tablet_get_deliveryorderstatus`(
    IN var_userid INT,	
    IN var_routeid INT
	)
BEGIN
SELECT RM.routecode,SM.salesmancode,CM.customercode,CM.customername,IFNULL(T.ordernumber,0) AS ordernumber,
IFNULL(T.orderamount,0) AS orderamount,IFNULL(T.orderdate,0) AS orderdate,IFNULL(T.invoicenumber,0) AS invoicenumber,
IFNULL(T.invoiceamount,0) AS invoiceamount,
IFNULL(T.invoicedate,0) AS invoicedate,IFNULL(T.differenceamount,0) AS differenceamount,
case when T.STATUS is null or T.STATUS = '' then 0 else T.STATUS end as STATUS, 
IFNULL(cm.alternatecode,0) AS alternatecode,IFNULL(T.ordernumber,0) AS alternateordernumber,
IFNULL(T.invoicenumber,0) AS alternateinvoicenumber,IFNULL(T.differencedate,0)	AS differencedate,
CASE WHEN T.ordercategory IS NULL OR T.ordercategory = '' THEN 0 ELSE T.ordercategory END AS ordercategory					
FROM orderstatus T INNER JOIN Salesman SM ON SM.AlternateSalesmancode=T.Salesmancode
INNER JOIN routemaster rm ON rm.salesmancode=sm.salesmancode
INNER JOIN customermaster cm ON cm.alternatecode=T.Customercode   WHERE SM.salesmancode=var_userid; 
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_tablet_get_warehousestock` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_tablet_get_warehousestock` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_tablet_get_warehousestock`(
    IN var_userid INT,	
	IN var_routeid INT
	)
BEGIN
/*
SELECT ws.warehousecode,ws.trandate,ws.itemcode,
IFNULL(ws.cases,0)AS cases,IFNULL(ws.units,0) AS units,
CASE WHEN (ws.totunits<im.unitspercase) THEN im.unitspercase ELSE ws.totunits END  AS totunits ,
IFNULL(ws.upc,0) AS upc,IFNULL(ws.caseprice,0) AS caseprice,IFNULL(ws.eachprice,0) AS eachprice,IFNULL(ws.balanceqty,0) AS balanceqty 
   FROM warehousestock ws  
   
        INNER  JOIN routemaster rm ON  rm.division= WS.WAREHOUSECODE OR  rm.memo1=ws.WAREHOUSECODE       
    INNER JOIN routeitemgrp rtg ON rtg.routeitemgrpcode=rm.routeitemgrpcode
    INNER JOIN routeitemmapping  rim ON rim.routeitemgrpcode =rtg.routeitemgrpcode 
     INNER JOIN itemmaster im ON im.actualitemcode = rim.itemcode 
   AND rim.itemcode=ws.itemcode
    WHERE rm.routecode=var_routeid AND ws.totunits>0; 
     
   */
   /*  ARUN CHANGED THE QRY ON APR 2 2023 */ 
    
SELECT 
	ws.warehousecode,
	ws.trandate,ws.itemcode,
	IFNULL(ws.cases,0)AS cases,
	IFNULL(ws.units,0) AS units,
	CASE WHEN (ws.totunits<im.unitspercase) THEN im.unitspercase ELSE ws.totunits END  AS totunits ,
	IFNULL(ws.upc,0) AS upc,
	IFNULL(ws.caseprice,0) AS caseprice,
	IFNULL(ws.eachprice,0) AS eachprice,
	IFNULL(ws.balanceqty,0) AS balanceqty 
FROM warehousestock ws             
        INNER JOIN SFA_ROUTE_WH_MAP RWM ON RWM.ROUTE_CODE = var_routeid AND WS.WAREHOUSECODE = RWM.WH_CODE
        INNER JOIN routemaster rm ON  rm.ROUTECODE= RWM.ROUTE_CODE
	INNER JOIN routeitemgrp rtg ON rtg.routeitemgrpcode=rm.routeitemgrpcode
	INNER JOIN routeitemmapping  rim ON rim.routeitemgrpcode =rtg.routeitemgrpcode 
	INNER JOIN itemmaster im ON im.actualitemcode = rim.itemcode AND rim.itemcode=ws.itemcode
WHERE rWM.route_code=var_routeid AND ws.totunits>0 ;
    
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_transactiondata` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_transactiondata` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_transactiondata`(
	IN var_routekey VARCHAR(255)
    )
BEGIN
	
	SELECT 'SEDY' TYPE, COUNT(*) CloudCount FROM startendday WHERE routekey= var_routekey UNION
	
	SELECT 'IVTH' TYPE, COUNT(*) CloudCount FROM inventorytransactionheader WHERE routekey= var_routekey AND DATA=0 AND voidflag = 0 	
	-- SELECT 'IVTH' TYPE, 3 CloudCount FROM inventorytransactionheader WHERE routekey= var_routekey AND DATA=0 AND voidflag = 0 
		
	UNION
	SELECT 'IVTD' TYPE, COUNT(*) CloudCount FROM inventorytransactiondetail WHERE routekey= var_routekey UNION
	SELECT 'IVSD' TYPE, COUNT(*) CloudCount FROM inventorysummarydetail WHERE routekey= var_routekey UNION
	
	SELECT 'RSCS' TYPE, COUNT(*) CloudCount FROM routesequencecustomerstatus WHERE routekey= var_routekey UNION
	-- SELECT 'RSCS' TYPE, 14 CloudCount FROM routesequencecustomerstatus WHERE routekey= var_routekey UNION
	SELECT 'RSCC' TYPE, IFNULL(SUM(servicedflag),0) CloudCount FROM routesequencecustomerstatus WHERE routekey= var_routekey UNION
	-- SELECT 'RSCC' TYPE, 23 CloudCount FROM routesequencecustomerstatus WHERE routekey= var_routekey UNION
	-- SELECT 'CVLG' TYPE, 6 CloudCount FROM customervisitlog WHERE routekey= var_routekey UNION
	SELECT 'CVLG' TYPE, COUNT(*) CloudCount FROM customervisitlog WHERE routekey= var_routekey UNION
	
	
	SELECT 'INVH' TYPE, COUNT(*) CloudCount FROM invoiceheader WHERE routekey = var_routekey 
	-- SELECT 'INVH' TYPE, 9 CloudCount FROM invoiceheader WHERE routekey= var_routekey 
	 
	UNION
	SELECT 'INVD' TYPE, COUNT(*) CloudCount FROM invoicedetail WHERE routekey= var_routekey UNION
	SELECT 'INVR' TYPE, COUNT(*) CloudCount FROM invoicerxddetail WHERE routekey= var_routekey UNION
	SELECT 'BAED' TYPE, COUNT(*) CloudCount FROM batchexpirydetail WHERE routekey= var_routekey UNION
	SELECT 'SAOH' TYPE, COUNT(*) CloudCount FROM salesorderheader WHERE routekey= var_routekey
	-- SELECT 'SAOH' TYPE,9  CloudCount FROM salesorderheader WHERE routekey= var_routekey
	
	UNION
	SELECT 'SAOD' TYPE, COUNT(*) CloudCount FROM salesorderdetail WHERE routekey= var_routekey UNION
	SELECT 'SAOR' TYPE, COUNT(*) CloudCount FROM orderrxddetail WHERE routekey= var_routekey UNION
	SELECT 'PRMD' TYPE, COUNT(*) CloudCount FROM promotiondetail WHERE routekey= var_routekey UNION
	-- SELECT 'ARHR' TYPE, 1 CloudCount FROM arheader WHERE routekey= var_routekey 
	 SELECT 'ARHR' TYPE, COUNT(*) CloudCount FROM arheader WHERE routekey= var_routekey 
	
	UNION
	SELECT 'ARDL' TYPE, COUNT(*) CloudCount FROM ardetail WHERE routekey= var_routekey UNION 
       -- SELECT DISTINCT 'CCDS' TYPE, 13 CloudCount FROM cashcheckdetail ccd WHERE ccd.routekey = var_routekey 
	
	SELECT DISTINCT 'CCDS' TYPE, 
		COALESCE((SELECT COUNT(ih.invoicenumber) cc FROM invoiceheader ih WHERE ih.routekey = ccd.routekey AND ih.paymenttype IN (0,4) AND ih.voidflag = 0),0) +
		COALESCE((SELECT COUNT(ah.invoicenumber) cc FROM arheader ah WHERE ah.routekey = ccd.routekey AND ah.voidflag = 0),0) CloudCount
		FROM cashcheckdetail ccd WHERE ccd.routekey = var_routekey 
			
		
	UNION
        SELECT 'CUOC' TYPE, COUNT(*) CloudCount FROM customeroperationscontrol WHERE routekey= var_routekey UNION
	-- SELECT 'CUOC' TYPE, 24 CloudCount FROM customeroperationscontrol WHERE routekey= var_routekey UNION
	SELECT 'CPPD' TYPE, COUNT(*) CloudCount FROM customerpromotionplandetail WHERE routekey= var_routekey UNION
	SELECT 'SADS' TYPE, COUNT(*) CloudCount FROM surveyauditdetail WHERE routekey= var_routekey UNION
	SELECT 'PECD' TYPE, COUNT(*) CloudCount FROM posequipmentchangedetail WHERE routekey= var_routekey UNION
	SELECT 'CUID' TYPE, COUNT(*) CloudCount FROM customerinventorydetail WHERE routekey= var_routekey UNION
	SELECT 'NOSC' TYPE, COUNT(*) CloudCount FROM nonservicedcustomer WHERE routekey= var_routekey UNION
	SELECT 'NOSH' TYPE, COUNT(*) CloudCount FROM nosalesheader WHERE routekey= var_routekey UNION
	SELECT 'AORL' TYPE, COUNT(*) CloudCount FROM t_access_override_log WHERE routekey= var_routekey;
	
	
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_updatesyncdate` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_updatesyncdate` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_updatesyncdate`(
	in var_userid int,
	in var_deviceid varchar(250),
	IN var_routeid INT
    )
BEGIN
SELECT routecode INTO @route FROM routemaster WHERE salesmancode = var_userid;
INSERT INTO tbl_syncservice(userid,deviceid,syncdate,synctime,routecode)
	VALUES(var_userid, var_deviceid, CURDATE(), CURTIME(), @route);
	
SELECT LAST_INSERT_ID() AS insertrow;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_update_invoicetransactionkey` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_update_invoicetransactionkey` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_update_invoicetransactionkey`(
		IN var_transactionkey BIGINT(20),
		IN var_routekey BIGINT(20),
		IN var_visitkey BIGINT(20),
		IN var_oldtransactionkey BIGINT(20)
		)
BEGIN
	
	UPDATE invoicerxddetail SET transactionkey = var_transactionkey	WHERE `routekey` = var_routekey AND `visitkey` =var_visitkey AND `transactionkey` =var_oldtransactionkey;
	
	UPDATE invoicerxddetail SET transactionkey = var_transactionkey	WHERE `routekey` = var_routekey AND `visitkey` =var_visitkey AND `transactionkey` =var_oldtransactionkey;
	
	UPDATE invoicerxddetail SET transactionkey = var_transactionkey	WHERE `routekey` = var_routekey AND `visitkey` =var_visitkey AND `transactionkey` =var_oldtransactionkey;
	
	UPDATE invoicerxddetail SET transactionkey = var_transactionkey	WHERE `routekey` = var_routekey AND `visitkey` =var_visitkey AND `transactionkey` =var_oldtransactionkey;
	
	UPDATE invoicerxddetail SET transactionkey = var_transactionkey	WHERE `routekey` = var_routekey AND `visitkey` =var_visitkey AND `transactionkey` =var_oldtransactionkey;
	
        UPDATE invoicerxddetail SET transactionkey = var_transactionkey	WHERE `routekey` = var_routekey AND `visitkey` =var_visitkey AND `transactionkey` =var_oldtransactionkey;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_upload_ar_detl` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_upload_ar_detl` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_upload_ar_detl`(
					IN var_routekey DECIMAL(28,0),
					IN var_visitkey DECIMAL(28,0),
					IN var_transactionkey DECIMAL(28,0),
					IN var_invoicenumber DECIMAL(18,0),
					IN var_invoicedate DATETIME,
					IN var_totalinvoiceamount DECIMAL(19,4),
					IN var_onacctreasoncode INT(11),
					IN var_amountpaid DECIMAL(19,4),
					IN var_invoicebalance DECIMAL(19,4),
					IN var_arcollectiontype INT(11),
					IN var_chequestatusindicator DECIMAL(18,0),
					IN var_sapchequestatusindicator VARCHAR(50),
					IN var_currencycode DECIMAL(18,0),
					IN var_pdcbalance DECIMAL(19,4),
					IN var_alternateinvoicenumber VARCHAR(30),
					IN var_salesmancode BIGINT(18),
					IN var_deductionamount DECIMAL(19,4)
				)
BEGIN
	DECLARE txnkey BIGINT DEFAULT 0;
	
	SELECT transactionkey INTO txnkey FROM arheader WHERE `routekey` = var_routekey AND `visitkey` =var_visitkey ;
	IF txnkey <> 0 THEN
		
		INSERT INTO ardetail SET 	
			routekey = var_routekey,
			visitkey = var_visitkey,
			transactionkey = txnkey,
			invoicenumber = var_invoicenumber,
			salesmancode=var_salesmancode,
			invoicedate = var_invoicedate,
			totalinvoiceamount = var_totalinvoiceamount,
			onacctreasoncode = var_onacctreasoncode,
			amountpaid = var_amountpaid,
			invoicebalance = var_invoicebalance,
			arcollectiontype = var_arcollectiontype,
			chequestatusindicator = var_chequestatusindicator,
			referenceno = var_sapchequestatusindicator,
			currencycode = get_default_currencycode_routekey(var_routekey),
			pdcbalance = var_pdcbalance,
			alternateinvoicenumber = var_alternateinvoicenumber,
			receivedtime = CURTIME(),
			deductionamount = var_deductionamount
			ON DUPLICATE KEY UPDATE transactionkey = txnkey ;						
			
		UPDATE customerinvoice SET amountpaid = amountpaid + var_amountpaid, invoicebalance = invoicebalance - var_amountpaid WHERE `invoicenumber` = var_invoicenumber;
		
	END IF;								
	
 				
	SELECT var_transactionkey AS lastid;	
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_upload_inv_detl` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_upload_inv_detl` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_upload_inv_detl`(
	IN var_routekey DECIMAL(28,0),
	IN var_visitkey DECIMAL(28,0),
	IN var_transactionkey BIGINT(20),
	IN var_itemcode DECIMAL(18,0),
	IN var_salesqty DECIMAL(18,0),
	IN var_returnqty DECIMAL(18,0),
	IN var_damagedqty DECIMAL(18,0),
	IN var_freesampleqty DECIMAL(18,0),
	IN var_salesprice DECIMAL(18,6),
	IN var_returnprice DECIMAL(18,6),
	IN var_stdsalesprice DECIMAL(18,6),
	IN var_stdreturnprice DECIMAL(18,6),
	IN var_promoqty DECIMAL(18,0),
	IN var_salesitemexcisetax DECIMAL(19,4),
	IN var_salesitemgsttax DECIMAL(19,4),
	IN var_returnitemexcisetax DECIMAL(19,4),
	IN var_returnitemgsttax DECIMAL(19,4),
	IN var_damageditemexcisetax DECIMAL(19,4),
	IN var_damageditemgsttax DECIMAL(19,4),
	IN var_fgitemexcisetax DECIMAL(19,4),
	IN var_fgitemgsttax DECIMAL(19,4),
	IN var_promoitemexcisetax DECIMAL(19,4),
	IN var_promoitemgsttax DECIMAL(19,4),
	IN var_coopid CHAR(10),
	IN var_batchdetailkey DECIMAL(18,0),
	IN var_salescaseprice DECIMAL(18,6),
	IN var_returncaseprice DECIMAL(18,6),
	IN var_stdsalescaseprice DECIMAL(18,6),
	IN var_stdreturncaseprice DECIMAL(18,6),
	IN var_goodreturnprice DECIMAL(18,6),
	IN var_goodreturncaseprice DECIMAL(18,6),
	IN var_stdgoodreturncaseprice DECIMAL(18,6),
	IN var_stdgoodreturnprice DECIMAL(18,6),
	IN var_expiryqty DECIMAL(18,0),
	IN var_currencycode DECIMAL(18,0),
	IN var_returnfreeqty DECIMAL(18,0),
	IN var_manualfreeqty DECIMAL(18,0),
	IN var_limitedfreeqty DECIMAL(18,0),
	IN var_rebaterentqty DECIMAL(18,0),
	IN var_fixedrentqty DECIMAL(18,0),
	IN var_pricechgindicator DECIMAL(18,0),
	IN var_discountamount DECIMAL(19,4),
	IN var_discountpercentage DECIMAL(18,6),
	IN var_promoamount DECIMAL(19,4),
	IN var_replacementqty DECIMAL(18,0),
	IN var_replacementprice DECIMAL(18,6),
	IN var_replacementcaseprice DECIMAL(18,6),
	IN var_promovalue DECIMAL(19,4),
	IN var_mdat DATETIME,
	IN var_sales_amount DECIMAL(18,4),
	IN var_returnpromovalue DECIMAL(19,4),
	IN var_returnpromoamount DECIMAL(19,4),
	IN var_return_amount DECIMAL(19,4),
	IN var_returnfreesampleqty DECIMAL(18,0),
	IN var_roundtotalsalesamount DECIMAL(18,4),
	IN var_diffround DECIMAL(18,4),
	IN var_linetotal DECIMAL(18,4) 
)
BEGIN   
	DECLARE txnkey BIGINT DEFAULT 0;
	
	SELECT transactionkey INTO txnkey FROM invoiceheader WHERE `routekey` = var_routekey AND `visitkey` =var_visitkey ;
	IF txnkey <> 0 THEN
	
		INSERT INTO invoicedetail SET 
		routekey = var_routekey,
		visitkey = var_visitkey,
		transactionkey = txnkey,
		itemcode = var_itemcode,
		salesqty = var_salesqty,
		returnqty = var_returnqty,
		damagedqty = var_damagedqty,
		freesampleqty = var_freesampleqty,
		salesprice = var_salesprice,
		returnprice = var_returnprice,
                stdsalesprice = var_stdsalesprice,
                stdreturnprice = var_stdreturnprice,
                promoqty = var_promoqty,
                salesitemexcisetax = var_salesitemexcisetax,
                salesitemgsttax = var_salesitemgsttax,
		returnitemgsttax = var_returnitemgsttax,
		damageditemexcisetax = var_damageditemexcisetax,
		damageditemgsttax = var_damageditemgsttax,
		fgitemexcisetax = var_fgitemexcisetax,
		fgitemgsttax = var_fgitemgsttax,
		promoitemexcisetax = var_promoitemexcisetax,
		promoitemgsttax = var_promoitemgsttax,
		coopid = var_coopid,
		batchdetailkey = var_batchdetailkey,
		salescaseprice = var_salescaseprice,
		returncaseprice = var_returncaseprice,
		stdsalescaseprice = var_stdsalescaseprice,
		stdreturncaseprice = var_stdreturncaseprice,
		goodreturnprice = var_goodreturnprice,
		goodreturncaseprice = var_goodreturncaseprice,
		stdgoodreturncaseprice = var_stdgoodreturncaseprice,
		stdgoodreturnprice = var_stdgoodreturnprice,
		expiryqty = var_expiryqty,
		currencycode = get_default_currencycode_routekey(var_routekey),
		returnfreeqty = var_returnfreeqty,
		manualfreeqty = var_manualfreeqty,
		limitedfreeqty = var_limitedfreeqty,
		rebaterentqty = var_rebaterentqty,
		fixedrentqty = var_fixedrentqty,
		pricechgindicator = var_pricechgindicator,
		discountamount = var_discountamount,
		discountpercentage = var_discountpercentage,
		promoamount = var_promoamount,
		replacementqty = var_replacementqty,
		replacementprice = var_replacementprice,
		replacementcaseprice = var_replacementcaseprice,
		promovalue = var_promovalue,
		mdat = var_mdat,
		sales_amount = var_sales_amount,
		returnpromovalue = var_returnpromovalue,
		returnpromoamount = var_returnpromoamount,
		return_amount = var_return_amount,
		returnfreesampleqty = var_returnfreesampleqty,
		roundsalesamount=var_roundtotalsalesamount,
		diffround=var_diffround,
		linetotal = var_linetotal,
		receivedtime = CURTIME()
		ON DUPLICATE KEY UPDATE transactionkey = txnkey ;
		
	END IF;
	SELECT var_routekey AS lastid; 
	
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_version_check` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_version_check` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_version_check`(
	var_route_code VARCHAR(255),	
	var_curvrs varchar(50)
    )
BEGIN
	
	declare vno varchar(50) default '0';
	declare vsts VARCHAR(50)  default '0';
	
	
	SELECT VER_NO, VER_STS INTO vno, vsts FROM route_version_map 
	WHERE route_code = var_route_code limit 1;	
	
	
	if vsts = 1 and vno <> var_curvrs then
		select 0 as STATUS;			
	ELSE
		SELECT 1 AS  STATUS;
	end if;
	
	
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `TEMP_STRIKE` */

/*!50003 DROP PROCEDURE IF EXISTS  `TEMP_STRIKE` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `TEMP_STRIKE`(
    IN vardivisioncode VARCHAR(500),
    IN route_month INT,
    IN varYear INT
    )
BEGIN
 
IF vardivisioncode = '0' THEN
INSERT INTO TTS_STRIKE_YTD 
SELECT MONTH(sed.`routestartdate`) route_, rm.divisioncode,sm.salesmancode AS salesmancode,sm.salesmanname1,  sm.arbsalesmanname1, 
0 AS Mtd_odometer,
0 AS plannedcalls, 
0 AS actualcalls, 0 AS unschedulecall,
0 AS cashsale, 0 AS creditsale , 
0 AS orders,
0 AS `returns`,
0 AS productivecalls, 
0 AS totalreceipt,
0 AS strikerate,
0 AS productiverate,
0 AS CustomerFaceTime,
0 AS OTPUsedCount,
0 AS settlementskipeddays,
0 AS CFTMin
FROM startendday sed	
INNER JOIN routemaster rm ON sed.routecode = rm.routecode
INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
WHERE 1=1  AND YEAR(sed.routestartdate) = varYear  
GROUP BY sed.routecode  ;
ELSE
 
INSERT INTO TTS_STRIKE_YTD 
SELECT MONTH(sed.`routestartdate`) route_month, rm.divisioncode,sm.salesmancode AS salesmancode,sm.salesmanname1,  sm.arbsalesmanname1, 
0 AS Mtd_odometer,
0 AS plannedcalls, 
0 AS actualcalls, 0 AS unschedulecall,
0 AS cashsale, 0 AS creditsale , 
0 AS orders, 
0 AS `RETURNS`, 
0 AS productivecalls, 
0 AS totalreceipt,
0 AS strikerate,
0 AS productiverate,
0 AS CustomerFaceTime,
0 AS OTPUsedCount,
0 AS settlementskipeddays,
0 AS CFTMin
FROM startendday sed	
INNER JOIN routemaster rm ON sed.routecode = rm.routecode
INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
INNER JOIN divisionmaster dm ON dm.divisionname=rm.divisioncode
WHERE FIND_IN_SET(dm.divisioncode, vardivisioncode) AND YEAR(sed.routestartdate) = varYear  
GROUP BY sed.routecode  ;
END IF;
UPDATE TTS_STRIKE_YTD t INNER JOIN (
SELECT salesmancode,SUM(CASE WHEN routeendodometer =0 THEN 0 ELSE IFNULL(routeendodometer-routestartodometer,0) END) AS mtdodometer 
FROM startendday sed1
WHERE MONTH (sed1.routestartdate) = route_month AND YEAR(sed1.routestartdate) = varYear GROUP BY salesmancode 
) u
ON t.salesmancode=u.salesmancode
SET t.Mtd_odometer=u.mtdodometer;
UPDATE TTS_STRIKE_YTD t INNER JOIN (
SELECT  Salesmancode,SUM(callcount) AS plannedcalls FROM (
SELECT sed1.salesmancode,rs.routekey ,COUNT(*) AS callcount FROM routesequencecustomerstatus rs 
INNER JOIN startendday sed1 ON rs.routekey=sed1.routekey AND sed1.routecode=rs.routecode 
WHERE rs.schelduledflag = 1 AND 
MONTH (sed1.routestartdate) = route_month AND YEAR(sed1.routestartdate) = varYear
GROUP BY rs.routekey,rs.customercode)t
GROUP BY salesmancode
) u
ON t.salesmancode=u.salesmancode
SET t.plannedcalls=u.plannedcalls;
UPDATE TTS_STRIKE_YTD t INNER JOIN (
SELECT  Salesmancode,SUM(callcount) AS ActualCalls FROM (
SELECT sed1.salesmancode,rs.routekey ,COUNT(*) AS callcount FROM routesequencecustomerstatus rs 
INNER JOIN startendday sed1 ON rs.routekey=sed1.routekey AND sed1.routecode=rs.routecode 
WHERE rs.servicedflag  = 1 AND 
MONTH (sed1.routestartdate) = route_month AND YEAR(sed1.routestartdate) = varYear
GROUP BY rs.routekey,rs.customercode)t
GROUP BY salesmancode
) u
ON t.salesmancode=u.salesmancode
SET t.actualcalls=u.ActualCalls;
UPDATE TTS_STRIKE_YTD t INNER JOIN 
(SELECT ih.salesmancode,COUNT(*) AS cashSalescount  FROM INVOICEHEader ih 
INNER JOIN startendday sed ON sed.routekey=ih.routekey AND sed.routecode=ih.routecode 
INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
WHERE  ih.immediatepaid > 0 AND ih.voidflag = 0  AND (MONTH(sed.routestartdate) = route_month AND YEAR(sed.routestartdate) = varYear)  GROUP BY ih.salesmancode) 
 u
ON t.salesmancode=u.salesmancode
SET t.cashsale=u.cashSalescount;
UPDATE TTS_STRIKE_YTD t INNER JOIN 
(SELECT ih.salesmancode,COUNT(*) AS creditsale  FROM INVOICEHEader ih 
INNER JOIN startendday sed ON sed.routekey=ih.routekey AND sed.routecode=ih.routecode 
INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
WHERE  ih.immediatepaid =0 AND totalsalesamount>0 AND ih.voidflag = 0  AND (MONTH(sed.routestartdate) = route_month AND YEAR(sed.routestartdate) = varYear)  GROUP BY ih.salesmancode )
 u
ON t.salesmancode=u.salesmancode
SET t.creditsale=u.creditsale;
UPDATE TTS_STRIKE_YTD t INNER JOIN 
(SELECT ih.salesmancode,COUNT(*) AS grvcount  FROM INVOICEHEader ih 
INNER JOIN startendday sed ON sed.routekey=ih.routekey AND sed.routecode=ih.routecode 
INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
WHERE ih.totalinvoiceamount < 0  AND ih.totalsalesamount=0  AND ih.voidflag = 0  AND (MONTH(sed.routestartdate) = route_month AND YEAR(sed.routestartdate) = varYear)  GROUP BY ih.salesmancode )
 u
ON t.salesmancode=u.salesmancode
SET t.returns=u.grvcount;
UPDATE TTS_STRIKE_YTD t INNER JOIN 
(SELECT ih.salesmancode,COUNT(*) AS ordercount  FROM Salesorderheader ih 
INNER JOIN startendday sed ON sed.routekey=ih.routekey AND sed.routecode=ih.routecode 
INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
WHERE ih.voidflag = 0  AND (MONTH(sed.routestartdate) = route_month AND YEAR(sed.routestartdate) = varYear)  GROUP BY ih.salesmancode )
 u
ON t.salesmancode=u.salesmancode
SET t.orders=u.ordercount;
UPDATE TTS_STRIKE_YTD t INNER JOIN (
SELECT  Salesmancode,SUM(callcount) AS unschedulecall FROM (
SELECT sed1.salesmancode,rs.routekey ,COUNT(*) AS callcount FROM routesequencecustomerstatus rs 
INNER JOIN startendday sed1 ON rs.routekey=sed1.routekey AND sed1.routecode=rs.routecode 
WHERE rs.servicedflag = 1 AND  rs.schelduledflag = 0  AND 
MONTH (sed1.routestartdate) = route_month AND YEAR(sed1.routestartdate) = varYear
GROUP BY rs.routekey,rs.customercode)t
GROUP BY salesmancode
) u
ON t.salesmancode=u.salesmancode
SET t.unschedulecall=u.unschedulecall;
UPDATE TTS_STRIKE_YTD t INNER JOIN 
(SELECT ah.salesmancode,COUNT(*) AS receipts  FROM arheader ah 
INNER JOIN startendday sed ON ah.routekey= sed.routekey AND ah.routecode= sed.routecode 
INNER JOIN salesman sm  ON sed.salesmancode=sm.salesmancode 
WHERE  1=1   AND (MONTH(sed.routestartdate) = route_month AND YEAR(sed.routestartdate) = varYear)  GROUP BY ah.salesmancode )
 u
ON t.salesmancode=u.salesmancode
SET t.totalreceipt=u.receipts;
 
 UPDATE TTS_STRIKE_YTD t INNER JOIN (
SELECT  Salesmancode,COUNT(DISTINCT customercode,routestartdate) AS productivecalls FROM (
SELECT  coc.Salesmancode,coc.customercode,sed.routestartdate FROM invoiceheader coc
INNER JOIN startendday sed ON coc.routecode = sed.routecode AND coc.routekey = sed.routekey
WHERE  (MONTH(sed.routestartdate) = route_month AND YEAR(sed.routestartdate) = varYear)
UNION
SELECT  coc.Salesmancode,customercode,sed.routestartdate FROM salesorderheader coc
INNER JOIN startendday sed ON coc.routecode = sed.routecode AND coc.routekey = sed.routekey
WHERE  (MONTH(sed.routestartdate) = route_month AND YEAR(sed.routestartdate) = varYear)
UNION
SELECT  coc.Salesmancode,customercode,sed.routestartdate FROM arheader coc
INNER JOIN startendday sed ON coc.routecode = sed.routecode AND coc.routekey = sed.routekey
WHERE  (MONTH(sed.routestartdate) = route_month AND YEAR(sed.routestartdate) = varYear))t  GROUP BY salesmancode
) u
ON t.salesmancode=u.salesmancode
SET t.productivecalls=u.productivecalls;
UPDATE TTS_STRIKE_YTD t INNER JOIN (	 
SELECT salesmancode,(((actualcalls)/plannedcalls)*100) AS strikerate FROM  TTS_STRIKE_YTD
 ) u
ON t.salesmancode=u.salesmancode
SET t.strikerate=u.strikerate;
	 
	 
UPDATE TTS_STRIKE_YTD t INNER JOIN 	 
(SELECT coc.`salesmancode`, 
SUM(TIMESTAMPDIFF(MINUTE,
STR_TO_DATE(CONCAT(STR_TO_DATE(visitstartdate,'%Y-%m-%d'),' ',STR_TO_DATE(visitstarttime, '%H:%i')),'%Y-%m-%d %H:%i:%s'), 
STR_TO_DATE(CONCAT(STR_TO_DATE(visitenddate,'%Y-%m-%d'),' ',STR_TO_DATE(visitendtime, '%H:%i')),'%Y-%m-%d %H:%i:%s')
)) CFTMin
FROM customeroperationscontrol coc INNER JOIN startendday sed ON sed.routekey=coc.routekey
WHERE (MONTH(sed.routestartdate) = route_month AND YEAR(sed.routestartdate) = varYear) 
GROUP BY  coc.salesmancode) 
u
ON t.salesmancode=u.salesmancode
SET t.CFTMin=u.CFTMin;
	 
UPDATE TTS_STRIKE_YTD t
SET t.CustomerFaceTime=TIME_FORMAT(SEC_TO_TIME(t.CFTMin*60),'%H:%i');
  
UPDATE TTS_STRIKE_YTD t INNER JOIN 	 
(SELECT sm.`salesmancode`, COUNT(customercode) OTPUsedCount
FROM otplogdetail otp  
INNER JOIN routemaster rm ON rm.routecode=otp.routecode
INNER JOIN salesman sm ON sm.salesmancode=rm.salesmancode
WHERE (MONTH(otpdate) = route_month AND YEAR(otp.otpdate) = varYear) 
GROUP BY  sm.salesmancode) 
u
ON t.salesmancode=u.salesmancode
SET t.OTPUsedCount=u.OTPUsedCount;
 
 
UPDATE TTS_STRIKE_YTD t INNER JOIN (
SELECT salesmancode,DATEDIFF(RouteEndDate,routestartdate) AS settlementskipeddays FROM startendday
WHERE DATEDIFF(RouteEndDate,routestartdate)>0  AND (MONTH(routestartdate) = route_month AND YEAR(routestartdate) = varYear) 
 ) u
ON t.salesmancode=u.salesmancode
SET t.settlementskipeddays=u.settlementskipeddays;
UPDATE TTS_STRIKE_YTD t INNER JOIN (
SELECT salesmancode,((productivecalls)/(actualcalls)*100) AS productiverate FROM  TTS_STRIKE_YTD 
)u
ON t.salesmancode=u.salesmancode
SET t.productiverate=u.productiverate;
SELECT * FROM TTS_STRIKE_YTD;
END */$$
DELIMITER ;

/* Procedure structure for procedure `tts_adjust_visit` */

/*!50003 DROP PROCEDURE IF EXISTS  `tts_adjust_visit` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `tts_adjust_visit`()
BEGIN
	declare rundate date;
	set rundate = curdate();
	INSERT INTO routesequencecustomerstatus
		SELECT DISTINCT c.routekey, 
		(SELECT rp32weeknumber  FROM salescalender s WHERE rundate BETWEEN weekstartdate AND weekenddate ) weekno,
		( CASE WHEN DAYNAME(rundate) = 'Monday' THEN  1 
		WHEN DAYNAME(rundate) = 'Tuesday' THEN  2 
		WHEN DAYNAME(rundate) = 'Wednesday' THEN  3
		WHEN DAYNAME(rundate) = 'Thursday' THEN  4
		WHEN DAYNAME(rundate) = 'Friday' THEN  5
		WHEN DAYNAME(rundate) = 'Saturday' THEN  6 
		WHEN DAYNAME(rundate) = 'Sunday' THEN  7 END ) seqweekday,
		s.routecode , c.customercode , 0 AS sequencenumber, 
		(
			SELECT COUNT(*)
			FROM startendday s  INNER JOIN salescalender s2 ON s.routestartdate BETWEEN weekstartdate AND weekenddate 
			INNER JOIN routesequence r ON r.rp32weeknumber = s2.rp32weeknumber AND salesyear = 2025 AND s.routecode = r.routecode AND 
			CASE WHEN DAYNAME(rundate) = 'Monday' THEN  callrestrictiondays1 
			WHEN DAYNAME(rundate) = 'Tuesday' THEN  callrestrictiondays2 
			WHEN DAYNAME(rundate) = 'Wednesday' THEN  callrestrictiondays3
			WHEN DAYNAME(rundate) = 'Thursday' THEN  callrestrictiondays4
			WHEN DAYNAME(rundate) = 'Friday' THEN  callrestrictiondays5
			WHEN DAYNAME(rundate) = 'Saturday' THEN  callrestrictiondays6 
			WHEN DAYNAME(rundate) = 'Sunday' THEN  callrestrictiondays7 END = 1 
			WHERE s.routestartdate = rundate AND s.routecode = c.routecode  AND r.customercode = c.customercode
		) scheduled, 1 serviced, 0 scanned
		FROM customeroperationscontrol c 
		INNER JOIN startendday s ON c.routekey = s.routekey 
		WHERE s.routestartdate = rundate AND s.routecode NOT LIKE '9%' AND s.routecode <> 0
		AND (c.routekey, s.routecode , c.customercode  ) NOT IN 
		(SELECT routekey, routecode, customercode  FROM routesequencecustomerstatus r);
		UPDATE 		
		routesequencecustomerstatus c
		INNER JOIN 
		(
		SELECT routecode, routekey, customercode,  servicedflag, visitcount FROM (
		SELECT r.*, s.routeclosed,
		(SELECT COUNT(totaltransactions) FROM customeroperationscontrol c WHERE c.routecode = r.routecode AND c.customercode = r.customercode AND c.routekey  = r.routekey  ) visitcount 
		FROM routesequencecustomerstatus r  INNER JOIN startendday s ON r.routekey = s.routekey 
		WHERE s.routestartdate = rundate
		) a WHERE visitcount >0 AND servicedflag = 0
		) b 
		 ON c.routekey = b.routekey AND c.customercode = b.customercode
		 SET c.servicedflag = 1;
 
 
 INSERT INTO customervisitlog
		SELECT routekey, logkey, routecode,
		    salesmancode,
		    customercode,
		    logstartdate,
		    logstarttime,
		    logenddate,
		    logendtime,
		    mdate FROM(
		SELECT 
		    routekey,
		    routecode,
		    salesmancode,
		    customercode,
		    logstartdate,
		    logstarttime,
		    logenddate,
		    logendtime,
		    mdate,
		    (@logkey := IF(@prev_routekey = routekey, @logkey + 1, 
				   IFNULL((SELECT MAX(logkey) 
					   FROM customervisitlog 
					   WHERE routekey = t.routekey), 0) + 1)
		    ) AS logkey,
		    (@prev_routekey := routekey) AS debug_route -- for debugging only
		FROM (
		    SELECT 
			c.routekey, 
			s.routecode,
			c.salesmancode, 
			c.customercode, 
			visitstartdate AS logstartdate, 
			visitstarttime AS logstarttime, 
			visitenddate AS logenddate, 
			visitendtime AS logendtime, 
			CURDATE() AS mdate 
		    FROM customeroperationscontrol c 
		    INNER JOIN startendday s ON s.routekey = c.routekey 
		    WHERE s.routestartdate = rundate
		      AND (c.routekey, c.customercode) NOT IN (
			SELECT routekey, customercode FROM customervisitlog
		      ) 
		      AND s.routecode NOT LIKE '9%' 
		    ORDER BY c.routekey, c.customercode
		) t,
		(SELECT @logkey := 0, @prev_routekey := '') vars
		) a;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `tts_get_cust_visit_log` */

/*!50003 DROP PROCEDURE IF EXISTS  `tts_get_cust_visit_log` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `tts_get_cust_visit_log`( 
