	 where 1=1 ", in_where);
	
	-- SET @dyn_sql1 = CONCAT("  SELECT l.routecode, l.salesmancode, s.salesmanname1 , l.customercode, c.customername, logstartdate, logstarttime, logenddate, logendtime , 
	-- TIMEDIFF(logendtime, logstarttime) duration
