	-- LEFT JOIN CUSTOMERVISITLOG l ON l.routekey = coc.routekey AND l.customercode = coc.customercode 
	-- 	AND TIME_FORMAT(coc.visitstarttime,'%H:%i') >= TIME_FORMAT(l.logstarttime,'%H:%i') 
	--	AND TIME_FORMAT(coc.visitendtime,'%H:%i') <= TIME_FORMAT(l.logendtime ,'%H:%i') 
	-- INNER JOIN customermaster c ON l.customercode = c.customercode
