	-- WHERE 1=1 ", in_where);
	
	PREPARE s1 FROM @dyn_sql1;
	
	EXECUTE s1;	
		
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `tts_get_day_load` */

/*!50003 DROP PROCEDURE IF EXISTS  `tts_get_day_load` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `tts_get_day_load`(
	IN route_id INT
	)
BEGIN
	SELECT DISTINCT ddate, loadperiodnumber, count(*) itemcount FROM startingloaddetail s WHERE  s.ddate  = CURDATE() AND s.routecode = route_id AND STATUS =0
	group by ddate, loadperiodnumber;
	
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `TTS_GET_STRIKERATE_PRODUCTIVITY` */

/*!50003 DROP PROCEDURE IF EXISTS  `TTS_GET_STRIKERATE_PRODUCTIVITY` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `TTS_GET_STRIKERATE_PRODUCTIVITY`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit VARCHAR(25),
IN in_page VARCHAR(25))
BEGIN
	  
	SET @dyn_sql5 = CONCAT
	(
	"SELECT 
  salesmanname1, 
  ARBsalesmanname1, 
  SALESMANCODE, 
  ROUTENAME, 
  ARBROUTENAME, 
  ROUTECODE, 
  PLANNEDCALLS, 
  ACTUALCALLS, 
  SHCEDULECALL, 
  CASHSALE, 
  CREDITSALE, 
  PRODUCTIVECALLS, 
  TOTRCPT, 
  (actualcalls / plannedcalls)* 100 STRIKERATE, 
  (productivecalls / plannedcalls)* 100 PRODUCTIVERATE, 
  TIMESPEND AS CUSTOMERFACETIME 
from 
  (
    SELECT 
      (
        SELECT 
          salesmanname1 
        FROM 
          SALESMAN S 
        WHERE 
          S.SALESMANCODE = A.SALESMANCODE
      ) salesmanname1, 
      (
        SELECT 
          ARBsalesmanname1 
        FROM 
          SALESMAN S 
        WHERE 
          S.SALESMANCODE = A.SALESMANCODE
      ) ARBsalesmanname1, 
      (
        SELECT 
          ALTERNATESALESMANCODE 
        FROM 
          SALESMAN S 
        WHERE 
          S.SALESMANCODE = A.SALESMANCODE
      ) SALESMANCODE, 
      (
        SELECT 
          S.routename 
        FROM 
          ROUTEMASTER S 
        WHERE 
          S.SALESMANCODE = A.SALESMANCODE
      ) ROUTENAME, 
      (
        SELECT 
          S.arbroutename 
        FROM 
          ROUTEMASTER S 
        WHERE 
          S.SALESMANCODE = A.SALESMANCODE
      ) ARBROUTENAME, 
      (
        SELECT 
          S.alternateroutecode 
        FROM 
          ROUTEMASTER S 
        WHERE 
          S.SALESMANCODE = A.SALESMANCODE
      ) ROUTECODE, 
      SUM(CASE WHEN type = 'SCHLD' then cnt end) PLANNEDCALLS, 
      SUM(CASE WHEN type = 'SRVCD' then cnt end) ACTUALCALLS, 
      SUM(
        CASE WHEN type = 'UNSHLD' then cnt end
      ) SHCEDULECALL, 
      SUM(
        CASE WHEN type = 'CSHSALE' then cnt end
      ) CASHSALE, 
      SUM(
        CASE WHEN type = 'CRDSALE' then cnt end
      ) CREDITSALE, 
      SUM(
        CASE WHEN type = 'PRDCALL' then cnt end
      ) PRODUCTIVECALLS, 
      SUM(
        CASE WHEN type = 'TOTRCPT' then cnt end
      ) TOTRCPT, 
      SUM(
        CASE WHEN type = 'TIMESPEND' then cnt end
      ) TIMESPEND 
    from 
      (
        SELECT 
          'SCHLD' type, 
          s.salesmancode, 
          COUNT(*) cnt 
        FROM 
          routesequencecustomerstatus C 
          INNER JOIN STARTENDDAY S ON C.ROUTEKEY = S.ROUTEKEY 
         ",in_where," AND schelduledflag = 1 
        GROUP BY 
          C.ROUTECODE 
        union 
        SELECT 
          'SRVCD' type, 
          s.salesmancode, 
          COUNT(*) cnt 
        FROM 
          routesequencecustomerstatus C 
          INNER JOIN STARTENDDAY S ON C.ROUTEKEY = S.ROUTEKEY 
         ",in_where," 
          AND servicedflag = 1 
        GROUP BY 
          C.ROUTECODE 
        UNION 
        SELECT 
          'UNSHLD' type, 
          s.salesmancode, 
          COUNT(*) cnt 
        FROM 
          routesequencecustomerstatus C 
          INNER JOIN STARTENDDAY S ON C.ROUTEKEY = S.ROUTEKEY 
        ",in_where," 
          AND servicedflag = 1 
          AND schelduledflag = 0 
        GROUP BY 
          C.ROUTECODE 
        UNION 
        SELECT 
          'CRDSALE', 
          s.salesmancode, 
          COUNT(*) cnt 
        FROM 
          INVOICEHEADER H 
          INNER JOIN STARTENDDAY S ON H.ROUTEKEY = S.ROUTEKEY 
        ",in_where," 
          AND H.immediatepaid <> 0 
          AND H.voidflag = 0 
        GROUP BY 
          H.ROUTECODE 
        UNION 
        SELECT 
          'CSHSALE', 
          s.salesmancode, 
          COUNT(*) cnt 
        FROM 
          INVOICEHEADER H 
          INNER JOIN STARTENDDAY S ON H.ROUTEKEY = S.ROUTEKEY 
        ",in_where," 
          AND H.immediatepaid = 0 
          AND H.voidflag = 0 
        GROUP BY 
          H.ROUTECODE 
        UNION 
        SELECT 
          'TOTRCPT', 
          s.salesmancode, 
          count(*) cnt 
        FROM 
          ARHEADER H 
          INNER JOIN STARTENDDAY S ON H.ROUTEKEY = S.ROUTEKEY 
        ",in_where,"  
          AND H.voidflag = 0 
        GROUP BY 
          H.ROUTECODE 
        UNION 
        SELECT 
          'PRDCALL', 
          s.salesmancode, 
          COUNT(*) cnt 
        FROM 
          customeroperationscontrol C 
          INNER JOIN STARTENDDAY S ON C.routekey = S.ROUTEKEY 
        ",in_where," 
          AND C.totaltransactions > 0 
        GROUP BY 
          C.ROUTECODE 
        UNION 
        SELECT 
          'TIMESPEND', 
          S.SALESMANCODE, 
          SUM(
            TIMESTAMPDIFF(
              MINUTE, 
              STR_TO_DATE(
                CONCAT(
                  STR_TO_DATE(visitstartdate, '%Y-%m-%d'), 
                  ' ', 
                  STR_TO_DATE(visitstarttime, '%H:%i')
                ), 
                '%Y-%m-%d %H:%i:%s'
              ), 
              STR_TO_DATE(
                CONCAT(
                  STR_TO_DATE(visitenddate, '%Y-%m-%d'), 
                  ' ', 
                  STR_TO_DATE(visitendtime, '%H:%i')
                ), 
                '%Y-%m-%d %H:%i:%s'
              )
            )
          ) CNT 
        FROM 
          customeroperationscontrol c 
          INNER JOIN startendday s ON C.routekey = S.ROUTEKEY 
        ",in_where," 
        GROUP BY 
          SALESMANCODE
      ) a 
    group by 
      salesmancode
  ) B 
ORDER BY 
  SALESMANCODE	 "
	);
	PREPARE s5 FROM @dyn_sql5;
	EXECUTE s5;
	  
END */$$
DELIMITER ;

/* Procedure structure for procedure `tts_proc_update_jp` */

/*!50003 DROP PROCEDURE IF EXISTS  `tts_proc_update_jp` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `tts_proc_update_jp`()
BEGIN
	DELETE FROM tts_merch_journey_plan WHERE JP_DATE = CURDATE() ;
	INSERT INTO tts_merch_journey_plan(jp_date,jp_routecode,jp_agentcode,jp_cust_code,jp_planned_yn,jp_serviced_yn)	
	SELECT CURDATE(), SEQ.routecode,tmrm.merch_code,seq.customercode, 1,0 
	FROM routesequence seq 		
	INNER JOIN tts_merch_route_master tmrm ON tmrm.ROUTE_CODE =SEQ.routecode 
	AND  CASE WHEN DAYNAME(CURDATE()) = 'Monday' THEN callrestrictiondays1
		WHEN DAYNAME(CURDATE()) = 'Tuesday' THEN callrestrictiondays2
		WHEN DAYNAME(CURDATE()) = 'Wednesday' THEN callrestrictiondays3
		WHEN DAYNAME(CURDATE()) = 'Thursday' THEN callrestrictiondays4
		WHEN DAYNAME(CURDATE()) = 'Friday' THEN callrestrictiondays5
		WHEN DAYNAME(CURDATE()) = 'Saturday' THEN callrestrictiondays6
		WHEN DAYNAME(CURDATE()) = 'Sunday' THEN callrestrictiondays7
		END = 1
	INNER JOIN salescalender cal ON CURDATE() BETWEEN weekstartdate AND weekenddate AND cal.rp32weeknumber = seq.rp32weeknumber; 	
END */$$
DELIMITER ;

/* Procedure structure for procedure `tts_proc_update_jp_visit` */

/*!50003 DROP PROCEDURE IF EXISTS  `tts_proc_update_jp_visit` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `tts_proc_update_jp_visit`(
IN var_routecode INT, var_routedate BIGINT, var_routekey BIGINT, var_agentcode INT
)
BEGIN
	DECLARE done INT DEFAULT 0;
	DECLARE vcount INT DEFAULT 0;
	DECLARE var_custcode BIGINT DEFAULT 0;
	DECLARE cur CURSOR FOR SELECT DISTINCT customercode FROM tts_merch_cust_visit WHERE txndate = DATE(var_routedate) AND routecode = var_routecode;
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;
	OPEN cur;
	label: LOOP
	FETCH cur INTO var_custcode;
	
		SELECT COUNT(*) INTO vcount FROM tts_merch_journey_plan WHERE jp_date = var_routedate AND jp_routecode= var_routecode AND jp_cust_code = var_custcode;
		IF vcount = 0 THEN 
			INSERT INTO tts_merch_journey_plan
			(jp_date,jp_routecode,jp_routekey,jp_cust_code,jp_planned_yn,jp_serviced_yn, jp_agentcode)
			VALUES( var_routedate, var_routecode, var_routekey, var_custcode, 0,1, var_agentcode )
			; 
		ELSE
			UPDATE tts_merch_journey_plan SET jp_serviced_yn = 1 , jp_routekey = var_routekey
			WHERE jp_routecode = var_routecode AND jp_date = var_routedate AND jp_cust_code = var_custcode;
		END IF;	 
	IF done = 1 THEN LEAVE label;
	END IF;
	END LOOP;
	CLOSE cur;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `tts_proc_update_mtd_report` */

/*!50003 DROP PROCEDURE IF EXISTS  `tts_proc_update_mtd_report` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `tts_proc_update_mtd_report`(		 
)
BEGIN
  -- TRUNCATE TABLE tts_mtd_monthly;
  delete from tts_mtd_monthly where routeenddate = DATE_SUB(CURDATE(), INTERVAL 1 DAY);
  INSERT INTO tts_mtd_monthly
  SELECT t1.* FROM (
	SELECT 
		"INVOICE" `type`,sed.routeenddate routeenddate, ih.routekey, ih.visitkey, ih.invoicenumber,
						ih.actualtransactiondate transactiondate, 
						ih.totalinvoiceamount AS transactiontime,
						ih.salesmancode invoicedby, " " againstinv, 
						ih.actualtransactiondate saleinvoiceddate,
						cm.alternatecode AS customercode, cm.reportcustcode, customeraddress1 AS customername, ih.routecode, rm.routename, ih.salesmancode, sm.salesmanname1, ccd.typecode,
						CASE WHEN ccd.typecode = 0 THEN "CASH" ELSE "CHEQUE" END paytype,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE ccd.checknumber END checknumber,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE ccd.checkdate END checkdate,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE ccd.bankcode END bankcode,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE bm.bankname END bankname,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE bm.arbbankname END arbbankname,
						ccd.amount,
						CASE WHEN ccd.typecode = 0 THEN ccd.amount ELSE 0 END cashamt,
						CASE WHEN ccd.typecode = 1 THEN ccd.amount ELSE 0 END checkamt,
						cm.arbcustomername,rm.arbroutename,sm.arbsalesmanname1, cm.alternatecode,ih.comments,rm.divisioncode
					FROM
						startendday sed
						INNER JOIN invoiceheader ih ON ih.routekey = sed.routekey AND ih.voidflag = 0
						INNER JOIN cashcheckdetail ccd ON ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey AND CCD.AMOUNT <> 0 
						INNER JOIN customermaster cm ON cm.customercode = ih.customercode
						INNER JOIN routemaster rm ON rm.routecode = ih.routecode
						INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
						LEFT JOIN bankmaster bm ON bm.bankcode = ccd.bankcode
					WHERE 1=1 AND routeenddate = DATE_SUB(CURDATE(), INTERVAL 1 DAY)
					UNION
					SELECT
						"AR" `type`, sed.routeenddate routeenddate, arh.routekey, arh.visitkey, arh.invoicenumber, 
						arh.transactiondate transactiondate, ard.totalinvoiceamount AS  transactiontime,
						(SELECT ih1.salesmancode FROM invoiceheader ih1 WHERE ih1.invoicenumber = ard.invoicenumber)  invoicedby,
						ard.alternateinvoicenumber againstinv,ard.invoicedate saleinvoiceddate,
						cm.alternatecode AS  customercode, cm.reportcustcode, customeraddress1 AS customername,
						arh.routecode, rm.routename, arh.salesmancode, sm.salesmanname1, ccd.typecode,
						CASE WHEN ccd.typecode = 0 THEN "CASH" ELSE "CHEQUE" END paytype,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE ccd.checknumber END checknumber,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE ccd.checkdate END checkdate,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE ccd.bankcode END bankcode,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE bm.bankname END bankname,
						CASE WHEN ccd.typecode = 0 THEN " " ELSE bm.arbbankname END arbbankname,
						ard.amountpaid AS amount,
						CASE WHEN ccd.typecode = 0 THEN ard.amountpaid  ELSE 0 END cashamt,
						CASE WHEN ccd.typecode = 1 THEN ard.amountpaid  ELSE 0 END checkamt,
						cm.arbcustomername,rm.arbroutename,sm.arbsalesmanname1, cm.alternatecode,arh.comments,rm.divisioncode
					FROM
						startendday sed
						INNER JOIN arheader arh ON arh.routekey = sed.routekey AND arh.voidflag = 0
						INNER JOIN ardetail ard ON ard.routekey = arh.routekey AND ard.visitkey = arh.visitkey
						INNER JOIN cashcheckdetail ccd ON ccd.routekey = arh.routekey AND ccd.visitkey = arh.visitkey AND CCD.AMOUNT <> 0 
						INNER JOIN customermaster cm ON cm.customercode = arh.customercode
						INNER JOIN routemaster rm ON rm.routecode = arh.routecode
						INNER JOIN salesman sm ON sm.salesmancode = arh.salesmancode
						LEFT JOIN bankmaster bm ON bm.bankcode = ccd.bankcode
					WHERE
						1=1 AND routeenddate = DATE_SUB(CURDATE(), INTERVAL 1 DAY)
					UNION
					SELECT
						"ADVANCE PAYMENT" `type`, sed.routeenddate routeenddate, arh.routekey, arh.visitkey, arh.invoicenumber,  
						arh.transactiondate transactiondate, arh.totalinvoiceamount AS transactiontime,
						"" invoicedby, "" againstinv, "" saleinvoiceddate,
						cm.alternatecode AS customercode, cm.reportcustcode, customeraddress1 AS customername,
						arh.routecode, rm.routename, arh.salesmancode, sm.salesmanname1, ccd.typecode,
						CASE WHEN ccd.typecode = 0 THEN "CASH" ELSE "CHEQUE" END paytype,
						CASE WHEN ccd.typecode = 0 THEN "" ELSE ccd.checknumber END checknumber,
						CASE WHEN ccd.typecode = 0 THEN "" ELSE  ccd.checkdate END checkdate,
						CASE WHEN ccd.typecode = 0 THEN "" ELSE ccd.bankcode END bankcode,
						CASE WHEN ccd.typecode = 0 THEN "" ELSE bm.bankname END bankname,
						CASE WHEN ccd.typecode = 0 THEN "" ELSE bm.arbbankname END arbbankname,
						arh.amountpaid amount,
						CASE WHEN ccd.typecode = 0 THEN arh.amountpaid ELSE 0 END cashamt,
						CASE WHEN ccd.typecode = 1 THEN arh.amountpaid ELSE 0 END checkamt,
						cm.arbcustomername,rm.arbroutename,sm.arbsalesmanname1, cm.alternatecode,arh.comments,rm.divisioncode
					FROM
						startendday sed
						INNER JOIN arheader arh ON arh.routekey = sed.routekey AND arh.voidflag = 0
						INNER JOIN cashcheckdetail ccd ON ccd.routekey = arh.routekey AND ccd.visitkey = arh.visitkey AND CCD.AMOUNT <> 0 
						INNER JOIN customermaster cm ON cm.customercode = arh.customercode
						INNER JOIN routemaster rm ON rm.routecode = arh.routecode
						INNER JOIN salesman sm ON sm.salesmancode = arh.salesmancode
						LEFT JOIN bankmaster bm ON bm.bankcode = ccd.bankcode
					WHERE
					         
						1=1 AND advancepaymentflag=1 AND routeenddate = DATE_SUB(CURDATE(), INTERVAL 1 DAY)
				) AS t1;
END */$$
DELIMITER ;

/* Procedure structure for procedure `tts_sp_update_oprn_cntl_daily` */

/*!50003 DROP PROCEDURE IF EXISTS  `tts_sp_update_oprn_cntl_daily` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `tts_sp_update_oprn_cntl_daily`()
BEGIN
	delete from akg_cust_oprn_contl where visitstartdate = curdate();
	INSERT INTO akg_cust_oprn_contl(primary_id,visitkey,routekey,customercode,routecode,salesmancode,odometerreading,visitstartdate,visitstarttime,visitenddate,
		visitendtime,totaltransactions,addedcustomer,voidflag,scannerindicator,reasoncode,latitude,longitude,radius,sapseq)
	SELECT c.* FROM customeroperationscontrol c INNER JOIN startendday s ON c.`routekey`= s.`routekey` 
	WHERE s.`routestartdate` = CURDATE();
	
	UPDATE akg_cust_oprn_contl a
	INNER JOIN invoiceheader i ON a.routekey = i.routekey AND a.visitkey = i.visitkey
	SET a.trantype = 'SALES', txnamoount= i.totalinvoiceamount, paidamount = i.amountpaid, docno = i.documentnumber
	WHERE a.visitstartdate = CURDATE();
	UPDATE akg_cust_oprn_contl a
	INNER JOIN salesorderheader i ON a.routekey = i.routekey AND a.visitkey = i.visitkey
	SET a.trantype = 'ORDER', txnamoount= i.totalinvoiceamount, docno = i.documentnumber
	WHERE a.visitstartdate = CURDATE();
	
	UPDATE akg_cust_oprn_contl a
	INNER JOIN arheader i ON a.routekey = i.routekey AND a.visitkey = i.visitkey
	SET a.trantype = 'RECEIPT', txnamoount= i.totalinvoiceamount, rcptamount = i.amountpaid, docno = i.documentnumber
	WHERE a.visitstartdate = CURDATE();
	-- UPDATE akg_cust_oprn_contl a SET 
	-- docno = (SELECT documentnumber FROM akg_ar_2025 b WHERE b.routekey= a.routekey AND b.visitkey= a.visitkey LIMIT 1),
	-- trantype = (SELECT 'RECEIPT' FROM akg_ar_2025 b WHERE b.routekey= a.routekey AND b.visitkey= a.visitkey LIMIT 1),
	-- rcptamount = (SELECT amountpaid FROM akg_ar_2025 b WHERE b.routekey= a.routekey AND b.visitkey= a.visitkey LIMIT 1),
	-- txnamoount = (SELECT totalinvoiceamount FROM akg_ar_2025 b WHERE b.routekey= a.routekey AND b.visitkey= a.visitkey LIMIT 1)
	-- WHERE a.visitstartdate =  = (DATE_SUB(CURDATE(), INTERVAL 1 DAY)) AND docno IS NULL AND trantype IS NULL;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `update_data_posting` */

/*!50003 DROP PROCEDURE IF EXISTS  `update_data_posting` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `update_data_posting`(
        IN var_routecode BIGINT(20)
    )
BEGIN
	SELECT COALESCE(MAX(routekey),0), salesmancode INTO @routekey, @salesman FROM startendday WHERE routecode = var_routecode;
	
	IF @routekey > 0 THEN
		
		DELETE ird
		FROM invoicerxddetail ird 
		LEFT JOIN invoicedetail id ON id.transactionkey = ird.transactionkey AND id.itemcode = ird.itemcode AND ird.itemtransactiontype = 3
		WHERE  id.manualfreeqty = 0 AND id.routekey = @routekey;				
		
		UPDATE customeroperationscontrol coc, invoiceheader ih
		SET coc.customercode = ih.customercode
		WHERE coc.routekey = ih.routekey AND coc.visitkey = ih.visitkey AND coc.customercode <> ih.customercode AND
			coc.routekey = @routekey;		
		
		UPDATE customeroperationscontrol coc, arheader ih
		SET coc.customercode = ih.customercode
		WHERE coc.routekey = ih.routekey AND coc.visitkey = ih.visitkey AND coc.customercode <> ih.customercode AND
			coc.routekey = @routekey;
	END IF;
	
	
	
	
		
	
				
    END */$$
DELIMITER ;

/* Procedure structure for procedure `ws_sp_exportarheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `ws_sp_exportarheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `ws_sp_exportarheader`()
BEGIN
DROP TEMPORARY TABLE IF EXISTS TempInvoiceNumber;
CREATE TEMPORARY TABLE TempInvoiceNumber AS 
SELECT DISTINCT ah.invoicenumber,ah.transactiondate FROM Arheader ah INNER JOIN ardetail ad ON ah.transactionkey=ad.transactionkey
WHERE IFNULL(posted,0) =0;
SELECT  CONCAT('SC',rem.alternatecode,drs.InvoicePrefix,DATE_FORMAT(NOW(), '%d')) AS  batch,cm.alternatecode AS accountno,CONCAT(drs.InvoicePrefix,ah.invoicenumber) AS item,
'/001' AS val,DATE_FORMAT(ah.transactiondate,'%Y-%m-%d') AS dated,cm.Alpha,ah.amountpaid,0 AS unall_amount,sm.alternatesalesmancode AS analysis_codes1,
cm.Transaction_Anals3 AS analysis_codes3,DATE_FORMAT(ah.transactiondate,'%Y-%m-%d')transactiondate,MONTH(ah.transactiondate)AS Period,YEAR(ah.transactiondate)AS slyear,
(SELECT GROUP_CONCAT(alternateinvoicenumber) AS invoicenumbers
FROM ardetail  WHERE transactionkey=ah.transactionkey)invoicenumbers,(SELECT GROUP_CONCAT(amountpaid) AS amountpaids
FROM ardetail  WHERE transactionkey=ah.transactionkey)amountpaids,(SELECT GROUP_CONCAT('u') AS site_list
FROM ardetail  WHERE transactionkey=ah.transactionkey) AS us,cm.control,ah.invoicenumber
FROM arheader ah 
 INNER JOIN customermaster cm ON cm.customercode=ah.customercode
INNER JOIN Division_Route_Setting drs ON drs.Division=cm.DivisionCode
INNER JOIN routemaster rm ON rm.routecode=ah.routecode
INNER JOIN regionmaster rem ON rem.regionmstcode=rm.regionmstcode
INNER JOIN salesman sm ON sm.salesmancode=rm.salesmancode 
INNER JOIN  TempInvoiceNumber t ON t.invoicenumber=ah.invoicenumber ;
 
END */$$
DELIMITER ;

/* Procedure structure for procedure `ws_sp_exportsalesorderdetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `ws_sp_exportsalesorderdetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `ws_sp_exportsalesorderdetail`()
BEGIN
 SET @lineno :=0;
DROP TEMPORARY TABLE IF EXISTS TempInvoiceNumber;
CREATE TEMPORARY TABLE TempInvoiceNumber AS 
SELECT DISTINCT invoicenumber FROM salesorderheader sh INNER JOIN salesorderdetail sd ON sh.transactionkey=sd.transactionkey
WHERE IFNULL(posted,0) =0 AND (sd.salesqty>0 OR sd.manualfreeqty>0);
SET  @country_rank =0;
SELECT  CASE WHEN cm.type=2 THEN LEFT(cm.alternatecode, LENGTH(cm.alternatecode)-2) ELSE cm.alternatecode END AS Customer,CASE WHEN cm.type=2 THEN LEFT(cm.alternatecode, LENGTH(cm.alternatecode)-2) ELSE cm.alternatecode END AS Invoice_customer,
CONCAT(rm.alternateroutecode,'1', RIGHT(soh.invoicenumber,4)) AS  order_no,
CASE WHEN cm.type=2 THEN LEFT(cm.alternatecode, LENGTH(cm.alternatecode)-2) ELSE cm.alternatecode END AS statementcustomer,rm.warehouse ,DATE_FORMAT(soh.transactiondate,'%Y-%m-%d')  AS dateentered,DATE_FORMAT(soh.transactiondate,'%Y-%m-%d') datereceived,
DATE_FORMAT(soh.transactiondate,'%Y-%m-%d') daterequired,cm.Territory,cm.Class,cm.Region,cm.Cust_Disc_Code
,sm.alternatesalesmancode AS Transactionanlys1,cm.Transaction_Anals3,cm.Alpha,cm.chaincode ,  DATE_FORMAT(DATE_ADD(soh.transactiondate,INTERVAL statementdays DAY),'%Y-%m-%d') AS invoiceduedate,
soh.totalpromoamount AS orderdiscount,CASE WHEN LENGTH(customername)>32 THEN SUBSTRING(customername,0,31) ELSE customername END AS customername ,cm.customeraddress1,cm.CustomerAddress2,cm.CustomerAddress3,'' AS CustomerAddress4 ,CASE WHEN LENGTH(comments)>10 THEN SUBSTRING(comments,0,9) ELSE comments END AS comments,CASE WHEN orderdeliverydate='0000-00-00 00:00' THEN soh.transactiondate ELSE orderdeliverydate END  AS deliverydate,soh.invoicenumber
FROM salesorderheader soh INNER JOIN customermaster cm ON cm.customercode=soh.customercode
INNER JOIN Division_Route_Setting drs ON drs.Division=cm.DivisionCode
INNER JOIN routemaster rm ON rm.routecode=soh.routecode
INNER JOIN salesman sm ON sm.salesmancode=rm.salesmancode 
INNER JOIN  TempInvoiceNumber t ON t.invoicenumber=soh.invoicenumber ;
SELECT product,discount_code,warehouse,Pricing_Unit,Unit_Sales,TRUNCATE(list_price,3)list_price,TRUNCATE(Net_price,3)Net_price,
@ordernumber := order_no AS order_no,
order_qty,1 AS LineNo,TRUNCATE(totalamount,3)totalamount,sales_account,cost_of_sales_acc,stock_account,nominal_category,unitoperand,unitfactor,transorderqty,TRUNCATE(translistprice,3)translistprice,TRUNCATE(transprice,3)transprice,pricingunitoperand,pricingunitfactor,TRUNCATE(pricinglistprice,3)pricinglistprice,TRUNCATE(pricingPrice,3)pricingPrice,majorcategorydesciption,submajorcategorydesciption,itemgroupname,itemshortdescription,itemdescription
,primarykey
 FROM 
 
 (SELECT ih.invoicenumber,im.alternatecode AS product ,im.alternatecode AS discount_code,rm.warehouse, CONCAT('CS',LPAD(im.unitspercase,4,'0')) Pricing_Unit, 
CONCAT('CS',LPAD(im.unitspercase,4,'0')) Unit_Sales,
id.salescaseprice AS list_price,id.salescaseprice AS Net_price,
CONCAT(rm.alternateroutecode,'1', RIGHT(ih.invoicenumber,4)) AS  order_no,
(id.salesqty DIV im.unitspercase ) AS order_qty,  
(id.salesqty DIV im.unitspercase )*id.salescaseprice AS totalamount,gm.sales_account,gm.cost_of_sales_acc,gm.stock_account,im.nominal_category,
'*' unitoperand,1 AS unitfactor,(id.salesqty DIV im.unitspercase ) AS transorderqty,id.salescaseprice AS translistprice,id.salescaseprice AS transprice,'*' AS pricingunitoperand,1 AS pricingunitfactor,id.Salescaseprice AS pricinglistprice,id.Salescaseprice AS pricingPrice,
im.majorcategorydesciption,im.submajorcategorydesciption,im.itemgroupname,im.itemshortdescription,im.itemdescription,id.primarykey
FROM salesorderheader ih INNER JOIN salesorderdetail id ON ih.transactionkey=id.transactionkey
INNER JOIN itemmaster im ON im.actualitemcode=id.itemcode
INNER JOIN Division_Route_Setting drs ON drs.Division=im.Division
INNER JOIN routemaster rm ON rm.routecode=ih.routecode
INNER JOIN salesman SM ON SM.salesmancode=rm.salesmancode
LEFT OUTER JOIN  rp_whglmatrix wm ON wm.routecode=rm.warehouse AND wm.itemcode=im.alternatecode
INNER JOIN Customermaster cm ON cm.customercode=ih.customercode
INNER JOIN  rp_glmatrix gm ON gm.cost_of_sales=CONCAT(cm.Transaction_Anals2, wm.stock_account)
WHERE  (id.salesqty DIV im.unitspercase ) >0    AND id.salesqty>0
UNION 
SELECT ih.invoicenumber, im.alternatecode AS product ,im.alternatecode AS discount_code,rm.warehouse, 'EACH' AS Pricing_Unit, 
'EACH' Unit_Sales,
id.salescaseprice AS List_price,id.salescaseprice AS Net_price,
CONCAT(rm.alternateroutecode,'1', RIGHT(ih.invoicenumber,4)) AS  order_no,
((id.salesqty%im.unitspercase) / im.unitspercase) AS order_qty,  
(id.salesqty%im.unitspercase)*id.salesprice AS totalamount,gm.sales_account,gm.cost_of_sales_acc,gm.stock_account,im.nominal_category,
'/' AS unitoperand,im.unitspercase AS unitfactor,id.salesqty%im.unitspercase AS transorderqty,id.salesprice  AS translistprice,id.salesprice  AS transprice,'*' AS pricingunitoperand,1 AS pricingunitfactor,id.salesprice pricinglistprice,id.salesprice AS pricingprice,
im.majorcategorydesciption,im.submajorcategorydesciption,im.itemgroupname,im.itemshortdescription,im.itemdescription,id.primarykey
FROM salesorderheader ih INNER JOIN salesorderdetail id ON ih.transactionkey=id.transactionkey
INNER JOIN itemmaster im ON im.actualitemcode=id.itemcode
INNER JOIN Division_Route_Setting drs ON drs.Division=im.Division
INNER JOIN routemaster rm ON rm.routecode=ih.routecode
INNER JOIN salesman SM ON SM.salesmancode=rm.salesmancode
LEFT OUTER JOIN  rp_whglmatrix wm ON wm.routecode=rm.warehouse AND wm.itemcode=im.alternatecode
INNER JOIN Customermaster cm ON cm.customercode=ih.customercode
INNER JOIN  rp_glmatrix gm ON gm.cost_of_sales=CONCAT(cm.Transaction_Anals2, wm.stock_account)
WHERE  (id.salesqty%im.unitspercase) > 0 AND id.salesqty>0 
UNION
SELECT ih.invoicenumber,im.alternatecode AS product ,im.alternatecode AS discount_code,rm.warehouse, CONCAT('CS',LPAD(im.unitspercase,4,'0')) Pricing_Unit, 
CONCAT('CS',LPAD(im.unitspercase,4,'0')) Unit_Sales,
0 AS list_price,0 AS Net_price,
CONCAT(rm.alternateroutecode,'1', RIGHT(ih.invoicenumber,4)) AS  order_no,
(id.manualfreeqty DIV im.unitspercase ) AS order_qty,  
0 AS totalamount,gm.sales_account,gm.cost_of_sales_acc,gm.stock_account,im.nominal_category,
'*' unitoperand,1 AS unitfactor,(id.manualfreeqty DIV im.unitspercase ) AS transorderqty,0 AS translistprice,0 AS transprice,'*' AS pricingunitoperand,1 AS pricingunitfactor,0 AS pricinglistprice,0 AS pricingPrice,
im.majorcategorydesciption,im.submajorcategorydesciption,im.itemgroupname,im.itemshortdescription,im.itemdescription,id.primarykey
FROM salesorderheader ih INNER JOIN salesorderdetail id ON ih.transactionkey=id.transactionkey
INNER JOIN itemmaster im ON im.actualitemcode=id.itemcode
INNER JOIN Division_Route_Setting drs ON drs.Division=im.Division
INNER JOIN routemaster rm ON rm.routecode=ih.routecode
INNER JOIN salesman SM ON SM.salesmancode=rm.salesmancode
LEFT OUTER JOIN  rp_whglmatrix wm ON wm.routecode=rm.warehouse AND wm.itemcode=im.alternatecode
INNER JOIN Customermaster cm ON cm.customercode=ih.customercode
INNER JOIN  rp_glmatrix gm ON gm.cost_of_sales=CONCAT(cm.Transaction_Anals2, wm.stock_account) 
WHERE  (id.manualfreeqty DIV im.unitspercase ) >0   AND id.manualfreeqty>0
UNION 
SELECT ih.invoicenumber, im.alternatecode AS product ,im.alternatecode AS discount_code,rm.warehouse, 'EACH' AS Pricing_Unit, 
'EACH' Unit_Sales,
0 AS List_price,0 AS Net_price,
CONCAT(rm.alternateroutecode,'1', RIGHT(ih.invoicenumber,4)) AS  order_no,
((id.manualfreeqty%im.unitspercase) / im.unitspercase) AS order_qty,  
 0 AS totalamount,gm.sales_account,gm.cost_of_sales_acc,gm.stock_account,im.nominal_category,
'/' AS unitoperand,im.unitspercase AS unitfactor,id.manualfreeqty%im.unitspercase AS transorderqty,0 AS translistprice,0 AS transprice,'*' AS pricingunitoperand,1 AS pricingunitfactor,0 pricinglistprice,0 AS pricingprice,
im.majorcategorydesciption,im.submajorcategorydesciption,im.itemgroupname,im.itemshortdescription,im.itemdescription,id.primarykey
FROM salesorderheader ih INNER JOIN salesorderdetail id ON ih.transactionkey=id.transactionkey
INNER JOIN itemmaster im ON im.actualitemcode=id.itemcode
INNER JOIN Division_Route_Setting drs ON drs.Division=im.Division
INNER JOIN routemaster rm ON rm.routecode=ih.routecode
INNER JOIN salesman SM ON SM.salesmancode=rm.salesmancode
LEFT OUTER JOIN  rp_whglmatrix wm ON wm.routecode=rm.warehouse AND wm.itemcode=im.alternatecode
INNER JOIN Customermaster cm ON cm.customercode=ih.customercode
INNER JOIN  rp_glmatrix gm ON gm.cost_of_sales=CONCAT(cm.Transaction_Anals2, wm.stock_account) 
WHERE  (id.manualfreeqty%im.unitspercase) > 0 AND id.manualfreeqty>0 
)A 
INNER JOIN  TempInvoiceNumber t ON t.invoicenumber=A.invoicenumber 
ORDER BY order_no,primarykey;
 
 
 
END */$$
DELIMITER ;

/* Procedure structure for procedure `ws_sp_updatearheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `ws_sp_updatearheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `ws_sp_updatearheader`(
                IN var_routeid text
    )
BEGIN
	                                
	SET @dyn_sql = CONCAT("UPDATE arheader 
		SET posted = 1
	WHERE invoicenumber IN (",var_routeid,")");
	PREPARE s1 FROM @dyn_sql; 	
	EXECUTE s1;
select @dyn_sql;
END */$$
DELIMITER ;

