/*View structure for view kpi_averagedropsize */

/*!50001 DROP TABLE IF EXISTS `kpi_averagedropsize` */;
/*!50001 DROP VIEW IF EXISTS `kpi_averagedropsize` */;

/*!50001 CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `kpi_averagedropsize` AS select `sed`.`routestartdate` AS `routestartdate`,`sed`.`routekey` AS `routekey`,`dm`.`depotcode` AS `depotcode`,`dm`.`depotname` AS `depotname`,`am`.`areacode` AS `areacode`,`am`.`areaname` AS `areaname`,`sam`.`subareacode` AS `subareacode`,`sam`.`subareaname` AS `subareaname`,`rm`.`routecode` AS `routecode`,`rm`.`routename` AS `routename`,`sm`.`salesmancode` AS `salesmancode`,`sm`.`salesmanname1` AS `salesmanname1`,(select count(`ih`.`invoicenumber`) AS `COUNT(ih.invoicenumber)` from `invoiceheader` `ih` where ((`ih`.`routekey` = `sed`.`routekey`) and ((`ih`.`totalsalesamount` + `ih`.`totalinvoiceamount`) <> 0))) AS `totalinvoices`,(select sum(cast((`isd`.`salesqty` / `im`.`unitspercase`) as unsigned)) AS `t1` from (`invoicedetail` `isd` join `itemmaster` `im`) where ((`isd`.`routekey` = `sed`.`routekey`) and (`isd`.`itemcode` = `im`.`actualitemcode`))) AS `salesqty`,(select sum(cast(((`isd`.`freesampleqty` + `isd`.`manualfreeqty`) / `im`.`unitspercase`) as unsigned)) AS `t2` from (`invoicedetail` `isd` join `itemmaster` `im`) where ((`isd`.`routekey` = `sed`.`routekey`) and (`isd`.`itemcode` = `im`.`actualitemcode`))) AS `freeqty`,(select sum(cast(((`isd`.`promotionamount` * `isd`.`promotionquantity`) / `im`.`unitspercase`) as unsigned)) AS `t3` from (`promotiondetail` `isd` join `itemmaster` `im`) where ((`isd`.`routekey` = `sed`.`routekey`) and (`isd`.`itemcode` = `im`.`actualitemcode`) and (`isd`.`promotiontypecode` = 7))) AS `promoqty`,(select sum(cast((`isd`.`returnqty` / `im`.`unitspercase`) as unsigned)) AS `t4` from (`invoicedetail` `isd` join `itemmaster` `im`) where ((`isd`.`routekey` = `sed`.`routekey`) and (`isd`.`itemcode` = `im`.`actualitemcode`))) AS `returnqty`,(select sum(cast(((`isd`.`damagedqty` + `isd`.`expiryqty`) / `im`.`unitspercase`) as unsigned)) AS `t5` from (`invoicedetail` `isd` join `itemmaster` `im`) where ((`isd`.`routekey` = `sed`.`routekey`) and (`isd`.`itemcode` = `im`.`actualitemcode`))) AS `damageqty`,(select sum(`ih`.`totalsalesamount`) AS `SUM(ih.totalsalesamount)` from `invoiceheader` `ih` where (`ih`.`routekey` = `sed`.`routekey`)) AS `grossinvoiceamt`,(select sum(`ih`.`totalreturnamount`) AS `SUM(ih.totalreturnamount)` from `invoiceheader` `ih` where (`ih`.`routekey` = `sed`.`routekey`)) AS `returnamt`,(select sum((`ih`.`totaldamagedamount` + `ih`.`totalexpiryamount`)) AS `t6` from `invoiceheader` `ih` where (`ih`.`routekey` = `sed`.`routekey`)) AS `damagedamt`,coalesce((select sum((`pd`.`promotionamount` * `pd`.`promotionquantity`)) AS `t7` from `promotiondetail` `pd` where ((`pd`.`routekey` = `sed`.`routekey`) and (`pd`.`itemtransactiontype` = 1) and (`pd`.`promotiontypecode` in (5,6)))),0) AS `discountamt`,coalesce((select sum((`pd`.`promotionamount` * `pd`.`promotionquantity`)) AS `t8` from `promotiondetail` `pd` where ((`pd`.`routekey` = `sed`.`routekey`) and (`pd`.`itemtransactiontype` = 2) and (`pd`.`promotiontypecode` in (5,6)))),0) AS `discountamtret`,coalesce((select sum((`pd`.`promotionamount` * `pd`.`promotionquantity`)) AS `t9` from `promotiondetail` `pd` where ((`pd`.`routekey` = `sed`.`routekey`) and (`pd`.`itemtransactiontype` = 3) and (`pd`.`promotiontypecode` in (5,6)))),0) AS `discountamtdmg`,(select sum(`ih`.`totalinvoiceamount`) AS `t10` from `invoiceheader` `ih` where (`ih`.`routekey` = `sed`.`routekey`)) AS `netinvoiceamt` from (((((`startendday` `sed` join `routemaster` `rm`) join `salesman` `sm`) join `subareamaster` `sam`) join `areamaster` `am`) join `depotmaster` `dm`) where ((`sed`.`routecode` = `rm`.`routecode`) and (`rm`.`salesmancode` = `sm`.`salesmancode`) and (`rm`.`subareacode` = `sam`.`subareacode`) and (`sam`.`areacode` = `am`.`areacode`) and (`am`.`depotcode` = `dm`.`depotcode`)) */;

/*View structure for view split_depot_string_view */

/*!50001 DROP TABLE IF EXISTS `split_depot_string_view` */;
/*!50001 DROP VIEW IF EXISTS `split_depot_string_view` */;

/*!50001 CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `split_depot_string_view` AS select distinct `dm`.`depotcode` AS `depotcode`,`dm`.`depotname` AS `depotname`,`rm`.`routecode` AS `routecode`,`rm`.`routename` AS `routename` from (((`routemaster` `rm` join `subareamaster` `sam` on((`sam`.`subareacode` = `rm`.`subareacode`))) join `areamaster` `am` on((`am`.`areacode` = `sam`.`areacode`))) join `depotmaster` `dm` on((`dm`.`depotcode` = `am`.`depotcode`))) where (`dm`.`depotcode` = 131) order by `dm`.`depotcode`,`rm`.`routecode` */;

/*View structure for view temp_v_cust_visit_head */

/*!50001 DROP TABLE IF EXISTS `temp_v_cust_visit_head` */;
/*!50001 DROP VIEW IF EXISTS `temp_v_cust_visit_head` */;

/*!50001 CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `temp_v_cust_visit_head` AS select `rm`.`divisioncode` AS `divisioncode`,`sed`.`routekey` AS `routekey`,date_format(`sed`.`routestartdate`,'%m-%d-%Y') AS `transactiondate`,`sed`.`routecode` AS `routecode`,`sed`.`salesmancode` AS `salesmancode`,`rscs`.`customercode` AS `customercode`,`rscs`.`schelduledflag` AS `schelduledflag`,`rscs`.`servicedflag` AS `servicedflag`,`sm`.`salesmanname1` AS `salesmanname1`,`sm`.`arbsalesmanname1` AS `arbsalesmanname1`,`sm`.`alternatesalesmancode` AS `alternatesalesmancode`,`rm`.`routename` AS `routename`,`rm`.`arbroutename` AS `arbroutename`,`rm`.`alternateroutecode` AS `alternateroutecode`,`cm`.`customername` AS `customername`,`cm`.`arbcustomername` AS `arbcustomername`,`cm`.`alternatecode` AS `customeraltcode`,`chm`.`channelname` AS `channelname`,`chm`.`arbchannelname` AS `arbchannelname`,(select min(str_to_date(`cop`.`visitstarttime`,'%H:%i %p')) from `customeroperationscontrol` `cop` where ((`rscs`.`routekey` = `cop`.`routekey`) and (`rscs`.`customercode` = `cop`.`customercode`))) AS `starttime`,(select max(str_to_date(`cop`.`visitendtime`,'%H:%i %p')) from `customeroperationscontrol` `cop` where ((`rscs`.`routekey` = `cop`.`routekey`) and (`rscs`.`customercode` = `cop`.`customercode`))) AS `enddtime` from (((((`startendday` `sed` left join `routesequencecustomerstatus` `rscs` on(((`rscs`.`routekey` = `sed`.`routekey`) and (`rscs`.`routecode` = `sed`.`routecode`)))) join `routemaster` `rm` on((`rm`.`routecode` = `sed`.`routecode`))) join `salesman` `sm` on((`sm`.`salesmancode` = `sed`.`salesmancode`))) join `customermaster` `cm` on((`cm`.`customercode` = `rscs`.`customercode`))) left join `channelmaster` `chm` on((`chm`.`channelcode` = `cm`.`channelcode`))) where ((1 = 1) and (`sed`.`routeenddate` = (curdate() - interval 1 day))) order by `rm`.`divisioncode`,`sed`.`routecode` desc */;

